window.__BOOK__['p06'].push([{"id":"b113-1","bab":"الجزء 11","sec":"بسم الله الرحمن الرحيم أخبار النابغة ونسبه","page":"ج11 ص5","text":"النابغة اسمه زياد بن معاوية بن ضباب بن جناب بن يربوع بن غيظ بن مرة بن عوف بن سعد بن ذبيان بن بغيض بن ريث بن غطفان بن سعد بن قيس ابن عيلان بن مضر ويكنى أبا أمامة وذكر أهل الرواية أنه إنما لقب النابغة لقوله\n(فقد نبغت لهم منا شؤون ... )\nطبقته ومنزلته عند الخلفاء وهو أحد الأشراف الذين غض الشعر منهم وهو من الطبقة الأولى المقدمين على سائر الشعراء أخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر ابن شبة قال حدثنا أبو نعيم قال حدثنا شريك عن مجاهد عن الشعبي عن\nربعي بن حراش قال قال عمر يا معشر غطفان من الذي يقول\n(أتيتك عاريا خلقا ثيابي ... على خوف تظن بي الظنون)\nلنا النابغة قال ذاك أشعر شعرائكم أخبرني أحمد وحبيب قالا حدثنا عمر بن شبة قال حدثنا عبيد بن جناد قال حدثنا معن بن عبد الرحمن عن عيسى بن عبد الرحمن السلمي عن جده عن الشعبي قال قال عمر من أشعر الناس قالوا أنت أعلم يا أمير المؤمنين قال من الذي يقول\n(إلا سليمان إذ قال الإله له ... قم في البرية فاحددها عن الفند)\n(وخبر الجن أني قد أذنت لهم ... يبنون تدمر بالصفاح والعمد)\nالوا النابغة قال فمن الذي يقول\n(أتيتك عاريا خلقا ثيابي ... على خوف تظن بي الظنون)\nالوا النابغة قال فمن الذي يقول\n(حلفت فلم أترك لنفسك ريبة ... وليس وراء الله للمرء مذهب)\n(لئن كنت قد بلغت عني خيانة ... لمبلغك الواشي أغش وأكذب)\n(ولست بمستبق أخا لا تلمه ... على شعث أي الرجال المهذب)\nالوا النابغة قال فهو أشعر العرب أخبرنا أحمد قال حدثنا عمر بن شبة قال حدثنا عبد الصمد بن عبد الوارث قال حدثنا عمر بن أبي زائدة عن الشعبي قال ذكر الشعر عند عمر ثم ذكر مثله أخبرني أحمد قال حدثنا عمر قال حدثني علي بن محمد عن المدائني عن عبد الله بن الحسن عن عمر بن الحباب عن أبي المؤمل قال قام رجل إلى ابن عباس فقال أي الناس أشعر فقال ابن عباس أخبره يا أبا الأسود الدؤلي قال الذي يقول\n(فإنك كالليل الذي هو مدركي ... وإن خلت أن المنتأى عنك واسع)\nخبرني الحسين بن يحيى قال قال حماد قرأت على أبي عن جرير بن شريك بن جرير بن عبد الله البجلي قال كنا عند الجنيد بن عبد الرحمن\nبخراسان وعنده بنو مرة وجلساؤه من الناس فتذاكروا شعر النابغة حتى أنشدوا قوله\n(فإنك كالليل الذي هو مدركي ... وإن خلت أن المنتأى عنك واسع)\nقال شيخ من بني مرة ما الذي رأى في النعمان حيث يقول له هذا وهل كان النعمان إلا على منظرة من مناظر الحيرة وقالت ذلك القيسية فأكثروا فنظر إلي الجنيد وقال يا أبا خالد لا يهولنك قول هؤلاء الأعاريض فأقسم بالله أن لو عاينوا من النعمان ما عاين صاحبهم لقالوا أكثر مما قال ولكنهم قالوا ما تسمع وهم آمنون","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":0,"spl":"بسم الله الرحمن الرحيم أخبار النابغة ونسبه","loc":1977,"partial":1},
{"id":"b113-2","bab":"الجزء 11","sec":"كان الشعراء يحتكمون إليه","page":"ج11 ص8","text":"أخبرني حبيب بن نصر وأحمد بن عبد العزيز قالا حدثنا عمر بن شبة قال حدثنا أبو بكر العليمي قال حدثني عبد الملك بن قريب قال كان يضرب للنابغة قبة من أدم بسوق عكاظ فتأتيه الشعراء فتعرض عليه أشعارها قال وأول من أنشده الأعشى ثم حسان بن ثابت ثم أنشدته الشعراء ثم أنشدته الخنساء بنت عمرو بن الشريد\n(وإن صخرا لتأتم الهداة به ... كأنه علم في رأسه نار)\nقال والله لولا أن أبا بصير أنشدني آنفا لقلت إنك أشعر الجن والإنس فقام حسان فقال والله لأنا أشعر منك ومن أبيك فقال له النابغة يا بن أخي أنت لا تحسن أن تقول\n(فإنك كالليل الذي هو مدركي ... وإن خلت أن المنتأى عنك واسع)\n(خطاطيف حجن في حبال متينة ... تمد بها أيد إليك نوازع)\nال فخنس حسان لقوله أخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال حدثنا الأصمعي قال حدثنا أبو عمرو بن العلاء قال قال فلان لرجل سماه فأنسيته بينا نحن نسير بين أنقاء من الأرض تذاكرنا الشعر فإذا راكب أطيلس يقول أشعر الناس زياد بن معاوية ثم تملس فلم نره أخبرني أحمد قال حدثنا عمر قال حدثنا الأصمعي قال سمعت أبا عمرو\nيقول ما كان ينبغي للنابغة إلا أن يكون زهير أجيرا له أخبرني أحمد قال حدثنا عمر قال عمرو بن المنتشر المرادي وفدنا على عبد الملك بن مروان فدخلنا عليه فقام رجل فاعتذر من أمر وحلف عليه فقال له عبد الملك ما كنت حريا أن تفعل ولا تعتذر ثم أقبل على أهل الشأم فقال أيكم يروي من اعتذار النابغة الى النعمان\n(حلفت فلم أترك لنفسك ريبة ... وليس وراء الله للمرء مذهب)\nلم يجد فيهم من يرويه فأقبل علي فقال أترويه قلت نعم فأنشدته القصيدة كلها فقال هذا أشعر العرب أخبرنا حبيب بن نصر وأحمد بن عبد العزيز قالا حدثنا عمر بن شبة قال قال معاوية بن بكر الباهلي قلت لحماد الراوية بم تقدم النابغة قال باكتفائك بالبيت الواحد من شعره لا بل بنصف بيت لا بل بربع بيت مثل قوله\n(حلفت فلم أترك لنفسك ريبة ... وليس وراء الله للمرء مذهب)\nل نصف يغنيك عن صاحبه وقوله\n(أي الرجال المهذب ... )\nربع بيت يغنيك عن غيره وهذه القصيدة العينية يقولها في النعمان بن المنذر يعتذر اليه بها وبعدة قصائد قالها فيه تذكر في مواضعها ولقد اختلفت الرواة في السبب الذي دعاه الى ذلك","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":1,"spl":"كان الشعراء يحتكمون إليه — خبره مع النعمان وزوجته المتجردة","loc":1978,"partial":1},
{"id":"b113-3","bab":"الجزء 11","sec":"خبره مع النعمان وزوجته المتجردة","page":"ج11 ص10","text":"فأخبرني حييب بن نصر المهلبي وأحمد بن عبد العزيز الجوهري قالا حدثنا عمر بن شبة عن أبي عبيدة وغيره من علمائهم\nان النابغة كان كبيرا عند النعمان خاصا به وكان من ندمائه وأهل أنسه فرأى زوجته المتجردة يوما وغشيها تشبيها بالفجاءة فسقط نصيفها واستترت بيدها وذراعها فكادت ذراعها تستر وجهها لعبالتها وغلظها فقال قصيدته التي أولها\n(أمن آل مية رائح أو مغتدي ... عجلان ذا زاد وغير مزود)\n(زعم البوارح أن رحلتنا غدا ... وبذاك تنعاب الغراب الأسود)\n(لا مرحبا بغد ولا أهلا به ... إن كان تفريق الأحبة في غد)\n(أزف الترحل غير أن ركابنا ... لما تزل برحالنا وكأن قد)\n(في إثر غانية رمتك بسهمها ... فأصاب قلبك غير أن لم تقصد)\n(بالدر والياقوت زين نحرها ... ومفصل من لؤلؤ وزبرجد)\nروضه من الكامل وغناه أبو كامل من رواية حبش ثقيلا أول بالبنصر وغناه الغريض من روايته ثاني ثقيل بالوسطى وغناه ابن سريج من رواية إسحاق ثقيلا أول بالسبابة في مجرى الوسطى\nقوله أمن آل مية يخاطب نفسه كالمستثبت وعجلان من العجلة نصبه على الحال والزاد في هذا الموضع ما كان من تسليم ورد تحية والبوارح ما جاء من ميامنك إلى مياسرك فولاك مياسره والسانح ما جاء من مياسرك فولاك ميامنه حكى ذلك أبو عبيدة عن رؤبة وقد سأله يونس عنه وأهل نجد يتشاءمون بالبوارح وغيرهم من العرب تتشاءم بالسانح وتتيمن بالبارح ومنهم من لا يرى ذلك شيئا قال بعضهم\n(ولقد غدوت وكنت لا ... أغدو على واق وحاتم)\n(فإذا الأشائم كالأيامن ... والأيامن كالأشائم)\nتنعاب الغراب صياحه يقال نعب الغراب ينعب نعيبا ونعبانا والتنعاب تفعال من هذا وكان النابغة قال في هذا البيت\n(وبذاك خبرنا الغراب الأسود ... )\nثم ورد يثرب فسمعه يغنى فيه فبان له الإقواء فغيره في مواضع من شعره","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":1,"spl":"كان الشعراء يحتكمون إليه — خبره مع النعمان وزوجته المتجردة","loc":1979,"partial":1},
{"id":"b113-4","bab":"الجزء 11","sec":"الإقواء عيب في شعره","page":"ج11 ص12","text":"وأخبرنا الحسين بن يحيى قال قال حماد بن إسحاق قرأت على أبي قال أبو عبيدة كان فحلان من الشعراء يقويان النابغة وبشر بن أبي\nخازم فأما النابغة فدخل يثرب فهابوه أن يقولوا له لحنت وأكفأت فدعوا قينة وأمروها أن تغني في شعره ففعلت فلما سمع الغناء وغير مزود والغراب الأسود وبان له ذلك في اللحن فطن لموضع الخطأ فلم يعد وأما بشر بن أبي خازم فقال له أخوه سوادة إنك تقوي قال وما ذاك قال قولك\n(وينسي مثل ما نسيت جذام ... )\nم قلت بعده\n(إلى البلد الشآم ... )\nففطن فلم يعد أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا خلاد الأرقط وغيره من علمائنا قالوا كان النابغة يقول إن في شعري لعاهة ما أقف عليها فلما قدم المدينة غني في شعره فلما سمع قوله\n(واتقتنا باليد ... )\nو\n(يكاد من اللطافة يعقد ... )\nتبين له لما مدت باليد فصارت الكسرة ياء ومدت يعقد فصارت الضمة كالواو ففطن فغيره وجعله\n(عنم على أغصانه لم يعقد ... )\nكان يقول وردت يثرب وفي شعري بعض العاهة فصدرت عنها\nوأنا أشعر الناس وقوله لا مرحبا لا سعة ونصبه ها هنا شبيه بالمصدر كأنه قال لا رحب رحبا ولا أهل أهلا وأزف قرب قال وقال في قصيدته هذه يذكر ما نظر إليه من المتجردة وسترها وجهها بذراعها\n(سقط النصيف ولم ترد إسقاطه ... فتناولته واتقتنا باليد)\n(بمخضب رخص كأن بنانه ... عنم على أغصانه لم يعقد)\n(وبفاحم رجل أثيث نبته ... كالكرم مال على الدعام المسند)\n(نظرت اليك بحاجة لم تقضها ... نظر السقيم إلى وجوه العود)\nناه ابن سريج ولحنه من خفيف الثقيل الأول بالوسطى عن عمرو والنصيف الخمار والجمع أنصفة ونصف والعنم فيما ذكر أبو عبيدة يساريع حمر تكون في البقل في الربيع وقال الأصمعي العنم شجر يحمر وينعم نبته والفاحم الشديد السواد والرجل الذي ليس بجعد والأثيث المتكاثف قال أمرؤ القيس\n(أثيث كقنو النخلة المتعثكل ... )\nيقال شعر رجل ورجل ويروى\n(ورنت إلي بمقلتي مكحولة ... )\nوالمكحولة البقرة وقوله لم تقضها يعني المرأة أي لم تقدر على الكلام من مخافة أهلها فهي كالسقيم الذي ينظر الى من يعوده غناه أبن سريج خفيف ثقيل أول بالوسطى على مذهب إسحاق من رواية عمرو بن بانة","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":2,"spl":"الإقواء عيب في شعره","song":1,"loc":1980,"partial":1},
{"id":"b113-5","bab":"الجزء 11","sec":"اتهم بالتخنث","page":"ج11 ص15","text":"وأخبرنا محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري قال قال الهيثم بن عدي قال لي صالح بن حسان كان والله النابغة مخنثا قلت وما علمك به أرأيته قط قال لا والله قلت أفأخبرت عنه قال لا قلت فما علمك به قال أما سمعت قوله\n(سقط النصيف ولم ترد إسقاطه ... فتناولته واتقتنا باليد)\nا والله ما أحسن هذه الإشارة ولا هذا القول إلا مخنث قال فأنشدها النابغة مرة بن سعد القريعي فأنشدها مرة النعمان فامتلأ غضبا فأوعد النابغة وتهدده فهرب منه فأتى قومه ثم شخص إلى ملوك غسان بالشأم فامتدحهم وقيل إن عصام بن شهبر الجرمي حاجب النعمان أنذره وعرفه ما يريده النعمان وكان صديقه فهرب وعصام الذي يقول\nفيه الراجز\n(نفس عصام سودت عصاما ... وعلمته الكر والإقداما)\n(وجعلته ملكا هماما ... )\nقال من رويت عنه خبر النابغة إن السبب في هربه من النعمان أن عبد القيس بن خفاف التميمي ومرة بن سعد بن قريع السعدي عملا هجاء في النعمان على لسانه وأنشدا النعمان منه أبياتا يقال فيها\n(ملك يلاعب أمه وقطينه ... رخو المفاصل أيره كالمرود)\nومنه\n(قبح الله ثم ثنى بلعن ... وارث الصائغ الجبان الجهولا)\n(من يضر الأدنى ويعجز عن ضر الأقاصي ومن يخون الخليلا ... )\n(يجمع الجيش ذا الألوف ويغزو ... ثم لا يرزأ العدو فتيلا)\nعني بوارث الصائغ النعمان وكان جده لأمه بفدك يقال له عطية وأم النعمان سلمى بنت عطية فأخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن ابن حبيب عن ابن الأعرابي عن المفضل أن مرة بن سعد القريعي الذي وشى\nبالنابغة كان له سيف قاطع يقال له ذو الريقة من كثرة فرنده وجوهره فذكره النابغة للنعمان فأخذه فاضطغن ذلك القريعي حتى وشى به إلى النعمان وحرضه عليه وأخبرنا الحسين بن يحيى عن حماد عن أبيه عن محمد بن سلام عن يونس بن حبيب عن أبي عمرو بن العلاء وأخبرنا إبراهيم بن أيوب عن أبن قتيبة وأخبرنا أحمد بن عبد العزيز عن عمر بن شبة قالوا جميعا إن الذي من أجله هرب النابغة من النعمان أنه كان والمنخل بن عبيد ابن عامر اليشكري جالسين عنده وكان النعمان دميما أبرش قبيح المنظر وكان المنخل بن عبيد من أجمل العرب وكان يرمي بالمتجردة زوجة النعمان ويتحدث العرب أن ابني النعمان منها كانا من المنخل فقال النعمان للنابغة يا أبا أمامة صف المتجردة في شعرك فقال قصيدته التي وصفها فيها ووصف بطنها وروادفها وفرجها فلحقت المنخل من ذلك غيرة فقال للنعمان ما يستطيع أن يقول هذا الشعر إلا من جربه فوقر ذلك في نفس النعمان وبلغ النابغة فخافه فهرب فصار في غسان","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":3,"spl":"اتهم بالتخنث — تشبيبه بهند صاحبة المنخل اليشكري","loc":1981,"partial":1},
{"id":"b113-6","bab":"الجزء 11","sec":"تشبيبه بهند صاحبة المنخل اليشكري","page":"ج11 ص18","text":"قالوا وكان المنخل يهوى هندا بنت عمرو بن هند وفيها يقول\n(ولقد دخلت على الفتاة ... الخدر في اليوم المطير)\n(الكاعب الحسناء ترفل ... في الدمقس وفي الحرير)\n(فدفعتها فتدافعت ... مشي القطاة إلى الغدير)\n(ولثمتها فتنفست ... كتنفس الظبي البهير)\nناه ابراهيم الموصلي من رواية عمرو بن بانة ثاني ثقيل بالوسطى على مذهب إسحاق\n(وبدت وقالت يا منخل ... ما بجسمك من فتور)\n(ما مس جسمي غير حبك ... فاهدئي عني وسيري)\n(ولقد شربت من المدامة ... بالكبير وبالصغير)\n(فإذا سكرت فإنني ... رب الخورنق والسدير)\n(وإذا صحوت فإنني ... رب الشويهة والبعير)\n(يا هند هل من نائل ... يا هند للعاني الأسير)\n(وأحبها وتحبني ... وتحب ناقتها بعيري)\nوقال حماد بن إسحاق عن أبيه في كتاب أغاني ابن مسجح في هذا الصوت لمالك ومعبد وابن سريج وابن محرز والغريض وابن مسجح لكلهم فيه ألحان قال فبلغ عمرا خبر المنخل فأخذه فقتله وقال المنخل قبل أن يقتله وهو محبوس في يده يحض قومه على طلب الثأر به\n(طل وسط العراق قتلي بلا جرم ... وقومي ينتجون السخالا)\nجع الخبر إلى سياقه قالوا جميعا فلما صار النابغة الى غسان نزل بعمرو بن الحارث الأصغر بن الحارث الأعرج بن الحارث الأكبر بن أبي شمر وأم الحارث الأعرج مارية بنت ظالم بن وهب بن الحارث بن معاوية بن ثور بن مرتع الكندية وهي ذات القرطين اللذين يضرب بهما المثل فيقال لما يغلى به الثمن خذه ولو بقرطي مارية وأختها هند الهنود امرأة حجر آكل المرار وإياها عنى حسان بقوله في جبلة بن الأيهم\n(أولاد جفنة حول قبر أبيهم ... قبر ابن مارية الجواد المفضل)","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":3,"spl":"اتهم بالتخنث — تشبيبه بهند صاحبة المنخل اليشكري","song":1,"loc":1982},
{"id":"b113-7","bab":"الجزء 11","sec":"مدحه النعمان وأخاه عمرو بن الحارث","page":"ج11 ص20","text":"ولذلك خبر يأتي في موضعه فمدحه النابغة ومدح أخاه النعمان ولم يزل مقيما مع عمرو حتى مات وملك أخوه النعمان فصار معه الى أن استطلعه النعمان فعاد إليه فمما مدح به عمرا قوله\n(كليني لهم يا أميمة ناصب ... وليل أقاسيه بطيء الكواكب)\n(وصدر أراح الليل عازب همه ... تضاعف فيه الحزن من كل جانب)\n(تقاعس حتى قلت ليس بمنقض ... وليس الذي يهدي النجوم بآئب)\n(علي لعمرو نعمة بعد نعمة ... لوالده ليست بذات عقارب)\nروضه من الطويل غنى في البيتين الأولين ابن محرز خفيف ثقيل أول بالبنصر على مذهب إسحاق من رواية عمرو وغنى فيه الأبجر من رواية حبش ثاني ثقيل بالوسطى وغنى مالك في البيت الرابع ثاني ثقيل بالسبابة في مجرى الوسطى من رواية هارون بن محمد بن عبد الملك الزيات وغنى في الأربعة الأبيات عبد الله بن العباس الربيعي ماخوريا عن حبش وغنى فيها طويس رملا بالوسطى بحكايتين عن حبش هكذا روي قوله يا أميمة مفتوح الهاء قال الخليل من عادة العرب أن تنادي المؤنث بالترخيم فتقول يا أميم ويا عز ويا سلم فلما لم يرخم لحاجته الى الترخيم أجراها على لفظها مرخمة وأتى بها بالفتح وكليني أي دعيني\nووكلته الى كذا أكله وكالة وناصب متعب وبطيء الكواكب أي قد طال حتى إن كواكبه لا تجري ولا تغور أراح رد يقال أراح الرجل إبله أي ردها فيقول رد هذا الليل إلي ما عزب من همي بالنهار لأنه يتعلل نهارا بمحادثة الناس والتشاغل بغير الفكر فإذا خلا بالليل راح اليه همه وتقاعس تأخر وأصل التقاعس الرجوع الى خلف القهقري فشبه الليل في طوله بالمتقاعس والذي يهدي النجوم أولها شبهها بهواديها وقوله\n(ليست بذات عقارب ... )\nأي لا يكدرها ولا يمنها ومما يغنى فيه من هذه القصيدة\n(حلفت يمينا غير ذي مثنوية ... ولا علم إلا حسن ظني بصاحب)\n(لئن كان للقبرين قبر بجلق ... وقبر بصيداء الذي عند حارب)\n(وللحارث الجفني سيد قومه ... ليلتمسن بالجيش دار المحارب)\nناه إسحاق خفيف ثقيل أول بالبنصر على مذهبه من رواية عمرو بن بانة عنه ومن رواية حبش وغناه ابن سريج ثاني ثقيل بالبنصر يقول ليس لي علم بما يكون من صاحبي إلا أني أحسن الظن به وقوله\n(لئن كان للقبرين ... )\nيعني لئن كان عمرو ابنا للمدفونين في هذين القبرين يعني قبر أبيه وجده وهما الحارث الأكبر والحارث الأعرج ليلتمسن جيشه دار المحارب له يحرضه بذلك ويروى أرض المحارب\n(ولا عيب فيهم غير أن سيوفهم ... بهن فلول من قراع الكتائب)\n(إذا استنزلوا عنهن الطعن أرقلوا ... إلى الموت إرقال الجمال المصاعب)\nوت\n(لهم شيمة لم يعطها الله غيرهم ... من الناس والأحلام غير عوازب)\n(على عارفات للطعان عوابس ... بهن كلوم بين دام وجالب)\n(ولا عيب فيهم غير أن سيوفهم ... بهن فلول من قراع الكتائب)\n(إذا استنزلوا عنهن للطعن أرقلوا ... إلى الموت إرقال الجمال المصاعب)\n(حبوت بها غسان إذ كنت لاحقا ... بقومي وإذ أعيت علي مذاهبي)\nجدت في كتاب لهارون بن محمد بن عبد الملك الزيات في البيتين والثالث والرابع لحنا منسوبا إلى معبد من خفيف الرمل بالوسطى وأحسبه من لحن يحيى المكي الشيمة الطبيعة وجمعها شيم غير عوازب أي لا تعزب أحلامهم فتنفذ عنهم وعارفات للطعان أي صابرات عليه قد عودت أن يحارب عليها وعوابس كوالح وجالب أي عليه جلبة وهي قشرة تكون على الجرح يقال جلب الجرح يجلب جلوبا وأجلب إجلابا والإرقال مشي يشبه الخبب سريع والمصاعب واحدها مصعب وهو الفحل الذي لم يمسسه الحبل وإنما يقتنى للفحلة ويقال له قرم ومقرم وقوله حبوت بها يعني\nبالقصيدة وروى أبو عبيدة إذ كنت لاحقا بقوم وقال يعني إذ كنت لاحقا بغيركم أي بقوم آخرين فكنتم أحق بالمدح منهم قالوا فنظر إلى النعمان بن الحارث أخي عمرو وهو يومئذ غلام فقال\n(هذا غلام حسن وجهه ... مقتبل الخير سريع التمام)\n(للحارث الأكبر والحارث الأصغر ... والأعرج خير الأنام)\n(ثم لهند ولهند فقد ... أسرع في الخيرات منه إمام)\n(خمسة آباء وهم ما هم ... هم خير من يشرب صوب الغمام)\nناه حنين خفيف رمل بالبنصر عن حبش","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":4,"spl":"مدحه النعمان وأخاه عمرو بن الحارث","song":1,"loc":1983,"partial":1},
{"id":"b113-8","bab":"الجزء 11","sec":"الشعبي يفضله على الأخطل في مجلس عبد الملك بن مروان","page":"ج11 ص23","text":"أخبرنا أحمد بن عبد العزيز الجوهري قال حدثناعمر بن شبة قال حدثنا هارون بن عبد الله الزبيري قال حدثنا شيخ يكنى أبا داود عن الشعبي قال\nدخلت على عبد الملك بن مروان وعنده الأخطل وأنا لا أعرفه\nفقلت حين دخلت عامر بن شراحيل الشعبي\nفقال على علم ما أذنا لك\nفقلت في نفسي خذ واحدة على وافد أهل العراق\nفسأل عبد الملك الأخطل من أشعر الناس قال أنا يا أمير المؤمنين\nفقلت لعبد الملك من هذا يا أمير\nالمؤمنين فتبسم وقال هذا الأخطل فقلت في نفسي خذها ثنتين على وافد أهل العراق فقلت أشعر منك الذي يقول\n(هذا غلام حسن وجهه ... مستقبل الخير سريع التمام)\n(للحارث الأكبر والحارث الأصغر ... والأعرج خير الأنام)\n(خمسة آباء وهم ما هم ... هم خير من يشرب ماء الغمام)\nالشعر للنابغة فقال الأخطل إن أمير المؤمنين إنما سألني عن أشعر أهل زمانه ولو سألني عن أشعر أهل الجاهلية لكنت حريا أن أقول كما قلت أو شبيها به فقلت في نفسي خذها ثلاثا على وافد أهل العراق يعني أنه أخطأ ثلاث مرات ونسخت هذا الخبر من كتاب أحمد بن الحارث الخراز ولم أسمعه من أحد ووجدته أتم مما رأيت في كل موضع فأتيت به في هذا الموضع وإن لم يكن من خاص خبر النابغة لأنه أليق به قال أحمد بن الحارث الخراز حدثني المدائني عن عبد الملك بن مسلم قال كتب عبد الملك إلى الحجاج إنه ليس شيء من لذة الدنيا إلا وقد أصبت منه ولم يكن عندي شيء ألذه إلا مناقلة الإخوان للحديث وقبلك عامر الشعبي فابعث به إلي يحدثني فدعا الحجاج الشعبي فجهزه وبعث به إليه وقرطه وأطراه في كتابه فخرج الشعبي حتى إذا كان بباب عبد الملك قال للحاجب استأذن لي قال من أنت قال أنا عامر الشعبي قال حياك الله ثم نهض فأجلسني على كرسيه فلم يلبث أن خرج إلي فقال ادخل يرحمك الله فدخلت فإذا عبد الملك جالس على كرسي وبين يديه رجل أبيض الرأس واللحية على كرسي فسلمت فرد علي السلام ثم أومأ إلي بقضيبه فقعدت عن يساره ثم أقبل على الذي بين يديه فقال ويحك\nمن اشعر الناس قال أنا يا أمير المؤمنين قال الشعبي فأظلم علي ما بيني وبين عبد الملك فلم أصبر أن قلت ومن هذا يا أمير المؤمنين الذي يزعم أنه أشعر الناس قال فعجب عبد الملك من عجلتي قبل أن يسألني عن حالي قال هذا الأخطل فقلت يا أخطل أشعر والله منك الذي يقول\n(هذا غلام حسن وجهه ... مستقبل الخير سريع التمام)\n(للحارث الأكبر والحارث الأصغر ... والأعرج خير الأنام)\n(ثم لهند ولهند فقد ... أسرع في الخيرات منه إمام)\n(خمسة آباء وهم ما هم ... هم خير من يشرب صوب الغمام)\nفرددتها حتى حفظها عبد الملك فقال الأخطل من هذا يا أمير المؤمنين قال هذا الشعبي قال فقال صدق والله يا أمير المؤمنين النابغة والله أشعر مني فقال الشعبي ثم أقبل علي فقال كيف أنت يا شعبي قلت بخير يا أمير المؤمنين فلا زلت به ثم ذهبت لأضع معاذيري لما كان من خلافي على الحجاج مع عبد الرحمن بن محمد بن الأشعث فقال مه إنا لا نحتاج إلى هذا المنطق ولا تراه منا في قول ولا فعل حتى تفارقنا ثم أقبل علي فقال ما تقول في النابغة قال قلت يا أمير المؤمنين قد فضله عمر بن الخطاب في غير موطن على الشعراء أجمعين وببابه وفد غطفان فقال يا معشر غطفان أي شعرائكم الذي يقول\n(حلفت فلم أترك لنفسك ريبة ... وليس وراء الله للمرء مذهب)\n(لئن كنت قد بلغت عني خيانة ... لمبلغك الواشي أغش وأكذب)\n(ولست بمستبق أخا لا تلمه ... على شعث أي الرجال المهذب)\nقالوا النابغة يا أمير المؤمنين قال فأيكم الذي يقول\n(فإنك كالليل الذي هو مدركي ... وإن خلت أن المنتأى عنك واسع)\n(خطاطيف حجن في حبال متينة ... تمد بها أيد إليك نوازع)\nالوا النابغة قال فأيكم الذي يقول\n(الى ابن محرق أعملت نفسي ... وراحلتي وقد هدت العيون)\n(أتيتك عاريا خلقا ثيابي ... على خوف تظن بي الظنون)\n(فألفيت الأمانة لم تحنها ... كذلك كان نوح لا يخون)\nالوا النابغة يا أمير المؤمنين قال هذا أشعر شعرائكم قال ثم أقبل على الأخطل فقال أتحب أن لك قياضا بشعرك شعر أحد من العرب أو تحب أنك قلته قال لا والله يا أمير المؤمنين إلا أني وددت أن كنت قلت أبياتا قالها رجل منا كان والله ما علمت مغدف القناع قليل السماع قصير الذراع قال وما قال فأنشد قصيدته\n(إنا محيوك فاسلم أيها الطلل ... وإن بليت وإن طالت بك الطيل)","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":5,"spl":"الشعبي يفضله على الأخطل في مجلس عبد الملك بن مروان","loc":1984},
{"id":"b113-9","bab":"الجزء 11","sec":"الشعبي يفضله على الأخطل في مجلس عبد الملك بن مروان","page":"ج11 ص23","text":"(ليس الجديد به تبقى بشاشته ... إلا قليلا ولا ذو خلة يصل)\n(والعيش لا عيش إلا ما تقر به ... عين ولا حال إلا سوف تنتقل)\n(إن ترجعي من أبي عثمان منجحة ... فقد يهون على المستنجح العمل)\n(والناس من يلق خيرا قائلون له ... ما يشتهي ولأم المخطىء الهبل)\n(قد يدرك المتأني بعض حاجته ... وقد يكون مع المستعجل الزلل)\nحتى أتى على آخرها قال الشعبي فقلت قد قال القطامي أفضل من هذا قال وما قال قلت قال\n(طرقت جنوب رحالنا من مطرق ... ما كنت أحسبها قريب المعنق)\n(قطعت اليك بمثل جيد جداية ... حسن معلق تومتيه مطوق)\n(ومصرعين من الكلال كأنما ... شربوا الغبوق من الرحيق المعرق)\n(متوسدين ذراع كل نجيبة ... ومفرج عرق المقذ منوق)\n(وجثت على ركب تهد بها الصفا ... وعلى كلاكل كالنقيل المطرق)\n(وإذا سمعن إلى هماهم رفقة ... ومن النجوم غوابر لم تخفق)\n(جعلت تميل خدودها آذانها ... طربا بهن إلى حداء السوق)\n(كالمنصتات إلى الغناء سمعنه ... من رائع لقلوبهن مشوق)\n(وإذا نظرن إلى الطريق رأينه ... لهقا كشاكلة الحصان الأبلق)\n(وإذا تخلف بعدهن لحاجة ... حاد يشسع نعله لم يلحق)\n(وإذا يصيبك والحوادث جمة ... حدث حداك إلى أخيك الأوثق)\n(لئن الهموم عن الفؤاد تفرقت ... وخلا التكلم للسان المطلق)\nال فقال عبد الملك هذا والله أشعر ثكلت القطامي أمه قال فالتفت إلي الأخطل فقال يا شعبي إن لك فنونا في الأحاديث وإنما لنا فن واحد فإن رأيت ألا تحملني على أكتاف قومك فأدعهم حرضا فقلت لا أعرض لك في شيء من الشعر أبدا فأقلني في هذه المرة قال من يتكفل بك قلت أمير المؤمنين فقال عبد الملك هو علي ألا يعرض لك أبدا ثم قال يا شعبي أي نساء الجاهلية أشعر قلت خنساء قال ولم فضلتها على غيرها قلت لقولها\n(وقائلة والنعش قد فات خطوها ... لتدركه يالهف نفسي على صخر)\n(ألا ثكلت أم الذين غدوا به ... إلى القبر ماذا يحملون إلى القبر)\nفقال عبد الملك أشعر منها والله التي تقول\n(مهفهفث الكشح والسربال منخرق ... عنه القميص لسير الليل محتقر)\n(لا يأمن الناس ممساه ومصبحه ... في كل فج وإن لم يغز ينتظر)\nم قال يا شعبي لعلك شق عليك ما سمعت قلت إي والله يا أمير المؤمنين أشد المشقة إني أحدثك منذ شهرين لم أفدك إلا أبيات النابغة في الغلام قال يا شعبي إنما أعلمتك هذا لأنه بلغني أن اهل العراق يتطاولون على أهل الشام يقولون إن كانوا غلبونا على الدولة فلم يغلبونا على العلم والرواية وأهل الشأم أعلم بعلم أهل العراق من أهل العراق ثم رد علي الأبيات أبيات ليلى حتى حفظتها ولم أزل عنده فكنت أول داخل وآخر خارج قال فمكثت كذلك سنتين وجعلني في ألفين من العطاء وعشرين رجلا من ولدي وأهل بيتي في ألفين ألفين فبعثني إلى أخيه عبد العزيز بن مروان بمصر وكتب اليه يا أخي إني قد بعثت اليك الشعبي فأنظر هل رأيت مثله قط ثم أذن لي فأنصرفت أخبرني الحسين بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني وأخبرني ببعضه أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة عن أبي بكر الهذلي قال قال حسان بن ثابت قدمت علىالنعمان بن المنذر وقد أمتدحته فأتيت حاجبه عصام بن شهبر فجلست إليه فقال إني لأرى عربيا أفمن الحجاز أنت قلت نعم قال فكن قحطانيا فقلت فأنا قحطاني قال فكن يثربيا قلت فأنا يثربي قال فكن خزرجيا قلت فأنا خزرجي قال فكن حسان بن ثابت قلت فأنا هو قال أجئت بمدحة الملك قلت نعم قال فإني أرشدك إذا دخلت إليه فإنه يسألك عن جبلة بن الأيهم","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":6,"spl":"الشعبي يفضله على الأخطل في مجلس عبد الملك بن مروان","loc":1985},
{"id":"b113-10","bab":"الجزء 11","sec":"الشعبي يفضله على الأخطل في مجلس عبد الملك بن مروان","page":"ج11 ص23","text":"ويسبه فإياك أن تساعده على ذلك ولكن أمر ذكره إمرارا لا توافق فيه ولا تخالف وقل ما دخول مثلي أيها الملك بينك وبين جبلة وهو منك وأنت منه وإن دعاك إلى الطعام فلا تؤاكله فإن أقسم عليك فأصب منه اليسير إصابة بار قسمه متشرف بمؤاكلته لا أكل جائع سغب ولا تطل محادثته ولا تبدأه بإخبار عن شيء حتى يكون هو السائل لك ولا تطل الإقامة في مجلسه فقلت أحسن الله رفدك قد أوصيت واعيا ودخل ثم خرج إلي فقال لي ادخل فدخلت فسلمت وحييت تحية الملوك فجاراني من أمر جبلة ما قاله عصام كأنه كان حاضرا وأجبت بما أمرني ثم أستأذنته في الإنشاد فأذن لي فأنشدته ثم دعا بالطعام ففعلت ما أمرني عصام به وبالشراب ففعلت مثل ذلك فأمر لي بجائزة سنية وخرجت فقال لي عصام بقيت علي واحدة لم أوصك بها قد بلغني أن النابغة الذبياني قدم عليه وإذا قدم فليس لأحد منه حظ سواه فأستأذن حينئذ وانصرف مكرما خير من أن تنصرف مجفوا فأقمت ببابه شهرا ثم قدم عليه الفزاريان وكان بينهما وبين النعمان دخلل أي خاصة وكان معهما النابغة قد استجار بهما وسألهما مسألة النعمان أن يرضى عنه فضرب عليهما قبة من أدم ولم يشعر بأن النابغة معهما ودس النابغة قينة تغنيه بشعره\n(يا دار مية بالعلياء فالسند ... )\nلما سمع الشعر قال أقسم بالله إنه لشعر النابغة وسأل عنه فأخبر أنه مع الفزاريين فكلماه فيه فأمنه وقال أبو زيد عمر بن شبة في خبره لما صار معهما إلى النعمان كان يرسل إليهما بطيب وألطاف مع قينة من إمائه فكانا يأمرانها أن تبدأ بالنابغة\nقبلهما فذكرت ذلك للنعمان فعلم أنه النابغة ثم ألقى عليها شعره هذا وسألها أن تغنيه به إذا أخذت فيه الخمر ففعلت فأطربته فقال هذا شعر علوي هذا شعر النابغة قال ثم خرج في غب سماء فعارضه الفزاريان والنابغة بينهما قد خضب بحناء فقنأ خضابه فلما رآه النعمان قال هي بدم كانت أحرى أن تخضب فقال الفزاريان أبيت اللعن لا تثريب قد أجرناه والعفو أجمل فأمنه وأستنشده أشعاره فعند ذلك قال حسان بن ثابت فحسدته على ثلاث لا أدري على أيتهن كنت له أشد حسدا على إدناء النعمان له بعد المباعدة ومسامرته له وإصغائه إليه أم على جودة شعره أم على مائة بعير من عصافيره أمر له بها قال أبو عبيدة قيل لأبي عمرو أفمن مخافته امتدحه وأتاه بعد هربه منه أم لغير ذلك فقال لا لعمر الله ما لمخافته فعل إن كان لامنا من أن يوجه النعمان له جيشا وما كانت عشيرته لتسلمه لأول وهلة ولكنه رغب في عطاياه وعصافيره وكان النابغة يأكل ويشرب في آنية الفضة والذهب من عطايا النعمان وأبيه وجده لا يستعمل غير ذلك وقيل إن السبب في رجوعه إلى النعمان بعد هربه منه أنه بلغه أنه عليل لا يرجى فأقلقه ذلك ولم يملك الصبر على البعد عنه مع علته وما خافه عليه وأشفق من حدوثه به فصار إليه وألفاه محمولا على سريره ينقل ما بين الغمر وقصور الحيرة فقال لعصام بن شهبر حاجبه فيما أخبرنا به اليزيدي عن عمه عبيد الله وابن حبيب عن ابن الأعرابي عن المفضل\n\n(ألم أقسم عليك لتخبرني ... أمحمول على النعش الهمام)\n(فإني لا ألومك في دخولي ... ولكن ما وراءك يا عصام)\n(فإن يهلك أبو قابوس يهلك ... ربيع الناس والشهر الحرام)\n(ونمسك بعده بذناب عيش ... أجب الظهر ليس له سنام)\nناه حنين ثقيلا أول بالبنصر عن حبش قال أبو عبيدة كانت ملوك العرب إذا مرض أحدهم حملته الرجال على أكتافها يتعاقبونه فيكون كذلك على أكتاف الرجال لأنه عندهم أوطأ من الأرض وقوله\n(فإني لا ألومك في دخولي ... )\nي لا ألومك في ترك الإذن لي في الدخول ولكن أخبرني بكنه أمره وقوله\n(ربيع الناس والشهر الحرام ... )\nريد أنه كالربيع في الخصب لمجتديه وكالشهر الحرام لجاره لا يوصل إلى من أجاره كما لا يوصل في الشهر الحرام إلى أحد","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":7,"spl":"الشعبي يفضله على الأخطل في مجلس عبد الملك بن مروان","song":1,"loc":1986,"partialRef":{"sid":"b68-2","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b113-11","bab":"الجزء 11","sec":"أصوات من شعره تغنى","page":"ج11 ص33","text":"\n(رأيتك ترعاني بعين بصيرة ... وتبعث حراسا علي وناظرا)\n(فآليت لا آتيك إن كنت مجرما ... ولا أبتغي جارا سواك مجاورا)\n(وأهلي فداء لامرىء إن أتيته ... تقبل معروفي وسد المفاقرا)\n(ألا أبلغ النعمان حيث لقيته ... وأهدى له الله الغيوث البواكرا)\nناه خليد الوادي رملا بالبنصر من رواية حبش ومما يغنى فيه من قصائد النابغة التي يعتذر فيها إلى النعمان\n(يا دار مية بالعلياء فالسند ... أقوت وطال عليها سالف الأمد)\n(وقفت فيها أصيلانا أسائلها ... أعيت جوابا وما بالربع من أحد)\n(إلا الأواري لأيا ما أبينها ... والنؤي كالحوض بالمظلومة الجلد)\n(ردت عليه أقاصيه ولبده ... ضرب الوليدة بالمسحاة في الثأد)\n(خلت سبيل أتي كان يحبسه ... ورفعته إلى السجفين فالنضد)\n(أضحت خلاء وأضحى أهلها احتملوا ... أخنى عليها الذي أخنى على لبد)\nالغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه لجميلة ثاني ثقيل بالبنصر عن عمرو وحبش قال الأصمعي قوله يا دار مية يريد يا أهل دار مية كما قال امرؤ القيس\n(ألاعم صباحا أيها الطلل البالي ... )\nريد أهل الطلل وقال الفراء إنما نادى الدار لا أهلها أسفا عليها وتشوقا إلى أهلها وتمنيه أن تكون أهلا والعلياء المكان المرتفع بناؤه يقال من ذلك علا يعلو وعلي يعلى مثل حلا يحلو وحلي يحلى وسلا يسلو وسلي يسلى والسند سند الجبل وهو ارتفاعه حيث يسند فيه أي يصعد أقوت أقفرت وخلت من أهلها وقال أبو عبيدة في قوله يا دار مية ثم قال أقوت ولم يقل أقويت إن من شأن العرب أن يخاطبوا الشيء ثم يتركوه ويكفوا عنه وروى الأصمعي أصيلانا وهو تصغير أصلان ويروى عيت جوابا أي عييت بالجواب والأواري جمع آري ولأيا بطأ والمظلومة التي لم يكن فيها أثر فحفر أهلها فيها حوضا وظلمهم إياها إحداثهم فيها ما لم يكن فيها شبه النؤي بذلك الحوض لاستدارته والجلد الأرض الصلبة الغليظة من غير حجارة وإنما جعلها جلدا لأن الحفر فيها لا يسهل وقوله ردت عليه أقاصيه يعني أمة فعلت ذلك أضمرها ولم يكن جرى لها ذكر وأقاصيه يعني أقاصي النؤي على أدناه ليرتفع ولبده طأمنه والوليدة الأمة\nالشابة والثأد الندى والسبيل الطريق والأتي النهر المحفور والأتي السيل من حيث كان يقول لما أفسدت طريق الأتي سهلت له طريقا حتى جرى ورفعته أي قدمت الحفر الى موضع السجفين وليس رفعته ها هنا من ارتفاع العلو والسجفان ستران رقيقان يكونان في مقدم البيت والنضد ما نضد من المتاع وأخنى أفسد ولبد آخر نسور لقمان التي اختار أن يعمر مثل أعمارها وله حديث ليس هذا موضعه\n(أسرت عليه من الجوزاء سارية ... تزجي الشمال عليه جامد البرد)\n(فأرتاع من صوت كلاب فبات له ... طوع الشوامت من خوف ومن صرد)\n(فبثهن عليه وأستمر به ... صمع الكعوب بريات من الحرد)\n(وكان ضمران منه حيث يوزعه ... طعن المعارك عند المحجر النجد)\n(شك الفريصة بالمدرى فأنفذها ... طعن المبيطر إذ يشفي من العضد)\nنى فيه إبراهيم الموصلي هزجا بالبنصر من رواية عمرو بن بانة وفيه لحن لمالك يعني أن سحابة مرت عليه ليلا وأن أنواء الجوزاء أسرت عليه بها وتزجي تسوق وتدفع عليه أي على الثور والكلاب صاحب\nالكلاب وقوله بات له طوع الشوامت أي بات له ما يسر الشوامت اللواتي شمتن به وصمع الكعوب يعني قوائمه أنها لازقة محددة الأطراف ليست برهلات وأصل الصمع رقة الشيء ولطافته والحرد داء يعيبه يقال بعير أحرد وناقة حرداء والمحجر الملجأ والنجد الشجاع والفريصة مرجع الكتف الى الخاصرة والمدرى القرن والمبيطر البيطار والعضد داء يأخذ في العضد وفي لحن ابراهيم الموصلي بعد فارتاع من صوت كلاب\n(كأن رحلي وقد زال النهار بنا ... يوم الجليل على مستأنس وحد)\n(من وحش وجرة موشي أكارعه ... طاوي المصير كسيف الصيقل الفرد)\nال الأصمعي زال النهار بنا أي انتصف وبنا ها هنا في موضع علينا ومن روى مستوجس فإنه يعني أنه قد أوجس شيئا خافه فهو يستوجس والجليل الثمام واحدته جليلة ووجرة طرف السي وهي فلاة بين مران وذات عرق وهي ستون ميلا يجتمع فيها الوحش وموشي أكارعه أي إنه أبيض في قوائمه نقط سود وفي وجهه سفعة وطاوي المصير ضامر والمصير المعي وجمعه المصران والفرد المنقطع القرين يقال فرد وفرد وفرد","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":8,"spl":"أصوات من شعره تغنى","song":3,"loc":1987,"partial":1},
{"id":"b113-12","bab":"الجزء 11","sec":"أصوات من شعره تغنى","page":"ج11 ص33","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني إسحاق بن إبراهيم الموصلي قال غنى مخارق يوما بين يدي الرشيد\n(سرت عليه من الجوزاء سارية ... )\nفلما بلغ إلى قوله\n(فأرتاع من صوت كلاب فبات له ... )\nال فارتاع بضم العين فأردت أن أرد عليه خطأه ثم خفت أن يغضب الرشيد ويظن أني حسدته على منزلته منه وأردت إسقاطه فالتفت إليه بعض من حضر أظنه قال محمد بن عمر الرومي فقال له ويلك يا مخارق أتغني بمثل هذا الخطأ القبيح لسوقة فضلا عن الملوك ويلك لو قلت فارتاع كان أخف على اللسان وأسهل من قولك فارتاع فخجل مخارق وكفيت ما أردته بغيري قال وكان مخارق لحانا ومنها\n(قالت ألا ليتما هذا الحمام لنا ... إلى حمامتنا ونصفه فقد)\n(يحفه جانبا نيق وتتبعه ... مثل الزجاجة لم تكحل من الرمد)\n(فحسبوه فألفوه كما حسبت ... تسعا وتسعين لم تنقص ولم تزد)\n(فكملت مائة فيها حمامتها ... وأسرعت حسبة في ذلك العدد)\nناه ابن سريج خفيف ثقيل عن الهشامي هذا خبر روي عن زرقاء اليمامة ويروى عن بنت الخس","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":9,"spl":"أصوات من شعره تغنى — اعجابه بمعنى لزرقاء اليمامة واخذه عنها","song":1,"loc":1988,"partialRef":{"sid":"b113-11","gi":3,"vi":1,"side":0},"partial":1},
{"id":"b113-13","bab":"الجزء 11","sec":"اعجابه بمعنى لزرقاء اليمامة واخذه عنها","page":"ج11 ص38","text":"حدثني محمد بن العباس اليزيدي قال سمعت أبا العباس محمد بن الحسن الأحول يقول هذا أخذه النابغة من زرقاء اليمامة قالت\n(ليت الحمام ليه ... ونصفه قديه)\n(الى حمامتيه ... تم الحمام ميه)\nسلخه النابغة وقال الأصمعي سمعت أناسا من أهل البادية يتحدثون أن بنت الخس كانت قاعدة في جوار فمر بها قطا وارد في مضيق من الجبل فقالت\n(ياليت ذا القطا ليه ... ومثل نصف معيه)\n(إلى قطاة أهليه ... إذا لنا قطا ميه)\nوأتبعت فعدت على الماء فإذا هي ست وستون وقوله فقد أي فحسب ويحفه أي يكون من ناحية هذا الثمد يقال حف القوم بالرجل أي اكتنفوه والنيق الجبل ومثل الزجاجة يريد عينا صافية كصفاء الزجاجة الحسبة الهيئة التي تحسب يقال ما أحسن حسبته مثل الجلسة واللبسة والركبة ومنها\n(نبئت أن أبا قابوس أوعدني ... ولا قرار على زأر من الأسد)\n(مهلا فداء لك الأقوام كلهم ... وما أثمر من مال ومن ولد)\n(إن كنت قلت الذي بلغت معتمدا ... إذا فلا رفعت سوطي إلي يدي)\n(هذا الثناء فإن تسمع به حسنا ... فلم أعرض أبيت اللعن بالصفد)\nناه الهذلي ولحنه من الثقيل الأول عن الهشامي أثمر أصلح وأجمع والزأر صياح الأسد يقال زأر زئيرا وهو الزأر والصفد العطية يقال أصفده يصفده إصفادا إذا أعطاه وصفده يصفده صفدا إذا أوثقه","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":9,"spl":"أصوات من شعره تغنى — اعجابه بمعنى لزرقاء اليمامة واخذه عنها","song":1,"loc":1989},
{"id":"b113-14","bab":"الجزء 11","sec":"رواية حسان عنه حين وفد على النعمان","page":"ج11 ص39","text":"أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني الصلت بن مسعود قال حدثنا أحمد بن شبويه عن سليمان بن صالح عن عبد الله بن المبارك عن فليح بن سليمان عن رجل قد سماه عن حسان بن\nثابت ونسخت من كتاب ابن أبي خيثمة عن أبيه عن مصعب الزبيري قال قال حسان بن ثابت وأخبرنا محمد بن العباس اليزيدي قال حدثني عمي يوسف بن محمد عن عمه إسماعيل بن أبي محمد قال قال أبو عمرو الشيباني قال حسان ابن ثابت وقد جمعت رواياتهم وذكرت اختلافهم فيها وأكثر اللفظ للجوهري قال خرجت الى النعمان بن المنذر فلقيت رجلا وقال اليزيدي في خبره فلقيت صائغا من أهل فدك فلما رآني قال كن يثربيا فقلت الأمر كذلك قال كن خزرجيا قلت أنا خزرجي قال كن نجاريا قلت أنا نجاري قال كن حسان بن ثابت قلت أنا هو فقال أين تريد قلت إلى هذا الملك قال تريد أن أسددك إلى أين تذهب ومن تريد قلت نعم قال إن لي به علما وخبرا قلت فأعلمني ذلك قال فإنك إذا جئته متروك شهرا قبل أن يرسل إليك ثم عسى أن يسأل عنك رأس الشهر ثم إنك متروك آخر بعد المسألة ثم عسى أن يؤذن لك فإن أنت خلوت به وأعجبته فأنت مصيب منه خيرا فأقم ما أقمت فإن رأيت أبا أمامة فأظعن فلا شيء لك عنده قال فقدمت ففعل بي ما قال الرجل ثم أذن لي وأصبت منه مالا كثيرا ونادمته وأكلت معه فبينا أنا على ذلك وأنا معه في قبة له إذا رجل يرتجز حولها\n(أصم أم يسمع رب القبه ... يا أوهب الناس لعنس صلبه)\n(ضرابة بالمشفر الأذبه ... ذات هبات في يديها جلبه)\n(في لاحب كأنه الأطبه ... )\nوفي رواية اليزيدي في يديها خدبة أي طول واضطراب والأطبة جمع طباب وهو الشراك يجمع فيه بين الأديمين في الخرز وقال عمر بن شبة في خبره قال فليح بن سليمان أخذت هذا الرجز عن ابن دأب قال فقال أليس بأبي أمامة قالوا بلى قال فأذنوا له ودخل فحياه وشرب معه ثم وردت النعم السود ولم يكن لأحد من العرب بعير أسود يعرف مكانه ولا يفتحل أحد بعيرا أسود غير النعمان فأستأذنه في أن ينشده كلمته على الباء فأذن له أن ينشده قصيدته التي يقول فيها\n(فإنك شمس والملوك كواكب ... إذا طلعت لم يبد منهن كوكب)\nووردت عليه مائة من الإبل السود الكلبية فيها رعاؤها وبيتها وكلبها فقال شأنك بها يا أبا أمامة فهي لك بما فيها قال حسان فما أصابني حسد في موضع ما أصابني يومئذ وما أدري أيما كنت أحسد له عليه ألما أسمع من فضل شعره أم ما أرى من جزيل عطائه فجمعت جراميزي وركبت إلى بلادي وقد روى الواقدي عن محمد بن صالح الخبر فذكر أن حسان قدم علىجبلة بن أبي شمر ولعله غلط أخبرنا به محمد بن العباس اليزيدي قال حدثني عمي يوسف قال حدثني عمي إسماعيل عن الواقدي عن محمد بن صالح قال كان حسان بن ثابت يقدم على جبلة بن الأيهم سنة ويقيم سنة في أهله فقال لو وفدت على الحارث فإن له قرابة ورحما بصاحبي وهو أبذل\nالناس لمعروف وقد يئس مني أن أقدم عليه لما يعرف من انقطاعي إلى جبلة فخرجت في السنة التي كنت أقيم فيها بالمدينة حتى قدمت على الحارث وقد هيأت مديحا فقال لي حاجبه وكان لي ناصحا إن الملك قد سر بقدومك عليه وهو لا يدعك حتى تذكر جبلة فإياك أن تقع فيه فإنه يختبرك فإنك إن وقعت فيه زهد فيك وإن ذكرت محاسنه ثقل عليه فلا تبتدىء بذكره فإن سألك عنه فلا تطنب في الثناء عليه ولا تعبه امسح ذكره مسحا وجاوزه وإنه سوف يدعوك الى الطعام وهو يثقل عليه أن يؤكل طعامه أو يشرب شرابه فلا تضع يدك في شيء حتى يدعوك إليه قال فشكرت له ذلك ثم دعاني فسألني عن البلاد والناس وعن عيشنا في الحجاز وكيف ما بيننا من الحرب وكل ذلك أخبره حتى انتهى الى ذكر جبلة فقال كيف تجد جبلة فقد انقطعت إليه وتركتنا فقلت له إنما جبلة منك وأنت منه فلم أجر معه في مدح ولا ذم وفعلت في الطعام والشراب كما قال لي الحاجب قال ثم قال لي الحاجب قد بلغني قدوم النابغة وهو صديقه وآنس به وهو قبيح أن يجفوك بعد البر فاستأذنه من الآن فهو أحسن فاستأذنته فأذن لي وأمر لي بخمسمائة دينار وكسا وحملان فقبضتها وانصرفت إلى أهلي\n(ملوك وإخوان إذا ما لقيتهم ... أحكم في أموالهم وأقرب)\n(ولكنني كنت امرأ لي جانب ... من الأرض فيه مستراد ومطلب)","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":10,"spl":"رواية حسان عنه حين وفد على النعمان","song":1,"loc":1990,"partial":1},
{"id":"b113-15","bab":"الجزء 11","sec":"رواية حسان عنه حين وفد على النعمان","page":"ج11 ص39","text":"لغناء لإبراهيم ثقيل أول الجانب هنا المتسع من الأرض والمستراد المختلف يذهب فيه ويجيء ويقال راد الرجل لأهله إذا خرج رائدا لهم في طلب الكلإ ونحوه ثم ذكر مستراده فقال ملوك وإخوان ومن القصيدة العينية\n\n(عفا ذو حسا من فرتنا فالفوارع ... فجنبا أريك فالتلاع الدوافع)\n(فمجتمع الأشراج غير رسمها ... مصايف مرت بعدنا ومرابع)\n(توهمت آيات لها فعرفتها ... لستة أعوام وذا العام سابع)\n(رماد ككحل العين ما إن أبينه ... ونؤي كجذم الحوض أثلم خاشع)\nناه معبد من رواية حبش رملا بالبنصر\n(آذنتنا ببينها أسماء ... رب ثاو يمل منه الثواء)\n(بعد عهد لها ببرقة شما ... ء فأدنى ديارها اخصاء)\nروضه من الخفيف آذنتنا أعلمتنا والبين الفرقة والثاوي المقيم يقال ثوى ثواء والبرقة أرض ذات رمل وطين وشماء والخلصاء موضعان الشعر للحارث بن حلزة اليشكري والغناء لمعبد ثقيل أول بالوسطى عن عمرو ومن الناس من ينسبه إلى حنين","topic":"أخبار النابغة ونسبه","topicNo":113,"sp":11,"spl":"رواية حسان عنه حين وفد على النعمان","song":2,"loc":1991},
{"id":"b114-3","bab":"الجزء 11","sec":"أخبار الحارث بن حلزة ونسبه — مناسبة قصيدته المعلقة — قفي قبل التفرق يا ظعينا","page":"ج11 ص43 – ج11 ص44 – ج11 ص46","text":"هو الحارث بن حلزة بن مكروه بن يزيد بن عبد الله بن مالك بن عبد بن سعد بن جشم بن عاصم بن ذبيان بن كنانة بن يشكر بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار\nقال أبو عمرو الشيباني كان من خبر هذه القصيدة والسبب الذي دعا الحارث إلى قولها أن عمرو بن هند الملك وكان جبارا عظيم الشأن والملك لما جمع بكرا وتغلب ابني وائل وأصلح بينهم أخذ من الحيين رهنا من كل حي مائة غلام ليكف بعضهم عن بعض فكان أولئك الرهن يكونون معه في مسيره ويغزون معه فأصابتهم سموم في بعض مسيرهم فهلك عامة التغلبيين وسلم البكريون فقالت تغلب لبكر أعطونا ديات أبنائنا فإن ذلك لكم لازم فأبت بكر بن وائل فاجتمعت تغلب إلى عمرو بن كلثوم وأخبروه بالقصة فقال عمرو ابن كلثوم لتغلب بمن ترون بكرا تعصب أمرها اليوم قالوا بمن عسى إلا برجل من أولاد ثعلبة قال عمرو أرى والله الأمر سينجلي عن أحمر أصلج أصم من بني يشكر فجاءت بكر بالنعمان بن هرم أحد بني ثعلبة بن غنم بن يشكر وجاءت تغلب بعمرو بن كلثوم فلما\nاجتمعوا عند الملك قال عمرو بن كلثوم للنعمان بن هرم يا أصم جاءت بك أولاد ثعلبة تناضل عنهم وهم يفخرون عليك فقال النعمان وعلى من أظلت السماء كلها يفخرون ثم لا ينكر ذلك فقال عمرو بن كلثوم له أما والله لو لطمتك لطمة ما أخذوا لك بها فقال له النعمان والله لو فعلت ما أفلت بها قيس أير أبيك فغضب عمرو بن هند وكان يؤثر بني تغلب على بكر فقال يا جارية أعطيه لحيا بلسان أنثى أي سبية بلسانك فقال أيها الملك أعط ذلك أحب أهلك إليك فقال يا نعمان أيسرك أني أبوك قال لا ولكن وددت أنك أمي فغضب عمرو بن هند غضبا شديدا حتى هم بالنعمان وقام الحارث بن حلزة فارتجل قصيدته هذه ارتجالا توكأ على قوسه وأنشدها وانتظم كفه وهو لا يشعر من الغضب حتى فرغ منها قال ابن الكلبي أنشد الحارث عمرو بن هند هذه القصيدة وكان به وضح فقيل لعمرو بن هند إن به وضحا فأمر أن يجعل بينه وبينه ستر فلما تكلم أعجب بمنطقه فلم يزل عمرو يقول أدنوه حتى أمر بطرح الستر وأقعده معه قريبا منه لإعجابه به هذه رواية أبي عمرو وذكر الأصمعي نحوا من ذلك وقال أخذ منهم ثمانين غلاما من كل حي وأصلح بينهم بذي المجاز وذكر أن الغلمان من بني تغلب كانوا معه في حرب فأصيبوا وقال في خبره إن الحارث بن حلزة لما ارتجل هذه القصيدة بين يدي عمرو قام عمرو بن كلثوم فارتجل قصيدته\nوغير الأصمعي ينكر ذلك وينكر أنه السبب في قول عمرو بن كلثوم وذكر ابن الكلبي عن أبيه ان الصلح كان بين بكر وتغلب عن المنذر بن ماء السماء وكان قد شرط أي رجل وجد قتيلا في دار قوم فهم ضامنون لدمه وإن وجد بين محلتين قيس ما بينهما فينظر أقربهما إليه فتضمن ذلك القتيل وكان الذي ولي ذلك واحتمى لبني تغلب قيس بن شراحيل بن مرة بن همام ثم إن المنذر أخذ من الحيين أشرافهم وأعلامهم فبعث بهم إلى مكة فشرط بعضهم على بعض وتواثقوا على ألا يبقي واحد منهم لصاحبه غائلة ولا يطلبه بشيء مما كان من الآخر من الدماء وبعث المنذر معهم رجلا من بني تميم يقال له الغلاق وفي ذلك يقول الحارث بن حلزة\n(فهلا سعيت لصلح الصديق ... كصلح ابن مارية الأقصم)\n(وقيس تدارك بكر العراق ... وتغلب من شرها الأعظم)\n(وبيت شراحيل في وائل ... مكان الثريا من الأنجم)\n(فأصلح ما أفسدوا بينهم ... كذلك فعل الفتى الأكرم)\nبن مارية هو قيس بن شراحيل ومارية أمه بنت الصباح بن شيبان من بني هند فلبثوا كذلك ما شاء الله وقد أخذ المنذر من الفريقين رهنا بأحداثهم فمتى التوى أحد منهم بحق صاحبه أقاد من الرهن فسرح النعمان ابن المنذر ركبا من بني تغلب إلى طيىء في أمر من أمره فنزلوا بالطرفة وهي لبني شيبان وتيم اللات فذكروا أنهم أجلوهم عن الماء وحملوهم على المفازة فمات القوم عطشا فلما بلغ ذلك بني تغلب غضبوا وأتوا عمرو بن\nهند فاستعدوه على بكر وقالوا غدرتم ونقضتم العهد وانتهكتم الحرمة وسفكتم الدماء وقالت بكر أنتم الذين فعلتم ذلك قذفتمونا بالعضيهة وسمعتم الناس بها وهتكتم الحجاب والستر بادعائكم الباطل علينا قد سقيناهم إذ وردوا وحملناهم على الطريق إذ خرجوا فهل علينا إذ حار القوم وضلوا ويصدق ذلك قول الحارث بن حلزة\n(لم يغروكم غرورا ولكن ... يرفع الآل جرمهم والضحاء)","topic":"أخبار الحارث بن حلزة ونسبه","topicNo":114,"sp":0,"spl":"أخبار الحارث بن حلزة ونسبه — مناسبة قصيدته المعلقة — قفي قبل التفرق يا ظعينا","loc":1992},
{"id":"b114-4","bab":"الجزء 11","sec":"ابو عمرو الشيباني يعجب لارتجاله معلقته في موقف واحد","page":"ج11 ص47","text":"وقال يعقوب بن السكيت كان أبو عمرو الشيباني يعجب لارتجال الحارث هذه القصيدة في موقف واحد ويقول لو قالها في حول لم يلم\nقال وقد جمع فيها ذكر عدة من أيام العرب عير ببعضها بني تغلب تصريحا وعرض ببعضها لعمرو بن هند فمن ذلك قوله\n(أعلينا جناح كندة أن يغنم ... غازيهم ومنا الجزاء)\nال وكانت كندة قد كسرت الخراج على الملك فبعث اليهم رجالا من بني تغلب يطالبونهم بذلك فقتلوا ولم يدرك بثأرهم فعيرهم بذلك هكذا ذكر الأصمعي وذكر غيره أن كندة غزتهم فقتلت وسبت واستاقت فلم يكن في ذلك منهم شيء ولا أدركوا ثأرا قال وهكذا البيت الذي يليه وهو\n(أم علينا جرى قضاعة أم ليس ... علينا فيما جنوا أنداء)\nإنه عيره بأن قضاعة كانت غزت بني تغلب ففعلت بهم فعل كندة ولم يكن منهم في ذلك شيء ولا أدركوا منهم ثأرا قال وقوله\n(أم علينا جرى حنيفة أم ما ... جمعت من محارب غبراء)\nال وكانت حنيفة محالفة لتغلب على بكر فأذكر الحارث عمرو بن هند بهذا البيت قتل شمر بن عمرو الحنفي أحد بني سحيم المنذر بن ماء السماء غيلة لما حارب الحارث بن جبلة الغساني وبعث الحارث إلى المنذر بمائة غلام تحت لواء شمر هذا يسأله الأمان على أن يخرج له عن ملكه ويكون من قبله فركن المنذر إلى ذلك وأقام الغلمان معه فاغتاله شمر بن عمرو الحنفي فقتله غيلة وتفرق من كان مع المنذر وانتهبوا عسكره فحرضه بذلك على حلفاء بني تغلب بني حنيفة قال وقوله\n(وثمانون من تميم بأيديهم ... رماح صدورهن القضاء)\nعني عمرا أحد بني سعد بن مناة زيد خرج في ثمانين رجلا من تميم فأغار على قوم من بني قطن من تغلب يقال لهم بنو رزاح كانوا يسكنون أرضا تعرف بنطاع قريبة من البحرين فقتل فيهم وأخذ أموالا كثيرة فلم يدرك منه بثأر قال وقوله\n(ثم خيل من بعد ذاك مع الغلاق ... لا رأفة ولا إبقاء)\nال الغلاق صاحب هجائن النعمان بن المنذر وكان من بني حنظلة ابن زيد مناة تميميا وكان عمرو بن هند دعا بني تغلب بعد قتل المنذر إلى الطلب بثأره من غسان فامتنعوا وقالوا لا نطيع أحدا من بني المنذر أبدا أيظن ابن هند أنا له رعاء فغضب عمرو بن هند وجمع جموعا كثيرة من العرب فلما اجتمعت آلى ألا يغزو قبل تغلب أحدا فغزاهم فقتل منهم قوما ثم استعطفه من معه لهم واستوهبوه جريرتهم فأمسك عن بقيتهم وطلت دماء القتلى فذلك قول الحارث\n(من أصابوا من تغلبي فمطلول ... عليه إذا تولى العفاء)\nثم اعتد على عمرو بحسن بلاء بكر عنده فقال\n(من لنا عنده من الخير آيات ... ثلاث في كلهن القضاء)\n(آية شارق الشقيقة إذا جاءوا ... جميعا لكل حي لواء)\n(حول قيس مستلئمين بكبش ... قرظي كأنه عبلاء)\n(فرددناهم بضرب كما يخرج ... من خربة المزاد الماء)\n(ثم حجرا أعني ابن أم قطام ... وله فارسية خضراء)\n(أسد في اللقاء ذو أشبال ... وربيع إن شنعت غبراء)\n(فرددناهم بطعن كما تنهز ... في جمة الطوي الدلاء)\n(وفككنا غل امرىء القيس عنه ... بعدما طال حبسه والعناء)\n(وأقدناه رب غسان بالمنذر ... كرها وما تكال الدماء)\n(وفديناهم بتسعة أملاك ... كرام اسلابهم أغلاء)\n(ومع الجون آل بني الأوس ... عنود كأنها دفواء)\nعني بهذه الأيام أياما كانت كلها لبكر مع المنذر فمنها يوم الشقيقة وهم قوم من شيبان جاؤوا مع قيس بن معد يكرب ومعه جمع عظيم من أهل اليمن يغيرون على إبل عمرو بن هند فردتهم بنو يشكر وقتلوا فيهم ولم يوصل إلى شيء من إبل عمرو بن هند ومنها يوم غزا حجر الكندي وهو حجر بن أم قطام امرأ القيس وهو ماء السماء بن المنذر لقيه ومع حجر جمع\nكثير من كندة وكانت بكر مع امرىء القيس فخرجت إلى حجر فردته وقتلت جنوده وقوله\n(ففككنا غل امرىء القيس عنه ... )","topic":"أخبار الحارث بن حلزة ونسبه","topicNo":114,"sp":1,"spl":"ابو عمرو الشيباني يعجب لارتجاله معلقته في موقف واحد","loc":1993,"partial":1},
{"id":"b114-5","bab":"الجزء 11","sec":"ابو عمرو الشيباني يعجب لارتجاله معلقته في موقف واحد","page":"ج11 ص47","text":"كانت غسان أسرته يوم قتل المنذر أبيه فأغارت بكر بن وائل على بعض بوادي الشام فقتلوا ملكا من ملوك غسان واستنقذوا امرأ القيس بن المنذر وأخذ عمرو بن هند بنتا لذلك الملك يقال لها ميسون وقوله وفديناهم بتسعة يعني بني حجر آكل المرار وكان المنذر وجه خيلا من بكر في طلب بني حجر فظفرت بهم بكر بن وائل فأتوا المنذر بهم وهم تسعة فأمر بذبحهم في ظاهر الحيرة فذبحوا بمكان يقال له جفر الأملاك قال والجون جون آل بني الأوس ملك من ملوك كندة وهو ابن عم قيس بن معد يكرب وكان الجون جاء ليمنع بني آكل المرار ومعه كتيبة خشناء فحاربته بكر فهزموه وأخذوا بني الجون فجاؤوا بهم إلى المنذر فقتلهم قال فلما فرغ الحارث من هذه القصيدة حكم عمرو بن هند أنه لا يلزم بكر بن وائل ما حدث على رهائن تغلب فتفرقوا على هذه الحال ثم لم يزل في نفسه من ذلك شيء حتى هم باستخدام أم عمرو بن كلثوم تعرضا لهم وإذلالا فقتله عمرو بن كلثوم وخبره يذكر هناك قال يعقوب بن السكيت أنشدني النضر بن شميل للحارث بن حلزة وكان يستحسنها ويستجيدها ويقول لله دره ما أشعره\n(من حاكم بيني وبين ... الدهر مال علي عمدا)\n(أودى بسادتنا وقد ... تركوا لنا حلقا وجردا)\n(خيلي وفارسها ورب ... أبيك كان أعز فقدا)\n(فلو أن ما يأوي إلي ... أصاب من ثهلان هدا)\n(فضعي قناعك إن ريب ... الدهر قد أفنى معدا)\n(فلكم رأيت معاشرا ... قد جمعوا مالا وولدا)\n(وهم زباب حائر ... لا تسمع الآذان رعدا)\n(فعش بجد لا يضرك ... النوك ما لاقيت جدا)\n(والعيش خير في ظلال ... النوك ممن عاش كدا)\nي البيت الأول من القصيدة والبيتين الأخيرين خفيف ثقيل أول بالوسطى لعبد الله بن العباس الربيعي ومن الناس من ينسبه إلى بابويه\n(ألا هبي بصحنك فاصبحينا ... ولا تبقي خمور الأندرينا)\n(مشعشعة كأن الحص فيها ... إذا ما الماء خالطها سخينا)\nعروضه من الوافر الشعر لعمرو بن كلثوم التغلبي والغناء لإسحاق ثقيل أول بالخنصر في مجرى الوسطى من روايته وفيه لإبراهيم ثاني ثقيل بالوسطى عن عمرو","topic":"أخبار الحارث بن حلزة ونسبه","topicNo":114,"sp":2,"spl":"ابو عمرو الشيباني يعجب لارتجاله معلقته في موقف واحد","song":2,"loc":1994},
{"id":"b115-1","bab":"الجزء 11","sec":"نسب عمرو بن كلثوم وخبره","page":"ج11 ص54","text":"هو عمرو بن كلثوم بن مالك بن عتاب بن سعد بن زهير بن جشم بن بكر بن حبيب بن عمرو بن غنم بن تغلب بن وائل بن قاسط بن هنب بن أفصى ابن دعمي بن جديلة بن أسد بن ربيعة بن نزار بن معد بن عدنان وأم عمرو بن كلثوم ليلى بنت مهلهل أخي كليب وأمها بنت بعج بن عتبة بن سعد بن زهير أخبرني محمد بن الحسن بن دريد قال حدثني العكلي عن العباس بن هشام عن أبيه عن خراش بن إسماعيل عن رجل من بني تغلب ثم من بني عتاب قال سمعت الأخذر وكان نسابة يقول لما تزوج مهلهل بنت بعج بن عتبة أهديت إليه فولدت له ليلى بنت مهلهل فقال مهلهل لإمرأته هند أقتليها فأمرت خادما لها أن تغيبها عنها فلما نام هتف به هاتف يقول\n(كم من فتى يؤمل ... وسيد شمردل)\n(وعدة لا تجهل ... في بطن بنت مهلهل)\nاستيقظ فقال ياهند أين بنتي قالت قتلتها قال كلا وإله ربيعة فكان أول من حلف بها فاصدقيني فأخبرته فقال أحسني غذاءها فتزوجها كلثوم بن مالك بن عتاب فلما حملت بعمرو بن كلثوم قالت إنه أتاني آت في المنام فقال\n(يا لك ليلى من ولد ... يقدم إقدام الأسد)\n(من جشم فيه العدد ... أقول قيلا لافند)\nولدت غلاما فسمته عمرا فلما أتت عليه سنة قالت أتاني ذلك الآتي في الليل أعرفه فأشار إلى الصبي وقال\n(إني زعيم لك أم عمرو ... بماجد الجد كريم النجر)\n(أشجع من ذي لبد هزبر ... وقاص أقران شديد الأسر)\n(يسودهم في خمسة وعشر ... )\nال الأخذر فكان كما قال ساد وهو ابن خمسة عشر ومات وله مائة وخمسون سنة","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":0,"spl":"نسب عمرو بن كلثوم وخبره — قصة قتله لعمرو بن هند","loc":1995,"partial":1},
{"id":"b115-2","bab":"الجزء 11","sec":"قصة قتله لعمرو بن هند","page":"ج11 ص56","text":"قال أبو عمرو حدثني أسد بن عمر الحنفي وكرد بن السمعي وغيرهما وقال ابن الكلبي حدثني أبي وشرقي بن القطامي وأخبرنا إبراهيم بن أيوب عن ابن قتيبة أن عمرو بن هند قال ذات يوم لندمائه هل تعلمون أحدا من العرب تأنف أمه من خدمة أمي فقالوا نعم أم عمرو بن كلثوم قال ولم قالوا لأن أباها مهلهل بن ربيعة وعمها كليب وائل أعز العرب وبعلها كلثوم بن مالك أفرس العرب وابنها عمرو وهو سيد قومه فأرسل عمرو بن هند إلى عمرو بن كلثوم يستزيره ويسأله أن يزير أمه أمه فأقبل عمرو من الجزيرة إلى الحيرة في جماعة بني تغلب وأقبلت ليلى بنت مهلهل في ظعن من بني تغلب وأمر عمرو بن هند برواقة فضرب فيما بين الحيرة والفرات وأرسل إلى وجوه أهل مملكته فحضروا في وجوه بني تغلب فدخل عمرو بن كلثوم على عمرو بن هند في رواقه ودخلت ليلى وهند في قبة من جانب الرواق وكانت هند عمة امرىء القيس بن حجر الشاعر وكانت أم ليلى بنت مهلهل بنت أخي فاطمة بنت ربيعة التي هي أم امرىء القيس وبينهما هذا النسب وقد كان عمرو بن هند أمر أمه أن تنحي الخدم إذا دعا بالطرف وتستخدم ليلى فدعا عمرو بمائدة ثم دعا بالطرف فقالت هند ناوليني يا ليلى ذلك الطبق فقالت ليلى لتقم صاحبة الحاجة إلى حاجتها فأعادت عليها وألحت فصاحت ليلى واذلاه يا لتغلب فسمعها عمرو بن كلثوم فثار الدم في وجهه ونظر إليه عمرو بن هند فعرف الشر في وجهه فوثب عمرو بن كلثوم إلى سيف لعمرو بن هند معلق بالرواق ليس هناك سيف غيره فضرب به رأس عمرو بن هند ونادى في بني تغلب فانتهبوا ما في الرواق وساقوا نجائبه وساروا نحو الجزيرة ففي ذلك يقول عمرو بن كلثوم\n(ألا هبي بصحنك فاصبحينا ... )\nكان قام بها خطيبا بسوق عكاظ وقام بها في موسم مكة وبنو تغلب تعظمها جدا ويرويها صغارهم وكبارهم حتى هجوا بذلك قال بعض شعراء بكر بن وائل\n(ألهى بني تغلب عن كل مكرمة ... قصيدة قالها عمرو بن كلثوم)\n(يروونها أبدا مذ كان أولهم ... يا للرجال لشعر غير مسؤوم)","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":0,"spl":"نسب عمرو بن كلثوم وخبره — قصة قتله لعمرو بن هند","loc":1996,"partialRef":{"sid":"b114-5","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b115-3","bab":"الجزء 11","sec":"شعراء تغلب يفخرون بقتله عمرو بن هند","page":"ج11 ص57","text":"وقال الفرزدق يرد على جرير في هجائه الأخطل\n(ما ضر تغلب وائل أهجوتها ... أم بلت حيث تناطح البحران)\n(قوم هم قتلوا ابن هند عنوة ... عمرا وهم قسطوا على النعمان)\nقال أفنون صريم التغلبي يفخر بفعل عمرو بن كلثوم في قصيدة له\n(لعمرك ما عمرو بن هند وقد دعا ... لتخدم ليلى أمه بموفق)\n(فقام ابن كلثوم إلى السيف مصلتا ... فأمسك من ندمانه بالمخنق)\n(وجلله عمرو على الرأس ضربة ... بذي شطب صافي الحديدة رونق)\nوقال وكان لعمرو أخ يقال له مرة بن كلثوم فقتل المنذر بن النعمان وأخاه وإياه عنى الأخطل بقوله لجرير\n(أبني كليب إن عمي اللذا ... قتلا الملوك وفككا الأغلالا)\nكان لعمرو بن كلثوم ابن يقال له عباد وهو قاتل بشر بن عمرو بن عدس ولعمرو بن كلثوم عقب باق ومنهم كلثوم بن عمرو العتابي الشاعر صاحب الرسائل","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":1,"spl":"شعراء تغلب يفخرون بقتله عمرو بن هند — أسره يزيد بن عمرو ثم أطلقه فمدحه","loc":1997},
{"id":"b115-4","bab":"الجزء 11","sec":"أسره يزيد بن عمرو ثم أطلقه فمدحه","page":"ج11 ص58","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسن الأحول عن ابن الأعرابي قال أغار عمرو بن كلثوم التغلبي على بني تميم ثم مر من غزوه ذلك على حي من بني قيس بن ثعلبة فملأ يديه منهم وأصاب أسارى وسبايا وكان فيمن أصاب أحمد بن جندل السعدي ثم انتهى إلى بني حنيفة باليمامة وفيهم أناس من عجل فسمع به أهل حجر فكان أول من أتاه من بني حنيفة بنو سحيم عليهم يزيد بن عمرو بن شمر فلما رآهم عمرو بن كلثوم ارتجز فقال\n(من عاذ مني بعدها فلا اجتبر ... ولا سقى الماء ولا أرعى الشجر)\n(بنو لجيم وجعاسيس مضر ... بجانب الدو يدهدون العكر)\nانتهى إليه يزيد بن عمرو فطعنه فصرعه عن فرسه وأسره وكان يزيد شديدا جسيما فشده في القد وقال له أنت الذي تقول\n(متى تعقد قرينتنا بحبل ... تجذ الحبل أو تقص القرينا)\nما إني سأقرنك إلى ناقتي هذه فأطردكما جميعا فنادى عمرو بن كلثوم يالربيعة أمثلة قال فاجتمعت بنو لجيم فنهوه ولم يكن يزيد ذلك به فسار به حتى أتى قصرا بحجر من قصورهم وضرب عليه قبة ونحر له وكساه وحمله على نجيبه وسقاه الخمر فلما أخذت برأسه تغنى\n(أأجمع صحبتي السحر ارتحالا ... ولم اشعر ببين منك هالا)\n(ولم أر مثل هالة في معد ... أشبه حسنها إلا الهلالا)\n(ألا أبلغ بني جشم بن بكر ... وتغلب كلما أتيا حلالا)\n(بأن الماجد القرم ابن عمرو ... غداة نطاع قد صدق القتالا)\n(كتيبته ململمة رداح ... إذا يرمونها تفني النبالا)\n(جزى الله الأغر يزيد خيرا ... ولقاه المسرة والجمالا)\n(بمأخذه ابن كلثوم بن عمرو ... يزيد الخير نازله نزالا)\n(بجمع من بني قران صيد ... يجيلون الطعان إذا أجالا)\n(يزيد يقدم السفراء حتى ... يروي صدرها الأسل النهالا)\nخبرني علي بن سليمان قال أخبرنا الأحول عن ابن الأعرابي قال زعموا أن بني تغلب حاربوا المنذر بن ماء السماء فلحقوا بالشأم خوفا منه فمر بهم عمرو بن أبي حجر الغساني فتلقاه عمرو بن كلثوم فقال له يا عمرو ما منع قومك أن يتلقوني فقال له يا عمرو يا خير الفتيان فإن قومي لم يستيقظوا لحرب قط إلا علا فيها أمرهم واشتد شأنهم ومنعوا ما وراء ظهورهم فقال له أيقاظ نومة ليس فيها حلم أجتث فيها أصولهم وأنفى فلهم إلى اليابس الجرد والنازح الثمد فانصرف عمرو بن كلثوم وهو يقول\n(ألا فاعلم أبيت اللعن أنا ... على عمد سنأتي ما نريد)\n(تعلم أن محملنا ثقيل ... وأن زناد كبتنا شديد)\n(وأنا ليس حي من معد ... يوازينا إذا لبس الحديد)","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":1,"spl":"شعراء تغلب يفخرون بقتله عمرو بن هند — أسره يزيد بن عمرو ثم أطلقه فمدحه","loc":1998},
{"id":"b115-5","bab":"الجزء 11","sec":"هجا النعمان بن المنذر","page":"ج11 ص60","text":"قال وقال ابن الأعرابي بلغ عمرو بن كلثوم أن النعمان بن المنذر يتوعده فدعا كاتبا من العرب فكتب إليه\n(ألا أبلغ النعمان عني رسالة ... فمدحك حولي وذمك قارح)\n(متى تلقني في تغلب ابنةوائل ... وأشياعها ترقى إليك المسالح)\nهجا النعمان بن المنذر هجاء كثيرا منه قوله يعيره بأمه سليمى\n(حلت سليمى بخبت بعد فرتاج ... وقد تكون قديما في بني ناج)\n(إذ لا ترجي سليمى أن يكون لها ... من بالخورنق من قين ونساج)\n(ولا يكون على أبوابها حرس ... كما تلفف قبطي بديباج)\n(تمشي بعدلين من لؤم ومنقصة ... مشي المقيد في الينبوت والحاج)\nال وقال في النعمان\n(لحا الله أدنانا إلى اللؤم زلفة ... وألأمنا خالا وأعجزنا أبا)\n(وأجدرنا أن ينفخ الكير خاله ... يصوغ القروط والشنوف بيثربا)\nخبرني الحسين بن علي قال حدثنا أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار قال حدثني علي بن المغيرة عن ابن الكلبي عن رجل من النمر بن قاسط قال\nلما حضرت عمرو بن كلثوم الوفاة وقد أتت عليه خمسون ومائة سنة جمع بنيه فقال يا بني قد بلغت من العمر مالم يبلغه أحد من آبائي ولا بد أن ينزل بي ما نزل بهم من الموت وإني والله ما عيرت أحدا بشيء إلا عيرت بمثله إن كان حقا فحقا وإن كان باطلا فباطلا ومن سب سب فكفوا عن الشتم فإنه أسلم لكم وأحسنوا جواركم يحسن ثناؤكم وامنعوا من ضيم الغريب فرب رجل خير من ألف ورد خير من خلف وإذا حدثتم فعوا وإذا حدثتم فأوجزوا فإن مع الإكثار تكون الأهذار وأشجع القوم العطوف بعد الكر كما أن أكرم المنايا القتل ولا خير فيمن لا روية له عند الغضب ولا من إذا عوتب لم يعتب ومن الناس من لا يرجى خيره ولا يخاف شره فبكؤه خير من دره وعقوقه خير من بره ولا تتزوجوا في حيكم فإنه يؤدي إلى قبيح البغض\n(لمن الديار ببرقة الروحان ... إذ لا نبيع زماننا بزمان)\n(صدع الغواني إذ رمين فؤاده ... صدع الزجاجة ما لذاك تداني)\n(إن زرت أهلك لم أنول حاجة ... وإذا هجرتك شفني هجراني)\nالشعر لجرير يهجو الأخطل ويرد عليه حكومته التي حكم بها للفرزدق عليه والغناء فيما ذكره علي بن يحيى المنجم في كتابه الذي لقبه بالمحدث لمعبد ثقيل أول بالوسطى وذكر الهشامي أنه لحنين قال\nويقال إنه لمعبد وفيه ليزيد حوراء لحن ذكره عبد الملك بن موسى عنه وقال لا أدري أهو الثقيل الأول أم خفيف الرمل وذكر حبش أن الثقيل الأول للغريض وأن خفيف الرمل بالبنصر للدلال","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":2,"spl":"هجا النعمان بن المنذر","song":1,"loc":1999},
{"id":"b115-6","bab":"الجزء 11","sec":"ذكر الخبر عن السبب في اتصال الهجاء بين جرير والأخطل سبب النقائض بين جرير والأخطل","page":"ج11 ص64","text":"أخبرني علي بن سليمان الأخفش ومحمد بن العباس اليزيدي قالا حدثنا أبو سعيد السكري عن محمد بن حبيب عن أبي عبيدة وعن أبي غسان دماذ عن أبي عبيدة وأخبرني محمد بن يحيى قال حدثنا أبو ذكوان القاسم بن إسماعيل قال حدثنا أبو غسان عن أبي عبيدة وأخبرنا الصولي عن إبراهيم بن المعلى الباهلي عن الطوسي عن ابن الأعرابي وأبي عمرو الشيباني وقد جمعت رواياتهم قال أبو عبيدة حدثني عامر بن مالك المسمعي قال كان الذي هاج التهاجي بين جرير والأخطل أنه لما بلغ الأخطل تهاجي جرير والفرزدق قال لابنه مالك وهو أكبر ولده وبه كان يكنى انحدر إلى العراق حتى تسمع منهما وتأتيني بخبرهما فانحدر مالك حتى لقيهما وسمع منهما ثم أتى أباه فقال له كيف وجدتهما قال وجدت جريرا يغرف من بحر ووجدت الفرزدق ينحت من صخر فقال الأخطل الذي يغرف من بحر أشعرهما وقال يفضل جريرا على الفرزدق\n(إني قضيت قضاء غير ذي جنف ... لما سمعت ولما جاءني الخبر)\n(أن الفرزدق قد شالت نعامته ... وعضه حية من قومه ذكر)\nوفي رواية ابن الأعرابي قد سال الفرات به قال أبو عبيدة ثم إن بشر بن مروان دخل الكوفة فقدم عليه الأخطل فبعث إليه محمد بن عمير بن عطارد بن حاجب بن زرارة بألف درهم وكسوة وبغلة وخمر وقال له لا تعن علي شاعرنا واهج هذا الكلب الذي يهجو بني دارم فإنك قد قضيت على صاحبنا فقل أبياتا واقض لصاحبنا عليه فقال الأخطل\n(أجرير إنك والذي تسمو له ... كأسيفة فخرت بحدج حصان)\n(عملت لربتها فلما عوليت ... نسلت تعارضها مع الركبان)\n(أتعد مأثرة لغيرك فخرها ... وثناؤها في سالف الأزمان)\n(تاج الملوك وفخرهم في دارم ... أيام يربوع من الرعيان)\nهي طويلة يقول فيها\n(فاخسأ إليك كليب أن مجاشعا ... وأبا الفوارس نهشلا أخوان)\n(سبقوا أباك بكل أعلى تلعة ... في المجد عند مواقف الركبان)\n(قوم إذا خطرت عليك قرومهم ... ألقتك بين كلاكل وجران)\n(وإذا وضعت أباك في ميزانهم ... رجحوا وشال أبوك في الميزان)\nقال جرير يرد حكومة الأخطل\n(لمن الديار ببرقة الروحان ... إذ لا نبيع زماننا بزمان)\nهي طويلة يقول فيها\n(يا ذا الغباوة إن بشرا قد قضى ... ألا تجوز حكومة النشوان)\n(فدعوا الحكومة لستم من أهلها ... إن الحكومة في بني شيبان)\n(قتلوا كليبكم بلقحة جارهم ... يا خزرتغلب لستم بهجان)\nمما غني فيه من نقائض جرير والأخطل\n(أناخوا فجروا شاصيات كأنها ... رجال من السودان لم يتسربلوا)\n(فقلت اصبحوني لا أبا لأبيكم ... وما وضعوا الأثقال إلا ليفعلوا)\n(تمر بها الأيدي سنيحا وبارحا ... وترفع باللهم حي وتنزل)\nلشاصيات الشائلات القوائم من امتلائها وعنى بالشاصيات ها هنا الزقاق لأنها إذا امتلأت شالت أكارعها يقال شصا برجله إذا رفعها وشصا ببصره إذا شخص قال الراجز يصف الشاخص\n(وبقر خماص ... ينظرن من خصاص)\n(بأعين شواصي ... كفلق الرصاص)\nوالسانح والسنيح ما جاء عن يمينك يريد شمالك والبارح ما جاء عن شمالك يريد يمينك والجابه ما جاء من أمامك مواجها لك والقعيد والخفيف ما جاء من ورائك شبه دور الكأس واختلافها بينهم بالسوانح والبوارح الشعر للأخطل والغناء لمالك فيه لحنان كلاهما له أحدهما رمل بالبنصر في مجراها في الأبيات الثلاثة على الولاء من رواية إسحاق والآخر خفيف رمل بالوسطى في الثالث ثم الأول والثاني عن عمرو وذكر عمرو أن الرمل أيضا لابن سريج وأنه بالوسطى وفيه لإبراهيم رمل بالبنصر في الأول والثاني عن الهشامي وعمرو وفيه لابن محرز خفيف ثقيل أول بالبنصر عن عمرو والهشامي ومنها\n(خف القطين فراحوا منك أو بكروا ... وأزعجتهم نوى في صرفها غير)\n(كأنني شارب يوم استبد بهم ... من قرقف ضمنتها حمص أو جدر)\n(جادت بها من ذوات القار مترعة ... كلفاء ينحت من خرطومها المدر)\n(يا قاتل الله وصل الغانيات إذا ... أيقن أنك ممن قد زها الكبر)\n(أعرضن لما حنى قوسي موترها ... وابيض بعد سواد اللمة الشعر)\nاستبد بهم أي علي عليهم والقرقف التي تأخذ شاربها رعدة لشدتها والكلفاء الخابية في لونها كلف وقوله زها الكبر يعني استخفه وأضعفه يقال زهاه وازدهاه وقال أبو عبيدة الأصل في زهاه رفعه فكأنه أراد أنه رفعه في علو سنه عما يردن منه واللمة الشعر المجتمع الشعر للأخطل يمدح عبد الملك بن مروان ويهجو قيسا وبني كليب ويقول فيها","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":3,"spl":"ذكر الخبر عن السبب في اتصال الهجاء بين جرير والأخطل سبب النقائض بين جرير والأخطل","song":2,"loc":2000},
{"id":"b115-7","bab":"الجزء 11","sec":"ذكر الخبر عن السبب في اتصال الهجاء بين جرير والأخطل سبب النقائض بين جرير والأخطل","page":"ج11 ص64","text":"(أما كليب بن يربوع فليس لها ... عند التفاخر إيراد ولا صدر)\n(مخلفون ويقضي الناس أمرهم ... وهم بغيب وفي عمياء ما شعروا)\n(ملطمون بأعقار الحياض فما ... ينفك من دارمي فيهم أثر)\n(بئس الصحاة وبئس الشرب شربهم ... إذا جرى فيهم المزاء والسكر)\n(قوم تناهت إليهم كل مخزية ... وكل فاحشة سبت بها مضر)\n(الآكلون خبيث الزاد وحدهم ... والسائلون بظهر الغيب ما الخبر)\nهذه القصيدة من فاخر شعر الأخطل ومقدمه ومما غلب فيه علىجرير وقد احتاج جرير إلى سلخ بيته هذا الأخير فرده عليه بعينه في نقيضة هذه القصيدة وضمنه بيتين من شعره فقال\n(الآكلون خبيث الزاد وحدهم ... والنازلون إذا واراهم الخمر)\n(والظاعنون على العمياء إن رحلوا ... والسائلون بظهر الغيب ما الخبر)\nفي هذه القصيدة يقول الأخطل يمدح عبد الملك\n(إلى امرىء لا تعرينا نوافله ... أظفره الله فليهنىء له الظفر)\n(الخائض الغمر والميمون طائره ... خليفة الله يستسقى به المطر)\n(والهم بعد نجي النفس يبعثه ... بالحزم والأصمعان القلب والحذر)\n(وما الفرات إذا جاشت غواربه ... في حافتيه وفي أوساطه العشر)\n(وزعزعته رياح الصيف واضطربت ... فوق الجآجىء من آذيه غدر)\n(مسحنفر من جبال الروم يستره ... منها أكافيف فيها دونه زور)\n(يوما بأجود منه حين تسأله ... ولا بأجهر منه حين يجتهر)\n(في نبعة من قريش يعصبون بها ... ما إن يوازى بأعلى نبتها الشجر)\n(حشد على الخير عيافو الخنا أنف ... إذا ألمت بهم مكروهة صبروا)\n(لا يستقل ذوو الأضغان حربهم ... ولا يبين في عيدانهم خور)\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":4,"spl":"ذكر الخبر عن السبب في اتصال الهجاء بين جرير والأخطل سبب النقائض بين جرير والأخطل — الرشيد ","loc":2001},
{"id":"b115-8","bab":"الجزء 11","sec":"الرشيد وآدم بن عمر يمدحان شعر الأخطل","page":"ج11 ص70","text":"أخبرنا الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثنا علي بن الصباح عن أبيه أن الرشيد قال لجماعة من أهله وجلسائه أي بيت مدح به الخلفاء منا ومن بني أمية أفخر فقالوا وأكثروا فقال الرشيد أمدح بيت وأفخره قول ابن النصرانية في عبد الملك\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)\nخبرني الحسن قال حدثنا ابن مهرويه قال حدثني أحمد بن الحارث عن المدائني قال قال المهدي يوما وبين يديه مروان بن أبي حفصة أين ما تقوله فينا من قولك في أمير المؤمنين المنصور\n(له لحظات عن حفافي سريره ... إذا كرها فيها عقاب ونائل)\nاعترضه آدم بن عمر بن عبد العزيز فقال هيهات والله يا أمير المؤمنين أن يقول هذا ولا ابن هرمة كما قال الأخطل\n(شمس العداوة حتى يستقاد لهم ... وأعظم الناس أحلاما إذا قدروا)\nال فغضب المهدي حتى استشاط وقال كذب والله ابن النصرانية العاض بظر أمه وكذبت يا عاض بظر أمك والله لولا أن يقال إني خفرت بك لعرفتك من أكثر شعرا خذوا برجل ابن الفاعلة فأخرجوه عني فأخرجوه على تلك الحال وجعل يشتمه وهو يجر ويقول يا بن الفاعلة أراها في رؤوسكم وأنفسكم\n(إني أرقت ولم يأرق معي صاح ... لمستكف بعيد النوم لواح)\n(دان مسف فويق الأرض هيدبه ... يكاد يدفعه من قام بالراح)\nروضه من البسيط الشعر لأوس بن حجر وهكذا رواه الأصمعي أخبرنا بذلك اليزيدي عن الرياشي عنه ووافقه بعض الكوفيين وغير هؤلاء يرويه لعبيد بن الأبرص والغناء لإبراهيم الموصلي ثقيل أول بإطلاق الوتر في مجرى الوسطى ولحسين بن محرز لحن في البيت الثاني وبعده\n(إن أشرب الخمر أو أغلى بها ثمنا ... فلا محالة يوما أنني صاح)\nطريقته خفيف رمل بالوسطى قوله مستكف يعني مستديرا وكل طرة كفة أخبرنا محمد بن\nالعباس اليزيدي قال حدثنا الرياشي قال حدثنا الأصمعي قال سمعت أبا مهدي يقول وهو يصف شجاعا عرض له في طريقه تبعني شجاع من هذه الشجعان فمر خلفي كأنه سهم زالج فحدت عنه واستكف كأنه كفة حابل فرميته فنظرت ثلاثة أثنائه وكذلك يقال كفة الحابل وكفة الميزان بالكسر والأولى مضمومة ولواح من قولهم لاح يلوح إذا ظهر ومسف قد أسف على وجه الأرض إذا صار عليها أو قرب منها أو دنا إليها ومن هذا يقال أسف الطائر إذا طار على وجه الأرض ويقال ذلك للسهم أيضا وهيدبه الذي تراه كالمتعلق بالسحاب يقول هذا السحاب يكاد من قام أن يمسه ويدفعه براحته لقربه من الأرض وهو أحسن ما وصف به السحاب","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":4,"spl":"ذكر الخبر عن السبب في اتصال الهجاء بين جرير والأخطل سبب النقائض بين جرير والأخطل — الرشيد ","song":1,"loc":2002},
{"id":"b115-9","bab":"الجزء 11","sec":"ذكر أوس بن حجر وشيء من أخباره","page":"ج11 ص73","text":"وقد اختلف في نسبه فقال الأصمعي فيما أخبرنا به محمد بن العباس اليزيدي عن الرياشي عنه هو أوس بن حجر بن مالك بن حزن بن عقيل بن خلف بن نمير وقال ابن حبيب فيما ذكره السكري عنه هو أوس بن حجر من شعراء الجاهلية وفحولها وذكر أبو عبيدة أنه من الطبقة الثالثة وقرنه بالحطيئة ونابغة بني جعدة فأخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال قال أبو عبيدة حدثنا يونس عن أبي عمرو قال كان أوس شاعر مضر حتى أسقطه النابغة وزهير فهو شاعر تميم في الجاهلية غير مدافع أخبرنا أحمد قال حدثنا عمر قال حدثنا الأصمعي قال سمعت أبا عمرو يقول كان أوس بن حجر فحل الشعراء فلما نشأ النابغة طأطأ منه وأما الكلبي فإنه زعم أن من هذه الطبقة لبيد بن ربيعة والشماخ بن ضرار\nقال وتميم إلى الآن مقيمة على تقديم أوس قال ومنهم من يقول بتقديم عدي وأنشد لحارثة بن بدر الغداني\n(والشعر كان مبيته ومظله ... عند العبادي الذي لا يجهل)\nقال يعقوب بن سليمان قال حماد أدركت رجالا من بني تميم لا يفضلون على عدي في الشعر أحدا أخبرني اليزيدي عن الرياشي عن الأصمعي قال تميم تروي هذه القصيدة الحائية لعبيد وذلك غلط ومن الناس من يخلطها بقصيدته التي على وزنها ورويها لتشابههما أخبرني علي بن سليمان الأخفش قال أخبرنا أبو سعيد السكري قال حدثنا علي بن الصباح قال حدثني عبيد الله بن الحسين بن المسود بن وردان مولى رسول الله قال خرج أعرابي مكفوف ومعه ابنة عم له لرعي غنم لهما فقال الشيخ أجد ريح النسيم قد دنا فارفعي رأسك فأنظري فقالت أراها كأنها ربرب معزى هزلى قال ارعي واحذري ثم قال لها بعد ساعة إني أجد ريح النسيم قد دنا فارفعي رأسك فانظري قالت أراها كأنها بغال دهم تجر جلالها قال ارعي واحذري ثم مكث ساعة ثم قال إني لأجد ريح النسيم قد دنا فانظري قالت أراها كأنها بطن حمار أصحر فقال ارعي واحذري ثم مكث ساعة فقال إني لأجد ريح النسيم فما ترين قالت أراها كما قال الشاعر\n(دان مسف فويق الأرض هيدبه ... يكاد يدفعه من قام بالراح)\n(كأنما بين أعلاه وأسفله ... ريط منشرة أو ضوء مصباح)\n(فمن بمحفله كمن بنجوته ... والمستكن كمن يمشي بقرواح)\nقال انجي لا أبالك فما انقضىكلامه حتى هطلت السماء عليهما البيت الثاني من هذه الأبيات ليس من رواية ابن حبيب ولا الأصمعي معنى قول الجارية كأنها بطن حمار أصحر تعني أنه أبيض فيه حمرة والصحرة لون كذلك وقوله\n(فمن بمحفله كمن بنجوته ... )\nيعني من هو بحيث احتفل السيل واحتفال كل شيء معظمه كمن في نجوته وقد روي بمحفشه وهما واحد ومعناهما مجرى معظم السيل يقول فمن هو في هذا الموضع منه كمن بنجوته أي ناحية عنه سواء لكثرة المطر والقرواح الفضاء يقال قرواح وقرياح ويقال في معنى المحفش حفشت الأودية إذا سالت وتحفشت المرأة على ولدها إذا قامت عليه أخبرني علي بن سليمان الأخفش قال حدثني علي بن أبي عامر السهمي المصري قال حدثني أبو يوسف الأصبهاني قال حدثني أبو محمد الباهلي عن الأصمعي وذكر هذا الخبر أيضا التوزي عن أبي عبيدة فجمعت روايتيهما قالا","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":5,"spl":"ذكر أوس بن حجر وشيء من أخباره","loc":2003,"partial":1},
{"id":"b115-10","bab":"الجزء 11","sec":"مدح فضالة بن كلدة لأنه أكرمه بعد أن صرعته ناقته","page":"ج11 ص75","text":"كان أوس بن حجر غزلا مغرما بالنساء فخرج في سفر حتى إذا كان\nبأرض بني أسد بين شرج وناظرة فبينا هو يسير ظلاما إذا جالت به ناقته فصرعته فاندقت فخذاه فبات مكانه حتى إذا أصبح غدا جواري الحي يجتنين الكمأة وغيرها من نبات الأرض والناس في ربيع فبينا هن كذلك إذ بصرن بناقته تجول وقد علق زمامها في شجرة وأبصرنه ملقى ففزعن فهربن فدعا بجارية منهن فقال لها من أنت قالت أنا حليمة بنت فضالة بن كلدة وكانت أصغرهن فأعطاها حجرا وقال لها اذهبي إلى أبيك فقولي له ابن هذا يقرئك السلام فأخبرته فقال يا بنية لقد أتيت أباك بمدح طويل أو هجاء طويل ثم احتمل هو وأهله حتى بنى عليه بيته حيث صرع وقال والله لا أتحول أبدا حتى تبرأ وكانت حليمة تقوم عليه حتى استقل فقال أوس بن حجر في ذلك\n(جدلت على ليلة ساهره ... بصحراء شرج إلى ناظره)\n(تزاد ليالي في طولها ... فليست بطلق ولا ساكره)\n(أنوء برجل بها ذهنها ... وأعيت بها أخثها الغابره)\nقال في حليمة\n(لعمرك ما ملت ثواء ثويها ... حليمة إذ ألقى مراسي مقعد)\n(ولكن تلقت باليدين ضمانتي ... وحل بشرج م القبائل عودي)\n(ولم تلهها تلك التكاليف إنها ... كما شئت من أكرومة وتخرد)\n(سأجزيك أو يجزيك عني مثوب ... وقصرك أن يثنى عليك وتحمدي)","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":6,"spl":"مدح فضالة بن كلدة لأنه أكرمه بعد أن صرعته ناقته — رثاؤه فضالة حين مات","loc":2004},
{"id":"b115-11","bab":"الجزء 11","sec":"رثاؤه فضالة حين مات","page":"ج11 ص77","text":"قالا ثم مات فضالة بن كلدة وكان يكنى أبا دليجة فقال فيه أوس بن حجر يرثيه\n(يا عين لا بد من سكب وتهمال ... على فضالة جل الرزء والعالي)\nيروى عيني العالي الأمر العظيم الغالب وهي طويلة جدا وفيها مما يغنى فيه\n(أبا دليجة من توصي بأرملة ... أم من لأشعث ذي طمرين ممحال)\n(أبا دليجة من يكفي العشيرة إذ ... أمسوا من الأمر في لبس وبلبال)\n(لا زال مسك وريحان له أرج ... على صداك بصافي اللون سلسال)\nنى فيه دحمان خفيف رمل بالوسطى عن عمرو وذكر حبش أن فيه لابن عائشة رملا بالوسطى عن عمرو وذكر حبش أن فيه لابن عائشة رملا\nبالبنصر ولداود بن العباس ثاني ثقيل ولابن جامع خفيف ثقيل ومن فاضل مراثيه إياه ونادرها قوله\n(أيتها النفس أجملي جزعا ... إن الذي تكرهين قد وقعا)\n(إن الذي جمع السماحة والنجدة ... والحزم والقوى جمعا)\n(المخلف المتلف المرزأ لم ... يمتع بضعف ولم يمت طبعا)\n(أودى وهل تنفع الإشاحة من ... شيء لمن قد يحاول البدعا)\nهي قصيدة أيضا يمدحه بها في حياته ويرثيه بعد وفاته وله فيه قصائد غير هذه\n(رأيت زهيرا تحت كلكل خالد ... فأقبلت أسعى كالعجول أبادر)\n(فشلت يميني يوم أضرب خالدا ... ويمنعه مني الحديد المظاهر)\nروضه من الطويل الشعر لورقاء بن زهير والغناء لكردم خفيف ثقيل أول بالوسطى في مجراها عن إسحاق وذكر عمرو بن بانة أنه لمعبد وذكر إسحاق أنه ينسبه إلى معبد من لا يعلم وروى عن أبيه عن سياط عن يونس أنه أخذه من كردم وأعلمه أن الصنعة فيه له","topic":"نسب عمرو بن كلثوم وخبره","topicNo":115,"sp":6,"spl":"مدح فضالة بن كلدة لأنه أكرمه بعد أن صرعته ناقته — رثاؤه فضالة حين مات","song":2,"loc":2005},
{"id":"b116-1","bab":"الجزء 11","sec":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","page":"ج11 ص79","text":"هو ورقاء بن زهير بن جذيمة بن رواحة بن ربيعة بن مازن بن الحارث بن قطيعة بن عبس بن بغيض بن ريث بن غطفان يقوله لما قتل خالد بن جعفر بن كلاب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة أباه زهير بن جذيمة وكان السبب في ذلك فيما أخبرني به أحمد بن عبد العزيز الجوهري وحبيب بن نصر قالا حدثنا عمر بن شبة ونسخت بعض هذا الخبر عن الأثرم ورواية ابن الكلبي وأضفت بعض الروايات إلى بعض إلا ما أفردته وجلبته عن راويه قال أبو عبيدة حدثني عبد الحميد بن عبد الواحد بن عاصم بن عبد الله بن رافع بن مالك بن عبد بن جلهمة بن حداق بن يربوع بن سعد بن تغلب بن عوف بن جلان بن غنم بن أعصر قال حدثني أبي عبد الواحد وعمي صفوان ابنا عاصم عن أبيهما عاصم بن عبد الله عمن أدرك شأس بن زهير قال كان مولد عاصم قبل مبعث النبي وكان عاصم جاهليا قال قال وعبد الحميد حدثني سيار بن عمرو أحد بني عبيد بن سعد بن عوف بن جلان بن غنم قال أبو عبيدة وكان أعلم غني عن شيوخهم","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":0,"spl":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","loc":2006},
{"id":"b116-2","bab":"الجزء 11","sec":"مقتل أخيه شأس ومحاولة الثأر من قاتله","page":"ج11 ص80","text":"أن شأس بن زهير بن جذيمة أقبل من عند ملك قال أبو عبيدة أراه النعمان وكان بينه وبين زهير صهر قال أبو عبيدة ثم حدثني مرة أخرى قال كانت ابنة زهير عنده فأقبل شأس بن زهير من عنده وقد حباه أفضل الحبوة مسكا وكسا وقطفا وطنافس فأناخ ناقته في يوم شمال وقر على ردهة في جبل ورياح بن الأسك أحد بني رباع بن عبيد بن سعد بن عوف بن جلان على الردهة ليس غير بيته بالجبل فأنشأ شأس يغتسل بين الناقة والبيت فاستدبره رياح فأهوى له بسهم فبتر به صلبه قال أبو عبيدة وحدثني رجل يخيل إلي أنه أبو يحيى الغنوي قال ورد شأس وقد حباه الملك بحبوة فيها قطيفة حمراء ذات هدب وطيب فورد منعجا وعليه خباء ملقى لرياح بن الأسك فيه أهله في الظهيرة فألقى ثيابه بفنائه ثم قعد يهريق عليه الماء والمرأة قريبة منه يعني امرأة رياح فإذا هو مثل الثور الأبيض فقال رياح لامرأته أنطيني قوسي فمدت إليه قوسه وسهما وانتزعت المرأة نصله لئلا يقتله فأهوى عجلان إليه فوضع السهم في مستدق الصلب بين فقارتين ففصلهما وخر ساقطا وحفر له حفرا فهدمه عليه ونحر جمله وأكله قال وقال عبد الحميد أكل ركوبته وأولج متاعه بيته وقال عبد الحميد وفقد شأس وقص أثره ونشد وركبوا إلى الملك فسألوه عن حاله فقال لهم الملك حبوته وسرحته فقالوا وما متعته به قال مسك وكسا\nونطوع وقطف فأقبلوا يقصون أثره فلم تتضح لهم سبيله فمكثوا كذلك ما شاء الله لا أدري كم حتى رأوا أمرأة رياح باعت بعكاظ قطيفة حمراء أو بعض ما كان من حباء الملك فعرفت وتيقنوا أن رياحا ثأرهم قال أبو عبيدة وزعم الاخر قال نشد زهير بن جذيمة الناس فانقطع ذكره على منعج وسط غني ثم أصابت الناس جائحة وجوع فنحر زهير ناقة فأعطى أمرأة شطيها فقال اشتري لي الهدب والطيب فخرجت بذلك الشحم والسنام تبيعه حتى دفعت إلى امرأة رياح فقالت إن معي شحما أبيعه في الهدب والطيب فاشترت المرأة منها فأتت المرأة زهيرا بذلك فعرف الهدب فأتى زهير غنيا فقالوا نعم قتله رياح بن الأسك ونحن برءاء منه وقد لحق بخاله من بني الطماح وبني أسد بن خزيمة فكان يكون الليل عنده ويظهر في أبان إذا أحس الصبح يرمي الأروى إلى أن أصبح ذات يوم وهو عنده وعبس تريغه فركب خاله جملا وجعله على كفل وراءه فبينا هو كذلك إذ دنت فقالوا هذه خيل عبس تطلبك فطمر في قاع شجر فحفر في أصل\nسوقه ولقيت الخيل خاله فقالوا هل كان معك أحد قال لا فقالوا ما هذا المركب وراءك لتخبرنا أو لنقتلنك قال لا كذب هو رياح في ذلك القاع فلما دنوا منه قال الحصينان يا بني عبس دعونا وثأرنا فخنسوا عنهما فأخذ رياح نعلين من سبت فصيرهما على صدره حيال كبده ونادى هذا غزالكما الذي تبغيان فحمل عليه أحدهما فطعنه فأزالت النعل الرمح إلى حيث شاكلته ورماه رياح موليا فجذم صلبه قال ثم جاء الآخر فطعنه فلم يغن شيئا ورماه موليا فصرعه فقالت عبس أين تذهبون إلى هذا والله ليقتلن منكم عدد مراميه وقد جرحاه فسيموت قال وأخذ رياح رمحيهما وسلبيهما وخرج حتى سند إلى أبان فأتته عجوز وهو يستدمي على الحوض ليشرب منه وقالت استأسر تحي فقال جنبيني حتى أشرب قال فأبت ولم تنته فلما غلبته أخذ مشقصا وكنع به كرسوعي يديها قال فقال عبد الحميد فلما استبان لزهير بن جذيمة أن رياحا ثأره قال يرثي شأسا","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":1,"spl":"مقتل أخيه شأس ومحاولة الثأر من قاتله","loc":2007},
{"id":"b116-3","bab":"الجزء 11","sec":"قصيدة زهير بن جذيمة في رثاء ابنه شأس","page":"ج11 ص82","text":"(بكيت لشأس حين خبرت أنه ... بماء غني آخر الليل يسلب)\n(لقد كان مأتاه الرداه لحتفه ... وما كان لولا غرة الليل يغلب)\n(قتيل غني ليس شكل كشكله ... كذاك لعمري الحين للمرء يجلب)\n(سأبكي عليه إن بكيت بعبرة ... وحق لشأس عبرة حين تسكب)\n(وحزن عليه ما حييت وعولة ... على مثل ضوء البدر أو هو أعجب)\n(إذا سيم ضيما كان للضيم منكرا ... وكان لدى الهيجاء يخشى ويرهب)\n(وإن صوت الداعي إلى الخير مرة ... أجاب لما يدعو له حين يكرب)\n(ففرج عنه ثم كان وليه ... فقلبي عليه لو بدا القلب ملهب)\nوقال زهير بن جذيمة حين قتل شأس شأس وما شأس والبأس وما البأس لولا مقتل شأس لم يكن بيننا بأس قال ثم انصرف إلى قومه فكان لا يقدر على غنوي إلا قتله قال عبد الحميد فغزت بنو عبس غنيا قبل أن يطلبوا قودا أو دية مع أخي شأس الحصين بن زهير بن جذيمة والحصين بن أسيد بن جذيمة ابن أخي زهير فقيل ذلك لغني فقالت لرياح انج لعلنا نصالح على شيء أو نرضيهم بدية وفداء فخرج رياح رديفا لرجل من بني كلاب وزعم أبو حية النميري أنه من بني جعد وكان معهما صحيفة فيها آراب لحم لا يريان إلا أنهما قد خالفا وجهة القوم فأوجفا أيديهما في الصحيفة فأخذ كل واحد منهما وذرة ليأكلها مترادفين لا يقدران على النزول قال فمر فوق رؤوسهما صرد فصرصر فألقيا اللحم وأمسكا بأيديهما وقالا ما هذا ثم\nعادا إلى مثل ذلك فأخذ كل واحد منهما عظما ومر الصرد فوق رؤوسهما فصرصر فألقيا العظمين وأمسكا بأيديهما وقالا ما هذا ثم عادا الثالثة فأخذ كل واحد منهما قطعة فمر الصرد فوق رؤوسهما فصرصر فألقيا القطعتين حتى فعلا ذلك ثلاث مرات فاذا هما بالقوم أدنى ظلم وأدنى ظلم أي أدنى شيء وقد كانا يظنان أنهما قد خالفا وجهة القوم فقال صاحبه لرياح اذهب فإني آتي القوم أشاغلهم عنك وأحدثهم حتى تعجزهم ثم ماض إن تركوني فانحدر رياح عن عجز الجمل فأخذ أدراجه وعدا أثر الراحلة حتى أتى ضفة فاحتفر تحتها مثل مكان الأرنب فولج فيه ثم أخذ نعليه فجعل إحداهما على سرته والأخرى على صفنه ثم شد عليهما العمامة ومضى صاحبه حتى لقي القوم فسألوه فحدثهم وقال هذه غني كاملة وقد دنوت منهم فصدقوه وخلوا سربه فلما ولى رأوا مركب الرجل خلفه فقالوا من الذي كان خلفك فقال لا مكذبة ذلك رياح في الأول من السمرات فقال الحصينان لمن معهما قفوا علينا حتى نعلم علمه فقد أمكننا الله من ثأرنا ولم يريدا أن يشركهما فيه أحد فمضيا ووقف القوم عنهما قالوا قال رياح فاذا هما ينقلان فرسيهما فما زالا يريغاني فابتدراني فرميت الأول فبترت صلبه وطعنني الآخر قبل أن أرميه وأراد السرة فأصاب الربلة ومر الفرس يهوي به فاستدبرته بسهم فرشقت به صلبه فانفقر منحنى الأوصال وقد بترت صلبيهما قال أبو عبيدة قال أبو حية بل قال رياح استدبرته بسهم وقد خرجت قدمه فقطعتها فكأنما نشرت بمنشار قال عبد الحميد وند فرساهما\nفلحقا بالقوم قال رياح فأخذت رمحيهما فخرجت بهما حتى أتيت رملة فسندت فغرزت الرمحين فيها ثم انحدرت قال وطلبه القوم حتى إذا رفع لهم الرمحان لم يقربوهما علم الله حتى وجدوا أثر رياح خارجا قد فات وانطلق رياح خارجا حتى ورد ردهة عليها بيت أنمار بن بغيض وفيه امرأة ولها ابنان قريبان منها وجمل لها راتع في الجبل وقد مات رياح عطشا فلما رأته يستدمي طمعت فيه ورجت أن يأتيها ابناها فقالت له استأسر فقال لها دعيني ويحك أشرب فأبت فأخذ حديدة إما سكينا وإما مشقصا فجذم به رواهشها فماتت وعب في الماء حتى نهل ثم توجه إلى قومه فقال رياح فيها وفي الحصينين\n(قالت لي استأسر لتكتفني ... حينا ويعلو قولها قولي)\n(ولأنت أجرأ من أسامة أو ... مني غداة وقفت للخيل)\n(إذ الحصين لدى الحصين كما ... عدل الرجازة جانب الميل)\nال الأثرم الرجازة شيء يكون مع المرأة في هودجها فإذا مال أحد الجانبين وضعته في الناحية الأخرى ليعتدل قال أبو عبيدة يعني حصين بن زهير بن جذيمة وحصين بن أسيد بن جذيمة وهو ابن عمه قال أبو عبيدة قال عبد الحميد والله لقد سمعت هذا الحديث على ما حدثتك به منذ ستين سنة قال عبد الحميد وما سمعت أن بني عبس أدركوا بواحد منهم ولا اقتادوا ولا أنذروا ولا سمعت فيه من الشعر لنا ولا لغيرنا في الجاهلية بأكثر مما أنشدتك وإلى هذا انتهى حديثنا وحديثه ولا والله ما قتل خالد بن جعفر","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":2,"spl":"قصيدة زهير بن جذيمة في رثاء ابنه شأس","loc":2008},
{"id":"b116-4","bab":"الجزء 11","sec":"قصيدة زهير بن جذيمة في رثاء ابنه شأس","page":"ج11 ص82","text":"زهير بن جذيمة في حربنا غير أن الكميت بن زيد الأسدي وكانت له أمان من غني ذكر من مقتل أخواله من غني في بني عبس ومن قتلوا من بني نمير بن عامر في كلمة له واحدة فلعله لهذا الحديث قالها وذكر إدراكاتهم وذكر قتل شبيب بن سالم النميري فقال في ذلك\n(أنا ابن غني والداي كلاهما ... لأمين فيهم في الفروع وفي الأصل)\n(هم استودعوا هوى شبيب بن سالم ... وهم عدلوا بين الحصينين بالنبل)\n(وهم قتلوا شأس الملوك ورغموا ... أباه زهيرا بالمذلة والثكل)\n(فما أدركت فيهم جذيمة وترها ... بما قود يوما لديها ولا عقل)\nال أبو عبيدة فذكر عبد الحميد أنه أتى عليهم هنيئة من الدهر لا أدري كم وقت ذلك بعد انصرام أمر شأس قال فما زادوا على هذا فهو باطل قال الأثرم هنيئة من الدهر وهنيهة وبرهة وحقبة بمعنى الدهر","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":3,"spl":"قصيدة زهير بن جذيمة في رثاء ابنه شأس — مقتل زهير بن جذيمة العبسي","loc":2009},
{"id":"b116-5","bab":"الجزء 11","sec":"مقتل زهير بن جذيمة العبسي","page":"ج11 ص87","text":"قتله خالد بن جعفر بن كلاب قال أبو عبيدة قال أبو حية النميري كان بين انصراف حديث شأس وحديث قتل خالد بن جعفر زهير بن جذيمة ما بين العشرين سنة إلى الثلاثين سنة قال أبو عبيدة وهوازن بن منصور لا ترى زهير بن جذيمة إلا ربا قال وهوازن يومئذ لا خير فيها ولم تكثر عامر بن صعصعة بعد فهم أذل من يد في رحم وإنما هم رعاء الشاء في الجبال قال وكان زهير يعشرهم وكان إذا كان أيام عكاظ أتاها زهير ويأتيها الناس من كل وجه فتأتيه هوازن بالإتاوة التي كانت له في أعناقهم فيأتونه بالسمن والأقط والغنم وذلك بعد ما خلع ذلك من أبي الجناد أخي بني أسيد بن عمرو بن تميم ثم إذا تفرق الناس عن عكاظ نزل زهير بالنفرات قال أبو عبيدة عن عبد الحميد وأبي حية النميري قالا فأتته عجوز رهيش من بني نصر بن معاوية بن بكر بن هوازن وقال أبو حية بل أتته\nعجوز من هوازن بسمن في نحي واعتذرت إليه وشكت السنين التي تتابعن على الناس فذاقه فلم يرض طعمه فدعها بقوس في يده عطل في صدرها فاستلقت لحلاوة القفا فبدت عورتها فغضبت من ذلك هوازن وحقدت عليه إلى ما كان في صدرها من الغيظ والدمن وأوحرها من الحسك قال وقد أمرت عامر بن صعصعة يومئذ فآلى خالد بن جعفر فقال والله لأجعلن ذراعي وراء عنقه حتى أقتل أو يقتل قال وفي ذلك يقول خالد بن جعفر بن كلاب\n(أديروني إدارتكم فإني ... وحذفة كالشجا تحت الوريد)\n(مقربة أسويها بجزء ... وألحفها ردائي في الجليد)\n(وأوصي الراعيين ليؤثراها ... لها لبن الخلية والصعود)\n(تراها في الغزاة وهن شعث ... كقلب العاج في الرسغ الجديد)\n(يبيت رباطها بالليل كفي ... على عود الحشيش وغير عود)\n(لعل الله يمكنني عليها ... جهارا من زهير أو أسيد)\n(فإما تثقفوني فاقتلوني ... فمن أثقف فليس إلى خلود)\n(وقيس في المعارك غادرته ... قناتي في فوارس كالأسود)\n(ويربوع بن غيظ يوم ساق ... تركناهم كجارية وبيد)\n(تركت بها نساء بني عصيم ... أرامل ما تحن إلى وليد)\n(يلذن بحارث جزعا عليه ... يقلن لحارث لولا تسود)\n(ومني بالظويلم قارعات ... تبيد المخزيات ولا تبيد)\n(وحكت بركها ببني جحاش ... وقد أجروا إليها من بعيد)\n(تركت ابني جذيمة في مكر ... ونصرا قد تركت لها شهودي)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":3,"spl":"قصيدة زهير بن جذيمة في رثاء ابنه شأس — مقتل زهير بن جذيمة العبسي","loc":2010},
{"id":"b116-6","bab":"الجزء 11","sec":"قتله خالد بن جعفر وما كان قبل قتله","page":"ج11 ص89","text":"قال أبو عبيدة وحدثني أبو سرار الغنوي قال كان زهير رجلا عدوسا فانتقل من قومه ببنيه وبني أخويه زنباع وأسيد بركبة يريغ الغيث في عشراوات له وشول قال وبنو عامر قريب منهم ولا يشعر بهم قال عبد الحميد وأبو حية بل بنو عامر بدمخ وزهير بالنفرات وبينهم ليلتان أو ثلاث قال فقال أبو سرار فأتى الحارث بني عامر والله ما تغير\nطعم اللبن الذي زوده الحارث بن عمرو بن الشريد السلمي حتى أتى بني عامر فأخبرهم قال أبو عبيدة أخبرني سليمان بن المزاحم المازني عن أبيه قال بل كانت بنو عامر بالجريثة وزهير بالنفرات وكانت تماضر بنت عمرو ابن الشريد بن رياح بن يقظة بن عصية بن خفاف السلمي امرأة زهير بن جذيمة وهي أم ولده فمر بها أخوها الحارث بن عمرو فقال زهير لبنيه إن هذا الحمار لطليعة عليكم فأوثقوه فقالت أخته لبنيها أيزوركم خالكم فتوثقوه وتحرموه فخلوه فقالت تماضر لأخيها الحارث إنه ليريبني اكبئنانك وقروبك فلا يأخذن فيك ما قال زهير فإنه رجل بيذارة غيذارة شنؤة قال ثم حلبوا له وطبا وأخذوا منه يمينا ألا يخبر عنهم ولا ينذر بهم أحدا قال أبو عبيدة وزعم أبو حية النميري أنه لما أتوه بقراهم أراهم أنه يشربه في الظلمة وجعل يهوي به إلى جيبه فيصبه بين سرباله وصدره أسفا وغظيا قال وكان الذي حلب له الوطب وقراه الحارث بن زهير وبه سمي قال فخرج يطير حتى أتى عامرا عند ناديهم فأتى حاذة أو شجرة غيرها فألقى الوطب تحتها والقوم ينظرون ثم قال أيتها الشجرة الذليلة اشربي من هذا اللبن فانظري ما طعمه فقال أهل المجلس هذا رجل مأخوذ عليه عهد وهو يخبركم خبرا فأتوه فإذا هو الحارث بن عمرو وذاقوا اللبن فإذا هو حلو لم يقرص بعد فقالوا إنه ليخبرنا أن طلبنا قريب فركب معه ستة\nفوارس لينظروا ما الخبر وهم خالد بن جعفر بن كلاب على حذفة وحندج بن البكاء ومعاوية بن عبادة بن عقيل فارس الهرار وهو الأخيل جد ليلى الأخيلية قال والأخيل هو معاوية قال وهو يومئذ غلام له ذؤابتان وكان أصغر من ركب وثلاثة فوارس من سائر بني عامر فاقتصوا أثر السير حتى إذا رأوا إبل بني جذيمة نزلوا عن الخيل فقالت النساء إنا لنرى حرجة من عضاه أو غابة رماح بمكان لم نكن نرى به شيئا ثم راحت الرعاء فأخبروا بمثل ما للنساء قال وأخبرت راعية أسيد بن جذيمة أسيدا بمثل ذلك فأتى أسيد أخاه زهيرا فأخبره بما أخبرته به الراعية وقال إنما رأت خيل بني عامر ورماحها فقال زهير كل أزب نفور فذهبت مثلا وكان أسيد كثير الشعر خناسيا وأين بنو عامر أما بنو كلاب فكالحية إن تركتها تركتك وإن وطئتها عضتك وأما بنو كعب يصيدون اللأي يريد الثور الوحشي وأما بنو نمير فإنهم يرعون إبلهم في رؤوس الجبال وأما بنو هلال فيبيعون العطر قال فتحمل عامة بني رواحة وآلي زهير لا يبرح مكانه حتى يصبح وتحمل من كان معه غير ابنيه ورقاء والحارث قال وكان لزهير ربيئة من الجن فحدثه ببعض أمرهم حتى أصبح وكانت له مظلة دوح يربط فيها أفراسه لا تريمه حذرا من الحوادث قال فلما أصبح صهلت فرس منها حين أحست بالخيل وهي القعساء فقال زهير ما لها فقال ربيئته\n(أحست الخيل فصهلت إليهن ... فلم تؤذنهم بهم إلا والخيل دوائس)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":4,"spl":"قتله خالد بن جعفر وما كان قبل قتله","loc":2011},
{"id":"b116-7","bab":"الجزء 11","sec":"قتله خالد بن جعفر وما كان قبل قتله","page":"ج11 ص89","text":"محاضير بالقوم غدية فقال زهير وظن أنهم أهل اليمن يا أسيد ما هؤلاء فقال هؤلاء الذين تعمي حديثهم منذ الليلة قال وركب أسيد فمضى ناجيا قال ووثب زهير وكان شيخا نبيلا فتدثر القعساء فرسه وهو يومئذ شيخ قد بدن وهو يومئذ عقوق متهم واعرورى ورقاء والحارث ابناه فرسيهما ثم خالفوا جهة مالهم ليعموا على بني عامر مكان مالهم فلا يأخذوه فهتف هاتف من بني عامر ياليحامر يريد يحامر وهو شعار لأهل اليمن لأن يعمي على الجذميين من القوم فقال زهير هذه اليمن قد علمت أنها أهل اليمن وقال لابنه ورقاء انظر يا ورقاء ما ترى قال ورقاء أرى فارسا على شقراء يجهدها ويكدها بالسوط قد ألح عليها يعني خالدا فقال زهير شيئا ما يريد السوط الى الشقراء فذهبت مثلا وقال في المرة الثانية شيئا ما يطلب السوط الى الشقراء وهي حذفة فرس خالد بن جعفر والفارس خالد بن جعفر قال وكانت الشقراء من خيل غني قال وتمردت القعساء بزهير وجعل خالد يقول لا نجوت إن نجا مجدع يعني زهيرا فلما تمعطت القعساء بزهير ولم تتعلق بها حذفة قال خالد لمعاوية الأخيل بن عبادة وكان على الهرار حصان أعوج أدرك معاوي فأدرك معاوية زهيرا وجعل ابناه ورقاء والحارث يوطشان عنه أي عن أبيهما قال فقال خالد اطعن يا معاوية\nفي نساها فطعن في أحدى رجليها فانخذلت القعساء بعض الانخذال وهي في ذلك تمعط فقال زهير اطعن الأخرى يكيده بذلك لكي تستوي رجلاها فتحامل فناداه خالد يا معاوية أفذ طعنتك أي اطعن مكانا واحدا فشعشع الرمح في رجلها فانخذلت قال ولحقه خالد على حذفة فجعل يده وراء عنق زهير فاستخف به عن الفرس حتى قلبه وخر خالد فوقع فوقه ورفع المغفر عن رأس زهير وقال يا لعامر اقتلونا معا فعرفوا أنهم بنو عامر فقال ورقاء وا أنقطاع ظهراه إنها لبنو عامر سائر اليوم وقال غيره فقال بعض بني جذيمة وا انقطاع ظهري قال ولحق حندج بن البكاء وقد حسر خالد المغفر عن رأس زهير فقال نح رأسك يا أبا جزء لم يحن يومك قال فنحى خالد رأسه وضرب حندج رأس زهير وضرب ورقاء بن زهير رأس خالد بالسيف وعليه درعان وكان أسجر العينين أزب أقمر مثل الفالج فلم يغن شيئا قال وأجهض ابنا زهير القوم عن زهير فانتزعاه مرتثا فقال خالد حين استنقذ زهيرا ابناه والهفتاه قد كنت أظن أن هذا المخرج سيسعكم ولام حندجا فقال حندج وكان لجلالته غصة إذا تكلم السيف حديد والساعد شديد وقد ضربته ورجلاي متمكنتان في الركابين وسمعت السيف قال قب حين وقع برأسه ورأيت على ظبته مثل ثمر المرار وذقته فكان حلوا فقال خالد قتلته بأبي أنت ونظر بنو زهير فإذا الضربة قد بلغت الدماغ ونهي بنو زهير أن يسقوا أباهم الماء فاستسقاهم فمنعوه حتى\nنهك عطشا قال وذلك أن المأموم يخاف عليه الماء حتى بلغ منه العطش فجعل يهتف أميت أنا عطشا وينادي يا ورقاء قال أبو حية فجعل ينادي يا شأس فلما رأوا ذلك سقوه فمات لثالثة فقال ورقاء بن زهير","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":5,"spl":"قتله خالد بن جعفر وما كان قبل قتله","loc":2012},
{"id":"b116-8","bab":"الجزء 11","sec":"شعر ورقاء بن زهير حين قتل والده","page":"ج11 ص94","text":"(رأيت زهيرا تحت كلكل خالد ... فأقبلت أسعى كالعجول أبادر)\n(إلى بطلين ينهضان كلاهما ... يريغان نصل السيف والسيف نادر)\n(فشلت يميني إذ ضربت ابن جعفر ... وأحرزه مني الحديد المظاهر)\nال أبو عبيدة وسمعت أبا عمرو بن العلاء ينشد هذا البيت فيها\n(وشلت يميني يوم أضرب خالدا ... وشل بناناها وشل الخناصر)\nال أبو عبيدة وأنشدني أبو سرار أيضا فيها\n(فياليتني من قبل أيام خالد ... ويوم زهير لم تلدني تماضر)\nماضر بنت عمرو بن الشريد بن رياح بن يقظة بن عصية بن خفاف السلمي امرأة زهير بن جذيمة قال أبو عبيدة أنشدني أبو سرار فيها\n(لعمري لقد بشرت بي إذ ولدتني ... فماذا الذي ردت عليك البشائر)\nوقال خالد بن جعفر يمن على هوازن بقتله زهيرا ويصدق الحديث قال أبو عبيدة أنشدنيه مالك بن عامر بن عبد الله بن بشر بن عامر ملاعب الأسنة\n(بل كيف تكفرني هوازن بعدما ... أعتقتهم فتوالدوا أحرارا)\n(وقتلت ربهم زهيرا بعد ما ... جدع الأنوف وأكثر الأوتارا)\n(وجعلت حزن بلادهم وجبالهم ... أرضا فضاء سهلة وعشارا)\n(وجعلت مهر بناتهم ودمائهم ... عقل الملوك هجائنا أبكارا)\nال أبو عبيدة ألا ترى أنه ذكر في شعره أن زهيرا كان ربهم وقد كان جدعهم وأنه قتله من أجلهم لا من أجل غني وأن غنيا ليسوا من ذلك في ذكر ولا لهم فيه معنى قال وقال ورقاء بن زهير\n(أما كلاب فإنا لا نسالمها ... حتى يسالم ذئب الثلة الراعي)\n(بنو جذيمة حاموا حول سيدهم ... إلا أسيدا نجا إذ ثوب الداعي)\nال ثم نعى الفرزدق على بني عبس ضربة ورقاء خالدا واعتذر بها الى سليمان بن عبد الملك فقال\n(إن يك سيف خان أو قدر أبى ... لتأخير نفس حتفها غير شاهد)\n(فسيف بني عبس وقد ضربوا به ... نبا بيدي ورقاء عن رأس خالد)\n(كذاك سيوف الهند تنبو ظباتها ... وتقطع أحيانا مناط القلائد)\n(ولو شئت قد السيف ما بين عنقه ... إلى علق تحت الشراسيف جامد)\nال وكان ضلع بني عبس مع جرير فقال الفرزدق فيهم هذه الأبيات هذه رواية أبي عبيدة","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":6,"spl":"شعر ورقاء بن زهير حين قتل والده","loc":2013},
{"id":"b116-9","bab":"الجزء 11","sec":"ماذا قال الاصمعي عن مقتل زهير وابنه","page":"ج11 ص96","text":"وأما الأصمعي فإنه ذكر فيما رواه الأثرم عنه قال حدثني غير واحد من الأعراب أن سبب مقتل زهير العبسي أن ابنه شأس بن زهير وفد إلى بعض الملوك فرجع ومعه حباء قد حبي به فمر بأبيات من بني عامر بن صعصعة وأبيات من بني غني على ماء لبني عامر أو غيرهم الشك من الأصمعي قال فاغتسل فناداه الغنوي استتر فلم يحفل بما قال فقال استتر ويحك البيوت بين يديك فلم يحفل فرماه الغنوي رياح بن الأسك بسهم أو ضربه فقتله والحي خلوف فاتبعه أصحاب شأس وهم في عدة فركب الفلاة واتبعوه فرهقوه فقتل حصينا وأخاه حصينا ثم نجا على وجهه حتى أدركه العطش فلجأ إلى منزل عجوز من بني إنسان وبنو إنسان حي من بني جشم فقالت له العجوز لا تبرح حتى يأتي بني فيأسروك قال الأصمعي فأخبرني مخبران اختلفا فقال أحدهما إنه أخذ سكينا فقطع عصبتي يديها وقال الآخر أخذ حجرا فشدخ به رأسها ثم أنشأ يقول\n(ولأنت أشجع من أسامة أو ... مني غداة وقفت للخيل)\n(إذ الحصين لدى الحصين كما ... عدل الرجازة جانب الميل)\n(وإذا أنهنهها لأفتلها ... جاشت ليغلب قولها قولي)\nقال فضرب الزمان ضربانه فالتقى خالد بن جعفر بن كلاب وزهير بن جذيمة العبسي فقال خالد لزهير أما آن لك أن تشتفي وتكف قال الأصمعي يعني مما قتل بشأس قال فأغلظ له زهير وحقره قال الأصمعي وأخبرني طلحة بن محمد بن سعيد بن المسيب أن ذلك الكلام بينهما كان بعكاظ عند قريش فلما حقره زهير وسبه قال خالد عسى إن كان يتهدده ثم قال اللهم أمكن يدي هذه الشقراء القصيرة من عنق زهير بن جذيمة ثم أعني عليه فقال زهير اللهم أمكن يدي هذه البيضاء الطويلة من عنق خالد ثم خل بيننا فقالت قريش هلكت والله يا زهير فقال إنكم والله الذين لا علم لكم قال الأصمعي ثم نرجع إلى حديث العبسيين والعامريين وبعضه من حديث أبي عمرو بن العلاء قال فجاء أخو امرأة زهير وكانت امرأته فاطمة بنت الشريد السلمية وهي أم قيس بن زهير وكان زهير قد أساء إليهم في شيء فجاء أخوها إلى بني عامر فقال هل لكم في زهير بن جذيمة ينتج إبله ليس معه أحد غير أخيه أسيد بن جذيمة وعبد راع لإبله وجئتكم من عنده وهذا لبن حلبوه لي فذاقوه فإذا هو ليس بحازر فعلموا أنه قريب فخرج حندج بن البكاء وخالد بن جعفر ومعاوية بن عبادة بن عقيل ليس على أحدهم درع غير خالد كانت عليه درع أعاره إياها عمرو بن يربوع الغنوي وكانت درع ابن الأجلح المرادي كان قتله فأخذها منه وكان يقال لها ذات الأزمة وإنما سميت بذلك لأنها كانت لها عرى تعلق فضولها بها إذا أراد أن يشمرها قال فطلعوا فقال أسيد بن جذيمة قال الأصمعي وكان أسيد شيخا كبيرا وكان كثير شعر الوجه والجسد أتيت ورب الكعبة فقال زهير\nكل أزب نفور فذهبت مثلا فلم يشعر بهم زهير إلا في سواد الليل فركب فرسه ثم وجهها فلحقه قوم أحدهم حندج أو العقيلي واختلفوا فيهما فطعن فخذ الفرس طعنة خفيفة ثم أراد أن يطعن الرجل الصحيحة فناداه خالد يا فلان لا تفعل فيستويا أقبل على السقيمة قال فطعنها فانخذلت الفرس فأدركوه فلما أدركوه رمى بنفسه وعانقه خالد فقال اقتلوني ومجدعا فجاء حندج وكان أعجم اللسان فقال لخالد وهو فوق زهير نح رأسك يا أبا جزء فنحى رأسه فضرب حندج زهيرا ضربة على دهش ثم ركبوا وتركوه قال فقال خالد ويحك يا حندج ما صنعت فقال ساعدي شديد وسيفي حديد وضربته ضربة فقال السيف قب وخرج عليه مثل ثمرة المرار فطعمته فوجدته حلوا يعني دماغه قال إن كنت صدقت فقد قتلته قال فجاء قوم زهير فاحتملوه ومنعوه الماء كراهة أن يبتل دماغه فيموت فقال يا آل غطفان أأموت عطشا فسقي فمات وذلك بعد أيام ففي ذلك يقول ورقاء بن زهير وكان قد ضرب خالدا ضربة فلم يصنع شيئا فقال\n(رأيت زهيرا تحت كلكل خالد ... فأقبلت أسعى كالعجول أبادر)\n(إلى بطلين ينهضان كلاهما ... يريدان نصل السيف والسيف نادر)\nال الأصمعي فضرب الدهر من ضربانه إلى أن التقى خالد بن جعفر والحارث بن ظالم","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":7,"spl":"ماذا قال الاصمعي عن مقتل زهير وابنه","loc":2014},
{"id":"b116-10","bab":"الجزء 11","sec":"ذكر مقتل خالد بن جعفر بن كلاب","page":"ج11 ص99","text":"قتله الحارث بن ظالم المري قال أبو عبيدة كان الذي هاج من الأمر بين الحارث بن ظالم وخالد بن جعفر أن خالد بن جعفر أغار على رهط الحارث بن ظالم من بني يربوع بن غيظ بن مرة وهم في واد يقال له حراض فقتل الرجال حتى أسرع والحارث يومئذ غلام وبقيت النساء وزعموا أن ظالما هلك في تلك الوقعة من جراحة أصابته يومئذ وكانت نساء بني ذبيان لا يحلبن النعم فلما بقين بغير رجال طفقن يدعون الحارث فيشد عصاب الناقة ثم يحلبنها ويبكين رجالهن ويبكي الحارث معهن فنشأ على بغض خالد وأردف ذلك قتل خالد زهير بن جذيمة فاستحق العدواة في غطفان فقال خالد بن جعفر في تلك الوقعة\n(تركت نساء يربوع بن غيظ ... أرامل يشتكين إلى وليد)\n(يقلن لحارث جزعا عليه ... لك الخيرات مالك لا تسود)\n(تركت بني جذيمة في مكر ... ونصرا قد تركت لدى الشهود)\n(ومني سوف تأتي قارعات ... تبيد المخزيات ولا تبيد)\n(وقيس ابن المعارك غادرته ... قناتي في فوارس كالأسود)\n(وحلت بركها ببني جحاش ... وقد مدوا إليها من بعيد)\n(وحي بني سبيع يوم ساق ... تركناهم كجارية وبيد)\nال أبو عبيدة فمكث خالد بن جعفر برهة من دهره حتى كان من أمره وأمر زهير بن جذيمة ما كان وخالد يومئذ رأس هوازن فلما استحق عداوة عبس وذبيان أتى النعمان بن المنذر ملك الحيرة لينظر ما قدره عنده وأتاه بفرس فألفى عنده الحارث بن ظالم قد أهدى له فرسا فقال أبيت اللعن نعم صباحك وأهلي فداؤك هذا فرس من خيل بني مرة فلن تؤتى بفرس يشق غباره إن لم تنسبه انتسب كنت ارتبطته لغزو بني عامر بن صعصعة فلما أكرمت خالدا أهديته إليك وقام الربيع بن زياد العبسي فقال أبيت اللعن نعم صباحك وأهلي فداؤك هذا فرس من خيل بني عامر ارتبطت أباه عشرين سنة لم يخفق في غزوة ولم يعتلك في سفره وفضله على هذين الفرسين كفضل بني عامر على غيرهم قال فغضب النعمان عند ذلك وقال يا معشر قيس أرى خيلكم أشباها أين اللواتي كأن أذنابها شقاق أعلام وكأن مناخرها وجار الضباع وكأن عيونها بغايا النساء رقاق\nالمستطعم تعالك اللجم في أشداقها تدور على مذاودها كأنما يقضمن حصى قال خالد زعم الحارث أبيت اللعن أن تلك الخيل خيله وخيل آبائه فغضب النعمان عند ذلك على الحارث بن ظالم فلما أمسوا اجتمعوا عند قينة من أهل الجيرة يقال لها بنت عفزر يشربون فقال خالد تغني\n(دار لهند والرباب وفرتنى ... ولميس قبل حوادث الأيام)\nهن خالات الحارث بن ظالم فغضب الحارث بن ظالم حتى امتلأ غيظا وغضبا وقال ما تزال تتبع أولى بآخرة قال أبو عبيدة ثم إن النعمان بن المنذر دعاهم بعد ذلك وقدم لهم تمرا فطفق خالد بن جعفر يأكل ويلقي نوى ما يأكل من التمر بين يدي الحارث فلما فرغ القوم قال خالد بن جعفر أبيت اللعن انظر إلى ما بين يدي الحارث بن ظالم من النوى ما ترك لنا تمرا إلا أكله فقال الحارث أما أنا فأكلت التمر وألقيت النوى وأما أنت فأكلته بنواه فغضب خالد وكان لا ينازع فقال أتنازعني يا حارث وقد قتلت حاضرتك وتركتك يتيما في حجور النساء فقال الحارث ذلك يوم لم أشهده وأنا مغن اليوم بمكاني قال خالد فهلا تشكر لي إذ قتلت زهير بن جذيمة وجعلتك سيد غطفان قال بلى أشكرك على ذلك فخرج الحارث بن ظالم إلى بنت عفزر فشرب عندها وقال لها تغني\n(تعلم أبيت اللعن أني فاتك ... من اليوم أو من بعده بابن جعفر)\n(أخالد قد نبهتني غير نائم ... فلا تأمنن فتكي يد الدهر واحذر)\n(أعيرتني أن نلت منا فوارسا ... غداة حراض مثل جنان عبقر)\n(أصابهم الدهر الختور بختره ... ومن لا يق الله الحوادث يعثر)\n(فعلك يوما أن تنوء بضربة ... بكف فتى من قومه غير جيدر)\n(يغص بها عليا هوازن والمنى ... لقاء أبي جزء بأبيض مبتر)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":8,"spl":"ذكر مقتل خالد بن جعفر بن كلاب","loc":2015},
{"id":"b116-11","bab":"الجزء 11","sec":"ذكر مقتل خالد بن جعفر بن كلاب","page":"ج11 ص99","text":"قال فبلغ خالد بن جعفر قوله فلم يحفل به فقال عبد الله بن جعدة وهو ابن أخت خالد وكان رجل قيس رأيا لابنه يا بني ائت أبا جزء فأخبره أن الحارث بن ظالم سفيه موتور فأخف مبيتك الليلة فإنه قد غلبه الشراب فإن أبيت فاجعل بينك وبينه رجلا ليحرسك فوضعوا رجلا بإزائه ونام ابن جعدة دون الرجل وخالد من خلف الرجل وعرف أن ابن عتبة وابن جعدة يحرسان خالدا فأقبل الحارث فانتهى إلى ابن جعدة فتعداه ومضى إلى الرجل وهو يحسبه خالدا فعجنه بكلكله حتى كسره وجعل يكدمه لا يعقل فخلى عنه والرجل تحته ومضى إلى خالد وهو نائم فضربه بالسيف حتى قتله فقال لعروة أخبر الناس أني قتلت خالدا وقال في ذلك\n(ألا سائل النعمان إن كنت سائلا ... وحي كلاب هل فتكت بخالد)\n(عشوت عليه وابن جعدة دونه ... وعروة يكلا عمه غير راقد)\n(وقد نصبا رجلا فباشرت جوزه ... بكلكل مخشي العداوة حارد)\n(فأضربه بالسيف يأفوخ رأسه ... فصمم حتى نال نوط القلائد)\n(وأفلت عبد الله مني بذعره ... وعروة من بعد ابن جعدة شاهدي)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":9,"spl":"ذكر مقتل خالد بن جعفر بن كلاب","loc":2016},
{"id":"b116-12","bab":"الجزء 11","sec":"شعر قيس بن زهير للحارث حين قتل خالدا","page":"ج11 ص103","text":"فلما أبت غطفان أن تجيره غضبت لذلك بنو عبس وبعث إليه قيس بن زهير بن جذيمة بهذه الأبيات\n(جزاك الله خيرا من خليل ... شفى من ذي تبولته الخليلا)\n(أزحت بها جوى ودخيل حزن ... تمخخ أعظمي زمنا طويلا)\n(كسوت الجعفري أبا جزيء ... ولم تحفل به سيفا صقيلا)\n(أبأت به زهير بني بغيض ... وكنت لمثلها ولها حمولا)\n(كشفت له القناع وكنت ممن ... يجلي العار والأمر الجليلا)\nفأجابه الحارث بن ظالم\n(أتاني عن قييس بني زهير ... مقالة كاذب ذكر التبولا)\n(فلو كنتم كما قلتم لكنتم ... لقاتل ثأركم حرزا أصيلا)\n(ولكن قلتم جاور سوانا ... فقد جللتنا حدثا جليلا)\n(ولو كانوا هم قتلوا أخاكم ... لما طردوا الذي قتل القتيلا)\nال ابوعبيدة فلما منعته غطفان لحق بحاجب بن زرارة فأجاره ووعده أن يمنعه من بني عامر وبلغ بني عامر مكانه في بني تميم فساروا في عليا هوازن فلما كانوا قريبا من القوم في أول واد من أوديتهم خرج رجل من بني غني ببعض البوادي فإذا هو بامرأة من بني تميم ثم من بني حنظلة تجتني الكمأة فأخذها فسألها عن الخبر فأخبرته بمكان الحارث بن ظالم عند حاجب بن زرارة وما وعده من نصرته ومنعه فانطلق بها الغنوي الى رحله فانسلت في وسط من الليل فأتى الغنوي الأحوص بن جعفر فأخبره أن المرأة قد ذهبت وقال هي منذرة عليك فقال له الأحوص ومتى عهدك بها قال عهدي بها والمني يقطر من فرجها قال وأبيك إن عهدك بها لقريب وتبع المرأة عامر بن مالك يقص أثرها حتى انتهى إلى بني زرارة والمرأة عند حاجب وهو يقول لها أخبريني أي قوم أخذوك قالت أخذني قوم يقبلون بوجوه الظباء ويدبرون بأعجاز النساء قال أولئك بنو عامر قال فحدثيني من في القوم قالت رأيتهم يغدون على شيخ كبير لا ينظر بمأقيه حتى يرفعوا له من حاجبيه قال ذلك الأحوص بن جعفر قالت ورأيت شابا شديد الخلق\nكأن شعر ساعديه حلق الدرع يعذم القوم بلسانه عذم الفرس العضوض قال ذلك عتبة بن بشير بن خالد قالت ورأيت كهلا إذا أقبل معه فتيان يشرف القوم إليه فإذا نطق أنصتوا قال ذلك عمرو بن خويلد والفتيان ابناه زرعة ويزيد قالت ورأيت شابا طويلا حسنا إذا تكلم بكلمة أنصتوا لها ثم يؤلون إليه كما تؤل الشول إلى فحلها قال ذلك عامر بن مالك قال أبو عبيدة فدعا حاجب الحارث بن ظالم فأخبره برأيه وخبر القوم وقال يا بن ظالم هؤلاء بنو عامر قد أتوك فما أنت صانع قال الحارث ذلك إليك إن شئت أقمت فقاتلت القوم وإن شئت تنحيت قال حاجب تنح عني غير ملوم فغضب الحارث من ذلك وقال\n(لعمري لقد جاورت في حي وائل ... ومن وائل جاورت في حي تغلب)\n(فأصبحت في حي الأراقم لم يقل ... لي القوم يا حار بن ظالم أذهب)\n(وقد كان ظني إذ عقلت إليكم ... بني عدس ظني بأصحاب يثرب)\n(غداة أتاهم تبع في جنوده ... فلم يسلموا المرين من حي يحصب)\n(فإن تك في عليا هوازن شوكة ... تخاف ففيكم حد ناب ومخلب)\n(وإن يمنع المرء الزراري جاره ... فأعجب بها من حاجب ثم أعجب)\nغضب حاجب فقال\n(لعمر أبيك الخير يا حار إنني ... لأمنع جارا من كليب بن وائل)\n(وقد علم الحي المعدي أننا ... على ذاك كنا في الخطوب الأوائل)\n(وأنا إذا ما خاف جار ظلامة ... لبسنا له ثوبي وفاء ونائل)\n(وأن تميما لم تحارب قبيلة ... من الناس إلا أولعت بالكواهل)\n(ولو حاربتنا عامر يا بن ظالم ... لعضت علينا عامر بالأنامل)\n(ولاستيقنت عليا هوازن أننا ... سنوطئها في دارها بالقنابل)\n(ولكنني لا أبعث الحرب ظالما ... ولو هجتها لم ألف شحمة آكل)\nقال فتنحى الحارث بن ظالم عن بني زرارة فلحق بعروض اليمامة ودعا معبدا ولقيطا ابني زرارة فقال سيرا في الظعن فموعدكما رحرحان فإنا مقيمون في حامية الخيل حتى تأتينا بنو عامر وخرج عامر بن مالك الى قومه بالخبر فقالوا ما ترى قال أن ندعهم بمكانهم ونسبقهم إلى الظعن قال فلقوها برحرحان فاقتتلوا قتالا شديدا فأصابوها وأسر معبد وجرح لقيط فبعثوا بمعبد الى رجل بالطائف كان يعذب الأسرى فقطعه إربا إربا حتى قتله وقال عامر بن مالك يرد على حاجب قوله\n(ألكني الى المرء الزراري حاجب ... رئيس تميم في الخطوب الأوائل)\n(وفارسها في كل يوم كريهة ... وخير تميم بين جاف وناعل)\n(لعمري لقد دافعت عن حي مالك ... شآبيب من حرب تلقح حائل)\n(على كل جرداء السراة طمرة ... وأجرد خوار العنان مناقل)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":10,"spl":"شعر قيس بن زهير للحارث حين قتل خالدا","loc":2017},
{"id":"b116-13","bab":"الجزء 11","sec":"شعر قيس بن زهير للحارث حين قتل خالدا","page":"ج11 ص103","text":"(نصحت له إذ قلت إن كنت لاحقا ... بقوم فلا تعدل بأبناء وائل)\n(ولو ألجأته عصبة تغلبية ... لسرنا إليهم بالقنا والقنابل)\n(ولو رمتم أن تمنعوه رأيتم ... هناك أمورا غيها غير طائل)\n(لشاب وليد الحي قبل مشيبه ... وعضت تميم كلها بالأنامل)\n(وقامت رجال منكم خندفية ... ينادون جهرا ليتنا لم نقاتل)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":11,"spl":"شعر قيس بن زهير للحارث حين قتل خالدا — الحارث يقتل ابن النعمان حين رآه في حجر سلمى بنت ظال","loc":2018},
{"id":"b116-14","bab":"الجزء 11","sec":"الحارث يقتل ابن النعمان حين رآه في حجر سلمى بنت ظالم","page":"ج11 ص107","text":"قال فخرج الحارث بن ظالم من فوره ذلك حتى أتى سلمى بنت ظالم وفي حجرها ابن النعمان فقال لها إنه لن يجيرني من النعمان إلا تحرمي بابنه فادفعيه إلي\nوقد كان النعمان بعث إلى جارات للحارث بن ظالم فسباهن فدعاه ذلك الى قتل الغلام فقتله\nفوثب النعمان على عم الحارث بن ظالم فقال له لأقتلنك أو لتأتيني بابن أخيك\nفاعتذر اليه فخلى عنه\nفأقبل ينطلق فقال\n(يا حار إني أحيا من مخبأة ... وأنت أجرأ من ذي لبدة ضاري)\n(قد كان بيتي فيكم بالعلاء فقد ... أحللت بيتي بين السيل والنار)\n(مهما أخفك على شيء تجيء به ... فلم اخفك على أمثالها حار)\n(ولم أخفك على ليث تخاتله ... عبل الذارعين للأقران هصار)\n(وقد علمت بأني لن ينجيني ... مما فعلت سوى الإقرار بالعار)\n(فقد عدوت على النعمان ظالمه ... في قتل طفل كمثل البدر معطار)\n(فاعلم بأنك منه غير منفلت ... وقد عدوت على ضرغامة شاري)\nقال الحارث بن ظالم في ذلك\n(قفا فاسمعا أخبركما إذ سألتما ... محارب مولاه وثكلان نادم)\n(حسبت أبا قابوس أنك سابقي ... ولما تذق فتكي وأنفك راغم)\n(أخصيي حمار بات يكدم نجمة ... أتؤكل جاراتي وجارك سالم)\n(تمنيته جهرا على غير ريبة ... أحاديث طسم إنما أنت حالم)\n(فإن تك أذوادا أصبت ونسوة ... فهذا ابن سلمى أمره متفاقم)\n(علوت بذي الحيات مفرق رأسه ... وكان سلاحي تجتويه الجماجم)\n(فتكت به فتكا كفتكي بخالد ... وهل يركب المكروه إلا الأكارم)\n(بدأت بهذي ثم أثني بمثلها ... وثالثة تبيض منها المقادم)\n(شفيت غليل الصدر منه بضربة ... كذلك يأبى المغضبون القماقم)\nقال النعمان بن المنذر ما يعني بالثالثة غيري قال سنان بن أبي حارثة المري وهو يومئذ رأس غطفان أبيت اللعن والله ما ذمة الحارث لنا بذمة ولا جاره لنا بجار ولو أمنته ما أمناه فبلغ ابن ظالم قول سنان بن أبي حارثة فقال في ذلك\n(ألا أبلغ النعمان عني رسالة ... فكيف بخطاب الخطوب الأعاظم)\n(وأنت طويل البغي أبلخ معور ... فزوع إذا ما خيف إحدى العظائم)\n(فما غرة والمرء يدرك وتره ... بأروع ماضي الهم من آل ظالم)\n(أخي ثقة ماضي الجنان مشيع ... كميش التوالي عند صدق العزائم)\n(فأقسم لولا من تعرض دونه ... لعولي بهندي الحديدة صارم)\n(فأقتل أقواما لئاما أذلة ... يعضون من غيظ أصول الأباهم)\n(تمنى سنان ضلة أن يخيفني ... ويأمن ما هذا بفعل المسالم)\n(تمنيت جهدا أن تضيع ظلامتي ... كذبت ورب الراقصات الرواسم)\n(يمين امرىء لم يرضع اللؤم ثديه ... ولم تتكنفه عروق الألائم)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":11,"spl":"شعر قيس بن زهير للحارث حين قتل خالدا — الحارث يقتل ابن النعمان حين رآه في حجر سلمى بنت ظال","loc":2019},
{"id":"b116-15","bab":"الجزء 11","sec":"ديهث تستجير بالحارث بن ظالم بعد أن سلبت إبلها","page":"ج11 ص110","text":"قال فأمنه النعمان وأقام حينا\nثم إن مصدقا للنعمان أخذ إبلا لامرأة من بني مرة يقال لها ديهث فأتت الحارث فعلقت دلوها بدلوه ومعها بني لها فقالت أبا ليلى إني أتيتك مضافة\nفقال الحارث إذا أورد القوم النعم فنادي بأعلى صوتك\n(دعوت بالله ولم تراعي ... ذلك راعيك فنعم الراعي)\n(وتلك ذود الحارث الكساع ... يمشي لها بصارم قطاع)\n(يشفي به مجامع الصداع ... )\nوخرج الحارث في أثرها يقول\n(أنا أبو ليلى وسيفي المعلوب ... كم قد أجرنا من حريب محروب)\n(وكم رددنا من سليب مسلوب ... وطعنة طعنتها بالمنصوب)\n(ذاك جيهز الموت عند المكروب ... )\nم قال لها لا تردن عليك ناقة ولا بعير تعرفينه إلا أخذتيه ففعلت فأتت على لقوح لها يحلبها حبشي فقالت يا أبا ليلى هذه لي فقال الحبشي كذبت فقال الحارث أرسلها لا أم لك فضرط الحبشي فقال\nالحارث است الحالب أعلم فسارت مثلا قال أبو عبيدة ففي ذلك يقول في الإسلام الفرزدق\n(كما كان أوفى إذ ينادي ابن ديهث ... وصرمته كالمغنم المتنهب)\n(فقام أبو ليلى اليه ابن ظالم ... وكان متى ما يسلل السيف يضرب)\n(وما كان جارا غير دلو تعلقت ... بحبلين في مستحصد القد مكرب)\nال أبو عبيدة حدثني أبو محمد عصام العجلي قال فلما قتل الحارث بن ظالم خالد بن جعفر في جوار الملك خرج هاربا حتى أتى صديقا له من كندة يحل شعبي قال شعبي غير ممدود فلما ألح الأسود في طلب الحارث قال له الكندي ما أرى لك نجاة إلا أن ألحقك بحضرموت ببلاد اليمن فلا يوصل إليك فسار معه يوما وليلة فلما غربه قال إنني أنقطع ببلاد اليمن فأغترب بها وقد برئت منك خفارتي فرجع حتى أتى أرض بكر بن وائل فلجأ الى بني عجل بن لجيم فنزل على زبان فأجاره وضرب عليه قبة وفي ذلك يقول العجلي\n(ونحن منعنا بالرماح ابن ظالم ... فظل يغني آمنا في خبائنا)\nال أبو عبيدة فجاءته بنو ذهل بن ثعلبة وبنو عمرو بن شيبان فقالوا أخرج هذا المشؤوم من بين أظهرنا لا يعرنا بشر فإنا لا طاقة لنا بالملحاء\nوالملحاء كتيبة الأسود فأبت عجل أن تخفره فقاتلوه فامتنعت بنو عجل فقال الحارث بن ظالم في الكندي وفيهم\n(يكلفني الكندي سير تنوفة ... أكابد فيها كل ذي صبة مثري)\nلصبة قطعة من الغنم أو بقية منها\n(وأقبل دوني جمع ذهل كأنني ... خلاة لذهل والزعانف من عمرو)\n(ودوني ركب من لجيم مصمم ... وزبان جاري والخفير على بكر)\n(لعمري لا أخشى ظلامة ظالم ... وسعد بن عجل مجمعون على نصري)\nال أبو عبيدة ثم قال لهم الحارث إني قد اشتهر أمري فيكم ومكاني وأنا راحل عنكم فارتحل فلحق بطيىء فقال الحارث في ذلك\n(لعمري لقد حلت بي اليوم ناقتي ... إلى ناصر من طيىء غير خاذل)\n(فأصبحت جارا للمجرة منهم ... على باذخ يعلو على المتطاول)\nال أبو عبيدة وحدثني أبو حية ان الأسود حين قتل الحارث خالدا سأل عن أمر يبلغ منه فقال له عروة بن عتبة إن له جارات من بلي بن عمرو ولا أراك تنال منه شيئا أغيظ له من أخذهن وأخذ أموالهن فبعث الأسود فأخذهن واستاق أموالهن فبلغ ذلك الحارث فخرج من الحين فانساب في غمار الناس حتى عرف موضع جاراته ومرعى إبلهن فأتى الإبل فوجد حالبين يحلبان ناقة لهن يقال لها اللفاع وكانت لبونا كأغزر الإبل إذا حلبت اجترت ودمعت عيناها وأصغت برأسها وتفاجت تفاج البائل وهجمت في\nالمحلب هجما حتى تسنمه وتجاوبت أحاليلها بالشخب هثا وهثيما حتى تصف بين ثلاثة محالب فصاح الحارث بهما ورجز فقال\n(إذا سمعت حنة اللفاع ... فادعي أبا ليلى ولا تراعي)\n(ذلك راعيك فنعم الراعي ... يجبك رحب الباع والذراع)\n(منطقا بصارم قطاع ... )\nليا عنها فعرفاه فضرط البائن فقال الحارث است الضارط أعلم فذهبت مثلا قال الأثرم البائن الحالب الأيمن والمستعلي الحالب الأيسر ثم عمد إلى أموال جاراته والى جاراته فجمعهن ورد أموالهن وسار معهن حتى اشتلاهن أي أنقذهن","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":12,"spl":"ديهث تستجير بالحارث بن ظالم بعد أن سلبت إبلها","loc":2020,"partial":1},
{"id":"b116-16","bab":"الجزء 11","sec":"رواية في قتله ابن الملك","page":"ج11 ص113","text":"قال أبو عبيدة ولحق الحارث ببلاد قومه مختفيا وكانت أخته سلمى بنت ظالم عند سنان بن أبي حارثة المري قال أبو عبيدة وكان الأسود بن المنذر قد تبنى سنان بن أبي حارثة المري ابنه شرحبيل فكانت سلمى بنت كثير بن ربيعة من بني غنم بن دودان امرأة سنان بن أبي حارثة المري ترضعه وهي أم هرم وكان هرم غنيا يقدر على ما يعطي سائليه فجاء الحارث وقد كان اندس في بلاد غطفان فاستعار سرج سنان ولا يعلم سنان وهم نزول\nبالشربة فأتى به سلمى ابنة ظالم فقال يقول لك بعلك ابعثي بابن الملك مع الحارث حتى أستأمن له ويتخفر به وهذا سرجه آية إليك فزينته ثم دفعته الى الحارث فأتى بالغلام ناحية من الشربة فقتله ثم أنشأ يقول\n(قفا فاسمعا أخبركما إذ سألتما ... محارب مولاه وثكلان نادم)\nثكلان نادم يعني الأسود لأنه قتل ابنه شرحبيل محارب مولاه يعني الحارث نفسه ومولاه سنان\n(أخصيي حمار بات يكدم نجمة ... أتؤكل جاراتي وجارك سالم)\n(حسبت أبيت اللعن أنك فائت ... ولما تذق ثكلا وأنفك راغم)\n(فإن تك أذوادا أصبت ونسوة ... فهذا ابن سلمى رأسه متفاقم)\n(علوت بذي الحيات مفرق رأسه ... وكان سلاحي تجتويه الجماجم)\n(فتكت به كما فتكت بخالد ... ولا يركب المكروه إلا الأكارم)\n(بدأت بتلك وانثنيت بهذه ... وثالثة تبيض منها المقادم)\nال ففي ذلك يقول عقيل بن علفة في الإسلام وهو من بني يربوع بن\nغيظ بن مرة لما هاجى شبيب بن البرصاء وأبوه يزيد وهو من بني نشبة بن غيظ بن مرة ابن عم سنان بن أبي حارثة فعيره بقتل الحارث بن ظالم شرحبيل لأنه ربيب بني حارثة بن مرة بن نشبة بن غيظ رهط شبيب ففي ذلك يقول عقيل\n(قتلنا شرحبيلا ربيب أبيكم ... بناصية المعلوب ضاحية غصبا)\n(فلم تنكروا أن يغمز القوم جاركم ... بإحدى الدواهي ثم لم تطلعوا نقبا)\nال أبو عبيدة وهرب الحارث فغزا الأسود بني ذبيان إذ نقضوا العهد وبني أسد بشط أريك قال أبو عبيدة وسألته عنه فقال هما أريكان الأسود والأبيض ولا أدري بأيهما كانت الوقعة قال أبو عبيدة وقال آخرون إن سلمى امرأة سنان التي أخذ الحارث شرحبيل من عندها من بني أسد قال فإنما غزا الأسود بني أسد لدفع الأسدية سلمى ابنه إلى الحارث فقتل فيهم قتلا ذريعا وسبى واستاق أموالهم وفي ذلك يقول الأعشى ميمون\n(وشيوخ صرعى بشطي أريك ... ونساء كأنهن السعالي)\n(من نواصي دودان إذ نقضوا العهد ... وذبيان والهجان الغوالي)\n(رب رفد هرقته ذلك اليوم ... وأسرى من معشر أقتال)\n(هؤلا ثم هؤلا كلا أحذيت ... نعالا محذوة بمثال)\n(وأرى من عصاك أصبح مخذولا ... وكعب الذي يطيعك عالي)\nال ووجد نعل شرحبيل عند أضاخ وهو من الشربة في بني محارب بن خصفة بن قيس عيلان قال فأحمى لهم الأسود الصفا التي بصحراء أضاخ وقال لهم إني أحذيكم نعالا فأمشاهم على الصفا المحمى فتساقط لحم أقدامهم فلما كان الإسلام قتل جوشن الكندي رجلا من بني محارب فأقيد به جوشن بالمدينة وكان الكندي من رهط عباس بن يزيد الكندي فهجا بني محارب فعيرهم بتحريق الأسود أقدامهم فقال\n(على عهد كسرى نعلتكم ملوكنا ... صفا من أضاخ حاميا يتلهب)\nال أبو عبيدة وصار ذلك مثلا يتوعد به الشعراء من هجوه ويحذرونهم مثل ذلك ومن ذلك أن ابن عتاب الكلبي ورد على بني النوس من جديلة طيىء فسرقوا سهاما له فقال يحذرهم\n(بني النوس ردوا أسهمي إن أسهمي ... كنعل شرحبيل التي في محارب)\nوقال في الجاهلية ابن أم كهف الطائي في مدحه لمالك بن حمارالشمخي فذكر نعل شرحبيل فقال\n(ومولاك الذي قتل ابن سلمى ... علانية شرحبيل ابن نعل)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":13,"spl":"رواية في قتله ابن الملك","loc":2021},
{"id":"b116-17","bab":"الجزء 11","sec":"رواية في قتله ابن الملك","page":"ج11 ص113","text":"لأنه لولا النعل لم يعرف وإنما عرف بما صنع أبوه ببني محارب من أجل نعله التي وجدت في بني محارب قال أبو عبيدة وأخذ الأسود سنان بن أبي حارثة فأتاه الحارث بن سفيان أحد بني الصارد وهو الحارث بن سفيان بن مرة بن عوف بن الحارث بن سفيان أخو سيار بن عمرو بن جابر الفزاري لأمه فاعتذر الى الأسود أن يكون سنان بن أبي حارثة علم أو اطلع ولقد كان أطرد الحارث من بلاد غطفان وقال علي دية ابنك ألف بعير دية الملوك فحملها إياه وخلى عن سنان فأدى الى الأسود منها ثمانمائة بعير ثم مات فقال سيار بن عمرو أخوه لأمه أنا أقوم فيما بقي مقام الحارث بن سفيان فلم يرض به الأسود فرهنه سيار قوسه فأدى البقية فلما مدح قراد بن حنش الصاردي بني فزارة جعل الحمالة كلها لسيار بن عمرو فقال\n(ونحن رهنا القوس ثمت فوديت ... بألف على ظهر الفزاري أقرعا)\n(بعشر مئين للملوك سعى بها ... ليوفي سيار بن عمرو فأسرعا)\n(رمينا صفاه بالمئين فأصبحت ... ثناياه للساعين في المجد مهيعا)\nال ويقال بل قالها ربيع بن قعنب فرد عليه قراد فقال\n(ما كان ثعلب ذي عاج ليحملها ... ولا الفزاري جوفان بن جوفان)\n(لكن تضمنها ألفا فأخرجها ... على تكاليفها حار بن سفيان)\nوقال عويف القوافي بن عيينة بن حصن بن حذيفة بن بدر في الإسلام يفخر على أبي منظور الوبري حين هاجاه أحد بني وبر بن كلاب\n(فهل وجدتم حاملا كحاملي ... إذ رهن القوس بألف كامل)\n(بدية ابن الملك الحلاحل ... فافتكها من قبل عام قابل)\n(سيار الموفي بها ذو السائل ... )\nحوق الحارث ببني دارم بعد قتله شرحبيل قال أبو عبيدة فلما قتل الحارث شرحبيل لحق ببني دارم فلجأ الى بني ضمرة قال وبنو عبد الله بن دارم يقولون بل جاور معبد بن زرارة فأجاره فجر جواره يوم رحرحان وجر يوم رحرحان يوم جبلة وطلبه الأسود بن المنذر بخفرته فلما بلغه نزوله ببني دارم أرسل فيه إليهم أن يسلموه فأبوا فقال يمن على بني قطن بن نهشل بن دارم بما كان من النعمان بن المنذر في أمر بني رشية وهي رميلة حين طلبهم من لقيط بن زرارة حتى أستنقذهم ورشية أمة كانت لزرارة بن عدس بن زيد المجاشعي فوطئها رجل من بني نهشل فأولدها وكان زرارة يأتي بني نهشل يطلب الغلمة التي ولدت وولدت الأشهب بن رميلة والرباب بن رميلة وغيرهما وكانوا يسمعونه ما يكره فيرجع\nالى ولده فيقول أسمعني بنو عمي خيرا وقالوا سنبعث بهم إليك عاجلا حتى مات زرارة فقام لقيط ابنه بأمرهم فلما أتاهم أسمعوه ما كره ووقع بينهم شر فذهب النهشلي إلى الملك فقال أبيت اللعن لا تصلني وتصل قومي بأفضل من طلبتك إلى لقيط الغلمة ليكف عني فدعاه فشرب معه ثم استوهبهم منه فوهبهم له فقال الأسود بن المنذر في ذلك\n(كأين لنا من نعمة في رقابكم ... بني قطن فضلا عليكم وأنعما)\n(وكم منة كانت لنا في بيوتكم ... وقتل كريم لم تعدوه مغرما)\n(فإنكم لا تمنعون ابن ظالم ... ولم يمس بالأيدي الوشيج المقوما)\nأجابه ضمرة بن ضمرة فقال\n(سنمنع جارا عائذا في بيوتكم ... بأسيافنا حتى يؤوب مسلما)\n(إذا ما دعونا دارما حال دونه ... عوابس يعلكن الشكيم المعجما)\n(ولو كنت حربا ما وردت طويلعا ... ولا حوفه إلا خميسا عرمرما)\n(تركت بني ماء السماء وفعلهم ... وأشبهت تيسا بالحجاز مزنما)\n(ولن أذكر النعمان إلا بصالح ... فإن له فضلا علينا وأنعما)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":14,"spl":"رواية في قتله ابن الملك","loc":2022,"partial":1},
{"id":"b116-18","bab":"الجزء 11","sec":"رواية في قتله ابن الملك","page":"ج11 ص113","text":"قال وبلغ ذلك بني عامر فخرج الأحوص غازيا لبني دارم طالبا بدم أخيه خالد بن جعفر حين انطووا على الحارث وقاموا دونه فغزاهم فالتقوا برحرحان فهزمت بنو دارم وأسر معبد بن زرارة فانطلقوا به حتى مات في أيديهم وحديثه في يوم رحرحان يأتي بعد ثم أسر بنو هزان الحارث بن ظالم وقال أبو عبيدة خرج الحارث من عندهم فجعل يطوف في البلاد حتى سقط في ناحية من بلاد ربيعة ووضع سلاحه وهو في فلاة ليس فيها أثر ونام فمر به نفر من بني سعد قيس بن ثعلبة ومعهم قوم من بني هزان من عنزة وهو نائم فأخذوا فرسه وسلاحه ثم أوثقوه فانتبه وقد شدوه فلا يملك من نفسه شيئا فسألوه من أنت فلم يخبرهم وطوى عنهم الخبر فضربوه ليقتلوه على أن يخبرهم من هو فلم يفعل فاشتراه القيسيون من الهزانيين بزق خمر وشاة ويقال أشتراه رجل من بني سعد بإغلاق بكرة وعشرين من الشاء ثم انطلقوا به إلى بلادهم فقالوا له من أنت وما حالك فلم يخبرهم فضربوه ليموت فأبى قال وهو قريب من اليمامة قال فبينما هم على تلك الحال وهم يريغونه ضربا مرة وتهددا أخرى ولينا مرة ليخبرهم بحاله وهو يأبى حتى ملوه فتركوه في قيده حتى انفلت ليلا فتوجه نحو اليمامة وهي قريب منه فلقي غلمة يلعبون فنظر إلى غلام منهم أخلقهم للخير عنده فقال من أنت قال أنا بجير بن أبجر العجلي وله ذؤابة يومئذ وأمه امراة قتادة بن مسلمة الحنفي فأتاه وأخذ بحقويه والتزمه وقال أنا لك جار فيقال إن عجلا أجارته في هذا اليوم لا في اليوم الأول\nالذي ذكرناه في أول الحديث فأتى الغلام أباه فأخبره وأجاره وقال ائت عمك قتادة بن مسلمة الحنفي فأخبره فأتى قتادة فأخبره فأجاره قال أبو عبيدة وأما فراس فزعم أنه أفلت من بني قيس فأقبل شدا حتى أتى اليمامة واتبعوه حتى انتهى إلى نادي بني حنيفة وفيه قتادة بن مسلمة فلما رأوه يهوي نحوهم قال إن هذا لخائف وبصر بالقوم خلفه فصاح به الحصن الحصن فأقبل حتى ولج الحصن وجاءت بنو قيس فحال دونه وقال لو أخذتموه قبل دخوله الحصن لأسلمته إليكم فأما إذ تحرم بي فلا سبيل إليه قال فقالوا أسيرنا أشتريناه بأموالنا وما هو لك بجار ولا تعرفه وإنما أتاك هاربا من أيدينا ونحن قومك وجيرتك قال أما أن أسلمه أبدا فلا يكون ذلك ولكن اختاروا مني إن شئتم فانظروا ما اشتريتموه به فخذوه مني وإن شئتم أعطتيه سلاحا كاملا وحملته على فرس ودعوه حتى يقطع الوادي بيني وبينه ثم دونكموه فقالوا رضينا فقال ذلك للحارث فقال نعم فألبسه سلاحا كاملا وحمله على فرسه وقال له إن أفلتهم فرد إلي الفرس والسلاح لك قال فخرج وتركوه حتى جاز الوادي ثم أتبعوه ليأخذوه فلم يزل يقاتلهم ويطاردهم حتى ورد بلاد بني قشير وهو قريب من اليمامة أيضا بينهما أقل من يوم فلما صار إلى بلاد بني قشير يئسوا منه فرجعوا عنه وعرفه بنو قشير فانطووا عليه وأكرموه ورد إلى قتادة بن مسلمة فرسه وأرسل إليه بمائة من الإبل لا أدري أأعطاه إياها بنو قشير من أموالهم ليكافىء بها قتادة أم كانت له لم يفسر أبو عبيدة أمرها ولا سألته عنها فقال الحارث بن ظالم في ابني حلاكة وهما من الذين باعوه من القيسيين وفيما كان من أمره قال أبو عبيدة ويقال أسره راعيان من بني هزان يقال لهما ابنا حلاكة\n(أبلغ لديك بني قيس مغلغلة ... أني أقسم في هزان أرباعا)\n(ابنا حلاكة باعاني بلا ثمن ... وباع ذو آل هزان بما باعا)\n(يا بني حلاكة لما تأخذا ثمني ... حتى أقسم أفراسا وأدراعا)\n(قتادة الخير نالتني حذيته ... وكان قدما إلى الخيرات طلاعا)\nوقال في ذلك أيضا\n(همت عكابة أن تضيم لجيما ... فأبت لجيم ما تقول عكابه)\n(فآسقي بجيرا من رحيق مدامة ... واسقي الخفير وطهري أثوابه)\n(جاءت حنيفة قبل جيئة يشكر ... كلا وجدنا أوفياء ذؤابه)\nزعم أبو عبيدة أن الحارث لما هزمت بنو تميم يوم رحرحان مر برجل من بني أسد بن خزيمة فقال ياحار إنك مشؤوم وقد فعلت فانظر إذا كنت بمكان كذا وكذا من برقة رحرحان فإن لي به جملا أحمر فلا تعرض له وإنما يعرض له ويكره أن يصرح فيبلغ الأسود فيأخذه فلما كان الحارث بذلك المكان أخذ الجمل فنجا عليه وإذا هو لا يساير من أمامه ولا يسبق من ورائه فبلغ ذلك الأسود فأخذ الأسود الأسدي وناسا من قومه وبلغ ذلك الحارث بن ظالم فقال كأنه يهجوهم لئلا يتهمهم الأسود","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":15,"spl":"رواية في قتله ابن الملك","loc":2023},
{"id":"b116-19","bab":"الجزء 11","sec":"رواية في قتله ابن الملك","page":"ج11 ص113","text":"(أراني الله بالنعم المندى ... ببرقة رحرحان وقد أراني)\n(لحي الأنكدين وحي عبس ... وحي نعامة وبني غدان)\nقال فلما بلغ قوله الأسود خلى عنهم ولحق الحارث بمكة وانتمى إلى قريش وذلك قوله\n(وما قومي بثعلبة بن سعد ... ولا بفزارة الشعر الرقابا)\n(وقومي إن سألت بنو لؤي ... بمكة علموا مضر الضرابا)\nقال فزوده وحمله رواحة الجمحي على ناقة فذلك قوله\n(وهش رواحة الجمحي رحلي ... بناجية ولم يطلب ثوابا)\n(كأن الرحل والأنساع منها ... وميثرتي كسين أقب جابا)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":16,"spl":"رواية في قتله ابن الملك — خبر مقتله","loc":2024},
{"id":"b116-20","bab":"الجزء 11","sec":"خبر مقتله","page":"ج11 ص123","text":"يروى حش وهش وهما لغتان وحش سوى قال فلحق الحارث بالشام بملك من ملوك غسان يقال هو النعمان ويقال بل هو يزيد بن عمرو الغساني فأجاره وكانت للملك ناقة محماة في عنقها مدية وزناد وصرة ملح وإنما يختبر بذلك رعيته هل يجترىء عليه أحد منهم ومع الحارث أمرأتان فوحمت إحدى امرأتيه قال أبو عبيدة وأصابت الناس سنة شديدة فطلبت الشحم إليه قال ويحك وأنى لي بالشحم والودك فألحت عليه فعمد إلى الناقة فأدخلها بطن واد فلب في سبلتها أي\nطعن فأكلت امرأته ورفعت ما بقي من الشحم في عكتها قال وفقدت الناقة فوجدت نحيرا لم يؤخذ منها إلا السنام فأعلموا ذلك الملك وخفي عليهم من فعله فأرسل إلى الخمس التغلبي وكان كاهنا فقال من نحر الناقة فذكر أن الحارث نحرها فتذمم الملك وكذب عنه فقال إن أردت أن تعلم علم ذلك فدس امرأة تطلب إلى امرأته شحما ففعل فدخل الحارث وقد أخرجت امرأته إليها شحما فعرف الداء فقتلها ودفنها في بيته فلما فقدت المرأة قال الخمس غالها ما غال الناقة فإن كره الملك أن يفتشه عن ذلك فليأمر بالرحيل فإذا ارتحل بحث بيته ففعل واستثار الخمس مكان بيته فوثب عليه الحارث فقتله فأخذ الحارث فحبس فاستسقى ماء فأتاه رجل بماء فقال أتشرب فأنشأ الحارث يقول\n(لقد قال لي عند المجاهد صاحبي ... وقد حيل دون العيش هل أنت شارب)\n(وددت بأطراف البنان لو انني ... بذي أرونى ترمي ورائي الثعالب)\nلثعالب من مرة وهم رماة أروني مكان وقال مرة أخرى الثعالب بنو ثعلبة يقول كانوا يرمون عني ويقومون بأمري قال فأمر الملك بقتله فقال إنك قد أجرتني فلا تغدرني فقال لا ضير إن غدرت بك مرة فقد غدرت بي مرارا فأمر مالك بن الخمس التغلبي أن يقتله بأبيه فقال با بن شر الأظماء أنت تقتلني فقتله وقال ابن الكلبي لما قام ابن الخمس إلى الحارث ليقتله قال من أنت قال ابن الخمس قال أنت ابن شر الأظماء قال وأنت ابن شر الأسماء فقتله فقال رجل من ضري وهم حي من جرهم يرثي الحارث بن ظالم\n(يا حار حنيا ... حرا قطاميا)\n(ما كنت ترعيا ... في البيت ضجعيا)\n(أدعى لباخيا ... مملأ عيا)\nأخذ ابن الخمس سيف الحارث بن ظالم المعلوب فأتى به سوق عكاظ في الحرم فجعل يعرضه على البيع ويقول هذا سيف الحارث بن ظالم فاستراه إياه قيس بن زهير بن جذيمة فأراه إياه فعلاه به حتى قتله في الحرم فقال قيس بن زهير يرثي الحارث بن ظالم\n(ما قصرت من حاضن ستر بيتها ... أبر وأوفى منك حار بن ظالم)\n(أعز وأحمى عند جار وذمة ... وأضرب في كاب من النقع قاتم)\nهذه رواية أبي عبيدة والبصريين وأما الكوفيون فإنهم يذكرون أن النعمان بن المنذر هو الذي قتله أخبرني بذلك علي بن سليمان الأخفش قال حدثنا أبو سعيد عن محمد بن حبيب عن ابن الاعرابي عن المفضل قال لما هرب الحارث إلى مكة أسف النعمان بن المنذر على فوته إياه فلطف له وراسله وأعطاه الأمان وأشهد على نفسه وجوه العرب من ربيعة ومضر واليمن أنه لا يطلبه بذحل ولا يسوءه في حال وأرسل به مع جماعة ليسكن الحارث اليهم وأمرهم أن يتكفلوا له بالوفاء ويضمنوا له عنه أنه لا\nيهيجه ففعلوا ذلك وسكن إليه الحارث فأتى النعمان وهو في قصر بني مقاتل فقال للحاجب استأذن لي والناس يومئذ عند النعمان متوافرون فآستأذن له فقال النعمان ائذن له وخذ سيفه فقال له ضع سيفك وادخل فقال الحارث ولم أضعه قال ضعه فلا بأس عليك فلما ألح عليه وضعه ودخل ومعه الأمان فلما دخل قال أنعم صباحا أبيت اللعن قال لا أنعم الله صباحك فقال الحارث هذا كتابك قال النعمان كتابي والله ما أنكره أنا كتبته لك وقد غدرت وفتكت مرارا فلا ضير أن غدرت بك مرة ثم نادى من يقتل هذا فقام ابن الخمس التغلبي وكان الحارث فتك بأبيه فقال أنا أقتله وذكر باقي الخبر في قصته مع ابن الخمس مثل ما ذكر أبو عبيدة","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":16,"spl":"رواية في قتله ابن الملك — خبر مقتله","loc":2025},
{"id":"b116-21","bab":"الجزء 11","sec":"خبر الحارث وعمرو بن الإطنابة وإنما ذكر هاهنا لاتصاله بمقتل خالد بن جعفر ولأن فيما تناقضاه من","page":"ج11 ص127","text":"الأشعار أغاني صالح ذكرها في هذا الموضع\nقال أبو عبيدة كان عمرو بن الإطنابة الخزرجي ملك الحجاز ولما بلغه قتل الحارث بن ظالم خالد بن جعفر وكان خالد مصافيا له غضب لذلك غضبا شديدا وقال والله لو لقي الحارث خالدا وهو يقظان لما نظر إليه ولكنه قتله نائما ولو أتاني لعرف قدره ثم دعا بشرابه ووضع التاج على رأسه ودعا بقيانه فتغنين له\n(عللاني وعللا صاحبيا ... وأسقياني من المروق ريا)\n(إن فينا القيان يعزفن بالدف ... لفتياننا وعيشا رخيا)\n(يتبارين في النعيم ويصببن خلال القرون مسكا ذكيا ... )\n(إنما همهن أن يتحلن ... سموطا وسنبلا فارسيا)\n(من سموط المرجان فصل بالشذر ... فأحسن بحليهن حليا)\n(وفتى يضرب الكتيبة بالسيف ... إذا كانت السيوف عصيا)\n(إننا لا نسر في غير نجد ... إن فينا بها فتى خزرجيا)\n(يدفع الضيم والظلامة عنها ... فتجافي عنه لنا يامنيا)\n(أبلغ الحارث بن ظالم الرعديد ... والناذر النذور عليا)\n(أنما يقتل النيام ولا يقتل ... يقظان ذا سلاح كميا)\n(ومعي شكتي معابل كالجمر ... وأعددت ضارما مشرفيا)\n(لو هبطت البلاد أنسيتك القتل ... كما ينسىء النسيء النسيا)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":17,"spl":"خبر الحارث وعمرو بن الإطنابة وإنما ذكر هاهنا لاتصاله بمقتل خالد بن جعفر ولأن فيما تناقضاه ","loc":2026,"partial":1},
{"id":"b116-22","bab":"الجزء 11","sec":"شعر الحارث بعد أن انخذل عمرو عنه","page":"ج11 ص128","text":"قال فلما بلغ الحارث شعره هذا ازداد حنقا وغيظا فسار حتى أتى ديار بني الخزرج ثم دنا من قبة عمرو بن الإطنابة ثم نادى أيها الملك أغثني فإني جار مكثور وخذ سلاحك فأجابه وخرج معه حتى إذا برز له عطف عليه الحارث وقال أنا أبو ليلى فاعتركا مليا من الليل وخشي عمرو أن يقتله الحارث فقال له يا حار إني شيخ كبير وإني تعتريني سنة فهل لك في تأخير هذا الأمر إلى غد فقال هيهات ومن لي به في غد فتجاولا ساعة ثم ألقى عمرو الرمح من يده وقال يا حار ألم أخبرك أن النعاس قد يغلبني قد سقط رمحي فاكفف فكف قال أنظرني إلى غد قال لا أفعل قال فدعني آخذ رمحي قال خذه قال أخشى أن تعجلني عنه أو تفتك بي إذا أردت أخذه قال وذمة ظالم لا أعجلتك ولا قاتلتك ولا\nفتكت بك حتى تأخذه قال وذمة الإطنابة لا آخذه ولا أقاتلك فانصرف الحارث إلى قومه وقال مجيبا له\n(اعزفا لي بلذة قينتيا ... قبل أن يبكر المنون عليا)\n(قبل أن يبكر العواذل إني ... كنت قدما لأمرهن عصيا)\n(ما أبالي أراشدا فآصبحاني ... حسبتني عواذلي أم غويا)\n(بعد ألا أصر لله إنما ... في حياتي ولا أخون صفيا)\n(من سلاف كأنها دم ظبي ... في زجاج تخاله رازقيا)\n(بلغتنا مقالة المرء عمرو ... فأنفنا وكان ذاك بديا)\n(قد هممنا بقتله إذ برزنا ... ولقيناه ذا سلاح كميا)\n(غير ما نائم تعلل بالحلم ... معدا بكفه مشرفيا)\n(فمننا عليه بعد علو ... بوفاء وكنت قدما وفيا)\n(ورجعنا بالصفح عنه وكان ... المن منا عليه بعد تليا)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":17,"spl":"خبر الحارث وعمرو بن الإطنابة وإنما ذكر هاهنا لاتصاله بمقتل خالد بن جعفر ولأن فيما تناقضاه ","loc":2027},
{"id":"b116-23","bab":"الجزء 11","sec":"نسبة ما في هذا الخبر من الأغاني منها في شعر عمرو بن الإطنابة","page":"ج11 ص129","text":"\n(عللاني وعللا صاحبيا ... وأسقياني من المروق ريا)\n(إن فينا القيان يعزفن بالدف ... لفتياننا وعيشا رخيا)\nغنته عزة الميلاء من رواية حماد عن أبيه خفيف رمل بالوسطى قال حماد أخبرني أبي قال بلغني أن معبدا قال دخلت على جميلة وعندها عزة الميلاء تغنيها لحنها في شعر عمرو بن الإطنابة الخزرجي\n(عللاني وعللا صاحبيا ... )\nلى معزفة لها وقد أسنت فما سمعت قط مثلها وذهبت بعقلي وفتنتني فقلت هذا وهي كبيرة مسنة فكيف بها لو أدركتها وهي شابة وجعلت أعجب منها ومنها في شعر الحارث بن ظالم\n(ما أبالي إذا اصطبحت ثلاثا ... أرشيدا حسبتني أم غويا)\n(من سلاف كأنها دم ظبي ... في زجاج تخاله رازقيا)\nناه فليح بن أبي العوراء رملا بالبنصر عن عمرو بن بانة وغناه ابن محرز خفيف ثقيل أول بالخنصر من رواية حبش ومنها\n(بلغتنا مقالة المرء عمرو ... فأنفنا وكان ذاك بديا)\n(قد هممنا بقتله إذ برزنا ... ولقيناه ذا سلاح كميا)\nغناه مالك خفيف رمل بالبنصر من رواية حبش وذكر اسحاق في مجرده أن الغناء في هذين البيتين ليونس الكاتب ولم ينسب الطريقة ولا جنسها","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":17,"spl":"خبر الحارث وعمرو بن الإطنابة وإنما ذكر هاهنا لاتصاله بمقتل خالد بن جعفر ولأن فيما تناقضاه ","song":3,"loc":2028,"partialRef":{"sid":"b116-21","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b116-24","bab":"الجزء 11","sec":"يوم رحرحان الثاني","page":"ج11 ص131","text":"أخبرني علي بن سليمان ومحمد بن العباس اليزيدي في كتاب النقائض قالا قال أبو سعيد الحسن بن الحسين السكري عن محمد بن حبيب عن أبي عبيدة قال كان من خبر رحرحان الثاني أن الحارث بن ظالم المري لما قتل خالد بن جعفر بن كلاب غدرا عند النعمان بن المنذر بالحيرة هرب فأتى زرارة بن عدس فكان عنده وكان قوم الحارث قد تشاءموا به فلاموه وكره أن يكون لقومه زعم عليه والزعم المنة فلم يزل في بني تميم عند زرارة حتى لحق بقريش وكان يقال إن مرة بن عوف من لؤي بن غالب وهو قول الحارث بن ظالم ينتمي إلى قريش\n(رفعت السيف إذ قالوا قريش ... وبينت الشمائل والقبابا)\n(فما قومي بثعلبة بن سعد ... ولا بفزارة الشعر الرقابا)\nأتاهم لذلك النسب فكان عند عبد الله بن جدعان فخرجت بنو عامر\nإلى الحارث بن ظالم حيث لجأ إلى زرارة وعليهم الأحوص بن جعفر فأصابوا امرأة من بني تميم وجدوها تحتطب وكان في رأس الخيل التي خرجت في طلب الحارث بن ظالم شريح بن الأحوص وأصابوا غلمانا يجتنون الكمأة وكان الذي أصاب تلك المرأة رجلا من غني فأرادت بنو عامر أخذها منه فقال الأحوص لا تأخذوا أخيذة خالي وكانت أم جعفر يعني أبا الأحوص خبية بنت رياح الغنوي وهي إحدى المنجبات ويقال أتى شريح بن الأحوص بتلك المرأة إليه فسألها عن بني تميم فأخبرتهم أنهم لحقوا بقومهم حين بلغهم مجيئكم فدفعها الأحوص إلى الغنوي فقال اعفجها الليلة واحذر أن تنفلت فوطئها الغنوي ثم نام فذهبت على وجهها فلما أصبح دعوا بها فوجدوها قد ذهبت فسألوه عنها فقال هذا حري رطبا من زبها وكانت المرأة يقال لها حنظلة وهي بنت أخي زرارة بن عدس فأتت قومها فسألها عمها زرارة عما رأت فلم تستطع أن تنطق فقال بعضهم اسقوها ماء حارا فإن قلبها قد برد من الفرق ففعلوا وتركوها حتى اطمأنت فقالت يا عم أخذني القوم أمس وهم فيما أرى يريدونكم فاحذر أنت وقومك فقال لا بأس عليك يا بنت أخي فلا تذعري قومك ولا تروعيهم وأخبريني ما هيئة القوم وما نعتهم قالت أخذني قوم يقبلون بوجوه الظباء ويدبرون بأعجاز النساء قال زرارة أولئك بنو عامر فمن رأيت فيهم قالت رأيت رجلا قد سقط حاجباه على عينيه فهو يرفع حاجبيه صغير العينين عن أمره يصدرون قال ذاك الأحوص بن جعفر قالت ورأيت رجلا قليل المنطق إذا تكلم اجتمع القوم لمنطقه كما تجتمع الإبل لفحلها وهو من أحسن الناس وجها ومعه ابنان له لا يدبر أبدا إلا وهما يتبعانه ولا يقبل إلا وهما بين يديه قال ذلك مالك بن جعفر وابناه\nعامر وطفيل قالت ورأيت رجلا أبيض هلقامة جسيما والهلقامة الأفوه وقال ذلك ربيعة بن عبد الله بن أبي بكر بن كلاب قالت ورأيت رجلا أسود أخنس قصيرا إذا تكلم عذم القوم عذم المنخوس قال ذلك ربيعة بن قرط بن عبد بن أبي بكر بن كلاب قالت ورأيت رجلا صغير العينين أقرن الحاجبين كثير شعر السبلة يسيل لعابه على لحيته إذا تكلم قال ذلك حندج بن البكاء قالت ورأيت رجلا صغير العينين ضيق الجبهة طويلا يقود فرسا له معه جفير لا يجاوز يده قال ذلك ربيعة بن عقيل قالت ورأيت رجلا آدم معه ابنان له حسنا الوجه أصبهان إذا أقبلا نظر القوم إليهما حتى ينتهيا وإذا أدبرا نظروا إليهما قال ذلك عمرو بن خويلد بن نفيل بن عمرو بن كلاب وابناه يزيد وزرعة ويقال قالت ورأيت فيهم رجلين أحمرين جسيمين ذوي غدائر لا يفترقان في ممشى ولا مجلس فإذا أدبرا اتبعهما القوم بأبصارهم وإذا أقبلا لم يزالوا ينظرون إليهما حتى يجلسا قال ذانك خويلد وخالد ابنا نفيل قالت ورأيت آدم جسيما كأن رأسه مجز غضورة والغضورة حشيش دقاق خشن قائم يكون بمكة تريد أن شعره قائم خشن كأنه حشيش قد جز قال ذلك عوف بن الأحوص قالت ورأيت رجلا كأن شعر فخذيه حلق الدروع قال ذلك شريح بن الأحوص قالت ورأيت رجلا أسمر طويلا يجول في القوم كأنه غريب قال ذلك عبد الله بن جعدة ويقال قالت ورأيت رجلا","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":18,"spl":"يوم رحرحان الثاني","loc":2029},
{"id":"b116-25","bab":"الجزء 11","sec":"يوم رحرحان الثاني","page":"ج11 ص131","text":"كثير شعر الرأس صخابا لا يدع طائفة من القوم إلا أصخبها قال ذلك عبد الله بن جعدة بن كعب بن ربيعة بن عامر بن صعصعة فسارت بنو عامر نحوهم والتقوا برحرحان وأسر يومئذ معبد بن زرارة أسره عامر بن مالك واشترك في أسره طفيل بن مالك ورجل من غني يقال له أبو عميلة وهو عصمة بن وهب وكان أخا طفيل بن مالك من الرضاعة وكان معبد بن زرارة رجلا كثير المال فوفد لقيط بن زرارة على عامر بن مالك في الشهر الحرام وهو رجب وكانت مضر تدعوه الأصم لأنهم كانوا لا يتنادون فيه يا لفلان ويا لفلان ولا يتغازون ولا يتنادون فيه بالشعارات وهو أيضا منصل الأل والأل الأسنة كانوا إذا دخل رجب أنصلوا الأسنة من الرماح حتى يخرج الشهر وسأل لقيط عامرا أن يطلق أخاه فقال أما حصتي فقد وهبتها لك ولكن أرض أخي وحليفي اللذين اشتركا فيه فجعل لقيط لكل واحد مائة من الإبل فرضيا وأتيا عامرا فأخبراه فقال عامر للقيط دونك أخاك فأطلق عنه فلما أطلق فكر لقيط في نفسه فقال أعطيهم مائتي بعير ثم تكون لهم النعمة علي بعد ذلك لا والله لا أفعل ذلك ورجع إلى عامر فقال إن أبي زرارة نهاني أن أزيد على مائة دية مضر فإن أنتم رضيتم أعطيتكم مائة من الإبل فقالوا لا حاجة لنا في ذلك فانصرف لقيط فقال له معبد مالي يخرجني من أيديهم فأبى ذلك عليه فقال إذا يقتسم العرب بني زرارة فقال معبد لعامر بن مالك يا عامر أنشدك الله لما خليت سبيلي فإنما يريد ابن الحمراء أن يأكل كل مالي ولم تكن أمه أم لقيط فقال له عامر أبعدك الله إن لم يشفق عليك أخوك فأنا أحق ألا أشفق عليك فعمدوا إلى معبد فشدوا عليه القد وبعثوا به إلى الطائف فلم يزل به حتى مات فذلك قول شريح بن الأحوص\n(لقيط وأنت امرؤ ماجد ... ولكن حلمك لا يهتدي)\n(ولما أمنت وساغ الشراب ... واحتل بيتك في ثهمد)\n(رفعت برجليك فوق الفراش ... تهدي القصائد في معبد)\n(وأسلمته عند جد القتال ... وتبخل بالمال أن تفتدي)\nقال في ذلك عوف بن عطية بن الخرع التيمي يعير لقيط بن زرارة\n(هلا فوارس رحرحان هجوتهم ... عشرا تناوح في سرارة واد)\n(لا تأكل الإبل الغراث نباته ... ما إن يقوم عماده بعماد)\n(هلا كررت على أخيك معبد ... والعامري يقوده بصفاد)\n(وذكرت من لبن المحلق شربة ... والخيل تعدو بالصفاح بداد)\nداد متفرقة والصفاح موضع والمحلق موسومة بحلق على وجوهها يقول ذكرت لبنها يعني إبله\n(لو كنت إذ لا تستطيع فديته ... بهجان أدم طارف وتلاد)\n(لكن تركته في عميق قعرها ... جزرا لخامعة وطير عواد)\n(لو كنت مستحيا لعرضك مرة ... قاتلت أو لفديت بالأذواد)\nفيها يقول نابغة بني جعدة\n(هلا سألت بيومي رحرحان وقد ... ظنت هوازن أن العز قد زالا)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":19,"spl":"يوم رحرحان الثاني — بعض ما قاله الشعراء في يوم رحرحان","loc":2030},
{"id":"b116-26","bab":"الجزء 11","sec":"بعض ما قاله الشعراء في يوم رحرحان","page":"ج11 ص136","text":"وفيها يقول مقدام أخو بني عدس بن زيد في الإسلام وقتلت بنو طهية ابنا للقعقاع بن معبد فتوادوا فأخذت بنو طهية منهم الفضل\n(وأنتم بنو ماء السماء زعمتم ... ومات أبوكم يا بني معبد هزلا)\nقال المخبل السعدي يذكر معبدا\n(فإن تك نالتنا كليب بقرة ... فيومك فيهم بالمصيفة أبرد)\n(هم قتلوا يوم المصيفة مالكا ... وشاط بأيديهم لقيط ومعبد)\nفيها يقول عياض بن مرثد بن أسيد بن قريط بن لبيد في الإسلام\n(نحن أسرنا معبدا يوم معبد ... فما افتك حتى مات من شدة الأسر)\n(ونحن قتلنا بالصفا بعد معبد ... أخاه بأطراف الردينية السمر)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":19,"spl":"يوم رحرحان الثاني — بعض ما قاله الشعراء في يوم رحرحان","loc":2031},
{"id":"b116-27","bab":"الجزء 11","sec":"وهذا يوم شعب جبلة السبب في يوم جبلة","page":"ج11 ص137","text":"قال أبو عبيدة وأما يوم جبلة وكان من عظام أيام العرب وكان عظام أيام العرب ثلاثة يوم كلاب ربيعة ويوم جبلة ويوم ذي قار وكان الذي هاج يوم جبلة أن بني عبس بن بغيض حين خرجوا هاربين من بني\nذبيان بن بغيض وحاربوا قومهم خرجوا متلددين فقال الربيع بن زياد العبسي أما والله لأرمين العرب بحجرها اقصدوا لبني عامر فخرج حتى نزل مضيقا من وادي بني عامر ثم قال امكثوا فخرج ربيع وعامر ابنا زياد والحارث بن خليف حتى نزلوا على ربيعة بن شكل بن كعب بن الحريش وكان العقد من بني عامر الى بني كعب بن ربيعة وكانت الرياسة في بني كلاب بن ربيعة فقال ربيعة بن شكل يا بني عبس شأنكم جليل وذحلكم الذي يطلب منكم عظيم وأنا أعلم والله ان هذه الحرب أعز حرب حاربتها العرب قط ولا والله ما بد من بني كلاب فأمهلوني حتى أستطلع طلع قومي فخرج في قوم من بني كعب حتى جاؤوا بني كلاب فلقيهم عوف بن الأحوص فقال يا قوم أطيعوني في هذا الطرف من غطفان فاقتلوهم واغنموهم لا تفلح غطفان بعده أبدا ووالله إن تزيدون على أن تسمنوهم وتمنعوهم ثم يصيروا لقومكم أعداء فأبوا عليه وانقلبوا حتى نزلوا على الأحوص بن جعفر فذكروا له من أمرهم فقال لربيعة بن شكل أظللتهم ظلك وأطعمتهم طعامك قال نعم قال قد والله أجرت القوم فانزلوا القوم وسطهم بحبوحة دارهم وذكر بشر بن عبد الله بن حيان الكلابي أن عبسا لما حاربت قومها أتوا بني عامر وأرادوا عبد الله بن جعدة وابن الحريش ليصيروا حلفاءهم دون كلاب فأتى قيس بن زهير وأقبل نحو بني جعفر هو والربيع بن زياد حتى انتهيا الى الأحوص جالسا قدام بيته فقال قيس للربيع إنه لا حلف ولا ثقة دون أن أنتهي إلى هذا الشيخ فتقدم إليه قيس فأخذ بمجامع ثوبه من وراء فقال هذا مقام العائذ بك قتلتم أبي فما أخذت له عقلا ولا قتلت به أحدا وقد أتيتك\nلتجيرنا فقال الأحوص نعم أنا لك جار مما أجير منه نفسي وعوف بن الأحوص عن ذلك غائب فلما سمع عوف بذلك أتى الأحوص وعنده بنو جعفر فقال يا معشر بني جعفر أطيعوني اليوم وأعصوني أبدا وإن كنت والله فيكم معصيا إنهم والله لو لقوا بني ذبيان لولوكم أطراف الأسنة إذا نكهوا في أفواههم بكلام فابدأوا بهم فاقتلوهم واجعلوهم مثل البرغوث دماغه في دمه فأبوا عليه وحالفوهم فقال والله لا أدخل في هذا الحلف قال وسمعت بهم حيث قر قرارهم بنو ذبيان فحشدوا واستعدوا وخرجوا وعليهم حصن بن حذيفة بن بدر ومعه الحليفان أسد وذبيان يطلبون بدم حذيفة وأقبل معهم شرحبيل بن أخضر بن الجون والجون هو معاوية سمي بذلك لشدة سواده ابن آكل المرار الكندي في جمع من كندة وأقبلت بنو حنظلة بن مالك والرباب عليهم لقيط بن زرارة يطلبون بدم معبد بن زرارة ويثربي بن عدس وأقبل معهم حسان بن عمرو بن الجون في جمع عظيم من كندة وغيرهم فأقبلوا إليهم بوضائع كانت تكون بالحيرة مع الملوك وهم الرابطة وكان في الرباب رجل من اشرافهم يقال له النعمان بن قهوس التيمي وكان معه لواء من سار الى جبلة وكان من فرسان العرب وله تقول دختنوس بنت لقيط بن زرارة يومئذ\n(فر ابن قهوس الشجاع ... بكفه رمح متل)\n(يعدو به خاظي البضيع ... كأنه سمع أزل)\n(إنك من تيم فدع ... غطفان إن ساروا وحلوا)\nمتل مستقيم يتل به كل شيء الخاظي الشيء المكتنز والسمع ولد الضبغ من الذئب والعسبار ولد الذئب من الكلبة\n(لا منك عدهم ولا ... آباك إن هلكوا وذلوا)\n(فخر البغي بحدج ربتها ... إذا الناس استقلوا)\n(لا حدجها ركبت ولا ... لرغال فيه مستظل)\n(ولقد رأيت أباك وسط ... القوم يربق أو يجل)\n(متقلدا ربق الفرار ... كأنه في الجيد غل)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":20,"spl":"وهذا يوم شعب جبلة السبب في يوم جبلة","loc":2032},
{"id":"b116-28","bab":"الجزء 11","sec":"وهذا يوم شعب جبلة السبب في يوم جبلة","page":"ج11 ص137","text":"جل يلقط البعر والفرار أولاد الغنم واحدها فرارة قال وكان معهم رؤساء بني تميم حاجب بن زرارة ولقيط بن زرارة وعمرو بن عمرو وعتيبة بن الحارث بن شهاب وتبعهم غثاء من غثاء الناس يريدون الغنيمة فجمعوا جمعا لم يكن في الجاهلية قط مثله أكثر كثرة فلم تشك العرب في هلاك بني عامر فجاؤوا حتى مروا ببني سعد بن زيد مناة فقالوا لهم سيروا معنا إلى بني عامر فقالت لهم بنو سعد ما كنا لنسير معكم ونحن نزعم أن عامر بن صعصعة ابن سعد بن زيد مناة فقالوا أما إذ أبيتم أن تسيروا معنا فاكتموا علينا فقالوا أما هذا فنعم فلما سمعت بنو عامر بمسيرهم اجتمعوا الى الأحوص بن جعفر وهو يومئذ شيخ كبير قد وقع حاجباه على عينيه وقد ترك الغزو غير أنه يدبر أمر الناس وكان مجربا حازما ميمون\nالنقيبة فأخبروه الخبر فقال لهم الأحوص قد كبرت فما أستطيع أن أجيء بالحزم وقد ذهب الرأي مني ولكني إذا سمعت عرفت فأجمعوا آراءكم ثم بيتوا ليلتكم هذه ثم اغدوا علي فاعرضوا علي آراءكم ففعلوا فلما أصبحوا غدوا عليه فوضعت له عباءة بفنائه فجلس عليها ورفع حاجبيه عن عينيه بعصابة ثم قال هاتوا ما عندكم فقال قيس بن زهير العبسي بات في كنانتي الليلة مائة رأي فقال له الأحوص يكفينا منها رأي واحد حازم صليب مصيب هات فانثر كنانتك فجعل يعرض كل رأي رآه حتى أنفد فقال له الأحوص ما أرى بات في كنانتك الليلة رأي واحد وعرض الناس آراءهم حتى أنفدوا فقال ما أسمع شيئا وقد صرتم إلي احملوا أثقالكم وضعفاءكم ففعلوا ثم قال احملوا ظعنكم فحملوها ثم قال اركبوا فركبوا وجعلوه في محفة وقال انطلقوا حتى تعلوا في اليمين فإن أدرككم أحد كررتم عليه وإن أعجزتموهم مضيتم فسار الناس حتى أتوا وادي بحار ضحوة فإذا الناس يرجع بعضهم على بعض فقال الأحوص ما هذا قيل هذا عمرو بن عبد الله بن جعدة في فتيان من بني عامر يعقرون بمن أجاز بهم ويقطعون بالنساء حواياهن فقال الأحوص قدموني فقدموه حتى وقف عليهم فقال ما هذا الذي تصنعون قال عمرو أردت أن تفضحنا وتخرجنا هاربين من بلادنا ونحن أعز العرب وأكثرهم عددا وجلدا وأحدهم شوكة تريد أن تجعلنا موالي في\nالعرب إذ خرجت بنا هاربا قال فكيف أفعل وقد جاءنا ما لا طاقة لنا به فما الرأي قال نرجع الى شعب جبلة فنحرز النساء والضعفة والذراري والأموال في رأسه ونكون في وسطه ففيه ثمل أي خصب وماء فإن أقام من جاءك أسفل أقاموا على غير ماء ولا مقام لهم وإن صعدوا عليك قاتلتهم من فوق رؤوسهم بالحجارة فكنت في حرز وكانوا في غير حرز وكنت على قتالهم أقوى منهم على قتالك قال هذا والله الرأي فأين كان هذا عنك حين استشرت الناس قال إنما جاءني الآن قال الأحوص للناس ارجعوا فرجعوا ففي ذلك يقول نابغة بني جعدة\n(ونحن حبسنا الحي عبسا وعامرا ... لحسان وابن الجون إذ قيل أقبلا)\n(وقد صعدت وادي بحار نساؤهم ... كإصعاد نسر لا يرومون منزلا)\n(عطفنا لهم عطف الضروس فصادفوا ... من الهضبة الحمراء عزا ومعقلا)\nلضروس الناقة العضوض فدخلوا شعب جبلة وجبلة هضبة حمراء بين الشريف والشرف والشريف ماء لبني نمير والشرف ماء لبني كلاب وجبلة جبل عظيم له شعب عظيم واسع لا يؤتى الجبل إلا من قبل الشعب والشعب متقارب المدخل وداخله متسع وبه اليوم عرينة من بجيلة فدخلت بنو عامر شعبا منه يقال له مسلح فحصنوا النساء والذراري والأموال في رأس الجبل وحلؤوا الإبل عن الماء واقتسموا الشعب بالقداح فأقرع بين القبائل في شظاياه فخرجت بنو تميم ومعهم بارق حي من الأزد حلفاء يومئذ لبني نمير وبارق هو سعد بن عدي بن حارثة بن عمرو مزيقياء بن\nعامر ماء السماء وسمي مزيقياء لأنه كان يمزق عليه كل يوم حلة فولجوا الخليف والخليف الطريق بين الشعبين شبه الزقاق لأن سهمهم تخلف وفيه يقول معقر بن أوس بن حمار البارقي\n(ونحن الأيمنون بنو نمير ... يسيل بنا أمامهم الخليف)\nال وكان معقر يومئذ شيخا كبيرا أعمى ومعه ابنة له تقود به جمله فجعل يقول لها من أسهل من الناس فتخبره وتقول هؤلاء بنو فلان وهؤلاء بنو فلان حتى إذا تناهى الناس قال اهبطي لا يزال هذا الشعب منيعا سائر هذا اليوم وهبط وكانت كبشة بنت عروة الرحال بن عتبة بن جعفر بن كلاب يومئذ حاملا بعامر بن الطفيل فقالت ويلكم يا بني عامر ارفعوني فوالله إن في بطني لعز بني عامر","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":21,"spl":"وهذا يوم شعب جبلة السبب في يوم جبلة","loc":2033},
{"id":"b116-29","bab":"الجزء 11","sec":"القبائل التي شهدت وقعة جبلة","page":"ج11 ص143","text":"فصفوا القسي على عواتقهم ثم حملوها حتى أثووها بالقنة يقال قنة وقنان فزعموا أنها ولدت عامرا يوم فرغ الناس من القتال فشهدت بنو عامر كلها جبلة إلا هلال بن عامر وعامر بن ربيعة بن عامر وشهدها مع بني عامر من العرب بنو عبس بن رفاعة بن الحارث بن بهثة بن سليم وكان لهم بأس وحزم وعليهم مرداس بن أبي عامر وهو أبو العباس بن مرداس وكانت بنو عبس بن رفاعة حلفاء بني عمرو بن كلاب وزعم بعض بني عامر أن مرداسا كان مع أخواله غني وكانت أمه فاطمة بنت جلهمة الغنوية وشهدتها غني وباهلة وناس من بني سعد بن بكر وقبائل بجيلة كلها إلا قسرا\nلحرب كانت بين قسر وقومها فارتحلت بجيلة فتفرقت في بطون بني عامر فكانت عادية بن عامر بن قداد من بجيلة في بني عامر بن ربيعة وكانت سحمة من بجيلة في بني جعفر بن كلاب ويقال عمرو بن كلاب وكانت عرينة من بجيلة في عمرو بن كلاب وكانت بنو قيس كبة لفرس يقال لها كبة من بجيلة في بني عامر بن ربيعة وكانت فتيان في بني عامر بن ربيعة وبنو قطيعة من بجيلة في بني أبي بكر بن كلاب ونصيب بن عبد الله من بجيلة في بني نمير وكانت ثعلبة والخطام من بجيلة في بني عامر بن ربيعة وبنو عمرو بن معاوية بن زيد من بجيلة في بني أبي بكر بن كلاب معهم يومئذ نفير من عكل فبلغ جمعهم ثلاثين ألفا وعمي على بني عامر الخبر فجعلوا لا يدرون ما قرب القوم من بعدهم وأقبلت تميم وأسد وذبيان ولفهم نحو جبلة فلقوا كرب بن صفوان بن شجنة بن عطارد بن عوف بن كعب بن سعد بن زيد مناة فقالوا له أين تذهب أتريد أن تنذر بنا بني عامر قال لا قالوا فأعطنا عهدا وموثقا ألا تفعل فأعطاهم فخلوا سبيله فمضى مسرعا على فرس له عري حتى إذا نظر إلى مجلس بني عامر وفيهم الأحوص نزل تحت شجرة حيث يرونه فأرسلوا إليه يدعونه قال لست فاعلا ولكن إذا رحلت فأتوا منزلي فإن الخبر فيه فلما جاؤوا منزله إذا فيه تراب في صرة وشوك قد كسر رؤوسه وفرق جهته وإذا حنظلة موضوعة وإذا وطب معلق فيه لبن فقال الأحوص هذا رجل قد أخذ عليه المواثيق ألا يتكلم وهو يخبركم أن القوم مثل التراب كثرة وأن شوكتهم كليلة وهم متفرقون وجاءتكم بنو حنظلة انظروا ما في الوطب فاصطبوه فإذا فيه لبن حزر قرص\nفقال القوم منك على قدر حلاب اللبن إلى أن يحزر فقال رجل من بني يربوع ويقال قالته دختنوس بنت لقيط بن زرارة\n(كرب بن صفوان بن شجنة لم يدع ... من دارم أحدا ولا من نهشل)\n(أجعلت يربوعا كقورة دائر ... ولتحلفن بالله أن لم تفعل)\nوذلك قول عامر بن الطفيل بعد جبلة بحين\n(ألا أبلغ جموع سعد ... فبيتوا لن نهيجكم نياما)\n(نصحتم بالمغيب ولم تعينوا ... علينا إنكم كنتم كراما)\n(ولو كنتم مع أبن الجون كنتم ... كمن أودى وأصبح قد ألاما)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":22,"spl":"القبائل التي شهدت وقعة جبلة","loc":2034},
{"id":"b116-30","bab":"الجزء 11","sec":"تشاور الأعداء في الصعود الى بني عامر","page":"ج11 ص145","text":"فلما أستيقنت بنو عامر بإقبالهم صعدوا الشعب وأمر الأحوص بالإبل التي ظمئت قبل ذلك فقال اعقلوها كل بعير بعقالين في يديه جميعا وأصبح لقيط والناس نزول به وكانت مشورتهم إلى لقيط فاستقبلهم جمل عود أجرب أحذ أعصل كاشر عن أنيابه فقال الحزاة من بني أسد والحازي العائف اعقروه فقال لقيط والله لا يعقر حتى يكون فحل إبلي\nغدا وكان البعير من عصافير المنذر التي أخذها قرة بن هبيرة بن عامر بن سلمة بن قشير والعصافير إبل كانت للملوك نجائب ثم أستقبلهم معاوية بن عبادة بن عقيل وكان أعسر فقال\n(أنا الغلام الأعسر ... الخير في والشر)\n(والشر في أكثر ... )\nتشاءمت بنو أسد وقالوا ارجعوا عنهم وأطيعونا فرجعت بنو أسد فلم تشهد جبلة مع لقيط إلا نفيرا يسيرا منهم شأس بن أبي بلي أبو عمرو بن شأس الشاعر ومعقل بن عامر بن موءلة المالكي وقال الناس للقيط ما ترى فقال أرى أن تصعدوا إليهم فقال شأس لا تدخلوا على بني عامر فإني أعلم الناس بهم قد قاتلتهم وقاتلوني وهزمتهم وهزموني فما رأيت قوما قطد أقلق بمنزل من بني عامر والله ما وجدت لهم مثلا إلا الشجاع فإنه لا يقر في جحره قلقا وسيخرجون إليكم والله لئن بتم هذه الليلة لا تشعرون بهم إلا وهم منحدرون عليكم فقال لقيط والله لندخلن عليهم فأتوهم وقد أخذوا حذرهم وجعل الأحوص أبنه شريحا على تعبئة الناس فأقبل لقيط وأصحابه مدلين فأسندوا الى الجبل حتى ذرت الشمس فصعد لقيط في الناس وأخذ بحافتي الشجن فقالت بنو عامر للأحوص قد أتوك فقال دعوهم حتى إذا نصفوا الجبل وانتشروا فيه قال الأحوص حلوا عقل الإبل ثم احدروها واتبعوا آثارها وليتبع كل رجل منكم بعيره حجرين أو ثلاثة ففعلوا ثم صاحوا بها فلم يفجا الناس إلا الإبل تريد الماء والمرعى وجعلوا يرمونهم بالحجارة والنبل وأقبلت الإبل تحطم كل شيء مرت به وجعل البعير يدهدي بيديه كذا وكذا حجرا وقد كان لقيط وأصحابه سخروا منهم حين صنعوا بالإبل ما صنعوا فقال رجل من بني أسد\n(زعمت أن العير لا تقاتل ... بلى إذا تقعقع الرحائل)\n(واختلف الهندي والذوابل ... وقالت الأبطال من ينازل)\n(بلى وفيها حسب ونائل ... )\nعر بني عامر في يوم جبلة فانحط الناس منهزمين من الجبل حتى السهل فلما بلغ الناس السهل لم يكن لأحد منهم همة إلا أن يذهب على وجهه فجعلت بنو عامر يقتلونهم ويصرعونهم بالسيوف في آثارهم فانهزموا شر الهزيمة فجعل رجل من بني عامر يومئذ يرتجز ويقول\n(لم أر يوما مثل يوم جبله ... يوم أتتنا أسد وحنظله)\n(وغطفان والملوك أزفله ... نضربهم بقضب منتخله)\n(لم تعد أن أفرش عنها الصقله ... حتى حدوناهم حداء الزومله)\nجعل معقل بن عامر يرتجز ويقول\n(نحن حماة الشعب يوم جبله ... بكل عضب صارم ومعبله)\n(وهيكل نهد معا وهيكله ... )\nالمعبلة السهم إذا كان نصله عريضا فهو معبلة والرقيق القطبة وخرجت بنو تميم من الخليف على الخيل فكركروا الناس يعني ردوهم وانقطع شريح بن الأحوص في فرسان حتى أخذ الجرف فقاتل الناس قتالا شديدا هناك وجعل لقيط يومئذ وهو على برذون له مجفف بديباج أعطاه إياه كسرى وكان أول عربي جفف يقول\n(عرفتكم والدمع م العين يكف ... لفارس أتلفتموه ما خلف)\n(إن النشيل والشواء والرغف ... والقينة الحسناء والكأس الأنف)\n(وصفوة القدر وتعجيل اللقف ... للطاعنين الخيل والخيل قطف)\nجعل لا يمر به أحد من الجيش إلا قال له أنت والله قتلتنا وشتمتنا فجعل يقول\n(يا قوم قد أحرقتموني باللوم ... ولم أقاتل عامرا قبل اليوم)\n(فاليوم إذ قاتلتهم فلا لوم ... تقدموا وقدموني للقوم)\n(شتان هذا والعناق والنوم ... والمضجع البارد في ظل الدوم)\nقال شأس بن أبي بلي يجيبه\n(لكن أنا قاتلتها قبل اليوم ... إذ كنت لا تعصى أموري في القوم)\nجعل لقيط يقول من كر فله خمسون ناقة وجعل يقول\n(أكلكم يزجركم أرحب هلا ... ولن تروه الدهر إلا مقبلا)\n(يحمل زغفا ورئيسا حجفلا ... وسائلا في أهله ما فعلا)\nوجعل يقول أيضا\n(أشقر إن لم تتقدم تنحر ... وإن تأخر عن هياج تعقر)\nثم عاد يقول\n(إن الشواء والنشيل والرغف ... )\nأجابه شريح بن الأحوص\n(إن كنت ذا صدق فأقحمه الجرف ... وقرب الأشقر حتى تعترف)\n(وجوهنا إنا بنوالبيض العطف ... )","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":23,"spl":"تشاور الأعداء في الصعود الى بني عامر","loc":2035,"partial":1},
{"id":"b116-31","bab":"الجزء 11","sec":"تشاور الأعداء في الصعود الى بني عامر","page":"ج11 ص145","text":"وبينه وبينه جرف منكر فضرب لقيط فرسه وأقحمه عليه الجرف فطعنه شريح فسقط وقد اختلفوا في ذلك فذكروا أن الذي طعنه جزء بن خالد بن جعفر وبنو عقيل تزعم أن عوف بن المنتفق العقيلي قتله يومئذ وأنشأ يقول\n(ظلت تلوم لما بها عرسي ... جهلا وأنت حليمة أمس)\n(إن تقتلوا بكري وصاحبه ... فلقد شفيت بسيفه نفسي)\n(فقتلته في الشعب أول فارس ... في الشرق قبل ترحل الشمس)\nزعموا أن عوفا هذا قتل يومئذ ستة نفر وقتل ابن له وابن أخ له وأما العلماء فلا يشكون أن شريحا قتله وأرتث وبه طعنات والارتثاث أن يحمل وهو مجروح فإن حمل ميتا فليس بمرتث فبقي يوما ثم مات فجعل لقيط يقول عند موته\n(يا ليت شعري عنك دختنوس ... إذا أتاك الخبر المرسوس)\n(أتحلق القرون أم تميس ... لا بل تميس إنها عروس)\nختنوس بنت لقيط بن زرارة وكانت تحت عمرو بن عمرو بن عدس وجعلت بنو عبس يضربونه وهو ميت فقالت دختنوس\n(ألا يالها الويلات ويلات من بكى ... لضرب بني عبس لقيطا وقد قضى)\n(لقد ضربوا وجها عليه مهابة ... وما تحفل الصم الجنادل من ردى)\n(فلو أنكم كنتم غداة لقيتم ... لقيطا صبرتم للأسنة والقنا)\n(غدرتم ولكن كنتم مثل خضب ... أصاب لها القناص من جانب الشرى)\n(فما ثأره فيكم ولكن ثأره ... شريح وأردته الأسنة إذ هوى)\n(فإن تعقب الأيام من عامر يكن ... عليهم حريقا لا يرام إذا سما)\n(ليجزيهم بالقتل قتلا مضعفا ... وما في دماء الحمس يا مال من بوا)\n(ولو قتلتنا غالب كان قتلها ... علينا من العار المجدع للعلا)\n(لقد صبرت للموت كعب وحافظت ... كلاب وما أنتم هناك لمن رأى)\nقالت دختنوس أيضا\n(لعمري لئن لاقت من الشر دارم ... عناء لقد آبت حميدا ضرابها)\n(فما جبنوا بالشعب إذ صبرت لهم ... ربيعة يدعى كعبها وكلابها)\n(عصوا بسيوف الهند وأعتكرت لهم ... براكاء موت لا يطير غرابها)\nراكاء مباركة القتال وهو الجد في القتال يقال للرجل إذا وقع في خطب لا يطير غرابه وقالت دختنوس\n(بكر النعي بخير خندف ... كهلها وشبابها)\n(وبخيرها نسبا إذا ... عدت إلى أنسابها)\n(فرت بنو أسد حرود ... الطير عن أربابها)\n(لم يحفلوا نسبا ولم ... يلووا لفيء عقابها)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":24,"spl":"تشاور الأعداء في الصعود الى بني عامر","loc":2036},
{"id":"b116-32","bab":"الجزء 11","sec":"اخبار الذين نجوا أو قتلوا في الموقعة","page":"ج11 ص152","text":"وقتل يومئذ قريظ بن معبد بن زرارة وزيد بن عمرو بن عدس قتله الحارث بن الأبرص بن ربيعة بن عامر بن عقيل وقتل الفلتان بن المنذر بن سلمى بن جندل بن نهشل وقتل أبو إياس بن حرملة بن جعدة بن العجلان بن حشورة بن عجب بن ثعلبة بن سعد بن ذبيان وهو يقول\n(أقدم قطين إنهم بنو عبس ... المعشر الحلة في القوم الحمس)\nلحلة لم يكونوا يتشددون في دينهم قال واستلحم عمرو بن حسحاس بن وهب بن أعياء بن طريف الأسدي فاستنقذه معقل بن عامر بن موءلة فداواه وكساه فقال معقل في ذلك\n(يديت على ابن حسحاس بن وهب ... بأسفل ذي الجذاة يد الكريم)\n(قصرت له من الدهماء لما ... شهدت وغاب من له من حميم)\n(ولو أني أشاء لكنت منه ... مكان الفرقدين من النجوم)\n(أخبره بأن الجرح يشوي ... وأنك فوق عجلزة جموم)\nقول إن الجرح الذي بك شوى لم يصب منك مقتلا\n(ذكرت تعلة الفتيان يوما ... وإلحاق الملامة بالمليم)\nال وحمل معاوية بن يزيد الفزاري فأخذ كبشة بنت الحجاج بن معاوية بن قشير وكانت عند مالك بن خفاجة بن عمرو بن عقيل فحمل معاوية بن خفاجة أخو مالك على معاوية بن يزيد فقتله واستنقذ كبشة وقال يا بني عامر إنهم يموتون وقد كان قيل لهم إنهم لا يموتون ونزل حسان بن عامر بن الجون وصاح يا آل كندة فحمل عليه شريح بن الأحوص فاعترض دون ابن الجون رجل من كندة يقال له حوشب فضربه شريح بن الأحوص في رأسه فانكسر السيف فيه فخرج يعدو بنصف السيف وكان مما رعب الناس مكانه وشد طفيل بن مالك بن جعفر فأسر حسان بن الجون وشد عوف بن الأحوص على معاوية بن الجون فأسره وجز ناصيته وأعتقه على الثواب فلقيته بنو عبس فأخذه قيس بن زهير فقتله فأتاهم عوف فقال قتلتم طليقي فأحيوه أو ائتوني بملك مثله فتخوفت بنو عبس شره وكان مهيبا فقالوا أمهلنا فانطلقوا حتى أتوا أبا براء عامر بن مالك بن جعفر يستغيثونه على عوف فقال دونكم سلمى بن مالك فإنه نديمه وصديقه وكانا مشتبهين أحمرين أشقرين ضخمة أنوفهما وكان في سلمى حياء فأتوه فقال سأكلم لكم طفيلا حتى يأخذ أخاه فإنه لا ينجيكم من عوف إلا ذلك وأيم الله\nليأتين شحيحا فانطلقوا إليه فقال طفيل قد أتوني بك ما أعرفني بما جئتم له أتيتموني تريدون مني ابن الجون تقيدون به من عوف خذوه فأعطاهم إياه فأتوا به عوفا فجز ناصيته وأعتقه فسمي الجزاز فذلك قول نافع بن الخنجر بن الحكم بن عقيل بن طفيل بن مالك في الإسلام\n(قضينا الجون عن عبس وكانت ... منية معبد فينا هزالا)\nال وشهدها لبيد بن ربيعة بن مالك بن جعفر وهو ابن تسع سنين ويقال كان ابن بضع عشرة سنة وعامر بن مالك يقول له اليوم يتمت من أبيك إن قتل أعمامك وقتل يومئذ زهير بن عمرو بن معاوية وجد مقتولا بين ظهراني صفوف بني عامر حيث لم يبلغ القتال وهو معاوية الضباب بن كلاب فقال أخوه حصين للذي قتله\n(يا ضبعا عثواء لا تستأنسي ... تلتقم الهبر من السقب الرذي)\n(أقسم بالله وما حجت بلي ... وما على العزى تعزه غني)\n(وقد حلفت عند منحر الهدي ... أعطيكم غير صدور المشرفي)\n(فليس مثلي عن زهير بغني ... هو الشجاع والخطيب اللوذعي)\n(والفارس الحازم والشهم الأبي ... والحامل الثقل إذا ينزل بي)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":25,"spl":"اخبار الذين نجوا أو قتلوا في الموقعة","loc":2037},
{"id":"b116-33","bab":"الجزء 11","sec":"اخبار الذين نجوا أو قتلوا في الموقعة","page":"ج11 ص152","text":"وذكروا أن طفيل بن مالك لما رأى القتال يوم جبلة قال ويلكم وأين نعم هؤلاء فأغار على نعم عمرو وإخوته وهم من بني عبدالله بن غطفان ثم من بني الثرماء فاستاق ألف بعير فلقيه عبيدة بن مالك فاستجداه فأعطاه مائة بعير وقال كأني بك قد لقيت ظبيان بن مرة بن خالد فقال لك أعطاك من ألفه مائة فجئت مغضبا فلقي عبيدة ظبيان فقال له كم أعطاك قال مائة فقال أمائة من ألف فغضب عبيدة قال وذكر أن عبيدة تسرع يومئذ إلى القتال فنهاه أخواه عامر وطفيل أن يفعل حتى يرى مقاتلا فعصاهما وتقدم فطعنه رجل في كتفه حتى خرج السنان من فوق ثديه فاستمسك فيه السنان فأتى طفيلا فقال له دونك السنان فانزعه فأبى أن يفعل ذلك غضبا فأتى عامرا فلم ينزعه منه غضبا فأتى سلمى بن مالك فانتزعته منه وألقي جريحا مع النساء حتى فرغ القوم من القتال وقتلت بنو عامر يومئذ من تميم ثلاثين غلاما أغرل وخرج حاجب بن زرارة منهزما وتبعه الزهدمان زهدم وقيس ابنا حزن بن وهب بن عويمر بن رواحة العبسيان فجعلا يطردان حاجبا ويقولان له استأسر وقد قدرا عليه فيقول من أنتما فيقولان الزهدمان فيقول لا أستأسر اليوم لموليين فبينما هم كذلك إذ أدركهم مالك ذو الرقيبة بن سلمة بن قشير فقال لحاجب استأسر قال ومن أنت قال أنا مالك ذو الرقيبة فقال أفعل فلعمري ما أدركتني حتى كدت أن أكون عبدا فألقى إليه رمحه واعتنقه زهدم فألقاه عن فرسه فصاح حاجب يا\nغوثاه وندر السيف وجعل زهدم يريغ قائم السيف فنزل مالك فاقتلع زهدما عن حاجب فمضى زهدم وأخوه حتى أتيا قيس بن زهير بن جذيمة فقالا أخذ مالك أسيرنا من أيدينا قال ومن أسيركما قالا حاجب بن زرارة فخرج قيس يتمثل قول حنظلة بن الشرقي القيني أبي الطمحان رافعا صوته يقول\n(أجد بني الشرقي اولع أنني ... متى أستجر جارا وإن عز يغدر)\n(إذا قلت أوفى أدركته دروكة ... فيا موزع الجيران بالغي أقصر)\nتى وقف على بني عامر فقال إن صاحبكم أخذ أسيرنا قالوا من صاحبنا قال مالك ذو الرقيبة أخذ حاجبا من الزهدمين فجاءهم مالك فقال لم آخذه منهما ولكنه استأسر لي وتركهما فلم يبرحوا حتى حكموا حاجبا في ذلك وهو في بيت ذي الرقيبة فقالوا من أسرك يا حاجب فقال أما من ردني عن قصدي ومنعني أن أنجو ورأى مني عورة فتركها فالزهدمان وأما الذي استأسرت له فمالك فحكموني في نفسي قال له القوم قد جعلنا إليك الحكم في نفسك يقال أما مالك فله ألف ناقة وللزهدمين مائة فكان بين قيس بن زهير وبين الزهدمين مغاضبة بعد ذلك فقال قيس\n(جزاني الزهدمان جزاء سوء ... وكنت المرء يجزى بالكرامه)\n(وقد دافعت قد علمت معد ... بني قرط وعمهم قدامه)\n(ركبت بهم طريق الحق حتى ... أثبتهم بها مائة ظلامه)\nقال جرير في ذلك\n(ويوم الشعب قد تركوا لقيطا ... كأن عليه حلة أرجوان)\n(وكبل حاجب بشمام حولا ... فحكم ذا الرقيبة وهو عاني)\nأما عمرو بن عمرو بن عدس فأفلت يومئذ فزعمت بنو سليم أن الخيل عرضت على مرداس بن أبي عامر يوم جبلة وكان أبصر الناس بالخيل فعرضت عليه فرس لغلام من بني كلاب فقال والله لا أعجزها ولا أدركها ذكر ولا أنثى فهذا ردائي بها وخمس وعشرون ناقة فلما انهزم الناس يوم جبلة خرج الكلابي على فرسه تلك يطلب عمرو بن عمرو قال الكلابي فراكضته نهارا على السواء والله ما علمت أنه سبقني بمقدار أعرفه ثم زاد مكانه ونقصت فقلت قمر والله مرداس وهوى عمرو إلى فرسه فضربها بالسوط فانكشفت فإذا هي خنثى لا ذكر ولا أنثى فأخبرتهم أني سبقت فقالوا قمر السلمي فقلت لا ثم أخبرتهم الخبر فقال مرداس\n(تمطت كميت كالهراوة ضامر ... لعمرو بن عمرو بعد ما مس باليد)\n(فلولا مدى الخنثى وبعد جرائها ... لقاظ ضعيف النهض حق مقيد)\n(تذكر ربطا بالعراق وراحة ... وقد خفق الأسياف فوق المقلد)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":26,"spl":"اخبار الذين نجوا أو قتلوا في الموقعة","loc":2038},
{"id":"b116-34","bab":"الجزء 11","sec":"اخبار الذين نجوا أو قتلوا في الموقعة","page":"ج11 ص152","text":"وزعم علماء بني عامر أنه لما انهزم الناس خرجت بنو عامر وحلفاؤهم في آثارهم يقتلون ويأسرون ويسلبون فلحق قيس بن المنتفق بن عامر بن طفيل بن عقيل عمرو بن عمرو فأسره فأقبل الحارث بن الأبرص بن ربيعة بن عقيل في سرعان الخيل فرآه عمرو مقبلا فقال لقيس إن أدركني الحارث قتلني وفاتك ما تلتمس عندي فهل أنت محسن إلي وإلى نفسك تجز ناصيتي فتجعلها في كنانتك ولك العهد لأفين لك ففعل وأدركهما الحارث وهو ينادي قيسا ويقول أقتل أقتل فلحق عمرو بقومه فلما كان الشهر الحرام خرج قيس إلى عمرو يستثيبه وتبعه الحارث بن الأبرص حتى قدما على عمرو بن عمرو فأمر عمرو بن عمرو ابنة أخية آمنة بنت زيد بن عمرو فقال اضربي على قيس الذي أنعم على عمك هذه القبة وقد كان الحارث قتل أباها زيدا يوم جبلة فجاءت بالقبة فرأت الحارث أهيأهما وأجملهما فظنته قيسا فضربت القبة على رأسه وهي تقول هذا والله رجل لم يطلع الدهر عليه بما اطلع به علي فلما رجعت إلى عمها عمرو قال يابنة أخي على من ضربت القبة فنعتت له نعت الحارث فقال ضربتها والله على رجل قتل أباك وأمر بقتل عمك فجزعت مما قال لها عمها فقال الحارث بن الأبرص\n(أما تدرين يابنة آل زيد ... أمين بما أجن اليوم صدري)\n(فكم من فارس لم ترزئيه ... فتى الفتيان في عيص وقصر)\n(رأيت مكانه فصددت عنه ... فأعيا أمره وشددت أزري)\n(لقد آمرته فعصى إماري ... بأم عزيمة في جنب عمرو)\n(أمرت به لتخمش حنتاه ... فضيع أمره قيس وأمري)\nالحنة الزوجة يقال حنته وطلته ثم إن عمرا قال يا حار مالذي جاء بك فوالله مالك عندي نعمة ولقد كنت سيء الرأي في قتلت أخي وأمرت بقتلي فقال بل كففت عنك ولو شئت إذ أدركتك لقتلتك قال ما لك عندي من يد ثم تذمم منه فأعطاه مائة من الإبل ثم انطلق فذهب الحارث فلما جاء عمرا قيس أعطاه إبلا كثيرة فخرج قيس بها حتى إذا دنا من أهله سمع به الحارث بن الأبرص فخرج في فوارس من بني أبيه حتى عرض لقيس فأخذ ما كان معه فلما أتى قيس بني أبيه بني المنتفق اجتمعوا إليه وأرادوا الخروج فقال مهلا لا تقاتلوا إخوتكم فإنه يوشك أن يرجع وأن يؤول إلى الحق فإنه رجل حسود فلما رأى الحارث أن قيسا قد كف عنه رد إليه ما أخذ منه وأما عتيبة بن الحارث بن شهاب فإنه أسر يومئذ فقيد في القد وكان يبول على قده حتى عفن فلما دخل الشهر الحرام هرب فأفلت منهم بغير فداء وغنم مرداس بن أبي عامر غنائم وأخذ رجلا فأخذ منه مائة ناقة فانتزعها منه بنو أبي بكر بن كلاب فخرج مرداس إلى يزيد بن الصعق وكان له خليلا فانتهى إليه مرداس وهو يقول\n(لعمرك ما ترجو معد ربيعها ... رجائي يزيدا بل رجائي أكثر)\n(يزيد بن عمرو خير من شد ناقة ... بأقتادها إذا الرياح تصرصر)\n(تداعت بنو بكر علي كأنما ... تداعت علي بالأحزة بربر)\n(تداعوا علي أن رأوني بخلوة ... وأنتم بأحدان الفوارس أبصر)\nيروى بوحدان فركب يزيد حتى أخذ الإبل من بني أبي بكر فردها إليه فطرقه البكريون فسقوه الخمر حتى سكر ثم سألوه الإبل فأعطاهم إياها فلما أصبح ندم فخرج إلى يزيد فوجد الخبر قد جاءه فقال له يزيد أصاح أنت أم سكران فانصرف فاطرد إبلا من إبل بني جعفر فذهب بها وأنشأ يقول\n(أجن بليلى قلبه أم تذكرا ... منازل منها حول قرى ومحضرا)\n(تخر الهدال فوق خيمات أهلها ... ويرسون حسا بالعقال مؤطرا)\nلحس الفرس الخفيفة والمؤطر المعطوف\n(سآبى وأستغني كما قد أمرتني ... وأصرف عنك العسر لست بأفقرا)\n(وإن سليما والحجاز مكانها ... متى آتهم أجد لبيتي مهجرا)\nلمهجر الموضع الصالح يقال هذا أهجر من هذا إذا كان أجود منه وأصلح\n(يفرج عني حدهم وعديدهم ... وأسرج لبدي خارجيا مصدرا)\n(قصرت عليه الحالبين فجوده ... إذا ما عدا بل الحزام وأمطرا)\nالحالبين الراعيين يقول احتبستهما\n(فخذ إبلا إن العتاب كما ترى ... على خذم ثم ارم للنصر جعفرا)\n(فإن بأكناف البحار إلى الملا ... وذي النخل مصحى إن صحوت ومسكرا)\n(وأرعى من الأظلاف أثلا وحمضة ... وترعى من الأطواء أثلا وعرعرا)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":27,"spl":"اخبار الذين نجوا أو قتلوا في الموقعة","loc":2039},
{"id":"b116-35","bab":"الجزء 11","sec":"اخبار الذين نجوا أو قتلوا في الموقعة","page":"ج11 ص152","text":"انصرف يومئذ سنان بن أبي حارثة المري في بني ذبيان على حاميته فلحق بهم معاوية بن الصموت بن الكامل الكلابي وكان يسمى الأسد المجدع ومعه حرملة العكلي ونفر من الناس فلحق بسنان بن أبي حارثة ومالك بن حمار الفزاري في سبعين فارسا من بني ذبيان فقال سنان يا مالك كر واحمنا ولك خولة بنت سنان ابنتي أزوجكها فكر مالك فقتل معاوية ثم اتبعه حرملة العكلي وهو يقول\n(لأي يوم يخبأ المرء السعه ... مودع ولا ترى فيه الدعه)\nكر عليه مالك فقتله ثم اتبعه رجل من بني كلاب فكر عليه مالك فقتله ثم اتبعه رجلان من قيس كبة من بجيلة فكر عليهما فقتلهما ومضى مالك وأصحابه فقال مالك في ذلك\n(ولقد صددت عن الغنيمة حرملا ... ولقيته لددا وخيلي تطرد)\n(أقبلته صدر الأغر وصارما ... ذكرا فخر على اليدين الأبعد)\n(وابن الصموت تركت حين لقيته ... في صدر مارنة يقوم ويقعد)\n(وابنا ربيعة في الغبار كلاهما ... وابنا غني عامروالأسود)\n(حتى تنفس بعد نكظ مجحرا ... أذهبت عنه والفرائص ترعد)\nلنكظ الجهد قال\n(يعدو ببزي سابح ذو ميعة ... نهد المراكل ذو تليل أقود)\nخطب إليه مالك خولة فأبى أن يزوجه وأما بنو جعفر فيزعمون أن عروة الرحال بن عتبة بن جعفر وجد سنان بن أبي حارثة وابنيه هرما ويزيد على غدير قد كاد العطش أن يهلكهم فجز نواصيهم وأعتقهم ثم إن عروة أتى سنانا بعد ذلك يستثيبه ثوابا يرضاه فلم يثبه شيئا فقال عروة في ذلك\n(ألا من مبلغ عني سنانا ... ألوكا لا أريد بها عتابا)\n(أفي الخضراء تقسم هجمتيكم ... وعروة لم يثب الا الترابا)\n(فلو كان الجعافر طاوعوني ... غداة الشعب لم نذق الشرابا)\n(أتجزي القين نعمتها عليكم ... ولا تجزي بنعمتها كلابا)\nأما بنو عامر فيزعمون أن سنانا انصرف ذات يوم هو وناس من طيىء وغيرهم قبل الوقعة فبلغه أن بني عامر يقولون مننا عليه فأنشأ يقول\n(والله ما منوا ولكن شكتي ... منت وحادرة المناكب صلدم)\n(بخرير شول يوم يدعى عامر ... لا عاجز ورع ولا مستسلم)\nأما مارق فتدعي أسر سنان يومئذ على الثواب ثم أتوه فلم يصنع بهم خيرا فقال معقر بن أوس بن حمار البارقي\n(متى تك في ذبيان منك صنيعة ... فلا تحمدنها الدهر بعد سنان)\n(يظل يمنينا بحسن ثوابه ... لكم مائة يحدو بها فرسان)\n(مخاض أؤديها وجل لقائح ... وأكرم مثوى منكم من اتاني)\n(فجئناه للنعمى فكان ثوابه ... رغوث ووطبا حازر مذقان)\n(وظل ثلاثا يسأل الحي ما يرى ... يؤامرهم فينا له أملان)\n(فإن كنت هذا الدهر لا بد شاكرا ... فلا تثقن بالشكر في غطفان)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":28,"spl":"اخبار الذين نجوا أو قتلوا في الموقعة","loc":2040},
{"id":"b116-36","bab":"الجزء 11","sec":"تأريخ يوم جبلة وما قيل فيه من الشعر","page":"ج11 ص164","text":"قال وكان جبلة قبل الإسلام بتسع وخمسين سنة قبل مولد النبي بتسع عشرة سنة وولد النبي عام الفيل ثم أوحى الله إليه بعد أربعين سنة وقبض وهو ابن ثلاث وستين سنة وقدم عامر بن الطفيل في السنة التي قبض فيها قال وهو ابن ثمانين سنة وقال المعقر بن أوس بن حمار البارقي حليف بني نمير بن عامر\n(أمن آل شعثاء الخمول البواكر ... مع الليل أم زالت قبيل الأباعر)\n(وحلت سليمى في هضاب وأيكة ... فليس عليها يوم ذلك قادر)\n(وأتت عصاها واستقرت بها النوى ... كما قر عينا بالإياب المسافر)\n(وصبحها أملاكها بكتيبة ... عليها إذا أمست من الله ناظر)\n(معاوية بن الجون ذبيان حوله ... وحسان في جمع الرباب مكاثر)\n(فمروا بأطناب البيوت فردهم ... رجال بأطراف الرماح مساعر)\n(وقد جمعوا جمعا كأن زهاءه ... جراد هوى في هبوة متطاير)\n(فباتوا لنا ضيفا وبتنا بنعمة ... لنا مسمعات بالدفوف وسامر)\n(ولم نقرهم شيئا ولكن قصدهم ... صبوح لدينا مطلع الشمس حازر)\n(صبحناهم عند الشروق كتائبا ... كأركان سلمى شبرها متواتر)\n(كأن نعام الدو باض عليهم ... وأعينهم تحت الحبيك جواحر)\nلحبيك في البيض إحكام عملها وطرائقها\n(من الضاربين الكبش يمشون مقدما ... إذا غص بالريق القليل الحناجر)\n(وظن سراة القوم ألا يقتلوا ... إذا دعيت بالسفح عبس وعامر)\n(ضربنا حبيك البيض في غمر لجة ... فلم يبق في الناجين منهم مفاخر)\n(ولم ينج إلا من يكون طمره ... يوائل أو نهد ملح مثابر)\n(هوى زهدم تحت الغبار لحاجب ... كما انقض أقنى ذو جناحين ماهر)\n(هما بطلان يعثران كلاهما ... أراد رئاس السيف والسيف نادر)\n(ولا فضل إلا أن يكون جراءة ... وذبيان تسمو والرؤوس حواسر)\n(ينوء وكفا زهدم من ورائه ... وقد علقت ما بينهن الأظافر)\n(يفرج عنا كل ثغر نخافه ... مسح كسرحان القصيمة ضامر)\nلقصيمة من الرمل ما أنبتت الغضى والرمث\n(وكل طموح في العنان كأنها ... إذا اغتمست في الماء فتخاء كاسر)\n(لها ناهض في المهد قد مهدت لها ... كما مهدت للبعل حسناء عاقر)\nبهذا البيت سمي معقرا واسمه سفيان بن أوس وإنما خص العاقر لأنها أقل دلا على الزوج من الولود فهي تصنع له وتداريه\n(تخاف نساء يبتدرن حليلها ... محردة قد حردتها الضراء)\nقال عامر بن الطفيل بعد ذلك بدهر\n(ويوم الجمع لاقينا لقيطا ... كسونا رأسه عضبا حساما)\n(أسرنا حاجبا فثوى بقد ... ولم نترك لنسوته سواما)\n(وجمع الجون إذ دلفوا إلينا ... صبحنا جمعهم جيشا لهاما)\nقال لبيد بن ربيعة في ذلك\n(وهم حماة الشعب يوم تواكلت ... أسد وذبيان الصفا وتميم)\n(فارتث كلماهم عشية هزمهم ... حي بمنعرج المسيل مقيم)\nتم اليوم والحمد لله\n(أيجمل ما يؤتى إلى فتياتكم ... وأنتم رجال فيكم عدد النمل)\n(فلو أننا كنا رجالا وكنتم ... نساء حجال لم نقر بذا الفعل)\nلشعر لعفيرة بنت عفار وقيل بنت عباد الجديسية التي يقال لها الشموس والغناء لعريب خفيف ثقيل أول مطلق في مجرى البنصر وفيه لحن من الثقيل الأول قديم","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":29,"spl":"تأريخ يوم جبلة وما قيل فيه من الشعر","song":1,"loc":2041},
{"id":"b116-37","bab":"الجزء 11","sec":"سبب مقتل عمليق ملك طسم","page":"ج11 ص167","text":"أخبرني بهذا الشعر والسبب الذي من أجله قيل علي بن سليمان الأخفش عن السكري عن محمد بن حبيب عن ابن الأعرابي عن المفضل أن عمليقا ملك طسم بن لاوذ بن إرم بن سام بن نوح عليه السلام وجديس بن لاوذ بن\nإرم بن سام بن نوح عليه السلام وكانت منازلهم في موضع اليمامة كان في أول مملكته قد تمادى في الظلم والغشم والسيرة بغير الحق وأن أمرأة من جديس كان يقال لها هزيلة وكان لها زوج يقال له قرقس فطلقها وأراد أخذ ولدها منها فخاصمته الى عمليق فقالت يا أيها الملك إني حملته تسعا ووضعته دفعا وأرضعته شفعا حتى إذا تمت أوصاله ودنا فصاله أراد أن يأخذه مني كرها ويتركني من بعده ورها فقال لزوجها ما حجتك قال حجتي أيها الملك أني قد أعطيتها المهر كاملا ولم أصب منها طائلا إلا وليدا خاملا فافعل ما كنت فاعلا فأمر بالغلام أن ينزع منهما جميعا ويجعل في غلمانه وقال لهزيلة ابغيه ولدا ولا تنكحي أحدا واجزيه صفدا فقالت هزيلة أما النكاح فإنما يكون بالمهر وأما السفاح فإنما يكون بالقهر وما لي فيهما من أمر فلما سمع ذلك عمليق أمر بأن تباع هي وزوجها فيعطى زوجها خمس ثمنها وتعطى هزيلة عشر ثمن زوجها فأنشأت تقول\n(أتينا أخا طسم ليحكم بيننا ... فأنفذ حكما في هزيلة ظالما)\n(لعمري لقد حكمت لا متورعا ... ولا كنت فيما تبرم الحكم عالما)\n(ندمت ولم أندم وأني بعثرتي ... وأصبح بعلي في الحكومة نادما)\nلما سمع عمليق قولها أمر ألا تزوج بكر من جديس وتهدى الى زوجها حتى يفترعها هو قبل زوجها فلقوا من ذلك بلاء وجهدا وذلا فلم يزل يفعل هذا حتى زوجت الشموس وهي عفيرة بنت عباد أخت الأسود الذي وقع الى\nجبل طيىء فقتلته طيىء وسكنوا الجبل من بعده فلما أرادوا حملها الى زوجها أنطلقوا بها الى عمليق لينالها قبله ومعها القيان يتغنين\n(ابدي بعمليق وقومي فاركبي ... وبادري الصبح لأمر معجب)\n(فسوف تلقين الذي لم تطلبي ... وما لبكر عنده من مهرب)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":30,"spl":"سبب مقتل عمليق ملك طسم — افترع عفيرة بنت عباد فحرضت قومها عليه","loc":2042},
{"id":"b116-38","bab":"الجزء 11","sec":"افترع عفيرة بنت عباد فحرضت قومها عليه","page":"ج11 ص168","text":"فلما أن دخلت عليه أفترعها وخلى سبيلها فخرجت إلى قومها في دمائها شاقة درعها من قبل ومن دبر والدم يسيل وهي في أقبح منظر وهي تقول\n(لا أحد أذل من جديس ... أهكذا يفعل بالعروس)\n(يرضى بهذا يا لقومي حر ... أهدى وقد أعطى وسيق المهر)\n(لأخذة الموت كذا لنفسه ... خير من ان يفعل ذا بعرسه)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":30,"spl":"سبب مقتل عمليق ملك طسم — افترع عفيرة بنت عباد فحرضت قومها عليه","loc":2043},
{"id":"b116-39","bab":"الجزء 11","sec":"وقالت تحرض قومها فيما أتي إليها","page":"ج11 ص169","text":"(أيجمل ما يؤتى الى فتياتكم ... وأنتم رجال فيكم عدد النمل)\n(وتصبح تمشي في الدماء عفيرة ... جهارا وزفت في النساء الى بعل)\n(ولو أننا كنا رجالا وكنتم ... نساء لكنا لا نقر بذا الفعل)\n(فموتوا كراما أو أميتوا عدوكم ... ودبوا لنار الحرب بالحطب الجزل)\n(وإلا فخلوا بطنها وتحملوا ... الى بلد قفر وموتوا من الهزل)\n(فللبين خير من مقام على أذى ... وللموت خير من مقام على الذل)\n(وإن أنتم لم تغضبوا بعد هذه ... فكونوا نساء لا تعاب من الكحل)\n(ودونكم طيب العروس فإنما ... خلقتم لأثواب العروس وللغسل)\n(فبعدا وسحقا للذي ليس دافعا ... ويختال يمشي بيننا مشية الفحل)\nلما سمع الأسود أخوها ذلك وكان سيدا مطاعا قال لقومه يا معشر جديس إن هؤلاء القوم ليسوا بأعز منكم في داركم إلا بما كان من ملك صاحبهم علينا وعليهم ولولا عجزنا وإدهاننا ما كان له فضل علينا ولو امتنعنا لكان لنا منه النصف فأطيعوني فيما آمركم به فإنه عز الدهر وذهاب ذل العمر وأقبلوا رأيي قال وقد أحمى جديسا ما سمعوا من قولها فقالوا نطيعك ولكن القوم أكثر وأحمى وأقوى قال فإني أصنع للملك طعاما ثم أدعوهم له جميعا فإذا جاؤوا يرفلون في الحلل ثرنا الى سيوفنا وهم غارون فأهمدناهم بها قالوا نفعل فصنع طعاما كثيرا وخرج به الى ظهر بلدهم ودعا عمليقا وسأله أن يتغدى عنده هو وأهل بيته فأجابه الى ذلك وخرج إليه مع أهله يرفلون في الحلى والحلل حتى إذا أخذوا مجالسهم ومدوا أيديهم إلى الطعام أخذوا سيوفهم من تحت أقدامهم فشد الأسود على عمليق فقتله وكل رجل منهم على جليسه حتى أماتوهم فلما فرغوا من الأشراف شدوا على السفلة فلم يدعوا منهم أحدا فقال الأسود في ذلك\n(ذوقي ببغيك يا طسم مجللة ... فقد أتيت لعمري أعجب العجب)\n(إنا أبينا فلم ننفك نقتلهم ... والبغي هيج منا سورة الغضب)\n(ولن يعود علينا بغيهم أبدا ... ولن يكونوا كذي أنف ولا ذنب)\n(وإن رعيتم لنا قربى مؤكدة ... كنا الأقارب في الأرحام والنسب)\nثم إن بقية طسم لجأوا إلى حسان بن تبع فغزا جديسا فقتلها وأخرب بلادها فهرب الأسود قاتل عمليق فأقام بجبلي طيىء قبل نزول طيىء إياهما وكانت طيىء تسكن الجرف من أرض اليمن وهو اليوم محلة مراد وهمدان وكان سيدهم يومئذ أمامة بن لؤي بن الغوث بن طيىء وكان الوادي مسبعة وهم قليل عددهم وقد كان ينتابهم بعير في أزمان الخريف ولم يدر أين يذهب ولم يروه إلى قابل وكانت الأزد قد خرجت من اليمن أيام العرم فاستوحشت طيىء لذلك وقالت قد ظعن إخواننا فصاروا الى الأرياف فلما هموا بالظعن قالوا لأسامة إن هذا البعير يأتينا من بلد ريف وخصب وإنا لنرى في بعره النوى فلو أننا نتعهده عند انصرافه فشخصنا معه لكنا نصيب مكانا خيرا من مكاننا هذا فأجمعوا أمرهم على ذلك فلما كان الخريف جاء البعير فضرب في إبلهم فلما انصرف احتملوا واتبعوه يسيرون بسيره ويبيتون حيث يبيت حتى هبط على الجبلين فقال أسامة بن لؤي\n(اجعل طريبا كحبيب ينسى ... لكل قوم مصبح وممسى)\nال وطريب اسم الموضع الذي كانوا ينزلون به فهجمت طيىء على النخل في الشعاب وعلى مواش كثيرة وإذا هم برجل في شعب من تلك الشعاب وهو الأسود بن عباد فهالهم ما رأوا من عظم خلقه وتخوفوه وقد\nنزلوا ناحية من الأرض واستبروها هل يرون بها أحدا غيره فلم يروا فقال أسامة بن لؤي لابن له يقال له الغوث أي بني إن قومك قد عرفوا فضلك عليهم في الجلد والبأس والرمي فإن كفيتنا هذا الرجل سدت قومك آخر الدهر وكنت الذي أنزلتنا هذا البلد فانطلق الغوث حتى أتى الرجل فكلمه وساءله فعجب الأسود من صغر خلق الغوث فقال له من أين أقبلتم قال من اليمن وأخبره خبر البعير ومجيئهم معه وأنهم رهبوا ما رأوا من عظم خلقه وصغرهم عنه وشغلوه بالكلام فرماه الغوث بسهم فقتله وأقامت طيىء بالجبلين بعده فهم هنالك الى اليوم\n(إذا قبل الإنسان آخر يشتهي ... ثناياه لم يحرج وكان له أجرا)\n(فإن زاد زاد الله في حسناته ... مثاقيل يمحو الله عنه بها وزرا)\nلشعر لرجل من عذرة والغناء لعريب ثقيل أول بالوسطى","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":31,"spl":"وقالت تحرض قومها فيما أتي إليها","song":1,"loc":2044},
{"id":"b116-40","bab":"الجزء 11","sec":"عمر بن أبي ربيعة وصاحبه العذري","page":"ج11 ص172","text":"نسخت هذا الخبر من كتاب محمد بن موسى بن حماد قال ذكر الرياشي قال قال حماد الراوية أتيت مكة فجلست في حلقة فيها عمر بن أبي ربيعة فتذاكروا من العذريين فقال عمر بن أبي ربيعة كان لي صديق من عذرة يقال له الجعد بن مهجع وكان أحد بني سلامان وكان يلقى مثل الذي ألقى من الصبابة بالنساء والوجد بهن على أنه كان لا عاهر الخلوة ولا سريع السلوة\nوكان يوافي الموسم في كل سنة فإذا راث عن وقته ترجمت عنه الأخبار وتوكفت له الأسفار حتى يقدم فغمني ذات سنة إبطاؤه حتى قدم حجاج عذرة فأتيت القوم أنشد صاحبي وإذا غلام قد تنفس الصعداء ثم قال أعن أبي المسهر تسأل قلت عنه أسأل وإياه أردت قال هيهات هيهات أصبح والله أبو المسهر لا مؤيسا فيهمل ولا مرجوا فيعلل أصبح والله كما قال القائل\n(لعمرك ما حبي لأسماء تاركي ... أعيش ولا أقضي به فأموت)\nال قلت وما الذي به قال مثل الذي بك من تهوركما في الضلال وجركما أذيال الخسار فكأنكما لم تسمعا بجنة ولا نار قلت من أنت منه يا بن أخي قال أخوه قلت أما والله يا بن أخي ما يمنعك أن تسلك مسلك أخيك من الأدب وأن تركب منه مركبه إلا أنك وأخاك كالبرد والبجاد لا ترقعه ولا يرقعك ثم صرفت وجه ناقتي وأنا أقول\n(أرائحة حجاج عذرة وجهة ... ولما يرح في القوم جعد بن مهجع)\n(خليلان نشكو ما نلاقي من الهوى ... متى ما يقل أسمع وإن قلت يسمع)\n(ألا ليت شعري أي شيء أصابه ... فلي زفرات هجن ما بين أضلعي)\n(فلا يبعدنك الله خلا فإنني ... سألقى كما لاقيت في كل مصرع)\nم انطلقت حتى وقفت موقفي من عرفات فبينا أنا كذلك إذ أنا بإنسان\nقد تغير لونه وساءت هيئته فأدنى ناقته من ناقتي حتى خالف بين أعناقهما ثم عانقني وبكى حتى اشتد بكاؤه فقلت ما وراءك قال برح العذل وطول المطل ثم أنشأ يقول\n(لئن كانت عدية ذات لب ... لقد علمت بأن الحب داء)\n(ألم تنظر إلى تغيير جسمي ... وأني لا يفارقني البكاء)\n(ولو أني تكلفت الذي بي ... لقف الكلم وانكشف الغطاء)\n(فإن معاشري ورجال قومي ... حتوفهم الصبابة واللقاء)\n(إذا العذري مات خلي ذرع ... فذاك العبد يبكيه الرشاء)\nقلت يا أبا المسهر إنها ساعة تضرب إليها أكباد الإبل من شرق الأرض وغربها فلو دعوت الله كنت قمنا أن تظفر بحاجتك وأن تنصر على عدوك قال فتركني وأقبل على الدعاء فلما نزلت الشمس للغروب وهم الناس أن يفيضوا سمعته يتكلم بشيء فأصغيت إليه فإذا هو يقول\n(يا رب كل غدوة وروحه ... من محرم يشكو الضحى ولوحه)\n(أنت حسيب الخلق يوم الدوحه ... )\nمر بن أبي ربيعة يسعى لزواج الجعد بن مهجع من عشيقته فقلت له وما يوم الدوحة قال والله لأخبرنك ولو لم تسألني فيممنا\nنحو مزدلفة فأقبل علي وقال إني رجل ذو مال كثير من نعم وشاء وذو المال لا يصدره ولا يرويه الثماد وقطر الغيث أرض كلب فانتجعت أخوالي منهم فأوسعوا لي عن صدر المجلس وسقوني جمة الماء وكنت فيهم في خير أخوال ثم إني عزمت على موافقة إبلي بماء لهم يقال له الحوذان فركبت فرسي وسمطت خلفي شرابا كان أهداه إلي بعضهم ثم مضيت حتى إذا كنت بين الحي ومرعى النعم رفعت لي دوحة عظيمة فنزلت عن فرسي وشددته بغصن من أغصانها وجلست في ظلها فبينا أناكذلك إذ سطع غبار من ناحية الحي ورفعت لي شخوص ثلاثة ثم تبينت فإذا فارس يطرد مسحلا وأتانا فتأملته فإذا عليه درع أصفر وعمامة خز سوداء وإذا فروع شعره تضرب خصريه فقلت غلام حديث عهد بعرس أعجلته لذة الصيد فترك ثوبه ولبس ثوب أمرأته فما جاز علي إلا يسيرا حتى طعن المسحل وثنى طعنة للأتان فصرعهما وأقبل راجعا نحوي وهو يقول\n(نطعنهم سلكى ومخلوجة ... كرك لامين على نابل)\nقلت إنك قد تعبت وأتعبت فلو نزلت فثنى رجله فنزل فشد فرسه\nحذف 176\nبغصن من أغصان الشجرة وألقى رمحه وأقبل حتى جلس فجعل يحدثني حديثا ذكرت به قول أبي ذؤيب\n(وإن حديثا منك لو تبذلينه ... جنى النحل في ألبان عوذ مطافل)","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":32,"spl":"عمر بن أبي ربيعة وصاحبه العذري","loc":2045,"partial":1},
{"id":"b116-41","bab":"الجزء 11","sec":"عمر بن أبي ربيعة وصاحبه العذري","page":"ج11 ص172","text":"قمت إلى فرسي فأصلحت من أمره ثم رجعت وقد حسر العمامة عن رأسه فإذا غلام كأن وجهه الدينار المنقوش فقلت سبحانك اللهم ما أعظم قدرتك وأحسن صنعتك فقال مم ذاك قلت مما راعني من جمالك وبهرني من نورك قال وما الذي يروعك من حبيس التراب وأكيل الدواب ثم لا يدري أينعم بعد ذلك أم يبأس قلت لا يصنع الله بك إلا خيرا ثم تحدثنا ساعة فأقبل علي وقال ما هذا الذي أرى قد سمطت في سرجك قلت شراب أهداه إلي بعض أهلك فهل لك فيه من أرب قال أنت وذاك فأتيته به فشرب منه وجعل ينكت أحيانا بالسوط على ثناياه فجعل والله يتبين لي ظل السوط فيهن فقلت مهلا فإني خائف أن تكسرهن فقال ولم قلت لأنهن رقاق وهن عذاب قال ثم رفع عقيرته يتغنى\n(إذا قبل الإنسان آخر يشتهي ... ثناياه لم يأثم وكان له أجرا)\n(فإن زاد زاد الله في حسناته ... مثاقيل يمحو الله عنه بها الوزرا)\nم قام إلى فرسه فأصلح من أمره ثم رجع قال فبرقت لي بارقة تحت الدرع فإذا ثدي كأنه حق عاج فقلت نشدتك الله امرأة قالت إي والله إلا أني أكره العشير وأحب الغزل ثم جلست فجعلت تشرب معي ما أفقد\nمن أنسها شيئا حتى نظرت إلى عينيها كأنهما عينا مهاة مذعورة فوالله ماراعني إلا ميلها على الدوحة سكرى فزين لي والله الغدر وحسن في عيني ثم إن الله عصمني منه فجلست حجرة منها فما لبث إلا يسيرا حتى انتبهت فزعة فلاثت عمامتها برأسها وجالت في متن فرسها وقالت جزاك الله عن الصحبة خيرا قلت أو ما تزودينني منك زادا فناولتني يدها فقبلتها فشممت والله منها ريح المسك المفتوت فذكرت قول الشاعر\n(كأنها إذ تقضى النوم وانتبهت ... سحابة ما لها عين ولا أثر)\nلت وأين الموعد قالت إن لي إخوة شرسا وأبا غيورا ووالله لأن أسرك أحب إلي من أن أضرك ثم انصرفت فجعلت أتبعها بصري حتى غابت فهي والله يا بن أبي ربيعة أحلتني هذا المحل وأبلغتني فقلت له يا أبا المسهر إن الغدر بك مع ما تذكر لمليح فبكى واشتد بكاؤه فقلت لاتبك فما قلت لك ما قلت إلا مازحا ولو لم أبلغ في حاجتك بمالي لسعيت في ذلك حتى أقدر عليه فقال لي خيرا فلما انقضى الموسم شددت على ناقتي وشد على ناقته ودعوت غلامي فشد على بعير له وحملت عليه قبة حمراء من أدم كانت لأبي ربيعة المخزومي وحملت معي ألف دينار ومطرف خز وانطلقنا حتى أتينا بلاد كلب فنشدنا عن أبي الجارية فوجدناه في نادي قومه وإذا هو سيد الحي وإذا الناس حوله فوقفت على القوم فسلمت فرد الشيخ السلام ثم قال من الرجل قلت عمر بن أبي ربيعة بن المغيرة فقال المعروف غير المنكر فما الذي جاء بك قلت خاطبا قال الكفء والرغبة قلت إني لم آت ذلك لنفسي عن غير زهاده فيك ولا جهالة بشرفك ولكني أتيت في حاجة ابن أختكم العذري وها هو ذاك فقال\nوالله إنه لكفيء الحسب رفيع البيت غير أن بناتي لم يقعن إلا في هذا الحي من قريش فوجمت لذلك وعرف التغير في وجهي فقال أما إني صانع بك ما لم أصنعه بغيرك قلت وما ذاك فمثلي من شكر قال أخيرها فهي وما اختارت قلت ما أنصفتني إذ تختار لغيري وتولي الخيار غيرك فأشار إلي العذري أن دعه يخيرها فأرسل إليها إن من الأمر كذا وكذا فأرسلت إليه ما كنت لأستبد برأي دون القرشي فالخيار في قوله حكمه فقال لي إنها قد ولتك أمرها فاقض ما أنت قاض فحمدت الله عز و جل وأثنيت عليه وقلت اشهدوا أني قد زوجتها من الجعد بن مهجع وأصدقتها هذا الألف الدينار وجعلت تكرمتها العبد والبعير والقبة وكسوت الشيخ المطرف وسألته أن يبني بها عليه في ليلته فأرسل إلى أمها فقالت أتخرج ابنتي كما تخرج الأمة فقال الشيخ هجري في جهازها فما برحت حتى ضربت القبة في وسط الحريم ثم أهديت إليه ليلا وبت أنا عند الشيخ فلما أصبحت أتيت القبة فصحت بصاحبي فخرج إلي وقد أثر السرور فيه فقلت كيف كنت بعدي وكيف هي بعدك فقال لي أبدت لي والله كثيرا مما كانت أخفته عني يوم لقيتها فسألتها عن ذلك فأنشأت تقول\n(كتمت الهوى لما رأيتك جازعا ... وقلت فتى بعض الصديق يريد)\n(وأن تطرحني أو تقول فتية ... يضر بها برح الهوى فتعود)\n(فوريت عما بي وفي داخل الحشى ... من الوجد برح فاعلمن شديد)\nفقلت أقم على أهلك بارك الله لك فيهم وانطلقت وأنا أقول\n(كفيت أخي العذري ما كان نابه ... وإني لأعباء النوائب حمال)\n(أما استحسنت مني المكارم والعلا ... إذا طرحت إني لمالي بذال)\nوقال العذري","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":33,"spl":"عمر بن أبي ربيعة وصاحبه العذري","loc":2046},
{"id":"b116-42","bab":"الجزء 11","sec":"عمر بن أبي ربيعة وصاحبه العذري","page":"ج11 ص172","text":"(إذا ما أبو الخطاب خلى مكانه ... فاف لدنيا ليس من أهلها عمر)\n(فلا حي فتيان الحجازين بعده ... ولا سقيت أرض الحجازين بالمطر)\n\n(إن الخليط قد ازمعوا تركي ... فوقفت في عرصاتهم أبكي)\n(جنية برزت لتقتلني ... مطلية الأصداغ بالمسك)\n(عجبا لمثلك لا يكون له ... خرج العراق ومنبر الملك)\nلشعر لابن قيس الرقيات يقوله في عائشة بنت طلحة والغناء لمعبد ثقيل أول بالسبابة في مجرى البنصر والسبب في قول ابن قيس هذا الشعر فيها يذكر في أخبارها إن شاء الله تعالى","topic":"خبر ورقاء بن زهير ونسبه وقصة شعره هذا","topicNo":116,"sp":34,"spl":"عمر بن أبي ربيعة وصاحبه العذري","song":1,"loc":2047},
{"id":"b117-2","bab":"الجزء 11","sec":"أخبار عائشة بنت طلحة ونسبها — كانت فريدة بين نساء عصرها","page":"ج11 ص179 – ج11 ص180","text":"عائشة بنت طلحة بن عبيد الله بن عثمان بن عامر بن عمرو بن كعب بن سعد بن تيم وأمها أم كلثوم بنت أبي بكر الصديق أخبرني الحسين بن يحيى قال قال حماد قال أبي قال مصعب\nكانت عائشة بنت طلحة لا تستر وجهها من أحد فعاتبها مصعب في ذلك فقالت إن الله تبارك وتعالى وسمني بميسم جمال أحببت أن يراه الناس ويعرفوا فضلي عليهم فما كنت لأستره ووالله ما في وصمة يقدر أن يذكرني بها أحد وطالت مرادة مصعب إياها في ذلك وكانت شرسة الخلق قال وكذلك نساء بني تيم هن أشرس خلق الله وأحظاه عند أزواجهن وكانت عند الحسين بن علي صلوات الله عليهما أم إسحاق بنت طلحة فكان يقول والله لربما حملت ووضعت وهي مصارمة لي لا تكلمني قال نالت عائشة من مصعب وقالت علي كظهر أمي وقعدت في\nغرفة وهيأت فيها ما يصلحها فجهد مصعب أن تكلمه فأبت فبعث إليها ابن قيس الرقيات فسألها كلامه فقالت كيف بيميني فقال ها هنا الشعبي فقيه أهل العراق فاستفتيه فدخل عليها فأخبرته فقال ليس هذا بشيء فقالت أتحلني وتخرج خائبا فأمرت له بأربعة آلاف درهم وقال ابن قيس الرقيات لما رآها\n(جنية برزت لتقتلنا ... مطلية الأقراب بالمسك)\nذكر باقي الأبيات","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":0,"spl":"أخبار عائشة بنت طلحة ونسبها — كانت فريدة بين نساء عصرها","loc":2048},
{"id":"b117-3","bab":"الجزء 11","sec":"هي وأشعب يتآمران على مصعب","page":"ج11 ص181","text":"أخبرني محمد بن العباس اليزيدي قال حدثنا محمد بن إسحاق اليعقوبي قال حدثنا سليمان بن أبي شيخ عن محمد بن الحكم قال كان أشعب يألف مصعبا فغضبت عليه عائشة بنت طلحة يوما وكانت من أحب الناس إليه فشكا ذلك إلى أشعب فقال ما لي إن رضيت قال حكمك قال عشرة آلاف درهم قال هي لك فانطلق حتى أتى عائشة فقال جعلت فداءك قد علمت حبي لك وميلي قديما وحديثا\nإليك من غير منالة ولا فائدة وهذه حاجة قد عرضت تقضين بها حقي وترتهنين بها شكري قالت وما عناك قال قد جعل لي الأمير عشرة آلاف درهم إن رضيت عنه قالت ويحك لا يمكنني ذلك قال بأبي أنت فارضي عنه حتى يعطيني ثم عودي الى ما عودك الله من سوء الخلق فضحكت منه ورضيت عن مصعب وقد ذكر المدائني أن هذه القصة كانت لها مع عمر بن عبيد الله بن معمر وأن الرسول إليها والمخاطب لها بهذه المخاطبة ابن أبي عتيق وأخبرني الحسين بن يحيى قال قال حماد قال أبي حدثت عن صالح بن حسان قال كان بالمدينة امرأة حسناء تسمى عزة الميلاء يألفها الأشراف وغيرهم من أهل المروءات وكانت من أظرف الناس وأعلمهم بأمور النساء فأتاها مصعب بن الزبير وعبد الله بن عبد الرحمن بن أبي بكر وسعيد بن العاص فقالوا إنا خطبنا فانظري لنا فقالت لمصعب يا بن أبي عبد الله ومن خطبت فقال عائشة بنت طلحة فقالت فأنت يا بن أبي أحيحة قال عائشة بنت عثمان قالت فأنت يابن الصديق قال أم القاسم بنت زكريا بن طلحة قالت يا جارية هاتي منقلي تعني خفيها فلبستهما وخرجت ومعها خادم لها فإذا هي بجماعة يزحم بعضهم بعضا فقالت يا جارية انظري ما هذا فنظرت ثم رجعت فقالت امرأة أخذت مع رجل فقالت داء قديم امض ويلك فبدأت بعائشة بنت طلحة فقالت فديتك كنا في مأدبة أو مأتم لقريش فتذاكروا جمال النساء وخلقهن فذكروك فلم أدر كيف أصفك فديتك فألقي ثيابك ففعلت فأقبلت وأدبرت فارتج كل شيء منها فقالت لها عزة خذي ثوبك فديتك فقالت عائشة قد قضيت\nحاجتك وبقيت حاجتي قالت عزة وما هي بنفسي أنت قالت تغنيني صوتا فاندفعت تغني لحنها\n(خليلي عوجا بالمحلة من جمل ... وأترابها بين الأصيفر والخبل)\n(نقف بمغان قد محا رسمها البلى ... تعاقبها الأيام بالريح والوبل)\n(فلو درج النمل الصغار بجلدها ... لأندب أعلى جلدها مدرج النمل)\n(وأحسن خلق الله جيدا ومقلة ... تشبه في النسوان بالشادن الطفل)\nلشعر لجميل بن عبد الله بن معمر العذري والغناء لعزة الميلاء ثقيل أول بالوسطى فقامت عائشة فقبلت ما بين عينيها ودعت لها بعشرة أثواب وبطرائف من أنواع الفضة وغير ذلك فدفعته الى مولاتها فحملته وأتت النسوة على مثل ذلك تقول ذلك لهن حتى أتت القوم في السقيفة فقالوا ما صنعت فقالت يابن أبي عبد الله أما عائشة فلا والله إن رأيت مثلها مقبلة ومدبرة محطوطة المتنين عظيمة العجيزة ممتلئة الترائب نقية الثغر وصفحة الوجه فرعاء الشعر لفاء الفخذين ممتلئة الصدر\nخميصة البطن ذات عكن ضخمة السرة مسرولة الساق يرتج مابين أعلاها الى قدميها وفيها عيبان أما أحدهما فيواريه الخمار وأما الآخر فيواريه الخف عظم القدم والأذن وكانت عائشة كذلك ثم قالت عزة وأما أنت يا بن أبي أحيحة فإني والله ما رأيت مثل خلق عائشة بنت عثمان لامرأة قط ليس فيها عيب والله لكأنما أفرغت إفراغا ولكن في الوجه ردة وإن استشرتني أشرت عليك بوجه تستأنس به وأما أنت يابن الصديق فوالله ما رأيت مثل أم القاسم كأنها خوط بانة تنثني وكأنها جدل عنان أو كأنها جان يتثنى على رمل لو شئت أن تعقد أطرافها لفعلت ولكنها شختة الصدر وأنت عريض الصدر فإذا كان ذلك كان قبيحا لا والله حتى يملأ كل شيء مثله قال فوصلها الرجال والنساء وتزوجوهن أخبرني الطوسي وحرمي عن الزبير عن عمه وأخبرني الحسين بن يحيى عن حماد عن أبيه عن الزبيري والمدائني ونسخت بعض هذه الأخبار من كتاب أحمد بن الحارث عن المدائني وجمعت ذلك قالوا جميعا إن أم عائشة بنت طلحة أم كلثوم بنت أبي بكر الصديق وأمها حبيبة بنت خارجة بن زيد بن أبي زهير من بني الخزرج بن الحارث قالوا وكانت عائشة بنت طلحة تشبه بعائشة أم المؤمنين خالتها فزوجتها عائشة عبد الله بن عبد","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":1,"spl":"هي وأشعب يتآمران على مصعب","song":1,"loc":2049},
{"id":"b117-4","bab":"الجزء 11","sec":"هي وأشعب يتآمران على مصعب","page":"ج11 ص181","text":"الرحمن بن أبي بكر وهو ابن أخيها وابن خال عائشة بنت طلحة وهو أبو عذرها فلم تلد من أحد من أزواجها سواه ولدت له عمران وبه كانت تكنى وعبد الرحمن وأبا بكر وطلحة ونفيسة وتزوجها الوليد بن عبد الملك ولكل هؤلاء عقب وكان ابنها طلحة من أجواد قريش وله يقول الحزين الديلي\n(فإن تك يا طلح أعطيتني ... عذافرة تستخف الضفارا)\n(فما كان نفعك لي مرة ... ولا مرتين ولكن مرارا)\n(أبوك الذي صدق المصطفى ... وسار مع المصطفى حيث سارا)\n(وأمك بيضاء تيمية ... إذا نسب الناس كانوا نضارا)\nال فصارمت عائشة بنت طلحة زوجها وخرجت من دارها غضبى فمرت في المسجد وعليها ملحفة تريد عائشة أم المؤمنين فرآها أبو هريرة فقال سبحان الله كأنها من الحور العين فمكثت عند عائشة أربعة أشهر وكان زوجها قد آلى منها فأرسلت عائشة إني أخاف عليك الإيلاء فضمها إليه وكان موليا منها فقيل له طلقها فقال\n(يقولون طلقها لأصبح ثاويا ... مقيما علي الهم أحلام نائم)\n(وإن فراقي أهل بيت أحبهم ... لهم زلفة عندي لإحدى العظائم)","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":2,"spl":"هي وأشعب يتآمران على مصعب — زواجها من مصعب بن الزبير","loc":2050},
{"id":"b117-5","bab":"الجزء 11","sec":"زواجها من مصعب بن الزبير","page":"ج11 ص186","text":"فتوفي عبد الله بعد ذلك وهي عنده فما فتحت فاها عليه وكانت عائشة أم المؤمنين تعدد عليها هذا في ذنوبها التي تعددها ثم تزوجها بعده مصعب بن الزبير فأمهرها خمسمائة ألف درهم وأهدى لها مثل ذلك وبلغ ذلك أخاه فقال إن مصعبا قدم أيره وأخر خيره فبلغ ذلك من قوله عبد الملك بن مروان فقال لكنه أخر أيره وخيره وكتب ابن الزبير إلى مصعب يؤنبه على ذلك ويقسم عليه أن يلحق به بمكة ولا ينزل المدينة ولا ينزل إلا بالبيداء وقال له إني لأرجو أن تكون الذي يخسف به بالبيداء فما أمرتك بنزولها إلا لهذا وصار إليه وأرضاه من نفسه فأمسك عنه قال وحدثني المدائني عن سحيم بن حفص قال كان مصعب بن الزبير لا يقدر عليها إلا بتلاح ينالها منه وبضربها فشكا ذلك إلى ابن أبي فروة كاتبه فقال له أنا أكفيك هذا إن أذنت لي قال نعم افعل ما شئت فإنها أفضل شيء نلته من الدنيا فأتاها ليلا ومعه أسودان فاستأذن عليها فقالت له أفي مثل هذه الساعة قال نعم فأدخلته فقال للأسودان احفرا هاهنا بئرا فقالت له جاريتها وما تصنع بالبئر قال شؤم مولاتك أمرني هذا الفاجر أن أدفنها حية وهو أسفك خلق الله لدم حرام فقالت عائشة فأنظرني أذهب إليه قال هيهات لاسبيل إلى ذلك وقال للأسودين احفرا فلما رأت الجد منه بكت ثم قالت يابن أبي فروة إنك لقاتلي ما منه بد قال نعم وإني لأعلم أن الله سيجزيه بعدك ولكنه قد غضب وهو كافر الغضب قالت وفي أي شيء غضبه قال في امتناعك عنه وقد ظن أنك تبغضينه وتتطلعين إلى غيره فقد جن فقالت أنشدك الله إلا عاودته قال إني أخاف أن يقتلني فبكت وبكى جواريها فقال قد\nرققت لك وحلف أنه يغرر بنفسه ثم قال لها فما أقول قالت تضمن عني ألا أعود أبدا قال فما لي عندك قالت قيام بحقك ما عشت قال فأعطيني المواثيق فأعطته فقال للأسودين مكانكما وأتى مصعبا فأخبره فقال له استوثق منها بالأيمان ففعلت وصلحت بعد ذلك لمصعب","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":2,"spl":"هي وأشعب يتآمران على مصعب — زواجها من مصعب بن الزبير","loc":2051},
{"id":"b117-6","bab":"الجزء 11","sec":"بعض اخبارها مع مصعب","page":"ج11 ص187","text":"قال ودخل عليها مصعب يوما وهي نائمة متصبحة ومعه ثماني لؤلؤات قيمتها عشرون ألف دينار فأنبهها ونثر اللؤلؤ في حجرها فقالت له نومتي كانت الي من هذا اللؤلؤ قال وصارمت مصعبا مرة فطالت مصارمتها له وشق ذلك عليها وعليه وكانت لمصعب حرب فخرج إليها ثم عاد وقد ظفر فشكت عائشة مصارمته إلى مولاة لها فقالت الآن يصلح أن تخرجي إليه فخرجت فهنأته بالفتح وجعلت تمسح التراب عن وجهه فقال لها مصعب إني أشفق عليك من رائحة الخديد فقالت لهو والله عندي أطيب من ريح المسك الأذفر أخبرني ابن يحيى عن حماد عن أبيه عن المسعر قال كان مصعب من أشد الناس إعجابا بعائشة بنت طلحة ولم يكن لها شبه في زمانها حسنا ودماثة وجمالا وهيئة ومتانة وعفة وإنها دعت يوما نسوة من قريش فلما جئنها أجلستهن في مجلس قد نضد فيه الريحان والفواكه والطيب و المجمر وخلعت على كل امرأة منهن خلعة تامة من الوشي والخز ونحوهما ودعت عزة الميلاء ففعلت بها مثل ذلك وأضعفت ثم قالت لعزة\nهاتي يا عزة فغنينا فغنتهن في شعر امرىء القيس\n(وثغر أغر شتيت النبات ... لذيذ المقبل والمبتسم)\n(وما ذقته غير ظن به ... وبالظن يقضي عليك الحكم)\nكان مصعب قريبا منهن ومعه إخوان له فقام فانتقل حتى دنا منهن والستور مسبلة فصاح يا هذه إنا قد ذقناه فوجدناه على ما وصفت فبارك الله فيك يا عزة ثم أرسل إلى عائشة أما أنت فلا سبيل لنا إليك مع من عندك وأما عزة فتأذنين لها أن تغنينا هذا الصوت ثم تعود إليك ففعلت وخرجت عزة إليه فغنته هذا الصوت مرارا وكاد مصعب أن يذهب عقله فرحا ثم قال لها يا عزة إنك لتحسنين القول والوصف وأمرها بالعود إلى مجلسها وتحدث ساعة مع القوم ثم تفرقوا وقال المدائني وذكره القحذمي أيضا في خبره فلما قتل مصعب عن عائشة خطبها بشر بن مروان وقدم عمر بن عبيد الله بن معمر التيمي من الشام فنزل الكوفة فبلغه أن بشر بن مروان خطبها فأرسل إليها جارية لها وقال قولي لابنة عمي يقرئك السلام ابن عمك ويقول لك أنا خير من هذا المبسور المطحول وأنا ابن عمك وأحق بك وإن تزوجت بك ملأت بيتك خيرا وحرك أيرا فتزوجته فبنى بها بالحيرة ومهدت له سبعة أفرشة عرضها أربع أذرع فأصبح ليلة بنى بها عن تسع قال فلقيته مولاة لها فقالت أبا حفص فديتك قد كملت في كل شيء حتى في هذا وقال مصعب في خبره إن بشرا بعث إليها عمر بن عبيد الله بن معمر يخطبها عليه فقالت له يا مصارع قلة أما وجد بشر رسولا الى ابنة عمك\nغيرك فأين بك عن نفسك قال أو تفعلين قالت نعم فتزوجها وقال مصعب الزبيري في خبره لما بنى بها عمر قال لها لأقتلنك الليلة فلم يصنع إلا واحدة فقالت له لما أصبح قم يا قتال قال وقالت له حينئذ\n(قد رأيناك فلم تحل لنا ... وبلوناك فلم نرض الخبر)\nهذه الحكاية تحامل من مصعب الزبيري وعصبية والخبر في رضاها عنه والحكاية في هذا غير ما حكاه وهو ما سبق","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":3,"spl":"بعض اخبارها مع مصعب","loc":2052},
{"id":"b117-7","bab":"الجزء 11","sec":"زواجها من عمر بن عبيد الله","page":"ج11 ص189","text":"أخبرني الحسن بن علي قال حدثنا ابن مهرويه عن ابن أبي سعد عن القحذمي أن عمر بن عبيد الله لما قدم الكوفة تزوج عائشة بنت طلحة فحمل اليها ألف ألف درهم خمسمائة ألف درهم مهرا وخمسمائة ألف هدية وقال لمولاتها لك علي ألف دينار إن دخلت بها الليلة وأمر بالمال فحمل فألقي في الدار وغطي بالثياب وخرجت عائشة فقالت لمولاتها أهذا فرش أم ثياب قالت انظري إليه فنظرت فإذا مال فتبسمت فقالت أجزاء من حمل هذا أن يبيت عزبا قالت لا والله ولكن لايجوز دخوله إلا بعد أن أتزين له وأستعد قالت فيم ذا فوجهك والله أحسن من كل زينة وما تمدين يدك الى طيب أو ثوب أو مال أو فرش إلا وهو عندك وقد عزمت عليك أن تأذني له قالت افعلي فذهبت إليه فقالت له بت بنا الليلة فجاءهم عند العشاء الآخرة فأدني إليه طعام فأكل الطعام كله حتى أعرى الخوان وغسل يده وسأل عن المتوضأ فأخبرته فتوضأ وقام يصلي حتى ضاق صدري ونمت ثم قال أعليكم إذن قلت نعم فادخل فأدخلته وأسبلت الستر\nعليهما فعددت له في بقية الليل على قلتها سبع عشرة مرة دخل المتوضأ فيها فلما أصبحنا وقفت على رأسه فقال أتقولين شيئا قلت نعم والله ما رأيت مثلك أكلت أكل سبعة وصليت صلاة سبعة ونكت نيك سبعة فضحك وضرب يده بيده على منكب عائشة فضحكت وغطت وجهها وقالت\n(قد رأيناك فلم تحل لنا ... وبلوناك فلم نرض الخبر)\nيدل أيضا على بطلان خبره أنه لما مات ندبته قائمة ولم تندب أحدا من أزواجها إلا جالسة فقيل لها في ذلك فقالت إنه كان أكرمهم علي وأمسهم رحما بي وأردت ألا أتزوج بعده وكانت ندبة المرأة زوجها قائمة مما تفعله من لا تريد أن تتزوج بعد زوجها أخبرني بذلك الحسن بن علي عن أحمد بن زهير بن حرب عن محمد بن سلام وهذا دليل على خلاف ما ذكره مصعب ثم رجع الخبر إلى سياقة خبرها قال المدائني في خبره قالت أمرأة كنت عند عائشة بنت طلحة فقيل لها قد جاء الأمير فتنحيت ودخل عمر بن عبيد الله وكنت بحيث أسمع كلامهما فوقع عليها فجاءت بالعجائب ثم خرج فقلت لها أنت في نفسك وموضعك وشرفك تفعلين هذا فقالت إنا نتشهى لهذه الفحول بكل ما حركها وكل ما قدرنا عليه قال المدائني وحدثني مسلمة بن محارب قال قالت رملة بنت عبد الله بن خلف وكانت تحت عمر بن عبيد الله بن معمر وقد ولدت منه ابنه طلحة الجود لمولاة لعائشة بنت طلحة أريني عائشة متجردة ولك ألفا درهم فأخبرت عائشة بذلك قالت فإني أتجرد فأعلميها ولا تعرفيها أني أعلم فقامت عائشة كأنها تغتسل وأعلمتها فأشرفت عليها مقبلة ومدبرة فأعطت رملة مولاتها ألفي درهم وقالت لوددت أني\nأعطيتك أربعة آلاف درهم ولم أرها قال وكانت رملة قد أسنت وكانت حسنة الجسم قبيحة الوجه عظيمة الأنف وفيها وفي عائشة يقول الشاعر\n(انعم بعائش عيشا غير ذي رنق ... وانبذ برملة نبذ الجورب الخلق)\nيقال إن رملة قد أسنت عند عمر بن عبيد الله فكانت تجتنبه في أيام أقرائها ثم تغتسل تريه أنها تحيض وذلك بعد انقطاع حيضها فقال في ذلك بعض الشعراء\n(جعل الله كل قطرة حيض ... قطرت منك في حماليق عيني)\nخبرنا بذلك الجوهري عن عمر بن شبة وذكر هارون بن الزيات عن أبي محلم عن أبي بكر بن عياش قال قال عمر بن عبيد الله لعائشة بنت طلحة وقد أصاب منها طيب نفس ما مر بي مثل يوم أبي فديك فقالت له اعدد أيامك واذكر أفضلها فعد يوم سجستان ويوم قطري بفارس ونحو ذلك فقالت عائشة قد تركت يوما","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":4,"spl":"زواجها من عمر بن عبيد الله","loc":2053},
{"id":"b117-8","bab":"الجزء 11","sec":"زواجها من عمر بن عبيد الله","page":"ج11 ص189","text":"لم تكن في أيامك أشجع منك فيه قال وأي يوم قالت يوم أرخت عليها وعليك رملة الستر تريد قبح وجهها قال فمكثت عائشة عند عمر بن عبيد الله بن معمر ثماني سنين ثم مات عنها في سنة اثنتين وثمانين فتأيمت بعده فخطبها جماعة فردتهم ولم تتزوج بعده أحدا قال المدائني كان عمر بن عبيد الله من أشد الناس غيرة فدخل يوما على عائشة وقد ناله حر شديد وغبار فقال لها انفضي التراب عني فأخذت منديلا تنفض به عنه التراب ثم قالت له ما رأيت الغبار على وجه أحد قط كان أحسن منه على وجه مصعب قال فكاد عمر يموت غيظا وقال أحمد بن حماد بن جميل حدثني القحذمي قال كانت عائشة بنت طلحة من أشد الناس مغايظة لأزواجها وكانت تكون لمن يجيء يحدثها في رقيق الثياب فإذا قالوا قد جاء الأمير ضمت عليها مطرنها وقطبت وكانت كثيرا ما تصف لعمر بن عبيد الله مصعبا وجماله تغيظه بذلك فيكاد يموت وقال المدائني حدثني مسلمة بن محارب وعبيد الله بن فائد وأخبرنا به حرمي عن الزبير عن عمه ومحمد بن الضحاك قالوا دخلت عائشة بنت طلحة على الوليد بن عبد الملك وهو بمكة فقالت يا أمير المؤمنين مر لي بأعوان فضم إليها قوما يكونون معها فحجت ومعها\nستون بغلا عليها الهوادج والرحائل فعرض لها عروة بن الزبير فقال\n(عائش يا ذات البغال الستين ... أكل عام هكذا تحجين)\nفأرسلت إليه نعم يا عرية فتقدم إن شئت فكف عنها ولم تتزوج حتى ماتت","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":5,"spl":"زواجها من عمر بن عبيد الله — حجت مع سكينة بنت الحسين","loc":2054},
{"id":"b117-9","bab":"الجزء 11","sec":"حجت مع سكينة بنت الحسين","page":"ج11 ص193","text":"وقال غير المدائني إن عائشة بنت طلحة حجت وسكينة بنت الحسين عليهما السلام معا وكانت عائشة أحسن آلة وثقلا فقال حاديها\n(عائش يا ذات البغال الستين ... لا زلت ما عشت كذا تحجين)\nشق ذلك على سكينة ونزل حاديها فقال\n(عائش هذي ضرة تشكوك ... لولا أبوها ما اهتدى أبوك)\nأمرت عائشة حاديها أن يكف فكف وقال إسحاق بن إبراهيم في خبره حدثني محمد بن سلام عن يزيد بن عياض قال\nاستأذنت عاتكة بنت يزيد بن معاوية عبد الملك في الحج فأذن لها وقال ارفعي حوائجك واستظهري فإن عائشة بنت طلحة تحج ففعلت فجاءت بهيئة جهدت فيها فلما كانت بين مكة والمدينة إذا موكب قد جاء فضغطها وفرق جماعتها فقالت أرى هذه عائشة بنت طلحة فسألت عنها فقالوا هذه خازنتها ثم جاء موكب آخر أعظم من ذلك فقالوا عائشة عائشة فضغطهم فسألت عنه فقالوا هذه ماشطتها ثم جاءت مواكب على هذا الى سننها ثم أقبلت كوكبة فيها ثلثمائة راحلة عليها القباب والهوادج فقالت عاتكة ماعند الله خير وأبقى وقال هارون بن الزيات حدثني قبيصة عن ابن عائشة عن أمه عن سلامة مولاة جدته أثيلة بنت المغيرة بن عبد الله بن معمر قالت زرت مع مولاتي خالتها عائشة بنت طلحة وأنا يومئذ وصيفة فرأيت عجيزتها من خلفها وهي جالسة كأنها غيرها فوضعت أصبعي عليها لأعلم ما هي فلما وجدت مس أصبعي قالت ما هذا قلت جعلت فداءك لم أدر ماهو فجئت لأنظر فضحكت وقالت ما أكثر من يعجب مما عجبت منه وزعم بكر بن عبد الله بن عاصم مولى عرينة عن أبيه عن جده أن عائشة نازعت زوجها إلى أبي هريرة فوقع خمارها عن وجهها فقال أبو هريرة سبحان الله ما أحسن ما غذاك أهلك لكأنما خرجت من الجنة\nقال ابن عائشة وحدثني أبي أن عائشة بنت طلحة وفدت على هشام فقال لها ما أوفدك قالت حبست السماء المطر ومنع السلطان الحق قال فإني أبل رحمك وأعرف حقك ثم بعث إلى مشايخ بني أمية فقال إن عائشة عندي فاسمروا عندي الليلة فحضروا فما تذاكروا شيئا من أخبار العرب وأشعارها وأيامها إلا أفاضت معهم فيه وما طلع نجم ولا غار إلا سمته فقال لها هشام أما الأول فلا أنكره وأما النجوم فمن أين لك قالت أخذتها عن خالتي عائشة فأمر لها بمائة ألف درهم وردها إلى المدينة","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":5,"spl":"زواجها من عمر بن عبيد الله — حجت مع سكينة بنت الحسين","loc":2055},
{"id":"b117-10","bab":"الجزء 11","sec":"خبرها مع النميري الشاعر","page":"ج11 ص195","text":"أخبرني عمي عن الكراني عن المغيرة بن محمد المهلبي عن محمد بن عبد الوهاب عن عبد الرحمن بن عبد الله قال حدثني ابن عمران البزازي قال لما تأيمت عائشة بنت طلحة كانت تقيم بمكة سنة وبالمدينة سنة تخرج إلى مال لها بالطائف عظيم وقصر لها فتتنزه وتجلس فيه بالعشيات فتناضل بين الرماة فمر بها النميري الشاعر فسألت عنه فنسب لها فقالت ائتوني به فقالت له لما أتوها به أنشدني مما قلت في زينب فامتنع وقال ابنة عمي وقد صارت عظاما بالية قالت أقسمت لما فعلت فأنشدها قوله\n(نزلن بفخ ثم رحن عشية ... يلبين للرحمن معتمرات)\n(يخبئن أطراف الأكف من التقى ... ويخرجن شطر الليل معتجرات)\n(ولما رأت ركب النميري أعرضت ... وكن من ان يلقينه حذرات)\n(تضوع مسكا بطن نعمان أن مشت ... به زينب في نسوة خفرات)\nقالت والله ما قلت إلا جميلا ولا وصفت إلا كرما وطيبا وتقى ودينا أعطوه ألف درهم فلما كانت الجمعة الأخرى تعرض لها فقالت علي به فجاء فقالت أنشدني من شعرك في زينب فقال أو أنشدك من قول الحارث فيك فوثب مواليها فقالت دعوه فإنه أراد أن يستقيد لابنة عمه هات فأنشدها\n(ظعن الأمير بأحسن الخلق ... وغدوا بلبك مطلع الشرق)\n(وتنوء تثقلها عجيزتها ... نهض الضعيف ينوء بالوسق)\n(ما صبحت زوجا بطلعتها ... إلا غدا بكواكب الطلق)\n(قرشية عبق العبير بها ... عبق الرهان بجانب الحق)\n(بيضاء من تيم كلفت بها ... هذا الجنون وليس بالعشق)\nالت والله ما ذكر إلا جميلا ذكر أني إذا صبحت زوجا بوجهي غدا بكواكب الطلق وأني غدوت مع أمير تزوجني إلى الشرق أعطوه ألف درهم واكسوه حلتين ولا تعد لإتياننا يا نميري\nأخبرني الحسن بن علي قال حدثنا أحمد بن أبي خيثمة عن محمد بن سلام أن عبد الملك ولى الحارث بن خالد على مكة فأذن المؤذن وخرج للصلاة فأرسلت اليه عائشة بنت طلحة قد بقي من طوافي شيء لم آته وكان يتعشقها فأمر المؤذن فكف عن الإقامة ففرغت من طوافها وبلغ ذلك عبد الملك فعزله فقال ما أهون والله غضبه وعزله إياي علي عند رضاها عني أخبرني أحمد بن عبد العزيز قال حدثني عمر بن شبة قال قال سلم بن قتيبة رأيت عائشة بنت طلحة بمنى أو مسجد الخيف فسألتني من أنت قلت سلم بن قتيبة فقالت رحم الله مصعبا ثم ذهبت تقوم ومعها امرأتان تنهضانها فأعجزتها أليتاها من عظمهما فقالت إني بكما لمعناة فذكرت قول الحارث\n(وتنوء تثقلها عجيزتها ... نهض الضعيف ينوء بالوسق)\nروى هذا الخبر هارون بن الزيات عن جعفر بن محمد عن أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أبو عمرو بن خلاد عن المدائني قال قال أبو هريرة لعائشة بنت طلحة ما رأيت شيئا أحسن منك إلا معاوية أول يوم خطب على منبر رسول الله صلى الله عليه و سلم فقالت والله لأنا أحسن من النار في الليلة القرة في عين المقرور","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":6,"spl":"خبرها مع النميري الشاعر","loc":2056},
{"id":"b117-11","bab":"الجزء 11","sec":"رفضت الزواج من أبان بن سعيد","page":"ج11 ص197","text":"أخبرني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ عن محمد بن الحكم عن عوانة قال\nكتب أبان بن سعيد إلى أخيه يحيى يخطب عليه عائشة بنت طلحة ففعل فقالت ليحيى ما أنزل أخاك أيلة قال أراد العزلة قالت اكتب إلى أخيك\n(حللت محل الضب لاأنت ضائر ... عدوا ولا مستنفع بك نافع)\n\n(إذا المال لم يوجب عليك عطاءه ... صنيعة تقوى أو صديق توامقه)\n(منعت وبعض المنع حزم وقوة ... فلم يفتلتك المال إلا حقائقه)\nروضه من الطويل توامقه تفاعله من الموامقة أي توده ويودك يقال ومقته أمقه أي أحببته ويفتلتك أي يخرجه من يدك وقبضتك الشعر لكثير والغناء لمالك بن أبي السمح ويقال إنه للهذلي خفيف ثقيل أول بالبنصر أخبرنا محمد بن خلف وكيع قال حدثنا طلحة بن عبد الله قال حدثني أبو معمر عافية بن شيبة قال حدثني العتبي قال\nأفلس صيرفي بالمدينة فخرج قوم يسألون له فمروا بابن عمران الطلحي وفتح بابه واجتمع له أصحابه فسألوه فقرع بمخصرته ثم رفع رأسه اليهم فقال\n(إذا المال لم يوجب عليك عطاءه ... صنيعة تقوى أو صديق توامقه)\n(بخلت وبعض البخل حزم وقوة ... فلم يفتلتك المال إلا حقائقه)\nإنا والله ما نحيد عن الحق ولانتدفق في الباطل وإن لنا لحقوقا تشغل فضول أموالنا وما كل من أفلس من صيارفة المدينة قدرنا أن نجبره قوموا قال فقمنا نستبق الباب أخبرني محمد بن العباس اليزيدي قال حدثنا عمر بن شبة قال حدثنا أبو مسلمة المديني قال أخبرني أبي قال كان رجل من الأنصار من بني حارثة مملقا ليس في ديوان ولاعطاء وكان صديقا لإبراهيم بن هشام بن إسماعيل فقال له يوما إن أمير المؤمنين مسابق عدا بين الخيل وقد أمرت الحرس ألا يعرضوا لك حتى تكلمه قال فسبق هشاما يومئذ ابن له وكان السبق يشتد عليه فعرض له الأنصاري فقال يا أمير المؤمنين أنا امرؤ من الأنصار وقد بلغت هذه السن ولسن في ديوان فإن رأى أمير المؤمنين أن يفرض لي فعل قال فأقبل عليه هشام فقال والله لا أفرض لك حتى مثل هذه الليلة من السنة المقبلة ثم أقبل على الأبرش فقال يا أبرش أخطأ أخو الأنصار المسألة فقال يا أمير المؤمنين ابن أبي جمعة يقول\n(إذا المال لم يوجب عليك عطاءه ... صنيعة تقوى أو خليل توامقه)","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":7,"spl":"رفضت الزواج من أبان بن سعيد","song":1,"loc":2057},
{"id":"b117-12","bab":"الجزء 11","sec":"شعر لعمرو بن شائس","page":"ج11 ص200","text":"(منعت وبعض المنع حزم وقوة ... فلم يفتلتك المال إلا حقائقه)\n\n(فواندمي على الشباب وواندم ... ندمت وبان اليوم مني بغير ذم)\n(وإذ إخوتي حولي وإذ أنا شامخ ... وإذ لا أجيب العاذلات من الصمم)\n(أرادت عرارا بالهوان ومن يرد ... عرارا لعمري بالهوان فقد ظلم)\n(فإن كنت مني أو تريدين صحبتي ... فكوني له كالسمن ربت له الأدم)\n(وإلا فبيني مثل ما بان راكب ... تيممم خمسا ليس في ورده يتم)\n(فإن عرارا إن يكن واشكيمه ... تعافينها منه فما أملك الشيم)\n(وإن عرارا إن يكن غير واضح ... فإني أحب الجون ذا المنكب العمم)\n(وإني لأعطي غثها وسمينها ... وأسري إذا ما الليل ذو الظلم ادلهم)\n(حذارا على ما كان قدم والدي ... إذا روحتهم حرجف تطرد الصرم)\nروضه من الطويل الشعر لعمرو بن شأس الأسدي والغناء في الأول والثاني من الأبيات لمعبد ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وذكر عمرو أن فيهما لمالك خفيف رمل بالبنصر وفي الثامن والتاسع لابن جامع هزج بالوسطى عن الهشامي وعلي بن يحيى وفيهما لإبراهيم ماخوري بالبنصر من نسخة عمرو الثانية ولابن سريج ثاني ثقيل\nبالبنصر عن حبش وفيهما رمل مجهول وقيل إنه لسليم الشامخ الذي يشمخ بأنفه زهوا وكبرا وأصل الظلم وضع الشيء في غير موضعه والشيمة الطبيعة ربت له يعني للسمن فلا تفسده والأدم جمع واحدها أديم وجمعها أدم كما يقال أفيق وأفق واليتم الغفلة والضيعة واليتيم مأخوذ من هذا واليتيم من البهائم ما اختلج عن أمه والعرب تقول لا تخلج الفصيل عن أمه فإن الذئب عالم بمكان الفصيل اليتيم ويقال فلان شديد الشكيمة أي شديد اللسان كثير البيان ومنه شكيمة اللجام وجمعها شكائم قال عويف القوافي\n(أقول لفتيان كرام تروحوا ... على الجرد في أفواههن الشكائم)\nالواضح الأبيض والجون الأسود والأبيض أيضا وهو من الأضداد والعمم الطويل يقال رجل عمم وامرأة عمم ورجل عميم وامرأة عميمة ونخل عميم ونبت عميم والسرى السير ليلا وادلهم اشتد سواده والحرجف الريح الشديدة الباردة والصرم جمع صرمة وهي القطعة من الإبل يعني أن هذه الريح إذا هبت طرد الرعاء الإبل الى مراحها وأعطانها فتسكن فيها","topic":"أخبار عائشة بنت طلحة ونسبها","topicNo":117,"sp":8,"spl":"شعر لعمرو بن شائس","song":1,"loc":2058},
{"id":"b118-1","bab":"الجزء 11","sec":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره","page":"ج11 ص202","text":"هو عمرو بن شأس بن عبيد بن ثعلبة بن ذؤيبة بن مالك بن الحارث بن سعد بن ثعلبة بن دودان بن أسد بن خزيمة وهذا الشعر يقوله في امرأته أم حسان وابنه عرار بن عمرو وكانت تؤذيه وتعيره بسواده وأخبرني علي بن سليمان الأخفش قال حدثنا محمد بن الحسن الأحول قال قال ابن الأعرابي كانت امرأة عمرو بن شأس من رهطه ويقال لها أم حسان واسمها حية بنت الحارث بن سعد وكان له ابن يقال له عرار من أمة له سوداء وكانت تعيره وتؤذي عرارا وتشتمه ويشتمها فلما أعيت عمرا قال فيها\n(ديار ابنة السعدي هيه تكلمي ... بدافقة الحومان فالسفح من رمم)\n(لعمر ابنة السعدي إني لأتقي ... خلائق تؤبى في الثراء وفي العدم)\n(وقفت بها ولم أكن قبل أرتجي ... إذا الحبل من إحدى حبائبي انصرم)\n(وإني لمزر بالمطي تنقلي ... عليه وإيقاعي المهند بالعصم)\n(وإني لأعطي غثها وسمينها ... وأسري إذا ما الليل ذو الظلم ادلهم)\n(إذا الثلج أضحى في الديار كأنه ... مناثر ملح في السهول وفي الأكم)\n(حذارا على ما كان قدم والدي ... إذا روحتهم حرجف تطرد الصرم)\n(وأترك ندماني يجر ثيابه ... وأوصاله من غير جرح ولا سقم)\n(ولكنها من رية بعد رية ... معتقة صهباء راووقها رذم)\n(من العانيات من مدام كأنها ... مذابح غزلان يطيب بها الشمم)\n(وإذ إخوتي حولي وإذ أنا شامخ ... وإذ لا أجيب العاذلات من الصمم)\n(ألم يأتها أني صحوت وأنني ... تحالمت حتى ما أعارم من عرم)\n(وأطرقت إطراق الشجاع ولو يرى ... مساغا لنابيه الشجاع لقد أزم)\n(وقد علمت سعد بأني عميدها ... قديما وأني لست أهضم من هضم)\nقول لا أظلم أحدا من قومي وأتهضمه فيطلبني بمثل ذلك أي أرفع نفسي عن هذا\n(خزيمة رداني الفعال ومعشر ... قديما بنوا لي سورة المجد والكرم)\n(إذا ما وردنا الماء كانت حماته ... بنو أسد يوما على رغم من رغم)\n(أرادت عرارا بالهوان ومن يرد ... عرارا لعمري بالهوان فقد ظلم)","topic":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره","topicNo":118,"sp":0,"spl":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره — طلق زوجته بعد أن يئس من الصلح بينها وبين ابنه","loc":2059},
{"id":"b118-2","bab":"الجزء 11","sec":"طلق زوجته بعد أن يئس من الصلح بينها وبين ابنه عرار","page":"ج11 ص204","text":"وذكر باقي الأبيات قال ابن الأعرابي وأبو بكر الشيباني فجهد عمرو بن شأس أن يصلح بين ابنه وامرأته أم حسان فلم يمكنه ذلك وجعل الشر يزيد بينهما فلما رأى ذلك طلقها ثم ندم ولام نفسه فقال في ذلك\n(تذكر ذكرى أم حسان فاقشعر ... على دبر لما تبين ما ائتمر)\n(فكدت أذوق الموت لو أن عاشقا ... أمر بموساه الشوارب فانتحر)\n(تذكرتها وهنا وقد حال دونها ... رعان وقيعان بها الزهر والشجر)\n(فكنت كذات البو لما تذكرت ... لها ربعا حنت لمعهده سحر)\n(حفاظا ولم تنزع هواي أثيمة ... كذلك شأو المرء يخلجه القدر)\nال ابن الأعرابي الأثيمة الفعيلة من الإثم وهي مرفوعة بفعلها كأنه قال لم تنزع الأثيمة هواي تخلجه تصرفه شأوه همه ونيته قال وقال فيها أيضا\n(ألم تعلمي يا أم حسان أنني ... إذا عبرة نهنهتها فتخلت)\n(رجعت الى صدر كجرة حنتم ... إذا قرعت صفرا من الماء صلت)","topic":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره","topicNo":118,"sp":0,"spl":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره — طلق زوجته بعد أن يئس من الصلح بينها وبين ابنه","loc":2060},
{"id":"b118-3","bab":"الجزء 11","sec":"خبر ابنه عرار مع عبد الملك","page":"ج11 ص205","text":"أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن إسحاق بن محمد بن سلام وأخبرني إبراهيم بن أيوب عن ابن قتيبة قال قال ابن سلام لما قتل الحجاج عبد الرحمن بن محمد بن الأشعث بعث برأسه مع عرار بن عمرو بن شأس الأسدي فلما ورد به وأوصل كتاب الحجاج جعل عبد الملك يعجب من بيانه وفصاحته مع سواده فقال متمثلا\n(وإن عرارا إن يكن غير واضح ... فإني أحب الجون ذا المنكب العمم)\nضحك عرار من قوله ضحكا غاظ عبد الملك فقال له مم ضحكت ويحك قال أتعرف عرارا يا أمير المؤمنين الذي قيل فيه هذا الشعر قال لا قال أنا والله هو فضحك عبد الملك ثم قال حظ وافق كلمة وأحسن جائزته وسرحه وقال الطوسي أغار ملك من ملوك غسان يقال له عدي وهو ابن أخت الحارث بن أبي شمر الغساني على بني أسد فلقيته بنو سعد بن ثعلبة بن دودان بالفرات ورئيسهم ربيعة بن حذار فاقتتلوا قتالا شديدا فقتلت بنو سعد عديا اشترك في قتله عمرو وعمير ابنا حذار أخوا ربيعة وأمهما امرأة من كنانة يقال لها تماضر إحدى بني فراس بن غنم وهي التي يقال لها مقيدة الحمار فقالت فاختة بنت عدي\n(لعمرك ما خشيت على عدي ... رماح بني مقيدة الحمار)\n(ولكني خشيت على عدي ... رماح الجن أو إياك حار)\nعني الحارث بن أبي شمر خاله\n(قتيل ما قتيل ابني حذار ... بعيد الهم طلاع النجار)\nيروى جواب الصحاري فقال عمرو بن شأس في ذلك\n(متى تعرف العينان أطلال دمنة ... لليلى بأعلى ذي معارك تدمعا)\n(على النحر والسربال حتى تبله ... سجوم ولم تجزع على الدار مجزعا)\n(خليلي عوجا اليوم نقض لبانة ... وإلا تعوجا اليوم لا ننطلق معا)\n(وإن تنظراني اليوم أتبعكما غدا ... قياد الجنيب أو أذل وأطوعا)\nهي قصيدة غنى في هذه الأبيات إبراهيم ثقيلا أول بالوسطى عن الهشامي والدمنة في هذا الموضع آثار الناس وما سودوا وهي في غير هذا الموضع الحقد يقال في صدره علي إحنة وترة وضب وحسيكة ودمنة وعوجا احبسا وتلبثا عاج يعوج عياجا وما أعيج بكلامك أي ما ألتفت إليه واللبانة الحاجة يقال لي في كذا لبانة ولبونة ولماسة ووطر وحوجاء ممدودة وقوله لا ننطلق معا يقول إن لم تقفا تأخرت عنكما فتفرقنا وتنظراني تنظراني يقال نظرته أنظره وأنظرته أنظره إنظارا ونظرة أيضا إذا أخرته قال الله عز و جل ( فنظرة إلى ميسرة\nالجنيب المجنوب من فرس وغيره والجنيب أيضا الذي يشتكي رئته من شدة العطش\nوقال الطوسي قال الأصمعي جاور رجل من بني عامر بن صعصعة عمرو ابن شأس ومعه بنت له من أجمل الناس وأظرفهم فخطبها عمرو إلى أبيها فقال أبوها أما ما دمت جارا لكم فلا لأني أكره أن يقول الناس غصبه أمره ولكن إذا أتيت قومي فاخطبها إلي أزوجكها فوجد عمرو من ذلك في نفسه وأعتقد ألا يتزوجها أبدا إلا أن يصيبها مسبية فلما ارتحل أبوها هم عمرو بغزو قومها فسار في أثر أبيها فلما وقعت عينه عليه وظفر به استحيا من جواره وما كان بينهما من العهد والميثاق فنظر إلى الجارية أمامهم وقد أخرجت رأسها من الهودج تنظر إليه فلما رآها رجع مستحييا متذمما منها وكان عمرو مع شجاعته ونجدته من أهل الخير فقال في ذلك\n(إذا نحن أدلجنا وأنت أمامنا ... كفى لمطايانا بوجهك هاديا)\n(أليس يزيد العيس خفة أذرع ... وإن كن حسرى أن تكوني أماميا)\n(ولولا اتقاء الله والعهد قد رأى ... منيته مني أبوك اللياليا)\n(ونحن بنو خير السباع أكيلة ... وأحربه إذا تنفس عاديا)\n(بنو أسد ورد يشق بنابه ... عظام الرجال لا يجيب الرواقيا)\n(متى تدع قيسا أدع خندف إنهم ... إذا ما دعوا أسمعت ثم الدواعيا)\n(لنا حاضر لم يحضر الناس مثله ... وباد إذا عدوا علينا البواديا)\nلغناء لإسحاق الموصلي ثاني ثقيل في الأول والثاني من الأبيات وفيه لحن قديم\nأخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثنا الحزامي قال حدثنا معن بن عيسى عن رجل عن سويد بن أبي رهم قال قلت لابن سيرين ما تقول في الشعر قال هو كلام حسنه حسن وقبيحه قبيح قلت فما تقول في النسيب قال لعلك تريد مثل قول الشاعر\n(إذا نحن أدلجنا وأنت أمامنا ... كفى لمطايانا بوجهك هاديا)\n(أليس يزيد العيس خفة أذرع ... وإن كن حسرى أن تكوني أماميا)\nال وأراد بإنشاده إياهما أنك قد رأيتني أحفظ هذا الجنس وأرويه وأنشدتك إياه فلو كان به بأس ما أنشدته","topic":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره","topicNo":118,"sp":1,"spl":"خبر ابنه عرار مع عبد الملك","song":3,"loc":2061},
{"id":"b118-4","bab":"الجزء 11","sec":"خبر ابنه عرار مع عبد الملك","page":"ج11 ص205","text":"(فإن تكن القتلى بواء فإنكم ... فتى ما قتلتم آل عوف بن عامر)\n(فتى كان أحيا من فتاة حيية ... وأشجع من ليث بخفان خادر)\nروضه من الطويل البواء بالباء التكافؤ يقال ما فلان لفلان ببواء أي ما هو له بكفء أن يقتل به وما في قولها فتى ما قتلتم صلة وآل عوف نداء وخفان موضع مشهور وخادر مقيم في مكمنه وغيله وهو مأخوذ من الخدر الشعر لليلى الأخيلية ترثي توبة بن الحمير والغناء لإسحاق بن\nإبراهيم الموصلي رمل بإطلاق الوتر في مجرى البنصر وفيه لإبراهيم خفيف ثقيل بالوسطى عن حبش وفي هذه القصيدة عدة أغان تذكر مع سائر ما قاله توبة في ليلى وقالت فيه من الشعر عند أنقضاء الخبر في مقتله إن شاء الله تعالى","topic":"نسب عمرو بن شأس وأخباره في هذا الشعر وغيره","topicNo":118,"sp":2,"spl":"خبر ابنه عرار مع عبد الملك","loc":2062},
{"id":"b119-1","bab":"الجزء 11","sec":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","page":"ج11 ص210","text":"هي ليلى بنت عبد الله بن الرحال وقيل ابن الرحالة بن شداد بن كعب بن معاوية وهو الأخيل وهو فارس الهرار ابن عبادة بن عقيل بن كعب بن ربيعة بن عامر بن صعصعة وهي من النساء المتقدمات في الشعر من شعراء الإسلام وكان توبة بن الحمير يهواها وهو توبة بن الحمير بن حزم بن كعب بن خفاجة بن عمرو بن عقيل أخبرني ببعض أخبارهما أحمد بن عبد العزيز الجوهري ومحمد بن حبيب ابن نصر المهلبي قالا حدثنا عبد الله بن أبي سعد الوراق قال حدثنا محمد بن علي أبو المغيرة قال حدثنا أبي عن أبي عبيدة قال حدثني أنيس بن عمرو العامري قال كان توبة بن الحمير أحد بني الأسدية وهي عامرة بنت والبة بن الحارث وكان يتعشق ليلى بنت عبد الله بن الرحالة ويقول فيها الشعر فخطبها إلى أبيها فأبى أن يزوجه إياها وزوجها في بني الأدلع فجاء يوما كما كان يجيء لزيارتها فإذا هي سافرة ولم ير منها إليه بشاشة فعلم أن ذلك لأمر ما كان فرجع إلى راحلته فركبها ومضى وبلغ بني الأدلع أنه أتاها فتبعوه ففاتهم فقال توبة في ذلك\n(نأتك بليلى دارها لا تزورها ... وشطت نواها واستمر مريرها)\nهي طويلة يقول فيها\n(وكنت إذا ما جئت ليلى تبرقعت ... فقد رابني منها الغداة سفورها)","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":0,"spl":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله — كانت تخرج إلى توبة بن الحمير في برقع","loc":2063},
{"id":"b119-2","bab":"الجزء 11","sec":"كانت تخرج إلى توبة بن الحمير في برقع","page":"ج11 ص211","text":"أخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال كان توبة بن الحمير إذا أتى ليلى الأخيلية خرجت إليه في برقع فلما شهر أمره شكوه الى السلطان فأباحهم دمه إن أتاهم فمكثوا له في الموضع الذي كان يلقاها فيه فلما علمت به خرجت سافرة حتى جلست في طريقة فلما رآها سافرة فطن لما أرادت وعلم أنه قد رصد وأنها سفرت لذلك تحذره فركض فرسه فنجا وذلك قوله\n(وكنت إذا ما جئت ليلى تبرقعت ... فقد رابني منها الغداة سفورها)\nال أبو عبيدة وحدثني غير أنيس أنه كان يكثر زيارتها فعاتبه أخوها وقومها فلم يعتب وشكوه الى قومه فلم يقلع فتظلموا منه إلى السلطان فأهدر دمه إن أتاهم وعلمت ليلى بذلك وجاءها زوجها وكان غيورا فحلف لئن لم تعلمه بمجيئه ليقتلنها ولئن أنذرته بذلك ليقتلنها قالت ليلى وكنت أعرف الوجه الذي يجيئني منه فرصدوه بموضع ورصدته بآخر فلما اقبل لم أقدر على كلامه لليمين فسفرت وألقيت البرقع عن رأسي فلما رأى ذلك أنكره فركب راحلته ومضى ففاتهم\nأخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني أحمد ابن معاوية بن بكر قال حدثني أبو زياد الكلابي قال خرج رجل من بني كلاب ثم من بني الصحمة يبتغي إبلا له حتى أوحش وأرمل ثم أمسى بأرض فنظر إلى بيت بواد فأقبل حتى نزل حيث ينزل الضيف فأبصر امرأة وصبيانا يدورون بالخباء فلم يكلمه أحد فلما كان بعد هدأة من الليل سمع جرجرة إبل رائحة وسمع فيها صوت رجل حتى جاء بها فأناخها على البيت ثم تقدم فسمع الرجل يناجي المرأة ويقول ما هذا السواد حذاءك قالت راكب أناخ بنا حين غابت الشمس ولم أكلمه فقال لهاكذبت ما هو إلا بعض خلانك ونهض يضربها وهي تناشده قال الرجل فسمعته يقول والله لا أترك ضربك حتى يأتي ضيفك هذا فيغيثك فلما عيل صبرها قالت يا صاحب البعير يا رجل وأخذ الصحمي هراوته ثم أقبل يحضر حتى أتاها وهو يضربها فضربه ثلاث ضربات أو أربعا ثم أدركته المرأة فقالت يا عبد الله مالك ولنا نح عنا نفسك فانصرف فجلس على راحلته وأدلج ليلته كلها وقد ظن أنه قتل الرجل وهو لا يدري من الحي بعد حتى أصبح في أخبية من الناس ورأى غنما فيها أمة مولدة فسألها عن أشياء حتى بلغ به الذكر فقال أخبريني عن أناس وجدتهم بشعب كذا فضحكت وقالت إنك لتسألني عن شيء وأنت به عالم فقال وما ذاك لله بلادك فوالله ما أنا به عالم قالت ذاك خباء ليلى الأخيلية وهي أحسن الناس وجها وزوجها رجل غيور فهو يعزب بها عن\nالناس فلا يحل بها معهم والله ما يقربها أحد ولا يضيفها فكيف نزلت أنت بها قال إنما مررت فنظرت إلى الخباء ولم أقربه وكتمها الأمر وتحدث الناس عن رجل نزل بها فضربها زوجها فضربه الرجل ولم يدر من هو فلما أخبر باسم المرأة وأقر على نفسه تغنى بشعر دل فيه على نفسه وقال\n(ألا يا ليل أخت بني عقيل ... أنا الصحمي إن لم تعرفيني)\n(دعتني دعوة فحجزت عنها ... بصكات رفعت بها يميني)\n(فإن تك غيرة أبرئك منها ... وإن تك قد جننت فذا جنوني)","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":0,"spl":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله — كانت تخرج إلى توبة بن الحمير في برقع","loc":2064},
{"id":"b119-3","bab":"الجزء 11","sec":"جوابها للحجاج عندما ارتاب بأمرها مع توبة","page":"ج11 ص213","text":"أخبرني الحسن بن علي قال حدثنا رشد بن حنتم الهلالي قال حدثني أيوب بن عمرو عن رجل يقال له ورقاء قال سمعت الحجاج يقول لليلى الأخيلية إن شبابك قد ذهب واضمحل أمرك وأمر توبة فأقسم عليك إلا صدقتني هل كانت بينكما ريبة قط أو خاطبك في ذلك قط فقال لا والله أيها الأمير إلا أنه قال لي ليلة وقد خلونا كلمة ظننت أنه قد خضع فيها لبعض الأمر فقلت له\n(وذي حاجة قلنا له لا تبح بها ... فليس إليها ما حييت سبيل)\n(لنا صاحب لا ينبغي أن نخونه ... وأنت لأخرى فارغ وحليل)\nفلا والله ما سمعت منه ريبة بعدها حتى فرق بيننا الموت قال لها الحجاج فما كان منه بعد ذلك قالت وجه صاحبا له إلى حاضرنا فقال إذا أتيت الحاضر من بني عبادة بن عقيل فاعل شرفا ثم أهتف بهذا البيت\n(عفا الله عنها هل أبيتن ليلة ... من الدهر لا يسري إلي خيالها)\nلما فعل الرجل ذلك عرفت المعنى فقلت له\n(وعنه عفا ربي وأحسن حاله ... عزيز علينا حاجة لا ينالها)\nسبة ما في هذا الخبر من الغناء وهو أجمع في قصيدة توبة\n(نأتك بليلى دارها لا تزورها ... )\nوت\n(حمامة بطن الواديين ترنمي ... سقاك من الغر الغوادي مطيرها)\n(أبيني لنا لا زال ريشك ناعما ... ولا زلت في خضراء دان بريرها)\n(وأشرف بالقوز اليفاع لعلني ... أرى نار ليلى أو يراني بصيرها)\n(وكنت إذا ما جئت ليلى تبرقعت ... فقد رابني منها الغداة سفورها)\n(علي دماء البدن إن كان بعلها ... يرى لي ذنبا غير أني أزورها)\n(وأني إذا ما زرتها قلت يا اسلمي ... وما كان في قولي اسلمي ما يضيرها)\n(وغيرني إن كنت لما تغيري ... هواجر تكتنينها وأسيرها)\n(وأدماء من سر المهارى كأنها ... مهاة صوار غير ما مس كورها)\n(قطعت بها أجواز كل تنوفة ... مخوف رداها كلما استن مورها)\n(ترى ضعفاء القوم فيها كأنهم ... دعاميص ماء نش عنها غديرها)\nنى في الأربعة الأبيات الأول فليح بن أبي العوراء ثاني ثقيل بالبنصر عن عمرو وغنى في الثالث والرابع ابن سريج رملا بالوسطى عن الهشامي وعلي بن يحيى المنجم وذكر غيرهما أنه لمحمد بن إسحاق بن عمرو بن بزيع وغنى فيها الهذلي ثقيلا أول بالبنصر عن حبش وغنى ابن محرز في علي دماء البدن والذي بعده خفيف رمل بالبنصر عن عمرو وعن ابن مسجح في\n(وغيرني إن كنت لما تغيري ... )\nما بعده لحن ذكر أن عبد الله بن جعفر رواه الأبيات وأمره أن يغني بها أخبرني بذلك إسماعيل بن يونس الشيعي عن عمر بن شبة عن إسحاق الموصلي عن ابن الكلبي في خبر قد ذكرته في أخبار ابن مسجح وذكر الهشامي أن اللحن ثقيل أول بالوسطى حدثنا أحمد بن عبيد الله بن عمار قال حدثني محمد بن يعقوب بالأنبار قال حدثني من أنشد الأصمعي\n(علي دماء البدن إن كان زوجها ... يرى لي ذنبا غير أني أزورها)\n(وأني إذا ما زرتها قلت يا اسلمي ... فهل كان في قولي اسلمي ما يضيرها)\nقال الأصمعي شكوى مظلوم وفعل ظالم","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":1,"spl":"جوابها للحجاج عندما ارتاب بأمرها مع توبة","loc":2065,"partialRef":{"sid":"b27-3","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b119-4","bab":"الجزء 11","sec":"سبب وكيفية مقتل توبة بن الحمير","page":"ج11 ص216","text":"أخبرني بالسبب في مقتل توبة محمد بن الحسن بن دريد إجازة عن أبي حاتم السجستاني عن أبي عبيدة والحسن بن علي الخفاف قال حدثنا عبد الله بن أبي سعد قال حدثنا محمد بن علي بن المغيرة عن أبيه عن أبي عبيدة وأخبرني علي بن سليمان الأخفش قال أخبرنا أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي ورواية أبي عبيدة أتم واللفظ له قال أبو عبيدة كان الذي هاج مقتل توبة بن الحمير بن حزم بن كعب بن خفاجة بن عمرو ابن عقيل بن كعب بن ربيعة بن عامر بن صعصعة أنه كان بينه وبين بني عامر بن عوف بن عقيل لحاء ثم إن توبة شهد بني خفاجة وبني عوف وهم يختصمون عند همام بن مطرف العقيلي في بعض أمورهم قال وكان مروان بن الحكم يومئذ أميرا على المدينة في خلافة معاوية بن أبي سفيان فاستعمله على صدقات بني عامر قال فوثب ثور بن أبي سمعان بن كعب بن عامر بن عوف بن عقيل على توبة بن الحمير فضربه بجرز وعلى توبة الدرع والبيضة فجرح أنف البيضة وجه توبة فأمر همام بثور بن أبي سمعان\nفأقعد بين يدي توبة فقال خذ بحقك يا توبة فقال له توبة ما كان هذا إلا عن أمرك وما كان ليجترىء علي عند غيرك وأم همام صوبانة بنت جون بن عامر بن عوف بن عقيل فاتهمه توبة لذلك فانصرف ولم يقتص منه فمكثوا غير كثير وإن توبة بلغه أن ثور بن أبي سمعان خرج في نفر من رهطه إلى ماء من مياه قومه يقال له قوباء يريدون مالهم بموضع يقال له جرير بتثليث قال وبينهما فلاة فاتبعه توبة في ناس من أصحابه فسأل عنه وبحث حتى ذكر له أنه عند رجل من بني عامر بن عقيل يقال له سارية بن عمير بن أبي عدي وكان صديقا لتوبة فقال توبة والله لا نطرقهم عند سارية الليلة حتى يخرجوا عنه فأرادوا أن يخرجوا حين يصبحون فقال لهم سارية ادرعوا الليل فإني لا آمن توبة عليكم الليلة فإنه لا ينام عن طلبكم قال فلما تعشوا ادرعوا الليل في الفلاة وأقعد له توبة رجلين فغفل صاحبا توبة فلما ذهب الليل فزع توبة وقال لقد اغتررت الى رجلين ما صنعا شيئا وإني لأعلم أنهم لم يصبحوا بهذه البلاد فاقتص آثارهم فإذا هو بأثر القوم قد خرجوا فبعث الى صاحبيه فأتياه فقال دونكما هذا الجمل فأوقراه من الماء في مزادتيه ثم اتبعا أثري فإن خفي عليكم أن تدركاني فإني سأنور لكما إن أمسيتما دوني وخرج توبة في أثر القوم مسرعا حتى إذا انتصف النهار جاوز علما يقال له أفيح في الغائط فقال لأصحابه هل ترون سمرات إلى جنب قرون بقر وقرون\nبقر مكان هنالك فإن ذلك مقيل القوم لم يتجاوزوه فليس وراءه ظل فنظروا فقال قائل أرى رجلا يقود بعيرا كأنه يقوده لصيد قال توبة ذلك ابن الحبترية وذلك من أرمى من رمى فمن له يختلجه دون القوم فلا ينذرون بنا قال فقال عبد الله أخو توبة أنا له قال فاحذر لا يضربنك وإن استطعت أن تحول بينه وبين أصحابه فافعل فخلى طريق فرسه في غمض من الأرض ثم دنا منه فحمل عليه فرماه ابن الحبترية قال وبنو الحبتر ناس من مذحج في بني عقيل فعقر فرس عبد الله أخي توبة واختل السهم ساق عبد الله فانحاز الرجل حتى أتى أصحابه فانذرهم فجمعوا ركابهم وكانت متفرقة قال وغشيهم توبة ومن معه فلما رأوا ذلك صفوا رحالهم وجعلوا السمرات في نحو وأخذوا سلاحهم ودرقهم وزحف إليهم توبة فارتمى القوم لا يغني أحد منهم شيئا في أحد ثم إن توبة وكان يترس له أخوه عبد الله قال يا أخي لا تترس لي فإني رأيت ثورا كثيرا ما يرفع الترس عسى أن أوافق منه عند رفعه مرمى فأرميه قال ففعل فرماه توبة على حلمة ثديه فصرعه وجال القوم فغشيهم توبة وأصحابه فوضعوا فيهم السلاح حتى تركوهم صرعى وهم سبعة نفر ثم إن ثورا قال انتزعوا هذا السهم عني قال توبة ما وضعناه لننتزعه فقال أصحاب توبة أنج بنا نأخذ آثارنا ونلحق راويتنا فقد أخذنا ثأرنا من هؤلاء وقد متنا عطشا قال توبة كيف بهؤلاء القوم الذين لا يمنعون ولا يمتنعون فقالوا","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":2,"spl":"سبب وكيفية مقتل توبة بن الحمير","loc":2066},
{"id":"b119-5","bab":"الجزء 11","sec":"سبب وكيفية مقتل توبة بن الحمير","page":"ج11 ص216","text":"ابعدهم الله توبة ما أنا بفاعل وما هم إلا عشيرتكم ولكن تجيء الراوية فأضع لهم ماء وأغسل عنهم دماءهم وأخيل عليهم من السباع والطير لا تأكلهم حتى أوذن قومهم بهم بعمق فأقام توبة حتى أتته الراوية قبل الليل فسقاهم من الماء وغسل عنهم الدماء وجعل في أساقيهم ماء ثم خيل لهم بالثياب على الشجر ثم مضى حتى طرق من الليل سارية بن عويمر بن أبي عدي العقيلي فقال إنا قد تركنا رهطا من قومكم بسمرات من قرون بقر فأدركوهم فمن كان حيا فداووه ومن كان ميتا فادفنوه ثم انصرف فلحق بقومه وصبح سارية القوم فاحتملهم وقد مات ثور بن أبي سمعان ولم يمت غيره فلم يزل توبة خائفا وكان السليل بن ثور المقتول راميا كثير البغي والشر فأخبر بغرة من توبة وهو بقنة من قنان الشرف يقال لها قنة بني الحمير فركب في نحو ثلاثين فارسا حتى طرقه فترقى توبة ورجل من إخوته في الجبل فأحاطوا بالبيوت فناداهم وهو في الجبل هأنذا من تبغون فاجتنبوا البيوت فقالوا إنكم لن تستطيعوه وهو في الجبل ولكن خذوا ما استدف لكم من ماله فأخذوا أفراسا له ولإخوته وانصرفوا ثم إن توبة غزاهم فمر على أفلت بن حزن بن معاوية بن خفاجة ببطن بيشة\nفقال يا توبة أين تريد قال أريد الصبيان من بني عوف بن عقيل قال لا تفعل فإن القوم قاتلوك فمهلا قال لا أقلع عنهم ما عشت ثم ضرب بطن فرسه فاستمر به يحضر وهو يرتجز ويقول\n(تنجو إذا قيل لها يعاط ... تنجو بهم من خلل الأمشاط)\nتى انتهى الى مكان يقال له حجر الراشدة ظليل أسفله كالعمود وأعلاه منتشر فاستظل فيه هو وأصحابه حتى إذا كان بالهاجرة مرت عليه إبل هبيرة بن السمين أخي بني عوف بن عقيل واردة ماء لهم يقال له طلوب فأخذها وخلى طريق راعيها وقال له إذا أتيت صدغ البقرة مولاك فأخبره أن توبة أخذ الإبل ثم انصرف توبة يطرد الإبل قال فلما ورد العبد على مولاه فأخبره نادى في بني عوف وقال حتام هذا فتعاقدوا بينهم نحوا من ثلاثين فارسا ثم اتبعوه ونهضت امرأة من بني خثعم من بني الهرة كانت في بني عوف وكانت تؤخذ لهم فقالت أروني أثره فخرجوا فأروها أثره فأخذت من ترابه فسافته فقالت اطلبوه فإنه سيحبس عليكم فطلبوه فسبقهم فتلاوموا بينهم وقالوا ما نرى له أثرا وما نراه إلا وقد سبقكم قال وخرج توبة حتى إذا كان بالمضجع من أرض بني كلاب جعل نذارته وحبس أصحابه حتى إذا كان بشعب من هضبة يقال لها هند من كبد المضجع جعل ابن عم له يقال له قابض بن عبد الله ربيئة له على رأس الهضبة فقال انظر فإن شخص لك شيء فأعلمنا فقال عبد الله بن\nالحمير يا توبة إنك حائن أذكرك الله فوالله ما رأيت يوما أشبه بسمرات بني عوف يوم أدركناهم في ساعتهم التي أتيناهم فيها منه فانج إن كان بك نجاة قال دعني فقد جعلت ربيئة ينظر لنا قال يرجع بنو عوف بن عقيل حين لم يجدوا أثر توبة فيلقون رجلا من غني فقالوا له هل أحسست في مجيئك أثر خيل أو أثر إبل قال لا والله قالوا كذبت وضربوه فقال يا قوم لا تضربوني فإني لم أجد أثرا ولقد رأيت زهاء كذا وكذا إبلا شخوصا في هاتيك الهضبة وما أدري ما هو فبعثوا رجلا منهم يقال له يزيد بن رويبة لينظر ما في الهضبة فأشرف على القوم فلما رآهم ألوى بثوبه لأصحابه حتى جاؤوا فحمل أولهم على القوم حتى غشي توبة وفزع توبة وأخوه الى خيلهما فقام توبة إلى فرسه فغلبته لا يقدر على أن يلجمها ولا وقفت له فخلى طريقها وغشيه الرجل فاعتنقه فصرعه توبة وهو مدهوش وقد لبس الدرع على السيف فانتزعه ثم أهوى به ليزيد بن رويبة فاتقاه بيده فقطع منها وجعل يزيد يناشده رحم صفية وصفية أم له من بني خفاجة وغشي القوم توبة من ورائه فضربوه فقتلوه وعلقهم عبد الله بن الحمير يطعنهم بالرمح حتى انكسر قال فلما فرغوا من توبة لووا على عبد الله بن الحمير فضربوا رجله فقطعوها فلما وقع بالأرض أشرع سيفه وحده ثم جثا على ركبتيه وجعل يقول هلموا ولم يشعر القوم بما أصابه وانصرف بنو عوف بن عقيل وولى قابض منهزما حتى لحق بعبد العزيز بن زرارة الكلابي فأخبره الخبر قال فركب عبد العزيز حتى أتى توبة فدفنه وضم أخاه ثم ترافع القوم إلى مروان بن الحكم فكافأ بين الدمين وحملت الجراحات ونزل بنو عوف بن عقيل البادية ولحقوا بالجزيرة والشام","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":3,"spl":"سبب وكيفية مقتل توبة بن الحمير","loc":2067},
{"id":"b119-6","bab":"الجزء 11","sec":"ابو عبيدة يروي مقتل توبة وسببه","page":"ج11 ص222","text":"قال أبو عبيدة وقد كان توبة أيضا يغير زمن معاوية بن أبي سفيان على قضاعة وخثعم ومهرة وبني الحارث بن كعب وكانت بينهم وبين بني عقيل مغاورات فكان توبة إذا أراد الغارة عليهم حمل الماء معه في الروايا ثم دفنه في بعض المفازة على مسيرة يوم منها فيصيب ما قدر عليه من إبلهم فيدخلها المفازة فيطلبه القوم فإذا دخل المفازة أعجزهم فلم يقدروا عليه فانصرفوا عنه قال فمكث كذلك حينا ثم إنه أغار في المرة الأولى التي قتل فيها هو وأخوه عبد الله بن الحمير ورجل يقال له قابض بن أبي عقيل فوجد القوم قد حذروا فانصرف توبة مخفقا لم يصب شيئا فمر برجل من بني عوف بن عامر بن عقيل متنحيا عن قومه فقتله توبة وقتل رجلا كان معه من رهطه واطرد إبلهما ثم خرج عامدا يريد عبد العزيز بن زرارة بن جزء بن سفيان بن عوف بن كلاب وخرج ابن عم لثور بن أبي سمعان المقتول فقال له خزيمة صر إلى بني عوف بن عامر بن عقيل فأخبرهم الخبر فركبوا في طلب توبة فأدركوه في أرض بني خفاجة وقد أمن في نفسه فنزل وقد كان أسرى يومه وليلته فاستظل ببرديه وألقى عنه درعه وخلى عن فرسه الخوصاء تتردد قريبا منه وجعل قابضا ربيئة له ونام فأقبلت بنو عوف بن عامر متقاطرين لئلا يفطن لهم أحد فنظر قابض فأبصر رجلا منهم فأقبل الى توبة فأنبهه فقال توبة ما رأيت قال رأيت شخص رجل واحد فنام ولم يكترث له وعاد قابض الى مكانه فغلبته عيناه فنام قال فأقبل القوم على\nتلك الحال فلم يشعر بهم قابض حتى غشوه فلما رآهم طار على فرس وأقبل القوم إلى توبة وكان أول من تقدم غلام أمرد على فرسه عري يقال له يزيد بن رويبة بن سالم بن كعب بن عوف بن عامر بن عقيل ثم تلاه ابن عمه عبد الله بن سالم ثم تتابعوا فلما سمع توبة وقع الخيل نهض وهو وسنان فلبس درعه على سيفه ثم صوت بفرسه الخوصاء فأتته فلما أراد أن يركبها أهوت ترمحه ثلاث مرات فلما رأى ذلك لطم وجهها فأدبرت وحال القوم بينه وبينها فأخذ رمحه وشد على يزيد بن رويبة فطعنه فأنفذ فخذيه جميعا وشد على توبة ابن عم الغلام عبد الله بن سالم فطعنه فقتله وقطعوا رجل عبد الله فلما رجع عبد الله بعد ذلك الى قومه لاموه وقالوا له فررت عن أخيك فقال عبد الله بن الحمير في ذلك قال أبو عبيدة وحدثني أيضا مزرع بن عبد الله بن همام بن مطرف بن الأعلم قال كان أهل دار من بني جشم بن بكر بن هوازن يقال لهم بنو الشريد حلفاء لبني عداد بن خفاجة في الإسلام فكان بينهم وبين خميس بن ربيعة رهط قومه قتال على ماءة تدعى الحليفة وعامتها لجد بن همام قال وشهد عبد الله بن الحمير ذلك وهو أعرج عرج يوم قتل توبة فلم يغن كثير غناء فقالت بنو عقيل لو توبة تلقاهم لبلوا منه بغير أفوق ناصل فقال عبد الله بن الحمير يعتذر إليهم","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":4,"spl":"ابو عبيدة يروي مقتل توبة وسببه","loc":2068},
{"id":"b119-7","bab":"الجزء 11","sec":"شعر عبد الله اخي توبة في اعتذاره لقومه","page":"ج11 ص224","text":"(تأوبني بعارمة الهموم ... كما يعتاد ذا الدين الغريم)\n(كأن الهم ليس يريد غيري ... ولو أمسى له نبط وروم)\n(علام تقوم عاذلتي تلوم ... تؤرقني وما انجاب الصريم)\n(فقلت لها رويدا كي تجلى ... غواشي النوم والليل البهيم)\n(ألما تعلمي أني قديما ... إذا ما شئت أعصي من يلوم)\n(وأن المرء لا يدري إذا ما ... يهم علام تحمله الهموم)\n(وقد تعدي على الحاجات حرف ... كركن الرعن ذعلبة عقيم)\n(مداخلة الفقار وذات لوث ... على الحزان مقحمة غشوم)\n(كأن الرحل منها فوق جأب ... بذات الحاذ معقله الصريم)\n(طباه برجلة البقار برق ... فبات الليل منتصبا يشيم)\n(فبينا ذاك إذ هبطت عليه ... دلوح المزن واهية هزيم)\n(تهب لها الشمال فتمتريها ... ويعقبها بنافحة نسيم)\n(يكب إذا الرذاذ جرى عليه ... كما يصغي الى الآسي الأميم)\n(إذا ما قال أقشع جانباه ... نشت من كل ناحية غيوم)\n(فأشعر ليله أرقا وقرا ... يسهره كما أرق السليم)\n(ألا من يشتري رجلا برجل ... تخونها السلاح فما تسوم)\n(تلومك في القتال بنو عقيل ... وكيف قتال أعرج لا يقوم)\n(ولو كنت القتيل وكان حيا ... لقاتل لا ألف ولا سؤوم)\n(ولا جثامة ورع هيوب ... ولا ضرع إذا يمسي جثوم)\nال ثم إن خفاجة رهط توبة جمعوا لبني عوف بن عامر بن عقيل الذين قتلوا توبة فلما بلغهم الخبر لحقوا ببني الحارث بن كعب ثم افترقت بنو خفاجة فلما بلغ ذلك بني عوف رجعوا فجمعت لهم بنو خفاجة أيضا قبائل عقيل فلما رأت ذلك بنو عوف بن عامر بن عقيل لحقوا بالجزيرة فنزلوها\nوهم رهط إسحاق بن مسافر بن ربيعة بن عاصم بن عمرو بن عامر بن عقيل ثم إن بني عامر بن صعصعة صاروا في أمرهم إلى مروان بن الحكم وهو والي المدينة لمعاوية بن أبي سفيان فقالوا ننشدك الله أن تفرق جماعتنا فعقل توبة وعقل الآخرين معاقل العرب مائة من الإبل فأدتها بنوعامر قال فخرجت بنو عوف بن عامر قتلة توبة فلحقوا بالجزيرة فلم يبق بالعالية منهم أحد وأقامت بنو ربيعة بن عقيل وعروة بن عقيل وعبادة بن عقيل بمكانهم بالبادية","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":5,"spl":"شعر عبد الله اخي توبة في اعتذاره لقومه","loc":2069},
{"id":"b119-8","bab":"الجزء 11","sec":"رواية اخرى لأبي عبيدة عن مقتل توبة","page":"ج11 ص226","text":"قال أبو عبيدة وحدثنا مزرع بن عمرو بن همام قال أبو عبيدة وكان معي أبو الخطاب وغيره قال توبة بن حمير بن ربيعة بن كعب بن خفاجة بن عمرو بن عقيل وأمه زبيدة فهاج بينه وبين السليل بن ثور بن أبي سمعان بن عامر بن عوف بن عقيل كلام وكان شريرا ونظير توبة في القوة والبأس فبلغ الحور وهو الكلام إلى أن أوعد كل واحد منهما صاحبه فالتقى بعد ذلك توبة والسليل على غدير من ماء السماء فرمى توبة السليل فقتله ثم إن توبة أغار ثانية على إبل بني السمين بن كعب بن عوف بن عقيل واردة ماءهم فاطردها واتبعوه وهم سبعة نفر يزيد بن رويبة وعبد الله بن سالم ومعاوية بن عبد الله قال أبو عبيدة ولم يذكر غير هؤلاء فانصرفوا يجنبون الخيل يحملون المزاد فقصوا أثر توبة وأصحابه فوجدوهم وقد\nأخذوا في المضجع من أرض بني كلاب في أرض دمثة تربة فضلت فرس توبة الخوصاء من الليل فأقام واضطجع حتى أصبح وساق أصحابه الإبل وهم ثلاثة نفر سوى توبة المحرز أحد بني عمرو بن كلاب وقابض بن أبي عقيل أحد بني خفاجة وعبد الله بن حمير أخو توبة لأمه وأبيه فلما أصبح توبة إذا فرسه الخوصاء راتعة أدنى ظلم قريبة منه ليس دونها وجاح فأشلاها حتى أتته ثم خرج يعدو حتى لحق بأصحابه فانتهوا الى هضبة بكبد المضجع فارتقى توبة فوقها ينظر الطلب فرآه القوم ولم يرهم عند طلوع الشمس وبالت الخوصاء حين انتهت الى الهضبة فقال القوم إنه لطائر أو إنسان فركب يزيد بن رويبة وكان أحدث القوم سنا وأمه بنت عم توبة فأغار ركضا حتى انتهى الى الهضبة فإذا بول الفرس وعليه بقية من رغوته وإذا أثر توبة يعرفونه فرجع فخبر أصحابه واندفع توبة وأصحابه حتى نزلوا إلى طرف هضبة يقال لها الشجرة من أرض بني كلاب فقالوا بالظهيرة فلم يشعر شعر إلا والإبل قد نفرت وكانت بركا بالهاجرة من وئيد الخيل فوثب توبة وكان لا يضع السيف فصب الدرع على السيف متقلده وهلا وداجت القوم فطلب قائم السيف فلم يقدر عليه تحت الدرع فلم يستطع سله فطار إلى الرمح فأخذه فأهوى به طعنا الى يزيد بن رويبة وقد كان يزيد عاهد الله ليقتلنه أو ليأخذنه فأنفذ فخذ يزيد واعتنقه يزيد فعض\nبوجنتيه واستدبره عبد الله بالسيف ففلق رأس توبة وهيت توبة حين اعتوره الرجلان بقابض يا قابض فلم يلو عليه وفر قابض والكلابي وذب عبد الله بن حمير عن أخيه فأهوى له معاوية بن عبد الله بالسيف فأصاب ركبته فاختلعت أي سقطت فأتى قابض من فوره ذلك عبد العزيز بن زرارة أحد بني أبي بكر بن كلاب فقال قتل توبة فنادى في قومه فجاءه أبوه زرارة فقال أين تريد فقال قتل توبة فقال أبوه طوط سحقا لك أتطلب بدم توبة أن قتلته بنو عقيل ظالما لها باغيا عاديا عليها قال لكني أجنه إذا قال أبوه أما هذه فنعم فألقى السلاح وانطلق حتى أجنه وحمل أخاه عبد الله بن حمير قال فأهل البادية يزعمون أن محرزا سحر فأخذ عن سيفه","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":6,"spl":"رواية اخرى لأبي عبيدة عن مقتل توبة","loc":2070},
{"id":"b119-9","bab":"الجزء 11","sec":"شعر ليلى في رثاء توبة","page":"ج11 ص228","text":"فقالت ليلى الأخيلية بنت عبد الله بن الرحالة بن شداد بن كعب بن معاوية فارس الهرار ابن عبادة بن عقيل\n(نظرت وركن من ذقانين دونه ... مفارز حوضى أي نظرة ناظر)\n(لأونس إن لم يقصر الطرف عنهم ... فلم تقصر الأخبار والطرف قاصري)\n(فوارس أجلى شأوها عن عقيرة ... لعاقرها فيها عقيرة عاقر)\nأوها سرعتها وهو الطلق وجريها وقال غيره غايتها عقيرة تعني توبة لعاقرها تعني لعاقر توبة تريد يزيد بن رويبة ووجه آخر في عقيرة عاقر معنى مدح أي عقيرة كريمة لعاقرها ووجه آخر عقيرة لعاقرها فيها الهلاك بعقرها\n(فآنست خيلا بالرقي مغيرة ... سوابقها مثل القطا المتواتر)\n(قتيل بني عوف وأيصر دونه ... قتيل بني عوف قتيل يحابر)\n(توارده أسيافهم فكأنما ... تصادرن عن أقطاع أبيض باتر)\n(من الهندوانيات في كل قطعة ... دم زل عن أثر من السيف ظاهر)\n(أتته المنايا دون زغف حصينة ... وأسمر خطي وخوصاء ضامر)\n(على كل جرداء السراة وسابح ... درأن بشباك الحديد زوافر)\n(عوابس تعدو الثعلبية ضمرا ... وهن شواح بالشكيم الشواجر)\n(فلا يبعدنك الله يا توب إنما ... لقاء المنايا دارعا مثل حاسر)\n(فإلا تك القتلى بواء فإنكم ... ستلقون يوما ورده غير صادر)\n(وإن السليل إذ يباوي قتيلكم ... كمرحومة من عركها غير طاهر)\n(فإن تكن القتلى بواء فإنكم ... فتى ما قتلتم آل عوف بن عامر)\n(فتى لا تخطاه الرفاق ولا يرى ... لقدر عيالا دون جار مجاور)\n(ولا تأخذ الكوم الجلاد رماحها ... لتوبة في نحس الشتاء الصنابر)\n(إذا ما رأته قائما بسلاحه ... تقته الخفاف بالثقال البهازر)\n(إذا لم يجد منها برسل فقصره ... ذرى المرهفات والقلاص التواجر)\n(قرى سيفه منها مشاشا وضيفه ... سنام المهاريس السباط المشافر)\n(وتوبة أحيا من فتاة حيية ... وأجرأ من ليث بخفان خادر)\n(ونعم الفتى إن كان توبة فاجرا ... وفوق الفتى إن كان ليس بفاجر)\n(فتى ينهل الحاجات ثم يعلها ... فيطلعها عنه ثنايا المصادر)\n\n(كأن فتى الفتيان توبة لم ينخ ... قلائص يفحصن الحصا بالكراكر)\n(ولم يبن أبرادا عتاقا لفتية ... كرام ويرحل قبل فيء الهواجر)\nي هذين البيتين لحن من الثقيل الأول لمحمد بن إبراهيم قريض وهو من خاص صنعته وغنائه\n(ولم يتجل الصبح عنه وبطنه ... لطيف كطي السب ليس بحادر)\n(فتى كان للمولى سناء ورفعة ... وللطارق الساري قرى غير باسر)\n(ولم يدع يوما للحفاظ وللندا ... وللحرب يرمى نارها بالشرائر)\n(وللبازل الكوماء يرغو حوارها ... وللخيل تعدو بالكماة المساعر)\n(كأنك لم تقطع فلاة ولم تنخ ... قلاصا لدى فأو من الأرض غائر)\n(وتصبح بموماة كأن صريفها ... صريف خطاطيف الصرى في المحاور)\n(طوت نفعها عنا كلاب وآسدت ... بنا أجهليها بين غاو وشاعر)\n(وقد كان حقا أن تقول سراتهم ... لعا لأخينا عاليا غير عاثر)\n(ودوية قفر يحار بها القطا ... تخطيتها بالناعجات الضوامر)\n(فتالله تبني بيتها أم عاصم ... على مثله أخرى الليالي الغوابر)\n(فليس شهاب الحرب توبة بعدها ... بغاز ولا غاد بركب مسافر)\n(وقد كان طلاع النجاد وبين الل ... سان ومدلاج السرى غير فاتر)\n(وقد كان قبل الحادثات إذا انتحى ... وسائق أو معبوطة لم يغادر)\n(وكنت إذا مولاك خاف ظلامة ... دعاك ولم يهتف سواك بناصر)\n(فإن يك عبد الله آسى أبن أمه ... وآب بأسلاب الكمي المغاور)\n(وكان كذات البو تضرب عنده ... سباعا وقد ألقينه في الجراجر)\n(فإنك قد فارقته لك عاذرا ... وأنى لحي عذر من في المقابر)\n(فأقسمت أبكي بعد توبة هالكا ... وأحفل من نالت صروف المقادر)\n(على مثل همام ولابن مطرف ... لتبك البواكي أو لبشر بن عامر)\n(غلامان كانا استوردا كل سورة ... من المجد ثم أستوثقا في المصادر)\n(ربيعي حيا كانا يفيض نداهما ... على كل مغمور نداه وغامر)\n(كأن سنا ناريهما كل شتوة ... سنا البرق يبدو للعيون النواظر)\nقالت أيضا ترثي توبة عن أم حمير وأمها أبنة أخي توبة عن أمها قال أبو عبيدة أم حمير أخت أبي الجراح العقيلي قال وأمها بنت أخي توبة بن حمير قال وكان الأصمعي يعجب بها\n(أيا عين بكي توبة بن حمير ... بسح كفيض الجدول المتفجر)\n(لتبك عليه من خفاجة نسوة ... بماء شؤون الغبرة المتحدر)\n(سمعن بهيجا أرهقت فذكرنه ... ولا يبعث الأحزان مثل التذكر)\n(كأن فتى الفتيان توبة لم يسر ... بنجد ولم يطلع مع المتغور)","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":7,"spl":"شعر ليلى في رثاء توبة","song":1,"loc":2071},
{"id":"b119-10","bab":"الجزء 11","sec":"شعر ليلى في رثاء توبة","page":"ج11 ص228","text":"(ولم يرد الماء السدام إذا بدا ... سنا الصبح في بادي الحواشي منور)\n(ولم يغلب الخصم الضجاج ويملأ الجفان ... سديفا يوم نكباء صرصر)\n(ولم يعل بالجرد الجياد يقودها ... بسرة بين الأشمسات فايصر)\n(وصحراء موماة يحار بها القطا ... قطعت على هول الجنان بمنسر)\n(يقودون قبا كالسراحين لاحها ... سراهم وسير الراكب المتهجر)\n(فلما بدت أرض العدو سقيتها ... مجاج بقيات المزاد المقير)\n(ولما أهابوا بالنهاب حويتها ... بخاظي البضيع كره غير أعسر)\n(ممر ككر الأندري مثابر ... إذا ما ونين مهلب الشد محضر)\n(فألوت بأعناق طوال وراعها ... صلاصل بيض سابغ وسنور)\n(ألم تر أن العبد يقتل ربه ... فيظهر جد العبد من غير مظهر)\n(قتلتم فتى لا يسقط الروع رمحه ... إذا الخيل جالت في قنا متكسر)\n(فيا توب للهيجا ويا توب للندى ... ويا توب للمستنبح المتنور)\n(ألا رب مكروب أجبت ونائل ... بذلت ومعروف لديك ومنكر)\nوقالت ترثيه\n(أقسمت أرثي بعد توبة هالكا ... وأحفل من دارت عليه الدوائر)\n(لعمرك ما بالموت عار على الفتى ... اذا لم تصبه في الحياة المعاير)\n(وما أحد حي وإن عاش سالما ... بأخلد ممن غيبته المقابر)\n(ومن كان مما يحدث الدهر جازعا ... فلا بد يوما أن يرى وهو صابر)\n(وليس لذي عيش عن الموت مقصر ... وليس على الأيام والدهر غابر)\n(ولا الحي مما يحدث الدهر معتب ... ولا الميت إن لم يصبر الحي ناشر)\n(وكل شباب أو جديد إلى بلى ... وكل امرىء يوما إلى الله صائر)\n(وكل قريني ألفة لتفرق ... شتاتا وإن ضنا وطال التعاشر)\n(فلا يبعدنك الله حيا وميتا ... أخا الحرب إن دارت عليك الدوائر)\nيروى\n(فلا يبعدنك الله يا توب هالكا ... أخا الحرب إن دارت عليك الدوائر)\n(فآليت لا أنفك أبكيك ما دعت ... على فنن ورقاء أو طار طائر)\n(قتيل بني عوف فيا لهفتا له ... وما كنت إياهم عليه أحاذر)\n(ولكنما أخشى عليه قبيلة ... لها بدروب الروم باد وحاضر)\nقالت ترثيه\n(كم هاتف بك من باك وباكية ... يا توب للضيف إذ تدعى وللجار)\n(وتوب للخصم إن جاروا وان عدلوا ... وبدلوا الأمر نقضا بعد إمرار)\n(إن يصدروا الأمر تطلعه موارده ... أو يوردوا الأمر تحلله بإصدار)\nقالت ترثيه\n(هراقت بنو عوف دما غير واحد ... له نبأ نجديه سيغور)\n(تداعت له أفناء عوف ولم يكن ... له يوم هضب الردهتين نصير)\nقالت ترثيه\n(يا عين بكي بدمع دائم السجم ... وابكي لتوبة عند الروع والبهم)\n(على فتى من بني سعد فجعت به ... ماذا أجن به في الحفرة الرجم)\n(من كل صافية صرف وقافية ... مثل السنان وأمر غير مقتسم)\n(ومصدر حين يعيي القوم مصدرهم ... وجفنة عند نحس الكوكب الشبم)\nقالت تعير قابضا\n(جزى ا لله شرا قابضا بصنيعه ... وكل امرىء يجزى بما كان ساعيا)\n(دعا قابضا والمرهفات يردنه ... فقبحت مدعوا ولبيك داعيا)\nقالت لقابض وتعذر عبد الله أخا توبة\n(دعا قابضا والموت يخفق ظله ... وما قابض إذ لم يجب بنجيب)\n(وآسى عبيد الله ثم أبن أمه ... ولو شاء نجى يوم ذاك حبيبي)","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":8,"spl":"شعر ليلى في رثاء توبة","loc":2072},
{"id":"b119-12","bab":"الجزء 11","sec":"خبر توبة مع زنجي لقيه في الشام — جواب ليلى عندما سألها معاوية عن توبة","page":"ج11 ص237 – ج11 ص238","text":"أخبرني الحسن بن علي عن عبد الله بن أبي سعد عن أحمد بن معاوية بن بكر قال حدثني أبو الجراح العقيلي عن أمه دينار بنت خيبري بن الحمير عن توبة بن الحمير قال خرجت إلى الشام فبينا أنا أسير ليلة في بلاد لا أنيس بها ذات شجر نزلت لأريح وأخذت ترسي فألقيته فوقي وألقيت نفسي بين المضطجع والبارك فلما وجدت طعم النوم إذا شيء قد تجللني عظيم ثقيل قد برك علي ونشزت عنه ثم قمصت منه قماصا فرميت به على وجهه وجلست إلى راحلتي فانتضيت السيف ونهض نحوي فضربته ضربة انخزل منها\nوعدت إلى موضعي وأنا لا أدري ما هو أإنسان أم سبع فلما أصبحت إذا هو أسود زنجي يضرب برجليه وقد قطعت وسطه حتى كدت أبريه وانتهيت إلى ناقة مناخة موقرة ثيابا من سلبه وإذا جارية شابة ناهد وقد أوثقها وقرنها بناقته فسألتها عن خبرها فأخبرتني أنه قتل مولاها وأخذها منه فأخذت الجميع وعدت إلى أهلي قال أبو الجراح قالت أمي وأنا أدركتها في الحي تخدم أهلنا\nأخبرنا اليزيدي عن ثعلب عن أبن الأعرابي قال أخبرنا عطاء بن مصعب القرشي عن عاصم الليثي عن يونس بن حبيب الضبي عن أبي عمرو بن العلاء قال سأل معاوية بن أبي سفيان ليلى الأخيلية عن توبة بن الحمير فقال ويحك يا ليلى أكما يقول الناس كان توبة قالت يا أمير المؤمنين ليس كل ما يقول الناس حقا والناس شجرة بغي يحسدون أهل النعم حيث كانوا وعلى من كانت ولقد كان يا أمير المؤمنين سبط البنان حديد اللسان شجا للأقران كريم المخبر عفيف المئزر جميل المنظر وهو يا أمير المؤمنين كما قلت له قال وما قلت له قالت قلت ولم أتعد الحق وعلمي فيه\n(بعيد الثرى لا يبلغ القوم قعره ... ألد ملد يغلب الحق باطله)\n(اذا حل ركب في ذراه وظله ... ليمنعهم مما تخاف نوازله)\n(حماهم بنصل السيف من كل فادح ... يخافونه حتى تموت خصائله)\nقال لها معاوية ويحك يزعم الناس أنه كان عاهرا خاربا فقالت من ساعتها\n(معاذ إلهي كان والله سيدا ... جوادا على العلات جما نوافله)\n(أغر خفاجيا يرى البخل سبة ... تحلب كفاه الندى وأنامله)\n(عفيفا بعيد الهم صلبا قناته ... جميلا محياه قليلا غوائله)\n(وقد علم الجوع الذي بات ساريا ... على الضيف والجيران أنك قاتله)\n(وأنك رحب الباع يا توب بالقرى ... إذا مالئيم القوم ضاقت منازله)\n(يبيت قرير العين من بات جاره ... ويضحي بخير ضيفه ومنازله)\nقال لها معاوية ويحك يا ليلى لقد جزت بتوبة قدره فقالت والله يا أمير المؤمنين لو رأيته وخبرته لعرفت أني مقصرة في نعته وأني لا أبلغ كنه ما هو أهله فقال لها معاوية من أي الرجال كان قالت\n(أتته المنايا حين تم تمامه ... وأقصر عنه كل قرن يطاوله)\n(وكان كليث الغاب يحمي عرينه ... وترضى به أشباله وحلائله)\n(غضوب حليم حين يطلب حلمه ... وسم زعاف لا تصاب مقاتله)\nقال فأمر لها بجائزة عظيمة وقال لها خبريني بأجود ما قلت فيه من الشعر قالت يا أمير المؤمنين ما قلت فيه شيئا إلا والذي فيه من خصال الخير أكثر منه ولقد أجدت حين قلت\n(جزى الله خيرا والجزاء بكفه ... فتى من عقيل ساد غير مكلف)\n(فتى كانت الدنيا تهون بأسرها ... عليه ولا ينفك جم التصرف)\n(ينال عليات الأمور بهونة ... إذا هي أعيت كل حرق مشرف)\n(هو الذوب بل أري الخلايا شبيهه ... بدرياقة من خمر بيسان قرقف)\n(فياتوب مافي العيش خير ولا ندى ... يعد وقد أمسيت في ترب نفنف)\n(وما نلت منك النصف حتى ارتمت بك ال ... بسهم صائب الوقع أعجف)\n(فيا ألف ألف كنت حيا مسلما ... لألقاك مثل القسور المتطرف)\n(كما كنت إذ كنت المنحى من الردى ... إذا الخيل جالت بالقنا المتقصف)\n(وكم من لهيف محجر قد أجبته ... بأبيض قطاع الضريبة مرهف)\n(فانقذته والموت يحرق نابه ... عليه ولم يطعن ولم يتنسف)","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":9,"spl":"خبر توبة مع زنجي لقيه في الشام — جواب ليلى عندما سألها معاوية عن توبة","loc":2073},
{"id":"b119-13","bab":"الجزء 11","sec":"جميل يظهر غيرة على بثينة من توبة","page":"ج11 ص240","text":"أخبرني الحسن بن علي عن ابن مهرويه عن ابن أبي سعد قال حدثت عن القحذمي عن محارب بن غصين العقيلي قال كان توبة قد خرج إلى الشام فمر ببني عذرة فرأته بثينة فجعلت تنظر إليه فشق ذلك على جميل وذلك قبل أن يظهر حبه لها فقال له جميل من أنت قال أنا توبة بن الحمير قال هل لك في الصراع قال ذلك إليك فشدت عليه بثينة ملحفة مورسة فأتزر بها ثم صارعه فصرعه جميل ثم قال هل لك في النضال قال نعم فناضله فنضله جميل ثم قال له هل لك في السباق فقال نعم فسابقه فسبقه جميل فقال له توبة يا هذا إنما تفعل هذا بريح هذه الجالسة ولكن أهبط بنا الوادي فصرعه توبة ونضله وسبقه","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":10,"spl":"جميل يظهر غيرة على بثينة من توبة","loc":2074},
{"id":"b119-14","bab":"الجزء 11","sec":"ليلى تسخر من عبد الملك عندما حاول ان يسخر منها","page":"ج11 ص241","text":"أخبرنا إبراهيم بن أيوب عن ابن قتيبة قال\nبلغني أن ليلى الأخيلية دخلت على عبد الملك بن مروان وقد أسنت وعجزت فقال لها ما رأى توبة فيك حين هويك قالت ما رآه الناس فيك\nحين ولوك فضحك عبد الملك حتى بدت له سن سوداء كان يخفيها وأخبرني الحسن بن علي عن ابن أبي سعد عن أحمد بن رشيد بن حكيم الهلالي عن أيوب بن عمرو عن رجل من بني عامر يقال له ورقاء قال كنت عند الحجاج بن يوسف فدخل عليه الآذن فقال أصلح الله الأمير بالباب أمرأة تهدر كما يهدر البعير الناد قال أدخلها فلما دخلت نسبها فانتسبت له فقال ما أتى بك يا ليلى قالت إخلاف النجوم وقلة الغيوم وكلب البرد وشدة الجهد وكنت لنا بعد الله الرد قال فأخبريني عن الأرض قالت الأرض مقشعرة والفجاج مغبرة وذو الغنى مختل وذو الحد منفل قال وما سبب ذلك قالت أصابتنا سنون مجحفة مظلمة لم تدع لنا فصيلا ولا ربعا ولم تبق عافطة ولا نافطة فقد أهلكت الرجال ومزقت العيال وأفسدت الأموال ثم أنشدته الأبيات التي ذكرناها متقدما وقال في الخبر قال الحجاج هذه التي تقول\n(نحن الأخايل لا يزال غلامنا ... حتى يدب على العصا مشهورا)\n(تبكي الرماح إذا فقدن أكفنا ... جزعا وتعرفنا الرفاق بحورا)\nم قال لها يا ليلى أنشدينا بعض شعرك في توبة فأنشدته قولها\n(لعمرك ما بالموت عار على الفتى ... اذا لم تصبه في الحياة المعاير)\n(وما أحد حي وإن عاش سالما ... بأخلد ممن غيبته المقابر)\n(فلا الحي مما أحدث الدهر معتب ... ولا الميت إن لم يصبر الحي ناشر)\n(وكل جديد أو شباب إلى بلى ... وكل امرىء يوما إلى الموت صائر)\n(قتيل بني عوف فيا لهفتا له ... وما كنت إياهم عليه أحاذر)\n(ولكنني أخشى عليه قبيلة ... لها بدروب الشأم باد وحاضر)\nقال الحجاج لحاجبه أذهب فاقطع لسانها فدعا لها بالحجام ليقطع لسانها فقالت ويلك إنما قال لك الأمير أقطع لسانها بالصلة والعطاء فارجع إليه واستأذنه فرجع إليه فاستأمره فاستشاط عليه وهم بقطع لسانه ثم أمر بها فأدخلت عليه فقالت كاد وعهد الله يقطع مقولي وأنشدته\n(حجاج أنت الذي لا فوقه أحد ... إلا الخليفة والمستغفر الصمد)\n(حجاج أنت سنان الحرب إن نهجت ... وأنت للناس في الداجي لنا تقد)\nخبرنا الحسن قال حدثنا عبد الله بن أبي سعد قال حدثني أبو الحسن\nميمون الموصلي عن سلمة بن أيوب بن مسلمة الهمداني قال كان جدي عند الحجاج فدخلت عليه أمرأة برزة فانتسبت له فإذا هي ليلى الأخيلية وأخبرني بهذا الخبر محمد بن العباس اليزيدي وأخبرنا أحمد بن عبد العزيز الجوهري قال كنت عند الحجاج وأخبرني وكيع عن إسماعيل بن محمد عن المدائني عن جويرية عن بشر بن عبد الله بن أبي بكر أن ليلى دخلت على الحجاج ثم ذكر مثل الخبر الأول وزاد فيه فلما قالت\n(غلام إذا هز القناة سقاها ... )\nال لها لا تقولي غلام قولي همام وقال فيه فأمر لها بمائتين فقالت زدني فقال أجعلوها ثلاثمائة فقال بعض جلسائه إنها غنم فقالت الأمير أكرم من ذلك وأعظم قدرا من أن يأمر لي إلا بالإبل قال فاستحيا وأمر لها بثلاثمائة بعير وإنما كان أمر لها بغنم لا إبل وأخبرنا به وكيع عن إبراهيم بن إسحاق الصالحي عن عمر بن شبة عن عمرو بن أبي عمرو الشيباني عن أبيه وقال فيه ألا قلت مكان غلام همام وذكر باقي الخبر الذي ذكره من تقدم وقال فيه فقال لها أنشدينا ما قلت في توبة فأنشدته قولها\n(فإن تكن القتلى بواء فإنكم ... فتى ما قلتم آل عوف بن عامر)\n(فتى كان أحيا من فتاة حيية ... وأشجع من ليث بخفان خادر)\n(أتته المنايا دون درع حصينة ... وأسمر خطي وجرداء ضامر)\n(فنعم الفتى إن كان توبة فاجرا ... وفوق الفتى إن كان ليس بفاجر)\n(كأن فتى الفتيان توبة لم ينخ ... قلائص يفحصن الحصا بالكراكر)","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":11,"spl":"ليلى تسخر من عبد الملك عندما حاول ان يسخر منها","loc":2075,"partial":1},
{"id":"b119-16","bab":"الجزء 11","sec":"ليلى تسخر من عبد الملك عندما حاول ان يسخر منها — وفاة ليلى الأخيلية","page":"ج11 ص241 – ج11 ص245","text":"قال لها أسماء بن خارجة أيتها المرأة إنك لتصفين هذا الرجل بشيء ما تعرفه العرب فيه فقالت أيها الرجل هل رأيت توبة قط قال لا فقالت أما والله لو رأيته لوددت أن كل عاتق في بيتك حامل منه فكأنما فقىء في وجه أسماء حب الرمان فقال له الحجاج وما كان لك ولها أخبرني الحسن بن علي قال حدثنا ابن أبي سعد عن محمد بن علي بن المغيرة قال سمعت أبي يقول سمعت الأصمعي يذكر أن الحجاج أمر لها بعشرة آلاف درهم وقال لها هل لك من حاجة قالت نعم أصلح الله الأمير تحملني الى أبن عمي قتيبة بن مسلم وهو على خراسان يومئذ فحملها إليه فأجازها وأقبلت راجعة تريد البادية فلما كانت بالري ماتت فقبرها هناك هكذا ذكر الأصمعي في وفاتها وهو غلط وقد أخبرني عمي عن الحزنبل الأصبهاني عمن أخبره عن المدائني وأخبرني الحسن بن علي عن ابن مهدي عن ابن أبي سعد عن محمد بن الحسن النخعي عن ابن الخصيب الكاتب واللفظ في الخبر للحزنبل وروايته أتم\nأن ليلى الأخيلية أقبلت من سفر فمرت بقبر توبة ومعها زوجها وهي في هودج لها فقالت والله لا أبرح حتى أسلم على توبة فجعل زوجها يمنعها من ذلك وتأبى إلا أن تلم به فلما كثر ذلك منها تركها فصعدت أكمة عليها قبر توبة فقالت السلام عليك يا توبة ثم حولت وجهها إلى القوم فقالت ما عرفت له كذبة قط قبل هذا قالوا وكيف قالت أليس القائل\n\n(ولو أن ليلى الأخيلية سلمت ... علي ودوني تربة وصفائح)\n(لسلمت تسليم البشاشة أو زقا ... إليها صدى من جانب القبر صائح)\n(وأغبط من ليلى بما لا أناله ... ألا كل ما قرت به العين صالح)\nما باله لم يسلم علي كما قال وكانت الى جانب القبر بومة كامنة فلما رأت الهودج واضطرابه فزعت وطارت في وجه الجمل فنفر فرمى بليلى على رأسها فماتت من وقتها فدفنت الى جنبه وهذا هو الصحيح من خبر وفاتها غنى في الأبيات المذكورة آنفا حكم الوادي لحنين أحدهما رمل بالوسطى عن عمرو والآخر خفيف ثقيل أول بالوسطى عن حبش وقال حبش وفيها لحنان لجميلة والميلاء رملان بالبنصر وذكر أبو العبيس بن حمدون أن الرمل لعمر الوادي قال أبو عبيدة كان توبة شريرا كثير الغارة على بني الحارث بن كعب وخثعم وهمدان فكان يزور نساء منهن يتحدث اليهن وقال\n(أيذهب ريعان الشباب ولم أزر ... غرائر من همدان بيضا نحورها)\nال أبو عبيدة وكان توبة ربما ارتفع الى بلاد مهرة فيغير عليهم وبين بلاد مهرة وبلاد عقيل مفازة منكرة لا يقطعها الطير وكان يحمل مزاد الماء\nفيدفن منه على مسيرة كل يوم مزادة ثم يغير عليهم فيطلبونه فيركب بهم المفازة وإنما كان يتعمد حمارة القيظ وشدة الحر فإذا ركب المفازة رجعوا عنه أخبرني حرمي عن الزبير عن يحيى بن المقدام الربعي عن عمه موسى بن يعقوب قال دخل عبد الله بن مروان على زوجته عاتكة بنت يزيد بن معاوية فرأى عندها امرأة بدوية أنكرها فقال لها من أنت قالت أنا الوالهة الحرى ليلى الأخيلية قال أنت التي تقولين\n(أريقت جفان ابن الخليع فأصبحت ... حياض الندى زالت بهن المراتب)\n(فعفاته لهفى يطوفون حوله ... كما انقض عرش البئر والورد عاصب)\nالت أنا التي أقول ذلك قال فما أبقيت لنا قالت الذي أبقاه الله لك قال وما ذاك قالت نسبا قرشيا وعيشا رخيا وامرة مطاعة قال أفردته بالكرم قالت أفردته بما أفرده الله به فقالت عاتكة إنها قد جاءت تستعين بنا عليك في عين تسقيها وتحميها لها ولست ليزيد إن شفعتها في شيء من حاجاتها لتقديمها أعرابيا حلفا على أمير المؤمنين قال فوثبت ليلى فقامت على رجلها واندفعت تقول\n(ستحملني ورحلي ذات وخد ... عليها بنت آباء كرام)\n(إذا جعلت سواد الشأم جنبا ... وغلق دونها باب اللئام)\n(فليس بعائد أبدا إليهم ... ذوو الحاجات في غلس الظلام)\n(أعاتك لو رأيت غداة بنا ... عزاء النفس عنكم واعتزامي)\n(إذا لعلمت واستيقنت أني ... مشيعة ولم ترعي ذمامي)\n(أأجعل مثل توبة في نداه ... أبا الذبان فوه الدهر دامي)\n(معاذ الله ما عسفت برحلي ... تغذ السير للبلد التهامي)\n(أقلت خليفة فسواه أحجى ... بإمرته وأولى باللثام)\n(لثام الملك حين تعد كعب ... ذوو الأخطار والخطط الجسام)\nفقيل لها أي الكعبين عنيت قالت ما أخال كعبا ككعبي","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":12,"spl":"ليلى تسخر من عبد الملك عندما حاول ان يسخر منها — وفاة ليلى الأخيلية","song":1,"loc":2076},
{"id":"b119-17","bab":"الجزء 11","sec":"خبر آخر في وفودها على الحجاج","page":"ج11 ص248","text":"أخبرنا اليزيدي عن الخليل بن أسد عن العمري عن الهيثم بن عدي عن أبي يعقوب الثقفي عن عبد الملك بن عمير عن محمد بن الحجاج بن يوسف قال بينا الأمير جالس إذ استؤذن لليلى فقال الحجاج ومن ليلى قيل الأخيلية صاحبة توبة قال أدخلوها فدخلت امرأة طويلة دعجاء العينين حسنة المشية إلى الفوه ما هي حسنة الثغر فسلمت فرد الحجاج عليها ورحب بها فدنت فقال الحجاج دراك ضع لها وسادة يا غلام\nفجلست فقال ما أعملك إلينا قالت السلام على الأمير والقضاء لحقه والتعرض لمعروفه قال وكيف خلفت قومك قالت تركتهم في حال خصب وأمن ودعة أما الخصب ففي الأموال والكلأ وأما الأمن فقد أمنهم الله عز و جل بك وأما الدعة فقد خامرهم من خوفك ما أصلح بينهم ثم قالت ألا أنشدك فقال إذا شئت فقالت\n(أحجاج إن الله أعطاك غاية ... يقصر عنها من أراد مداها)\n(أحجاج لا يفلل سلاحك إنما المنايا ... بكف الله حيث تراها)\n(إذا هبط الحجاج أرضا مريضة ... تتبع أقصى دائها فشفاها)\n(شفاها من الداء العضال الذي بها ... غلام إذا هز القناة سقاها)\n(سقاها دماء المارقين وعلها ... إذا جمحت يوما وخيف أذاها)\n(إذا سمع الحجاج رز كتيبة ... أعد لها قبل النزول قراها)\n(أعد لها مصقولة فارسية ... بأيدي رجال يحلبون صراها)\n(أحجاج لا تعط العصاة مناهم ... ولا الله يعطي للعصاة مناها)\n(ولا كل حلاف تقلد بيعة ... فأعظم عهد الله ثم شراها)\nفقال الحجاج ليحيى بن منقذ لله بلادها ما أشعرها فقال ما لي بشعرها علم فقال علي بعبيدة بن موهب وكان حاجبه فقال أنشديه فأنشدته فقال عبيدة هذه الشاعرة الكريمة قد وجب حقها قال ما أغناها عن شفاعتك يا غلام مر لها بخمسمائة درهم واكسها خمسة أثواب أحدها كساء خز وأدخلها على ابنة عمها هند بنت أسماء فقل لها حليها\nفقالت أصلح الله الأمير أضر بنا العريف في الصدقة وقد خربت بلادنا وانكسرت قلوبنا فأخذ خيار المال قال اكتبوا لها الى الحكم بن أيوب فليبتع لها خمسة أجمال وليجعل أحدها نجيبا وأكتبوا الى صاحب اليمامة بعزل العريف الذي شكته فقال ابن موهب أصلح الله الأمير أأصلها قال نعم فوصلها بأربعمائة درهم ووصلتها هند بثلاثمائة درهم ووصلها محمد بن الحجاج بوصيفتين قال الهيثم فذكرت هذا الحديث لإسحاق بن الجصاص فكتبه عني ثم حدثني عن حماد الراوية قال لما فرغت ليلى من شعرها أقبل الحجاج على جلسائه فقال لهم أتدرون من هذه قالوا لا والله ما رأينا امرأة أفصح ولا أبلغ منها ولا أحسن إنشادا قال هذه ليلى صاحبة توبة ثم أقبل عليها فقال لها بالله يا ليلى أرأيت من توبة أمرا تكرهينه أو سألك شيئا يعاب قالت لا والله الذي أسأله المغفرة ما كان ذلك منه قط فقال إذا لم يكن فيرحمنا الله وإياه أخبرني أحمد بن عبد العزيز الجوهري عن ابن شبة عن عبد الله بن محمد بن حكيم الطائي عن خالد بن سعيد عن أبيه قال كنت عند الحجاج فدخلت عليه ليلى الأخيلية ثم ذكر مثل الخبر الأول وزاد فيه فلما قالت\n(غلام إذا هز القناة سقاها ... )\nقال لا تقولي غلام قولي همام\n(سالني الناس أين يعمد هذا ... قلت آتي في الدار قرما سريا)\n(ما قطعت البلاد أسري ولا يممت ... إلا إياك يا زكريا)\n(كم عطاء ونائل وجزيل ... كان لي منكم هنيا مريا)\nروضه من الخفيف الشعر للأقيشر الأسدي والغناء لدحمان وله فيه لحنان أحدهما خفيف ثقيل من أصوات قليلة الأشباه عن إسحاق والآخر ثقيل أول بالبنصر في الثالث والثاني عن عمرو وذكر يونس أنه للأبجر ولم يجنسه وذكر الهشامي أن لحن الأبجر خفيف ثقيل وأن لحن ابن بلوع في الثالث ثاني ثقيل وليحيى بن واصل ثقيل أول بالوسطى بالوسطى","topic":"ذكر ليلى ونسبها وخبر توبة بن الحمير معها وخبر مقتله","topicNo":119,"sp":13,"spl":"خبر آخر في وفودها على الحجاج","song":1,"loc":2077,"partialRef":{"sid":"b119-14","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b120-1","bab":"الجزء 11","sec":"ذكر الأقيشر وأخباره سبب تلقيبه الأقيشر","page":"ج11 ص252","text":"الأقيشر لقب غلب عليه لأنه كان أحمر الوجه أقشر واسمه المغيرة بن عبد الله بن معرض بن عمرو بن أسد بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وكان يكنى أبا معرض وقد ذكر ذلك في شعره في مواضع عدة منها قوله\n(فإن أبا معرض إذ حسا ... من الراح كأسا على المنبر)\n(خطيب لبيب أبو معرض ... فإن ليم في الخمر لم يصبر)\nوعمر عمرا طويلا فكان أقعد بني أسد نسبا وما أخلقه بأن يكون ولد في الجاهلية ونشأ في أول الإسلام لأن سماك بن مخرمة الأسدي صاحب سماك بالكوفة بناه في أيام عمر وكان عثمانيا وأهل تلك المحلة إلى اليوم كذلك فيروي أهل الكوفة أن علي بن أبي طالب صلوات الله عليه لم يصل فيه وأهل الكوفة إلى اليوم يجتنبونه وسماك الذي بناه هو سماك بن مخرمة بن حمين بن بلث بن عمرو بن معرض بن أسد والأقيشر أقعد نسبا منه وقال الأقيشر في ذكر مسجد سماك شعرا أخبرني محمد بن الحسن الكندي الكوفي قال أخبرني الحسن بن عليل\nالعنزي عن محمد بن معاوية وكنيته أبو عبد الله محمد بن معاوية قال الأقيشر من رهط خريم بن فاتك الأسدي وخريم إنما نسب إلى جد أبيه فاتك وهو خريم بن الأخرم بن شداد بن عمرو بن فاتك الأسدي وفاتك ابن قليب بن عمرو بن أسد والأقيشر هو المغيرة بن عبد الله بن معرض بن عمرو بن أسد قال وهو القائل لما بنى سماك بن مخرمة مسجده الذي بالكوفة وهو أكبر مسجد لبني أسد وهو في خطة بني نصر بن قعين\n(غضبت دودان من مسجدنا ... وبه يعرفهم كل أحد)\n(لو هدمنا غدوة بنيانه ... لانمحت أسماؤهم طول الأبد)\n(اسمهم فيه وهم جيرانه ... واسمه الدهر لعمرو بن أسد)\n(كلما صلوا قسمنا أجره ... فلنا النصف على كل جسد)\nحلف بنو دودان ليضربنه فأتاهم فقال قد قلت بيتا محوت به كل ما قلت قالوا وما هو يا فاسق قال قلت\n(وبنو دودان حي سادة ... حل بيت المجد فيهم والعدد)\nتركوه أخبرني وكيع عن إسماعيل بن مجمع عن المدائني قال وأخبرني أبو أيوب المديني عن محمد بن سلام قال كان الأقيشر كوفيا خليعا ماجنا مدمنا لشرب الخمر وهو الذي يقول لنفسه\n(فإن أبا معرض إذ حسا ... من الراح كأسا على المنبر)\n(خطيب لبيب أبو معرض ... فصار خليعا على المكبر)\n(أحل الحرام أبو معرض ... فإن ليم في الخمر لم يصبر)\n(يجل اللئام يلحي الكرام ... وإن أقصروا عنه لم يقصر)","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":0,"spl":"ذكر الأقيشر وأخباره سبب تلقيبه الأقيشر","loc":2078},
{"id":"b120-2","bab":"الجزء 11","sec":"كان يهجو من يناديه بلقبه","page":"ج11 ص254","text":"أخبرني الحسين بن يحيى عن حماد بن إسحاق عن أبيه عن المدائني وأخبرني عبد الوهاب بن عبيد الصحاف الكوفي عن قعنب بن محزر الباهلي عن المدائني أن الأقيشر مر يريد الحيرة فاجتاز على مجلس لبني عبس فناداه أحدهم يا أقيشر وكان يغضب منها فزجره الأشياخ ومضى الأقيشر ثم عاد إليه ومعه رجل وقال له قف معي فإذا أنشدت بيتا فقل لي ولم ذلك ثم انصرف وخذ هذين الدرهمين فقال له أنا أصير معك إلى حيث شئت يا أبا معرض ولا أرزؤك شيئا قال فأفعل فأقبل حتى أتى مجلس القوم فوقف عليهم ثم تأملهم وقد عرف الشاب فأقبل عليه وقال\n(أتدعوني الأقيشر ذلك اسمي ... وأدعوك ابن مطفئة السراج)\nقال له الرجل ولم ذاك فقال\n(تناجي خدنها بالليل سرا ... ورب الناس يعلم ما تناجي)\nقال قعنب في خبره فلقب ذلك الرجل ابن مطفئة السراج وقال قعنب في خبره عن المدائني أخبرنا به اليزيدي عن الخراز عن المدائني في كتاب الجوابات ولم يروه الباقون كان الأقيشر يكتري بغلة أبي المضاء المكاري فيركبها إلى الخمارين بالحيرة فركبها يوما ومضى لحاجته وعند أبي المضاء رجل من تميم يكنى أبا الضحاك فقال له من هذا قال الأقيشر فأخذ طبق الميزان وكتب فيه\n(عجبت لشاعر من حي سوء ... ضئيل الجسم مبطان هجين)\nقال لأبي المضاء إذا جاء فأقرئه هذا فلما جاء أقرأه فقال له الأقيشر ممن هو قال من بني تميم فكتب الأقيشر تحت كتابه\n(فلا أسدا أسب ولا تميما ... وكيف يجوز سب الأكرمين)\n(ولكن التميمي حال بيني ... وبينك يا ابن مضرطة العجين)\nهرب إلى الكوفة فلم يزد على هذا وقال قعنب في خبره عن المدائني فجاء التميمي فقرأ ما كتب فكتب تحته\n(يأيها المبتغي حشا لحاجته ... وجه الأقيشر حش غير ممنوع)\nلما قرأه قال اللهم إني أستعديك عليه وكتب تحته\n(إني أتاني مقال كنت آمنه ... فجاء من فاحش في الناس مخلوع)\n(عبد العزيز أبو الضحاك كنيته ... فيه من اللؤم وهي غير ممنوع)\n(ولم تبت أمه إلا مطاحنة ... وأن تؤاجر في سوق المراضيع)\n(ينساب ماء البرايا في استها سربا ... كأنما انساب في بعض البلاليع)\n(من ثم جاءت به والبظر حنكه ... كأنه في استها تمثال يسروع)\nلما جاءه جزع ومشى إليه بقوم من بني تميم فطلبوا أن يكف ففعل وأما عبد الله بن خلف فذكر عن أبي عمرو الشيباني أن الأقيشر قال هذا في مسكين والشعر الذي فيه الغناء يقوله الأقيشر في زكريا بن طلحة الذي يقال له الفياض وكان مداحا له","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":1,"spl":"كان يهجو من يناديه بلقبه — عبد الملك اعجب بشعره فمدحه","loc":2079},
{"id":"b120-3","bab":"الجزء 11","sec":"عبد الملك اعجب بشعره فمدحه","page":"ج11 ص256","text":"أخبرني الحسن بن علي عن العنزي عن محمد بن معاوية قال غنت جارية عند عبد الملك بن مروان بشعر الأقيشر\n(قرب الله بالسلام وحيا ... زكريا بن طلحة الفياض)\n(معدن الضيف إن أناخوا إليه ... بعد أين الطلائح الأنقاض)\n(ساهمات العيون خوص رذايا ... قد براها الكلال بعد أياض)\n(زاده خالد ابن عم أبيه ... منصبا كان في العلا ذا انتقاض)\n(فرع تيم من مرة حقا ... قد قضى ذاك لابن طلحة قاض)\nقال عبد الملك للجارية ويحك لمن هذا قالت للأقيشر قال هذا المدح لا على طمع ولا فرق وأشعر الناس الأقيشر وذكر عبد الله بن خلف أن أبا عمرو الشيباني أخبره أن الكميت بن زيد لقي الأقيشر في سفرة فقال له أين تقصد يا أبا معرض فقال\n(سالني الناس أين يقصد هذا ... قلت آتي في الدار قرما سريا)\nذكر باقي الأبيات التي فيها الغناء فلم يزل الكميت يستعيده إياها مرارا ثم قال ما كذب من قال إنك أشعر الناس","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":1,"spl":"كان يهجو من يناديه بلقبه — عبد الملك اعجب بشعره فمدحه","loc":2080},
{"id":"b120-4","bab":"الجزء 11","sec":"اتهم بالعنة فنفى ذلك","page":"ج11 ص257","text":"أخبرني عمي عن الكراني عن ابن سلام قال كان الاقيشر عنينا وكان لا يأتي النساء وكان كثيرا ما كان يصف\nضد ذلك من نفسه فجلس إليه يوما رجل من قيس فأنشده الأقيشر\n(ولقد أروح بمشرف ذي شعرة ... عسر المكرة ماؤه يتفصد)\n(مرح يطير من المراح لعابه ... وتكاد جلدته به تتقدد)\nم قال للرجل أتبصر الشعر قال نعم قال فما وصفت قال فرسا قال أفكنت لو رأيته ركبته قال إي والله وأثني عطفه فكشف عن أيره وقال هذا وصفت فقم فاركبه فوثب الرجل من مجلسه وجعل يقول له قبحك الله من جليس سائر اليوم ونسخت من كتاب عبد الله بن خلف حدثني أبو عمرو الشيباني قال ماتت بنت زياد العصفري فخرج الأقيشر في جنازتها فلما دفنوها انصرف فلقيه عابس مولى عائذ الله فقال له هل لك في غداء وطلاء أتيت به من طيزناباذ قال نعم فذهب به إلى منزله فغداه وسقاه فلما شرب قال\n(فليت زيادا لا يزلن بناته ... يمتن وألقى كلما عشت عابسا)\n(فذلك يوم غاب عني شره ... وأنجحت فيه بعد ما كنت آيسا)\nنسخت من كتابه حدثني أبو عمرو قال شرب الأقيشر في بيت خمار بالحيرة فجاءه الشرط ليأخذوه فتحرز\nمنهم وأغلق بابه وقال لست أشرب فما سبيلكم علي قالوا قد رأينا العس في كفك وأنت تشرب قال إنما شربت من لبن لقحة لصاحب الدار فلم يبرحوا حتى أخذوا منه درهمين فقال\n(إنما لقحتنا باطية ... فإذا ما مزجت كانت عجب)\n(لبن أصفر صاف لونه ... ينزع الباسور من عجب الذنب)\n(إنما نشرب من أموالنا ... فسلوا الشرطي ما هذا الغضب)\nخبرني الحسن بن علي عن العنزي عن محمد بن معاوية قال دخل وفد بني أسد على عبد الملك بن مروان فقال من شاعركم يا بني أسد قالوا إن فينا لشعراء ما يرضى قومهم أن يفضلوا عليهم أحدا قال لهم فما فعل الأقيشر قالوا مات قال لم يمت ولكنه مشتغل بعشقه وما أبعد أن يكون شاعركم إلا أنه يضيع نفسه أليس هو القائل\n(يأيها السائل عما مضى ... من علم هذا الزمن الذاهب)\n(إن كنت تبغي العلم أو أهله ... أو شاهدا يخبر عن غائب)\n(فاعتبر الأرض بأسمائها ... واعتبر الصاحب بالصاحب)\nذكر عبد الله بن خلف عن أبي عمرو الشيباني أن جارا للأقيشر طحانا كان ينسىء الناس يكنى أبا عائشة فأتاه الأقيشر يسأله فلم يعطه فقال له\n(يريد النساء ويأبى الرجال ... فما لي وما لأبي عائشه)\n(أدام له الله كد الرجال ... وأثكله ابنته عائشه)\nأعطاه ما أراد واستعفاه من أن يزيد شيئا نسخت من كتاب عبيد الله بن محمد اليزيدي بخطه قال الهيثم بن عدي حدثني عطاف بن عاصم بن الحدثان قال مر أعرابي من بني تميم كان يهزأ بالأقيشر فقال له\n(أبا معرض كن أنت إن مت دافني ... إلى جنب قبر فيه شلو المضلل)\n(فعلي أن أنجو من النار إنها ... تضرم للعبد اللئيم المبخل)\n(بذلك أوصاها الإله ولم تزل ... تحش بأوصال وترب وجندل)\n(وأنت بحمد الله إن شئت مفلتي ... بحزمك فاحزم يا أقيشر واعجل)\nقال له ممن أنت قال من بني تميم ثم أحد بني الهجيم بن عمرو بن تميم فقال الأقيشر\n(تميم بن مر كفكفوا عن تعمدي ... بذل فإني لست بالمتذلل)\n(أيهزأ بي العبد الهجيمي ضلة ... ومثلي رمى ذا التدرإ المتضلل)\n(بداهية دهياء لا يستطيعها ... شماريخ من أركان سلمى ويذبل)\n(وبالله لولا أن حلمي زاجري ... تركت تميما ضحكة كل محفل)\n(فكفوا رماكم ذو الجلال بخزية ... تصبحكم في كل جمع ومنزل)\n(فأنتم لئام الناس لا تنكرونه ... وألأمكم طرا حريث بن جندل)\nصار إليه شيوخ من بني الهجيم واعتذروا إليه واستكفوه فكف","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":2,"spl":"اتهم بالعنة فنفى ذلك","loc":2081}]);
window.__BOOK__['p06'].push([{"id":"b120-5","bab":"الجزء 11","sec":"كان يرتجل الشعر وهو في حلقات الشرب والغناء","page":"ج11 ص261","text":"أخبرني الأخفش قال حدثني أبو الفياض بن أبي شراعة عن أبيه قال شرب الأقيشر بالحيرة في بيت فيه خياط مقعد ورجل أعمى وعندهم مغن مطرب فطرب الأقيشر فسقاهم من شربه فلما انتشوا وثب الأعمى يسعى في حوائجهم وقفز الخياط المقصد يرقص على ظلعه فجهد في ذلك كل جهد فقال الأقيشر\n(ومقعد قوم قد مشى من شرابنا ... وأعمى سقيناه ثلاثا فأبصرا)\n(شرابا كريح العنبر الورد ريحه ... ومسحوق هندي من المسك أذفرا)\n(من الفتيات الغر من أرض بابل ... إذا شفها الحاني من الدن كبرا)\n(لها من زجاج الشام عنق غريبة ... تأنق فيها صانع وتخيرا)\n(ذخائر فرعون التي جبيت له ... وكل يسمى بالعتيق مشهرا)\n(إذا ما رآها بعد إنقاء غسلها ... تدور علينا صائم القوم أفطرا)\nخبرنا علي بن سليمان قال حدثني سوار قال حدثني أبي قال كان الأقيشر صاحب شراب وندامى فأشخص الحجاج بعض ندمائه إلى\nبعض النواحي ومات بعضهم ونسك بعضهم وهرب بعضهم فقال في ذلك\n(غلب الصبر فاعترتني هموم ... لفراق الثقات من إخواني)\n(مات هذا وغاب هذا وهذا ... دائب في تلاوة القرآن)\n(ولقد كان قبل إظهاره النسك ... قديما من أظرف الفتيان)\nوأخبرني أبو الحسن الأسدي عن العنزي قال قال ابن الكلبي حدثني سلمة ابن عبد سواع عن أبيه قال كان الأقيشر لا يسأل أحدا أكثر من خمسة دراهم يجعل درهمين في كراء بغل إلى الحيرة ودرهمين للشراب ودرهما للطعام وكان له جار يكنى أبا المضاء له بغل يكريه وكان يعطيه درهمين ويأخذ بغله فيركبه الى الحيرة حتى يأتي بيت الخمار فينزل عنده ويربطه بلجامه وسرجه فيقال إنه أعطى ثمنه في الكراء ثم يجلس فيشرب حتى يمسي ثم يركبه وينصرف فقال في ذلك\n(يا بغل بغل أبي المضاء تعلمن ... أني حلفت ولليمين نذور)\n(لتعسفن وإن كرهت مهامها ... فيما أحب وكل ذاك يسير)\n(بالرغم يا ولد الحمار قطعتها ... عمدا وأنت مذلل مصبور)\n(حتى تزور مسمعا في داره ... وترى المدامة بالأكف تدور)\n(لا يرفعون بما يسوءك نعرة ... وإذا سخطت فخطب ذاك صغير)","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":3,"spl":"كان يرتجل الشعر وهو في حلقات الشرب والغناء — خبره مع أم حنين في بيت الخمار","loc":2082},
{"id":"b120-6","bab":"الجزء 11","sec":"خبره مع أم حنين في بيت الخمار","page":"ج11 ص262","text":"قال فأتى يوما من الأيام بيت الخمار الذي كان يأتيه فلم يصادفه فجعل\nينتظره ودخلت الدار امرأة عبادية فقال لها ما فعل فلان قالت مضى في حاجة وأنا امرأته فما تريد قال نبيذا قالت بكم قال بدرهمين قالت هلم درهميك وانتظرني قال لا قالت فذلك إليك ومضت وتبعها فدخلت دارا لها بابان وخرجت من أحدهما وتركته فلما طال جلوسه خرج إليه بعض أهل الدار قالوا وما يجلسك فأخبرهم فقالوا له تلك امرأة محتالة يقال لها أم حنين من العباديين فعلم أنه قد خدع فانصرف الى خماره فأخبره بالقصة وقال له أنسئني اليوم فاسقني ففعل وأنشأ الأقيشر يقول\n(لم يغرر بذات خف سوانا ... بعد أخت العباد أم حنين)\n(وعدتنا بدرهمين نبيذا ... أو طلاء معجلا غير دين)\n(ثم ألوت بالدرهمين جميعا ... يا لقومي لضيعة الدرهمين)\nذكر هذا الخبر عبد الله بن خلف عن أبي عمرو الشيباني وزاد فيه أن الخمار كان يسمى بحنين وأن المرأة المحتالة قالت له إنها أم حنين الخمار الذي كان يعامله حتى أخذت الدرهمين ثم هربت منه وذكر الأبيات الثلاثة التي تقدمت وبعدها\n(عاهدت زوجها وقد قال إني ... سوف أغدو لحاجتي ولديني)\n(فدعت كالحصان أبيض جلدا ... وافر الأير مرسل الخصيتين)\n(قال ما أجرذا هديت فقالت ... سوف أعطيك أجره مرتين)\n(فأبدأ الآن بالسفاح فلما ... سافحته أرضته بالأخريين)\n(تلها للجبين ثم امتطاها ... عالم الأير أفحج الحالبين)\n(بينما ذاك منهما وهي تحوي ... ظهره بالبنان والمعصمين)\n(جاءها زوجها وقد شام فيها ... ذا انتصاب موثق الأخدعين)\n(فتأسى وقال ويل طويل ... لحنين من عار أم حنين)\nال فجاء حنين الخمار فقال له يا هذا ما أردت بهجائي وهجاء أمي قال أخذت مني درهمين ولم تعطني شرابا قال والله ما تعرفك أمي ولا أخذت منك شيئا قط فانظر إلى أمي فإن كانت هي صاحبتك غرمت لك الدرهمين قال لاوالله ما أعرف غير أم حنين ما قالت لي إلا ذلك ولا أهجو إلا أم حنين وابنها فإن كانت أمك فإياها أعني وإن كانت أم حنين أخرى فإياها أعني فقال أذا لا يفرق الناس بينهما قال فما علي أذا أترى درهمي يضيعان فقال له هلم إذا أغرمهما لك وأقم ما تحتاج إليه لا بارك الله لك ففعل","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":3,"spl":"كان يرتجل الشعر وهو في حلقات الشرب والغناء — خبره مع أم حنين في بيت الخمار","loc":2083},
{"id":"b120-7","bab":"الجزء 11","sec":"كان يرفض القليل من العطاء","page":"ج11 ص264","text":"قال عبد الله وحدثني أبو عمرو قال كان العريان بن الهيثم النخعي صديقا للأقيشر فقال له يا أقيشر إني أريد أن أمتد الى الشأم فأكتبني من ملحك فأكتبه فخرج إلى الشأم فأصاب مالا فبعث الى الأقيشر بخمسين درهما ففعل وقال هات قال المولى على أن تهجوه إذ وضع منك قال نعم فأعطاه خمسين درهما وقال الأقيشر\n(وسألتني يوم الرحيل قصائدا ... فملأتهن قصائدا وكتابا)\n(إني صدقتك إذ وجدتك صادقا ... وكذبتني فوجدتني كذابا)\n(وفتحت بابا للخيانة عامدا ... لما فتحت من الخيانة بابا)\nكان أبو العريان على الشرطة فخافه الأقيشر من هجاء ابنه وبلغ الهيثم هذه الأبيات فبعث إليه بخمسمائة درهم وسأله الكف عن ابنه وألا يشهره فأخذها وفعل قال أبو عمرو وخطب رجل من حضرموت امرأة من بني أسد فأقبل يسأل عنها وعن حسبها وأمهاتها حتى جاء الأقيشر فسأله عنها فقال له من أين أنت قال من حضرموت فأنشأ يقول\n(حضرموت فتشت أحسابنا ... وإلينا حضرموت تنتسب)\n(إخوة القرد وهم أعمامه ... برئت منكم إلى الله العرب)\nخبرني الحسن بن علي عن أبي أيوب المديني قال قال أبو طالب الشاعر حدثني رجل من بني أسد قال سمعت عمة الأقيشر تقول له يوما اتق الله وقم فصل فقال لا أصلي فأكثرت عليه فقال قد أبرمتني فاختاري خصلة من خصلتين إما أن أصلي ولا أتطهر وإما أن أتطهر ولا أصلي قالت قبحك الله فإن لم يكن غير هذا فصل بلا وضوء","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":4,"spl":"كان يرفض القليل من العطاء","loc":2084},
{"id":"b120-8","bab":"الجزء 11","sec":"كان يحتال على رجال الشرطة فيتخلص منهم","page":"ج11 ص265","text":"قال أبو أيوب وحدثت أنه شرب يوما في بيت خمار بالحيرة فجاء شرطي من شرط الأمير ليدخل عليه فغلق الباب دونه فناداه الشرطي اسقني نبيذا وأنت آمن فقال والله ما آمنك ولكن هذا ثقب في البال فاجلس عنده\nوأنا أسقيك منه ثم وضع له أنبوبا من قصب في الثقب وصب فيه نبيذا من داخل والشرطي يشرب من خارج الباب حتى سكر فقال الأقيشر\n(سأل الشرطي أن نسقيه ... فسقيناه بأنبوب القصب)\n(إنما نشرب من أموالنا ... فسلوا الشرطي ما هذا الغضب)\nخبرني عمي عن الكراني عن قعنب بن المحرز وحدثنا محمد بن خلف عن أبي أيوب المديني عن قعنب بن الهيثم بن عدي قال كان قيس بن محمد بن الأشعث ضرير البصر فأتاه الأقيشر فسأله فأمر قهرمانه فأعطاه ثلاثمائة درهم فقال لاأريدها جملة ولكن مر القهرمان أن يعطيني في كل يوم ثلاثة دراهم حتى تنفذ فكان يأخذها منه فيجعل درهما لطعامه ودرهما لشرابه ودرهما لدابة تحمله إلى بيوت الخمارين فلما نفذت الدراهم أتاه الثانية فسأله فأعطاه وفعل مثل ذلك وأتاه الثالثة فأعطاه وفعل مثل ذلك وأتاه الرابعة فسأله فقال له قيس لا أبا لك كأنك قد جعلت هذا خراجا علينا فانصرف وهو يقول\n(ألم تر قيسالأكمه ابن محمد ... يقول ولا تلقاه للخير يفعل)\n(رأيتك أعمى العين والقلب ممسكا ... وما خير أعمى العين والقلب يبخل)\n(فلو صم تمت لعنة الله كلها ... عليه وما فيه من الشر أفضل)\nقال قيس لو نجا أحد من الأقيشر لنجوت منه اخبرني أبو الحسن الأسدي عن العنزي عن محمد بن معاوية قال اختصم قوم بالكوفة في أبي بكر وعمر وعثمان وعلي فقالوا نجعل بيننا أول من يطلع علينا فطلع الأقيشر عليهم وهو سكران فقال بعضهم\nلبعض انظروا من حكمنا فقالوا يا أبا معرض قد حكمناك قال فيماذا فأخبروه فمكث ساعة ثم أنشأ يقول\n(إذا صليت خمسا كل يوم ... فإن الله يغفر لي فسوقي)\n(ولم أشرك برب الناس شيئا ... فقد أمسكت بالحبل الوثيق)\n(وهذا الحق ليس به خفاء ... ودعني من بنيات الطريق)\nال محمد بن معاوية وتزوج الأقيشر ابنة عم له يقال لها الرباب على أربعة آلاف درهم ويقال على عشرة آلاف درهم فأتى قومه فسألهم فلم يعطوه شيئا فأتى ابن رأس البغل وهو دهقان الصين وكان مجوسيا فسأله فأعطاه الصداق فقال الأقيشر\n(كفاني المجوسي مهر الرباب ... فدى للمجوسي خالي وعم)\n(شهدت بأنك رطب المشاش ... وأن أباك الجواد الخضم)\n(وأنك سيد أهل الجحيم ... اذا ما ترديت فيمن ظلم)\n(تجاور قارون في قعرها ... وفرعون والمكتنى بالحكم)\nقال له المجوسي ويحك سألت قومك فلم يعطوك وجئتني فأعطيتك فجزيتني هذا القول ولم أفلت من شعرك وشرك قال أوما ترضى أن جعلتك مع الملوك وفوق أبي جهل ثم جاء إلى عكرمة بن ربعي التميمي فلم يعطه فقال فيه\n(سألت ربيعة من شرها ... أبا ثم أما فقالوا لمه)\n(فقلت لأعلم من شركم ... وأجعل بالسب فيه سمه)\n(فقالوا لعكرمة المخزيات ... وماذا يرى الناس في عكرمه)\n(فإن يك عبدا زكا ماله ... فما غير ذا فيه من مكرمه)","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":5,"spl":"كان يحتال على رجال الشرطة فيتخلص منهم","loc":2085},
{"id":"b120-9","bab":"الجزء 11","sec":"شرب بثيابه حتى غلقت","page":"ج11 ص268","text":"قال ابن الكلبي وشرب الأقيشر في حانة خمار حتى أنفد مامعه ثم شرب بثيابه حتى غلقت فلم يبق عليه شيء وجلس في تبن إلى جانب البيت إلى حلقه مستدفئا به فمر رجل به ينشد ضالة فقال اللهم اردد عليه واحفظ علينا فقال له الخمار سخنت عينك أي شيء يحفظ عليك ربك قال هذا التبن لا تأخذه فأموت من البرد فضحك الخمار ورد عليه ثيابه وقال اذهب فاطلب ما تشرب به ولا تجئني بثيابك فإني لا أشتريها بعد ذلك قال ابن الكلبي واجتاز الأقيشر برجل يقال له هشام وكان على شرطة عمرو بن حريث وهو سكران فدعا به فقال له أنت سكران قال لا قال فما هذه الرائحة قال أكلت سفرجلا ثم قال\n(يقولون لي انكه شربت مدامة ... فقلت كذبتم بل أكلت سفرجلا)\nضحك منه ثم قال فإن لم تكن سكران فأخبرني كم تصلي في كل يوم فقال\n(يسائلني هشام عن صلاتي ... صلاة المسلمين فقلت خمس)\n(صلاة العصر والأولى ثمان ... مواترة فما فيهن لبس)\n(وعند مغيب قرن الشمس وتر ... وشفع بعدها فيهن حبس)\n(وغدوة اثنتان معا جميعا ... ولما تبد للرائين شمس)\n(وبعدهما لوقتهما صلاة ... لنسك بالضحاء إذا نبس)\n(أأحصيت الصلاة أيا هشاما ... فذاك مكدر الأخلاق جبس)\n(تعود أن يلام فليس يوما ... بحامده من الأقوام إنس)\nقال فضحك هشام وقال بلى قد أخبرتنا يا أبا معرض فانصرف راشدا أخبرني محمد بن الحسن بن دريد عن أبي عبيدة قال قدم رجل من بني سلول على قتيبة بن مسلم بكتاب عامله على الري وهو المعلى بن عمرو المحاربي فرآه على الباب قدامه بن جعدة بن هبيرة المخزومي وكان صديقا لقتيبة فدخل عليه فقال له ببابك ألأم العرب سلولي رسول محاربي إلى باهلي فتبسم قتيبة تبسما فيه غيظ وكان قدامة بن جعدة يتهم بشرب الخمر وكان الأقيشر ينادمه فقال قتيبة ادعوا لي مرداس بن جذام الأسدي فدعي فقال له أنشدني ما قال الأقيشر في قدامة بن جعدة وهو بالحيرة فأنشده قوله\n(رب ندمان كريم ماجد ... سيد الجدين من فرعي مضر)\n(قد سقيت الكأس حتى هرها ... لم يخالط صفوها منه كدر)\n(قلت قم صل فصلى قاعدا ... تتغشاه سمادير السكر)\n(قرن الظهر مع العصر كما ... تقرن الحقة بالحق الذكر)\n(ترك الفجر فما يقرؤها ... وقرا الكوثر من بين السور)\nال فتغير لون وجه القرشي وخجل فقال له قتيبة هذه بتلك والبادىء أظلم أخبرني الأخفش عن محمد بن الحسن بن الحرون قال حدثنا الكسروي عن الأصمعي قال قال عبد الملك للأقيشر أنشدني أبياتك في الخمر فأنشده قوله\n(تريك القذى من دونها وهي دونه ... لوجه أخيها في الإناء قطوب)\n(كميت إذا فضت وفي الكأس وردة ... لها في عظام الشاربين دبيب)\nقال له أحسنت يا أبا معرض ولقد أجدت وصفها وأظنك قد شربتها فقال والله يا أمير المؤمنين إنه ليريبني منك معرفتك بهذا","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":6,"spl":"شرب بثيابه حتى غلقت","loc":2086},
{"id":"b120-10","bab":"الجزء 11","sec":"كان ندماؤه يختبئون منه عندما تنفد دراهمه","page":"ج11 ص270","text":"أخبرني الحسن بن يحيى عن حماد بن إسحاق عن ابن الكلبي عن رجل من الأزد قال كان الأقيشر يأتي إخوانا له يسألهم فيعطونه فأتى رجلا منهم فأمر له بخمسمائة درهم فأخذها وتوجه إلى الحانة ودفعها إلى صاحبها وقال له أقم لي ما أحتاج إليه ففعل ذلك وانضم إليه رفقاء له فلم يزل معهم حتى نفدت\nالدراهم فأتاهم بعد إنفاقها بيوم ثم أتاهم من غد فاحتملوه فلما أتاهم في اليوم الثالث نظر إليه أصحابه من بعيد فقالوا لصاحب الحانة أصعدنا إلى غرفتك هذه وأعلم الأقيشر أنا لم نأت اليوم فلما جاء الأقيشر أعلمه ما قالوه له فعلم الأقيشر أنه لا فرج له عند صاحب الحانة إلا برهن فطرح إليه ثيابه وقال له أقم لي ما أحتاج إليه ففعل فلما أخذ فيه الشراب أنشأ يقول\n(يا خليلي اسقياني كاسا ... ثم كأسا حتى أخر نعاسا)\n(إن في الغرفة التي فوق رأسي ... لأناسا يخادعون أناسا)\n(يشربون المعتق الراح صرفا ... ثم لا يرفعون بالزور راسا)\nلما سمع أصحابه هذا الشعر فدوه بآبائهم وأمهاتهم ثم قالوا له إما أن تصعد إلينا أو ننزل إليك فصعد إليهم أخبرني الحسن بن علي عن ابن مهرويه قال حدثني أبو مسلم المستملي عن المدائني قال مدح الأقيشر بشر بن مروان ودخل إليه فأنشده القصيدة وعنده أيمن بن خريم بن فاتك الأسدي فقال أيمن هذا والله كلام حسن من جوف خرب فأجابه بالبيت المذكور وقال أبو عمرو أيضا في خبره فلما صار الأقيشر إلى منزله بعث عمه فأخذ منه الألف الدرهم وقال والله لا أخليك تفسدها وتشرب بها الخمر قال فتصنع بها ماذا قال أكسوك واكسو عيالك وأعد لك قوت عامك فتركه ودخل على بشر فقال له\n(أبلغ أبا مروان أن عطاءه ... أزاغ به من ليس لي بعيال)\nقال ومن ذلك فأخبره الخبر فأمر صاحب شرطته أن يحضر عمه\nوينتزع منه الألف الدرهم ويسلمها إليه وقال خذها ونحن نقوم لعيالك بما يصلحهم أخبرني هاشم بن محمد عن أبي غسان دماذ عن أبي عبيدة قال مر الأقيشر بخمارة بالحيرة يقال لها دومة فنزل عندها فاشترى منها نبيدا ثم قال لها جودي لي الشراب حتى أجيد لك المدح ففعلت فأنشأ يقول\n(ألا يا دوم دام لك النعيم ... وأسمر ملء كفك مستقيم)\n(شديد الاسر ينبض حالباه ... يحم كأنه رجل سقيم)\n(يرويه الشراب فيزدهيه ... وينفخ فيه شيطان رجيم)\nال فسرت به الخمارة وقالت ما قيل في أحسن من هذا ولا أسر لي منه أخبرني أبو الحسن الأسدي عن حماد بن إسحاق عن أبيه عن أيوب بن عباية قال كان فاتك بن فضالة بن شريك الأسدي كريما على بني أمية وهو الوافد على عبد الملك بن مروان قبل أن ينهض الى حرب ابن الزبير فضمن له على أهل العراق طاعتهم وتسليم بلادهم إليه وأن يسلموا مصعبا إذا لقيه ويتفرقوا عنه وله يقول الأقيشر في هذه الوفادة\n(وفد الوفود فكنت أفضل وافد ... يا فاتك بن فضالة بن شريك)","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":7,"spl":"كان ندماؤه يختبئون منه عندما تنفد دراهمه","loc":2087},
{"id":"b120-11","bab":"الجزء 11","sec":"هجوه بني تميم","page":"ج11 ص272","text":"أخبرني علي بن سليمان الأخفش عن السكري قال حدثني ابن حبيب قال\nولي الكوفة رجل من بني تميم يقال له مطر فلما علا المنبر انكسرت الدرجة من تحته فسقط عنها فقال الأقيشر\n(أبني تميم ما لمنبر ملككم ... ما يستقر قراره يتمرمر)\n(إن المنابر أنكرت أستاهكم ... فادعوا خزيمة يستقر المنبر)\nخبرني محمد بن مزيد عن حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال مر رجل من محارب يقال له قريظة بن يقظة بالأقيشر الأسدي وهو في مجلس من مجالس بني أسد فسلم على الأقيشر وكان به عارفا فقال له القوم من هذا يا أبا معرض وكان مخمورا فقال\n(ومن لي بأن أسطيع أن أذكر اسمه ... وأعيا عقالا أن يطيق له ذكرا)\nقال فضحك القوم وقالوا سبحان الله أي شيء تقول فقال اسمه ونسبه أعظم من أن أقدر على ذكرهما في يوم فإن شئتم سميته اليوم ونسبته غدا وإن شئتم نسبته اليوم وسميته غدا قالوا هات اسمه اليوم فقال قريظة فقال رجل منهم ينبغي أن يكون ابن يقظة فقال الأقيشر صدقت والله وأصبت ولقد أثقلني اسمه حين ذكرته أن أقول نعم فبلغ قريظة قوله وكان شاعرا فقال\n(لسانك من سكر ثقيل عن التقى ... ولكنه بالمخزيات طليق)\n(وأنت حقيق يا أقيشر أن ترى ... كذاك إذا ما كنت غير مفيق)\n(تسف من الصهباء صرفا تخالها ... جنى النحل يهديه إليك صديق)\nبلغ الأقيشر قول المحاربي وكان يكنى أبا الذيال فأجابه فقال\n(عدمت أبا الذيال من ذي نوالة ... له في بيوت العاهرات طريق)\n(أبالخمر عيرت أمرأ ليس مقلعا ... وذلك رأي لو علمت وثيق)\n(سأشربها ما دمت حيا وإن أمت ... ففي النفس منها زفرة وشهيق)","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":8,"spl":"هجوه بني تميم — شعر له في توبته من الخمر","loc":2088},
{"id":"b120-12","bab":"الجزء 11","sec":"شعر له في توبته من الخمر","page":"ج11 ص274","text":"أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال بلغني أن الرشيد سمع ليلة رجلا يغني\n(إن كانت الخمر قد عزت وقد منعت ... وحال من دونها الإسلام والحرج)\n(فقد أباكرها صرفا وأشربها ... أشفي بها غلتي صرفا وأمتزج)\n(وقد تقوم على رأسي مغنية ... لها إذا رجعت في صوتها غنج)\n(وترفع الصوت أحيانا وتخفضه ... كما يطن ذباب الروضة الهزج)\nال فوجه في أثر الصوت من جاءه بالرجل وهو يرعد فقال لا ترع فإنما أعجبني حسن صوتك فقال والله يا أمير المؤمنين ما تغنيت بهذا الشعر إلا وأنا قد تبت من شرب النبيذ وهذا شعر يقوله الأقيشر في توبته من النبيذ فقال له الرشيد وما حملك على تركه قال خشية الله وإني فيه يا أمير المؤمنين كما قال زيد بن ظبيان\n(جاءوا بقاقزة صفراء مترعة ... هل بين ذي كبرة والخمر من نسب)\n(بئس الشراب شرابا حين تشربه ... يوهي العظام وطورا مفتر العصب)\n(إني أخاف مليكي أن يعذبني ... وفي العشيرة أن يزري على حسبي)\nقال له الرشيد أنت وما اخترت أعلم فأعد الصوت فأعاده وأمر بإحضار المغنين واستعاده وأمرهم بأخذه عنه فأخذوه ووصله وانصرف وكان صوت الرشيد أياما هكذا ذكر إسماعيل بن يونس عن عمر بن شبة في هذا الخبر أن الأبيات للأقيشر ووجدتها في شعر أبي محجن الثقفي له لما تاب من الشراب","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":8,"spl":"هجوه بني تميم — شعر له في توبته من الخمر","loc":2089},
{"id":"b120-13","bab":"الجزء 11","sec":"باع حماره وشرب بثمنه","page":"ج11 ص275","text":"أخبرني علي بن سليمان قال حدثنا أبو سعيد عن محمد بن حبيب قال كان القباع وهو الحارث بن عبد الله بن أبي ربيعة قد أخرج الأقيشر مع قومه لقتال أهل الشأم ولم يكن عند الأقيشر فرس فخرج على حمار فلما عبر جسر سورا فوصل لقرية يقال لها قنين توارى عند خمار نبطي يبرز زوجته\nللفجور فباع حماره وجعل ينفقه هناك ويشرب بثمنه ويفجر إلى أن قفل الجيش وقال في ذلك\n(خرجت من المصر الحواري أهله ... بلا ندبة فيها أحتساب ولا جعل)\n(إلى جيش أهل الشأم أغزيت كارها ... سفاها بلا سيف حديد ولا نبل)\n(ولكن بترس ليس فيه حمالة ... ورمح ضعيف الزج منصدع النصل)\n(حباني به ظلم القباع ولم أجد ... سوى أمره والسير شيئا من الفعل)\n(فأزمعت أمري ثم أصبحت غازيا ... وسلمت تسليم الغزاة على أهلي)\n(وقلت لعلي أن أرى ثم راكبا ... على فرس أو ذا متاع على بغل)\n(جوادي حمار كان حينا لظهره ... إكاف وإشناق المزادة والحبل)\n(وقد خان عينيه بياض وخانه ... قوائم سوء حين يزجر في الوحل)\n(إذا ما انتحى في الماء والوحل لم ترم ... قوائمه حتى يؤخر بالحمل)\n(أنادي الرفاق بارك الله فيكم ... رويدكم حتى أجوز إلى السهل)\n(فسرنا الى قنين يوما وليلة ... كأنا بغايا ما يسرن الى بعل)\n(إذا ما نزلنا لم نجد ظل ساحة ... سوى يابس الأنهار أو سعف النخل)\n(مررنا على سوراء نسمع جسرها ... يئط نقيضا عن سفائنه الفضل)\n(فلما بدا جسر السراة وأعرضت ... لنا سوق فراغ الحديث إلى شغل)\n(نزلنا إلى ظل ظليل وباءة ... حلال برغم القلطمان وما نفل)\n(يشارطه من شاء كان بدرهم ... عروسا بما بين السبيئة والنسل)\n(فأتبعت رمح السوء سمية نصله ... وبعت حماري واسترحت من الثقل)\n(تقول ظبايا قل قليلا ألاليا ... فقلت لها إصوي فإني على رسل)\n(مهرت لها جرديقة فتركتها ... بمرها كطرف العين شائلة الرجل)\nمما يغنى فيه من شعر الأقيشر\n(لا أشربن أبدا راحا مسارقة ... إلا مع الغر أبناء البطاريق)\n(أفنى تلادي وما جمعت من نشب ... قرع القواقيز أفواه الأباريق)\nلغناء لحنين هزج بالبنصر عن عمرو وفيه لعمر الوادي رمل بالبنصر عن الهشامي وفيه ثقيل أول ينسب إلى حنين وعمر وحكم جميعا وهذا الغناء المذكور من قصيدة للأقيشر طويلة أولها\n(إني يذكرني هندا وجارتها ... بالطف صوت حمامات عل نيق)\n\n(دعاني دعوة والخيل تردي ... فلا أدري أباسمي أم كناني)\n(وكان إجابتي إياه إني ... عطفت عليه خوار العنان)\nلشعر لابن الغريزة النهشلي والغناء ليحيى المكي رمل بالوسطى عن الهشامي وقد جعل المغنون معه هذا البيت ولم أجده في قصيدته ولا أدري أهو له أم لغيره\n(ألا يا من لذا البرق اليماني ... يلوح كأنه مصباح بان)","topic":"ذكر الأقيشر وأخباره","topicNo":120,"sp":9,"spl":"باع حماره وشرب بثمنه","song":2,"loc":2090},
{"id":"b121-2","bab":"الجزء 11","sec":"أخبار ابن الغريزة ونسبه — قصيدته في يوم الطالقان","page":"ج11 ص278 – ج11 ص279","text":"كثير بن الغريزة التميمي أحد بني نهشل والغريزة أمه وهو مخضرم أدرك الجاهلية والإسلام وقال الشعر فيهما وهذا الشعر يقوله ابن الغريزة في غزاة غزاها الأقرع بن حابس وأخوه بالطالقان وجوزجان وتلك البلاد فأصيب من أصحابه قوم بالطالقان فرثاهم ابن الغريزة\nأخبرني الصولي عن الحزنبل عن ابن أبي عمرو الشيباني عن أبيه قال بعث عمر بن الخطاب الأقرع بن حابس وأخاه على جيش إلى الطالقان وجوزجان وتلك البلاد فأصيب من أصحابه قوم بالطالقان فقال ابن الغريزة النهشلي وقد شهد تلك الوقعة يرثيهم ويذكر ذلك اليوم\n(سقى مزن السحاب إذا استهلت ... مصارع فتية بالجوزجان)\n(إلى القصرين من رستاق خوط ... أبادهم هناك الأقرعان)\n(وما بي أن أكون جزعت إلا ... حنين القلب للبرق اليماني)\n(ومحبور برؤيتنا يرجي اللقاء ... ولن أراه ولن يراني)\n(ورب أخ أصاب الموت قبلي ... بكيت ولو نعيت له بكاني)\n(دعاني دعوة والخيل تردي ... فما أدري أباسمي أم كناني)\n(فكان إجابتي إياه أني ... عطفت عليه خوار العنان)\n(وأي فتى دعوت وقد تولت ... بهن الخيل ذات العنظوان)\n(وأي فتى إذا ما مت تدعو ... يطرف عنك غاشية السنان)\n(فإن أهلك فلم أك ذا صدوف ... عن الأقران في الحرب العوان)\n(ولم أدلج لأطرق عرس جاري ... ولم أجعل على قومي لساني)\n(ولكني إذا ما هايجوني ... منيع الجار مرتفع البنان)\n(ويكرهني إذا استبسلت قرني ... وأقضي واحدا ما قد قضاني)\n(فلا تستبعدا يومي فإني ... سأوشك مرة أن تفقداني)\n(ويدركني الذي لا بد منه ... وإن أشفقت من خوف الجنان)\n(وتبكيني نوائح معولات ... تركن بدار معترك الزمان)\n(حبائس بالعراق منهنهات ... سواجي الطرف كالبقر الهجان)\n(أعاذلتي من لوم دعاني ... وللرشد المبين فاهدياني)\n(وعاذلتي صوتكما قريب ... ونفعكما بعيد الخير واني)\n(فردا الموت عني إن أتاني ... ولا وأبيكما لا تفعلان)\n\n(دار لقاتلة الغرانق ما بها ... غير الوحوش خلت له وخلا لها)\n(ظلت تسائل بالمتيم ما به ... وهي التي فعلت به أفعالها)\nلشعر لأعشى بني تغلب من قصيدة يمدح بها مسلمة بن عبد الملك ويهجو جريرا ويعين الأخطل عليه ويروى ربع لقانصة الغرانق وهو الصحيح هكذا ويغنى دار لقاتلة لأنه يقول في آخر البيت خلت له وخلا لها والغناء لعبد الله بن العباس ثاني ثقيل بالبنصر عن عمرو بن بانة وابن المكي وفيه لمخارق رمل من جميع أغانيه","topic":"أخبار ابن الغريزة ونسبه","topicNo":121,"sp":0,"spl":"أخبار ابن الغريزة ونسبه — قصيدته في يوم الطالقان","song":1,"loc":2091},
{"id":"b122-2","bab":"الجزء 11","sec":"أخبار أعشى بني تغلب ونسبه — خبره مع الحر بن يوسف","page":"ج11 ص281 – ج11 ص282","text":"قال أبو عمرو الشيباني اسمه ربيعة وقال ابن حبيب اسمه النعمان بن يحيى بن معاوية أحد بني معاوية بن جشم بن بكر بن حبيب بن عمرو بن تغلب بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار شاعر من شعراء الدولة الأموية وساكني الشأم إذا حضر وإذا بدا نزل في بلاد قومه بنواحي الموصل وديار ربيعة وكان نصرانيا وعلى ذلك مات\nأخبرني علي بن سليمان الأخفش عن أبي سعيد السكري قال حدثنا محمد بن حبيب عن أبي عمرو الشيباني قال كان أعشى بني تغلب ينادم الحر بن يوسف بن يحيى بن الحكم فشربا يوما في بستان له بالموصل فسكر الأعشى فنام في البستان ودعا الحر بجواريه فدخلن عليه قبته واستيقظ الأعشى فأقبل ليدخل القبة فمانعه الخدم ودافعهم حتى كاد أن يهجم على الحر مع جواريه فلطمه خصي منهم فخرج إلى قومه فقال لهم لطمني الحر فوثب معه رجل من بني تغلب يقال له ابن أدعج وهو شهاب بن همام بن ثعلبة بن أبي سعد فاقتحما\nالحائط وهجما على الحر حتى لطمه الأعشى ثم رجعا فقال الأعشى\n(كأني وابن أدعج إذ دخلنا ... على قرشيك الورع الجبان)\n(هزبرا غابة وقصا حمارا ... فظلا حوله يتناهشان)\n(أنا الجشمي من جشم بن بكر ... عشية رعت طرفك بالبنان)\nأي لطمتك وقوله أنا الجشمي أي مثلي يفعل ذلك بمثلك\n(فما يسطيع ذو ملك عقابي ... إذا اجترمت يدي وجنى لساني)\n(عشية غاب عنك بنو هشام ... وعثمان استها وبنو أبان)\n(تروح إلى منازلها قريش ... وأنت مخيم بالزرقان)\nالزرقان قرية كانت للحر بسنجار","topic":"أخبار أعشى بني تغلب ونسبه","topicNo":122,"sp":0,"spl":"أخبار أعشى بني تغلب ونسبه — خبره مع الحر بن يوسف — مدح وأسيء ثوابه","loc":2092},
{"id":"b122-3","bab":"الجزء 11","sec":"مدح وأسيء ثوابه","page":"ج11 ص283","text":"قال ابن حبيب مدح أعشى بني تغلب مدرك بن عبد الله الكناني أحد بني أقيشر بن جذيمة بن كعب فأساء ثوابه فقال الأعشى\n(لعمرك إني يوم أمدح مدركا ... لكالمبتني حوضا على غير منهل)\n(أمر الهوى دوني وفيل مدحتي ... ولو لكريم قلتها لم تفيل)\nقال ابن حبيب كان شمعلة بن عامر بن عمرو بن بكر أخو بني فائد وهم رهط الفرس نصرانيا وكان ظريفا فدخل على بعض خلفاء بني أمية فقال أسلم يا شمعلة قال لا والله أسلم كارها أبدا ولا أسلم إلا طائعا إذا شئت فغضب فأمر به فقطعت بضعة من فخذه وشويت بالنار وأطعمها فقال أعشى بني تغلب في ذلك\n(أمن خذة بالفخذ منك تباشرت ... عداك فلا عار عليك ولا وزر)\n(وإن أمير المؤمنين وجرحه ... لكا لدهر لا عار بما فعل الدهر)\nقال ابن حبيب قال أبو عمرو كان الوليد بن عبد الملك محسنا إلى أعشى بني تغلب فلما ولي عمر بن عبد العزيز الخلافة وفد إليه ومدحه فلم يعطه شيئا وقال ما أرى للشعراء في بيت المال حقا ولو كان لهم فيه حق لماكان لك لأنك امرؤ نصراني فانصرف الأعشى وهو يقول\n(لعمري لقد عاش الوليد حياته ... إمام هدى لا مستزاد ولا نزر)\n(كأن بني مروان بعد وفاته ... جلاميد لا تندى وإن بلها القطر)\nقال ابن حبيب عن أبي عمرو كانت بين بني شيبان وبين تغلب حروب فعاون مالك بن مسمع بني شيبان في بعضها ثم قعد عنهم فقال أعشى بني تغلب في ذلك\n(بني أمنا مهلا فإن نفوسنا ... تميت عليكم عتبها ومصالها)\n(وترعى بلا جهل قرابة بيننا ... وبينكم لما قطعتم وصالها)\n(جزى الله شيبانا وتيما ملامة ... جزاء المسيء سعيها وفعالها)\n(أبا مسمع من تنكر الحق نفسه ... وتعجز عن المعروف يعرف ضلالها)\n(أأوقدت نار الحرب حتى إذا بدا ... لنفسك ما تجني الحروب فهالها)\n(نزعت وقد جردتها ذات منظر ... قبيح مهين حيث ألقت حلالها)\n(ألسنا إذا ما الحرب شب سعيرها ... وكان صفيح المشرفي صلالها)\n(أجارتنا حل لكم أن تناولوا ... محارمها وأن تميزوا حلالها)\n(كذبتم يمين الله حتى تعاوروا ... صدور العوالي بيننا ونصالها)\n(وحتى ترى عين الذي كان شامتا ... مزاحف عقرى بيننا ومجالها)\n\n(ويفرح بالمولود من آل برمك ... بغاة الندى والرمح والسيف والنصل)\n(وتنبسط الآمال فيه لفضله ... ولا سيما إن كان من ولد الفضل)\nلشعر لأبي النضير والغناء لإسحاق ثقيل أول بالبنصر عن عمرو بن بانة من مجموع اسحاق وقال حبش فيه لإبراهيم الموصلي ثقيل أول بالبنصر عن عمرو بن بانة من مجموع إسحاق وقال حبش فيه لابراهيم الموصلي ثقيل آخر بالوسطى ولقضيب وبراقش جاريتي يحيى بن خالد فيه لحنان","topic":"أخبار أعشى بني تغلب ونسبه","topicNo":122,"sp":0,"spl":"أخبار أعشى بني تغلب ونسبه — خبره مع الحر بن يوسف — مدح وأسيء ثوابه","song":1,"loc":2093},
{"id":"b123-2","bab":"الجزء 11","sec":"أخبار أبي النضير ونسبه — اسحاق الموصلي يشهد على ظرفه","page":"ج11 ص285 – ج11 ص286","text":"أبو النضير اسمه عمر بن عبد الملك بصري مولى لبني جمح أخبرنا بذلك عمي عن ابن مهرويه عن إسحاق بن محمد النخعي عن إسحاق بن خلف الشاعر قال قلت لأبي النضير بن أبي الياس لمن أنت فقال لبني جمح وذكر أبو يحيى اللاحقي أن اسمه الفضل بن عبد الملك شاعر من شعراء البصريين صالح المذهب ليس من المعدودين المتقدمين ولا من المولدين الساقطين وكان يغني بالبصرة على جوار له مولدات ويظهر الخلاعة والمجون والفسق ويعاشر جماعة ممن يعرف بذلك الشأن وكان أبان اللاحقي يعاشره ثم تصارما وهجاه وهجا جواريه وافترقا على قلى ثم انقطع أبو النضير إلى البرامكة فأغنوه إلى أن مات\nأخبرنا ابن أبي الأزهر عن حماد بن إسحاق قال سمعت أبي يقول لو قيل لي من أظرف من رأيته قط أو عاشرته لقلت أبو النضير\nأخبرني عيسى الوراق عن الفضل اليزيدي عن إسحاق وأخبرني محمد بن مزيد عن حماد عن أبيه قال ولد للفضل بن يحيى مولود فوفد عليه أبو النضير ولم يكن عرف الخبر فيعد له تهنئة فلما مثل بين يديه ورأى الناس يهنئونه نثرا ونظما قال ارتجالا\n(ويفرح بالمولود من آل برمك ... بغاة الندى والسيف والرمح والنصل)\n(وتنبسط الآمال فيه لفضله ... )\nم أرتج عليه فلم يدر ما يقول فقال الفضل يلقنه\n(ولا سيما إن كان من ولد الفضل ... )\nاستحسن الناس بديهة الفضل في هذا وأمر لأبي النضير بصلة وأخبرني حبيب بن نصر عن هارون بن محمد بن عبد الملك الزيات قال حدثني بعض الموالي قال حضرت الفضل بن يحيى وقد قال لأبي النضير يا أبا النضير أنت القائل فينا\n(إذا كنت من بغداد في رأس فرسخ ... وجدت نسيم الجود من آل برمك)\nقد ضيقت علينا جدا قال أفلأجل ذلك أيها الأمير ضاقت علي صلتك وضاقت عني مكافأتك وأنا الذي أقول\n(تشاغل الناس ببنيانهم ... والفضل في بنيانه جاهد)\n(كل ذوي الفضل وأهل النهى ... للفضل في تدبيره حامد)\nعلى ذلك فما قلت البيت الأول كما بلغ الأمير وإنما قلت\n(إذا كنت من بغداد منقطع الثرى ... وجدت نسيم الجود من آل برمك)\nفقال الفضل إنما أخرت عنك لأمازحك وأمر له بثلاثين ألف درهم","topic":"أخبار أبي النضير ونسبه","topicNo":123,"sp":0,"spl":"أخبار أبي النضير ونسبه — اسحاق الموصلي يشهد على ظرفه — خبره مع عنان الجارية","loc":2094,"partialRef":{"sid":"b52-13","gi":1,"vi":1,"side":1},"partial":1},
{"id":"b123-3","bab":"الجزء 11","sec":"خبره مع عنان الجارية","page":"ج11 ص288","text":"أخبرني ابن عمار عن أبي إسحاق الطلحي عن أبي سهيل قال كان أبو النضير يهوى عنان جارية الناطفي وكتب إليها\n(إن لي حاجة فرأيك فيها ... لك نفسي الفدا من الأوصاب)\n(وهي ليست مما يبلغه غيري ... ولا أستطيعه بكتاب)\n(غير أني أقولها حين ألقاك ... رويدا أسرها من ثيابي)\nأجابته وقالت\n(أنا مشغولة بمن لست أهواه ... وقلبي من دونه في حجاب)\n(فإذا ما أردت أمرا فأسرره ... ولا تجعلنه في كتاب)\nال وقال أبو النضير فيها\n\n(أنا والله أهواك ... وأهواك وأهواك)\n(وأهوى قبلة منك ... على برد ثناياك)\n(وأهوى لك ما أهوى ... لنفسي وكفى ذاك)\n(فهل ينفعني ذلك ... يوما حين ألقاك)\n(أنا والله أهواك ... وما يشعر مولاك)\n(فإياك بأن يعلم ... إياك وإياك)\nيه لعلي بن المارقي رمل بالبنصر عن الهشامي حدثنا ابن عمار عن الطلحي عن أبي سهيل قال كان أبو النضير يغني غناء صالحا فغنى ذات يوم صوتا كان استفاده ببغداد فقالت له قينة كانت ببغداد يقال لها مكتومة اطرح علي هذا الصوت يا أبا النضير فقال لا تطيب نفسي به محابيا ولكني أبيعك إياه قالت بكم قال برأس ماله قالت وما رأس ماله قال ناكني فيه الذي أخذته منه فغطت وجهها وقالت عليك وعلى هذا الصوت الدمار أخبرني ابن عمار عن الطلحي عن أبي سهيل قال قال أبو النضير وفيه غناء لإبراهيم\n(أيصحو فؤادك أم يطرب ... وكيف وقد شحطت زينب)\n(جرى الناس قبل أبي جعفر ... زمانا فلم يدر من غلبوا)\n(فلما جرى بأبي جعفر ... بنو تغلب سبقت تغلب)\nقال أبو سهيل وأبو جعفر الذي عناه أبو النضير هو عبد الله بن هشام بن عمرو التغلبي الذي يذكره العتابي في شعره ورسائله وكان جوادا سخيا وكان ابن هشام ولي السند وفيه يقول أبو النضير\n(ألا أيها الغيث الذي سح وبله ... كأنك تحكي راحة ابن هشام)\n(كأنك تحكيها ولكن جوده ... يدوم وقد تأتي بغير دوام)\n(وفيك جهام ربما كان مخلفا ... وراحته تغدو بغير جهام)","topic":"أخبار أبي النضير ونسبه","topicNo":123,"sp":0,"spl":"أخبار أبي النضير ونسبه — اسحاق الموصلي يشهد على ظرفه — خبره مع عنان الجارية","song":2,"loc":2095},
{"id":"b123-4","bab":"الجزء 11","sec":"خالفه ابراهيم الموصلي في قوله ان الغناء على تقطيع العروض","page":"ج11 ص290","text":"أخبرني ابن عمار عن الطلحي عن أبي سهيل قال كان أبو النضير يزعم أن الغناء على تقطيع العروض ويقول هكذا كان الذين مضوا يقولون وكان مستهزئا بالغناء حتى تعاطى أن يغني وكان ابراهيم الموصلي يخالفه في ذلك ويقول العروض محدث والغناء قبله بزمان فقال إسحاق بن إبراهيم ينصر أباه\n(سكت عن الغناء فلا أماري ... بصيرا لا ولا غير البصير)\n(مخافة أن أجنن فيه نفسي ... كما قد جن فيه أبو النضير)\nخبرني الحسن بن علي عن ابن مهرويه قال حدثني أبو طلحة الخزاعي عن اللاحقي قال كان جدي أبان يشرب مع إخوان له على شاطىء دجلة بعد مصارمته أبا\nالنضير وكان القوم أصدقاء له ولأبي النضير فذكروه فقال جدي إن حضر انصرفت فأمسكوا فقال جدي فيه\n(رب يوم بشط دجلة لذ ... وليال نعمت فيها لذاذ)\n(غيبة لم تطل علي وماذا ... خير قرب المطرمذ الملاذ)\n(ترك الأشربات ليس بعاط ... لرساطونها ولا الراقياذ)\n(وحكى الأحمق الذي ليس يدري ... أن خير الشراب هذا اللذاذ)\n(ضل رأي أراه ذاك كما ضل ... غواة لاذوا بشر ملاذ)\n(أنت أعمى فيما ادعيت كما لست ... لصوغ الألحان بالأستاذ)\n(كان ذنبا أتوب منه إلى الله ... اختياريك صاحبا وأتخاذي)\n(إن لله صوم شهرين شكرا ... أن قضى منك عاجلا إنقاذي)\n(لا لدين ولا لدنيا ولا يصلح ... في علم ما ادعى بنفاذ)\nدثني ابن عمار عن الطلحي عن أبي سهيل قال كتب أبو النضير الى حماد عجرد يسأل عن حاله في الشراب وشربه إياه ومن يعاشر عليه فكتب إليه حماد\n(أبا النضير اسمع كلامي ولا ... تجعل سوى الإنصاف من بالكا)\n(سألت عن حالي وما حال من ... لم يلق إلا عابدا ناسكا)\n(يظهر لي ذا فمتى يفترض ... شيئا تجده عاديا فاتكا)\nعني حريث بن عمرو وكان حماد نزل عليه وكان حريث هذا مشهورا بالزندقة وكذلك حماد هذا كان مشهورا بها فنزل عليه لذلك أخبرني الحسن بن علي عن ابن مهرويه عن أبي طلحة الخزاعي عن أبي يحيى اللاحقي قال كتب أبو النضير إلى عمي حمدان بن أبان وكان له صديقا يشكو إليه عمر بن يحيى الزيادي وكان عربد عليه وشتمه\n(أقر حمدان سلام الله ... من فضل وقل له)\n(يا فتى لست بحمد الله ... أخشى أن أمله)\n(ذاك أن الله قد أنهله ... الظرف وعله)\n(وذرا بيت رقاش ... وعلاها قد أحله)\n(إن شتم السفلة الكشخان ... ذي القرنين ضله)\n(ولو أن القلب هاجى ... عمرا يوما لغله)\n(ذاك أن الله قد أخزى ... ابن يحيى وأذله)\n(من يهاجي رجلا يستوعب ... الجردان كله)\n(ما يسيل الأير إلا ... أدخل الأير وبله)\n(وإذا عاين أيرا ... وافي الفيشة غله)\n(هذه قصة من قد ... جعل المردان شغله)","topic":"أخبار أبي النضير ونسبه","topicNo":123,"sp":1,"spl":"خالفه ابراهيم الموصلي في قوله ان الغناء على تقطيع العروض — شعره في طليقته","loc":2096},
{"id":"b123-5","bab":"الجزء 11","sec":"شعره في طليقته","page":"ج11 ص293","text":"حدثني عمى عن أبي العيناء عن أبي النضير قال دخلت على الفضل بن الربيع فقال هل أحدثت بعدي شيئا قلت نعم قلت أبياتا في امرأة تزوجتها وطلقتها لغير علة إلا بغضي لها وإنها لبيضاء بضة كأنها سبيكة فضة فقال لي وما قلت فيها فقلت قلت\n(رحلت سكينة بالطلاق ... فأرحت من غل الوثاق)\n(رحلت فلم تألم لها ... نفسي ولم تدمع مآقي)\n(لو لم تبن بطلاقها ... لأبنت نفسي بالإباق)\n(وشفاء ما لا تشتهيه ... النفس تعجيل الفراق)\nقال يا غلام الدواة والقرطاس فأتي بهما فأمرني فكتبت له الأبيات ثم قلت له أنت والله تبغض بنت أبي العباس الطوسي فقال اسكت أخزاك الله ثم ما لبث أن طلقها\n(ما بال عينك جائلا أقذاؤها ... شرقت بعبرتها وطال بكاؤها)\n(ذكرت عشيرتها وفرقة بينها ... فطوت لذلك غلة أحشاؤها)\nلشعر لعبد الله بن عمر العبلي والغناء لأبي سعيد مولى فائد رمل مطلق في مجرى الوسطى عن ابن المكي وذكره إسحاق في هذه الطريقة ولم ينسبه إلى أحد وقيل إنه من منحول يحيى الى أبي سعيد","topic":"أخبار أبي النضير ونسبه","topicNo":123,"sp":1,"spl":"خالفه ابراهيم الموصلي في قوله ان الغناء على تقطيع العروض — شعره في طليقته","song":1,"loc":2097},
{"id":"b124-1","bab":"الجزء 11","sec":"أخبار العبلي ونسبه","page":"ج11 ص294","text":"اسمه عبد الله بن عمر بن عبد الله بن علي بن عدي بن ربيعة بن عبد العزى بن عبد شمس بن عبد مناف ويكنى أبا عدي شاعر مجيد من شعراء قريش ومن مخضرمي الدولتين وله أخبار مع بني أمية وبني هاشم تذكر في غير هذا الموضع ويقال له عبد الله بن عمر العبلي وليس منهم لأن العبلات من ولد أمية الأصغر بن عبد شمس سموا بذلك لأن أمهم عبلة بنت عبيد بن حارك بن قيس بن مالك بن حنظلة بن مالك بن زيد مناة بن تميم وهؤلاء يقال لهم براجم بني تميم ولدت لعبد شمس بن عبد مناف أمية الأصغر وعبد أمية ونوفلا وأمه من بني عبد شمس فهؤلاء يقال لهم العبلات ولهم جميعا عقب أما أمية الأصغر فإنهم بالحجاز وهم بنو الحارث بن أمية منهم علي بن عبد الله بن الحارث ومنهم الثريا صاحبة ابن أبي ربيعة وأما بنو نوفل وعبد أمية فإنهم بالشام كثير وعبد العزى بن عبد شمس كان يقال له أسد البطحاء وإنما أدخلهم الناس في العبلات لما صار الأمر لبني أمية الأكبر وسادوا وعظم شأنهم في الجاهلية والإسلام وكثر أشرافهم فجعل سائر بني عبد شمس من لا يعلم قبيلة واحدة فسموهم أمية الصغرى ثم قيل لهم العبلات لشهرة الاسم وعلي بن عدي جد هذا الشاعر شهد مع عائشة يوم الجمل وله يقول شاعر بني ضبة لعنة الله عليه\n(يا رب اكبب بعلي جمله ... ولا تبارك في بعير حمله)\n(إلا علي بن عدي ليس له ... )\nميله إلى بني هاشم حرمه من عطاء الخلفاء فأما عبد الله بن عمر هذا الشاعر فكان في أيام بني أمية يميل إلى بني هاشم ويذم بني أمية ولم يكن منهم إليه صنع جميل فسلم بذلك في أيام بني العباس ثم خرج على المنصور في أيامه مع محمد بن عبد الله بن الحسن أخبرني الحسن بن علي عن أحمد بن زهير عن مصعب الزبيري قال العبلي عبد الله بن عمر بن عبد الله بن علي بن عدي بن ربيعة بن عبد العزى بن عبد شمس ويكنى أبا عدي وله أخبار كثيرة مع بني هاشم وبني أمية وقسم هشام بن عبد الملك أموالا وأجاز بجوائز فلم يعطه شيئا فقال\n(خس حظي أن كنت من عبد شمس ... ليتني كنت من بني مخزوم)\n(فأفوز الغداة منهم بسهم ... وأبيع الأب الشريف بلوم)\nلما استخلف المنصور كتب إلى السري بن عبد الله أن يوجه به إليه ففعل فلما قدم عليه قال له أنشدني ما قلت في قومك فاستعفاه فقال لا أعفيك فقال أعطني الأمان فأعطاه فأنشده\n(ما بال عنك جائلا أقذاؤها ... شرقت بعبرتها فطال بكاؤها)\nتى انتهى إلى قوله\n(فبنو أمية خير من وطىء الحصى ... شرفا وأفضل ساسة أمراؤها)\nفقال له اخرج عني لا قرب الله دارك فخرج حتى قدم المدينة فألفى محمد بن عبد الله بن حسن قد خرج فبايعه","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":0,"spl":"أخبار العبلي ونسبه","loc":2098,"partial":1},
{"id":"b124-2","bab":"الجزء 11","sec":"مدح السفاح فأكرمه","page":"ج11 ص296","text":"أخبرني عمي الكراني عن العمري عن العتبي عن أبيه قال كان أبو عدي الذي يقال له العبلي مجفوا في أيام بني مروان وكان منقطعا إلى بني هاشم فلما أفضت الدولة اليهم لم يبقوا على أحد من بني أمية وكان الأمر في قتلهم جدا إلا من هرب وطار على وجهه فخاف أبو عدي أن يقع به مكروه في تلك الفورة فتوارى وأخذ داود بن علي حرمه وماله فهرب حتى أتى أبا العباس السفاح فدخل عليه في غمار الناس متنكرا وجلس حجرة حتى تقوض القوم وتفرقوا وبقي أبو العباس مع خاصته فوثب إليه أبو عدي فوقف بين يديه وقال\n(ألا قل للمنازل بالستار ... سقيت الغيث من دمن قفار)\n(فهل لك بعدنا علم بسلمى ... وأتراب لها شبه الصوار)\n(أوانس لا عوابس جافيات ... عن الخلق الجميل ولا عواري)\n(وفيهن ابنة القصوي سلمى ... كهم النفس مفعمة الإزار)\n(تلوث خمارها بأحم جعد ... تضل الفاليات به المداري)\n(برهرهة منعمة نمتها ... أبوتها إلى الحسب النضار)\n(فدع ذكر الشباب وعهد سلمى ... فما لك منهما غير ادكار)\n(وأهد لهاشم غرر القوافي ... تنخلها بعلم وأختيار)\n(لعمرك إنني ولزوم نجد ... ولا ألقى حباء بني الخيار)\n(لكالبادي لأبرد مستهل ... بحوباء كبطن العير عار)\n(سأرحل رحلة فيها اعتزام ... وجد في رواح وابتكار)\n(إلى أهل الرسول غدت برحلي ... عذافرة ترامى بالصحاري)\n(تؤم المعشر الأبرار تبغي ... فكاكا للنساء من الإسار)\n(أيا أهل الرسول وصيد فهر ... وخير الواقفين على الجمار)\n(أتؤخذ نسوتي ويحاز مالي ... وقد جاهرت لو أغنى جهاري)\n(واذعر أن دعيت لعبد شمس ... وقد أمسكت بالحرم الصواري)\n(بنصرة هاشم شهرت نفسي ... بداري للعدا وبغير داري)\n(بقربى هاشم وبحق صهر ... لأحمد لفه طيب النجار)\n(ومنزل هاشم من عبد شمس ... مكان الجيد من عليا الفقار)\nقال له السفاح من أنت فانتسب له فقال له حق لعمري أعرفه قديما ومودة لا أجحدها وكتب له إلى داود بن علي بإطلاق من حبسه من أهله ورد أمواله عليه وإكرامه وأمر له بنفقة تبلغه المدينة","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":1,"spl":"مدح السفاح فأكرمه","loc":2099},
{"id":"b124-3","bab":"الجزء 11","sec":"عبد الله بن حسن يحسن وفادته وإكرامه","page":"ج11 ص298","text":"أخبرني أحمد بن محمد بن سعيد الهمداني قال حدثنا يحيى بن الحسن العلوي عن موسى بن عبد الله بن موسى بن عبد الله بن حسن قال حدثني أبي قال قال سعيد بن عقبة الجهني إني لعند عبد الله بن الحسن إذ أتاه آت فقال له هذا رجل يدعوك فخرجت فإذا أنا بأبي عدي الأموي الشاعر فقال أعلم أبا محمد فخرج إليه عبد الله بن حسن وابناه وقد ظهرت المسودة وهم خائفون فأمر له عبد الله بن حسن بأربعمائة دينار وابناه بينهما بأربعمائة دينار وهند بنت أبي عبيدة أمهما بمائتي دينار فخرج من عندهم بألف دينار وأخبرني حرمي عن الزبير وأخبرني الأخفش عن المبرد عن المغيرة ابن محمد المهلبي عن الزبير عن سليمان بن عياش السعدي قال جاء عبد الله بن عمر بن عبد الله العبلي إلى سويقة وهو طريد بني\nالعباس وذلك بعقب أيام بني أمية وابتداء خروج ملكهم إلى بني العباس فقصده عبد الله والحسن أبنا الحسن بسويقة فاستنشده عبد الله شيئا من شعره فأنشده فقال له أريد أن تنشدني شيئا مما رثيت به قومك فأنشده\n(تقول أمامة لما رأت ... نشوزي عن المضجع الأنفس)\n(وقلة نومي على مضجعي ... لدى هجعة الأعين النعس)\n(أبي ما عراك فقلت الهموم ... عرون أباك فلا تبلسي)\n(عرون أباك فحبسنه ... من الذل في شر ما محبس)\n(لفقد العشيرة إذ نالها ... سهام من الحدث المبئس)\n(رمتها المنون بلا نصل ... ولا طائشات ولا نكس)\n(بأسهمها الخالسات النفوس ... متى ما اقتضت مهجة تخلس)\n(فصرعاهم في نواحي البلاد ... تلقى بأرض ولم ترمس)\n(كريم أصيب وأثوابه ... من العار والذام لم تدنس)\n(وآخر قد طار خوف الردى ... وكان الهمام فلم يحسس)\n(فكم غادروا من بواكي العيون ... مرضى ومن صبية بؤس)\n(إذا ما ذكرنهم لم تنم ... لحر الهموم ولم تجلس)\n(يرجعن مثل بكاء الحمام ... في مأتم قلق المجلس)\n(فذاك الذي غالني فاعلمي ... ولا تسأليني فتستنحسي)\n(وأشياء قد ضفنني بالبلاد ... ولست لهن بمستحلس)\n(أفاض المدامع قتلى كدى ... وقتلى بكثوة لم ترمس)\n(وقتلى بوج وباللابتين ... من يثرب خير ما أنفس)\n(وبالزابيين نفوس ثوت ... وقتلى بنهر أبي فطرس)\n(أولئك قوم تداعت بهم ... نوائب من زمن متعس)\n(أذلت قيادي لمن رامني ... وألزقت الرغم بالمعطس)\n(فما أنس لا أنس قتلاهم ... ولا عاش بعدهم من نسي)\nال فلما أتى عليها بكى محمد بن عبد الله بن حسن فقال له عمه الحسن بن حسن بن علي عليهم السلام أتبكي على بني أمية وأنت تريد ببني العباس ما تريد فقال والله يا عم لقد كنا نقمنا على بني أمية ما نقمنا فما بنو العباس إلا أقل خوفا لله منهم وإن الحجة على بني العباس لأوجب منها عليهم ولقد كانت للقوم أخلاق ومكارم وفواضل ليست لأبي جعفر فوثب حسن وقال أعوذ بالله من شرك وبعث إلى أبي عدي بخمسين دينارا وأمر له عبد الله بن حسن بمثلها وأمر له كل واحد من محمد وإبراهيم ابنيه بخمسين خمسين وبعثت إليه أمهما هند بخمسين دينارا وكانت منفعته بها كثيرة فقال أبو عدي في ذلك\n(أقام ثوي بيت أبي عدي ... بخير منازل الجيران جارا)\n(تقوض بيته وجلا طريدا ... فصادف خير دور الناس دارا)\n(وإني إن نزلت بدار قوم ... ذكرتهم ولم أذمم جوارا)\nقالت هند لعبد الله وابنيها منه أقسمت عليكم إلا أعطيتموه خمسين دينارا أخرى فقد أشركني معكم في المدح فأعطوه خمسين دينارا أخرى عن هند\nأخبرني عيسى بن الحسين الوراق عن أبي أيوب المديني قال ذكر محمد ابن موسى مولى أبي عقيل قال قدم أبو عدي العبلي الطائف واليا من قبل محمد بن عبد الله بن حسن أيام خروجه على أبي جعفر ومعه أعراب من مزينة وجهينة وأسلم فأخذ الطائف وأتى محمد بن أبي بكر العمري حتى بايع وكان مع أبي عدي أحد عشر رجلا من ولد أبي بكر الصديق فقدمها بين أذان الصبح والإقامة فأقام بها ثلاثا ثم بلغه خروج الحسن بن معاوية من مكة فاستخلف على الطائف عبد الملك بن أبي زهير وخرج ليتلقى الحسن بالعرج فركب الحسن البحر ومضى أبو عدي هاربا على وجهه إلى اليمن فذلك حين يقول\n(هيجت للأجزاع حول عراب ... واعتاد قلبك عائد الأطراب)\n(وذكرت عهد معالم بلوى الثرى ... هيهات تلك معالم الأحباب)\n(هيهات تلك معالم من ذاهب ... أمسى بحوضى أو بحقل قباب)\n(قد حل بين أبارق ما إن له ... فيه من اخوان ولا أصحاب)\n(شطت نواه عن الأليف وساقه ... لقرى يمانية حمام كتاب)","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":2,"spl":"عبد الله بن حسن يحسن وفادته وإكرامه","loc":2100},
{"id":"b124-4","bab":"الجزء 11","sec":"عبد الله بن حسن يحسن وفادته وإكرامه","page":"ج11 ص298","text":"(يا أخت آل أبي عدي أقصري ... وذري الخضاب فما أوان خضاب)\n(أتخضبين وقد تخرم غالبا ... دهر أضر بها حديد الناب)\n(والحرب تعرك غالبا بجرانها ... وتعض وهي حديدة الأنياب)\n(أم كيف نفسك تستلذ معيشة ... أو تنقعين لها ألذ شراب)\nذكر العباس بن عيسى العقيلي عن هارون بن موسى الفروي عن سعيد ابن عقبة الجهني قال حضرت عبد الله بن عمر المكني أبا عدي الأموي ينشد عبد الله بن حسن قوله\n(أفاض المدامع قتلى كدى ... وقتلى بكثوة لم ترمس)\nال فرأيت عبد الله بن حسن وإن دموعه لتجري على خده وقد أخبرني محمد بن مزيد عن حماد عن أبيه عن الهيثم بن عدي عن أبي سعيد مولى فائد قال لما أتانا قتل عبد الله بن علي من قتل من بني أمية كنت أنا وفتى من ولد عثمان وأبو عدي العبلي متوارين في موضع واحد فلحقني من الجزع ما يلحق الرجل على عشيرته ولحق صاحبي كما لحقني فبكينا طويلا ثم تناولنا هذه القصيدة بيننا فقال كل واحد منا بعضها غير محصل ما لكل واحد منا فيها قال ثم أنشدنيها فأخذتها من فيه\n(تقول أمامة لما رأت ... نشوزي عن المضجع الأنفس)","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":3,"spl":"عبد الله بن حسن يحسن وفادته وإكرامه — قصيدته في مدح بني هاشم","loc":2101},
{"id":"b124-5","bab":"الجزء 11","sec":"قصيدته في مدح بني هاشم","page":"ج11 ص303","text":"أخبرني عيسى بن الحسين الوراق قال حدثنا محمد بن زكريا الغلابي عن ابن عائشة قال\nكان أبو عدي الأموي الشاعر يكره ما يجري عليه بنو أمية من ذكر علي بن أبي طالب صلوات الله عليه وسبه على المنابر ويظهر الإنكار لذلك فشهد عليه قوم من بني أمية بمكة بذلك ونهوه عنه فانتقل إلى المدينة وقال في ذلك\n(شردوا بي عند امتداحي عليا ... ورأوا ذاك في داء دويا)\n(فوربي لا أبرح الدهر حتى ... تختلى مهجتي بحبي عليا)\n(وبنيه لحب أحمد إني ... كنت أحببتهم بحبي النبيا)\n(حب دين لا حب دنيا وشر الحب ... حب يكون دنياويا)\n(صاغني الله في الذؤابة منهم ... لا زنيما ولا سنيدا دعيا)\n(عدويا خالي صريحا وجدي ... عبد شمس وهاشم أبويا)\n(فسواء علي لست أبالي ... عبشميا دعيت أم هاشميا)","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":3,"spl":"عبد الله بن حسن يحسن وفادته وإكرامه — قصيدته في مدح بني هاشم","loc":2102},
{"id":"b124-6","bab":"الجزء 11","sec":"هشام بن عبد الملك يفضل شعر بني مخزوم على شعره","page":"ج11 ص304","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن العتبي عن أبيه قال وفد أبو عدي الأموي إلى هشام بن عبد الملك وقد امتدحه بقصيدته التي يقول فيها\n(عبد شمس أبوك وهو أبونا ... لا نناديك من مكان بعيد)\n(والقرابات بيننا واشجات ... محكمات القوى بحبل شديد)\nأنشده إياها وأقام بباه مدة حتى حضر ببابه وفود قريش فدخل فيهم\nوأمر لهم بمال فضل فيه بني مخزوم أخواله وأعطى أبا عدي عطية لم يرضها فانصرف وقال\n(خس حظي أن كنت من عبد شمس ... ليتني كنت من بني مخزوم)\n(فأفوز الغداة فيهم بسهم ... وأبيع الأب الكريم بلوم)\nنى في البيتين المذكورين في هذا الخبر اللذين أولهما\n(عبد شمس أبوك وهو أبونا ... )\nبن جامع ولحنه ثاني ثقيل بإطلاق الوتر في مجرى الوسطى عن إسحاق وأول هذه القصيدة التي قالها في هشام\n(ليلتي من كنود بالغور عودي ... بصفاء الهوى من ام أسيد)\n(ما سمعنا ذاك الهوى ونسينا ... عهده فارجعي به ثم زيدي)\n(قد تولى عصر الشباب فقيدا ... رب جار يبين غير فقيد)\n(خلق الثوب من شباب ولبس ... وجديد الشباب غير جديد)\n(فاسرعنك الهموم حين تداعت ... بعلاة مثل الفنيق وخود)\n(عنتريس توفي الزمام بفعم ... مثل جذع الأشاءة المجرود)\n(وارم جوز الفلا بها ثم سمها ... عجرفي النجاء بالتوخيد)\n(وهشاما خليفة الله فاعمد ... واصر من مرة القوي الجليد)\n(تلقه محكم القوى أريحيا ... ذا قرى عاجل وسيب عتيد)\n(ملكا يشمل الرعية منه ... بأياد ليست بذات خمود)\n(أخضر الربع والجناب خصيب ... أفيح المستراد للمستريد)\n(ذكرت ناقتي البطاح فحنت ... حين أن وركت قبور ثمود)\n(قلت بعض الحنين يا ناق سيري ... نحو برق دعا لغيث عميد)\n(فأغذت في السير حتى أتتكم ... وهي قوداء في سواهم قود)\n(قد براها السرى إليك وسيري ... تحت حر الظهيرة الصيخود)\n(وطوى طائد العرائك منها ... غول بيد تجتابها بعد بيد)\n(وأتتكم حدب الظهور وكانت ... مسنمات ممرها بالكديد)\n(واطمأنت أرض الرصافة بالخصب ... ولم تلق رحلها بالصعيد)\n(نزلت بامرىء يرى الحمد غنما ... باذل متلف مفيد معيد)\n(بذل العدل في القصاص فأضحى ... لا يخاف الضعيف ظلم الشديد)\n(من بني النضر من ذرا منبت النضر ... بأورى زند وأكرم عود)\n(فهو كالقلب في الجوانح منها ... واسط سر جذمها والعديد)\n(بين مروان والوليد فبخ بخ ... للكريم المجيد غير الزهيد)\n(لو جرى الناس نحو غاية مجد ... لرهان في المحفل المشهود)\n(لعلاهم بسابغين من المجد ... على الناس طارف وتليد)\n(إنكم معشر أبى الله إلا ... أن تفوزوا بدرها المحشود)\n(لم ير الله معشرا من بني مروان ... أولى بالملك والتسويد)\n(قادة سادة ملوك بحار ... وبهاليل للقروم الصيد)\n(أريحيون ماجدون خضمون ... حماة عند اربداد الجلود)\n(يقطعون النهار بالرأي والحزم ... ويحيون ليلهم بالسجود)\n(أهل رفد وسؤدد وحياء ... ووفاء بالوعد والموعود)\n(ويرون الجوار من حرم الله فما الجار فيهم بوحيد ... )\n(لو بمجد نال الخلود قيل ... آل مروان فزتم بالخلود)\n(يا بن خير الأخيار من عبد شمس ... يا إمام الورى ورب الجنود)\n(عبد شمس أبوك وهو أبونا ... لا نناديك من مكان بعيد)\n(ثم جدي الأدنى وعمك شيخي ... وأبو شيخك الكريم الجدود)\n(فالقرابات بيننا واشجات ... محكمات القوى بحبل شديد)\n(فأثبني ثواب مثلك مثلي ... تلقني للثواب غير جحود)\n(إن ذا الجد من حبوت بود ... ليس من لا تود بالمجدود)\n(وبحسب امرىء من الخير يرجى ... كونه عند ظلك الممدود)\nأما قصيدته التي أولها\n(ما بال عينك جائلا أقذاؤها ... )\nهي التي فيها الغناء المذكور فإنه قالها في دولة بني أمية عند اختلاف كلمتهم ووقوع الفتنة بينهم يندب بينهم وفيها يقول\n(واعتادها ذكر العشيرة بالأسى ... فصباحها ثاب بها ومساؤها)\n(شركوا العدا في أمرهم فتفاقمت ... منها الفتون وفرقت أهواؤها)\n(ظلت هناك وما يعاتب بعضها ... بعضا فينفع ذا الرجاء رجاؤها)\n(إلا بمرهفة الظبات كأنها ... شهب تقل إذا هوت أخطاؤها)\n(وبعسل زرق يكون خضابها ... علق النحور إذا تفيض دماؤها)\n(فبذاكم أمست تعاتب بينها ... فلقد خشيت بأن يحم فناؤها)\n(ماذا أؤمل إن أمية ودعت ... وبقاء سكان البلاد بقاؤها)\n(أهل الرياسة والسياسة والندى ... وأسود حرب لا يخيم لقاؤها)\n(غيث البلاد هم وهم أمراؤها ... سرج يضيء دجى الظلام ضياؤها)","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":4,"spl":"هشام بن عبد الملك يفضل شعر بني مخزوم على شعره","loc":2103,"partialRef":{"sid":"b123-5","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b124-7","bab":"الجزء 11","sec":"هشام بن عبد الملك يفضل شعر بني مخزوم على شعره","page":"ج11 ص304","text":"(فلئن أمية ودعت وتتايعت ... لغواية حميت لها خلفاؤها)\n(ليودعن من البرية عزها ... ومن البلاد جمالها ورجاؤها)\n(ومن البلية أن بقيت خلافهم ... فردا تهيجك دورهم وخلاؤها)\n(لهفي علىحرب العشيرة بينها ... هلا نهى جهالها حلماؤها)\n(هلا نهى تنهى الغوي عن التي ... يخشى على سلطانها غوغاؤها)\n(وتقى وأحلام لها مضرية ... فيها إذا تدمى الكلوم دواؤها)\n(لما رأيت الحرب توقد بينها ... ويشب نار وقودها إذكاؤها)\n(نوهت بالملك المهيمن دعوة ... ورواح نفسي في البلاء دعاؤها)\n(ليرد ألفتها ويجمع أمرها ... بخيارها فخيارها رحماؤها)\n(فأجاب ربي في أمية دعوتي ... وحمى أمية أن يهد بناؤها)\n(وحبا أمية بالخلافة إنهم ... نور البلاد وزينها وبهاؤها)\n(فبنو أمية خير من وطىء الثرى ... شرفا وأفضل ساسة أمراؤها)\nهي قصيدة طويلة أقتصرت منها على ما ذكرته\n(مهلا ذريني فإني غالني خلقي ... وقد أرى في بلاد الله متسعا)\n(ما عضني الدهر إلا زادني كرما ... ولا أستكنت له إن خان أو خدعا)\nالشعر لأبي جلدة اليشكري من قصيدة يمدح بها مسمع بن مالك بن مسمع والغناء لعلويه رمل بالوسطى عن عمرو","topic":"أخبار العبلي ونسبه","topicNo":124,"sp":5,"spl":"هشام بن عبد الملك يفضل شعر بني مخزوم على شعره","song":1,"loc":2104},
{"id":"b125-2","bab":"الجزء 11","sec":"أخبار أبي جلدة ونسبه — انقلب على الحجاج بعد أن كان حليفا له","page":"ج11 ص310 – ج11 ص311","text":"أبو جلدة بن عبيد بن منقذ بن حجر بن عبيد الله بن مسلمة بن حبيب بن عدي بن جشم بن غنم بن حبيب بن كعب بن يشكر بن بكر بن وائل شاعر إسلامي من شعراء الدولة الأموية ومن ساكني الكوفة وكان ممن خرج مع ابن الأشعث فقتله الحجاج\nأخبرني بخبره في جملة ديوان شعره محمد بن العباس اليزيدي وقرأته عليه قال حدثني عمي عبد الله قال حدثني محمد بن حبيب وأخبرني به علي ابن سليمان الأخفش أيضا عن الحسن بن الحسن اليشكري عن ابن الأعرابي قال كان أبو جلدة اليشكري من أخص الناس بالحجاج حتى إنه بعثه وبعث معه عبد الله بن شداد بن الهادي الليثي إلى عبد الله بن جعفر بن أبي طالب عليه السلام فخطب الحجاج منه ابنته أم كلثوم ثم خرج بعد ذلك مع ابن الأشعث وكان من أشد الناس تحريضا على الحجاج فلما أتي الحجاج\nبرأسه ووضع بين يديه مكث ينظر إليه طويلا ثم قال كم من سر أودعته في هذا الرأس فلم يخرج حتى أتيت به مقطوعا فلما كان يوم الزاوية خرج أبو جلدة بين الصفين ثم أقبل على أهل الكوفة فأنشدهم قصيدته التي يقول فيها\n(فقل للحواريات يبكين غيرنا ... ولا تبكنا إلا الكلاب النوابح)\n(بكين إلينا خشية أن تبيحها ... رماح النصارى والسيوف الجوارح)\n(بكين لكيما يمنعوهن منهم ... وتأبى قلوب أضمرتها الجوانح)\n(وناديننا أين الفرار وكنتم ... تغارون أن تبدو البرى والوشائح)\n(أأسلمتمونا للعدو على القنا ... إذا أنتزعت منها القرون النواطح)\n(فما غار منكم غائر لحليلة ... ولا عزب عزت عليه المناكح)\nال فلما أنشدهم هذه الأبيات أنفوا وثاروا فشدوا شدة تضعضع لهم عسكر الحجاج وثبت لهم الحجاج وصاح بأهل الشأم فتراجعوا وثبتوا فكانت الدائرة له فجعل يقتل الناس بقية يومه حتى صاح به رجل والله يا حجاج لئن كنا قد أسأنا في الذنب لما أحسنت في العفو ولقد خالفت الله فينا وما أطعته فقال له وكيف ويلك قال لأن الله تعالى يقول ( فإذا لقيتم الذين كفروا فضرب الرقاب حتى إذا أثخنتموهم فشدوا الوثاق فإما منا بعد وإما\nفداء حتى تضع الحرب أوزارها\nوقد قتلت فأثخنت حتى تجاوزت الحد فأسر ولا تقتل ثم قال أو أمنن فقال أولى لك ألا كان هذا الكلام منك قبل هذا الوقت ثم نادى برفع السيف وأمن الناس جميعا قال ابن حبيب قال أبن الأعرابي فبلغني أن الحجاج قال يوما لجلسائه ما حرض علي أحد كما حرض أبو جلدة فإنه نزل على سرحة في وسط عسكر لابن الأشعث ثم نزع سراويله فوضعه وسلح فوقه والناس ينظرون إليه فقالوا له ما لك ويلك أجننت ما هذا الفعل قال كلكم قد فعلتم مثل هذا إلا أنكم سترتموه وأظهرته فشتموه وحملوا علي فما أنساهم وهو يقدمهم ويرتجز\n(نحن جلبنا الخيل من زرنجا ... ما لك يا حجاج منا منجى)\n(لتبعجن بالسيوف بعجا ... أو لتفرن فذاك أحجى)\nوالله لقد كاد أهل الشأم يومئذ يتضعضعون لولا أن ا لله تعالى أيد بنصره قال وقال أبو جلدة يومئذ\n(أيا لهفي ويا حزني جميعا ... ويا غم الفؤاد لما لقينا)\n(تركنا الدين والدنيا جميعا ... وخلينا الحلائل والبنينا)\n(فما كنا أناسا أهل دين ... فنصبر للبلاء إذا بلينا)\n(ولا كنا أناسا أهل دنيا ... فنمنعها وإن لم نرج دينا)\n(تركنا دورنا لطغام عك ... وأنباط القرى والأشعرينا)\nال ابن حبيب وكان أبو جلدة مع القعقاع بن سويد المنقري بسجستان فذم منه بعض ما عامله به فقال فيه\n(ستعلم أن رأيك رأي سوء ... إذا ظل الإمارة عنك زالا)\n(وراح بنو أبيك ولست فيهم ... بذي ذكر يزيدهم جمالا)\n(هناك تذكر الأسلاف منهم ... إذا الليل القصير عليك طالا)\nقال له القعقاع ومتى يطول علي الليل القصير قال إذا نظرت إلى السماء مربعة فلما عزل وحبس أخرج رأسه ليلة فنظر فإذا هو لا يرى السماء إلا بقدر تربيع السجن فقال هذا والله الذي حذرنيه أبو جلدة","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":0,"spl":"أخبار أبي جلدة ونسبه — انقلب على الحجاج بعد أن كان حليفا له","loc":2105},
{"id":"b125-3","bab":"الجزء 11","sec":"مدح مسمع بن مالك حين ولي سجستان ورثاه حين وفاته","page":"ج11 ص314","text":"قال وولي مسمع بن مالك سجستان وكان مكث أبي جلدة بها فخرج إليه فتلقاه ومدحه بقصيدته التي أولها\n(بانت سعاد وأمسى حبلها أنقطعا ... وليت وصلا لها من حبلها رجعا)\n(شطت بها غربة زوراء نازحة ... فطارت النفس من وجد بها قطعا)\n(ما قرت العين إذ زالت فينفعها ... طعم الرقاد إذا ما هاجع هجعا)\n(منعت نفسي من روح تعيش به ... وقد أكون صحيح الصدر فأنصدعا)\n(غدت تلوم على ما فات عاذلتي ... وقبل لومك ما أغنيت من منعا)\n(مهلا ذريني فإني غالني خلقي ... وقد أرى في بلاد الله متسعا)\n(فخري تليد وما أنفقت أخلفه ... سيب الإله وخير المال ما نفعا)\n(ما عضني الدهر إلا زادني كرما ... ولا أستكنت له إن خان أو خدعا)\n(ولا تلين على العلات معجمتي ... في النائبات إذا ما مسني طبعا)\n(ولا تلين من عودي غمائزه ... إذا المغمز منها لان أو خضعا)\n(ولا أخاتل رب البيت غفلته ... ولا أقول لشيء فات ما صنعا)\n(إني لأمدح أقواما ذوي حسب ... لم يجعل الله في أقوالهم قذعا)\n(الطيبين على العلات معجمة ... لو يعصر المسك من أطرافهم نبعا)\n(بني شهاب بها أعني وإنهم ... لأكرم الناس أخلاقا ومصطنعا)\nال فوصله مسمع بن مالك وحمله وكساه وولاه ناشيتكين وكان مكتبه قال ثم توفي مسمع بن مالك بسجستان فقال أبو جلدة يرثيه\n(أقول للنفس تأساء وتعزية ... قد كان من مسمع في مالك خلف)\n(يا مسمع الخير من ندعو إذا نزلت ... إحدى النوائب بالأقوام واختلفوا)\n(يا مسمعا لعراق لا زعيم لها ... بمن ترى يؤمن المستشرف النطف)\n(تلك العيون بحيث المصر سادمة ... تبكيك إذ غالك الأكفان والجرف)\n(قد وسدوك يمينا غير موسدة ... وبذل جود لما أودى بك التلف)\n(كنت الشهاب الذي يرمى العدو به ... والبحر منه سجال الجود تغترف)\nال ابن حبيب عن ابن الأعرابي قال كان أبو جلدة ينادم شقيق بن سليط بن بديل السدوسي أخا بسطام بن سليط وكان لهما أخ يقال له ثعلبة بن سليط وكان ثقيلا بخيلا مبغضا وكان يطفل عليهم ويؤذيهم فقال فيه أبو جلدة\n(أحب على لذاذتنا شقيقا ... وأبغض مثل ثعلبة الثقيل)\n(له غم على الجلساء مؤذ ... نوافله إذا شربوا قليل)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":1,"spl":"مدح مسمع بن مالك حين ولي سجستان ورثاه حين وفاته — مسمع بن مالك يكرمه على شعره","loc":2106},
{"id":"b125-4","bab":"الجزء 11","sec":"مسمع بن مالك يكرمه على شعره","page":"ج11 ص316","text":"قال ابن حبيب عن ابن الأعرابي وفرق مسمع بن مالك في عشيرته بني قيس بن ثعلبة عطايا كثيرة وقربهم وجفا سائر بطون بكر بن وائل فقال أبو جلدة\n(إذا نلت مالا قلت قيس عشيرتي ... تجور علينا عامدا في قضائكا)\n(وإن كانت الأخرى فبكر بن وائل ... بزعمك يخشى داؤها بدوائكا)\n(هنالك لا نمشي الضراء إليكم ... بني مسمع إنا هناك أولئكا)\n(عسى دولة الذهلين يوما ويشكر ... تكسر علينا سبغة من عطائكا)\nال فبعث إليه مسمع فترضاه ووصله وفرق في سائر بطون بكر بن وائل على جذمين جذم يقال له الذهلان وجذم يقال له اللهازم فالذهلان بنو شيبان بن ثعلبة بن يشكر بن وائل وبنو ضبيعة بن ربيعة واللهازم قيس ابن ثعلبة وتيم اللات بن ثعلبة وعجل بن لجيم وعنزة بن أسد بن ربيعة قال الفرزدق\n(وأرضى بحكم الحي بكر بن وائل ... إذا كان في الذهلين أو في اللهازم)\nال وقد دخل بنو قيس بن عكابة مع إخوتهم بني قيس بن ثعلبة بن عكابة وأما حنيفة فلم تدخل في شيء من هذا لانقطاعهم عن قومهم باليمامة في وسط دار مضر وكانوا لا ينصرون بكرا ولا يستنصرونهم فلما جاء الإسلام ونزل الناس مع بني حنيفة ومع بني عجل بن لجيم فتلهزموا ودخل معهم حلفاؤهم بنو مازن بن جدي بن مالك بن صعب بن علي فصاروا جميعا في اللهازم وقال موسى بن جابر الحنفي السحيمي بعد ذلك في الإسلام\n(وجدنا أبانا كان حل ببلدة ... سوى بين قيس قيس عيلان والفزر)\n(فلما نأت عنا العشيرة كلها ... أقمنا وحالفنا السيوف على الدهر)\n(فما أسلمتنا بعد في يوم وقعة ... ولا نحن أغمدنا السيوف على وتر)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":1,"spl":"مدح مسمع بن مالك حين ولي سجستان ورثاه حين وفاته — مسمع بن مالك يكرمه على شعره","loc":2107},
{"id":"b125-5","bab":"الجزء 11","sec":"هجا جاره سيفا لأنه كان يعربد","page":"ج11 ص318","text":"وقال ابن حبيب عن ابن الأعرابي قال كان لأبي جلدة بسجستان جار يقال له سيف من بني سعد وكان يشرب الخمر ويعربد على أبي جلدة فقال يهجوه\n(قل لذوي سيف وسيف ألستم ... أقل بني سعد حصادا ومزرعا)\n(كأنكم جعلان دار مقامة ... على عذرات الحي أصبحن وقعا)\n(لقد نال سيف في سجستان نهزة ... تطاول منها فوق ما كان إصبعا)\n(أصاب الزنا والخمر حتى لقد نمت ... له سرة تسقى الشراب المشعشعا)\n(فلولا هوان الخمر ما ذقت طعمها ... ولا سقت إبريقا بكفك مترعا)\n(كما لم يذقها أن تكون عزيزة ... أبوك ولم يعرض عليها فيطمعا)\n(وكان مكان الكلب أو من ورائه ... إذا ما المغني للذاذة أسمعا)\nال ابن حبيب وكان أبو جلدة قد استعمله القعقاع بن سويد حين تولى سجستان على بست والرخج فأرجف الناس بالقعقاع وأرجف به أبو جلدة\nمعهم وكتب القعقاع إليه يتهدده فكتب إليه أبو جلدة\n(يهددني القعقاع في غير كنهه ... فقلت له بكر إذا رمتني ترسي)\n(كأنا وإياكم إذا الحرب بيننا ... أسود عليها الزعفران مع الورس)\n(ترى كمصابيح الدياجي وجوهنا ... إذا ما لقينا والهرقلية الملس)\n(هناك السعود السانحات جرت لنا ... وتجري لكم طير البوارح بالنحس)\n(وما أنت يا قعقاع إلا كمن مضى ... كأنك يوما قد نقلت إلى الرمس)\n(أظن بغال البرد تسري إليكم ... به غطفانيا وإلا فمن عبس)\n(وإلا فبالبسال يا لك إن سرت ... به غير مغموز القناة ولا نكس)\n(فعمالنا أوفى وخير بقية ... وعمالكم أهل الخيانة واللبس)\n(وما لبني عمرو علي هوادة ... ولا للرباب غير تعس من التعس)\nال فلما انتهت هذه القصيدة إلى القعقاع وجه برسول إلى أبي جلدة وقال انظر فإن كان كتب هذا الكتاب بالغداة فاعزله وإن كان كتبه بالليل فأقرره على عمله ولا تعزله ولا تضربه وكان أبو جلدة صاحب شراب فقال للرسول والله ما كتبته إلا بالعشي فسأله البينة على ذلك فأتاه بأقوام شهدوا له بما قال فأقره على عمله وانصرف عنه","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":2,"spl":"هجا جاره سيفا لأنه كان يعربد — تشبيبه ببنت رجل من الدهاقين","loc":2108},
{"id":"b125-6","bab":"الجزء 11","sec":"تشبيبه ببنت رجل من الدهاقين","page":"ج11 ص320","text":"قال ابن حبيب ومر أبو جلدة بقصر من قصور بست ينزله رجل من الدهاقين فرأى ابنته تشرف من أعلى القصر فأنشأ يقول\n(إن في القصر ذي الخبا بدر تم ... حسن الدل للفؤاد مصيبا)\n(ولعا بالخلوق يأرج منه ... ريح رند إذا استقل منيبا)\n(يلبس الخز والمطارف والقز ... وعصبا من اليماني قشيبا)\n(ورأيت الحبيب يبرز كفا ... ما رآه المحب إلا خضيبا)\nبلغ ذلك من قوله الدهقان فأهدى له وبره وسأله ألا يذكر ابنته في شعر بعد ذلك قال ابن حبيب ولحق أبا جلدة ضيم من بعض الولاة فهتف بقومه فلم يقدروا على منعه منه ولا معونته رهبة للسلطان فهتف بأعلى صوته يا مسمع ابن مالك يا أمير بن أحمر ثم أنشأ يقول\n(ولما أن رأيت سراة قومي ... سكوتا لا يثوب لهم زعيم)\n(هتفت بمسمع وصدى أمير ... وقبر معمر تلك القروم)\nال فأبكى جميع من حضر وقاموا جميعا إلى الوالي فسألوه في أمره حتى كف عنه قال وأمير بن أحمر رجل من بني يشكر وكان سيدا جوادا\nوفيه يقول زياد الأعجم\n(لولا أمير هلكت يشكر ... ويشكر هلكى على كل حال)\nال أبن الأعرابي كان أمير بن أحمر واليا على خراسان في أيام معاوية ومعمر الذي عناه أبو جلدة معمر بن شمير بن عامر بن جبلة بن ناعب بن صريم وكان أمير سجستان وكان سيدا شريفا","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":2,"spl":"هجا جاره سيفا لأنه كان يعربد — تشبيبه ببنت رجل من الدهاقين","loc":2109},
{"id":"b125-7","bab":"الجزء 11","sec":"شعره بعد ان ابت خليعة بنت صعب الزواج منه","page":"ج11 ص321","text":"وقال خطب أبو جلدة أمرأة من بني عجل يقال لها خليعة بنت صعب فأبت أن تتزوجه وقالت أنت صعلوك فقير لا تحفظ مالك ولا تلفي شيئا إلا أنفقته في الخمر وتزوجت غيره فقال أبو جلدة في ذلك\n(لما خطبت إلى خليعة نفسها ... قالت خليعة ما أرى لك مالا)\n(أودى بمالي يا خليع تكرمي ... وتخرقي وتحملي الأثقالا)\n(إني وجدك لو شهدت مواقفي ... بالسفح يوم أجلل الأبطالا)\n(سيفي لسرك أن تكوني خادما ... عندي إذا كره الكماة نزالا)\nالغناء لإبراهيم الموصلي ثاني ثقيل بالوسطى عن الهشامي من كتاب علي بن يحيى قال أبو سعيد السكري وعمر بن سعيد صاحب الواقدي إن أبا جلدة كان في قرية من قرى بست يقال لها الخيزران ومعهم عمرو ابن صوحان أخو صعصعة في جماعة يتحدثون ويشربون إذ قام أبو جلدة ليبول فضرط وكان عظيم البطن فتضاحك القوم منه فسل سيفه وقال لأضربن من لا يضرط في مجلسه هذا ضربة بسيفي أمني تضحكون لا أم لكم فما زال حتى ضرطوا جميعا غير عمرو بن صوحان فقال له قد علمت أن عبد القيس لا تضرط ولك بدلها عشر فسوات قال لا والله أو تفصح بها فجعل عمرو يجثي وينحني فلا يقدر عليها فتركه وقال أبو جلدة في ذلك\n(أمن ضرطة بالخيزران ضرطتها ... تشدد مني دارة وتلين)\n(فما هو إلا السيف أو ضرطة لها ... يثور دخان ساطع وطنين)\nال ولعمرو بن صوحان يقول أبو جلدة اليشكري وطالت صحبته إياه فلم يظفر منه بشيء\n(صاحبت عمرا زمانا ثم قلت له ... الحق بقومك يا عمرو بن صوحانا)\n(فإن صبرت فإن الصبر مكرمة ... وإن جزعت فقد كان الذي كانا)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":3,"spl":"شعره بعد ان ابت خليعة بنت صعب الزواج منه","song":1,"loc":2110},
{"id":"b125-8","bab":"الجزء 11","sec":"تهاجى هو وزياد الأعجم","page":"ج11 ص322","text":"قال ابن سعيد وحدثني أبو صالح قال بلغ أبا جلدة أن زيادا الأعجم هجا بني يشكر فقال فيه\n(لا تهج يشكر يا زياد ولا تكن ... غرضا وأنت عن الأذى في معزل)\n(واعلم بأنهم إذا ما حصلوا ... خير وأكرم من أبيك الأعزل)\n(لولا زعيم بني المعلى لم نبت ... حتى نصبحكم بجيش جحفل)\n(تمشي الضراء رجالهم وكأنهم ... أسد العرين بكل عضب منصل)\n(فاحذر زياد ولا تكن ذا تدرأ ... عند الرجال ونهزة للختل)\nقال ابن حبيب كان سليمان بن عمرو بن مرثد البكري صديقا لأبي جلدة وكان فارسا شجاعا وقتله ابن خازم لشيء بلغه فأنكره وفيه يقول أبو جلدة\n(إذا كنت مرتادا نديما مكررا ... نماه سراة من سراة بني بكر)\n(فلا تعد ذا العليا سليمان عامدا ... تجد ماجدا بالجود منشرح الصدر)\n(كريما على علاته يبذل الندى ... ويشربها صهباء طيبة النشر)\n(معتقة كالمسك يذهب ريحها الزكام ... وتدعو المرء للجود بالوفر)\n(وتترك حاسي الكأس منها مرنحا ... يميد كما ماد الأثيم من السكر)\n(تلوح كعين الديك ينزو حبابها ... إذا مزجت بالماء مثل لظى الجمر)\n(فتلك إذا نادمت من آل مرثد ... عليها نديما ظل يهرف بالشعر)\n(يغنيك تارات وطورا يكرها ... عليك بحياك الإله ولا يدري)\n(تعود ألا يجهل الدهر عندها ... وأن يبذل المعروف في العسر واليسر)\n(وإن سليمان بن عمرو بن مرثد ... تألى يمينا أن يريش ولا يبري)\n(فهمته بذل الندى وأبتنا العلا ... وضرب طلى الأبطال في الحرب بالبتر)\n(وفي الأمن لا ينفك يحسو مدامة ... إذا ما دجا ليل إلى وضح الفجر)\nقال فلما بلغت سليمان هذه الأبيات قال هجاني أخي وما تعمد لكنه يرى أن الناس جميعا يؤثرون الصهباء كما يؤثرها هو ويشربونها كما يشربها وبلغ قوله أبا جلدة فأتاه فاعتذر إليه وحلف أنه لم يتعمد بذلك ما يكرهه وينكره قال قد علمت بذلك وشهدت لك به قبل أن تعتذر وقبل عذره وقال ابن حبيب سأل أبو جلدة الحضين بن المنذر الرقاشي شيئا فلم يعطه إياه وقال لا أعطيه ما يشرب به الخمر فقال أبو جلدة يهجوه\n(يا يوم بؤس طلعت شمسه ... بالنحس لا فارقت رأس الحضين)\n(إن حضينا لم يزل باخلا ... مذ كان بالمعروف كز اليدين)\nبلغ الحضين قول أبي جلدة فقال يجيبه\n(عض أبو جلدة من أمه ... معترضا ما جاوز الأسكتين)\n(بظرا طويلا غاشيا رأسه ... أعقف كالمنجل ذا شعبتين)\nقال أبو جلدة في حضين أيضا\n(لعمرك إني يوم أسند حاجتي ... إليك أبا ساسان غير مسدد)\n(فلا عالم بالغيب من أين ضره ... ولا خائف بث الأحاديث في غد)\n(فليت المنايا حلقت بي صروفها ... فلم أطلب المعروف عند المصرد)\n(فلو كنت حرا يا حضين بن منذر ... لقمت بحاجاتي ولم تتبلد)\n(تجهمتني خوف القرى واطرحتني ... وكنت قصير الباع غير المقلد)\n(ولم تعد ما قد كنت أهلا لمثله ... من اللؤم يابن المستذل المعبد)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":4,"spl":"تهاجى هو وزياد الأعجم — هجا الحضين بن المنذر فتهدده بنو رقاش","loc":2111},
{"id":"b125-9","bab":"الجزء 11","sec":"هجا الحضين بن المنذر فتهدده بنو رقاش","page":"ج11 ص325","text":"قال فبلغ أبا جلدة أن بني رقاش تهددوه بالقتل لهجائه الحضين بن منذر فقال\n(تهددني جهلا رقاش وليتني ... وكل رقاشي على الأرض في الحبل)\n(فباست حضين واست أم رمت به ... فبئس محل الضيف في الزمن المحل)\n(وإن أنا لم أترك رقاش وجمعهم ... أذل على وطء الهوان من النعل)\n(فشلت يداي واتبعت سوى الهدى ... سبيلا ولا وفقت للخير والفضل)\n(عظام الخصى ثط اللحى معدن الخنا ... مباخيل بالأزواد في الخصب والأزل)\n(إذا أمنوا ضراء دهر تعاظلوا ... عظال الكلاب في الدجنة والوبل)\n(وإن عضهم دهر بنكبة حادث ... فأخور عيدانا من المرخ والأثل)\n(أسود شرى وسط الندي ثعالب ... إذا خطرت حرب مراجلها تغلي)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":4,"spl":"تهاجى هو وزياد الأعجم — هجا الحضين بن المنذر فتهدده بنو رقاش","loc":2112},
{"id":"b125-10","bab":"الجزء 11","sec":"وصفه لدهقانة كان يختلف إليها","page":"ج11 ص326","text":"أخبرني محمد بن يحيى الصولي قال حدثني محمد بن عبد الله الأصبهاني المعروف بالحزنبل عن عمرو بن أبي عمرو الشيباني عن أبيه قال عشق أبو جلدة اليشكري دهقانة ببست وكان يختلف إليها ويكون عندها دائما وقال فيها\n(وكأس كأن المسك فيها حسوتها ... ونازعنيها صاحب لي ملوم)\n(أغر كأن البدر سنة وجهه ... له كفل واف وفرع ومبسم)\n(يضيء دجى الظلماء رونق خده ... وينجاب عنه الليل والليل مظلم)\n(وثديان كالحقين والمتن مدمج ... وجيد عليه نسق در منظم)\n(وبطن طواه الله طيا ومنطق ... رخيم وردف نيط بالحقو مفأم)\n(به تبلتني واستبتني وغادرت ... لظى في فؤادي نارها تتضرم)\n(أبيت بها أهذي إذا الليل جنني ... وأصبح مبهوتا فما أتكلم)\n(فمن مبلغ قومي الدنا أن مهجتي ... تبين لئن بانت ألا تتلوم)\n(وعهدي بها والله يصلح بالها ... تجود على من يشتهيها وتنعم)\n(فما بالها ضنت علي بودها ... وقلبي لها يا قوم عان متيم)\nال فلما بلغها الشعر سألت عن تفسيره ففسر لها فلما انتهى المفسر إلى هذين البيتين الأخيرين غضبت فقالت أنا زانية كما زعم إن كلمته كلمة أبدا أو كلما اشتهاني إنسان بذلت له نفسي وأنعمت من روحي إذا أي أنا إذا زانية فصرمته فلم يقدر عليها وعذب بها زمانا ثم قال فيها لما يئس منها\n(صحا قلبي وأقصر بعد غي ... طويل كان فيه من الغواني)\n(بأن قصد السبيل فباع جهلا ... برشد وارتجى عقبى الزمان)\n(وخاف الموت واعتصم ابن حجر ... من الحب المبرح بالجنان)\n(وقدما كان معترما جموحا ... إلى لذاته سلس العنان)\n(وأقلع بعد صبوته وأضحى ... طويل الليل يهرف بالقران)\n(ويدعو الله مجتهدا لكيما ... ينال الفوز من غرف الجنان)\nال ابن حبيب قال أبو عبيدة كان يزيد بن المهلب يتهم بالنساء فقال فيه أبو جلدة\n(إذا اعتكرت ظلماء ليل ونومت ... عيون رجال واستلذوا المضاجعا)\n(سما نحو جار البيت يستام عرسه ... يزيد دبيبا للمعاناة قابعا)\n(وإن أمكنته جارة البيت أو رنت ... إليه أتاها بعد ذلك طائعا)\nشاعت الأبيات ورواها الناس لقتادة بن معرب فقال أبو جلدة\n(أبا خالد ركني ومن أنا عبده ... لقد غالني الأعداء عمدا لتغضبا)\n(فإن كنت قلت اللذ أتاك به العدا ... فشلت يدي اليمنى وأصبحت أعضبا)\n(ولا زلت محمولا علي بلية ... وأمسيت شلوا للسباع متربا)\n(فلا تسمعن قول العدا وتبينن ... أبا خالد عذرا وإن كنت مغضبا)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":5,"spl":"وصفه لدهقانة كان يختلف إليها — مناقضته لقتادة بن معرب","loc":2113},
{"id":"b125-11","bab":"الجزء 11","sec":"البعيث يحيل رأيه فيه إلى قتادة بن معرب","page":"ج11 ص328","text":"وقال ابن حبيب قال رجل للبعيث أي رجل هو أبو جلدة فقال قتادة بن معرب أعرف به حيث يقول\n(إن أبا جلدة من سكره ... لا يعرف الحق من الباطل)\n(يزداد غيا وانهماكا ولا ... يسمع قول الناصح العاذل)\n(أعيا أبوه وبنو عمه ... وكان في الذروة من وائل)\n(فليته لم يك من يشكر ... فبئس خدن الرجل العاقل)\n(أعمى عن الحق بصير بما ... يعرفه كل فتى جاهل)\n(يصبح سكران ويمسي كما ... أصبح لا أسقي من الوابل)\n(شد ركاب الغي ثم اغتدى ... إلى التي تجلب من بابل)\n(فالسجن إن عاش له منزل ... والسجن دار العاجز الخامل)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":5,"spl":"وصفه لدهقانة كان يختلف إليها — مناقضته لقتادة بن معرب","loc":2114},
{"id":"b125-12","bab":"الجزء 11","sec":"مناقضته لقتادة بن معرب","page":"ج11 ص329","text":"وقال أبو جلدة يجيبه\n(قبحت لو كنت امرأ صالحا ... تعرف ما الحق من الباطل)\n(كففت عن شتمي بلا إحنة ... ولم تورط كفة الحابل)\n(لكن أبت نفسك فعل النهى ... والحزم والنجدة والنائل)\n(فتحت لي بالشتم حتى بدا ... مكنون غش في الحشا داخل)\n(فاجهد وقل لا تترك جاهدا ... شتم امرىء ذي نجدة عاقل)\n(تعذلني في قهوة مزة ... درياقة تجلب من بابل)\n(ولو رآها خر من حبها ... يسجد للشيطان بالباطل)\n(يا شر بكر كلها محتدا ... ونهزة المختلس الآكل)\n(عرضك وفره ودعني وما ... أهواه يا أحمق من باقل)\nقال ابن حبيب كان أبو جلدة يشرب مع ابن عم له من بكر بن وائل فسكر نديمه فعربد عليه وشتمه فاحتمله أبو جلدة وسقاه حتى نام وقال في ذلك\n(أبى لي أن ألحى نديمي إذا انتشى ... وقال كلاما سيئا لي على السكر)\n(وقاري وعلمي بالشراب وأهله ... وما نادم القوم الكرام كذي الحجر)\n(فلست بلاح لي نديما بزلة ... ولا هفوة كانت ونحن على الخمر)\n(عركت بجنبي قول خدني وصاحبي ... ونحن على صهباء طيبة النشر)\n(فلما تمادى قلت خذها عريقة ... فإنك من قوم جحاجحة زهر)\n(فما زلت أسقيه وأشرب مثل ما ... سقيت أخي حتى بدا وضح الفجر)\n(وأيقنت أن السكر طار بلبه ... فأغرق في شتمي وقال وما يدري)\nولاك لسانا كان إذ كان صاحيا يقلبه في كل فن من الشعر","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":5,"spl":"وصفه لدهقانة كان يختلف إليها — مناقضته لقتادة بن معرب","loc":2115},
{"id":"b125-13","bab":"الجزء 11","sec":"أبى رجل من قومه أن ينادمه فقال شعرا","page":"ج11 ص330","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن عاصم بن الحدثان قال كان أبو جلدة اليشكري قد خرج إلى تستر في بعث فشرب بها في حانة مع رجل من قومه كان ساكنا بها ثم خرج عنها بعد ذلك وعاد إلى بست\nوالرخج وكان مكتبه هناك فأقام بها مدة ثم لقي بها ذلك الرجل الذي نادمه بتستر ذات يوم فسلم عليه ودعاه إلى منزله فأكلا ثم دعا بالشراب ليشربا فامتنع الرجل وقال إني قد تركتها لله فقال أبو جلدة وهو يشرب\n(ألا رب يوم لي ببست وليلة ... ولا مثل أيامي المواضي بتستر)\n(غنيت بها أسقي سلاف مدامة ... كريم المحيا من عرانين يشكر)\n(نبادر شرب الراح حتى نهرها ... وتتركنا مثل الصريع المعفر)\n(فذلك دهر قد تولى نعيمه ... فأصبحت قد بدلت طول التوقر)\n(فراجعني حلمي وأصبحت منهج الشراب ... وقدما كنت كالمتحير)\n(وكل أوان الحق أبصرت قصده ... فلست وإن نبهت عنه بمقصر)\n(سأركض في التقوى وفي العلم بعدما ... ركضت إلى أمر الغوي المشهر)\n(وبالله حولي واحتيالي وقوتي ... ومن عنده عرفي الكثير ومنكري)\nأخبرني محمد بن العباس اليزيدي قال حدثنا محمد بن الحارث المدائني قال مر مسمع بن مالك بأبي جلدة فوثب إليه وأنشأ يقول\n(يا مسمع بن مالك يا مسمع ... أنت الجواد والخطيب المصقع)\n(فاصنع كما كان أبوك يصنع ... )\nقال له رجل كان جالسا هناك إن قبل منك والله يا أبا جلدة ناك أمه فقال له وكيف ذلك ويحك قال لأنك أمرته أن يصنع كما كان أبوه يصنع","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":6,"spl":"أبى رجل من قومه أن ينادمه فقال شعرا — هجا مقاتل بن مسمع لأنه لم يعطه","loc":2116,"partial":1},
{"id":"b125-14","bab":"الجزء 11","sec":"هجا مقاتل بن مسمع لأنه لم يعطه","page":"ج11 ص332","text":"وقال أبو عمرو الشيباني كان مسمع بن مالك يعطي أبا جلدة فقال فيه\n(يسعى أناس لكيما يدركوك ولو ... خاضوا بحارك أو ضحضاحها غرقوا)\n(وأنت في الحرب لا رث القوى برم ... عند اللقاء ولا رعديدة فرق)\n(كل الخلال التي يسعى الكرام لها ... إن يمدحوك بها يوما فقد صدقوا)\n(ساد العراق فحال الناس صالحة ... وسادهم وزمان الناس منخرق)\n(لا خارجي ولا مستحدث شرفا ... بل مجد آل شهاب كان مذ خلقوا)\nال ثم مدح مقاتل بن مسمع طمعا في مثل ما كان مسمع يعطيه فلم يلتفت إليه وأمر أن يحجب عنه فقيل له تعرضت للسان أبي جلدة وخبثه فقال ومن هو الكلب وما عسى أن يقول قبحه الله وقبح من كان منه فليجهد جهده فبلغ ذلك من قوله أبا جلدة فقال يهجوه\n(قرى ضيفه الماء القراح أبن مسمع ... وكان لئيما جاره يتذلل)\n(فلما رأى الضيف القرى غير راهن ... لديه تولى هاربا يتعلل)\n(ينادي بأعلى الصوت بكر بن وائل ... ألا كل من يرجو قراكم مضلل)\n(عميدكم هر الضيوف وكنتم ... ربيعة أمسى ضيفكم يتحول)\n(وختتم بأن تقروا الضيوف وكنتم ... زمانا بكم يحيا الضريك المعيل)\nحذف\n(فما بالكم بالله أنتم بخلتم ... وقصرتم والضيف يقرى وينزل)\n(ويكرم حتى يقترى حين يقترى ... يقول إذا ولى جميلا فيجمل)\n(فمهلا بني بكر دعوا آل مسمع ... ورأيهم لا يسبق الخيل محثل)\n(ودونكم أضيافكم فتحدبوا ... عليهم وواسوهم فذلك أجمل)\n(ولا تصبحوا أحدوثة مثل قائل ... به يضرب الأمثال من يتمثل)\n(إذا ما التقى الركبان يوما تذاكروا ... بني مسمع حتى يحموا ويثقلوا)\n(فلا تقربوا أبياتهم إن جارهم ... وضيفهم سيان أنى توسلوا)\n(هم القوم غر الضيف منهم رواؤهم ... وما فيهم إلا لئيم مبخل)\n(فلو ببني شيبان حلت ركائبي ... لكان قراهم راهنا حين أنزل)\n(أولئك أولى بالمكارم كلها ... وأجدر يوما أن يواسلوا ويفضلوا)\n(بني مسمع لا قرب الله داركم ... ولا زال واديكم من الماء يمحل)\n(فلم تردعوا الأبطال بالبيض والقنا ... إذا جعلت نار الحروب تاكل)","topic":"أخبار أبي جلدة ونسبه","topicNo":125,"sp":6,"spl":"أبى رجل من قومه أن ينادمه فقال شعرا — هجا مقاتل بن مسمع لأنه لم يعطه","loc":2117},
{"id":"b126-2","bab":"الجزء 11","sec":"أخبار علويه ونسبه — رأي إسحاق الموصلي فيه وفي مخارق","page":"ج11 ص334 – ج11 ص335","text":"هو علي بن عبد الله بن سيف وكان جده من السغد الذين سباهم الوليد بن عثمان بن عفان واسترق منهم جماعة اختصهم بخدمته وأعتق بعضهم ولم يعتق الباقين فقتلوه وذكر ابن خرداذبه وهو ممن لا يحصل قوله ولا يعتمد عليه أنه من أهل يثرب مولى بني أمية والقول الأول أصح ويكنى علويه أبا الحسن وكان مغنيا حاذقا ومؤدبا محسنا وصانعا متفننا وضاربا متقدما مع خفة روح وطيب مجالسة وملاحة نوادر وكان إبراهيم الموصلي علمه وخرجه وعني به جدا فبرع وغنى لمحمد الأمين وعاش إلى أيام المتوكل ومات بعد إسحاق الموصلي بمديدة يسيرة وكان سبب وفاته أنه خرج به جرب فشكاه إلى يحيى بن ماسويه فبعث إليه بدواء مسهل وطلاء فشرب الطلاء واطلى بالدواء المسهل فقتله ذلك وكان إسحاق يتعصب له في أكثر أوقاته على مخارق فأما التقديم والوصف فلم يكن إسحاق يرى أحدا من جماعته لهما أهلا فكانوا يتعصبون عليه لإبراهيم بن المهدي فلا يضره ذلك مع تقدمه وفضله\nأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق قال قلت لأبي إيما أفضل عندك مخارق أو علويه فقال يا بني علويه أعرفهما فهما بما يخرج من رأسه وأعلمهما بما يغنيه ويؤديه ولو خيرت بينهما من يطارح جواري أو شاورني من يستنصحني لما أشرت إلا بعلويه لأنه كان يؤدي الغناء وصنع صنعة محكمة ومخارق بتمكنه من حلقه وكثرة نغمه لا يقنع بالأخذ منه لأنه لا يؤدي صوتا واحدا كما أخذه ولا يغنيه مرتين غناء واحدا لكثرة زوائده فيه ولكنهما إذا اجتمعا عند خليفة أو سوقة غلب مخارق على المجلس والجائزة لطيب صوته وكثرة نغمه حدثني جحظة قال حدثني أبو عبد الله بن حمدون قال حدثني أبي قال اجتمعت مع إسحاق يوما في بعض دور بني هاشم وحضر علويه فغنى أصواتا ثم غنى من صنعته\n(ونبئت ليلى أرسلت بشفاعة ... إلي فهلا نفس ليلى شفيعها)\nلحنه ثاني ثقيل فقال له إسحاق أحسنت والله يا أبا الحسن أحسنت ما شئت فقام علويه من مجلسه فقبل رأس إسحاق وعينيه وجلس بين يديه وسر بقوله سرورا شديدا ثم قال أنت سيدي وابن سيدي وأستاذي وابن أستاذي ولي إليك حاجة قال قل فوالله إني أبلغ فيها ما تحب\nقال أيما أفضل عندك أنا أو مخارق فإني أحب أن أسمع منك في هذا المعنى قولا يؤثر ويحكيه عنك من حضر فتشرفني به فقال إسحاق ما منكم إلا محسن مجمل فلا ترد أن ترى في هذا شيئا قال سألتك بحقي عليك وبتربية أبيك وبكل حق تعظمه إلا حكمت فقال ويحك والله لو كنت أستجيز أن أقول غير الحق لقلته فيما تحب فأما إذ أبيت إلا ما ذكرت فهاك ما عندي فلو خيرت أنا من يطارح جواري أو يغنيني لما اخترت غيرك ولكنما إذا غنيتما بين يدي خليفة أو أمير غلبك على إطرابه واستبد عليك بجائزته فغضب علويه وقام وقال أف من رضاك ومن غضبك حدثني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال قدمت من سر من رأى قدمة إلى بغداد فلقيت أبا محمد إسحاق بن إبراهيم الموصلي فجعل يسألني عن أخبار الخليفة وأخبار الناس حتى انتهى إلى ذكر الغناء فقال أي شيء رأيت الناس يستحسونه في هذه الأيام من الأغاني فإن الناس ربما لهجوا بالصوت بعد الصوت فقلت صوتا من صنعتك فقال أي شيء هو فقلت\n(ألا يا حمامي قصر دوران هجتما ... بقلبي الهوى لما تغنيتما ليا)\n(وأبكيتماني وسط صحبي ولم أكن ... أبالي دموع العين لو كنت خاليا)\nضحك وقال ليس هذا لي هذا لعلويه ولقد لعمري أحسن فيه وجود ما شاء لحن علويه في هذين البيتين ثاني ثقيل بالوسطى","topic":"أخبار علويه ونسبه","topicNo":126,"sp":0,"spl":"أخبار علويه ونسبه — رأي إسحاق الموصلي فيه وفي مخارق","song":2,"loc":2118},
{"id":"b126-3","bab":"الجزء 11","sec":"كان أصحابه يتحلقون حوله فيغنيهم","page":"ج11 ص337","text":"حدثني عمي قال حدثنا عبد الله بن عمرو قال حدثني أحمد بن محمد بن عبد الله الأبزاري قال أتيت علويه يوما بالعشي فوجدت عنده خاقان بن حامد وعبد الله بن صالح صاحب المصلى وكنت حملت معي قفص فراريج كسكرية مسمنة وجرابي دقيق سميذ فسلمته إلى غلامه وبعث إلى بشر بن حارثة أطعمنا ما عندك فلم يزل يطعمنا فضلات حتى أدرك طعامه ثم بعث إلى عبد الوهاب بن الخصيب بن عمرو فحضر وقدم الطعام فأكل وأكلنا أكل معذرين ثم قال إني صنعت البارحة لحنا أعجبني فاسمعوه وقولوا فيه ما عندكم وغنانا فقال\n(هزئت عميرة أن رأت ظهري انحنى ... وذؤابتي علت بماء خضاب)\n(لا تهزئي مني عمير فإنني ... محض كريم شيبتي وشبابي)\nحن علويه في هذين البيتين من الثقيل الثاني بالوسطى فقلنا له حسن والله جميل يا أبا الحسن وشربنا عليه أقداحا ثم استؤذن لعثعث غلام أحمد بن يحيى بن معاذ فأذن له ومع عثعث كتاب من مولاه أحمد بن يحيى سمعت يا سيدي منك صوتا عند أمير المؤمنين يعني المعتصم فأحب أن تتفضل وتطرحه على عبدك عثعث وهو\n\n(فواحسرتا لم أقض منك لبانة ... ولم أتمتع بالجوار وبالقرب)\n(يقولون هذا آخر العهد منهم ... فقلت وهذا آخر العهد من قلبي)\nلحن علويه في هذا الشعر ثقيل أول وهو من مقدم أغانيه وصدورها وأول هذا الصوت\n(ألا يا حمام الشعب شعب مورق ... سقتك الغوادي من حمام ومن شعب)\nال وإذا مع حسين رقعة من مولاه سمعتك يا سيدي تغني عند الأمير أبي إسحاق إبراهيم بن المهدي\n(ألا يا حمامي قصر دوران هجتما ... بقلبي الهوى لما تغنيتما ليا)\nحب أن تطرحه على عبدك حسين قال فدعا بغلام له يسمى عبد آل فطرحه عليهما حتى أحكماه ثم عرضاه عليه حتى صح لهما فما أعلم أنه مر لنا يوم يقارب طيب ذلك اليوم وحسنه حدثني جعفر بن قدامة قال حدثني عبيد الله بن عبد الله بن طاهر قال سمعت أبي يقول سمعت الواثق يقول علويه أصح الناس صنعة بعد إسحاق وأطيب الناس صوتا بعد مخارق وأضرب الناس بعد ربرب وملاحظ فهو مصلي كل سابق قادر وثاني كل أول واصل متقدم قال\nوكان الواثق يقول غناء علويه مثل نقر الطست يبقى ساعة في السمع بعد سكوته نسخت من كتاب أبي العباس بن ثوابة بخطه حدثني أحمد بن إسماعيل أبو حاتم قال حدثني عبد الله بن العباس الربيعي قال اجتمعت يوما بين يدي المعتصم وحضر إسحاق الموصلي فغنىعلويه\n(لعبدة دار ما تكلمنا الدار ... تلوح مغانيها كما لاح أسطار)\nقال إسحاق أخطأت فيه ليس هو هكذا فغضب علويه وقال أم من أخذنا عنه هكذا زانية فقال إسحاق وشتمنا قبحه الله وسكت وبان ذلك فيه قال وكان علويه أخذه من أبيه","topic":"أخبار علويه ونسبه","topicNo":126,"sp":1,"spl":"كان أصحابه يتحلقون حوله فيغنيهم","song":2,"loc":2119},
{"id":"b126-4","bab":"الجزء 11","sec":"كان أعسر وعوده مقلوب الأوتار","page":"ج11 ص339","text":"حدثني عمي قال حدثنا هارون بن مخارق قال كان علويه أعسر وكان عوده مقلوب الأوتار البم أسفل الأوتار كلها ثم المثلث فوقه ثم المثنى ثم الزير وكان عوده إذا كان في يد غيره مقلوبا على هذه الصفة وإذا كان معه أخذه باليمنى وضرب باليسرى فيكون مستويا في يده ومقلوبا في يد غيره أخبرنا محمد بن خلف وكيع قال كان الخلنجي القاضي واسمه عبد الله ابن محمد ابن اخت علويه المغني وكان تياها صلفا فتقلد في خلافة\nالأمين قضاء الشرقية فكان يجلس إلى أسطوانة من أساطين المسجد فيستند إليها بجميع جسده ولا يتحرك فإذا تقدم إليه الخصمان أقبل عليهما بجميع جسده وترك الاستناد حتى يفصل بينهما ثم يعود لحاله فعمد بعض المجان إلى رقعة من الرقاع التي يكتب فيها الدعاوى فألصقها في موضع ذنبته بالدبق ومكن منها الدبق فلما تقدم إليه الخصوم وأقبل عليهم بجميع جسده كما كان يفعل انكشف رأسه وبقيت الذنبة موضعها مصلوبة ملتصقة فقام الخلنجي مغضبا وعلم أنها حيلة وقعت عليه فغطى رأسه بطيلسانه وقام فانصرف وتركها مكانها حتى جاء بعض أعوانه فأخذها وقال بعض شعراء ذلك العصر فيه هذه الأبيات\n(إن الخلنجي من تتايهه ... أثقل باد لنا بطلعته)\n(ما إن لذي نخوة مناسبة ... بين أخاوينه وقصعته)\n(يصالح الخصم من يخاصمه ... خوفا من الجور في قضيته)\n(لو لم تدبقه كف قانصه ... لطار تيها على رعيته)\nال وشهرت الأبيات والقصة ببغداد وعمل له علويه حكاية أعطاها للزفانين والمخنثين فأحرجوه فيها وكان علويه يعاديه لمنازعة كانت بينهما ففضحه واستعفى الخلنجي من القضاء ببغداد وسأل أن يولى بعض الكور البعيدة فولي جند دمشق أو حمص فلما ولي المأمون الخلافة غناه علويه\nبشعر الخلنجي فقال\n(برئت من الإسلام إن كان ذا الذي ... أتاك به الواشون عني كما قالوا)\n(ولكنهم لما رأوك غرية ... بهجري تواصوا بالنميمة واحتالوا)\n(فقد صرت أذنا للوشاة سميعة ... ينالون من عرضي وإن شئت ما نالوا)\nفقال له المأمون من يقول هذا الشعر فقال قاضي دمشق فأمر المأمون بإحضاره فكتب إلى صاحب دمشق بإشخاصه فأشخص وجلس المأمون للشرب وأحضر علويه ودعا بالقاضي فقال له أنشدني قولك\n(برئت من الإسلام إن كان ذا الذي ... أتاك به الواشون عني كما قالوا)\nقال له يا أمير المؤمنين هذه أبيات قلتها منذ أربعين سنة وأنا صبي والذي أكرمك بالخلافة وورثك ميراث النبوة ما قلت شعرا منذ أكثر من عشرين سنة إلا في زهد أو عتاب صديق فقال له أجلس فجلس فناوله قدح نبيذ التمر أو الزبيب فقال لا والله يا أمير المؤمنين ما أعرف شيئا منها فأخذ القدح من يده وقال أما والله لو شربت شيئا من هذا لضربت عنقك وقد ظننت أنك صادق في قولك كله ولكن لا يتولى لي القضاء رجل بدأ في قوله بالبراءة من الإسلام انصرف إلى منزلك وأمر علويه فغير الكلمة وجعل مكانها حرمت مناي منك","topic":"أخبار علويه ونسبه","topicNo":126,"sp":2,"spl":"كان أعسر وعوده مقلوب الأوتار","loc":2120},
{"id":"b126-5","bab":"الجزء 11","sec":"تقربه من المأمون بعد خلافه مع الأمين","page":"ج11 ص341","text":"حدثني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك قال كان علويه يغني بين يدي الأمين فغنى في بعض غنائه\n(ليت هندا أنجزتنا ما تعد ... وشفت أنفسنا مما تجد)\nكان الفضل بن الربيع يطعن عليه فقال للأمين إنما يعرض بك ويستبطىء المأمون في محاربته فأمر به فضرب خمسين سوطا وجر برجله وجفاه مدة حتى ألقى نفسه على كوثر فترضاه له ورد إلى خدمته وأمر له بخمسة آلاف دينار فلما قدم المأمون تقرب إليه بذلك فلم يقع له بحيث يحب وقال له إن الملك بمنزلة الأسد أو النار فلا تتعرض لما يغضبه فإنه ربما جرى منه ما يتلفك ثم لا تقدر بعد ذلك على تلافي ما فرط منه ولم يعطه شيئا ومثل هذا من فعل الأمين ما حدثني به محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق قال حدثني أبي قال دخلت على الأمين فرأيته مغضبا كالحا فقلت له ما لأمير المؤمنين تمم الله سروره ولا نغصه أراه كالحائر قال غاظني أبوك الساعة لا رحمه الله والله لو كان حيا لضربته خمسمائة سوط ولولاك لنبشت الساعة قبره وأحرقت عظامه فقمت على رجلي وقلت أعوذ بالله من سخطك يا أمير المؤمنين ومن أبي وما مقداره حتى تغتاظ منه وما الذي غاظك فلعل له فيه عذرا فقال شدة محبته للمأمون وتقديمه إياه علي حتى قال في الرشيد شعرا يقدمه فيه علي وغناه فيه وغنيته الساعة فأورثني هذا الغيظ فقلت والله ما سمعت بهذا قط ولا لأبي غناء إلا وأنا أرويه ما هو فقال قوله\n(أبو المأمون فينا والأمين ... له كنفان من كرم ولين)\nقلت له يا أمير المؤمنين لم يقدم المأمون في الشعر لتقديمه إياه في\nالموالاة ولكن الشعر لم يصح وزنه إلا هكذا فقال كان ينبغي له إذ لم يصح الشعر إلا هكذا أن يدعه إلى لعنة الله فلم أزل أداريه وأرفق به حتى سكن فلما قدم المأمون سألني عن هذا الحديث فحدثته به فجعل يضحك ويعجب منه حدثني جعفر بن قدامة قال حدثني عبيد الله بن عبد الله بن طاهر قال سمعت أبي يقول لو خيرت لونا من الطعام لا أزيد عليه غيره لاخترت الدراجة لأني إن زدت في خلها صارت سكباجة وإن زدت في مائها صارت إسفيدباجة وإن زدت في تصبيرها بل في تشييطها صارت مطجنة ولو اقتصرت على رجل واحد لما اخترت سوى علوية لأنه إن حدثني ألهاني وإن غناني أشجاني وإن رجعت إلى رأيه كفاني","topic":"أخبار علويه ونسبه","topicNo":126,"sp":3,"spl":"تقربه من المأمون بعد خلافه مع الأمين","loc":2121},
{"id":"b126-6","bab":"الجزء 11","sec":"وفد على سعيد بن عجيف فأكرمه","page":"ج11 ص343","text":"حدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن محمد الأبزاري قال كنت عند سعيد بن عجيف أنا وعبد الوهاب بن الخصيب وعبد الله بن صالح صاحب المصلى إذ دخل عليه حاجبه فقال له علويه بالباب فأذن له فدخل فقال له لا تحمدني فإني لم يجئني رسول رجل اليوم فعرضت إخواني جميعا على قلبي فلم يقع عليه غيرك فدعا له ببرذون ادهم بسرجه\nولجامه فأهداه إليه وجلسنا نشرب وعلويه يغني فلما توسطنا أمرنا جاء رسول عجيف يطلبه في منزله فقالوا له هو عند ابنه سعيد فأتاه الرسول فقال له أجب الأمير فقلنا هذا شيء ليس فيه حيلة وقد جاء الرسول وهو يغني\n(ألم تر أني يوم جو سويقة ... بكيت فنادتني هنيدة ما ليا)\n(فقلت لها إن البكاء لراحة ... به يشتفي من ظن أن لا تلاقيا)\nحن علوية في هذا رمل والشعر للفرزدق قال فقام علوية ثم قال هوذا أمضي إلى الأمير فأحدثه بحديثنا وأستأذنه في الانصراف بوقت يكون فيه فضل لكم فانصرف بعد المغرب ومعه جام فيه مسك وعشرة آلاف درهم ومنيان فيهما رماطون فقال جئت أشرب عندكم وآخذه وأنصرف إلى إنسان له عندي أياد يعني علي بن معاذ أخا يحيى بن معاذ فلم يزل عندنا حتى هم بالانصراف فلما رأيت ذلك فيه قمت قبله فأتيت منزل علي ابن معاذ فقيل له ابن الأبزاري بالباب فبعث إلي إن أردت مضاء فخذه يعني غلاما كان يغني فقلت له لست أريده إنما أريدك أنت فأذن لي فدخلت فقال ألك حاجة في هذا الوقت فقلت الساعة يجيئك\nعلوية فقال وما يدريك فحدثته بالحديث ودخل علويه فقال لي ما جاء بك إلى ها هنا فقلت ما كنت لأدع بقية ليلتي هذه تضيع فما زال يغنينا ونشرب حتى نام الناس ثم انصرفنا حدثني جعفر بن قدامة قال حدثنا هارون بن مخارق قال حدثني أبي قال قلت لعمرو بن بانة أيما أجود صنعتك أم صنعة علويه فقال صنعة علويه لأنه ضارب وأنا مرتجل ثم أطرق ساعة وقال لاأكذبك يا أبا المهنأ والله ما أحسن أن أصنع مثل صنعة علويه\n(فواحسرتا لم أفض منك لبانة ... ولم أتمتع بالجوار وبالقرب)\nلا مثل صنعته\n(هزئت أميمة أن رأت ظهري انحنى ... وذؤابتي علت بماء خضاب)\nلا مثل صنعته\n(ألا يا حمامي قصر دوران هجتما ... لقلبي الهوى لما تغنيتما ليا)\nقد مضت نسبة هذه الأصوات حدثني جحظة قال حدثني أحمد بن الحسين بن هشام أبو عبد الله قال حدثني أحمد بن الخليل بن هشام قال كان بين علويه وبين علي بن الهيثم جونقا شر في عربدة وقعت بينهما بحضرة الفضل بن الربيع وتمادى الشر بينهما فغنى علويه في شعر هجاه به\nأبو يعقوب في حاجة فهجاه وذكر أنه دعي وكان جونقا يدعي أنه من بني تغلب فقال فيه أبو يعقوب\n(يا علي بن هيثم يا جونقا ... أنت عندي من الأراقم حقا)\n(عربي وجده نبطي ... فدبنقا لذا الحديث دبنقا)\n(قد أصابتك في التقرب عين ... فاستنارت لشهبها الفلك برقا)\n(وإذا قال إني عربي ... فانتهزه وقل له أنت شفقا)\nللخريمي فيه أهاج نبطية فغنى علويه لحنا صنعه في هذه الأبيات بحضرة الأمين وكان الفضل بن الربيع حاضرا فقال يا أمير المؤمنين علي بن الهيثم كابني وإذا استخف به فإنما استخف بي فقال الأمين خذوه فأخذوه وضرب ثلاثين درة وأمر بإخراجه فطرح علويه نفسه على كوثر فاستصلح له الفضل بن الربيع وترضى له الأمين حتى رضي عنه عنه ووهب له خمسة آلاف دينار","topic":"أخبار علويه ونسبه","topicNo":126,"sp":4,"spl":"وفد على سعيد بن عجيف فأكرمه","song":1,"loc":2122},
{"id":"b126-7","bab":"الجزء 11","sec":"غنى بحضرة الواثق فأطربه","page":"ج11 ص346","text":"حدثني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك قال\nحدثني مخارق قال غنى علويه يوما بحضرة الواثق هذا الصوت\n(من صاحب الدهر لم يحمد تصرفه ... عنا وللدهر إحلاء وإمرار)\nلحنه ثقيل أول فأستحسنه الواثق وطرب عليه فقال علويه والله لو شئت لجعلت الغناء في أيدي الناس أكثر من الجوز وإسحاق حاضر بين يدي الواثق فتضاحك ثم قال يا أبا الحسن إذا تكون قيمته مثل قيمة الجوز ليتك إذ قللته صنعت شيئا فكيف إذا كثرته فخجل علويه حتى كأنما ألقمه إسحاق حجرا وما انتفع بنفسه يومئذ حدثني محمد بن يحيى الصولي قال حدثني عبد الله بن المعتز قال حدثني عبد الله الهشامي قال قال لي علويه أمرنا المأمون أن نباكره لنصطبح فلقيني عبد الله بن إسماعيل المراكبي مولى عريب فقال أيها الظالم المعتدي أما ترحم ولا ترق عريب هائمة من الشوق إليك تدعو الله وتستحكمه عليك وتحلم بك في نومها في كل ليلة ثلاث مرات قال علوية فقلت أم الخلافة زانية ومضيت معه فحين دخلت قلت استوثق من الباب فأنا أعرف الناس بفضول الحجاب فإذا عريب جالسة على كرسي تطبخ ثلاث قدور من دجاج فلما رأتني قامت فعانقتني وقبلتني وقالت أي شيء تشتهي فقلت قدرا من هذه القدور فأفرغت قدرا بيني وبينها فأكلنا ودعت بالنبيذ فصبت رطلا فشربت نصفه وسقتني نصفه فما زلت أشرب حتى كدت أن أسكر ثم قالت يا أبا الحسن غنيت البارحة في شعر لأبي العتاهية أعجبني أفتسمعه مني وتصلحه فغنت\n\n(عذيري من الإنسان لا إن جفوته ... صفا لي ولا إن صرت طوع يديه)\n(وإني لمشتاق إلى ظل صاحب ... يروق ويصفو إن كدرت عليه)\nصيرناه مجلسا وقالت قد بقي فيه شيء فلم أزل أنا وهي حتى اصلحناه ثم قالت وأحب أن تغني أنت فيه أيضا لحنا ففعلت وجعلنا نشرب على اللحنين مليا ثم جاء الحجاب فكسروا الباب واستخرجوني فدخلت إلى المأمون فأقبلت أرقص من أقصى الإيوان وأصفق وأغني بالصوت فسمع المأمون والمغنون ما لم يعرفوه فاستظرفوه وقال المأمون ادن يا علويه ورده فرددته عليه سبع مرات فقال لي في آخرها عند قولي\n(يروق ويصفو إن كدرت عليه ... )\nيا علويه خذ الخلافة وأعطني هذا الصاحب لحن عريب في هذا الشعر رمل وفيه لعلويه لحنان ثاني ثقيل وماخوري","topic":"أخبار علويه ونسبه","topicNo":126,"sp":5,"spl":"غنى بحضرة الواثق فأطربه — ابراهيم بن المهدي يحسده على صوتين غناهما","song":1,"loc":2123,"partialRef":{"sid":"b102-28","gi":0,"vi":1,"side":1},"partial":1},
{"id":"b126-8","bab":"الجزء 11","sec":"ابراهيم بن المهدي يحسده على صوتين غناهما","page":"ج11 ص348","text":"وقال العتابي حدثني أحمد بن حمدون قال غاب عنا علويه مدة ثم صار إلينا فقال له إبراهيم بن المهدي مالذي أحدثت بعدي من الصنعة يا أبا الحسن قال صنعت صوتين قال فهاتهما إذا فغناه\n\n(ألا إن لي نفسين نفسا تقول لي ... تمتع بليلى ما بدا لك لينها)\n(ونفسا تقول استبق ودك واتئد ... ونفسك لا تطرح على من يهينها)\nحن علويه في هذين البيتين خفيف ثقيل قال فرأيت إبراهيم بن المهدي قد كاد يموت من حسده وتغير لونه ولم يدر ما يقول له لأنه لم يجد في الصوت مطعنا فعدل عن الكلام في هذا المعنى وقال هذا يدل على أن ليلى هذه كانت من لينها مثل الموم بالبنفسج فسكت علويه ثم سأله عن الصوت الآخر فغناه\n(إذا كان لي شيئان يا أم مالك ... فإن لجاري منهما ما تخيرا)\n(وفي واحد إن لم يكن غير واحد ... أراه له أهلا إذا كان مقترا)\nوالشعر لحاتم الطائي لحن علويه في هذين البيتين أيضا خفيف ثقيل وقد روي أن إبراهيم الموصلي صنعه ونحله إياه وأنا أذكر خبره بعقب هذا الخبر قال أحمد بن حمدون فأتى والله بما برز على الأول وأوفى عليه وكاد إبراهيم يموت غيظا وحسدا لمنافسته في الصنعة وعجزه عنها فقال له وإن كانت لك امرأتان يا أبا الحسن حبوت جارك منهما واحدة فخجل علويه وما نطق بصوت بقية يومه\nوحدثني عمي عن علي بن محمد عن جده حمدون هذا لخبر ولفظه أقل من هذا","topic":"أخبار علويه ونسبه","topicNo":126,"sp":5,"spl":"غنى بحضرة الواثق فأطربه — ابراهيم بن المهدي يحسده على صوتين غناهما","song":2,"loc":2124},
{"id":"b126-9","bab":"الجزء 11","sec":"نحله إبراهيم الموصلي صوتا فشاع","page":"ج11 ص350","text":"فأما الخبر الذي ذكرته عن علويه أن إبراهيم الموصلي نحله هذا الصوت فحدثني جحظة قال حدثني أبن المكي المرتجل وهو محمد بن أحمد ابن يحيى قال حدثني علويه قال قال إبراهيم الموصلي يوما إني قد صنعت صوتا وما سمعه مني أحد بعد وقد أحببت أن أنفعك وأرفع منك بأن القيه عليك وأهبه لك ووالله ما فعلت هذا بإسحاق قط وقد خصصتك به فانتحله وادعه فلست أنسبه إلى نفسي وستكسب به مالا فألقى علي قوله\n(إذا كان لي شيئان يا أم مالك ... فإن لجاري منهما ما تخيرا)\nأخذته وادعيته وسترته طوال أيام الرشيد خوفا من أن أتهم فيه وطول أيام الأمين حتى حدث عليه ما حدث وقدم المأمون من خراسان وكان يخرج إلى الشماسية دائما يتنزه فركبت في زلال وجئت أتبعه فرأيت حراقة علي بن هشام فقلت للملاح اطرح زلالي على الحراقة ففعل وأستؤذن لي فدخلت وهو يشرب مع الجواري وما كانوا يحجبون جواريهم في ذلك الوقت ما لم يلدن فإذا بين يديه متيم وبذل من جواريه فغنيته الصوت\nفاستحسنه جدا وطرب عليه وقال لمن هذا فقلت هذا صوت صنعته وأهديته لك ولم يسمعه أحد قبلك فازداد به عجبا وطربا وقال لها خذيه عنه فألقيته عليها حتى أخذته فسر بذلك وطرب وقال لي ما أجد لك مكافأة على هذه الهدية إلا أن أتحول عن هذه الحراقة بما فيها وأسلمه إليك أجمع فتحول إلى أخرى وسلمت الحراقة بخزانتها وجميع آلاتها إلي وكل شيء فيها فبعت ذلك بمائة وخمسين ألف درهم وأشتريت بها ضيعتي الصالحية","topic":"أخبار علويه ونسبه","topicNo":126,"sp":6,"spl":"نحله إبراهيم الموصلي صوتا فشاع — غنى المأمون بيتا مجهولا","loc":2125},
{"id":"b126-10","bab":"الجزء 11","sec":"غنى المأمون بيتا مجهولا","page":"ج11 ص351","text":"حدثني جحظة قال حدثني ابن المكي المرتجل عن أبيه قال قال إسحاق ابن حميد كاتب أبي الرازي وحدثني به عمي قال حدثني عبد الله بن أبي سعد قال حدثني حسان بن محمد الحارثي عن إسحاق بن حميد كاتب أبي الرازي قال غنى علويه الأعسر يوما بين يدي المأمون\n(تخيرت من نعمان عود أراكة ... لهند فمن هذا يبلغه هندا)\nقال المأمون اطلبوا لهذا البيت ثانيا فلم يعرف وسأل كل من بحضرته من أهل الأدب والرواة والجلساء عن قائل هذا الشعر فلم يعرفه أحد فقال إسحاق بن حميد لما رأيت ذلك عنيت بهذا الشعر وجهدت في المسألة وطلبته ببغداد عند كل متأدب وذي معرفة فلم يعرفه وقلد المأمون أبا الرازي كور دجلة وأنا أكتب له ثم نقله إلى اليمامة والبحرين قال إسحاق بن\nحميد فلما خرجنا ركبت مع أبي الرازي في بعض الليالي على حمارة فأبتدأ الحادي يحدو بقصيدة طويلة وإذا البيت الذي كنت أطلبه فسألته عنها فذكر أنها للمرقش الأكبر فحفظت منها هذه الأبيات\n(خليلى عوجا بارك الله فيكما ... وإن لم تكن هند لأرضكما قصدا)\n(وقولا لها ليس الضلال أجازنا ... ولكننا جزنا لنلقاكم عمدا)\n(تخيرت من نعمان عود أراكة ... لهند فمن هذا يبلغه هندا)\n(وأنطيته سيفي لكيما أقيمه ... فلا أودا فيه أستبنت ولا خضدا)\n(ستبلغ هندا إن سلمنا قلائص ... مهارى يقطعن الفلاة بنا وخدا)\n(فلما أنخنا العيس قد طار سيرها ... إليهم وجدناهم لنا بالقرى حشدا)\n(فناولتها المسواك والقلب خائف ... وقلت لها يا هند أهلكتنا وجدا)\n(فمدت يدا في حسن دل تناولا ... إليه وقالت ما أرى مثل ذا يهدى)\n(وأقبلت كالمجتاز أدى رسالة ... وقامت تجر الميسناني والبردا)\n(تعرض للحي الذين أريدهم ... وما التمست إلا لتقتلني عمدا)\n(فما شبه هند غير أدماء خاذل ... من الوحش مرتاع مراع طلا فردا)\nال فكتب بها إلى المأمون فاستحسنت ورويت وأمر علويه فصنع في البيتين الأولين منها غناء يشبه أغاني علويه في هذه الأبيات اللحن الأول في قوله\n(تخيرت من نعمان عود أراكة ... )\nناه علويه وليس اللحن له اللحن لإبراهيم خفيف ثقيل بالبنصر ولحنه الثاني الذي أمره أن يصنعه في\n(خليلي عوجا بارك الله فيكما ... )\nمل","topic":"أخبار علويه ونسبه","topicNo":126,"sp":6,"spl":"نحله إبراهيم الموصلي صوتا فشاع — غنى المأمون بيتا مجهولا","loc":2126,"partial":1},
{"id":"b126-11","bab":"الجزء 11","sec":"غنى المعتصم بشعر ابن هرمة","page":"ج11 ص353","text":"حدثني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك قال عرض علويه على المعتصم رقعة في أمر رزقه وإقطاعه وهو يشرب دفعها إليه من يده فلما أخذها اندفع علويه يغني\n(إني استحيتك أن أفوه بحاجتي ... فإذا قرأت صحيفتي فتفهم)\n(وعليك عهد الله إن خبرته ... أحدا ولا أظهرته بتكلم)\nفقرأ المعتصم الرقعة وهو يضحك ثم وقع له فيها بما أراد الشعر لابن هرمة كتب به إلى بعض آل أبي طالب وهو إبراهيم بن الحسن يطلب منه نبيذا وقد خرج هو وأصحابه إلى السيالة فكتب إليه البيت الأول على ما رويناه والثاني غيره المغنون وهو\n(وعليك عهد الله إن أعلمته ... أهل السيالة إن فعلت وإن لم)\nلما قرأ الرقعة قال علي عهد الله إن لم أعلم به عامل السيالة وكتب الى عامل السيالة إن ابن هرمة وأصحابا له سفهاء يشربون بالسيالة فاركب إليهم حتى تأخذهم فركب إليهم ونذروا به فهرب وقال يهجو إبراهيم\n(كتبت إليك أستهدي نبيذا ... وأدلي بالمودة والحقوق)\n(فخبرت الأمير بذاك جهلا ... وكنت أخا مفاضحة وموق)\nدثني بذلك الحرمي بن أبي العلاء قال حدثنا الزبير وقد ذكرته في أخبار ابن هرمة والغناء لعبادل حدثني جعفر بن قدامة قال حدثني موسى بن هارون الهاشمي قال حدثني أبي قال\nكنت واقفا بين يدي المعتصم وهو جالس على حير الوحش والخيل تعرض عليه وهو يشرب وبين يديه علويه ومخارق يغنيان فعرض عليه فرس كميت أحمر ما رأيت مثله قط فتغامز علويه ومخارق وغناه علويه\n(وإذا ما شربوها وانتشوا ... وهبوا كل جواد وطمر)\nتغافل عنه وغناه مخارق\n(يهب البيض كالظباء وجردا ... تحت أجلالها وعيس الركاب)\nضحك ثم قال اسكتا يا ابني الزانيتين فليس يملكه والله واحد منكما قال ثم دار الدور فغنى علويه\n(وإذا ما شربوها وانتشوا ... وهبوا كل بغال وحمر)\nضحك وقال أما هذا فنعم وأمر لأحدهما ببغل وللآخر بحمار حدثني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن محمد الأبزاري قال كنا عند زلبهزة النخاس وكانت عنده جارية يقال لها خشف ابتاعها من علويه وذلك في شهر رمضان ومعنا رجل هاشمي من ولد عبد الصمد بن علي يقال له عبد الصمد وإبراهيم بن عمرو بن نهبون وكان يحبها فأعطى بها زلبهزة أربعة آلاف دينار فلم يبعها منه وبقيت معه حتى توفيت فغنتنا أصواتا كان فيها\n(أشارت بطرف العين خيفة أهلها ... إشارة محزون ولم تتكلم)\n(فأيقنت أن الطرف قد قال مرحبا ... وأهلا وسهلا بالحبيب المسلم)\n(وأبرزت طرفي نحوها لأجيبها ... وقلت لها قول امرىء غير معجم)\n(هنيئا لكم قتلي وصفو مودتي ... وقد سيط في لحمي هواك وفي دمي)\nلغناء لابن عائشة ثقيل أول عن الهشامي قال فلما وثبنا للانصراف قال لنا وقد اشتد الحر أقيموا عندي فوجهت غلاما معي وأعطيته دينارا وقلت له ابتع فراريج بعشرة دراهم وثلجا بخمسة دراهم وعجل فجاء بذلك فدفعه إلى زلبهزة وأمره بإصلاح الفراريج ألوانا وكتبت إلى علويه فعرفته خبرنا فجاءنا وأقام وأفطرنا عند زلبهزة وشرب منا من كان يستجيز الشراب وغنى علويه لحنا ذكر أنه لابن سريج ثقيل أول فاستغربه الجماعة وهو\n(يا هند إن الناس قد أفسدوا ... ودك حتى عزني المطلب)\n(يا ليت من يسعى بنا كاذبا ... عاش مهانا في أذى يتعب)\n(هبيه ذنبا كنت أذنبته ... قد يغفر الله لمن يذنب)\n(وقد شجاني وجرت دمعتي ... أن أرسلت هند وهي تعتب)\n(ما هكذا عاهدتنا في منى ... ما أنت إلا ساحر تخلب)\n(حلفت لي بالله لا نبتغي ... غيرك ما عشت ولا تطلب)\nال وقام عبد الصمد الهاشمي ليبول فقال علويه كل شيء قد عرفت معناه أما أنت فصديق الجماعة وهذا يتعشق هذه وهذا مولاها وأنا ربيتها وعلمتها وهذا الهاشمي أيش معناه فقلت لهم دعوني","topic":"أخبار علويه ونسبه","topicNo":126,"sp":7,"spl":"غنى المعتصم بشعر ابن هرمة","song":2,"loc":2127},
{"id":"b126-13","bab":"الجزء 11","sec":"غنى المعتصم بشعر ابن هرمة — رتبته بين المغنين","page":"ج11 ص353 – ج11 ص357","text":"أحكه وآخذ لزلبهزة منه شيئا فقال لا والله ما أريد فقلت له أنت أحمق أنا آخذ منه شيئا لا يستحي القاضي من أخذه فقال إن كان هكذا فنعم فقلت له إذا جاء عبد الصمد فقل لي ما فعل الآجر الذي وعدتني به فإن حائطي قد مال وأخاف أن يقع ودعني والقصة فلما جاء الهاشمي قال لي زلبهزة ما أمرته به فقلت ليس عندي آجر ولكن اصبر حتى أطلب لك من بعض أصدقائي وجعلت أنظر إلى الهاشمي نظر متعرض به قال الهاشمي يا غلام دواة ورقعة فأحضر ذلك فكتب له بعشرة آلاف آجرة إلى عامل له وشربنا حتى السحر وانصرفنا فجئت برقعته إلى الآجري ثم قلت بكم تبيعه الآجر فقال بسبعة وعشرين درهما الألف قلت فبكم تشتريه مني قال بنقصان ثلاثة دراهم في الألف فقلت فهات فأخذت منه مائتين وأربعين درهما واشتريت منها نبيذا وفاكهة وثلجا ودجاجا بأربعين درهما وأعطيت زلبهزة مائتي درهم وعرفته الخبر ودعونا علويه والهاشمي وأقمنا عند زلبهزة ليلتنا الثانية فقال علويه نعم الآن صار للهاشمي عندكم موضع ومعنى\nأخبرني جحظة قال حدثني أحمد بن حمدون قال حدثني أبي قال قال لنا الواثق يوما من أحذق الناس بالصنعة قلنا إسحاق قال ثم من قلنا علويه قال فمن أضرب الناس قلنا ثقيف قال ثم من قلنا علويه قال فمن أطيب الناس صوتا قلنا مخارق قال ثم من قلنا علويه قال أعترفتم له بأنه مصلي كل سابق وقد جمع الفضائل كلها وهي متفرقة فيهم فما ثم ثان لهذا الثالث\nوحدثني جحظة قال حدثني محمد بن أحمد المكي المرتجل قال حدثني أبي قال دخلت إلى علويه أعوده من علة أعتلها ثم عوفي منها فجرى حديث المأمون فقال لي كدت علم الله أذهب دفعة ذات يوم وأنا معه لولا أن الله تعالى سلمني ووهب لي حلمه فقلت كيف كان السبب في ذلك فقال كنت معه لما خرج الى الشأم فدخلنا دمشق فطفنا فيها وجعل يطوف على قصور بني أمية ويتبع آثارهم فدخل صحنا من صحونهم فإذا هو مفروش بالرخام الأخضر كله وفيه بركة ماء يدخلها ويخرج منها من عين تصب اليها وفي البركة سمك وبين يديها بستان على أربع زواياه أربع سروات كأنها قصت بمقراض من التفافها أحسن ما رأيت من السرو قط قدا وقدرا فاستحسن ذلك وعزم على الصبوح وقال هاتوا لي الساعة طعاما خفيفا فأتي ببزماورد فأكل ودعا بشراب وأقبل علي وقال غنني ونشطني فكأن الله عز و جل أنساني الغناء كله إلا هذا الصوت\n(لو كان حولي بنو أمية لم ... تنطق رجال أراهم نطقوا)\nنظر إلي مغضبا وقال عليك وعلى بني أمية لعنة الله ويلك أقلت لك سؤني أو سرني ألم يكن لك وقت تذكر فيه بني أمية إلا هذا الوقت تعرض بي فتحيلت عليه وعلمت أني قد أخطأت فقلت أتلومني على أن أذكر\nبني أمية هذا مولاكم زرياب عندهم يركب في مائتي غلام مملوك له ويملك ثلاثمائة ألف دينار وهبوها له سوى الخيل والضياع والرقيق وأنا عندكم أموت جوعا فقال أولم يكن لك شيء تذكرني به نفسك غير هذا فقلت هكذا حضرني حين ذكرتهم فقال اعدل عن هذا وتنبه على إرادتي فأنساني الله كل شيء أحسنه إلا هذا الصوت\n(الحين ساق إلى دمشق ولم أكن ... أرضى دمشق لأهلنا بلدا)\nرماني بالقدح فأخطأني فانكسر القدح وقال قم عني إلى لعنة الله وحر سقر وقام فركب فكانت والله تلك الحال آخر عهدي به حتى مرض ومات قال ثم قال لي يا أبا جعفر كم تراني أحسن أغني ثلاثة آلاف صوت أربعة آلاف صوت خمسة آلاف صوت أنا والله أغني أكثر من ذلك ذهب علم الله كله حتى كأني لم أعرف غير ما غنيت ولقد ظننت أنه لو كانت لي ألف روح ما نجت منه واحدة منها ولكنه كان رجلا حليما وكان في العمر بقية","topic":"أخبار علويه ونسبه","topicNo":126,"sp":8,"spl":"غنى المعتصم بشعر ابن هرمة — رتبته بين المغنين","loc":2128},
{"id":"b126-14","bab":"الجزء 11","sec":"نسبة هذين الصوتين المذكورين في الخبر","page":"ج11 ص359","text":"\n(لو كان حولي بنو أمية لم ... تنطق رجال أراهم نطقوا)\n(من كل قرم محض ضرائبه ... عن منكبيه القميص ينخرق)\nالشعر لعبد الله بن قيس الرقيات والغناء لمعبد ثقيل أول بالوسطى عن عمرو وذكر الهشامي أنه لابن سريج وذكر ابن خرداذبه أن فيه لدكين بن عبد الله بن عنبسة بن سعيد بن العاصي لحنا من الثقيل الأول وأن دكينا مدني كان منقطعا إلى جعفر بن سليمان\n(الحين ساق إلى دمشق وما ... كانت دمشق لأهلنا بلدا)\n(قادتك نفسك فاستقدت لها ... وأريت أمر غواية رشدا)\nعمر الوادي في هذا الشعر ثقيل أول بالوسطى عن ابن المكي قال وفيه ليعقوب الوادي رمل بالبنصر حدثني عمي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال سمعت الحسن بن وهب الكاتب يحدث أن علويه كان يصطبح في يوم خضابه مع جواريه وحرمه ويقال أجعل صبوحي في أحسن ما يكون عند جواري فقيل له إن ابن سيرين كان يقول لا بأس بالخضاب ما لم تغرر به امرأة مسلمة فقال إنما كره لئلا يتصنع به لمن لا يعرفه من الحرائر فيتزوجها على أنه شاب وهو شيخ فأما الإماء فهن ملكي وما أريد أن أغرهن قال الحسن فتعالل علويه على المعتصم ثلاثة أيام متوالية واصطبح فيها فدعاني وكان صوته على جواريه في شعر الأخطل\n(كأن عطارة باتت تطيف به ... حتى تسربل مثل الورس وانتعلا)\nقال لي كيف رويته فقلت له قرأت شعر الأخطل وكان أعلم الناس به كان يختار تسرول ويقول إنما وصف ثورا دخل روضة فيها نوار أصفر فأثر في قوائمه وبطنه فكان كالسراويل لا أنه صار له سربال ولو قال تسربل أيضا لم يكن فاسدا ولكن الوجه تسرول أخبرني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال قدمت من سر من رأى قدمة بعد طول غيبة فدخلت إلى إسحاق الموصلي فسلم علي وسألني خبري وخبر الناس حتى أنتهينا إلى ذكر الغناء فسألني عما يتشاغل الناس من الأصوات المستجادة فقلت له تركت الناس كلهم مغرمين بصوت لك قال وما هو فقلت\n(ألا يا حمامي قصر دوران هجتما ... )\nقال ليس ذلك لي ذاك لعلويه وقد لعمري أحسن فيه وجود ما شاء","topic":"أخبار علويه ونسبه","topicNo":126,"sp":9,"spl":"نسبة هذين الصوتين المذكورين في الخبر — نسبة هذه الأصوات التي تقدمت","song":2,"loc":2129,"partialRef":{"sid":"b126-2","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b126-15","bab":"الجزء 11","sec":"غنى المأمون بأبيات معه","page":"ج11 ص361","text":"أخبرني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك الخزاعي قال حدثني علويه قال خرج المأمون يوما ومعه أبيات قد قالها وكتبها في رقعة بخطه وهي\n\n(خرجنا إلى صيد الظباء فصادني ... هناك غزال أدعج العين أحور)\n(غزال كأن البدر حل جبينه ... وفي خده الشعرى المنيرة تزهر)\n(فصاد فؤادي إذ رماني بسهمه ... وسهم غزال الإنس طرف ومحجر)\n(فيا من رأى ظبيا يصيد ومن رأى ... أخا قنص يصطاد قهرا ويقسر)\nال فغنيته فيها فأمر لي بعشرة آلاف درهم قال أبو القاسم جعفر بن قدامة لحن علويه في هذا الشعر ثقيل أول ابتداؤه نشيد","topic":"أخبار علويه ونسبه","topicNo":126,"sp":9,"spl":"نسبة هذين الصوتين المذكورين في الخبر — نسبة هذه الأصوات التي تقدمت","song":1,"loc":2130},
{"id":"b126-16","bab":"الجزء 11","sec":"غنى الرشيد في مجلسه فأغضبه","page":"ج11 ص362","text":"أخبرني محمد بن مزيد قال حدثني حماد عن أبيه قال غنيت الرشيد يوما\n(هما فتاتان لما يعرفا خلقي ... وبالشباب على شيبي يدلان)\nطرب وأمر لي بألف دينار فقال له ابن جامع وكان أحسد الناس اسمع غناء العقلاء ودع غناء المجانين وكنت أخذت هذا الصوت من مجنون بالمدينة كان يجيده ثم غنى قوله\n(ولقد قالت لأتراب لها ... كالمها يلعبن في حجرتها)\n(خذن عني الظل لا يتبعني ... وغدت تسعى إلى قبتها)\nفطرب وأمر له بألف وخمسمائة دينار ثم تغنى وجه القرعة\n(يمشون فيها بكل سابغة ... أحكم فيها القتير والحلق)\nاستحسنه وشرب عليه وأمر له بخمسمائة دينار ثم تغنى علويه\n(وأرى الغواني لا يواصلن أمرأ ... فقد الشباب وقد يصلن الأمردا)\nدعاه الرشيد وقال له يا عاض بظر أمه تغني في مدح المرد وذم الشيب وستارتي منصوبة وقد شبت كأنك إنما عرضت بي ثم دعا بمسرور فأمره أن يأخذ بيده فيخرجه فيضربه ثلاثين درة ولا يرده إلى مجلسه ففعل ذلك ولم ينتفع الرشيد يومئذ بنفسه ولا أنتفعنا به بقية يومنا وجفا علويه شهرا فلم يأذن له حتى سألناه فأذن له","topic":"أخبار علويه ونسبه","topicNo":126,"sp":9,"spl":"نسبة هذين الصوتين المذكورين في الخبر — نسبة هذه الأصوات التي تقدمت","loc":2131},
{"id":"b126-17","bab":"الجزء 11","sec":"نسبة هذه الأصوات التي تقدمت","page":"ج11 ص363","text":"\n(هما فتاتان لما يعرفا خلقي ... وبالشباب على شيبي يدلان)\n(كل الفعال الذي يفعلنه حسن ... يضني فؤادي ويبدي سر أشجاني)\n(بل أحذرا صولة من صول شيخكما ... مهلا عن الشيخ مهلا يا فتاتان)\nم يقع إلي شاعره فيه لابن سريج ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وفيه لابن سريج رمل بالبنصر عن عمرو وفيه لسليمان المصاب رمل كان يغنيه فدس الرشيد إليه إسحاق حتى أخذه منه وقيل بل دس عليه ابن جامع","topic":"أخبار علويه ونسبه","topicNo":126,"sp":9,"spl":"نسبة هذين الصوتين المذكورين في الخبر — نسبة هذه الأصوات التي تقدمت","song":1,"loc":2132},
{"id":"b126-18","bab":"الجزء 11","sec":"إسحاق يأخذ صوتا من سليمان المصاب","page":"ج11 ص364","text":"أخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق عن أبيه قال دعاني الرشيد لما حج فقال صر إلى موضع كذا وكذا من المدينة فإن هناك غلاما مجنونا يغني صوتا حسنا وهو\n(هما فتاتان لما يعرفا خلقي ... وبالشباب على شيبي يدلان)\nله أم فصر إليها وأقم عندها واحتل حتى تأخذه فجئت أستدل حتى وقفت على بيتها فخرجت إلي فوهبت لها مائتي درهم وقلت لها أريد أن تحتالي على ابنك حتى آخذ منه الصوت الفلاني فقالت نعم وأدخلتني دارها وأمرتني فصعدت إلى علية لها فما لبثت أن جاء ابنها فدخل فقالت له يا سليمان فدتك نفسي أمك قد أصبحت اليوم خاثرة مغرمة فاحب أن تغني ذلك الصوت\n(هما فتاتان لما يعرفا خلقي ... )\nقال لها ومتى حدث لك هذا الطرب قالت ما طربت ولكنني أحببت أن أتفرج من هم قد لحقني فاندفع فغناه فما سمعت أحسن من غنائه فقالت له أمه أحسنت فديتك فقد والله كشفت عني قطعة من همي فأسألك أن تعيده قال والله ما لي نشاط ولا أشتري غمي بفرجك فقالت أعده مرتين ولك درهم صحيح تشتري به ناطفا قال\nومن أين لك درهم ومتى حدث لك هذا السخاء فقالت هذا فضول لا تحتاج إليه وأخرجت إليه درهما فأعطته إياه فأخذه وغناه مرتين فدار لي وكاد يستوي فأومأت إليها من فوق أن تستزيده فقالت يا بني بحقي عليك إلا أعدته فقال أظن أنك تريدين أن تأخذيه فتصيري مغنية فقالت نعم كذا هو قال لا وحق القبر لا أعدته إلا بدرهم آخر فأخرجت له درهما آخر فأخذه وقال أظنك والله قد تزندقت وعبدت الكبش فهو ينقد لك هذه الدراهم أو قد وجدت كنزا فغناه مرتين وأخذته واستوى لي ثم قام فخرج يعدو على وجهه فجئت إلى الرشيد فغنيته به وأخبرته بالقصة فطرب وضحك وأمر لي بألف دينار وقال لي هذه بدل مائتي الدرهم\n(ولقد قالت لأتراب لها ... كالمها يلعبن في حجرتها)\n(خذن عني الظل لا يتبعني ... وعدت سعيا إلى قبتها)\n(لم يصبها نكد فيما مضى ... ظبية تختال في مشيتها)\nفي هذه الأبيات رمل بالبنصر ذكر الهشامي أنه لابن جامع المكي وذكر ابن المكي أنه لابن سريج وهو في أخبار ابن سريج وأغانيه غير مجنس\n(يمشون فيها بكل سابغة ... أحكم فيها القتير والحلق)\n(تعرف إنصافهم إذا شهدوا ... وصبرهم حين تشخص الحدق)\nلغناء لابن محرز خفيف ثقيل بالوسطى عن الهشامي وحبش\n\n(يجحدنني ديني النهار وأقتضي ... ديني إذا وقذ النعاس الرقدا)\n(وأرى الغواني لا يواصلن امرأ ... فقد الشباب وقد يصلن الأمردا)\nلشعر للأعشى والغناء لمعبد خفيف ثقيل بالوسطى عن عمرو\n(أية حال يابن رامين ... حال المحبين المساكين)\n(تركتهم موتى وما موتوا ... قد جرعوا منك الأمرين)\n(وسرت في ركب على طية ... ركب تهام ويمانين)\n(يا راعي الذود لقد رعتهم ... ويلك من روع المحبين)\nالشعر لإسماعيل بن عمار الأسدي والغناء لمحمد بن الأشعث بن فجوة الزهري الكوفي ولحنه خفيف ثقيل مطلق في مجرى الوسطى عن الهشامي وأحمد بن المكي","topic":"أخبار علويه ونسبه","topicNo":126,"sp":10,"spl":"إسحاق يأخذ صوتا من سليمان المصاب","song":4,"loc":2133,"partialRef":{"sid":"b126-16","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b127-1","bab":"الجزء 11","sec":"نسب إسماعيل بن عمار وأخباره","page":"ج11 ص367","text":"هو إسماعيل بن عمار بن عيينة بن الطفيل بن جذيمة بن عمرو بن خلف بن زبان بن كعب بن مالك بن ثعلبة بن دودان بن أسد بن خزيمة أخبرني بذلك علي بن سليمان الأخفش عن السكري عن ابن حبيب وإسماعيل بن عمار شاعر مقل مخضرم من شعراء الدولتين الأموية والهاشمية وكان ينزل الكوفة قال ابن حبيب كان في الكوفة صاحب قيان يقال له ابن رامين قدمها من الحجاز فكان من يسمع الغناء ويشرب النبيذ يأتونه ويقيمون عنده مثل يحيى بن زياد الحارثي وشراعة بن الزندبوذ ومطيع بن إياس وعبد الله ابن العباس المفتون وعون العبادي الحيري ومحمد بن الأشعث الزهري المغني وكان نازلا في بني أسد في جيران إسماعيل بن عمار فكان إسماعيل يغشاه ويشرب عنده ثم انتقل من جواره إلى بني عائذ الله فكان إسماعيل يزوره هناك على مشقة لبعد ما بينهما وكان لابن رامين جوار يقال لهن سلامة الزرقاء وسعدة وربيحة وكن من أحسن الناس غناء واشترى بعد ذلك\nمحمد بن سليمان سلامة الزرقاء التي يقول فيها محمد بن الأشعث\n(أمسى لسلامة الزرقاء في كبدي ... صدع مقيم طوال الدهر والأبد)\n(لا يستطيع صناع القوم يشعبه ... وكيف يشعب صدع الحب في كبد)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":0,"spl":"نسب إسماعيل بن عمار وأخباره — رثاؤه لابن له مات","loc":2134},
{"id":"b127-2","bab":"الجزء 11","sec":"تشبيبه بجواري ابن رامين","page":"ج11 ص368","text":"وفي جواريه يقول إسماعيل بن عمار\n(هل من شفاء لقلب لج محزون ... صبا وصب إلى رئم ابن رامين)\n(إلى ربيحة إن الله فضلها ... بحسنها وسماع ذي أفانين)\n(وهاج قلبي منها مضحك حسن ... ولثغة بعد في زاي وفي سين)\n(نفسي تأبى لكم إلا طواعية ... وأنت تأبين لؤما أن تطيعيني)\n(وتلك قسمة ضيزي قد سمعت بها ... وأنت تتلينها ما ذاك في الدين)\n(إن تسعفيني بذاك الشيء أرض به ... وإن ضننت به عني فزنيني)\n(أنت الطبيب لداء قد تلبس بي ... من الجوى فانفثي في في وارقيني)\n(نعم شفاؤك منها أن تقول لها ... أضنيتني يوم دير اللج فاشفيني)\n(يا رب إن ابن رامين له بقر ... عين وليس لنا غير البراذين)\n(لو شئت أعطيته مالا على قدر ... يرضى به منك غير الربرب العين)\n(لا أنس سعدة والزرقاء يوم هما ... باللج شرقية وفوق الدكاكين)\n(يغنيان ابن رامين على طرب ... بالمسجحي وتشبيب المحبين)\n(أذاك أنعم أم يوم ظللت به ... فراشي الورد في بستان شورين)\n(يشوي لنا الشيخ شورين دواجنه ... بالجردناج وسحاج الشقابين)\n(نسقى طلاء لعمران يعتقه ... يمشي الأصحاء منه كالمجانين)\n(يزل أقدامنا من بعد صحتها ... كأنها ثقلا يقلعن من طين)\n(نمشي وأرجلنا مطوية شللا ... مشي الإوز التي تأتي من الصين)\n(أو مشي عميان دير لا دليل لهم ... سوى العصي إلى يوم السعانين)\n(في فتية من بني تيم لهوت بهم ... تيم بن مرة لا تيم العديين)\n(حمر الوجوه كأنا من تحشمنا ... حسناء شمطاء وافت من فلسطين)\n(ما عائذ الله لولا أنت من شجني ... ولا ابن رامين لولا ما يمنيني)\n(في عائذ الله بيت ما مررت به ... إلا وجئت علي قلبي بسكين)\n(يا سعدة القينة الخضراء أنت لنا ... أنس لأنك في دار ابن رامين)\n(ما كنت أحسب أن الأسد تؤنسني ... حتى رأيت إليك القلب يدعوني)\n(لولا ربيحة ما استأنست ما عمدت ... نفسي إليك ولو مثلت من طين)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":0,"spl":"نسب إسماعيل بن عمار وأخباره — رثاؤه لابن له مات","loc":2135},
{"id":"b127-3","bab":"الجزء 11","sec":"محمد بن سليمان اشترى سلامة الزرقاء بمائة ألف درهم","page":"ج11 ص369","text":"قال وحج ابن رامين وحج بجواريه معه وكان محمد بن سليمان إذ ذاك على الحجاز فاشترى منه سلامة الزرقاء بمائة ألف درهم\nفقال إسماعيل بن عمار\n(أية حال يا ابن رامين ... حال المحبين المساكين)\n(تركتهم موتى وما موتوا ... قد جرعوا منك الأمرين)\n(وسرت في ركب على طية ... ركب تهام ويمانين)\n(حججت بيت الله تبغي به البر ... ولم ترث لمحزون)\n(يا راعي الذود لقد رعتهم ... ويلك من روع المحبين)\n(فرقت قوما لا يرى مثلهم ... ما بين كوفان إلى الصين)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":0,"spl":"نسب إسماعيل بن عمار وأخباره — رثاؤه لابن له مات","loc":2136},
{"id":"b127-4","bab":"الجزء 11","sec":"رثاؤه لابن له مات","page":"ج11 ص370","text":"أخبرني علي بن سليمان الأخفش قال حدثنا السكري عن محمد قال كان لإسماعيل بن عمار ابن يقال له معن فمات فقال يرثيه\n(يا موت ما لك مولعا بضراري ... إني عليك وإن صبرت لزاري)\n(تعدو علي كأنني لك واتر ... وأؤول منك كما يؤول فراري)\n(نفس البعيد إذا أردت قريبة ... ليست بناجية مع الأقدار)\n(والمرء سوف وإن تطاول عمره ... يوما يصير لحفرة الحفار)\n(لما غلا عظم به فكأنه ... من حسن بنيته قضيب نضار)\n(فجعتني بأعز أهلي كلهم ... تعدو عليه عدوة الجبار)\n(هلا بنفسي أو ببعض قرابتي ... أوقعت أو ما كنت للمختار)\n(وتركت ربتي التي من أجلها ... عفت الجهاد وصرت في الأمصار)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":0,"spl":"نسب إسماعيل بن عمار وأخباره — رثاؤه لابن له مات","loc":2137},
{"id":"b127-5","bab":"الجزء 11","sec":"رفض العمل عندما رأى العمال يعذبون","page":"ج11 ص371","text":"أخبرني علي بن سليمان قال حدثني السكري عن محمد بن حبيب قال قال رجل من بني أسد كان وجها لإسماعيل بن عمار هلم أركب معك إلى يوسف بن عمر فإنه صديق حتى أكلمه فيك يستعملك على عمل تنتفع به فقال له إسماعيل دعني حتى يحول الحول فنظر إسماعيل إلى عمال يوسف يعذبون فقال في ذلك\n(رأيت صبيحة النيروز أمرا ... فظيعا عن إمارتهم نهاني)\n(فررت من العمالة بعد يحيى ... وبعد النهشلي أبي أبان)\n(وبعد الزور وابن أبي كثير ... وفيقد أشجع وأبي بطان)\n(فحاب بها أبا عثمان غيري ... فما شأن الإمارة لي بشان)\n(أحاذر أن أقصر في خراجي ... إلى النيروز أو في المهرجان)\n(أعجل إن أتى أجلي بوقت ... وحسبي بالمجرحة المتان)\n(فما عذري إذا عرضت ظهري ... لألف من سياط الشاهجان)\n(تعد ليوسف عدا صحيحا ... ويحفظها عليه الجالدان)\n(وأسحب في سراويلي بقيدي ... إلى حسان معتقل اللسان)\n(فمنهم قائل بعدا وسحقا ... ومنهم آخران يفديان)\n(كفاني من إمارتهم عطائي ... وما أحذيت من سبق الرهان)\n(كفاني ذاك منهم ما بقينا ... كما فيما مضى لي قد كفاني)\nقال ابن حبيب في الإسناد الذي ذكرناه إنه كانت لعبد الرحمن بن عنبسة بن سعيد بن العاصي وصيفة مغنية يؤدبها ويصنعها ليهديها إلى هشام بن عبد الملك يقال لها بوبة فقال فيها إسماعيل بن عمار\n(بوب حييت عن جليسك بوبا ... مخطئا في تحيتي أو مصيبا)\n(ما رأينا قتيل حي حبا القاتل ... بالوتر أن يكون حبيبا)\n(غير ما قد رزقت يا بوب مني ... فهنيئا وإن أتيت عجيبا)\n(غير من به عليك وإن كنت ... بقدر القيان طبا طبيبا)\n(بنت عشر أديبة في قريش ... بخ فأكرم بهم أبا ونسيبا)\n(أدبت في بني أمية حتى ... كملت في حجورهم تأديبا)\nال ثم أهداها ابن عنبسة إلى هشام فقال إسماعيل بن عمار\n(ألا حييت عنا ثم ... سقيا لك يا بوبه)\n(وأكرم بك مهداة ... وأحبب بك مطلوبه)\n(وواها لك من بكر ... وواها لك مثقوبه)\n(وواها لك ملقاة ... وواها لك مكبوبه)\n(لقد عاين من يلقاك ... من حسنك أعجوبه)\n(ويا ويلي ويا عولي ... فنفسي الدهر مكروبه)\n(على هيفاء حوراء ... على جيداء رعبوبه)\n(إذا ضاجعها المولى ... فقد أدرك محبوبه)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":1,"spl":"رفض العمل عندما رأى العمال يعذبون","loc":2138},
{"id":"b127-6","bab":"الجزء 11","sec":"هجاؤه لجارية له","page":"ج11 ص373","text":"قال ابن حبيب في هذه الرواية كان لإسماعيل بن عمار جارية قد ولدت منه وكانت سيئة الخلق قبيحة المنظر وكان يبغضها وتبغضه فقال فيها\n(بليت بزمردة كالعصا ... ألص وأخبث من كندش)\n(تحب النساء وتأبى الرجال ... وتمشي مع الأسفه الأطيش)\n(لها وجه قرد إذا ازينت ... ولون كبيض القطا الأبرش)\n(ومن فوقه لمة جثلة ... كمثل الخوافي من المرعش)\n(وبطن خواصره كالوطاب ... زاد على كرش الأكرش)\n(وإن نكهت كدت من نتنها ... أخر على جانب المفرش)\n(وثدي تدلى على بطنها ... كقربة ذي الثلة المعطش)\n(وفخذان بينهما بسطة ... إذا ما مشت مشية المنتشي)\n(وساق يخلخلها خاتم ... كساق الدجاجة أو أحمش)\n(وفي كل ضرس لها أكلة ... أصل من القبر ذي المنبش)\n(ولما رأيت خوا أنفها ... وفيها وإصلال ما تحتشي)\n(إلى ضامر مثل ظلف الغزال ... أشد اصفرارا من المشمش)\n(فررت من البيت من أجلها ... فرار الهجين من الأعمش)\n(وأبرد من ثلج ساتيدما ... إذا راح كالعطب المنفش)\n(وأرسح من ضفدع عثة ... تنق على الشط من مرعش)\n(وأوسع من باب جسر الأمير ... تمر المحامل لم تخدش)\n(فهذي صفاتي فلا تأتها ... فقد قلت طردا لها كشكشي)\nقال ابن حبيب كان في جوار إسماعيل بن عمار رجل من قومه ينهاه عن السكر وهجاء الناس ويعذله وكان إسماعيل له مغضبا فبنى ذلك الرجل مسجدا يلاصق دار إسماعيل وحسنه وشيده وكان يجلس فيه هو وقومه وذوو التستر والصلاح منهم عامة نهارهم فلا يقدر إسماعيل أن يشرب في داره ولا يدخل إليه أحد ممن كان يألفه من مغن أو مغنية أو غيرهما من أهل الريبة فقال اسماعيل يهجوه وكان الرجل يتولى شيئا من الوقوف للقاضي بالكوفة\n(بنى مسجدا بنيانه من خيانة ... لعمري لقدما كنت غير موفق)\n(كصاحبة الرمان لما تصدقت ... جرت مثلا للخائن المتصدق)\n(يقول لها أهل الصلاح نصيحة ... لك الويل لا تزني ولا تتصدقي)\nقال ابن حبيب ولي العسس رجل غاضري فأخذ بني مالك وهم رهط إسماعيل بن عمار بان كانوا معه فطافوا الى الغداة فلما أصبح غدا على الوالي مستعديا على الغاضري فقال له الوالي وكان رجلا من همدان ماذا صنع بك فأنشأ يقول\n(عس بنا ليلته كلها ... ما نحن في دنيا ولا آخره)\n(يأمر أشياخ بني مالك ... أن يحرسوا دون بني غاضره)\n(والله لا يرضى بذا كائنا ... من حكم همدان إلى الساهره)\nقال فقال له الوالي قد لعمري صدقت ووظف على سائر البطون أن يطوفوا مع صاحب العسس في عشائرهم ولا يتجاوزوا قبيلة إلى قبيلة ويكون ذلك بنوائب بينهم","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":2,"spl":"هجاؤه لجارية له — انقطع إلى خالد بن خالد بن الوليد ورثاه حين مات","loc":2139},
{"id":"b127-7","bab":"الجزء 11","sec":"انقطع إلى خالد بن خالد بن الوليد ورثاه حين مات","page":"ج11 ص376","text":"وقال ابن حبيب كان اسماعيل بن عمار منقطعا إلى خالد بن خالد بن الوليد بن عقبة بن أبي معيط وكان إليه محسنا وكان ينادمه\nفولي خالد بن خالد عملا للوليد بن يزيد بن عبد الملك فخرج إليه وكان إسماعيل عليلا فتأخر عنه ثم لم يلبث خالد أن مات في عمله فورد نعيه الكوفة في يوم فطر\nفقال إسماعيل بن عمار يرثيه\n(ما لعيني تفيض غير جمود ... ليس ترقا ولا لها من هجود)\n(فإذا قرت العيون استهلت ... فإذا نمن أولعت بالسهود)\n(ألنعي ابن خالد خالد الخيرات ... في يوم زينة مشهود)\n(سنحت لي يوم الخميس غداة الفطر ... طير بالنحس لا بالسعود)\n(فتعيفت أنهن لأمر ... مفظع ما جرين في يوم عيد)\n(فنعت خالد بن أروى وجل الخطب ... فقدان خالد بن الوليد)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":2,"spl":"هجاؤه لجارية له — انقطع إلى خالد بن خالد بن الوليد ورثاه حين مات","loc":2140},
{"id":"b127-8","bab":"الجزء 11","sec":"حبسه السلطان عندما وشي به","page":"ج11 ص377","text":"وقال ابن حبيب كان لإسماعيل بن عمار جار يقال له عثمان بن درباس فكان يؤذيه ويسعى به الى السلطان في كل حال ثم سعى به أنه يذهب مذهب الشراة فأخذ وحبس فقال يهجوه\n(من كان يحسدني جاري ويغبطني ... من الأنام بعثمان بن درباس)\n(فقرب الله منه مثله أبدا ... جارا وأبعد منه صالح الناس)\n(جار له باب ساج مغلق أبدا ... عليه من داخل حراس أحراس)\n(عبد وعبد وبنتاه وخادمه ... يدعون مثلهم ما ليس من ناس)\n(صفر الوجوه كأن السل خامرهم ... وما بهم غير جهد الجوع من باس)\n(له بنون كأطباء معلقة ... في بطن خنزيرة في دار كناس)\n(إن يفتح الباب عنهم بعد عاشرة ... تظنهم خرجوا من قعر أرماس)\n(فليت دار ابن درباس معلقة ... بالنجم بين سلاليم وأمراس)\n(فكان آخر عهدي منهم أبدا ... وابتعت دارا بغلماني وأفراسي)\nال وقال فيه أيضا\n(ليت برذوني وبغلي ... وجوادي وحماري)\n(كن في الناس وأبدلت ... غدا جارا بجار)\n(جار صدق بابن درباس ... وإلا بعت داري)\n(فتبدلت به من ... يمن أو من نزار)\n(بدلا يعرف ما الله ... وما حق الجوار)\n(لو تبدلت سواه ... طاب ليلي ونهاري)\n(واسترحنا من بلاياه ... صغار أو كبار)\n(لو جزيناه بها كنا ... جميعا في فجار)\n(أو سكتنا كان ذلا ... داخلا تحت الشعار)\nال فلما قال فيه الشعر استعدى عليه السلطان وذكر أنه من الشراة وأنهم مجتمعون عنده وأنه من دعاة عبد الله بن يحيى وأبي حمزة المختار فكتب من السجن إلى ابن أخ له يقال له معان\n(أبلغ معانا عني وإخوته ... قولا وما عالم كمن جهلا)\n(بأنني والمصبحات منى ... يعدون طورا وتارة رملا)\n(لخائف أن يكون ودكم ... إياي بعد الصفاء قد أفلا)\n(أئن عراني دهري بنائبة ... أصبح منها الفؤاد مشتعلا)\n(حاولتم الصرم أو لعلكم ... ظننتم ما أصابني جللا)\n(لا تغفلونا بني أخي فلقد ... أصبحت لا أبتغي بكم بدلا)\n(تمسكوا بالذي امتسكت به ... فإن خير الإخوان من وصلا)\nال فكتب إليه ابن أخيه\n(يا عم عوفيت من عذابهم النكر ... وفارقت سجنهم عجلا)\n(كتبت تشكو بني أخيك وقد ... أرسل من كان قبلنا مثلا)\n(ابدأهم بالصراخ ينهزموا ... فأنت يا عم تبتغي العللا)\n(زعمت أنا نرى بلاءك في ... دار بلاء مكبلا جللا)\n(يا عم بئس الفتيان نحن إذا ... أما وفي رجلك الكبول فلا)\n(علي إن كنت صادقا حجج ... للبيت عامين حافيا رجلا)\n(بعد عنك الهموم فارج من الله ... خلاصا وأحسن الأملا)","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":3,"spl":"حبسه السلطان عندما وشي به","loc":2141},
{"id":"b127-9","bab":"الجزء 11","sec":"شعره في الحكم بن الصلت بعد ان اطلقه من السجن","page":"ج11 ص379","text":"قال ثم ولي الحكم بن الصلت فأطلقه وأحسن إليه فلم يزل يشكره ويمدحه ثم عزل الحكم بعد ذلك فقال إسماعيل فيه\n(تبارك الله كيف أوحشت الكوفة ... أن لم يكن بها الحكم)\n(الحكم العدل في رعيته الكامل ... فيه العفاف والفهم)\n(فأصبح القصر والسريران والمنبر ... كالكل من أب يتم)\n(يذري عليه السرير عبرته ... والمبتر المشرفي يلتدم)\n(والناس من حسن سيرة الحكم بن ... الصلت يبكون كلما ظلموا)\n(مثل السكارى في فرط وجدهم ... إلا عدوا عليه يتهم)\n(يوم جرى طائر النحوس لهم ... ينزع منه القرطاس والقلم)\n(فأرغم الله حاسديه كما ... أرغم هود القرود إذ رغموا)\n(في سبتهم يوم ناب خطبهم ... والله ممن عصاه ينتقم)\n(إنا إلى الله راجعون أما ... للناس عهد يوفى ولا ذمم)\n(حول علينا وليلتان لنا ... من لذة العيش بئسما حكموا)\n(لا حكم إلا لله يظهره ... يقضي لضيزائها التي قسموا)\n(ماذا ترجي من عيشها مضر ... إن كان من شأنها الذي زعموا)\nقال ابن حبيب سمع اسماعيل بن عمار رجلا ينشد أبياتا للفرزدق يهجو بها عمر بن هبيرة الفزاري لما ولي العراق ويعجب من ولايته إياها وكان خالد القسري قد ولي في تلك الأيام العراق فقال إسماعيل أعجب والله مما عجب منه الفرزدق من ولاية ابن هبيرة وهو ما لست أراه يعجب منه ولاية خالد القسري وهو مخنث دعي ابن دعي ثم قال\n(عجب الفرزدق من فزارة أن رأى ... عنها أمية بالمشارق تنزع)\n(فلقد رأى عجبا وأحدث بعده ... أمر تطير له القلوب وتفزع)\n(بكت المنابر من فزارة شجوها ... فالآن من قسر تصيح وتجزع)\n(فملوك خندف أضرعونا للعدا ... لله در ملوكنا ما تصنع)\n(كانوا كقاذفة بنيها ضلة ... سفها وغيرهم ترب وترضع)\nخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثنا عبد الله بن سعيد بن أسيد العامري قال حدثني محمد بن أنس الأسدي قال جلست إلى إسماعيل بن عمار وإذا هو يفتل أصابعه متأسفا فقلت علام هذا التأسف والتلهف فقال\n(عيناي مشؤومتان ويحهما ... والقلب حران مبتلى بهما)\n(عرفتاه الهوى لظلمهما ... يا ليتني قبل ذا عدمتهما)\n(هما إلى الحين دلتا وهما ... ذل على من أحب دمعهما)\n(سأعذر القلب في هواه وما ... سبب كل البلاء غيرهما)\n\n(فكعبة نجران حتم عليك ... حتى تناخي بأبوابها)\n(نزور يزيد وعبد المسيح ... وقيسا هم خير أربابها)\n(وشاهدنا الجل والياسمين ... والمسمعات بقصابها)\n(وبربطنا دائم معمل ... فأي الثلاثة أزرى بها)\n(إذا الحبرات ناحت بهم ... وجروا أسافل هدابها)\n(فلما التقينا على آية ... ومدت إلي بأسبابها)\nروضه من المتقارب الشعر للأعشى يمدح بني عبد المدان الحارثيين من بني الحارث بن كعب والغناء لحنين خفيف ثقيل بالوسطى في مجراها عن إسحاق وذكر يونس أن فيه لحنا لمالك وزعم عمرو بن بانة أنه خفيف ثقيل وزعم أبو عبد الله الهشامي أن فيه لابن المكي خفيف رمل بالوسطى أوله\n(تنازعني إذ خلت بردها ... )\nومعه باقي الأبيات مخلطة مقدمة ومؤخرة والكعبة التي عناها الأعشى ها هنا يقال إنها بيعة بناها بنو عبد المدان على بناء الكعبة وعظموها مضاهاة للكعبة وسموها كعبة نجران وكان فيها أساقفة يقيمون وهم الذين جاؤوا إلى النبي ودعاهم إلى المباهلة وقيل بل هي قبة من أدم سموها الكعبة وكان إذا نزل بها مستجير أجير أو خائف أمن أو طالب حاجة قضيت أو مسترفد أعطي ما يريده والمسمعات القيان والقصاب أوتار العيدان وقال الأصمعي قلت لبعض الأعراب أنشدني شيئا من شعرك قال كنت أقول الشعر وتركته فقلت ولم ذاك قال لأنني قلت شعرا وغنى فيه حكم الوادي وسمعته فكاد يذهل عقلي فآليت ألا أقول شعرا وما حرك حكم قصابه إلا توهمت أن الله عز و جل مخلدي بها في النار","topic":"نسب إسماعيل بن عمار وأخباره","topicNo":127,"sp":4,"spl":"شعره في الحكم بن الصلت بعد ان اطلقه من السجن","song":1,"loc":2142,"partial":1},
{"id":"b128-1","bab":"الجزء 12","sec":"بسم الله الرحمن الرحيم أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","page":"ج12 ص5","text":"أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثنا العمري عن الهيثم بن عدي عن حماد الراوية عن سماك بن حرب عن يونس بن متى راوية الأعشى قال\nكان لبيد مجبرا حيث يقول\n(من هداه سبل الخير اهتدى ... ناعم البال ومن شاء أضل)\nكان الأعشى قدريا حيث يقول\n(استأثر الله بالوفاء وبالعدل ... وولى الملامة الرجلا)\nقلت له من أين أخذ هذا فقال أخذه من أساقفة نجران وكان يعود في كل سنة إلى بني عبد المدان فيمدحهم ويقيم عندهم يشرب الخمر معهم وينادمهم ويسمع من أساقفة نجران قولهم فكل شيء في شعره من هذا فمنهم أخذه","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":0,"spl":"بسم الله الرحمن الرحيم أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره — خبر أساقفة نجران مع","loc":2143},
{"id":"b128-2","bab":"الجزء 12","sec":"خبر أساقفة نجران مع النبي","page":"ج12 ص6","text":"فأما خبر مباهلتهم النبي فأخبرني به علي بن العباس بن الوليد البجلي المعروف بالمقانعي الكوفي قال أنبأنا بكار بن أحمد بن اليسع الهمداني قال حدثنا عبد الله بن موسى عن أبي حمزة عن شهر بن حوشب قال بكار\nوحدثنا إسماعيل بن أبان العامري عن عيسى بن عبد الله بن محمد بن عمر بن علي عن أبيه عن جده عن علي عليه السلام وحديثه أتم الأحاديث وحدثني به جماعة آخرون بأسانيد مختلفة وألفاظ تزيد وتنقص فممن حدثني به علي بن أحمد بن حامد التميمي قال حدثنا الحسن بن عبد الواحد قال حدثنا حسن بن حسين عن حيان بن علي عن الكلبي عن أبي صالح عن ابن عباس وعن الحسن بن الحسين عن محمد بن بكر عن محمد بن عبد الله بن علي بن أبي رافع عن أبيه جده عن أبي رافع وأخبرني علي بن موسى الحميري في كتابه قال حدثنا جندل بن والق قال حدثنا محمد بن عمر عن عباد الكليبي عن كامل أبي العلاء عن أبي صالح عن ابن عباس وأخبرني أحمد بن الحسين بن سعد بن عثمان إجازة قال حدثنا أبي قال حدثنا حصين بن مخارق عن عبد الصمد بن علي عن أبيه عن ابن عباس قال الحصين وحدثني أبو الجارود وأبو حمزة الثمالي عن أبي جعفر قال وحدثني حمد بن سالم وخليفة بن حسان عن زيد بن علي عليه السلام قال حصين وحدثني\nسعيد بن طريف عن عكرمة عن ابن عباس وممن حدثني أيضا بهذا الحديث علي بن العباس عن بكار عن إسماعيل بن أبان عن أبي أويس المدني عن جعفر بن محمد وعبد الله والحسن ابني الحسن وممن حدثني به أيضا محمد بن الحسين الأشناني قال حدثنا إسماعيل بن إسحاق الراشدي قال حدثني يحيى بن سالم عن جابر عن أبي جعفر عليه السلام وممن أخبرني به أيضا الحسين بن حمدان بن أيوب الكوفي عن محمد بن عمرو الخشاب عن حسين الأشقر عن شريك عن جابر عن أبي جعفر وعن شريك عن المغيرة عن الشعبي واللفظ للحديث الأول قالوا قدم وفد نصارى نجران وفيهم الأسقف والعاقب وأبو حبش والسيد وقيس وعبد المسيح وابن عبد المسيح الحارث وهو غلام وقال شهر بن حوشب في حديثه وهم أربعون حبرا حتى وقفوا على اليهود في بيت\nالمدارس فصاحوا بهم يابن صوريا يا كعب بن الأشرف انزلوا يا إخوة القرود والخنازير فنزلوا إليهم فقالوا لهم هذا الرجل عندكم منذ كذا وكذا سنة قد غلبكم أحضروا الممتحنة لنمتحنه غدا فلما صلى النبي الصبح قاموا فبركوا بين يديه ثم تقدمهم الأسقف فقال يا أبا القاسم موسى من أبوه قال عمران قال فيوسف من أبوه قال يعقوب قال فأنت من أبوك قال أبي عبد الله بن عبد المطلب قال فعيسى من أبوه فسكت رسول الله وآله فانقض عليه جبريل عليه السلام فقال ( إن مثل عيسى عند الله كمثل آدم خلقه من تراب\nفتلاها رسول الله فنزا الاسقف ثم دير به مغشيا عليه ثم رفع رأسه إلى النبي فقال له أتزعم أن الله جل وعلا أوحى إليك أن عيسى خلق من تراب ما نجد هذا فيما أوحي إليك ولا نجده فيما أوحي إلينا ولا تجده هؤلاء اليهود فيما أوحي إليهم فأوحى الله تبارك وتعالى إليه ( فمن حاجك فيه من بعدما جاءك من العلم فقل تعالوا ندع أبناءنا وأبناءكم ونساءنا ونساءكم وأنفسنا وأنفسكم ثم نبتهل فنجعل لعنة الله على الكاذبين\nفقال أنصفتنا يا أبا القاسم فمتى","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":0,"spl":"بسم الله الرحمن الرحيم أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره — خبر أساقفة نجران مع","loc":2144},
{"id":"b128-3","bab":"الجزء 12","sec":"خبر أساقفة نجران مع النبي","page":"ج12 ص6","text":"نباهلك فقال بالغداة إن شاء الله تعالى وانصرف النصارى وانصرفت اليهود وهي تقول والله ما نبالي أيهما أهلك الله الحنيفية أو النصرانية فلما صارت النصارى إلى بيوتها قالوا والله إنكم لتعلمون أنه نبي ولئن باهلناه إنا لنخشى أن نهلك ولكن استقيلوه لعله يقيلنا وغدا النبي من الصبح وغدا معه بعلي وفاطمة والحسن والحسين صلوات الله عليهم فلما صلى الصبح انصرف فاستقبل الناس بوجهه ثم برك باركا وجاء بعلي فأقامه بين يديه وجاء بفاطمة فأقامها بين كتفيه وجاء بحسن فأقامه عن يمينه وجاء بحسين فأقامه عن يساره فأقبلوا يستترون بالخشب والمسجد فرقا أن يبدأهم بالمباهلة إذا رآهم حتى بركوا بين يديه ثم صاحوا يا أبا القاسم أقلنا أقالك الله عثرتك فقال النبي نعم قال ولم يسأل النبي شيئا قط إلا أعطاه فقال قد أقلتكم فولوا فلما ولوا قال النبي أما والذي بعثني بالحق لو باهلتهم ما بقي على وجه الأرض نصراني ولا نصرانية إلا أهلكهم الله تعالى وفي حديث شهر بن حوشب أن العاقب وثب فقال أذكركم الله أن نلاعن هذا الرجل فوالله لئن كان كاذبا ما لكم في ملاعنته خير ولئن كان صادقا لا يحول الحول ومنكم نافخ ضرمة فصالحوه ورجعوا","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":1,"spl":"خبر أساقفة نجران مع النبي","loc":2145},
{"id":"b128-4","bab":"الجزء 12","sec":"قبة الأدم بنجران","page":"ج12 ص10","text":"وأما خبر القبة الأدم التي ذكرها الأعشى فأخبرني بخبرها عمي وحبيب بن نصر المهلبي قالا حدثنا عبد الله بن أبي سعد قال حدثني علي بن عمرو الأنصاري عن هشام بن محمد عن أبيه قال\nكان عبد المسيح بن دارس بن عربي بن معيقر من أهل نجران وكانت له قبة من ثلاثمائة جلد أديم وكان على نهر بنجران يقال النحيردان قال ولم يأت القبة خائف إلا أمن ولا جائع إلا شبع وكان يستغل من ذلك النهر عشرة آلاف دينار وكانت القبة تستغرق ذلك كله وكان أول من نزل نجران من بني الحارث بن كعب يزيد بن عبد المدان بن الديان وذلك أن عبد المسيح بن دارس زوج يزيد بن عبد المدان ابنته رهيمة فولدت له عبد الله بن يزيد فهم بالكوفة ومات عبد المسيح فانتقل ماله إلى يزيد فكان أول حارثي حل في نجران وفي ذلك يقول أعشى قيس بن ثعلبة\n(فكعبة نجران حتم عليك ... حتى تناجي بأبوابها)\n(نزور يزيد وعبد المسيح ... وقيسا هم خير أربابها)\nأخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه قال حدثني بعض بني الحارث بن كعب وأخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني عبد الله بن الصباح عن ابن الكلبي عن أبيه قال\nاجتمع يزيد بن عبد المدان وعامر بن الطفيل بموسم عكاظ وقدم أمية بن الأسكر الكناني ومعه ابنة له من أجمل أهل زمانها فخطبها يزيد وعامر فقالت أم كلاب امرأة أمية بن الأسكر من هذان الرجلان فقال هذا يزيد بن عبد المدان بن الديان وهذا عامر بن الطفيل فقالت أعرف بني الديان ولا أعرف عامرا فقال هل سمعت بملاعب الأسنة فقالت نعم قال فهذا ابن أخيه وأقبل يزيد فقال يا أمية أنا ابن الديان صاحب الكثيب ورئيس مذحج ومكلم العقاب ومن كان يصوب أصابعه فتنطف دما ويدلك راحتيه فتخرجان ذهبا فقال أمية بخ بخ فقال عامر\nجدي الأخرم وعمي ملاعب الأسنة وأبي فارس قرزل فقال أمية بخ بخ مرعى ولا كالسعدان فأرسلها مثلا فقال يزيد يا عامر هل تعلم شاعرا من قومي رحل بمدحة إلى رجل من قومك قال اللهم لا قال فهل تعلم أن شعراء قومك يرحلون بمدائحهم إلى قومي قال اللهم نعم قال فهل لكم نجم يمان أو برد يمان أو سيف يمان أو ركن يمان قال لا قال فهل ملكناكم ولم تملكونا قال نعم فنهض يزيد وأنشأ يقول\n(أمي يابن الأسكر بن مدلج ... لا تجعلن هوازنا كمذحج)\n(إنك إن تلهج بأمر تلجج ... ما النبع في مغرسه كالعوسج)\n(ولا الصريح المحض كالممزج ... )\nال قال مرة بن دودان النفيلي وكان عدوا لعامر\n(يا ليت شعري عنك يا يزيد ... ماذا الذي من عامر تريد)\n(لكل قوم فخركم عتيد ... أمطلقون نحن أم عبيد)\n(لا بل عبيد زادنا الهبيد ... )\nقال فزوج أمية يزيد بن عبد المدان ابنته فقال يزيد في ذلك\n(يا للرجال لطارق الأحزان ... ولعامر بن طفيل الوسنان)\n(كانت إتاوة قومه لمحرق ... زمنا وصارت بعد للنعمان)\n(عد الفوارس من هوازن كلها ... فخرا علي وجئت بالديان)\n(فإذا لي الشرف المبين بوالد ... ضخم الدسيعة زانني ونماني)\n(يا عام إنك فارس ذو ميعة ... غض الشباب أخو ندى وقيان)\n(واعلم بأنك بابن فارس قرزل ... دون الذي تسعى له وتداني)\n(ليست فوارس عامر بمقرة ... لك بالفضيلة في بني عيلان)\n(فإذا لقيت بني الحماس ومالك ... وبني الضباب وحي آل قنان)\n(فاسأل عن الرجل المنوه باسمه ... والدافع الأعداء عن نجران)\n(يعطى المقادة في فوارس قومه ... كرما لعمرك والكريم يماني)\nفقال عامر بن الطفيل\n(عجبا لواصف طارق الأحزان ... ولما يجيء به بنو الديان)\n(فخروا علي بحبوة لمحرق ... وإتاوة سيقت إلى النعمان)\n(ما أنت وابن محرق وقبيله ... وإتاوة اللخمي في عيلان)\n(فاقصد بفخرك قصد قومك قصرة ... ودع القبائل من بني قحطان)\n(إن كان سالفة الإتاوة فيكم ... أو لا ففخرك فخر كل يماني)\n(وافخر برهط بني الحماس ومالك ... وبني الضباب وزعبل وقنان)\n(فأنا المعظم وابن فارس قرزل ... وأبو براء زانني ونماني)\n(وأبو جزيء ذو الفعال ومالك ... منعا الذمار صباح كل طعان)\n(وإذا تعاظمت الأمور هوازن ... كنت المنوه باسمه والباني)","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":2,"spl":"قبة الأدم بنجران","loc":2146,"partialRef":{"sid":"b99-8","gi":1,"vi":2,"side":0},"partial":1},
{"id":"b128-5","bab":"الجزء 12","sec":"مرة بن دودان يرفض هجاء بني الديان","page":"ج12 ص15","text":"فلما رجع القوم إلى بني عامر وثبوا على مرة بن دودان وقالوا له أنت من بني عامر وأنت شاعر ولم تهج بني الديان فقال مرة\n(تكلفني هوازن فخر قوم ... يقولون الأنام لنا عبيد)\n(أبونا مذحج وبنو أبيه ... إذا ما عدت الآباء هود)\n(وهل لي إن فخرت بغير حق ... مقال والأنام لهم شهود)\n(فأنى تضرب الأعلام صفحا ... عن العلياء أم من ذا يكيد)\n(فقولوا يا بني عيلان كنا ... لهم قنا فما عنها محيد)\nوقال ابن الكلبي في هذه الرواية قدم يزيد بن عبد المدان وعمرو بن معد يكرب ومكشوح المرادي على ابن جفنة زوارا وعنده وجوه قيس ملاعب الأسنة عامر بن مالك ويزيد بن عمرو بن الصعق ودريد بن الصمة فقال ابن جفنة ليزيد بن عبد المدان ماذا كان يقول الديان إذا أصبح فإنه كان ديانا فقال كان يقول آمنت بالذي رفع هذه يعني السماء ووضع هذه يعني الأرض وشق هذه يعني أصابعه ثم يخر ساجدا ويقول سجد وجهي للذي خلقه وهو عاشم وما جشمني من شيء فإني جاشم فإذا رفع رأسه قال\n(إن تغفر اللهم تغفر جما ... وأي عبد لك ما ألما)\nفقال ابن جفنة إن هذا لذو دين ثم مال على القيسيين وقال ألا تحدثوني عن هذه الرياح الجنوب والشمال والدبور والصبا والنكباء لم سميت بهذه الأسماء فإنه قد أعياني علمها فقال القوم هذه أسماء وجدنا العرب عليها لا نعلم غير هذا فيها فضحك يزيد بن عبد المدان ثم قال يا خير الفتيان ما كنت أحسب أن هذا يسقط علمه على هؤلاء وهم أهل الوبر إن العرب تضرب أبياتها في القبلة مطلع الشمس لتدفئهم في الشتاء وتزول عنهم في الصيف فما هب من الرياح عن يمين البيت فهي الجنوب وما هب عن شماله فهي الشمال وما هب من أمامه فهي الصبا وما هب من خلفه فهي الدبور وما استدار من الرياح بين هذه الجهات فهي النكباء فقال ابن جفنة إن هذا للعلم يابن عبد المدان وأقبل على القيسيين يسألهم عن النعمان بن المنذر فعابوه وصغروه فنظر ابن جفنة إلى يزيد فقال له ما تقول يابن عبد المدان فقال يزيد يا خير الفتيان ليس صغيرا من منعك العراق وشركك في الشام وقيل له أبيت اللعن وقيل لك يا خير الفتيان وألفى أباه ملكا كما ألفيت أباك ملكا فلا يسرك من يغرك فإن هؤلاء لو سألهم عنك النعمان لقالوا فيك مثل ما قالوا فيه وايم الله ما فيهم رجل إلا ونعمة النعمان عنده عظيمة فغضب عامر بن مالك وقال له يابن الديان أما والله لتحتلبن بها دما فقال له ولم أزيد في هوازن من لا أعرفه فقال لا بل هم الذين تعرف فضحك يزيد ثم قال ما لهم جرأة بني الحارث ولا فتك مراد ولا بأس زبيد ولا كيد جعفي ولا مغار طيئ وما هم ونحن يا خير الفتيان بسواء ما قتلنا أسيرا قط ولا اشتهينا حرة قط ولا بكينا قتيلا حتى نسيء به وإن هؤلاء ليعجزون عن ثأرهم حتى يقتل السمي بالسمي والكني بالكني والجار بالجار وقال يزيد بن عبد المدان فيما كان بينه وبين القيسيين شعرا غدا به على ابن جفنة\n(تمالا على النعمان قوم إليهم ... موارده في ملكه ومصادره)\n(على غير ذنب كان منه إليهم ... سوى أنه جادت عليهم مواطره)\n(فباعدهم من كل شر يخافه ... وقربهم من كل خير يبادره)\n(فظنوا وأعراض الظنون كثيرة ... بأن الذي قالوا من الأمر ضائره)\n(فلم ينقصوه بالذي قيل شعرة ... ولا فللت أنيابه وأظافره)\n(وللحارث الجفني أعلم بالذي ... ينوء به النعمان إن خف طائره)\n(فيا حاركم فيهم لنعمان نعمة ... من الفضل والمن الذي أنا ذاكره)\n(ذنوبا عفا عنها ومالا أفاده ... وعظما كسيرا قومته جوابره)\n(ولو سال عنك العائبين ابن منذر ... لقالوا له القول الذي لا يحاوره)\nال فلما سمع ابن جفنة هذا القول عظم يزيد في عينه وأجلسه معه على سريره وسقاه بيده وأعطاه عطية لم يعطها أحدا ممن وفد عليه قط فلما قرب يزيد ركائبه ليرتحل سمع صوتا إلى جانبه وإذا هو رجل يقول\n(أما من شفيع من الزائرين ... يحب الثنا زنده ثاقب)\n(يريد ابن جفنة إكرامه ... وقد يمسح الضرة الحالب)\n(فينقذني من أظافيره ... وإلا فإني غدا ذاهب)\n(فقد قلت يوما على كربة ... وفي الشرب في يثرب غالب)\n(ألا ليت غسان في ملكها ... كلخم وقد يخطئ الشارب)\n(وما في ابن جفنة من سبة ... وقد خف حلمي بها العازب)\n(كأني غريب من الأبعدين ... وفي الحلق مني شجا ناشب)","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":3,"spl":"مرة بن دودان يرفض هجاء بني الديان","loc":2147},
{"id":"b128-6","bab":"الجزء 12","sec":"مرة بن دودان يرفض هجاء بني الديان","page":"ج12 ص15","text":"قال يزيد علي بالرجل فأتي به فقال ما خطبك أنت تقول هذا الشعر قال لا بل قاله رجل من جذام جفاه ابن جفنة وكانت له عند النعمان منزلة فشرب فقال على شرابه شيئا أنكره عليه ابن جفنة فحبسه وهو مخرجه غدا فقاتله فقال له يزيد أنا أغنيك فقال له ومن أنت حتى أعرفك فقال أنا يزيد بن عبد المدان فقال أنت لها وأبيك قال أجل قد كفيتك أمر صاحبك فلا يسمعنك أحد تنشد هذا الشعر وغدا يزيد على ابن جفنة ليودعه فقال له حياك الله يابن الديان حاجتك قال تلحق قضاعة الشأم بغسان وتؤثر من أتاك من وفود مذحج وتهب لي الجذامي الذي لا شفيع له إلا كرمك قال قد فعلت أما إني حبسته لأهبه لسيد أهل ناحيتك فكنت ذلك السيد ووهبه له فاحتمله يزيد معه ولم يزل مجاورا له بنجران في بني الحارث بن كعب وقال ابن جفنة لأصحابه ما كانت يميني لتفي إلا بقتله أو هبته لرجل من بني الديان فإن يميني كانت على هذين الأمرين فعظم بذلك يزيد في عين أهل الشام ونبه ذكره وشرف","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":4,"spl":"مرة بن دودان يرفض هجاء بني الديان","loc":2148},
{"id":"b128-7","bab":"الجزء 12","sec":"يزيد يتدخل لدى قيس بن عاصم لفك أسير","page":"ج12 ص19","text":"وقال ابن الكلبي في هذه الرواية عن أبيه جاور رجلان من هوازن يقال لهما عمرو وعامر في بني مرة بن عوف بن ذبيان وكانا قد أصابا دما في\nقومهما ثم إن قيس بن عاصم المنقري أغار على بني مرة بن عوف بن ذبيان فأصاب عامرا أسيرا في عدة اسارى كانوا عند بني مرة ففدى كل قوم أسيرهم من قيس بن عاصم وتركوا الهوازني فاستغاث أخوه بوجوه بني مرة سنان بن أبي حارثة والحارث بن عوف والحارث بن ظالم\nوهاشم بن حرملة والحصين بن الحمام فلم يغيثوه فركب إلى موسم عكاظ فأتى منازل مذحج ليلا فنادى\n(دعوت سنانا وابن عوف وحارثا ... وعاليت دعوى بالحصين وهاشم)\n(أعيرهم في كل يوم وليلة ... بترك أسير عند قيس بن عاصم)\n(حليفهم الأدنى وجار بيوتهم ... ومن كان عما سرهم غير نائم)\n(فصموا وأحداث الزمان كثيرة ... وكم في بني العلات من متصامم)\n(فيا ليت شعري من لإطلاق غله ... ومن ذا الذي يحظى به في المواسم)\nال فسمع صوتا من الوادي ينادي بهذه الأبيات\n(ألا أيهذا الذي لم يجب ... عليك بحي يجلي الكرب)\n(عليك بذا الحي من مذحج ... فإنهم للرضا والغضب)\n(فناد يزيد بن عبد المدان ... وقيسا وعمرو بن معد يكرب)\n(يفكوا أخاك بأموالهم ... وأقلل بمثلهم في العرب)\n(أولاك الرؤوس فلا تعدهم ... ومن يجعل الرأس مثل الذنب)\nقال فاتبع الصوت فلم ير أحدا فغدا على المكشوح واسمه قيس بن عبد يغوث المرادي فقال له إني وأخي رجلان من بني جشم بن معاوية أصبنا دما في قومنا وإن قيس بن عاصم أغار على بني مرة وأخي فيهم مجاور فأخذه أسيرا فاستغثت بسنان بن أبي حارثة والحارث بن عوف والحارث بن ظالم وهاشم بن حرملة فلم يغيثوني فأتيت الموسم لأصيب به من يفك أخي فانتهيت إلى منازل مذحج فناديت بكذا وكذا فسمعت من الوادي صوتا أجابني بكذا وكذا وقد بدأت بك لتفك أخي فقال له المكشوح والله إن قيس بن عاصم لرجل ما قارضته معروفا قط ولا هو لي بجار ولكن اشتر أخاك منه وعلي الثمن ولا يمنعك غلاؤه ثم أتى عمرو بن معد يكرب فقال له مثل ذلك فقال هل بدأت بأحد قبلي قال نعم بقيس المكشوح قال عليك بمن بدأت به فتركه وأتى يزيد بن عبد المدان فقال له يا أبا النضر إن من قصتي كذا وكذا فقال له مرحبا بك وأهلا أبعث إلى قيس بن عاصم فإن هو وهب لي أخاك شكرته وإلا أغرت عليه حتى يتقيني بأخيك فإن نلتها وإلا دفعت إليك كل أسير من بني تميم بنجران فاشتريت بهم أخاك قال هذا الرضا فأرسل يزيد إلى قيس بن عاصم بهذه الأبيات\n(يا قيس أرسل أسيرا من بني جشم ... إني بكل الذي تأتي به جازي)\n(لا تأمن الدهر أن تشجى بغصته ... فاختر لنفسك إحمادي وإعزازي)\n(فافكك أخا منقر عنه وقل حسنا ... فيما سئلت وعقبه بإنجاز)\nقال وبعث بالأبيات رسولا إلى قيس بن عاصم فأنشده إياها ثم قال له يا أبا علي إن يزيد بن عبد المدان يقرأ عليك السلام ويقول لك إن المعروف قروض ومع اليوم غد فأطلق لي هذا الجشمي فإن أخاه قد استغاث بأشراف بني مرة وبعمرو بن معد يكرب وبمكشوح مراد فلم يصب عندهم حاجته فاستجار بي ولو أرسلت إلي في جميع أسارى مضر بنجران لقضيت حقك فقال قيس بن عاصم لمن حضره من بني تميم هذا رسول يزيد بن عبد المدان سيد مذحج وابن سيدها ومن لا يزال له فيكم يد وهذه فرصة لكم فما ترون قالوا نرى أن نغليه عليه ونحكم فيه شططا فإنه لن يخذله أبدا ولو أتى ثمنه على ماله فقال قيس بئس ما رأيتم أما تخافون سجال الحروب ودول الأيام ومجازاة القروض فلما أبوا عليه قال بيعونيه فأغلوه عليه فتركه في أيديهم وكان أسيرا في يد رجل من بني سعد وبعث إلى يزيد فأعلمه بما جرى وأعلمه أن الأسير لو كان في يده أو في بني منقر لأخذه وبعث به ولكنه في يد رجل من بني سعد فأرسل يزيد إلى السعدي أن سر إلي بأسيرك ولك فيه حكمك فأتى به السعدي يزيد بن عبد المدان فقال له احتكم فقال مائة ناقة ورعاؤها فقال له يزيد إنك لقصير الهمة قريب الغنى جاهل بأخطار بني الحارث أما والله لقد غبتتك يا أخا بني سعد ولقد كنت أخاف أن يأتي ثمنه على جل أموالنا ولكنكم يا بني تميم قوم قصار الهمم وأعطاه ما احتكم فجاوره الأسير وأخوه حتى ماتا عنده بنجران وقال ابن الكلبي أغار عبد المدان على هوازن يوم السلف في جماعة من بني الحارث بن كعب وكانت حمته على بني عامر خاصة فلما التقى","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":5,"spl":"يزيد يتدخل لدى قيس بن عاصم لفك أسير","loc":2149},
{"id":"b128-8","bab":"الجزء 12","sec":"يزيد يتدخل لدى قيس بن عاصم لفك أسير","page":"ج12 ص19","text":"القوم حمل على وبر بن معاوية النميري فصرعه وثنى بطفيل بن مالك فأجره الرمح وطار به فرسه قرزل فنجا واستحر القتل في بني عامر وتبعت خيل بني الحارث من انهزم من بني عامر وفي هذه الخيل عمير ومعقل وكانا من فرسان بني الحارث بن كعب فلم يزالوا بقية يومهم لا يبقون على شيء أصابوه فقال في ذلك عبد المدان\n(عفا من سليمى بطن غول فيذبل ... فغمرة فيف الريح فالمتنخل)\n(ديار التي صاد الفؤاد دلالها ... وأغرت بها يوم النوى حين ترحل)\n(فإن تك صدت عن هواي وراعها ... نوازل أحداث وشيب مجلل)\n(فيا رب خيل قد هديت بشطبة ... يعارضها عبل الجزارة هيكل)\n(سبوح إذا جال الحزام كأنه ... إذا انجاب عنه النقع في الخيل أجدل)\n(يواغل جردا كالقنا حارثية ... عليها قنان والحماس وزعبل)\n(معاقلهم في كل يوم كريهة ... صدور العوالي والصفيح المصقل)\n(وزعف من الماذي بيض كأنها ... نهاء مرتها بالعشيات شمأل)\n(فما ذر قرن الشمس حتى تلاحقت ... فوارس يهديها عمير ومعقل)\n(فجالت على الحي الكلابي جولة ... فباكرهم ورد من الموت معجل)\n(فغادرن وبرا تحجل الطير حوله ... ونجى طفيلا في العجاجة قرزل)\n(فلم ينج إلا فارس من رجالهم ... يخفف ركضا خشية الموت أعزل)\nليزيد بن عبد المدان أخبار مع دريد بن الصمة قد ذكرت مع أخبار دريد في صنعة المعتضد مع أغاني الخلفاء فاستغني عن إعادتها في هذا الموضع","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":6,"spl":"يزيد يتدخل لدى قيس بن عاصم لفك أسير — أخبار عبد الله بن الحشرج","loc":2150},
{"id":"b128-9","bab":"الجزء 12","sec":"زينب بنت مالك ترثي يزيد بن عبد المدان","page":"ج12 ص25","text":"أخبرني علي بن سليمان قال أخبرني أبو سعيد السكري قال حدثني\nمحمد بن حبيب عن ابن الأعرابي وأبي عبيدة وابن الكلبي قالوا أغار يزيد بن عبد المدان ومعه بنو الحارث بن كعب على بني عامر فأسر عامر بن مالك ملاعب الأسنة أبا براء وأخاه عبيدة بن مالك ثم أنعم عليهما فلما مات يزيد بن عبد المدان واسم عبد المدان عمرو وكنيته أبو يزيد وهو ابن الديان بن قطن بن زياد بن الحارث بن مالك بن ربيعة بن كعب بن الحارث بن كعب بن عمرو قالت زينب بنت مالك بن جعفر بن كلاب أخت ملاعب الأسنة ترثي يزيد بن عبد المدان\n(بكيت يزيد بن عبد المدان ... حلت به الأرض أثقالها)\n(شريك الملوك ومن فضله ... يفضل في المجد أفضالها)\n(فككت أسارى بني جعفر ... وكندة إذ نلت أقوالها)\n(ورهط المجالد قد جللت ... فواضل نعماك أجبالها)\nقالت أيضا ترثيه\n(سأبكي يزيد بن عبد المدان ... على أنه الأحلم الأكرم)\n(رماح من العزم مركوزة ... ملوك إذا برزت تحكم)\nال فلامها قومها في ذلك وعيروها بأن بكت يزيد فقالت زينب\n(ألا أيها الزاري علي بأنني ... نزارية أبكي كريما يمانيا)\n(ومالي لا أبكي يزيد وردني ... أجر جديدا مدرعي وردائيا)\n\n(أطل حمل الشناءة لي وبغضي ... وعش ما شئت فانظر من تضير)\n(إذا أبصرتني أعرضت عني ... كأن الشمس من قبلي تدور)\nلشعر لعبد الله بن الحشرج الجعدي والغناء لابن سريج ثقيل أول بالبنصر عن الهشامي","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":6,"spl":"يزيد يتدخل لدى قيس بن عاصم لفك أسير — أخبار عبد الله بن الحشرج","song":1,"loc":2151},
{"id":"b128-10","bab":"الجزء 12","sec":"أخبار عبد الله بن الحشرج","page":"ج12 ص28","text":"هو عبد الله بن الحشرج بن الأشهب بن ورد بن عمرو بن ربيعة بن جعدة ابن كعب بن ربيعة بن عامر بن صعصعة بن معاوية بن بكر بن هوازن وكان عبد الله بن الحشرج سيدا من سادات قيس وأميرا من أمرائها ولي أكثر أعمال خراسان ومن أعمال فارس وكرمان وكان جوادا ممدحا وفيه يقول زياد الأعجم\n(إن السماحة والشجاعة والندى ... في قبة ضربت على ابن الحشرج)\nله يقول أيضا\n(إذا كنت مرتاد السماحة والندى ... فسائل تخبر عن ديار الأشاهب)\nسبه إلى الأشهب جده وفي بني الأشهب يقول نابغة بني جعدة\n(أبعد فوارس يوم الشريف ... آسى وبعد بني الأشهب)\nكان أبوه الحشرج بن الأشهب سيدا شاعرا وأميرا كبيرا وكان غلب على قهستان في زمن عبد الله بن خازم فبعث إليه عبد الله بن خازم المسيب بن أوفى القشيري فقتل الحشرج وأخذ قهستان وكان عمه زياد بن الأشهب أيضا شريفا سيدا وكان قد سار إلى أمير المؤمنين علي بن أبي طالب عليه السلام يصلح بينه وبين معاوية على أن يوليه الشأم فلم يجبه وفي ذلك يقول نابغة بني جعدة يعتد على معاوية\n(وقام زياد عند باب بن هاشم ... يريد صلاحا بينكم ويقرب)","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":6,"spl":"يزيد يتدخل لدى قيس بن عاصم لفك أسير — أخبار عبد الله بن الحشرج","loc":2152},
{"id":"b128-11","bab":"الجزء 12","sec":"قدامة بن الأحرز يمدح ابن الحشرج","page":"ج12 ص29","text":"أخبرني محمد بن خلف بن المرزبان قال حدثني أحمد بن الهيثم بن\nفراس قال حدثنا العمري عن عطاء بن مصعب عن عاصم بن الحدثان قال جاء إلى عبد الله بن الحشرج وهو بقهستان رجل من قشير يقال له قدامة ابن الأحرز فدخل عليه وأنشأ يقول\n(أخ وابن عم جاءكم متحرما ... بكم فارأبوا خلاته يابن حشرج)\n(فأنت ابن ورد سدت غير مدافع ... معدا على رغم المنوط المعلهج)\n(فبرزت عفوا إذ جريت ابن حشرج ... وجاء سكيتا كل أعقد أفحج)\n(سبقت ابن ورد كل حاف وناعل ... بجد إذا حار الأضاميم ممعج)\n(بورد بن عمر فتهم إن مثله ... قليل ومن يشر المحامد يفلج)\n(هو الواهب الأموال والمشتري اللها ... وضراب رأس المستميت المدجج)\nال فأعطاه أربعة آلاف درهم وقال اعذرني يابن عمي فإني في حالة الله بها عليم من كثرة الطلاب وأنت أحق من عذرني قال والله لو\nلم تعطني شيئا مع ما أعلمه من جميل رأيك في عشيرتك ومن انقطع إليك لعذرتك فكيف وقد أجزلت العطاء وأرغمت الأعداء وكان لابن الحشرج ابن عم يقول للقشيري ويحك ليس عنده خير وهو يكذبك ويملذك فبلغ ذلك عبد الله بن الحشرج فقال\n(أطل حمل الشناءة يل وبغضي ... وعش ما شئت فانظر من تضير)\n(فما بيديك خير أرتجيه ... وغير صدودك الخطب الكبير)\n(إذا أبصرتني أعرضت عني ... كأن الشمس من قبلي تدور)\n(وكيف تعيب من تمسي فقيرا ... إليه حين تحزبك الأمور)\n(ومن إن بعت منزلة بأخرى ... حللت بأمره وبه تسير)\n(أتزعم أنني ملذ كذوب ... وأن المكرمات لدي بور)\n(وكيف أكون كذابا ملوذا ... وعندي يطلب الفرج الضرير)\n(أواسي في النوائب من أتاني ... ويجبر بي أخو الضر الفقير)","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":7,"spl":"قدامة بن الأحرز يمدح ابن الحشرج","loc":2153},
{"id":"b128-12","bab":"الجزء 12","sec":"كرم عبد الله بن الحشرج","page":"ج12 ص32","text":"أخبرني محمد بن خلف قال حدثنا أحمد بن الهيثم عن العمري عن عطاء ابن مصعب عن عاصم بن الحدثان قال أعطى عبد الله بن الحشرج بخراسان حتى أعطى منشفة كانت عليه وأعطى فراشه ولحافه فقالت له امرأته لشد ما تلاعب بك الشيطان وصرت من إخوانه مبذرا كما قال الله عز و جل ( إن المبذرين كانوا إخوان الشياطين\nفقال عبد الله بن الحشرج لرفاعة بن زوي النهدي وكان أخا له وصديقا يا رفاعة ألا تسمع إلى ما قالت هذه الورهاء وما تتكلم به فقال صدقت والله وبرت إنك لمبذر وإن المبذرين لإخوان الشياطين فقال ابن الحشرج في ذلك\n(متى يأتنا الغيث المغيث تجد لنا ... مكارم ما تعيا بأموالنا التلد)\n(مكارم ما جدنا به إذ تمنعت ... رجال وضنت في الرخاء وفي الجهد)\n(أردنا بما جدنا به من تلادنا ... خلاف الذي يأتي خيار بني نهد)\n(تلوم على اتلافي المال طلتي ... ويسعدها نهد بن زيد على الزهد)\n(أنهد بن زيد لست منكم فتشفقوا ... علي ولا منكم غواتي ولا رشدي)\nراد غوايتي فحذف الياء ضرورة\n(أبيت صغيرا ناشئا ما أردتم ... وكهلا وحتى تبصروني في اللحد)\n(سأبذل مالي إن مالي ذخيرة ... لعقبي وما أجني به ثمر الخلد)\n(ولست بمبكاء على الزاد باسل ... يهر على الأزواد كالأسد الورد)\n(ولكنني سمح بما حزت باذل ... لما كلفت كفاي في الزمن الجحد)\n(بذلك أوصاني الرقاد وقبله ... أبوه بأن أعطي وأوفي بالعهد)\nلرقاد ابن عمرو بن ربيعة بن جعدة بن كعب وهو من عمومته وكان شجاعا سيدا جوادا قال عطاء بن مصعب وقال عبد الله بن الحشرج أيضا في ذلك هذه القصيدة وقد ذكر ابن الكلبي وأبو اليقظان شيئا من هذه القصيدة في\nكتابيهما المصنفين ونسباها إليه\n(سأجعل مالي دون عرضي وقاية ... من الذم إن المال يفنى وينفد)\n(ويبقي لي الجود اصطناع عشيرتي ... وغيرهم والجود عز مؤبد)\n(ومتخذ ذنبا علي سماحتي ... بمالي ونار البخل بالذم توقد)\n(يبيد الفتى والحمد ليس ببائد ... ولكنه للمرء فضل مؤكد)\n(ولا شيء يبقى للفتى غير جوده ... بما ملكت كفاه والقوم شهد)\n(ولائمة في الجود نهنهت غربها ... وقلت لها بني المكارم أحمد)\n(فلما ألحت في الملامة واعترت ... بذلك غيظي واعتراها التبلد)\n(عرضت عليها خصلتين سماحتي ... وتطليقها والكف عني أرشد)\n(فلجت وقالت أنت غاو مبذر ... قرينك شيطان مريد مفند)\n(فقلت لها بيني فما فيك رغبة ... ولي عنك في النسوان ظل ومقعد)\n(وعيش أنيق والنساء معادن ... فمنهن غل شرها يتمرد)\n(لها كل يوم فوق رأسي عارض ... من الشر براق يد الدهر يرعد)\n(وأخرى يلذ العيش منها ضجيعها ... كريم يغاديه من الطير أسعد)\n(فيا رجلا حرا خذ القصد واترك البلايا فإن الموت للناس موعد ... )\n(فعيش ناعما واترك مقالة عاذل ... يلومك في بذل الندى ويفند)\n(وجد باللها إن السماحة والندى ... هي الغاية القصوى وفيها التمجد)\n(وحسب الفتى مجدا سماحة كفه ... وذو المجد محمود الفعال محسد)\nقال فقالت له امرأته والله ما وفقك الله لحظك أنهيت مالك وبذرته وأعطيته هيان بن بيان ومن لا تدري من أي هافية هو قال فغضب فطلقها وكان لها محبا وبها معجبا فعنفه فيها ابن عم لها يقال له حنظلة بن الأشهب بن رميلة وقال له نصحتك فكافأتها بالطلاق فوالله ما وفقت لرشدك ولا نلت حظك ولقد خاب سعيك بعدها عند ذوي الألباب فهلا مضيت لطيتك وجريت على ميدانك ولم تلتفت إلى امرأة من أهل الجهالة والطيش لم تخلق للمشورة ولا مثل رأيها يقتدى به فقال ابن الحشرج لحنظلة\n(أحنظل دع عنك الذي نال ماله ... ليحمده الأقوام في كل محفل)\n(فكم من فقير بائس قد جبرته ... ومن عائل أغنيت بعد التعيل)\n(ومن مترف عن منهج الحق جائر ... علوت بعضب ذي غرارين مقصل)\n(وزار علي الجود والجود شيمتي ... فقلت له دعني وكن غير مفضل)\n(فمثلك قد عاصيت دهرا ولم أكن ... لأسمع أقوال اللئيم المبخل)\n(أبى لي جدي البخل مذ كنت يافعا ... صغيرا ومن يبخل يلم ويضلل)\n(ويستغن عنه الناس فاركب محجة الكرام ودع ما أنت عنه بمعزل ... )\n(فإني امرؤ لا أصحب الدهر باخلا ... لئيما وخير الناس كل معذل)\n(ومستحمق غاو أتته نذيرتي ... فلج ولم يعرف معرة مقولي)\n(نفحت ببيت يملأ الفم شارد ... له حبر كأنه حبر مغول)\n(فكف ولو لم أرمه شاع قوله ... وصار كدرياق الذعاف المثمل)\n(وليل دجوجي سريت ظلامه ... بناجية كالبرج وجناء عيهل)","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":8,"spl":"كرم عبد الله بن الحشرج","loc":2154,"partial":1},
{"id":"b128-13","bab":"الجزء 12","sec":"كرم عبد الله بن الحشرج","page":"ج12 ص32","text":"(إلى ملك من آل مروان ماجد ... كريم المحيا سيد متفضل)\n(يجود إذا ضنت قريش برفدها ... ويسبقها في كل يوم تفضل)\n(أبوه أبو العاصي إذا الحرب شمرت ... مراها بمسنون الغرارين منجل)\n(وقور إذا هاجت به الحرب مرجم ... صبور عليها غير نكس مهلل)\n(أقام لأهل الأرض دين محمد ... وقد أدبروا وارتاب كل مضلل)\n(فما زال حتى قوم الدين سيفه ... وعز بحزم كل قرم محجل)\n(وغادر أهل الشك شتى فمنهم ... قتل قتيل وناج فوق أجرد هيكل)\n(نجا من رماح القوم قدما وقد بدا ... تباشيره في العارض المتهلل)\nقال عاصم يعني بهذا المدح محمد بن مروان لما قتل مصعب بن الزبير بدير الجاثليق وكان محمد بن مروان يقوم بأمره ويوليه الأعمال ويشفع له إلى أخيه عبد الملك","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":9,"spl":"كرم عبد الله بن الحشرج — حوار حول تبذيره المال","loc":2155},
{"id":"b128-14","bab":"الجزء 12","sec":"حوار حول تبذيره المال","page":"ج12 ص37","text":"أخبرني محمد بن خلف قال حدثنا أحمد بن الهيثم قال حدثنا العمري عن عطاء بن مصعب عن عاصم بن الحدثان قال قال عبد الله بن الحشرج لابن عم له لأمه في إنهاب ماله وتبذيره إياه وقال له فيما يقول امرأتك كانت أعلم بك نصحتك فكافأتها بالطلاق فقال له يابن عم إن المرأة لم تخلق للمشورة وإنما خلقت وثارا للباءة\nووالله إن الرشد واليمن لفي خلاف المرأة يابن عم إياك واستماع كلام النساء والأخذ به فإنك إن أخذت به ندمت فقال له ابن عمه والله ليوشكن أن تحتاج يوما إلى بعض ما أتلفت فلا تقدر عليه ولا يخلفه عليك هن وهن فقال ابن الحشرج\n(وعاذلة هبت بليل تلومني ... وتعذلني فيما أفيد وأتلف)\n(تلومتها حتى إذا هي أكثرت ... أتيت الذي كانت لدي توكف)\n(وقلت عليك الفج أكثرت في الندى ... ومثلي تحاماه الألد المغطرف)\n(أبى لي ما قد سمتني غير واحد ... أب وجدود مجدها ليس يوصف)\n(كهول وشبان مضوا لسبيلهم ... إذا ذكروا فالعين مني تذرف)\n(هم الغيث إن ضنت سماء بقطرها ... وعندهم يرجو الحيا متلهف)\n(وحرب يخاف الناس شدة عرها ... تظل بأنواع المنية تصرف)\n(حموها وقاموا بالسيوف لحميها ... إذا فنيت أضحت لهم وهي تعصف)\n(فلما أبت إلا طماحا تنمروا ... بأسيافهم والقوم فيهم تعجرف)\n(فذلت وأعطت بالقياد وأذعنت ... إذا ما اشتهى قومي وذو الذل ينصف)\n(وكانت طموح الرأس يصرف نابها ... من الشر تارات وطورا تقفقف)\n(فلما امترينا بالسيوف خلوفها ... تأبت علينا والأسنة ترعف)\n(فدرت طباقا وارعوت بعد جهلها ... وكنا رماما للذي يتصلف)\nال وقال عبد الله بن الحشرج لرفاعة بن زوي النهدي فيما كان يلومه فيه من التبذير والجود\n(ألام على جودي وما خلت أنني ... ببذلي وجودي جرت عن منهج القصد)\n(فيالائمي في الجود أقصر فإنني ... سأبذل مالي في الرخاء وفي الجهد)\n(وجدت الفتى يفنى وتبقى فعاله ... ولا شيء خير في الحديث من الحمد)\n(وإني وبالله احتيالي وحرفتي ... أصير جاري بين أحشاي والكبد)\n(أرى حقه في الناس ما عشت واجبا ... علي وآتي ما أتيت على عمد)\n(وصاحب صدق كان لي ففقدته ... وصيرني دهري إلى مائق وغد)\n(يلوم فعالي كل يوم وليلة ... ويعدو على الجيران كالأسد الورد)\n(يخالفني في كل حق وباطل ... ويأنف أن يمشي على منهج الرشد)\n(فلما تمادى قلت غير مسامح ... له النهج فاركب ياعسيف بني نهد)\nخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل العتكي قال حدثنا ابن عائشة قال","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":9,"spl":"كرم عبد الله بن الحشرج — حوار حول تبذيره المال","loc":2156},
{"id":"b128-15","bab":"الجزء 12","sec":"مدحه زياد الأعجم فوصله","page":"ج12 ص40","text":"وفد زياد الأعجم على عبد الله بن الحشرج الجعدي وهو بسابور أمير عليها فأمر بإنزاله وألطفه وبعث إليه ما يحتاج إليه ثم غدا عليه زياد فأنشده\n(إن السماحة والمروءة والندى ... في قبة ضربت على ابن الحشرج)\n(ملك أغر متوج ذو نائل ... للمعتفين يمينه لم تشنج)\n(يا خير من صعد المنابر بالتقى ... بعد النبي المصطفى المتحرج)\n(لما أتيتك راجيا لنوالكم ... ألفيت باب نوالكم لم يرتج)\nقال فأمر له بعشرة آلاف درهم وقد قيل إن الأبيات التي ذكرتها وفيها الغناء ونسبتها إلى عبد الله بن الحشرج لغيره والقول الأصح هو الأول أخبرني بذلك محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثنا العمري عن هشام بن الكلبي أنه سمع أبا باسل ينشد هذا الشعر فقلت لمن هو فقال لعمي عنترة بن الأخرس قال وكان جدي أخرس فولد له سبعة أو ثمانية كلهم شاعر أو خطيب ولعل هذا من أكاذيب ابن الكلبي أو حكاه عن رجل ادعى فيه ما لا يعلم\n(أصاح ألا هل من سبيل إلى نجد ... وريح الخزامى غضة من ثرى جعد)\n(وهل لليالينا بذي الرمث مرجع ... فنشفي جوى الأحزان من لاعج الوجد)\nعروضه من الطويل - الشعر للطرماح بن حكيم والغناء ليحيى المكي ثقيل أول بالبنصر من كتابه","topic":"أخبار الأعشى وبني عبد المدان وأخبارهم مع غيره","topicNo":128,"sp":10,"spl":"مدحه زياد الأعجم فوصله","song":1,"loc":2157},
{"id":"b129-1","bab":"الجزء 12","sec":"أخبار الطرماح ونسبه","page":"ج12 ص43","text":"هو الطرماح بن حكيم بن الحكم بن نفر بن قيس بن جحدر بن ثعلبة بن عبد رضا بن مالك بن أمان بن عمرو بن ربيعة بن جرول بن ثعل بن عمرو بن الغوث بن طيئ ويكنى أبا نفر وأبا ضبينة والطرماح الطويل القامة وقيل إنه كان يلقب الطراح أخبرني بذلك أحمد بن عبد العزيز الجوهري قال حدثني علي بن محمد النوفلي عن أبيه قال كان الطرماح بن حكيم يلقب الطراح لقوله\n(ألا أيها الليل الطويل ألا ارتح ... بصبح وما الإصباح منك بأروح)\n(بلى إن للعينين في الصبح راحة ... بطرحهما طرفيهما كل مطرح)\nي هذين البيتين لأحمد بن المكي ثقيل أول بالوسطى من كتابه\nوالطرماح من فحول الشعراء الإسلاميين وفصحائهم ومنشؤه بالشأم وانتقل إلى الكوفة بعد ذلك مع من وردها من جيوش أهل الشأم واعتقد مذهب الشراة الأزارقة أخبرني إسماعيل بن يونس قال حدثنا عمر بن شبة عن المدائني عن أبي بكر الهذلي قال قدم الطرماح بن حكيم الكوفة فنزل في تيم اللات بن ثعلبة وكان فيهم شيخ من الشراة له سمت وهيئة وكان الطرماح يجالسه ويسمع منه فرسخ كلامه في قلبه ودعاه الشيخ إلى مذهبه فقبله واعتقده أشد اعتقاد وأصحه حتى مات عليه\nأخبرني ابن دريد قال حدثنا عبد الرحمن بن أخي الأصمعي عن عمه قال قال رؤبة كان الطرماح والكميت يصيران إلي فيسألاني عن الغريب فأخبرهما به فأراه بعد في أشعارهما أخبرني محمد بن العباس اليزيدي قال سمعت محمد بن حبيب يقول سألت ابن الأعرابي عن ثماني عشرة مسألة كلها من غريب شعر الطرماح فلم يعرف منها واحدة يقول في جميعها لا أدري لا أدري أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة وأخبرنا إبراهيم بن أيوب قال حدثنا ابن قتيبة قالا كان الكميت بن زيد صديقا للطرماح لا يكادان يفترقان في حال من أحوالهما فقيل للكميت لا شيء أعجب من صفاء ما بينك وبين الطرماح على\nتباعد ما يجمعكما من النسب والمذهب والبلد هو شآمي قحطاني شاري وأنت كوفي نزاري شيعي فكيف اتفقتما مع تباين المذهب وشدة العصبية اتفقنا على بغض العامة قال وأنشد الكميت قول الطرماح\n(إذا قبضت نفس الطرماح أخلقت ... عرى المجد واسترخى عنان القصائد)\nقال إي والله وعنان الخطابة والرواية والفصاحة والشجاعة وقال عمر بن شبة والسماحة مكان الشجاعة نسخت من كتاب جدي لأمي يحيى بن محمد بن ثوابة رحمه الله تعالى بخطه قال حدثني الحسن بن سعيد عن محمد بن حبيب عن ابن الأعرابي قال وفد الطرماح بن حكيم والكميت بن زيد على مخلد بن يزيد المهلبي فجلس لهما ودعاهما فتقدم الطرماح لينشد فقال له أنشدنا قائما فقال كلا والله ما قدر الشعر أن أقوم له فيحط مني وأحط منه بضراعتي وهو عمود الفخر وبيت الذكر لمآثر العرب قيل له فتنح ودعي بالكميت فأنشد قائما فأمر له بخمسين ألف درهم فلما خرج الكميت شاطرها الطرماح وقال له أنت أبا ضبينة أبعد همة وأنا ألطف حيلة وكان الطرماح يكنى أبا نفر وأبا ضبينة ونسخت من كتابه رضي الله عنه أخبرني الحسن بن سعيد قال أخبرني ابن علاق قال أخبرني شيخ لنا أن خالد بن كلثوم أخبره قال بينا أنا في مسجد الكوفة أريد الطرماح والكميت وهما جالسان بقرب باب\nالفيل إذ رأيت أعرابيا قد جاء يسحب أهداما له حتى إذا توسط المسجد خر ساجدا ثم رمى ببصره فرأى الكميت والطرماح فقصدهما فقلت من هذا الحائن الذي وقع بين هذين الأسدين وعجبت من سجدته في غير موضع سجود وغير وقت صلاة فقصدته ثم سلمت عليهم ثم جلست أمامهم فالتفت إلى الكميت فقال أسمعني شيئا يا أبا المستهل فأنشده قوله\n(أبت هذه النفس إلا أدكارا ... )\nتى أتى على آخرها فقال له أحسنت والله يا أبا المستهل في ترقيص هذه القوافي ونظم عقدها ثم التفت إلى الطرماح فقال أسمعني شيئا يا أبا ضبينة فأنشده كلمته التي يقول فيها\n(أساءك تقويض الخليط المباين ... نعم والنوى قطاعة للقرائن)\nقال لله در هذا الكلام ما أحسن إجابته لرويتك إن كدت لأطيل لك\nحسدا ثم قال الأعرابي والله لقد قلت بعدكما ثلاثة أشعار أما أحدها فكدت أطير به في السماء فرحا وأما الثاني فكدت أدعي به الخلافة وأما الثالث فرأيت رقصانا استفزني به الجذل حتى أتيت عليه قالوا فهات فأنشدهم قوله\n(أأن توهمت من خرقاء منزلة ... ماء الصبابة من عينيك مسجوم)\nتى إذا بلغ قوله\n(تنجو إذا جعلت تدمى أخشتها ... وابتل بالزبد الجعد الخراطيم)","topic":"أخبار الطرماح ونسبه","topicNo":129,"sp":0,"spl":"أخبار الطرماح ونسبه","song":1,"loc":2158,"partial":1},
{"id":"b129-2","bab":"الجزء 12","sec":"أخبار الطرماح ونسبه","page":"ج12 ص43","text":"ال أعلمتم أني في طلب هذا البيت منذ سنة فما ظفرت به إلا آنفا وأحسبكم قد رأيتم السجدة له ثم أسمعهم قوله\n(ما بال عينك منها الماء ينسكب ... )\nم أنشدهم كلمته الأخرى التي يقول فيها\n(إذا الليل عن نشر تجلى رمينه ... بأمثال أبصار النساء الفوارك)\nال فضرب الكميت بيده على صدر الطرماح ثم قال هذه والله الديباج لانسجي ونسجك الكرابيس فقال الطرماح لن أقول ذلك وإن\nأقررت بجودته فقطب ذو الرمة وقال يا طرماح أأنت تحسن أن تقول\n(وكائن تخطت ناقتي من مفازة ... إليك ومن أحواض ماء مسدم)\n(بإعقاره القردان هزلى كأنها ... نوادر صيصاء الهبيد المحطم)\nأصغى الطرماح إلى الكميت وقال له فانظر ما أخذ من ثواب هذا الشعر قال وهذه قصيدة مدح بها ذو الرمة عبد الملك فلم يمدحه فيها ولا ذكره إلا بهذين البيتين وسائرها في ناقته فلما قدم على عبد الملك بها أنشده إياها فقال له ما مدحت بهذه القصيدة إلا ناقتك فخذ منها الثواب وكان ذو الرمة غير محظوظ من المديح قال فلم يفهم ذو الرمة قول الطرماح للكميت فقال له الكميت إنه ذو الرمة وله فضله فأعتبه فقال له الطرماح معذرة إليك إن عنان الشعر لفي كفك فارجع معتبا وأقول فيك كما قال أبو المستهل أخبرني الحسن بن علي ومحمد بن يحيى الصولي قالا حدثنا\nالحسن بن عليل العنزي قال حدثني محمد بن إبراهيم بن عباد قال حدثني أبو تمام الطائي قال مر الطرماح بن حكيم في مسجد البصرة وهو يخطر في مشيته فقال رجل من هذا الخطار فسمعه فقال أنا الذي أقول\n(لقد زادني حبا لنفسي أنني ... بغيض إلى كل امرئ غير طائل)\n(وأني شقي باللئام ولا ترى ... شقيا بهم إلا كريم الشمائل)\n(إذا ما رآني قطع اللحظ بينه ... وبيني فعل العارف المتجاهل)\n(ملأت عليه الأرض حتى كأنها ... من الضيق في عينيه كفة حابل)\nي هذه الأبيات لأبي العبيس بن حمدون خفيف ثقيل أول بالبنصر","topic":"أخبار الطرماح ونسبه","topicNo":129,"sp":1,"spl":"أخبار الطرماح ونسبه — الطرماح وخالد القسري","song":1,"loc":2159,"partial":1},
{"id":"b129-3","bab":"الجزء 12","sec":"الطرماح وخالد القسري","page":"ج12 ص50","text":"أخبرني محمد بن خلف وكيع قال أخبرنا إسماعيل بن مجمع قال حدثنا هشام بن محمد قال أخبرنا ابن أبي العمرطة الكندي قال\nمدح الطرماح خالد بن عبد الله القسري فأقبل على العريان بن الهيثم فقال إني قد مدحت الأمير فأحب أن تدخلني عليه قال فدخل إليه فقال له إن الطرماح قد مدحك وقال فيك قولا حسنا فقال ما لي في الشعر من حاجة فقال العريان للطرماح تراء له فخرج معه فلما جاوز دار زياد وصعد المسناة إذا شيء قد ارتفع له فقال يا عريان انظر ما هذا فنظر ثم رجع فقال أصلح الله الأمير هذا شيء بعث به إليك عبد الله بن أبي موسى من سجستان فإذا حمر وبغال ورجال وصبيان ونساء فقال يا عريان أين طرماحك هذا قال هاهنا قال أعطه كل ما قدم به فرجع إلى الكوفة بما شاء ولم ينشده قال هشام والطرماح الطويل أخبرني محمد بن الحسن بن بريد قال حدثنا أبو حاتم قال حدثني الحجاجي قال بلغني أن الطرماح جلس في حلقة فيها رجل من بني عبس فأنشد\nالعبسي قول كثير في عبد الملك\n(فكنت المعلى إذ أجيلت قداحهم ... وجال المنيح وسطها يتقلقل)\nقال الطرماح أما إنه ما أراد به أنه أعلاهم كعبا ولكنه موه عليه في الظاهر وعنى في الباطن أنه السابع في الخلفاء الذين كان كثير لا يقول بإمامتهم لأنه أخرج عليا عليه السلام منهم فإذا أخرجه كان عبد الملك السابع وكذلك المعلى السابع من القداح فلذلك قال ما قاله وقد ذكر ذلك في موضع آخر فقال\n(وكان الخلائف بعد الرسو ... ل لله كلهم تابعا)\n(شهيدان من بعد صديقهم ... وكان ابن حرب لهم رابعا)\n(وكان ابنه بعده خامسا ... مطيعا لمن قبله سامعا)\n(ومروان سادس من قد مضى ... وكان ابنه بعده سابعا)\nال فعجبنا من تنبه الطرماح لمعنى قول كثير وقد ذهب على عبد الملك فظنه مدحا\nأخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ قال كان أبو عبيدة والأصمعي يفضلان الطرماح في هذين البيتين ويزعمان أنه فيهما أشعر الخلق\n(مجتاب حلة برجد لسراته ... قددا وأخلف ما سواه البرجد)\n(يبدو وتضمره البلاد كأنه ... سيف على شرف يسل ويغمد)\nخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ قال قال أبو نواس أشعر بيت قيل بيت الطرماح\n(إذا قبضت نفس الطرماح أخلقت ... عرى المجد واسترخى عنان القصائد)","topic":"أخبار الطرماح ونسبه","topicNo":129,"sp":1,"spl":"أخبار الطرماح ونسبه — الطرماح وخالد القسري","loc":2160},
{"id":"b129-4","bab":"الجزء 12","sec":"مناقضة بينه وبين حميد اليشكري","page":"ج12 ص53","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبيدة قال فضل الطرماح بني شمخ في شعره على بني يشكر فقال حميد اليشكري\n(أتجعلنا إلى شمخ بن جرم ... ونبهان فأف لذا زمانا)\n(ويوم الطالقان حماك قومي ... ولم تخضب بها طي سنانا)\nفقال الطرماح يجيبه\n(لقد علم المعذل يوم يدعو ... برمثة يوم رمثة إذ دعانا)\n(فوارس طيء منعوه لما ... بكى جزعا ولولاهم لحانا)\nقال رجل من بني يشكر\n(لأقضين قضاء غير ذي جنف ... بالحق بين حميد والطرماح)\n(جرى الطرماح حتى دق مسحله ... وغودر العبد مقرونا بوضاح)\nعني رجلا من بني تميم كان يهاجي اليشكري أخبرني إسماعيل بن يونس قال حدثنا الرياشي قال قال الأصمعي قال خلف كان الطرماح يرى رأي الشراة ثم أنشد له\n(لله در الشراة إنهم ... إذا الكرى مال بالطلى أرقوا)\n(يرجعون الحنين آونة ... وإن علا ساعة بهم شهقوا)\n(خوفا تبيت القلوب واجفة ... تكاد عنها الصدور تنفلق)\n(كيف أرجي الحياة بعدهم ... وقد مضى مؤنسي فانطلقوا)\n(قوم شحاح على اعتقادهم ... بالفوز مما يخاف قد وثقوا)\nخبرني محمد بن الحسن بن دريد قال أخبرنا أبو عثمان عن التوزي عن أبي عبيدة عن يونس قال دخل الطرماح على خالد بن عبد الله القسري فأنشده قوله\n(وشيبني ما لا أزال مناهضا ... بغير غنى أسمو به وأبوع)\n(وأن رجال المال أضحوا ومالهم ... لهم عند أبواب الملوك شفيع)\n(أمخترمي ريب المنون ولم أنل ... من المال ما أعصي به وأطيع)\nأمر له بعشرين ألف درهم وقال امض الآن فاعص بها وأطع","topic":"أخبار الطرماح ونسبه","topicNo":129,"sp":2,"spl":"مناقضة بينه وبين حميد اليشكري — أصحابه يفاجأون بنعشه","loc":2161},
{"id":"b129-5","bab":"الجزء 12","sec":"رأي المفضل في هجائه","page":"ج12 ص55","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا خذيفة بن محمد الكوفي قال قال المفضل إذا ركب الطرماح الهجاء فكأنما يوحى إليه ثم أنشد له قوله\n(لوحان ورد تميم ثم قيل لها ... حوض الرسول عليه الأزد لم ترد)\n(أو أنزل الله وحيا أن يعذبها ... إن لم تعد لقتال الأزد لم تعد)\n(لاعز نصر امرىء أضحى له فرس ... على تميم يريد النصر من أحد)\n(لو كان يخفى على الرحمن خافية ... من خلقه خفيت عنه بنو أسد)","topic":"أخبار الطرماح ونسبه","topicNo":129,"sp":2,"spl":"مناقضة بينه وبين حميد اليشكري — أصحابه يفاجأون بنعشه","loc":2162},
{"id":"b129-6","bab":"الجزء 12","sec":"أصحابه يفاجأون بنعشه","page":"ج12 ص56","text":"أخبرني إسماعيل بن يونس قال أخبرنا عمر بن شبة قال حدثني المدائني قال حدثني ابن دأب عن ابن شبرمة وأخبرني محمد بن القاسم الأنباري قال أخبرني أبي قال حدثني الحسن بن عبد الرحمن الربعي قال حدثني محمد بن عمران قال حدثني إبراهيم بن سوار الضبي قال حدثني محمد بن زياد القرشي عن ابن شبرمة قال كان الطرماح لنا جليسا ففقدناه أياما كثيرة فقمنا بأجمعنا لننظر ما فعل وما دهاه فلما كنا قريبا من منزله إذا نحن بنعش عليه مطرف أخضر فقلنا لمن هذا النعش فقيل هذا نعش الطرماح فقلنا والله ما استجاب الله له حيث يقول\n(وإني لمقتاد جوادي وقاذف ... به وبنفسي العام إحدى المقاذف)\n(لأكسب مالا أو أؤول إلى غنى ... من الله يكفيني عدات الخلائف)\n(فيارب إن حانت وفاتي فلا تكن ... على شرجع يعلى بخضر المطارف)\n(ولكن قبري بطن نسر مقيله ... بجو السماء في نسور عواكف)\n(وأمسي شهيدا ثاويا في عصابة ... يصابون في فج من الأرض خائف)\n(فوارس من شيبان ألف بينهم ... تقى الله نزالون عند التزاحف)\n(إذا فارقوا دنياهم فارقوا الأذى ... وصارو إلى ميعاد ما في المصاحف)\n\n(هل بالديار التي بالقاع من أحد ... باق فيسمع صوت المدلج الساري)\n(تلك المنازل من صفراء ليس بها ... حي يجيب ولا أصوات سمار)\nلشعر لبيهس الجرمي والغناء لابن محرز ثاني ثقيل بالبنصر عن\nعمرو وقال ذكر ذلك يحيى المكي وأظنه من المنحول وفيه لطياب بن إبراهيم الموصلي خفيف ثقيل وهو مأخوذ من لحن ابن صاحب الوضوء\n(ارفع ضعيفك لا يحر بك ضعفه ... )","topic":"أخبار الطرماح ونسبه","topicNo":129,"sp":2,"spl":"مناقضة بينه وبين حميد اليشكري — أصحابه يفاجأون بنعشه","song":1,"loc":2163,"partialRef":{"sid":"b21-13","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b130-1","bab":"الجزء 12","sec":"أخبار بيهس ونسبه","page":"ج12 ص59","text":"هو بيهس بن صهيب بن عامر بن عبد الله بن ناتل بن مالك بن عبيد بن علقمة بن سعد بن كثير بن غالب بن عدي بن سميس بن طرود بن قدامة بن جرم بن ربان بن حلوان بن عمران بن إلحاف بن قضاعة شاعر فارس من شعراء الدولة الأموية وكان يبدو بنواحي الشأم مع قبائل جرم وكلب وعذرة ويحضر إذا حضروا فيكون بأجناد الشأم قال أبو عمرو الشيباني لما هدأت الفتنة بعد وقعة مرج راهط وسكن الناس مر غلام من قيس بطوائف من جرم وعذرة وكلب وكانوا متجاورين على ماء هناك لهم فيقال إن بعض أحداثهم نخس به ناقته\nفألقته فاندقت عنقه فمات واستعدى قومه عبد الملك بن مروان فبعث إلى تلك البطون من جاءه بوجوههم وذوي الأخطار منهم فهرب بيهس بن صهيب الجرمي وكان قد اتهم بأنه هو الذي نخس به فنزل بمحمد بن مروان واستجار به فأجاره إلا من حد توجبه عليه شهادة فرضي بذلك\n(ألا يا حمامات اللوى عدن عودة ... فإني إلى أصواتكن حرين)\n(فعدن فلما عدن كدن يمتنني ... وكدت بأسراري لهن أبين)\n(دعون بأصوات الهديل كأنما ... شربن حميا أو بهن جنون)\n(فلم تر عيني مثلهن حمائما ... بكين ولم تدمع لهن عيون)\nلشعر لأعرابي هكذا أنشدناه جعفر بن قدامة عن أحمد بن حمدون عن أحمد بن إبراهيم بن إسماعيل والغناء لمحمد بن الحارث بن بسخنر خفيف رمل بالوسطى عن الهشامي وقد قيل إن الشعر لابن الدمينة","topic":"أخبار بيهس ونسبه","topicNo":130,"sp":0,"spl":"أخبار بيهس ونسبه","song":1,"loc":2164},
{"id":"b130-2","bab":"الجزء 12","sec":"أخبار محمد بن الحارث بن بسخنر","page":"ج12 ص61","text":"هو محمد بن الحارث بن بسخنر ويكنى أبا جعفر وهم فيما يزعمون موالي المنصور وأحسبه ولاء خدمة لا ولاء عتق وأصلهم من الري وكان محمد يزعم أنه من ولد بهرام جوبين وولد محمد بالحيرة وكان يغني مرتجلا إلا أن أصل ما غنى عليه المعزفة وكانت تحمل معه إلى دار الخليفة فمر غلامه بها يوما فقال قوم كانوا جلوسا على الطريق مع هذا الغلام مصيدة الفأر وقال بعضهم لا بل هي معزفة محمد بن الحارث فحلف يومئذ بالطلاق والعتاق ألا يغني بمعزفة أبدا أنفة من أن تشتبه آلة يغني بها بمصيدة الفأر وكان محمد أحسن خلق الله تعالى أداء وأسرعه أخذا للغناء وكان لأبيه الحارث بن بسخنر جوار محسنات وكان إسحاق يرضاهن ويأمرهن أن يطرحن على جواريه وقال يوما للمأمون وقد غنى\nمخارق بين يديه صوتا فآلتاث غناؤه فيه وجاء به مضطربا فقال إسحاق للمأمون يا أمير المؤمنين إن مخارقا قد أعجبه صوته وساء أداؤه في غنائه فمره بملازمة جواري الحارث بن بسخنر حتى يعود إلى ما تريد أخبرني جحظة قال حدثني أبو عبد الله الهشامي قال سمعت إسحاق بن إبراهيم بن مصعب يقول للواثق قال لي إسحاق بن إبراهيم الموصلي ما قدر أحد قط أن يأخذ مني صوتا مستويا إلا محمد بن الحارث بن بسخنر فإنه أخذ مني عدة أصوات كما أغنيها ثم لم نلبث أن دخل علينا محمد بن الحارث فقال له الواثق حدثني إسحاق بن\nإبراهيم عن إسحاق الموصلي فيك بكذا وكذا فقال قد قال إسحاق ذاك لي مرات فقال له الواثق فأي شيء أخذت من صنعته أحسن عندك فقال هو يزعم أنه لم يأخذ منه أحد قط هذا الصوت كما أخذته منه\n(إذا المرء قاسى الدهر وابيض رأسه ... وثلم تثليم الإناء جوانبه)\n(فليس له في العيش خير وإن بكى ... على العيش أو رجى الذي هو كاذبه)\nلشعر والغناء لإسحاق ولحنه فيه رمل بالوسطى فأمره الواثق بأن يغنيه فغناه إياه وأحسن ما شاء وأجاد واستحسنه الواثق وأمره بأن يردده فردده مرارا كثيرة حتى أخذه الواثق وأخذه جواريه والمغنون قال جحظة قال الهشامي فحدثت بهذا الحديث عمرو بن بانة فقال ما خلق الله تعالى أحدا يغني هذا الصوت كما يغنيه هبة الله بن إبراهيم بن المهدي فقلت له قد سمعت ابن إبراهيم يغنيه فاسمعه من محمد ثم احكم فلقيني بعد ذلك فقال الأمر كما قلت قد سمعته من محمد فسمعت منه الإحسان كله أخبرني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال\nكنت يوما في منزلي فجاءني محمد بن الحارث بن بسخنر مسلما وعائدا من علة كنت وجدتها فسألته أن يقيم عندي ففعل ودعوت بما حضر فأكلنا وشربنا وغنى محمد بن الحارث هذا الصوت\n(أمن ذكر خود عينك اليوم تدمع ... وقلبك مشغول بخودك مولع)\n(وقائلة لي يوم وليت معرضا ... أهذا فراق الحب أم كيف تصنع)\n(فقلت كذاك الدهر يا خود فآعلمي ... يفرق بين الناس طرا ويجمع)\nصل هذا الصوت يمان هزج بالوسطى قال الهشامي وفيه لفليح ثاني ثقيل ولإسحاق خفيف رمل قال علي بن يحيى فقلت له وقد ردد هذا الصوت مرارا وغناه أشجى غناء إن لك في هذا الصوت معنى وقد كررته من غير أن يقترحه عليك أحد فقال نعم هذا صوتي على جارية من القيان كنت أحبها وأخذته منها فقلت له فلم لا تواصلها فقال\n(لو لم أنكها دام لي حبها ... لكنني نكت فلا نكت)\nأجبته فقلت\n(أكثرت من نيكها والنيك مقطعة ... فارفق بنيكك إن الرفق محمود)\nأخبرني جعفر بن قدامة عن علي بن يحيى أن إسحاق غنى بحضرة الواثق لحنه\n(ذكرتك إذ مرت بنا أم شادن ... أمام المطايا تشرئب وتسنح)\n(من المؤلفات الرمل أدماء حرة ... شعاع الضحى في متنها يتوضح)\nالشعر لذي الرمة ولحن إسحاق فيه ثقيل أول فأمره أن يعيده على الجواري وأحلفه بحياته أن ينصح فيه فقال لا يستطيع الجواري أن يأخذنه مني ولكن يحضر محمد بن الحارث فيأخذه مني وتأخذه الجواري منه فأحضر وألقاه عليه فأخذه منه وأخذته الجواري منه أخبرني أحمد بن إبراهيم بن إسماعيل المعروف بوسواسة الموصلي قال حدثني حماد بن إسحاق قال قال لي محمد بن الحارث بن بسخنر أخذت جارية للواثق مني صوتا أخذته من أبيك وهو\n(أصبح الشيب في المفارق شاعا ... واكتسى الرأس من مشيب قناعا)\n(وتولى الشباب إلا قليلا ... ثم يأبى القليل إلا وداعا)\nلشعر والغناء لإسحاق ثقيل أول قال فسمعه الواثق منها","topic":"أخبار بيهس ونسبه","topicNo":130,"sp":1,"spl":"أخبار محمد بن الحارث بن بسخنر","song":3,"loc":2165},
{"id":"b130-3","bab":"الجزء 12","sec":"أخبار محمد بن الحارث بن بسخنر","page":"ج12 ص61","text":"فاستحسنه وقال لعلويه ومخارق أتعرفانه فقال مخارق أظنه لمحمد بن الحارث فقال علويه هيهات ليس هذا مما يدخل في صنعة محمد هو يشبه صنعة ذلك الشيطان إسحاق فقال له الواثق ما أبعدت ثم بعث إلي فأخبرني بالقصة فقلت صدق علويه يا أمير المؤمنين هذا لإسحاق ومنه أخذته حدثني جعفر بن قدامة قال حدثني عبد الله بن المعتز قال قال لي أحمد بن الحسين بن هشام جاءني محمد بن الحارث بن بسخنر يوما فقال لي قم حتى أطفل بك على صديق لي حر وله جارية أحسن خلق الله تعالى وجها وغناء فقلت له أنت طفيلي وتطفل بي هذه والله اخس حال فقال لي دع المجون وقم بنا فهو مكان لا يستحيي حر أن يتطفل عليه فقمت معه فقصد بي دار رجل من فتيان أهل سر من رأى كان لي صديقا يكنى أبا صالح وقد غيرت كنيته على سبيل اللقب فكني أبا الصالحات وكان ظريفا حسن\nالمروءة يضرب بالعود على مذهب الفرس ضربا حسنا وله رزق سني في الموالي وكان من أولادهم ولم يكن منزله يخلو من طعام كثير نظيف لكثرة قصد إخوانه منزله فلما طرق بابه قلت له فرجت عني هذا صديقي وأنا طفيلي بنفسي لا أحتاج أن أكون في شفاعة طفيلي فدخلنا وقدم إلينا طعام عتيد طيب نظيف فأكلنا وأحضرنا النبيذ وخرجت جاريته إلينا من غير ستارة فغنت غناء حسنا شكلا ظريفا ثم غنت من صنعة محمد بن الحارث هذا الصوت وكانت قد أخذته عنه وفيه أيضا لحن لإبراهيم والشعر لابن أبي عيينة\n(ضيعت عهد فتى لعهدك حافظ ... في حفظه وفي تضييعك)\n(إن تقتليه وتذهبي بفؤاده ... فبحسن وجهك لا بحسن صنيعك)\nطرب محمد بن الحارث ونقطها بدنانير مسيفة كانت معه في خريطته ووجه غلامه فجاءه ببرنية غالية كبيرة فغلفها منها ووهب لها الباقي وكان لمحمد بن الحارث أخ طيب ظريف يكنى أبا هارون فطرب ونعر ونخر وقال لأخيه أريد أن أقول لك شيئا في السر قال قله علانية قال لا يصلح قال والله ما بيني وبينك شيء أبالي أن تقوله جهرا فقله فقال أشتهي علم الله أن تسأل أبا الصالحات أن ينيكني فعسى صوتي أن تفتح ويطيب غنائي فضحك أبو الصالحات وخجلت الجارية وغطت وجهها وقالت سخنت عينك فإن حديثك يشبه وجهك\n\n(وأي أخ تبلو فتحمد أمره ... إذا لج خصم أو نبا بك منزل)\n(إذا أنت لم تنصف أخاك وجدته ... على طرف الهجران إن كان يعقل)\n(ستقطع في الدنيا إذا ما قطعتني ... يمينك فانظر أي كف تبدل)\n(إذا انصرفت نفسي عن الشيء لم تكد ... إليه بوجه آخر الدهر تقبل)\nلشعر لمعن بن أوس المزني والغناء لعريب خفيف رمل بالوسطى","topic":"أخبار بيهس ونسبه","topicNo":130,"sp":2,"spl":"أخبار محمد بن الحارث بن بسخنر","song":2,"loc":2166},
{"id":"b131-1","bab":"الجزء 12","sec":"أخبار معن بن أوس ونسبه","page":"ج12 ص69","text":"هو معن بن أوس بن نصر بن زياد بن أسحم بن زياد بن أسعد بن أسحم بن ربيعة بن عدي بن ثعلبة بن ذؤيب بن عداء بن عثمان بن مزينة بن أد بن طابخة بن إلياس بن مضر بن نزار ونسبوا إلى مزينة وهي امرأة مزينة بنت كلب بن وبرة وأبوهم عمرو بن أد بن طابخة أخبرني عبيد الله بن محمد الرازي وهاشم بن محمد الخزاعي وعمي قالوا حدثنا أحمد بن الحارث الخراز عن المدائني قال\nمزينة بنت كلب بن وبرة تزوجها عمرو بن أد بن طابخة فولدت له عثمان وأوسا فغلبت أمهما على نسبهما فعلى هذا القول عداء هو ابن عثمان بن عمرو بن أد بن طابخة ومعن شاعر مجيد فحل من مخضرمي الجاهلية والإسلام وله مدائح في جماعة من أصحاب النبي ورحمهم منهم عبد الله بن جحش وعمر ابن أبي سلمة المخزومي ووفد إلى عمر بن الخطاب رضي الله تعالى عنه مستعينا به على بعض أمره وخاطبه بقصيدته التي أولها\n(تأوبه طيف بذات الجراثم ... فنام رفيقاه وليس بنائم)\nعمر بعد ذلك إلى أيام الفتنة بين عبد الله بن الزبير ومروان بن الحكم أخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن أبي سعد قال حدثني إبراهيم بن المنذر الحزامي قال حدثنا عبد الملك بن عبد العزيز عن يحيى بن عبد الله بن ثوبان عن علقمة بن محجن الخزاعي عن أبيه قال كان معاوية يفضل مزينة في الشعر ويقول كان أشعر أهل الجاهلية\nمنهم وهو زهير وكان أشعر أهل الإسلام منهم وهو ابنه كعب ومعن بن أوس أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل تينة قال حدثني العتبي قال كان معن بن أوس مئناثا وكان يحسن صحبة بناته وتربيتهن فولد لبعض عشيرته بنت فكرهها وأظهر جزعا من ذلك فقال معن\n(رأيت رجالا يكرهون بناتهم ... وفيهن لا تكذب نساء صوالح)\n(وفيهن والأيام تعثر بالفتى ... نوادب لا يمللنه ونوائح)\nخبرني محمد بن عمران الصيرفي قال حدثنا العنزي يعني الحسن بن عليل قال حدثني أحمد بن عبد الله بن علي بن سويد بن منجوف عن أبيه قال\nمر عبيد الله بن العباس بن عبد المطلب بمعن بن أوس المزني وقد كف بصره فقال له يا معن كيف حالك فقال له ضعف بصري وكثر عيالي وغلبني الدين قال وكم دينك قال عشرة آلاف درهم فبعث بها إليه ثم مر به من الغد فقال له كيف أصبحت يا معن فقال\n(أخذت بعين المال حتى نهكته ... وبالدين حتى ما أكاد أدان)\n(وحتى سألت القرض عند ذوي الغنى ... ورد فلان حاجتي وفلان)\nقال له عبيد الله الله المستعان إنا بعثنا إليك بالأمس لقمة فما لكتها حتى انتزعت من يدك فأي شيء للأهل والقرابة والجيران وبعث إليه بعشرة آلاف درهم أخرى فقال معن يمدحه\n(إنك فرع من قريش وإنما ... تمج الندى منها البحور الفوارع)\n(ثووا قادة للناس بطحاء مكة ... لهم وسقايات الحجيج الدوافع)\n(فلما دعوا للموت لم تبك منهم ... على حادث الدهر العيون الدوامع)\nخبرني محمد بن عمران قال حدثني العنزي قال حدثني الفضل بن\nالعباس القرشي عن سعيد بن عمرو الزبيري قال كان لمعن بن أوس امرأة يقال لها ثور وكان لها محبا وكانت حضرية نشأت بالشأم وكانت في معن أعرابية ولوثة فكانت تضحك من عجرفيته فسافر إلى الشأم في بعض أعوامه فضلت الرفقة عن الطريق وعدلوا عن الماء فطووا منزلهم وساروا يومهم وليلتهم فسقط فرس معن في وجار ضب دخلت يده فيه فلم يستطع الفرس أن يقوم من شدة العطش حتى حمله أهل الرفقة حملا فأنهضوه وجعل معن يقوده ويقول\n(لو شهدتني وجوادي ثور ... والرأس فيه ميل ومور)\n(لضحكت حتى يميل الكور ... )\nمعن يهجو ابن الزبير أخبرني عمي قال حدثنا محمد بن سعد الكراني قال حدثنا العمري عن العتبي قال قدم معن بن أوس مكة على ابن الزبير فأنزله دار الضيفان وكان ينزلها الغرباء وأبناء السبيل والضيفان فأقام يومه لم يطعم شيئا حتى إذا كان الليل جاءهم ابن الزبير بتيس هرم هزيل فقال كلوا من هذا وهم نيف وسبعون رجلا فغضب معن وخرج من عنده فأتى عبيد الله بن العباس فقراه وحمله\nوكساه ثم أتى عبد الله بن جعفر وحدثه حديثه فأعطاه حتى أرضاه وأقام عنده ثلاثا ثم رحل فقال يهجو ابن الزبير ويمدح ابن جعفر وابن عباس رضي الله تعالى عنهم أجمعين\n(ظللنا بمستن الرياح غدية ... إلى أن تعالى اليوم في شر محضر)\n(لدى ابن الزبير حابسين بمنزل ... من الخير والمعروف والرفد مقفر)\n(رمانا أبو بكر وقد طال يومنا ... بتيس من الشاء الحجازي أعفر)","topic":"أخبار معن بن أوس ونسبه","topicNo":131,"sp":0,"spl":"أخبار معن بن أوس ونسبه","loc":2167,"partial":1},
{"id":"b131-2","bab":"الجزء 12","sec":"أخبار معن بن أوس ونسبه","page":"ج12 ص69","text":"(وقال اطعموا منه ونحن ثلاثة ... وسبعون إنسانا فيا لؤم مخبر)\n(فقلت له لا تقرنا فأمامنا ... جفان ابن عباس العلا وابن جعفر)\n(وكن آمنا وانعق بتيسك إنه ... له أعنز ينزو عليها وأبشر)\nخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثنا أبو عبد الله محمد بن معاوية الأسدي قال قدم معن بن أوس المزني البصرة فقعد ينشد في المربد فوقف\nعليه الفرزدق فقال يا معن من الذي يقول\n(لعمرك ما مزينة رهط معن ... بأخفاف يطأن ولا سنام)\nقال معن أتعرف يا فرزدق الذي يقول\n(لعمرك ما تميم أهل فلج ... بأرداف الملوك ولا كرام)\nفقال الفرزدق حسبك إنما جربتك قال قد جربت وأنت أعلم فانصرف وتركه أخبرني هاشم بن محمد الخزاعي أبو دلف قال حدثنا الرياشي قال حدثنا الأصمعي قال دخلت خضراء روح فإذا أنا برجل من ولده على فاحشة يوما فقلت قبحك الله هذا موضع كان أبوك يضرب فيه الأعناق ويعطي اللهى وأنت تفعل فيه ما أرى فالتفت إلي من غير أن يزول عنها وقال\n(ورثنا المجد عن آباء صدق ... أسأنا في ديارهم الصنيعا)\n(إذا الحسب الرفيع تواكلته ... بناة السوء أوشك أن يضيعا)\nال والشعر لمعن بن أوس المزني","topic":"أخبار معن بن أوس ونسبه","topicNo":131,"sp":1,"spl":"أخبار معن بن أوس ونسبه — سفره إلى الشام","loc":2168},
{"id":"b131-3","bab":"الجزء 12","sec":"سفره إلى الشام","page":"ج12 ص76","text":"أخبرني محمد بن جعفر النحوي صهر المبرد قال حدثنا أحمد بن عبيد أبو عصيدة عن الحرمازي قال سافر معن بن أوس إلى الشأم وخلف ابنته ليلى في جوار عمر بن أبي سلمة وأمه أم سلمة أم المؤمنين رضي الله تعالى عنها وفي جوار عاصم بن عمر بن الخطاب رضي الله تعالى عنه فقال له بعض عشيرته على من خلفت ابنتك ليلى بالحجاز وهي صبية ليس لها من يكفلها فقال معن رحمه الله تعالى\n(لعمرك ما ليلى بدار مضيعة ... وما شيخها أن غاب عنها بخائف)\n(وإن لها جارين لن يغدرا لها ... ربيب النبي وابن خير الخلائف)\nخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني مسعود بن بشر عن عبد الملك بن هشام قال قال عبد الملك بن مروان يوما وعنده عدة من أهل بيته وولده ليقل كل واحد منكم أحسن شعر سمع به فذكروا لامريء القيس والأعشى وطرفة\nفأكثروا حتى أتوا على محاسن ما قالوا فقال عبد الملك أشعرهم والله الذي يقول\n(وذي رحم قلمت أظفار ضغنه ... بحلمي عنه وهو ليس له حلم)\n(إذا سمته وصل القرابة سامني ... قطيعتها تلك السفاهة والظلم)\n(فأسعى لكي أبني ويهدم صالحي ... وليس الذي يبني كمن شأنه الهدم)\n(يحاول رغمي لا يحاول غيره ... وكالموت عندي أن ينال له رغم)\n(فما زلت في لين له وتعطف ... عليه كما تحنو على الولد الأم)\n(لأستل منه الضغن حتى سللته ... وإن كان ذا ضغن يضيق به الحلم)\nالوا ومن قائلها يا أمير المؤمنين قال معن بن أوس المزني","topic":"أخبار معن بن أوس ونسبه","topicNo":131,"sp":1,"spl":"أخبار معن بن أوس ونسبه — سفره إلى الشام","loc":2169},
{"id":"b131-4","bab":"الجزء 12","sec":"خروجه إلى البصرة","page":"ج12 ص77","text":"أخبرني عيسى بن حسين الوراق قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي عن أبيه قال خرج معن بن أوس المزني إلى البصرة ليمتار منها ويبيع إبلا له فلما قدمها نزل بقوم من عشيرته فتولت ضيافته امرأة منهم يقال لها ليلى وكانت ذات جمال ويسار فخطبها فأجابته فتزوجها وأقام عندها حولا في أنعم\nعيش فقال لها بعد حول يابنة عم إني قد تركت ضيعة لي ضائعة فلو أذنت لي فاطلعت طلع أهلي ورممت من مالي فقالت كم تقيم قال سنة فأذنت له فأتى أهله فأقام فيهم وأزمن عنها أي طال مقامه فلما أبطأ عليها رحلت إلى المدينة فسألت عنه فقيل لها إنه بعمق وهو ماء لمزينة فخرجت حتى إذا كانت قريبة من عمق نزلت منزلا كريما واقبل معن في طلب ذود له قد أضلها وعليه مدرعة من صوف وبت من صوف أخضر قال والبت الطيلسان وعمامة غليظة فلما رفع له القوم مال إليهم ليستسقي ومع ليلى ابن أخ لها ومولى من مواليها جالس أمام خباء له فقال له معن هل من ماء قال نعم وإن شئت سويقا وإن شئت لبنا فأناخ وصاح مولى ليلى يا منهلة وكانت منهلة الوصيفة التي تقوم على معن عندهم بالبصرة فلما أتته بالقدح وعرفها وحسر عن وجهه ليشرب عرفته وأثبتته فتركت القدح في يده وأقبلت مسرعة إلى مولاتها فقالت يا مولاتي هذا والله معن إلا أنه في جبة صوف وبت صوف فقالت هو والله عيشهم الحقي مولاي فقولي له هذا معن فاحبسه فخرجت الوصيفة مسرعة فأخبرت فوضع معن القدح وقال له دعني حتى ألقاها في غير هذا\nالزي فقال لست بارحا حتى تدخل عليها فلما رأته قال أهذا العيش الذي نزعت إليه يا معن قال إي والله يابنة عم أما إنك لو أقمت إلى أيام الربيع حتى ينبت البلد الخزامي والرخامي والسخبر والكمأة لأصبت عيشا طيبا فغسلت رأسه وجسده وألبسته ثيابا لينة وطيبته وأقام معها ليلته أجمع يهرجها ثم غدا متقدما إلى عمق حتى أعد لها طعاما ونحر ناقة وغنما وقدمت على الحي فلم تبق فيهم امرأة إلا أتتها وسلمت عليها فلم تدع منهن امرأة حتى وصلتها وكانت لمعن امرأة بعمق يقال لها أم حقة فقالت لمعن هذه والله خير لك مني فطلقني وكانت قد حملت فدخله من ذلك وقام ثم إن ليلى رحلت إلى مكة حاجة ومعن معها فلما فرغا من حجهما انصرفا فلما حاذيا منعرج الطريق إلى عمق قال معن يا ليلى كأن فؤادي ينعرج إلى ما هاهنا فلو أقمت سنتنا هذه حتى نحج من قابل ثم نرحل إلى البصرة فقالت ما أنا ببارحة مكاني حتى ترحل معي\nإلى البصرة أو تطلقني فقال أما إذ ذكرت الطلاق فأنت طالق فمضت إلى البصرة ومضى إلى عمق فلما فارقته ندم وتبعتها نفسه فقال في ذلك\n(توهمت ربعا بالمعبر واضحا ... أبت قرتاه اليوم إلا تراوحا)\n(أربت عليه رادة حضرمية ... ومرتجز كأن فيه المصابحا)\n(إذا هي حلت كربلاء فلعلعا ... فجوز العذيب دونها فالنوابحا)\n(وبانت نواها من نواك وطاوعت ... مع الشانئين الشامتات الكواشحا)\n(فقولا لليلى هل تعوض نادما ... له رجعة قال الطلاق ممازحا)\n(فإن هي قالت لا فقولا لها بلى ... ألا تتقين الجاريات الذوابحا)\nهي قصيدة طويلة فلما انصرف وليست ليلى معه قالت له امرأته أم حقة ما فعلت ليلى قال طلقتها قالت والله لو كان فيك خير ما فعلت ذلك فطلقني أنا أيضا فقال لها معن\n(أعاذل أقصري ودعي بياتي ... فإنك ذات لومات حمات)\n(فإن الصبح منتظر قريب ... وإنك بالملامة لن تفاتي)\n(نأت ليلى فليلى لاتواتي ... وضنت بالمودة والبتات)\n(وحلت دارها سفوان بعدي ... فذا قار فمنخرق الفرات)\n(تراعى الريف دائبة عليها ... ظلال ألف مختلط النبات)\n(فدعها أو تناولها لعنس ... من العيدي في قلص شخات)\nهي قصيدة طويلة قال وقال لأم حقة في مطالبتها إياه بالطلاق\n(كأن لم يكن يا أم حقة قبل ذا ... بميطان مصطاف لنا ومرابع)\n(وإذ نحن في غصن الشباب وقد عسا ... بنا الآن إلا أن يعوض جازع)\n(فقد أنكرته أم حقة حادثا ... وأنكرها ما شئت والود خادع)\n(ولو آذنتنا أم حقة إذ بنا ... شباب وإذ لما ترعنا الروائع)\n(لقلنا لها بيني بليل حميدة ... كذاك بلا ذم تؤدى الودائع)\n\n(أعابد حييتم على النأي عابدا ... سقاك الإله المنشآت الرواعدا)\n(أعابد ما شمس النهار إذا بدت ... بأحسن مما بين عينيك عابدا)\nيروى\n(أعابد ما شمس النهار بدت لنا ... )\nيروى\n(أعابد ما الشمس التي برزت لنا ... بأحسن مما بين ثوبيك عابدا)","topic":"أخبار معن بن أوس ونسبه","topicNo":131,"sp":2,"spl":"خروجه إلى البصرة","song":1,"loc":2170,"partial":1},
{"id":"b131-6","bab":"الجزء 12","sec":"خروجه إلى البصرة — أخبار الحسين بن عبد الله","page":"ج12 ص77 – ج12 ص83","text":"لشعر للحسين بن عبد الله بن عبيد الله بن العباس بن عبد المطلب والغناء لعطرد ثاني ثقيل بالبنصر وفيه ليونس لحن من كتابه غير مجنس\nقد تقدم نسبه وهو أشهر من أن يعاد ويكنى أبا عبد الله وكان من فتيان بني هاشم وظرفائهم وشعرائهم وقد روى الحديث وحمل عنه وله شعر صالح وهذه الأبيات يقولها في زوجته عابدة بنت شعيب بن محمد بن عبد الله بن عمرو بن العاص وهي أخت عمرو بن شعيب الذي يروى عنه الحديث وفيها يقول قبل أن يتزوجها\n(أعاذل إن الحب لا شك قاتلي ... لئن لم تقارضني هوى النفس عابده)\n(أعابد خافي الله في قتل مسلم ... وجودي عليه مرة قط واحده)\n(فإن لم تريدي في أجرا ولا هوى ... لكم غير قتلي يا عبيد فراشده)\n(فكم ليلة قد بت أرعى نجومها ... وعبدة لا تدري بذلك راقده)\nلغناء لحكم الوادي رمل بإطلاق الوتر في مجرى البنصر عن\nإسحاق فمما حمل عنه من الحديث ماحدثني به أحمد بن سعيد قال حدثني محمد بن عبيد الله بن المنادى قال حدثني يونس بن محمد قال حدثنا أبو أويس عن حسين بن عبد الله بن عبيد الله بن عباس عن عكرمة عن ابن عباس قال مر النبي على حسان بن ثابت وهو في ظل فارع وحوله أصحابه وجاريته سيرين تغنيه بمزهرها\n(هل علي ويحكما ... إن لهوت من حرج)\nضحك النبي ثم قال لا حرج إن شاء الله وكانت أم عابدة هذه عمة حسين بن عبد الله بن عبيد الله أمها عمرة بنت عبيد الله بن العباس تزوجها شعيب فولدت له محمدا وشعيبا ابني شعيب وعابدة وكان يقال لها عابدة الحسن وعابدة الحسناء أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار قال\nحدثني محمد بن يحيى قال خطب عابدة بنت شعيب بكار بن عبد الملك وحسين بن عبد الله فامتنعت على بكار وتزوجت الحسين فقال له بكار كيف تزوجتك العابدة واختارتك مع فقرك فقال له الحسين أتعيرنا بالفقر وقد نحلنا الله تعالى الكوثر أخبرني الحرمي والطوسي قالا حدثنا الزبير بن بكار عن عمه قال كان حسين بن عبد الله أمه أم ولد وكان يقول شيئا من الشعر وتزوج عابدة بنت شعيب وولدت منه وبسببها ردت على ولد عمرو بن العاص أموالهم في دولة بني العباس وكان عبد الله بن معاوية بن عبد الله بن جعفر صديقا له ثم تنكر ما بينهما فقال فيه ابن معاوية\n(إن ابن عمك وابن أمك ... معلم شاكي السلاح)\n(يقص العدو وليس يرضى ... حين يبطش بالجراح)\n(لا تحسبن أذى ابن عمك شرب لالبان اللقاح ... )\n(بل كالشجاة ورا اللهاة ... إذا تسوغ بالقراح)\n(فاختر لنفسك من يجي ... بك تحت أطراف الرماح)\n(من لا يزال يسوءه ... بالغيب أن يلحاك لاح)\nفقال حسين له\n(أبرق لمن يخشى وأوعد ... غير قومك بالسلاح)\n(لسنا نقر لقائل ... إلا المقرط بالصلاح)\nال ولحسين يقول ابن معاوية\n(قل لذي الود والصفاء حسين ... اقدر الود بيننا قدره)\n(ليس للدابغ المحلم بد ... من عتاب الأديم ذي البشره)\n(لست إن راغ ذو إخاء وود ... عن طريق بتابع أثره)\n(بل أقيم القناة والود حتى ... يتبع الحق بعد أو يذره)\nخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن محمد ابن سلام قال","topic":"أخبار معن بن أوس ونسبه","topicNo":131,"sp":3,"spl":"خروجه إلى البصرة — أخبار الحسين بن عبد الله","loc":2171,"partial":1},
{"id":"b131-7","bab":"الجزء 12","sec":"كان صديقا لابن أبي السمح","page":"ج12 ص86","text":"كان مالك بن أبي السمح الطائي المغني صديقا للحسين بن عبد الله بن عبيد الله بن العباس ونديما له وكان يتغنى في اشعاره وله يقول الحسين رحمه الله تعالى\n(لا عيش إلا بمالك بن أبي السمح فلا تلحني ولا تلم ... )\n(أبيض كالسيف أو كما يلمع البارق ... في حندس من الظلم)\n(يصيب من لذة الكريم ولا ... يهتك حق الإسلام والحرم)\n(يا رب ليل لنا كحاشية البرد ... ويوم كذاك لم يدم)\n(قد كنت فيه ومالك بن أبي السمح ... الكريم الأخلاق والشيم)\n(من ليس يعصيك إن رشدت ولا ... يجهل آي الترخيص في اللمم)\nقال فقال له مالك ولا إن غويت والله بأبي أنت وأمي أعصيك قال وغنى مالك بهذه الأبيات بحضرة الوليد بن يزيد فقال له أخطأ حسين في صفتك إنما كان ينبغي أن يقول\n(أحول كالقرد أو كما يخرج السارق ... في حالك من الظلم)\nخبرني الحسين بن يحيى عن حماد عن أبيه قال كان الحسين بن عبد الله بن عبيد الله بن العباس إذا صلى العصر دخل منزله سمع الغناء عشيته فأتاه قوم ذات عشية في حاجة لهم فقضاها ثم جلسوا يحدثونه فلما أطالوا قال لهم أتأذنون فقالوا نعم فقام في أصحاب له وهو يقول\n(قوموا بنا ندرك من العيش لذة ... ولا اثم فيها للتقي ولا عارا)\n\n(إن حربا وإن صخرا أبا سفيان ... حازا مجدا وعزا تليدا)\n(فهما وارثا العلا عن جدود ... ورثوها آباءهم والجدودا)\nلشعر لفضالة بن شريك الأسدي من قصيدة يمدح بها يزيد بن معاوية وبعد هذين البيتين يقول\n(وحوى إرثها معاوية القرم ... وأعطى صفو التراث يزيدا)\nالغناء لإبراهيم بن خالد المعيطي ثقيل أول بالبنصر عن الهشامي والله أعلم","topic":"أخبار معن بن أوس ونسبه","topicNo":131,"sp":4,"spl":"كان صديقا لابن أبي السمح","song":1,"loc":2172,"partial":1},
{"id":"b132-1","bab":"الجزء 12","sec":"أخبار فضالة بن شريك ونسبه","page":"ج12 ص89","text":"هو فضالة بن شريك بن سلمان بن خويلد بن سلمة بن عامر موقد النار بن الحريش بن نمير بن والبة بن الحارث بن ثعلبة بن دودان بن أسد بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وكان شاعرا فاتكا صعلوكا مخضرما أدرك الجاهلية والإسلام وكان له ابنان شاعران أحدهما عبد الله بن فضالة الوافد على عبد الله بن الزبير والقائل له إن ناقتي قد نقبت ودبرت فقال له ارقعها بجلد واخصفها بهلب وسر بها البردين فقال له إني قد جئتك مستحملا لا مستشيرا فلعن الله ناقة حملتني إليك فقال له ابن\nالزبير إن وراكبها فانصرف من عنده وهو يقول\n(أقول لغلمتي شدوا ركابي ... أجاوز بطن مكة في سواد)\n(فمالي حين أقطع ذات عرق ... إلى ابن الكاهلية من معاد)\n(سيبعد بيننا نص المطايا ... وتعليق الأداوى والمزاد)\n(وكل معبد قد أعلمته ... مناسمهن طلاع النجاد)\n(أرى الحاجات عند أبي خبيب ... نكدن ولا أمية بالبلاد)\n(من الأعياص أو من آل حرب ... أغر كغرة الفرس الجواد)\nدثنا بذلك محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز المدائني فأما فاتك بن فضالة فكان سيدا جوادا وله يقول الأقيشر يمدحه\n(وفد الوفود فكنت أفضل وافد ... يا فاتك بن فضالة بن شريك)\nخبرني بما أذكر من أخباره هاهنا مجموعا علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري عن محمد بن حبيب وما ذكرته متفرقا فأنا ذاكر إسناده عمن أخذته قال ابن حبيب","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":0,"spl":"أخبار فضالة بن شريك ونسبه","loc":2173},
{"id":"b132-2","bab":"الجزء 12","sec":"فضالة الهجاء","page":"ج12 ص91","text":"مر فضالة بن شريك بعاصم بن عمر بن الخطاب رضي الله عنهما وهو متبد بناحية المدينة فنزل به فلم يقره شيئا ولم يبعث إليه ولا إلى أصحابه\nبشيء وقد عرفوه مكانهم فارتحلوا عنه والتفت فضالة إلى مولى لعاصم فقال له قل له أما والله لأطوقنك طوقا لا يبلى وقال يهجوه\n(ألا أيها الباغي القرى لست واجدا ... قراك إذا ما بت في دار عاصم)\n(إذا جئته تبغي القرى بات نائما ... بطينا وأمسى ضيفه غير نائم)\n(فدع عاصما أف لأفعال عاصم ... إذا حصل الأقوام أهل المكارم)\n(فتى من قريش لا يجود بنائل ... ويحسب أن البخل ضربة لازم)\n(ولولا يد الفاروق قلدت عاصما ... مطوقة يحدى بها في المواسم)\n(فليتك من جرم بن زبان أو بني ... فقيم أو النوكى أبان بن دارم)\n(أناس إذا ما الضيف حل بيوتهم ... غدا جائعا عيمان ليس بغانم)\nال فلما بلغت أبياته عاصما استعدى عليه عمرو بن سعيد بن العاص وهو يؤمئذ بالمدينة أمير فهرب فضالة بن شريك فلحق بالشأم وعاذ بيزيد بن معاوية وعرفه ذنبه وما تخوف من عاصم فأعاذه وكتب إلى عاصم يخبره أن فضالة أتاه مستجيرا به وأنه يحب أن يهبه له ولا يذكر لمعاوية شيئا من أمره ويضمن له ألا يعود لهجائه فقبل ذلك عاصم وشفع يزيد بن معاوية فقال فضالة يمدح يزيد بن معاوية\n(إذا ما قريش فاخرت بقديمها ... فخرت بمجد يا يزيد تليد)\n(بمجد أمير المؤمنين ولم يزل ... أبوك أمين الله غير بليد)\n(به عصم الله الأنام من الردى ... وأدرك تبلا من معاشر صيد)\n(ومجد أبي سفيان ذي الباع والندى ... وحرب وما حرب العلا بزهيد)\n(فمن ذا الذي إن عدد الناس مجدهم ... يجيء بمجد مثل مجد يزيد)\nوقال فيه القصيدة المذكور فيها الغناء في هذه القصة بعينها أخبرني علي بن سليمان الأخفش قال حدثني السكري عن ابن حبيب قال كان عبد الله بن الزبير قد ولى عبد الله بن مطيع بن الأسود بن نضلة بن عبيد بن عويج بن عدي بن كعب الكوفة فطرده عنها المختار بن أبي عبيد حين ظهر فقال فضالة بن شريك يهجو ابن مطيع\n(دعا ابن مطيع للباع فجئته ... إلى بيعة قلبي بها غير عارف)\n(فقرب لي خشناء لما لمستها ... بكفي لم تشبه أكف الخلائف)\n(معودة حمل الهراوى لقومها ... فرورا إذا ما كان يوم التسايف)\n(من الشثنات الكرم أنكرت لمسها ... وليست من البيض السياط اللطائف)\n(ولم يسم إذ بايعته من خليفتي ... ولم يشترط إلا اشتراط المجازف)\n(متى تلق أهل الشأم في الخيل تلقني ... على مقرب لا يزدهى بالمجاذف)\n(ممر كبنيان العبادي مخطف ... من الضاريات بالدماء الخواطف)\nقال ابن حبيب في هذا الإسناد تزوج عامر بن مسعود بن أمية بن خلف الجمحي امرأة من بني نصر بن معاوية وسأل في صداقها بالكوفة فكان يأخذ من كل رجل سأله درهمين درهمين فقال له فضالة بن شريك يهجوه بقوله\n(أنكحتم يا بني نصر فتاتكم ... وجها يشين وجوه الربرب العين)\n(أنكحتم لا فتى دنيا يعاش به ... ولا شجاعا إذا انشقت عصا الدين)\n(قد كنت أرجو أبا حفص وسنته ... حتى نكحت بأرزاق المساكين)\nقال ابن حبيب في هذا الإسناد أودع فضالة بن شريك رجلا من بني سليم يقال له قيس ناقة فخرج في سفر فلما عاد طلبها منه فذكر أنها سرقت فقال فيه\n(ولو أنني يوم بطن العقيق ... ذكرت وذو اللب ينسى كثيرا)\n(مصاب سليم لقاح النبي لم ... أودع الدهر فيهم بعيرا)\n(وقد فات قيس بعيرانة ... إذا الظل كان مداه قصيرا)\n(من اللاعبات بفضل الزمام ... إذا أقلق السير فيه الضفورا)\n(ومن يبك منكم بني موقد ... ولم يرهم يبك شجوا كبيرا)\n(هم العاسفون صلاب القنا ... إذا الخيل كانت من الطعن زورا)\n(وأيسار لقمان إذ أمحلوا ... وعز لمن جاءهم مستجيرا)\n(فإن أنا لم يقض لي ألقهم ... قرأت السلام عليهم كثيرا)\nوذكر ابن حبيب في هذه الرواية أن القصيدة التي ذكرتها عن المدائني في خبر عبد الله بن فضالة بن شريك مع ابن الزبير كانت مع فضالة وابن الزبير لا مع ابنه وذكر الأبيات وزاد فيها\n(شكوت إليه أن نقبت قلوصي ... فرد جواب مشدود الصفاد)\n(يضن بناقة ويروم ملكا ... محال ذلكم غير السداد)\n(وليت إمارة فبخلت لما ... وليتهم بملك مستفاد)\n(فإن وليت أمية أبدلوكم ... بكل سميدع واري الزناد)\n(من الأعياص أو من آل حرب ... أغر كغرة الفرس الجواد)\n(إذا لم ألقهم بمنى فإني ... ببيت لا يهش له فؤادي)\n(سيدنيني لهم نص المطايا ... وتعليق الأداوى والمزاد)","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":1,"spl":"فضالة الهجاء","loc":2174},
{"id":"b132-3","bab":"الجزء 12","sec":"فضالة الهجاء","page":"ج12 ص91","text":"(وظهر معبد قد أعلمته ... مناسمهن طلاع النجاد)\n(رعين الحمض حمض خناصرات ... وما بالعرق من سبل الغوادي)\n(فهن خواضع الأبدان قود ... كأن رؤوسهن قبور عاد)\n(كأن مواقع الغربان منها ... منارات بنين على عماد)\nقال فلما ولي عبد الملك بعث إلى فضالة يطلبه فوجده قد مات فأمر لورثته بمائة ناقة تحمل وقرها برا وتمرا قال والكاهلية التي ذكرها زهرة بنت خنثر امرأة من بني كاهل بن أسد وهي أم خويلد بن أسد بن عبد العزى\n(لقد طال عهدي بالإمام محمد ... وما كنت أخشى أن يطول به عهدي)\n(فأصبحت ذا بعد وداري قريبة ... فواعجبا من قرب داري ومن بعدي)\n(فيا ليت أن العيد لي عاد يومه ... فإني رأيت العيد وجهك لي يبدي)\n(رأيتك في برد النبي محمد ... كبدر الدجى بين العمامة والبرد)\nلشعر لأبي السمط مروان الأصغر بن أبي الجنوب بن مروان الأكبر بن أبي حفصة والغناء لبنان خفيف رمل مطلق ابتداؤه ونشيد وذكر الصولي أن هذا الشعر ليحيى بن مروان وهذا غلط قبيح","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":2,"spl":"فضالة الهجاء — أخبار مروان الأصغر — مدحه المتوكل","song":1,"loc":2175},
{"id":"b132-5","bab":"الجزء 12","sec":"أخبار مروان الأصغر — مدحه المتوكل","page":"ج12 ص98 – ج12 ص99","text":"قد مر نسبه ونسب أبيه وأهله وأخبارهم متقدما وكان مروان هذا آخر من بقي منهم يعد في الشعراء وبقي بعده منهم متوج وكان ساقطا بارد الشعر فذكر لي عن أبي هفان أنه قال شعر آل أبي حفصة بمنزلة الماء الحار ابتداؤه في نهاية الحرارة ثم تلين حرارته ثم يفتر ثم يبرد وكذا كانت أشعارهم إلا أن ذلك الماء لما انتهى إلى متوج جمد وهذا الشعر يقوله مروان في المنتصر وكان قد أقصاه وجفاه وأظهر خلافا لأبيه في سائر مذاهبه حتى في التشيع فطرد مروان لنصبه وأخرجه عن جلسائه فقال هذه الأبيات وسأل بنان بن عمرو فغنى فيها المنتصر ليستعطفه وخبره في ذلك يذكر في هذا الموضع من الكتاب\nأخبرني عمي وحبيب بن نصر المهلبي قالا حدثنا عبد الله بن أبي سعد قال حدثني حماد بن أحمد بن سليمان الكلبي قال حدثني أبو السمط مروان الأصغر قال لما دخلت إلى المتوكل مدحته ومدحت ولاة العهود الثلاثة وأنشدته\n(سقى الله نجدا والسلام على نجد ... ويا حبذا نجد على النأي والبعد)\n(نظرت إلى نجد وبغداد دونها ... لعلي أرى نجدا وهيهات من نجد)\n(ونجد بها قوم هواهم زيارتي ... ولا شيء أحلى من زيارتهم عندي)\nال فلما فرغت منها أمر لي بمائة وعشرين ألف درهم وخمسين ثوبا وثلاثة من الظهر فرس وبغلة وحمار ولم أبرح حتى قلت قصيدتي التي أشكره فيها وأقول\n(تخير الناس للناس جعفرا ... وملكه أمر العباد تخيرا)\nلما صرت إلى هذا البيت\n(فأمسك ندى كفيك عني ولا تزد ... فقد كدت أن أطغى وأن أتجبرا)\nال لي لا والله لا أمسك حتى أغرقك بجودي وحدثني عمي بهذا الخبر قال حدثني أحمد بن أبي طاهر قال حدثني\nحماد بن أحمد بن يحيى قال حدثني مروان بن أبي الجنوب فذكر مثل هذا الخبر سواء وقال بعد قوله لا والله لا أمسك حتى أغرقك سلني حاجتك فقلت يا أمير المؤمنين الضيعة التي أمرت أن أقطعها باليمامة ذكر ابن المدبر أنها وقف المعتصم على ولده فقال قد قبلتك إياها مائة سنة بمائة درهم فقلت لا يحسن أن تضمن ضيعة بدرهم في السنة فقال ابن المدبر فبألف درهم في كل سنة فقلت نعم فأمر ابن المدبر أن ينفذ ذلك لي وقال ليست هذه حاجة هذه قبالة فسليني حاجتك فقلت ضيعة يقال لها السيوح أمر الواثق بإقطاعي إياها فمنعنيها ابن الزيات فأمر بإمضاء الإقطاع لي","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":2,"spl":"فضالة الهجاء — أخبار مروان الأصغر — مدحه المتوكل","loc":2176},
{"id":"b132-6","bab":"الجزء 12","sec":"هجاؤه علي بن الجهم","page":"ج12 ص100","text":"حدثني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال كان علي بن الجهم يطعن على مروان بن أبي الجنوب ويثلبه حسدا له على موضعه من المتوكل فقال له المتوكل يوما يا علي أيما أشعر أنت أو مروان فقال أنا يا أمير المؤمنين فأقبل على مروان فقال له قد\nسمعت فما عندك قال كل أحد أشعر مني يا أمير المؤمنين وما أصف نفسي ولا أزكيها وإذا رضيني أمير المؤمنين فماأبالي من زيفني فقال له قد صدقتك علي يزعم سرا وجهرا أنه أشعر منك فالتفت إليه مروان فقال له يا علي أأنت أشعر مني فقال أوتشك في ذاك قال نعم أشك وأشك وهذا أمير المؤمنين بيننا فقال له علي إن أمير المؤمنين يحابيك فقال المتوكل هذا عي منك يا علي ثم قال لابن حمدون احكم بينهما فقال طرحتني والله يا أمير المؤمنين بين أنياب ومخالب أسدين قال والله لتحكمن بينهما فقال له أما إذ حلفت يا أمير المؤمنين فأشعرهما عندي أعرفهما في الشعر فقال له المتوكل قد سمعت يا علي قال قد عرف ميلك إليه فمال معه فقال دعنا منك هذا كله عي فإن كنت صادقا فاهج مروان قال قد سكرت ولا فضل في فقال المتوكل لمروان اهجه أنت وبحياتي لا تبق غاية فقال مروان\n(إن ابن جهم في المغيب يعيبني ... ويقول لي حسنا إذا لاقاني)\n(صغرت مهابته وعظم بطنه ... فكأنما في بطنه ولدان)\n(ويح ابن جهم ليس يرحم أمه ... لو كان يرحمها لما عاداني)\n(فإذا التقينا ناك شعري شعره ... ونزا على شيطانه شيطاني)\nال فضحك المتوكل والجلساء منه وانخزل ابن الجهم فلم يكن عنده أكثر من أن قال جمع حيلة الرجال وحيلة النساء فقال له المتوكل\nهذا أيضا من عيك وبردك إن كان عندك شيء فهاته فلم يأت بشيء فقال لمروان بحياتي إن حضرك شيء فهاته ولا تقصر في شتمك فقال مروان\n(لعمرك ما الجهم بن بدر بشاعر ... وهذا علي بعده يدعي الشعرا)\n(ولكن أبي قد كان جارا لأمه ... فلما ادعى الأشعار أوهمني أمرا)\nقال فضحك المتوكل وقال زده بحياتي فقال فيه\n(يابن بدر ياعليه ... قلت إني قرشيه)\n(قلت ما ليس بحق ... فاسكتي يانبطيه)\n(اسكتي يا بنت جهم ... اسكتي يا حلقيه)\nأخذ عبادة هذه الأبيات فغناها على الطبل وجاوبه من كان يغني والمتوكل يضحك ويضرب بيديه ورجليه وعلي مطرق كأنه ميت ثم قال علي بالدواة فأتي بها فكتب\n(بلاء ليس يشبهه بلاء ... عداوة غير ذي حسب ودين)\n(يبيحك منه عرضا لم يصنه ... ويرتع منك في عرض مصون)\nخبرني علي بن العباس بن أبي طلحة قال حدثني جعفر بن هارون بن زياد قال حدثني محمد بن السري قال لما مدح علي بن الجهم وهو محبوس المتوكل بقوله\n(توكلنا على رب السماء ... وسلمنا لأسباب القضاء)\nوذكر فيها جميع الندماء وسبعهم وهجاهم انتدب له مروان بن أبي الجنوب فعارضه فيها وقد كان المتوكل رق له فلما أنشده مروان هذه القصيدة اعتورته ألسنة الجلساء فثلبوه واغتابوه وضربوا عليه فتركه في محبسه والقصيدة\n(ألم تعلم بأنك يابن جهم ... دعي في أناس أدعياء)\n(أعبد الله تهجو وابن عمر ... وبختيشوع أصحاب الوفاء)\n(هجوت الأكرمين وأنت كلب ... حقيق بالشتيمة والهجاء)\n(أترمي بالزناء بني حلال ... وأنت زنيم أولاد الزناء)\n(أسامة من جدودك يابن جهم ... كذبت وما بذلك من خفاء)\nخبرني محمد بن يحيى الصولي قال حدثنا الحسين بن يحيى قال حدثني إبراهيم بن الحسن قال لما كان من أمر العباس بن المأمون وعجيف ما كان أنشد مروان بن أبي الجنوب المعتصم قصيدة أولها\n(ألا يا دولة المعصوم دومي ... فإنك قلت للدنيا استقيمي)\nلما بلغ إلى قوله\n(هوى العباس حين أراد غدرا ... فوافى إذ هوى قعر الجحيم)\n(كذاك هوى كمهواه عجيف ... فأصبح في سواء لظى الحميم)\nقال المعتصم أبعده الله حدثني جعفر بن قدامة قال حدثنا أبو العيناء قال دخل مروان الأصغر بن أبي الجنوب على أشناس وقد مدحه بقصيدة فأنشده إياها فجعل أشناس يحرك رأسه ويومىء بيديه ويظهر طربا وسرورا وأمر له بصلة فلماخرج قال له كاتبه رأيت الأمير قد طرب وحرك رأسه ويديه لماكان يسمعه فقد فهمه قال نعم قال فأي شيء كان يقول قال ما زال يقول على رقية الخبز حتى حصل ما أراد وانصرف حدثني جعفر بن قدامة قال حدثني علي بن يحيى المنجم قال كان المتوكل يعابثني كثيرا فقال في يوم من الأيام لمروان بن أبي الجنوب اهج علي بن يحيى فقال مروان","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":3,"spl":"هجاؤه علي بن الجهم","loc":2177},
{"id":"b132-7","bab":"الجزء 12","sec":"هجاؤه علي بن الجهم","page":"ج12 ص100","text":"(ألا إن يحيى لا يقاس إلى أبي ... وعرض ابن يحيى لا يقاس إلى عرضي)\nهي أبيات تركت ذكرها صيانة لعلي بن يحيى قال فأجبته عنها فقلت\n(صدقت لعمري ما يقاس إلى أبي ... أبوك ومن قاس الشواهق بالخفض)\n(وهل لك عرض طاهر فتقيسه ... إذا قيست الأعراض يوما إلى عرضي)\n(ألستم موالي للعين ورهطه ... أعادي بني العباس ذي الحسب المحض)\n(توالون من عادى النبي ورهطه ... فترمون من والي أولي الفضل بالرفض)\n(وليس عجيبا أن أرى لك مبغضا ... لأنك أهل للعداوة والبغض)\nحدثني جحظة قال حدثني علي بن يحيى قال أنشد مروان بن أبي الجنوب المتوكل ذات يوم\n(إني نزلت بساحة المتوكل ... ونزلت في أقصى ديار الموصل)\nقال له بعض من حضر فكيف الاتصال بين هؤلاء والمراسلة فقال أبو العنبس الصيمري كان له حمام هدى يبعث بها إليه من الموصل حتى يكاتبه على أجنحتها فضحك المتوكل حتى استلقى وخجل مروان وحلف بالطلاق لا يكلم أبا العنبس أبدا فماتا متهاجرين كذا أكبر حفظي أن جحظة حدثني به عن علي بن يحيى فإني كتبته عن حفظي","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":4,"spl":"هجاؤه علي بن الجهم — علي بن الجهم يتهمه بانتحال الشعر","loc":2178},
{"id":"b132-8","bab":"الجزء 12","sec":"علي بن الجهم يتهمه بانتحال الشعر","page":"ج12 ص105","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني إبراهيم بن المدبر قال قرأت في كتاب قديم\nقال عوف بن محلم لعبد الله بن طاهر في علة اعتلها\n(فإن تك حمى الربع شفك وردها ... فعقباك منها أن يطول لك العمر)\n(وقيناك لو نعطى المنى فيك والهوى ... لكان بنا الشكوى وكان لك الاجر)\nال ثم حم المتوكل حمى الربع فدخل عليه مروان بن أبي الجنوب بن مروان بن أبي حفصة فأنشده قصيدة له على هذا الروي وأدخل البيتين فيها فسر بها المتوكل فقال له علي بن الجهم يا أمير المؤمنين هذا شعر مقول والتفت إلي وقال هذا يعلم فالتفت إلي المتوكل وقال أتعرفه فقلت ما سمعته قبل اليوم فشتم علي بن الجهم وقال له هذا من حسدك وشرك وكذبك فلما خرجنا قال علي بن الجهم ويحك ما لك قد جننت أما تعرف هذا الشعر قلت بلى وأنشدته إياه فلما عدت إلى المتوكل من غد قال له يا أمير المؤمنين قد اعترف لي بالشعر وأنشدنيه فقال لي أكذاك هو فقلت كذب يا أمير المؤمنين ما سمعت به قط فازداد عليه غيظا وله شتما فلما خرجنا قال لي ما في الأرض\nشر منك فقلت له أنت أحمق تريد مني أن أجيء إلى شعر قد قاله فيه شاعر يحبه ويعجبه شعره فأقول له إني أعرفه فأوقع نفسي وعرضي في لسان الشاعر لترتفع أنت عنده ويسقط ذاك ويبغضني أنا\n(ما لإبراهيم في العلم ... بهذا الشأن ثان)\n(إنما عمر أبي إسحاق زين للزمان ... )\n(فإذا غنى أبو اسحاق ... أجابته المثاني)\n(منه يجنى ثمر اللهو ... وريحان الجنان)\n(جنة الدنيا أبو إسحاق ... في كل مكان)\nعروضه من الرمل - الشعر لابن سيابة والغناء لإبراهيم الموصلي خفيف ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق ابنه","topic":"أخبار فضالة بن شريك ونسبه","topicNo":132,"sp":4,"spl":"هجاؤه علي بن الجهم — علي بن الجهم يتهمه بانتحال الشعر","song":1,"loc":2179,"partial":1},
{"id":"b133-1","bab":"الجزء 12","sec":"أخبار إبراهيم بن سيابة ونسبه","page":"ج12 ص108","text":"إبراهيم بن سيابة مولى بني هاشم وكان يقال إن جده حجام أعتقه بعض الهاشميين وهو من مقاربي شعراء وقته ليست له نباهة ولا شعر شريف وإنما كان يميل بمودته ومدحه إلى إبراهيم الموصلي وابنه إسحاق فغنيا في شعره ورفعا منه وكانا يذكرانه للخلفاء والوزراء ويذكرانهم به إذا غنيا في شعره فينفعانه بذلك وكان خليعا ماجنا طيب النادرة وكان يرمى بالأبنة أخبرني عيسى بن الحسين الوراق قال حدثنا يعقوب بن إسرائيل قال حدثني أبو زائدة عن جعفر بن زياد قال عشق ابن سيابة جارية سوداء فلامه أهله على ذلك وعاتبوه فقال\n(يكون الخال في وجه قبيح ... فيكسوه الملاحة والجمالا)\n(فكيف يلام معشوق على من ... يراها كلها في العين خالا)\nخبرني محمد بن مزيد وعيسى بن الحسين والحسين بن يحيى قالوا حدثنا حماد بن إسحاق عن أبيه قال لقي إبراهيم بن سيابة وهو سكران ابنا لسوار بن عبد الله القاضي أمرد\nفعانقه وقبله وكانت معه داية يقال لها رحاص فقيل لها إنه لم يقبله تقبيل السلام إنما قبله قبلة شهوة فلحقته الداية فشتمته وأسمعته كل ما يكره وهجره الغلام بعد ذلك فقال له\n(قل للذي ليس لي من ... يدي هواه خلاص)\n(أأن لثمتك سرا ... فأبصرتني رحاص)\n(وقال في ذاك قوم ... على انتقاصي حراص)\n(هجرتني وأتتني ... شتيمة وانتقاص)\n(فهاك فاقتص مني ... إن الجروح قصاص)\nيروى أن رحاص هذه مغنية كان الغلام يحبها وأنه سكر ونام فقبله ابن سيابة فلما انتبه قال للجارية ليت شعري ما كان خبرك مع ابن سيابة فقالت له سل عن خبرك أنت معه وحدثته بالقصة فهجره الغلام فال هذا الشعر أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثنا علي بن الصباح قال عاتبنا ابن سيابة على مجونة فقال ويلكم لأن ألقى الله تبارك وتعالى بذل المعاصي فيرحمني أحب إلي من أن ألقاه أتبختر إدلالا بحسناتي فيمقتني قال ورأيت ابن سيابة يوما وهو سكران وقد حمل في طبق يعبرون به على الجسر فسألهم إنسان ما هذا فرفع رأسه من الطبق وقال هذا بقية مما\nترك آل موسى وآل هارون تحمله الملائكة يا كشخان أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا أبو الشبل البرجمي قال ولع يوما أبو الحارث جميز بابن سيابة حتىأخجله فقال عند ذلك ابن سيابة يهجوه\n(بنى أبو الحارث الجميز في وسط ... من ظهره وقريبا من ذراعين)\n(ديرا لقس إذا ما جاء يدخله ... ألقى على باب دير القس خرجين)\n(يعدو على بطنه شدا على عجل ... لا ذو يدين ولا يمشي برجلين)\nخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إبراهيم تينة قال كتب ابن سيابة إلى صديق له يقترض منه شيئا فكتب إليه يعتذر له ويحلف أنه ليس عنده ما سأله فكتب إليه إن كنت كاذبا فجعلك الله صادقا وإن كنت ملوما فجعلك الله معذورا أخبرني محمد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن ابيه قال كان ابن سيابة الشاعر عندنا يوما مع جماعة نتحدث ونتناشد وهو ينشدنا شيئا من شعره فتحرك فضرط فضرب بيده على استه غير مكترث ثم قال إما أن تسكتي حتى أتكلم وإما أن تتكلمي حتى أسكت أخبرني علي بن صالح بن الهيثم الأنباري الكاتب قال حدثني أبو هفان قال غمز ابن سيابة غلاما أمرد ذات يوم فأجابه ومضى به إلى منزله فأكلا وجلسا يشربان فقال له الغلام أنت ابن سيابة الزنديق قال نعم قال\nأحب أن تعلمني الزندقة قال أفعل وكرامة ثم بطحه على وجهه فلما تمكن منه أدخل عليه فصاح الغلام أوه أيش هذا ويحك قال سألتني أن أعلمك الزندقة وهذا أول باب من شرائعها أخبرني الحسين بن القاسم الكوكبي قال حدثني محرز بن جعفر الكاتب قال قال لي إبراهيم بن سيابة الشاعر إذا كانت في جيرانك جنازة وليس في بيتك دقيق فلا تحضر الجنازة فإن المصيبة عندك أكبر منها عند القوم وبيتك أولى بالمأتم من بيتهم أخبرني جعفر بن قدامة ومحمد بن مزيد قالا حدثنا حماد بن إسحاق عن أبيه قال سخط الفضل بن الربيع على ابن سيابة فسألته أن يرضى عنه فامتنع فكتب إليه ابن سيابة بهذه الأبيات وسألني أيصالها\n(إن كان جرمي قد أحاط بحرمتي ... فأحط بجرمي عفوك المأمولا)\n(فكم ارتجيتك في التي لا يرتجى ... في مثلها أحد فنلت السولا)\n(وضللت عنك فلم أجد لي مذهبا ... ووجدت حلمك لي عليك دليلا)\n(هبني أسأت وما أسأت أقر كي ... يزداد عفوك بعد طولك طولا)","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":0,"spl":"أخبار إبراهيم بن سيابة ونسبه","loc":2180},
{"id":"b133-2","bab":"الجزء 12","sec":"أخبار إبراهيم بن سيابة ونسبه","page":"ج12 ص108","text":"(فالعفو أجمل والتفضل بامرىء ... لم يعدم الراجون منه جميلا)\nلما قرأها الفضل دمعت عيناه ورضي عن ابن سيابة وأوصله إليه وأمر له بعشرة آلاف درهم","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":1,"spl":"أخبار إبراهيم بن سيابة ونسبه — حواره المقذع مع بشار","loc":2181},
{"id":"b133-3","bab":"الجزء 12","sec":"حواره المقذع مع بشار","page":"ج12 ص112","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا الحسن بن الفضل قال سمعت ابن عائشة يقول جاء إبراهيم بن سيابة إلى بشار فقال له ما رأيت أعمى قط إلا وقد عوض من بصره إما الحفظ والذكاء وإما حسن الصوت فأي شيء عوضت أنت قال ألا أرى ثقيلا مثلك ثم قال له من أنت ويحك قال إبراهيم بن سيابة فتضاحك ثم قال لو نكح الأسد في استه لذل وكان إبراهيم يرمى بذلك ثم تمثل بشار\n(لو نكح الليث في استه خضعا ... ومات جوعا ولم ينل شبعا)\n(كذلك السيف عند هزته ... لو بصق الناس فيه ما قطعا)\nخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني عبد الله بن أبي نصر المروزي قال حدثني محمد بن عبد الله الطلحي قال حدثني سليمان بن يحيى بن معاذ قال قدم إبراهيم بن سيابة نيسابور فأنزلته علي فجاءني ليلة من الليالي\nوهو مهرب فجعل يصيح بي يا أبا أيوب فخشيت أن يكون قد غشيه شيء يؤذيه فقلت ما تشاء فقال\n(أعياني الشادن الربيب ... )\nقلت بماذا فقال\n(أكتب أشكو فلا يجيب ... )\nال فقلت له داره وداوه فقال\n(من أين أبغي شفاء ما بي ... وانما دائي الطبيب)\nقلت لا دواء إذا إلا أن يفرج الله تعالى فقال\n(يا رب فرج إذا وعجل ... فإنك السامع المجيب)\nم انصرف في هذا الشعر - رمل - طنبوري لجحظة\n(أيا شجر الخابور مالك مورقا ... كأنك لم تحزن على ابن طريف)\n(فتى لا يحب الزاد إلا من التقى ... ولا المال إلا من قنا وسيوف)\nالشعر لأخت الوليد بن طريف الشاري والغناء لعبد الله بن طاهر ثقيل أول بالوسطى من رواية ابنه عبيد الله عنه وأول هذه الأبيات كما أنشدنا محمد بن العباس اليزيدي عن أحمد بن يحيى ثعلب\n(بتل بنانا رسم قبر كأنه ... على علم فوق الجبال منيف)\n(تضمن جودا حاتميا ونائلا ... وسورة مقدام وقلب حصيف)\n(ألا قاتل الله الجثا حيث أضمرت ... فتى كان بالمعروف غير عفيف)\n(فإن يك أرداه يزيد بن مزيد ... فيارب خيل فضها وصفوف)\n(ألا يا لقوم للنوائب والردى ... ودهر ملح بالكرام عنيف)\n(وللبدر من بين الكواكب إذ هوى ... وللشمس همت بعده بكسوف)\n(أيا شجر الخابور مالك مورقا ... كأنك لم تحزن على ابن طريف)\n(فتى لا يحب الزاد إلا من التقى ... ولا المال إلا من قنا وسيوف)\n(ولا الخيل إلا كل جرداء شطبة ... وكل حصان باليدين غروف)\n(فلا تجزعا يا ابني طريف فإنني ... أرى الموت نزالا بكل شريف)\n(فقدناك فقدان الربيع وليتنا ... فديناك من دهمائنا بألوف)\nهذه الأبيات تقولها أخت الوليد بن طريف ترثيه وكان يزيد بن مزيد قتله","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":1,"spl":"أخبار إبراهيم بن سيابة ونسبه — حواره المقذع مع بشار","song":1,"loc":2182,"partial":1},
{"id":"b133-4","bab":"الجزء 12","sec":"مقتل الوليد بن طريف","page":"ج12 ص115","text":"أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد عن عمه عن جماعة من الرواة قال كان الوليد بن طريف الشيباني رأس الخوارج وأشدهم بأسا وصولة وأشجعهم فكان من بالشماسية لا يأمن طروقه إياه واشتدت شوكته وطالت أيامه فوجه إليه الرشيد يزيد بن مزيد الشيباني فجعل يخاتله ويماكره وكانت البرامكة منحرفة عن يزيد بن مزيد فأغروا به أمير المؤمنين وقالوا إنما يتجافى عنه للرحم وإلا فشوكة الوليد يسيرة وهو يواعده وينتظر ما يكون من أمره فوجه إليه الرشيد كتاب مغضب يقول فيه لو وجهت بأحد الخدم لقام بأكثر مما تقوم به ولكنك مداهن متعصب وأمير المؤمنين يقسم بالله لئن أخرت مناجزة الوليد ليوجهن إليك من يحمل رأسك إلى أمير المؤمنين فلقي الوليد عشية خميس في شهر رمضان فيقال إن يزيد جهد\nعطشا حتى رمى بخاتمه في فيه فجعل يلوكه ويقول اللهم إنها شدة شديدة فاسترها وقال لأصحابه فداكم أبي وأمي إنما هي الخوارج ولهم حملة فاثبتوا لهم تحت التراس فإذا انقضت حملتهم فاحملوا فإنهم إذا انهزموا لم يرجعوا فكان كما قال حملوا حملة وثبت يزيد ومن معه من عشيرته وأصحابه ثم حمل عليهم فانكشفوا ويقال إن أسد بن يزيد كان شبيها بأبيه جدا وكان لا يفصل بينهما إلا المتأمل وكان أكثر ما يباعده منه ضربة في وجه يزيد تأخذ من قصاص شعره ومنحرفة على جبهته فكان أسد يتمنى مثلها فهوت له ضربة فأخرج وجهه من الترس فأصابته في ذلك الموضع فيقال إنه لو خطت على مثال ضربة أبيه ما عدا جاءت كأنها هي واتبع يزيد الوليد بن طريف فلحقه بعد مسافة بعيدة فأخذ رأسه وكان الوليد خرج إليهم حيث خرج وهو يقول\n(أنا الوليد بن طريف الشاري ... قسورة لا يصطلى بناري)\n(جوركم أخرجني من داري ... )\nلما وقع فيهم السيف وأخذ رأس الوليد صبحتهم أخته ليلى بنت طريف مستعدة عليها الدرع والجوشن فجعلت تحمل على الناس فعرفت فقال يزيد دعوها ثم خرج إليها فضرب بالرمح قطاة فرسها ثم قال اغربي غرب الله عليك فقد فضحت العشيرة فاستحيت وانصرفت وهي تقول\n(أيا شجر الخابور ما لك مورقا ... كأنك لم تحزن على ابن طريف)\n(فتى لا يحب الزاد إلا من التقى ... ولا المال إلا من قنا وسيوف)\n(ولا الذخر إلا كل جرداء صلدم ... وكل رقيق الشفرتين خفيف)\nلما انصرف يزيد بالظفر حجب برأي البرامكة وأظهر الرشيد السخط عليه فقال وحق أمير المؤمنين لأصيفن وأشتون على فرسي أو أدخل فارتفع الخبر بذلك فأذن له فدخل فلما رآه أمير المؤمنين ضحك وسر وأقبل يصيح مرحبا بالأعرابي حتى دخل وأجلس وأكرم وعرف بلاؤه ونقاء صدره","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":2,"spl":"مقتل الوليد بن طريف","loc":2183,"partial":1},
{"id":"b133-5","bab":"الجزء 12","sec":"من قصيدة مسلم بن الوليد في يزيد بن مزيد","page":"ج12 ص117","text":"ومدحه الشعراء بذلك فكان أحسنهم مدحا مسلم بن الوليد فقال فيه قصيدته التي أولها\n(أجررت حبل خليع في الصبا غزل ... وشمرت همم العذال في عذلي)\n(هاج البكاء على العين الطموح هوى ... مفرق بين توديع ومحتمل)\n(كيف السلو لقلب بات مختبلا ... يهذي بصاحب قلب غير مختبل)\nفيها يقول\n(يفتر عند افترار الحرب مبتسما ... إذا تغير وجه الفارس البطل)\n(موف على مهج في يوم ذي رهج ... كأنه أجل يسعى إلى أمل)\n(ينال بالرفق ما يعيا الرجال به ... كالموت مستعجلا يأتى على مهل)\n(لا يرحل الناس إلا نحو حجرته ... كالبيت يفضي إليه ملتقى السبل)\n(يقري المنية أرواح العداة كما ... يقري الضيوف شحوم الكوم والبزل)\n(يكسو السيوف رؤوس الناكثين به ... ويجعل الهام تيجان القنا الذبل)\n(إذا انتضى سيفه كانت مسالكه ... مسالك الموت في الأبدان والقلل)\n(لا تكذبن فإن المجد معدنه ... وراثة في بني شيبان لم تزل)\n(إذا الشريكي لم يفخر على أحد ... تكلم الفخر عنه غير منتحل)\n(الزائديون قوم في رماحهم ... خوف المخيف وأمن الخائف الوجل)\n(كبيرهم لا تقوم الراسيات له ... حلما وطفلهم في هدي مكتهل)\n(اسلم يزيد فما في الملك من أود ... إذا سلمت ولا في الدين من خلل)\n(لولا دفاعك بأس الروم إذ مكرت ... عن بيضة الدين لم تأمن من الثكل)\n(والمارق ابن طريف قد دلفت له ... بعارض للمنايا مسبل هطل)\n(لو أن غير شريكي أطاف به ... فاز الوليد بقدح الناضل الخصل)\n(ما كان جمعهم لما دلفت لهم ... إلا كمثل جراد ريع منجفل)\n(كم آمن لك نائي الدار ممتنع ... أخرجته من حصون الملك والخول)\n(تراه في الأمن في درع مضاعفة ... لا يأمن الدهر أن يدعى على عجل)\n(لا يعبق الطيب خديه ومفرقه ... ولا يمسح عينيه من الكحل)\n(يأبى لك الذم في يوميك إن ذكرا ... عضب حسام وعرض غير مبتذل)\n(فافخر فمالك في شيبان من مثل ... كذاك ما لبني شيبان من مثل)\nقال محمد بن يزيد يعني بقوله\n(تراه في الأمن في درع مضاعفة ... )\nخبر يزيد بن مزيد وذاك أن امرأة معن بن زائدة عاتبت معنا في يزيد وقالت إنك لتقدمه وتؤخر بنيك وتشيد بذكره وتحمل ذكرهم ولو نبهتهم لانتبهوا ولو رفعتهم لارتفعوا فقال معن إن يزيد قريب لم تبعد رحمه وله على حكم الولد إذ كنت عمه وبعد فإنهم ألوط بقلبي وأدنى من نفسي على ما توجبه واجبة الولادة للأبوة من تقديمهم ولكني لا أجد عندهم ما أجده عنده ولوكان ما يضطلع به يزيد من بعيد لصار قريبا وفي عدو لصار حبيبا وسأريك في ليلتي هذه ما ينفسج به اللوم عني ويتبين به عذري يا غلام اذهب فادع جساسا وزائدة وعبد الله وفلانا وفلانا حتى أتى على أسماء ولده فلم يلبث أن جاؤوا في الغلائل المطيبة والنعال السندية وذلك بعد هدأة من الليل فسلموا وجلسوا ثم قال يا غلام ادع لي يزيد وقد أسبل سترا بينه وبين المرأة وإذا به قد دخل عجلا وعليه السلاح كله فوضع رمحه بباب المجلس ثم أتى يحضر فلما رآه معن قال ما هذه الهيئة أبا الزبير وكان يزيد يكنى أبا الزبير وأبا خالد فقال جاءني رسول الأمير فسبق إلى نفسي أنه يريدني لوجه فقلت إن كان مضيت ولم أعرج وإن يكن الأمر على خلاف ذلك فنزع هذه الآلة أيسر الخطب فقال لهم انصرفوا في حفظ الله فقالت المرأة قد تبين عذرك فأنشد معن متمثلا\n(نفس عصام سودت عصاما ... وعودته الكر والإقداما)\n(وصيرته ملكا هماما ... )\nمن شعر اخته في رثائه وأخبرني محمد بن الحسن الكندي قال حدثنا الرياشي قال أنشدني الأصمعي لأخت الوليد بن طريف ترثيه\n(ذكرت الوليد وأيامه ... إذ الأرض من شخصه بلقع)\n(فأقبلت أطلبه في السماء ... كما يبتغي أنفه الأجدع)\n(أضاعك قومك فليطلبوا ... إفادة مثل الذي ضيعوا)\n(لوان السيوف التي حدها ... يصيبك تعلم ما تصنع)\n(نبت عنك أو جعلت هيبة ... وخوفا لصولك لا تقطع)","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":3,"spl":"من قصيدة مسلم بن الوليد في يزيد بن مزيد","loc":2184,"partial":1},
{"id":"b133-6","bab":"الجزء 12","sec":"بعض اخلاق عبد الله بن طاهر","page":"ج12 ص121","text":"فأما خبر عبد الله بن طاهر في صنعته هذا الصوت فإن عبد الله كان بمحل من علو المنزلة وعظم القدر ولطف مكان من الخلفاء يستغني به عن التقريظ له والدلالة عليه وأمره في ذلك مشهور عند الخاصة والعامة وله في الأدب مع ذلك المحل الذي لا يدفع وفي السماحة والشجاعة ما لا يقاربه فيه كبير أحد أخبرني علي بن سليمان الأخفش عن محمد بن يزيد المبرد أن المأمون اعطى عبد الله بن طاهر مال مصر لسنة خراجها وضياعها فوهبه كله وفرقه في الناس ورجع صفرا من ذلك فغاظ المأمون فعله فدخل إليه يوم مقدمه فأنشده أبياتا قالها في هذا المعنى وهي\n(نفسي فداؤك والأعناق خاضعة ... للنائبات أبيا غير مهتضم)\n(إليك أقبلت من أرض أقمت بها ... حولين بعدك في شوق وفي ألم)\n(أقفو مساعيك اللاتي خصصت بها ... حذو الشراك على مثل من الأدم)\n(فكان فضلي فيها أنني تبع ... لما سننت من الإنعام والنعم)\n(ولو وكلت إلى نفسي غنيت بها ... لكن بدأت فلم أعجز ولم ألم)\nفضحك المأمون وقال والله ما نفست عليك مكرمة نلتها ولا أحدوثة حسن عنك ذكرها ولكن هذا شيء إذا عودته نفسك افتقرت ولم تقدر على لم شعثك وإصلاح حالك وزال ما كان في نفسه أخبرني وكيع قال حدثنا عبد الله بن أبي سعد قال حدثني عبد الله بن فرقد قال أخبرني محمد بن الفضل بن محمد بن منصور قال لما افتتح عبد الله بن طاهر مصر ونحن معه سوغه المأمون خراجها فصعد المنبر فلم يزل حتى أجاز بها كلها ثلاثة آلاف دينار أو نحوها فأتاه معلى الطائي وقد أعلموه ما قد صنع عبد الله بن طاهر بالناس في الجوائز وكان عليه واحدا فوقف بين يديه تحت المنبر فقال أصلح الله الأمير أنا معلى الطائي وقد بلغ مني ما كان منك إلي من جفاء وغلظ فلا يغلظن علي قلبك ولا يستخفنك الذي بلغك أنا الذي أقول\n(يا أعظم الناس عفوا عند مقدرة ... وأظلم الناس عند الجود للمال)\n(لو أصبح النيل يجري ماؤه ذهبا ... لما أشرت إلى خزن بمثقال)\n(تغلي بما فيه رق الحمد تملكه ... وليس شيء أعاض الحمد بالغالي)\n(تفك باليسر كف العسر من زمن ... إذا استطال على قوم بإقلال)\n(لم تخل كفك من جود لمختبط ... أ ومرهف قاتل في رأس قتال)\n(وما بثثت رعيل الخيل في بلد ... إلا عصفن بأرزاق وآجال)\n(إن كنت منك على بال مننت به ... فإن شكرك من قلبي على بال)\n(ما زلت منقضا لولا مجاهرة ... من ألسن خضن في صدري بأقوال)\nقال فضحك عبد الله وسر بما كان منه وقال يا أبا السمراء أقرضني عشرة آلاف دينار فما أمسيت أملكها فأقرضه فدفعها إليه أخبرني علي بن عبد العزيز عن ابن خرداذبة قال كان موسى بن خاقان مع عبد الله بمصر وكان نديمه وجليسه وكان له مؤثرا مقدما فأصاب منه معروفا كثيرا وأجازه بجوائز سنية هناك وقبل ذلك ثم إنه وجد عليه في بعض الأمر فجفاه وظهر له منه بعض ما لم يحبه فرجع حينئذ إلى بغداد وقال\n(إن كان عبد الله خلانا ... لا مبدئا عرفا وإحسانا)\n(فحسبنا الله رضينا به ... ثم بعبد الله مولانا)\nعني بعبد الله الثاني المأمون وغنت فيه جاريته ضعف لحنا من الثقيل الأول وسمعه المأمون فاستحسنه ووصله وإياها فبلغ ذلك عبد الله بن طاهر فغاظه ذلك وقال أجل صنعنا المعروف إلى غير أهله فضاع وكانت ضعف إحدى المحسنات ومن أوائل صنعتها وصدور أغانيها وما برزت فيه وقدمت فاختيرت صنعتها في شعر جميل\n(أمنك سرى يا بثن طيف تأوبا ... هدوءا فهاج القلب شوقا وأنصبا)\n(عجبت له أن زار في النوم مضجعي ... ولو زارني مستيقظا كان أعجبا)\nالشعر لجميل والغناء لضعف ثقيل أول بالبنصر","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":4,"spl":"بعض اخلاق عبد الله بن طاهر","song":1,"loc":2185},
{"id":"b133-7","bab":"الجزء 12","sec":"قصته مع محمد بن يزيد الأموي","page":"ج12 ص124","text":"أخبرني عمي قال حدثني أبو جعفر بن الدهقانة النديم قال حدثني العباس ابن الفضل الخراساني وكان من وجوه قواد طاهر وابنه عبد الله وكان أديبا عاقلا فاضلا قال لما قال عبد الله بن طاهر قصيدته التي يفخر فيها بمآثر أبيه وأهله ويفخر بقتلهم المخلوع عارضه محمد بن يزيد الأموي الحصني وكان رجلا من ولد مسلمة بن عبد الملك فأفرط في السب وتجاوز الحد في قبح الرد وتوسط بين القوم وبين بني هاشم فأربى في التوسط والتعصب فكان مما قال فيه\n(يابن بيت النار موقدها ... ما لحاذيه سراويل)\n(من حسين من أبوك ومن ... مصعب غالتكم غول)\n(نسب في الفخر مؤتشب ... وأبوات أراذيل)\n(قاتل المخلوع مقتول ... ودم المقتول مطلول)\nوهي قصيدة طويلة فلما ولي عبد الله مصر ورد إليه تدبير أمر الشام علم الحصني أنه لا يفلت منه إن هرب ولا ينجو من يده حيث حل فثبت في موضعه وأحرز حرمه وترك أمواله ودوابه وكل ما كان يملكه في موضعه وفتح باب حصنه وجلس عليه ونحن نتوقع من عبد الله بن طاهر أن يوقع به فلما شارفنا بلده وكنا على أن نصبحه دعاني عبد الله في الليل فقال لي بت عندي الليلة وليكن فرسك معدا عندك لا يرد ففعلت فلما كان في السحر أمر غلمانه وأصحابه ألا يرحلوا حتى تطلع الشمس وركب في السحر وأنا وخمسة من خواص غلمانه معه فسار حتى صبح الحصني فرأى بابه مفتوحا ورآه جالسا مسترسلا فقصده وسلم عليه ونزل عنده وقال له ما أجلسك هاهنا وحملك على أن فتحت بابك ولم تتحصن من هذا الجيش المقبل ولم تتنح عن عبد الله بن طاهر مع ما في نفسه عليك وما بلغه عنك فقال إن ما قلت لم يذهب علي ولكني تأملت أمري وعلمت أني أخطأت خطيئة حملني عليها نزق الشباب وغرة الحداثة وأني إن هربت منه لم أفته فباعدت البنات والحرم واستسلمت بنفسي وكل ما أملك فإنا أهل بيت قد أسرع القتل فينا ولي بمن مضى أسوة فإني أثق بأن الرجل إذا قتلني وأخذ مالي شفى غيظه ولم يتجاوز ذلك إلى الحرم ولا له فيهن أرب ولا يوجب جرمي إليه أكثر مما بذلته قال فوالله ما اتقاه عبد الله إلا بدموعه تجري على لحيته ثم قال له أتعرفني قال لا والله قال أنا عبد الله بن طاهر وقد أمن الله تعالى روعتك وحقن دمك وصان حرمك وحرس نعمتك وعفا عن ذنبك وما تعجلت إليك وحدي إلا لتأمن من قبل هجوم الجيش ولئلا يخالط عفوي عنك روعة تلحقك فبكى الحصني وقام فقبل رأسه وضمه إليه عبد الله وأدناه ثم قال له إما لا فلا بد من عتاب يا أخي جعلني الله فداك قلت شعرا في قومي أفخر بهم لم أطعن فيه على حسبك ولا ادعيت\nفضلا عليك وفخرت بقتل رجل هو وإن كان من قومك فهم القوم الذين ثأرك عندهم فكان يسعك السكوت أو إن لم تسكت لا تغرق ولا تسرف فقال أيها الأمير قد عفوت فاجعله العفو الذي لا يخلطه تثريب ولا يكدر صفوه تأنيب قال قد فعلت فقم بنا ندخل إلى منزلك حتى نوجب عليك حقا بالضيافة فقام مسرورا فأدخلنا فأتى بطعام كان قد أعده فأكلنا وجلسنا نشرب في مستشرف له وأقبل الجيش فأمرني عبد الله أن أتلقاهم فأرحلهم ولا ينزل أحد منهم إلا في المنزل وهو على ثلاثة فراسخ فنزلت فرحلتهم وأقام عنده إلى العصر ثم دعا بدواة فكتب له بتسويغه خراجه ثلاث سنين وقال له إن نشطت لنا فالحق بنا وإلا فأقم بمكانك فقال فأنا أتجهز وألحق بالأمير ففعل فلحق بنا بمصر ولم يزل مع عبد الله لا يفارقه حتى رحل إلى العراق فودعه وأقام ببلده","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":5,"spl":"قصته مع محمد بن يزيد الأموي","loc":2186},
{"id":"b133-8","bab":"الجزء 12","sec":"بعض الأشعار التي غنى فيها","page":"ج12 ص126","text":"فأما الأصوات التي غنى فيها عبد الله بن طاهر فكثيرة وكان عبيد الله بن عبد الله إذا ذكر شيئا منها قال الغناء للدار الكبيرة وإذا ذكر شيئا من صنعته قال الغناء للدار الصغيرة فمنها ومن مختارها وصدورها ومقدمها لحنه في شعر أخت عمرو بن عاصية وقيل إنه لاخت مسعود بن شداد فإنه صوت نادر جيد قال أبو العبيس بن حمدون وقد ذكره ففضله جاء به عبد الله بن طاهر صحيح العمل مزدوج النغم بين لين وشدة على رسم الحذاق من القدماء وهو\n\n(هلا سقيتم بني سهم أسيركم ... نفسي فداؤك من ذي غلة صادي)\n(الطاعن الطعنة النجلاء يتبعها ... مضرج بعد ما جادت بإزباد)\nلشعر لأخت عمرو بن عاصية السلمي ترثيه وكان بنو سهم وهن بطن من هذيل أسروه في حرب كانت بينهم ولم يعرفوه فلما عرفوه قتلوه وكان قد عطش فاستسقاهم فمنعوه وقتلوه على عطشه وقيل إن هذا الشعر للفارعة أخت مسعود بن شداد ولحن عبد الله بن طاهر خفيف ثقيل أول بالوسطى ابتداؤه استهلال أخبرني أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة قال قتلت بنو سهم وهو بطن من هذيل عمرو بن عاصية السلمي وكان رجلان منهم أخذاه أخذا فاستسقاهما ماء فمنعاه ذلك ثم قتلاه فقالت أخته ترثيه وتذكر ما صنعوا به\n(شبت هذيل وبهز بينها إرة ... فلا تبوخ ولا يرتد صاليها)\nيروى شبت هذيل وسهم وهو الصحيح ولكن كذا قال عمر بن شبة\n(إن ابن عاصية المقتول بينكما ... خلى علي فجاجا كان يحميها)\nوقالت أيضا ترثيه\n(يا لهف نفسي لهفا دائما أبدا ... على ابن عاصية المقتول بالوادي)\n(هلا سقيتم بني سهم أسيركم ... نفسي فداؤك من ذي غلة صادي)\nقال فغزا عرعرة بن عاصية هذيلا يطلبهم بدم أخيه فقتل منهم نفرا وسبى امرأة فجردها ثم ساقها معه عارية إلى بلاد بني سليم فقالت عند ذلك\n(ألامت سليم في السياق وأفحشت ... وأفرط في السوق العنيف إسارها)\n(لعل فتاة منهم أن يسوقها ... فوارس منا وهي باد شوارها)\n(فإن سبقت عليا سليم بذحلها ... هذيلا فقد باءت فكيف اعتذارها)\n(ألا ليت شعري هل أرى الخيل شزبا ... تثير عجاجا مستطيرا غبارها)\n(فترقا عيون بعد طول بكائها ... ويغسل ما قد كان بالأمس عارها)\nذه رواية عمر بن شبة فأما أبو عبيدة فإنه خالفه في ذلك وذكر في مقتله فيما أخبرني به محمد بن الحسن بن دريد إجازة عن أبي حاتم عن أبي عبيدة قال خرج عمرو بن عاصية السلمي ثم البهزي في جماعة من قومه فأغاروا على هذيل بن مدركة فصادفوا حيا من هذيل يقال لهم بنو سهم بن معاوية وكانت امرأة من هذيل تحت رجل من بني بهز فقالت لابن لها معه أي بني انطلق إلى أخوالك فأنذرهم بأن ابن عاصية السلمي قد أمسى يريدهم وذلك حين عزم ابن عاصية على غزوهم وأراد المسير إليهم فانطلق الغلام من تحت ليلته حتى أتى أخواله فأنذرهم فقال ابن عاصية السلمي يريدكم فخذوا حذركم فبدر القوم واستعدوا وأصبح عمرو بن عاصية قريبا من الحي\nفنزل فربأ لأصحابه على جبل مشرف على القوم فإذا هم حذرون فقال لأصحابه أرى القوم حذرين إن لهم لشأنا ولقد أنذروا علينا فكمن في الجبل يطلب غفلتهم فأصابه وأصحابه عطش شديد فقال ابن عاصية لأصحابه هل فيكم من يرتوي لأصحابه فقال أصحابه نخاف القوم وأبى أحد منهم أن يجيبه إلى ذلك قال فخرج على فرس له ومعه قربته وقد وضعت هذيل على الماء رجلا منهم رصدا وعلموا أنهم لا بد لهم من أن يردوا الماء فمر بهم عمرو بن عاصية وقد كمن له شيخ وفتيان من هذيل فلما نظروا إليه هم الفتيان أن يثاوراه فقال الشيخ مهلا فإنه لم يركما فكفا فانتهى ابن عاصية إلى البئر فنظر يمينا وشمالا فلم ير أحدا والآخرون يرمقونه من حيث لا يراهم فوثب نحو قربته فأخذها ثم دخل البئر فطفق يملأ القربة ويشرب وأقبل الفتيان والشيخ معهما حتى أشرفوا عليه وهو في البئر فرفع رأسه فأبصر القوم فقالوا قد أخزاك الله يابن عاصية وأمكن منك قال ورمى الشيخ بسهم فأصاب أخمصه فأنفذه فصرعه وشغل الفتيان بنزع السهم من قدم الشيخ ووثب ابن عاصية من البئر شدا نحو أصحابه وأدركه الفتيان قبل وصوله فأسراه فقال لهما حين أخذاه أروياني من الماء ثم اصنعا ما بدا لكما فلم يسقياه وتعاوراه بأسيافهما حتى قتلاه فقالت أخت عمرو بن عاصية ترثي أخاها\n(يا لهف نفسي يوما ضلة جزعا ... على ابن عاصية المقتول بالوادي)","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":6,"spl":"بعض الأشعار التي غنى فيها","song":1,"loc":2187},
{"id":"b133-9","bab":"الجزء 12","sec":"بعض الأشعار التي غنى فيها","page":"ج12 ص126","text":"(إذ جاء ينفض عن أصحابه طفلا ... مشي السبنتى أمام الأيكة العادي)\n(هلا سقيتم بني سهم أسيركم ... نفسي فداؤك من مستورد صادي)\nال أبو عبيدة وآب غزي بني سليم بعد مقتل ابن عاصية قال فبلغ أخاه عرعرة بن عاصية قتل هذيل أخاه وكيف صنع به فجمع لهم جمعا من قومه فيهم فوارس من بني سليم منهم عبيدة بن حكيم الشريدي وعمرو بن الحارث الشريدي وأبو مالك البهزي وقيس بن عمرو أحد بني مطرود من بني سليم وفوارس بني رعل قال فسرى إليهم عرعرة فالتقوا بموضع يقال له الجرف فاقتتلوا قتالا شديدا فظفرت بهم بنو سليم فأوجعوا فيهم وقتلوا منهم قتلى عظيمة وأسروا أسرى وأصابوا امراة من هذيل فعروها من ثيابها واستاقوها مجردة فأفحشوا في ذلك وقال عرعرة بن عاصية في ذلك يذكر من قتل\n(ألا أبلغ هذيلا حيث حلت ... مغلغلة تخب مع الشفيق)\n(مقامكم غداة الجرف لما ... تواقفت الفوارس بالمضيق)\n(غداة رأيتم فرسان بهز ... ورعل ألبدت فوق الطريق)\n(تراميتم قليلا ثم ولت ... فوارسكم توقل كل نيق)\n(بضرب تسقط الهامات منه ... وطعن مثل إشعال الحريق)\nوقال لي إن هذا الشعر الذي فيه صنعه عبد الله بن طاهر لمسعود بن شداد يرثي أخاه وزعم أن جرما كانت قتلته وهو عطشان فقال\n(يا عين جودي لمسعود بن شداد ... بكل ذي عبرات شجوه بادي)\n(هلا سقيتم بني جرم أسيركم ... نفسي فداؤك من ذي غلة صادي)\nأنشدنيها بعض أصحابنا قال أنشدني أبو بكر محمد بن الحسن بن دريد قال أنشدني أبو حاتم عن أبي عبيدة لفارعة المرية أخت مسعود بن شداد ترثيه فذكر من الأبيات البيت الأول وبعده\n(يا من رأى بارقا قد بت أرمقه ... جودا على الحرة السوداء بالوادي)\n(أسقي به قبر من أعني وحب به ... قبرا إلي ولو لم يفده فادي)\n(شهاد أندية رفاع أبنية ... شداد ألوية فتاح أسداد)\n(نحار راغية قتال طاغية ... حلال رابية فكاك أقياد)\n(قوال محكمة نقاض مبرمة ... فراج مبهمة حباس أوراد)\n(حلال ممرعة حمال مضلعة ... قراع مفظعة طلاع أنجاد)\n(جماع كل خصال الخير قد علموا ... زين القرين وخطم الظالم العادي)\n(أبا زرارة لا تبعد فكل فتى ... يوما رهين صفيحات وأعواد)\nالغناء في هذا الشعر لعبد الله بن طاهر خفيف ثقيل أول بالبنصر قال عبيد الله بن عبد الله بن طاهر لما صنع أبي هذا الصوت لم يحب أن يشيع شيء من هذا ولا ينسب إليه لأنه كان يترفع عن الغناء وما جس بيده وترا قط ولا تعاطاه ولكنه كان يعلم من هذا الشأن بطول الدربة وحسن الثقافة ما لا\nيعرفه كبير أحد وبلغ من علم ذلك إلى أن صنع أصواتا كثيرة فألقاها على جواريه فأخذنها عنه وغنين بها وسمعها الناس منهن وممن أخذ عنهن فلما أن صنع هذا الصوت\n(هلا سقيتم بني جرم أسيركم ... نفسي فداؤك من ذي غلة صادي)\nسبه إلى مالك بن أبي السمح وكان لآل الفضل بن الربيع جارية يقال لها داحة فكانت ترغب إلى عبد الله بن طاهر لما ندبه المأمون إلى مصر في أن يأخذها معه وكانت تغنيه وأخذت هذا الصوت عن جواريه وأخذه المغنون عنها ورووه لمالك مدة ثم قدم عبد الله العراق فحضر مجلس المأمون وغني الصوت بحضرته ونسب إلى مالك فضحك عبد الله ضحكا كثيرا فسئل عن القصة فصدق فيها واعترف بصنعة الصوت فكشف المأمون عن ذلك فلم يزل كل من سئل عنه يخبر عمن أخذه عنه فتنتهي القصة إلى داحه ثم تقف ولا تعدوها فأحضرت داحة وسئلت فأخبرت بقصته فعلم أنه من صنعته حينئذ بعد أن جاز على إسحاق وطبقته أنه لمالك ويقال إن إسحاق لم يعجب من شيء عجبه من عبد الله وحذقه بمذاهب الأوائل وحكاياتهم قال ومن غنائه أيضا\n(راح صحبي وعاود القلب داء ... من حبيب طلابه لي عناء)\n(حسن الرأي والمواعيد لا يلفى ... لشيء مما يقول وفاء)\n(من تعزى عمن يحب فإني ... ليس لي ما حييت عنه عزاء)\nلغناء لابن طنبورة خفيف ثقيل أول بالسبابة في مجرى الوسطى ولحن عبد الله بن طاهر ثاني ثقيل بالبنصر\nومنها\n(فمن يفرح ببينهم ... فغيري إذ غدوا فرحا)\n\n(يا خليلي قد مللت ثوائي ... بالمصلى وقد شنئت البقيعا)\n(بلغاني ديار هند وسلمى ... وارجعا بي فقد هويت الرجوعا)\nلشعر لعمر بن أبي ربيعة والغناء للغريض خفيف ثقيل بالوسطى في مجراها عن إسحاق وذكر الهشامي أنه لابن سريج وذكر حبش أن فيه رملا بالبنصر لإبراهيم وفيه لحن لمعبد ذكره حماد بن إسحاق عن أبيه ولم","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":7,"spl":"بعض الأشعار التي غنى فيها","song":2,"loc":2188},
{"id":"b133-10","bab":"الجزء 12","sec":"بعض الأشعار التي غنى فيها","page":"ج12 ص126","text":"يجنسه أخبرني بخبر عمر بن أبي ربيعة في هذا الشعر وقوله إياه الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا سليمان بن عياش السعدي قال أخبرني السائب بن ذكوان راوية كثير قال قدم عمر بن أبي ربيعة المدينة وأخبرني الحسين بن يحيى عن حماد عن أبيه عن عثمان بن حفص قال وأخبرني علي بن صالح عن أبي هفان عن إسحاق عن عثمان بن حفص والزبيري والمسيبي وأخبرني به أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة موقوفا عليه وجمعت رواياتهم وأكثر اللفظ للزبير بن بكار وخبره أتم أن عمر بن أبي ربيعة قدم المدينة فزعموا أنه قدمها من أجل امرأة من أهلها فأقام بها شهرا فذلك قوله\n(يا خليلي قد مللت ثوائي ... بالمصلى وقد شنئت البقيعا)\nال ثم خرج إلى مكة فخرج معه الأحوص واعتمرا قال الزبير في خبره عن سائب راوية كثير إنه قال لما مرا بالروحاء\nاستتلياني فخرجت أتلوهما حتى لحقتهما بالعرج عند رواحهما فخرجنا جميعا حتى وردنا ودان فحبسهما النصيب وذبح لهما وأكرمهما وخرجنا وخرج معنا النصيب فلما جئنا كلية عدلنا جميعا إلى منزل كثير فقيل لنا هبط قديدا فذكر لنا أنه في خيمة من خيامها فقال لي ابن أبي ربيعة اذهب فادعه لي فقال النصيب هو أحمق وأشد كبرا من أن يأتيك فقال لي عمر اذهب كما أقول لك فادعه لي فجئته فهش لي وقال اذكر غائبا تره لقد جئت وأنا أذكرك فأبلغته رسالة عمر فجدد إلى نظرة وقال أما كان عندك من المعرفة ما يردعك عن إتياني بمثل هذه الرسالة قلت بلى والله ولكني سترت عليك فأبى الله إلا أن يهتك سترك فقال لي إنك والله يابن ذكوان ما أنت من شكلي فقل لابن أبي\nربيعة إن كنت قرشيا فأنا قرشي فقلت له لا تترك هذا التلصق وأنت تقرف عنهم كما تقرف الصمغة فقال والله لأنا أثبت فيهم منك في سدوس ثم قال وقل له إن كنت شاعرا فأنا أشعر منك فقلت له هذا إذا كان الحكم إليك فقال وإلى من هو ومن أولى بالحكم مني وبعد هذا يا بن ذكوان فاحمد الله على لومك فقد منعك مني اليوم فرجعت إلى عمر فقال ما وراءك فقلت ما قال لك نصيب فقال وإن فأخبرته فضحك وضحك صاحباه ظهرا لبطن ثم نهضوا معي إليه فدخلنا عليه في خيمة فوجدناه جالسا على جلد كبش فوالله ما أوسع للقرشي فلما تحدثوا مليا فأفاضوا في ذكر الشعر اقبل على عمر فقال له أنت تنعت المرأة فتنسب بها ثم تدعها وتنسب بنفسك أخبرني يا هذا عن قولك\n(قالت تصدي له ليعرفنا ... ثم اغمزيه يا أخت في خفر)\n(قالت لها قد غمزته فأبى ... ثم اسبطرت تشتد في أثري)\n(وقولها والدموع تسبقها ... لنفسدن الطواف في عمر)\nتراك لو وصفت بهذا هرة أهلك ألم تكن قد قبحت وأسأت وقلت الهجر إنما توصف الحرة بالحياء والإباء والالتواء والبخل والامتناع كما قال هذا وأشار إلى الأحوص\n(أدور ولولا أن أرى أم جعفر ... بأبياتكم ما درت حيث أدور)\n(وما كنت زوارا ولكن ذا الهوى ... إذا لم يزر لا بد أن سيزور)\n(لقد منعت معروفها أم جعفر ... وإني إلى معروفها لفقير)\nقال فدخلت الأحوص أبهة وعرفت الخيلاء فيه فلما استبان كثير ذلك فيه قال أبطل آخرك أولك أخبرني عن قولك\n(فإن تصلي أصلك وإن تبيني ... بصرمك بعد وصلك لا أبالي)\n(ولا ألفى كمن إن سيم صرما ... تعرض كي يرد إلى الوصال)\nما والله لو كنت فحلا لباليت ولو كسرت أنفك ألا قلت كما قال هذا الأسود وأشار إلى نصيب\n(بزينب ألمم قبل أن يرحل الركب ... وقل إن تملينا فما ملك القلب)\nال فانكسر الأحوص ودخلت النصيب أبهة فلما نظر أن الكبرياء قد دخلته قال له يابن السوداء فأخبرني عن قولك\n(أهيم بدعد ما حييت فإن أمت ... فوا كبدي من ذا يهيم بها بعدي)\nهمك من ينيكها بعدك فقال نصيب استوت القوق قال وهي لعبة مثل المنقلة ومن هذا الموضع ينفرد الزبير بروايته دون الباقين قال سائب فلما أمسك كثير أقبل عليه عمر فقال له قد أنصتنا لك فاسمع يا مذبوب إلي أخبرني عن تخيرك لنفسك وتخيرك لمن تحب حيث تقول\n(ألا ليتنا يا عز كنا لذي غنى ... بعيرين نرعى في الخلاء ونعزب)\n(كلانا به عر فمن يرنا يقل ... على حسنها جرباء تعدي وأجرب)\n(إذا ما وردنا منهلا صاح أهله ... علينا فما ننفك نرمى ونضرب)\n(وددت وبيت الله أنك بكرة ... هجان وأني مصعب ثم نهرب)\n(نكون بعيري ذي غنى فيضيعنا ... فلا هو يرعانا ولا نحن نطلب)","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":8,"spl":"بعض الأشعار التي غنى فيها","loc":2189},
{"id":"b133-11","bab":"الجزء 12","sec":"بعض الأشعار التي غنى فيها","page":"ج12 ص126","text":"قال تمنيت لها ولنفسك الرق والجرب والرمي والطرد والمسخ فأي مكروه لم تمن لها ولنفسك لقد أصبابها منك قول القائل معاداة عاقل خير من مودة أحمق قال فجعل يختلج جسده كله ثم أقبل عليه الأحوص فقال إلي يا ابن استها أخبرك بخبرك وتعرضك للشر وعجزك عنه وإهدافك لمن رماك أخبرني عن قولك\n(وقلن وقد يكذبن فيك تعيف ... وشؤم إذا ما لم تطع صاح ناعقه)\n(وأعييتنا لا راضيا بكرامة ... ولا تاركا شكوى الذي أنت صادقه)\n(فأدركت صفو الود منا فلمتنا ... وليس لنا ذنب فنحن مواذقه)\n(وألفيتنا سلما فصدعت بيننا ... كما صدعت بين الأديم خوالقه)\nالله لو احتفل عليك هاجيك ما زاد على ما بؤت به على نفسك قال فخفق كما يخفق الطائر ثم أقبل عليه النصيب فقال أقبل علي يا زب\nالذباب فقد منيت معرفة غائب عندي علمه فيك حيث تقول\n(وددت وما تغني الودادة أنني ... بما في ضمير الحاجبية عالم)\n(فإن كان خيرا سرني وعلمته ... وإن كان شرا لم تلمني اللوائم)\nنظر في مرآتك واطلع في جيبك واعرف صورة وجهك تعرف ما عندها لك فاضطرب اضطراب العصفور وقام القوم يضحكون وجلست عنده فلما هدأ شأوه قال لي أرضيتك فيهم فقلت له أما في نفسك فنعم فقد نحس يومك معهم وقد بقيت أنا عليك فما عذرك ولا عذر لك في قولك\n(سقى دمنتين لم نجد لهما أهلا ... بحقل لكم يا عز قد رابنا حقلا)\n(نجاءالثريا كل آخر ليلة ... يجودهما جودا ويتبعه وبلا)\nم قلت في آخرها\n(وما حسبت ضمرية حدرية ... سوى التيس ذي القرنين أن لها بعلا)\nهكذا يقول الناس ويحك ثم تظن أن ذلك قد خفي ولم يعلم به أحد فتسب الرجال وتعيبهم فقال وما أنت وهذا وما علمك بمعنى ما أردت فقلت هذا أعجب من ذاك أتذكر امرأة تنسب بها في شعرك وتستغزر لها الغيث في أول شعرك وتحمل عليها التيس في آخره قال فأطرق وذل وسكن فعدت إلى أصحابي فأعلمتهم ما كان من خبره بعدهم فقالوا ما أنت بأهون حجارته التي رمي بها اليوم منا قال فقلت لهم إنه لم يترني\nفأطلبه بذحل ولكني نصحته لئلا يخل هذا الإخلال الشديد ويركب هذه العروض التي ركب في الطعن على الأحرار والعيب لهم اخبرني أحمد بن عبد العزيز الجوهري وإسماعيل بن يونس قالا حدثنا عمر بن شبة قال حدثني إسحاق الموصلي قال حدثني ابن جامع عن السعيدي عن سهل بن بركة وكان يحمل عود ابن سريج قال","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":9,"spl":"بعض الأشعار التي غنى فيها","loc":2190},
{"id":"b133-12","bab":"الجزء 12","sec":"نافع بن علقمة يشدد في أمر الغناء والمغنين","page":"ج12 ص140","text":"كان على مكة نافع بن علقمة الكناني فشدد في الغناء والمغنين والنبيذ ونادى في المخنثين فخرج فتية من قريش إلى بطن محسر وبعثوا برسول لهم فأتاهم براوية من الشراب الطائفي فلما شربوا وطربوا قالوا لو كان معنا ابن سريج تم سرورنا فقلت هو علي لكم فقال لي بعضهم دونك تلك البغلة فاركبها وامض إليه فأتيته فأخبرته بمكان القوم وطلبهم إياه فقال لي ويحك وكيف لي\nبذاك مع شدة السلطان في الغناء وندائه فيه فقلت له أفتردهم قال لا والله فكيف لي بالعود فقلت له أنا أخبؤه لك فشأنك فركب وسترت العود وأردفني فلما كنا ببعض الطريق إذا أنا بنافع بن علقمة قد أقبل فقال لي يابن بركة هذا الأمير فقلت لا بأس عليك أرسل عنان البغلة وامض ولا تخف ففعل فلما حاذيناه عرفني ولم يعرف ابن سريج فقال لي يابن بركة من هذا أمامك فقلت ومن ينبغي أن يكون هذا ابن سريج فتبسم ابن علقمة ثم تمثل\n(فإن تنج منها يا أبان مسلما ... فقد أفلت الحجاج خيل شبيب)\nم مضى ومضينا فلما كنا قريبا من القوم نزلنا إلى شجرة نستريح فقلت له غن مرتجلا فرفع صوته فخيل إلي أن الشجرة تنطق معه فغنى\n(كيف الثواء ببطن مكة بعدما ... هم الذين تحب بالإنجاد)\n(أم كيف قلبك إذ ثويت مخمرا ... سقما خلافهم وكربك بادي)\n(هل أنت إن ظعن الأحبة غادي ... أم قبل ذلك مدلج بسواد)\nلشعر للعرجي وذكر إسحاق في مجرده أن الغناء فيه لابن عائشة ثاني ثقيل مطلق في مجرى الوسطى وحكى حماد ابنه عن أن اللحن لابن سريج قال سهل فقلت أحسنت والذي فلق الحبة وبرأ النسمة ولو أن كنانة كلها سمعتك لاستحسنتك فكيف بنافع بن علقمة المغرور من غره نافع ثم قلت زدني وإن كان القوم متعلقة قلوبهم بك فغنى وتناول عودا من الشجرة فأوقع به على الشجرة فكان صوت الشجرة أحسن من خفق بطون الضأن\nعلى العيدان إذا أخذتها قضبان الدفلى قال والصوت الذي غنى\n(لا تجمعي هجرا علي وغربة ... فالهجر في تلف الغريب سريع)\n(من ذا فديتك يستطيع لحبه ... دفعا إذا اشتملت عليه ضلوع)\nفقلت بنفسي أنت والله من لا يمل ولا يكد والله ما جهل من فهمك اركب فدتك نفسي بنا فقال أمهلني كما أمهلتك اقض بعض شأني فقلت وهل عما تريد مدفع فقام فصلى ركعتين ثم ضرب بيده على الشجرة وقال أشهد أن لا إله إلا الله وأشهد أن محمد عبده ورسوله ثم قال يا حبيبتي إذا شهدت بذاك الشيء فاشهدي بهذا ثم مضينا والقوم متشوقون فلما دنونا أحست الدواب بالبغلة فصهلت وشحجت البغلة وإذا الغريض يغنيهم لحنه\n(من خيل حي ما تزال مغيرة ... سمعت على شرف صهيل حصان)\nبكى ابن سريج حتى ظننت أن نفسه قد خرجت فقلت ما يبكيك يا أيا يحيى جعلت فداك لا يسوءك الله ولا يريك سوءا قال أبكاني هذا المخنث بحسن غنائه وشجا صوته والله ما ينبغي لأحد أن يغني وهذا الصبي حي ثم نزل فاستراح وركب فلما سار هنيهة اندفع الغريض فغناهم لحنه\n(يا خليلي قد مللت ثوائي ... بالمصلى وقد شنئت البقيعا)\nال ولصوته دوي في تلك الجبال فقال ابن سريج ويلك يا بن بركة أسمعت أحسن من هذا الغناء والشعر قط قال ونظروا إلينا فأقبلوا\nنشاوى يسحبون أعطافهم وجعلوا يقبلون وجه ابن سريج فنزل فأقام عندهم ثلاثا والغريض لا ينطق بحرف واحد وأخذوا في شرابهم وقالوا يا حبيب النفس وشقيقها أعطها بعض مناها فضرب بيده إلى جيبه فأخرج منه مضرابا ثم أخذه بيده ووضع العود في حجره فما رأيت يدا أحسن من يده ولا خشبة تخيلت إلي أنها جوهرة إلا هي ثم ضرب فلقد سبح القوم جميعا ثم غنى فكل قال لبيك لبيك فكان مما غنى فيه واللحن له هزج\n(لبيك يا سيدتي ... لبيك ألفا عددا)\n(لبيك من ظالمة ... أحببتها مجتهدا)\n(قوموا إلى ملعبنا ... نحك الجواري الخردا)\n(وضع يد فوق يد ... ترفعها يدا يدا)\nكل قال نفعل ذاك فلقد رأيتنا نستبق أينا تقع يده على يده ثم غنى\n(ما هاج شوقك بالصرائم ... ربع أحال لأم عاصم)\n(ربع تقادم عهده ... هاج المحب على التقادم)\n(فيه النواعم والشباب ... الناعمون مع النواعم)\n(من كل واضحة الجبين ... عميمة ريا المعاصم)\nثم إنه غنى\n(شجاني معاني الحي وانشقت العصا ... وصاح غراب البين أنت مريض)\n(ففاضت دموعي عند ذاك صبابة ... وفيهن خود كالمهاة غضيض)\n(ووليت محزون الفؤاد مروعا ... كئيبا ودمعي في الرداء يفيض)","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":10,"spl":"نافع بن علقمة يشدد في أمر الغناء والمغنين","song":5,"loc":2191},
{"id":"b133-13","bab":"الجزء 12","sec":"نافع بن علقمة يشدد في أمر الغناء والمغنين","page":"ج12 ص140","text":"الغناء لابن محرز خفيف ثقيل مطلق في مجرى البنصر وفيه خفيف ثقيل آخر لابن جندب قال فلقد رأيت جماعة طير وقعن بقربنا وما نحس قبل ذلك منها شيئا فقالت الجماعة يا تمام السرور وكمال المجلس لقد سعد من أخذ بحظه منك وخاب من حرمك يا حياة القلوب ونسيم النفوس جعلنا الله فداءك غننا فغنى واللحن له\n(يا هند إنك لو علمت ... بعاذلين تتابعا)\nهذا الصوت يأتي خبره مفردا لأن فيه طولا فبدرت من بينهم فقبلت بين عينيه فتهافت القوم عليه يقبلونه فلقد رأيتني وأنا أرفعهم عنه شفقة عليه","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":11,"spl":"نافع بن علقمة يشدد في أمر الغناء والمغنين","song":1,"loc":2192},
{"id":"b133-14","bab":"الجزء 12","sec":"ما في الأشعار التي تناشدها عمر وأصحابه من أغان","page":"ج12 ص144","text":"وفي هذه الأشعار التي تناشدها كثير وعمر ونصيب والأحوص أغان\nمنها\n(أبصرتها ليلة ونسوتها ... يمشين بين المقام والحجر)\n(ما إن طمعنا بها ولا طمعت ... حتى التقينا ليلا على قدر)\n(بيضا حسانا خرائدا قطفا ... يمشين هونا كمشية البقر)\nلشعر لعمر والغناء لابن سريج رمل بالوسطى عن الهشامي وحبش وذكر عمرو أن فيه لابن سريج خفيف ثقيل أول بالبنصر ولأبي سعيد مولى فائد ثقيل أول وقيل إنه لسنان الكاتب ومن هذه القصيدة أيضا وهذا أولها\n(يا من لقلب متيم كمد ... يهذي لخود مريضة النظر)\n(تمشي رويدا إذا مشت فضلا ... وهي كمثل العسلوج م البسر)\n(ما زال طرفي يحار إذ برزت ... حتى عرفت النقصان في بصري)\nناه ابن محرز ولحنه من خفيف الثقيل الأول بإطلاق الوتر في مجرى الوسطى\nومنها\n(قالت لترب لها تحدثها ... لنفسدن الطواف في عمر)\n(قالت تصدي له ليعرفنا ... ثم اغمزيه يا أخت في خفر)\n(قالت لها قد غمزته فأبى ... ثم استطيرت تشتد في أثري)\nناء يونس خفيف ثقيل أول بالبنصر عن حبش وقيل إن فيه لعبد الله بن عباس لحنا جيدا ومنها ما لم يمض ذكره في الكتاب\n(ألا ليتنا يا عز من غير بغضة ... بعيرين نرعى في الخلاء ونعزب)\n(كلانا به عر فمن يرنا يقل ... على حسنها جرباء تعدي وأجرب)\n(إذا ما وردنا منهلا صاح أهله ... علينا فما ننفك نرمى ونضرب)\nلغناء لإبراهيم رمل بالوسطى عن حبش أخبرنا محمد بن خلف وكيع قال حدثنا حماد بن إسحاق عن أبيه عن أبي عبيدة عن عوانة وعيسى بن يزيد أن كثيرا دخل على عزة ذات يوم فقالت له ما ينبغي لنا أن نأذن\nلك في الجلوس قال ولم قالت لأني رأيت الأحوص ألين جانبا في شعره منك في شعرك وأضرع خدا للنساء وإنه لأشعر منك حين يقول\n(يا أيها اللائمي فيها لأصرمها ... أكثرت لو كان يغني منك إكثار)\n(ارجع فلست مطاعا إذ وشيت بها ... لا القلب سال ولا في حبها عار)\nإني استرققت قوله\n(وما كنت زوارا ولكن ذا الهوى ... ' إذا لم يزر لا بد أن سيزور)\nوأعجبني قوله\n(كم من دني لها قد صرت أتبعه ... ولو صحا القلب عنها كان لي تبعا)\n(وزادني كلفا بالحب أن منعت ... أحب شيء إلى الإنسان ما منعا)\nقوله أيضا\n(وما العيش إلا ما تلذ وتشتهي ... وإن لام فيه ذو الشنان وفندا)\nقال كثير قد والله أجاد فما الذي استجفيت من قولي قالت أخزاك الله أما استحييت حين تقول\n(يحاذرن مني غيرة قد عرفنها ... لدي فما يضحكن إلا تبسما)\nفقال كثير\n(وددت وبيت الله أنك بكرة ... هجان وأني مصعب ثم نهرب)\n(كلانا به عر فمن يرنا يقل ... على حسنها جرباء تعدي وأجرب)\n(نكون لذي مال كثير مغفل ... فلا هو يرعانا ولا نحن نطلب)\nقالت لي ويحك لقد أردت بي الشقاء الطويل ومن المنى ما هو أعفى من هذا وأطيب\n(قد كنت في منظر ومستمع ... عن نصر بهراء غير ذي فرس)\n(لا تره عندهم فتطلبها ... ولا هم نهزة لمختلس)\n(بكف حران ثائر بدم ... طلاب وتر في الموت منغمس)\n(إما تقارش بك الرماح فلا ... أبكيك إلا للدلو والمرس)\n(تذب عنه كف بها رمق ... طيرا عكوفا كزور العرس)\n(عما قليل يصبحن مهجته ... فهن من والغ ومنتهس)\nلشعر لأبي زبيد الطائي والغناء لابن محرز في الأول والثاني خفيف ثقيل الأول بالسبابة في مجرى البنصر عن إسحاق وذكر عمرو بن بانة أن في الأربعة الأول خفيفي ثقيل كلاهما بالبنصر لمعبد وابن محرز ووافقه الهشامي في لحن معبد في الأول والثاني وذكر أنه بالوسطى وفي كتاب ابن مسجح\nعن حماد له فيه لحن يقال إنه لابن سريج في الأول والخامس والسادس والسابع رمل بالوسطى عن عمرو وذكر لنا حبش أن الرمل لمعبد وذكر إسحاق أنه لابن سريج أيضا وأوله\n(تذب عنه كف بها رمق ... )\nوفيه لمالك في السادس والسابع خفيف ثقيل آخر وفيه لابن عائشة رمل وفيه لحنين ثاني ثقيل هذه الحكايات الثلاث عن يونس وطرائقها عن الهشامي ولمخارق في الرابع والأول خفيف رمل ولمتيم في الأول والثاني خفيف رمل آخر وذكر حبش أن لإبراهيم في الأول والثاني ثاني ثقيل بالوسطى ولابن مسجح خفيف ثقيل بالوسطى","topic":"أخبار إبراهيم بن سيابة ونسبه","topicNo":133,"sp":12,"spl":"ما في الأشعار التي تناشدها عمر وأصحابه من أغان","song":5,"loc":2193,"partial":1},
{"id":"b134-1","bab":"الجزء 12","sec":"أخبار أبي زبيد ونسبه","page":"ج12 ص150","text":"هو حرملة بن المنذر وقيل المنذر بن حرملة والصحيح حرملة بن المنذر بن معد يكرب بن حنظلة بن النعمان بن حية بن سعنة بن الحارث بن ربيعة بن مالك بن سكر بن هنيء بن عمرو بن الغوث بن طيئ بن أدد بن زيد بن يشجب بن عريب بن زيد بن كهلان وكان أبو زبيد نصرانيا وعلى دينه مات وهو ممن أدرك الجاهلية والإسلام فعد في المخضرمين وألحقه ابن سلام بالطبقة الخامسة من الإسلامين وهم العجير السلولي وذووه وقد مضى أكثر أخباره مع أخبار الوليد بن عقبة بن أبي معيط أخبرني أبو خليفة الفضل بن الحباب الجمحي إجازة قال حدثني محمد\nابن سلام الجمحي قال حدثني أبو الغراف قال","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":0,"spl":"أخبار أبي زبيد ونسبه","loc":2194},
{"id":"b134-2","bab":"الجزء 12","sec":"استنشده عثمان فأنشده قصيدة فيها وصف للاسد","page":"ج12 ص151","text":"كان أبو زبيد الطائي من زوار الملوك وخاصة ملوك العجم وكان عالما بسيرهم وكان عثمان بن عفان رضي الله تعالى عنه يقربه على ذلك ويدني مجلسه وكان نصرانيا فحضر ذات يوم عثمان وعنده المهاجرون والأنصار فتذاكروا مآثر العرب وأشعارها قال فالتفت عثمان إلى أبي زبيد وقال يا أخا تبع المسيح أسمعنا بعض قولك فقد أنبئت أنك تجيد فأنشده قصيدته التي يقول فيها\n(من مبلغ قومنا النائين إذ شحطوا ... أن الفؤاد إليهم شيق ولع)\nوصف فيها الأسد فقال عثمان رضي الله تعالى عنه تالله تفتأ تذكر الأسد ما حييت والله إني لأحسبك جبانا هدانا قال كلا يا أمير المؤمنين ولكني رأيت منه منظرا وشهدت منه مشهدا لا يبرح ذكره يتجدد ويتردد في قلبي ومعذور أنا يا أمير المؤمنين غير ملوم فقال له عثمان رضي الله عنه وأنى كان ذلك قال خرجت في صيابة أشراف من أفناء قبائل العرب ذوي هيئة وشارة حسنة ترتمي بنا المهاري بأكسائها ونحن نريد الحارث بن أبي شمر الغساني ملك الشأم فاخروط بنا السير في حمارة\nالقيظ حتى إذا عصبت الأفواه وذبلت الشفاه وشالت المياه وأذكت الجوزاء المعزاء وذاب الصيهد وصر الجندب وضاف العصفور الضب وجاوره في حجره قال قائل أيها الركب غوروا بنا في ضوج هذا الوادي وإذا واد قد بدا لنا كثير الدغل دائم الغلل شجراؤه مغنة وأطياره مرنة فحططنا رحالنا بأصول دوحات كنهبلات فأصبنا من فضلات الزاد وأتبعناها الماء البارد فإنا لنصف حر يومنا ومماطلته إذ صر أقصى الخيل أذنيه وفحص الأرض بيديه فوالله ما لبث أن جال ثم حمحم فبال ثم فعل فعله الفرس الذي يليه واحدا فواحدا فتضعضعت الخيل وتكعكعت الإبل وتقهقرت البغال فمن نافر بشكاله وناهض بعقاله فعلمنا أن قد أتينا وأنه السبع ففزع كل رجل منا إلى سيفه فاستله من جربانه ثم وقفنا له رزدقا أي صفا وأقبل أبو الحارث\nمن أجمته يتظالع في مشيته من نعته كأنه مجنوب أو في هجار معصوب لصدره نحيط ولبلاعمه غطيط ولطرفه وميض ولأسارعه نقيض كأنما يخبط هشيما أو يطأ صريما وإذا هامة كالمجن وخد كالمسن وعينان سجراوان كأنهما سراجان يقدان وقصرة ربلة ولهزمة رهلة وكتد مغبط وزور مفرط وساعد مجدول وعضد مفتول وكف شثنة البراثن إلى مخالب كالمحاجن فضرب بيده فأرهج وكشر فأفرج عن أنياب كالمعاول مصقولة غير مفلولة وفم أشدق كالغار الأخرق ثم تمطى فأسرع بيديه وحفز وركيه برجليه حتى صار ظله مثليه ثم أقعى فاقشعر ثم مثل\nفاكفهر ثم تجهم فازبأر فلا وذو بيته في السماء ما اتقيناه إلا بأول أخ لنا من فزارة كان ضخم الجزارة فوقصه ثم نفضه نفضة فقضقض متنيه فجعل يلغ في دمه فذمرت أصحابي فبعد لأي ما استقدموا فهجهجنا به فكر مقشعرا بزبرته كأن شيهما حوليا فاختلج رجلا أعجر ذا حوايا فنفضه نفضة تزايلت منها مفاصله ثم نهم ففرفر ثم زفر فبربر ثم زأر فجرجر ثم لحظ فوالله لخلت البرق يتطاير من تحت جفونه من عن شماله ويمينه فأرعشت الأيدي واصطكت الأرجل وأطت الأضلاع وارتجت الأسماع وشخصت العيون وتحققت الظنون وانخزلت المتون فقال له عثمان اسكت قطع الله لسانك فقد أرعبت قلوب المسلمين أخبرني محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثني العمري قال حدثني شعبة قال قلت للطرماح بن حكيم ما شأن أبي زبيد وشأن الأسد فقال إنه لقيه\nبالنجف فلما رآه سلح من فرقه وقال مرة أخرى فسلحه فكان بعد ذلك يصفه كما رأيت أخبرني أبو خليفة عن محمد بن سلام قال حدثني أبي عمن يثق به أن رجلا من طيئ من بني حية نزل به رجل من بني الحارث بن ذهل بن شيبان يقال له المكاء فدبح له شاة وسقاه الخمر فلما سكر الطائي قال هلم أفاخرك أبنو حية أكرم أم بنو شيبان فقال له الشيباني حديث حسن ومنادمة كريمة أحب إلينا من المفاخرة فقال الطائي والله ما مد رجل قط يدا أطول من يدي فقال الشيباني والله لئن أعدتها لأخضبنها من كوعها فرفع الطائي يده فضربها الشيباني بسيفه فقطعها فقال أبو زبيد في ذلك\n(خبرتنا الركبان أن قد فخرتم ... وفرحتم بضربة المكاء)\n(ولعمري لعارها كان أدنى ... لكم من تقى وحق وفاء)\n(ظل ضيفا أخوكم لأخينا ... في صبوح ونعمة وشواء)\n(ثم لما رآه رانت به الخمر ... وأن لا يريبه باتقاء)\n(لم يهب حرمة النديم وحقت ... بالقوم للسوءة السوءاء)","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":1,"spl":"استنشده عثمان فأنشده قصيدة فيها وصف للاسد","loc":2195},
{"id":"b134-3","bab":"الجزء 12","sec":"ما قاله في كلبه","page":"ج12 ص155","text":"أخبرني محمد بن العباس اليزيدي قال حدثني عمي عبيد الله عن محمد بن حبيب عن ابن الأعرابي قال\nكان لأبي زبيد كلب يقال له أكدر وكان له سلاح يلبسه إياه فكان لا يقوم له الأسد فخرج ليلة قبل أن يلبسه سلاحه فلقيه الأسد فقتله ويقال أخذه فأفلت منه فقال عند ذلك أبو زبيد\n(أحال أكدر مختالا كعادته ... حتى إذا كان بين البئر والعطن)\n(لاقى لدى ثلل الأطواء داهية ... أسرت وأكدر تحت الليل في قرن)\n(حطت به شيمة ورهاء تطرده ... حتى تناهى إلى الحولات في السنن)\n(إلى مقابل خطو الساعدين له ... فوق السراة كذفرى الفالج القمن)\n(رئبال غاب فلا قحم ولا ضرع ... كالبغل يحتطم العلجين في شطن)\nوهي قصيدة طويلة فلامه قومه على كثرة وصفه للأسد وقالوا له قد خفنا أن تسبنا العرب بوصفك له قال لو رأيتم منه ما رأيت أو لقيكم ما لقي أكدر لما لمتموني ثم أمسك عن وصفه فلم يصفه بعد ذلك في شعره حتى مات أخبرني علي بن سليمان الأخفش قال حدثني أبو سعيد السكري قال حدثني هارون بن مسلم بن سعدان أبو القاسم قال حدثنا هشام بن الكلبي قال كان الأجلح الكندي يحدث عن عمارة بن قابوس قال لقيت أبا زبيد الطائي فقلت له يا أبا زبيد هل أتيت النعمان بن المنذر\nقال إي والله لقد أتيته وجالسته قال قلت فصفه لي فقال كان أحمر أزرق أبرش قصيرا فقلت له بالله أخبرني أيسرك أنه سمع مقالتك هذه وأن لك حمر النعم قال لا والله ولا سودها فقد رأيت ملوك حمير في ملكها ورأيت ملوك غسان في ملكها فما رأيت أحدا قط كان أشد عزا منه وكان ظهر الكوفة ينبت الشقائق فحمى ذلك المكان فنسب إليه فقيل شقائق النعمان فجلس ذات يوم هناك وجلسنا بين يديه كأن على رؤوسنا الطير وكأنه باز فقام رجل من الناس فقال له أبيت اللعن أعطني فإني محتاج فتأمله طويلا ثم أمر به فأدني حتى قعد بين يديه ثم دعا بكنانة فاستخرج منها مشاقص فجعل يجأبها في وجهه حتى سمعنا قرع العظام وخضبت لحيته وصدره بالدم ثم أمر به فنحي ومكثنا مليا ثم نهض آخر فقال له أبيت اللعن أعطني فتأمله ساعة ثم قال أعطوه ألف درهم فأخذها وانطلق ثم التفت عن يمينه ويساره وخلفه فقال ما قولكم في رجل أزرق أحمر يذبح على هذه الأكمة أترون دمه سائلا حتى يجري في هذا الوادي فقلنا له أنت أبيت اللعن أعلى برأيك عينا فدعا برجل على هذه الصفة فأمر به فذبح ثم قال ألا تسألوني عما صنعت فقلنا ومن يسألك أبيت اللعن عن أمرك وما تصنع فقال\nأما الأول فإني خرجت مع أبي نتصيد فمررت به وهو بفناء بابه وبين يديه عس من شراب أو لبن فتناولته لأشرب منه فثار إلي فهراق الإناء فملا وجهي وصدري فأعطيت الله عهدا لئن أمكنني منه لأخضبن لحيته وصدره من دم وجهه وأما الآخر فكانت له عندي يد كافأته بها ولم أكن أثبته فتأملته حتى عرفته وأما الذي ذبحته فإن عينا لي بالشام كتب إلي إن جبلة بن الأيهم قد بعث إليك برجل صفته كذا وكذا ليغتالك فطلبته أياما فلم أقدر عليه حتى كان اليوم أخبرني الحسين بن يحيى عن حماد عن أبيه قال كان لأبي زبيد نديم يشرب معه بالكوفة فغاب أبو زبيد غيبة ثم رجع فأخبر بوفاته فعدل إلى قبره قبل دخوله منزله فوقف عليه ثم قال\n(يا هاجري إذ جئت زائره ... ما كان من عاداتك الهجر)\n(يا صاحب القبر السلام على ... من حال دون لقائه القبر)\nم انصرف وكان بعد ذلك يجيء إلى قبره فيشرب عنده ويصب الشراب على قبره\nوالأبيات التي فيها الغناء المذكور يقولها في غلام له قتلته تغلب وكان مجاورا فيهم فدل بهراء على عورتهم وقاتلهم معهم فقتل أخبرني بخبره أبو خليفة قال حدثني محمد بن سلام وأخبرني محمد بن العباس اليزيدي عن عمه عبيد الله عن محمد بن حبيب عن ابن الأعرابي قال كان أخوال أبي زبيد بني تغلب وكان يقيم فيهم أكثر أيامه وكان له غلام يرعى إبله فغزت بهراء بني تغلب فمروا بغلامه فدفع إليهم إبل أبي زبيد وقال انطلقوا أدلكم على عورة القوم وأقاتل معكم ففعلوا والتقوا فهزمت بهراء وقتل الغلام فقال أبو زبيد هذه القصيدة وهي\n(هل كنت في منظر ومستمع ... عن نصر بهراء غير ذي فرس)\n(تسعى إلى فتية الأراقم وأستعجلت ... قبل الجمان والقبس)\n(في عارض من جبال بهرائها الأولى ... مرين الحروب عن درس)\n(فبهرة من لقوا حسبتهم ... أحلى وأشهى من بارد الدبس)\n(لا ترة عندهم فتطلبها ... ولا هم نهزة لمختلس)","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":2,"spl":"ما قاله في كلبه","loc":2196},
{"id":"b134-4","bab":"الجزء 12","sec":"ما قاله في كلبه","page":"ج12 ص155","text":"(جود كرام إذا هم ندبوا ... غير لئام ضجر ولا كسس)\n(صمت عظام الحلوم إن قعدوا ... عن غير عي بهم ولا خرس)\n(تقود أفراسهم نساؤهم ... يزجون أجمالهم مع الغلس)\n(صادفت لما خرجت منطلقا ... جهم المحيا كباسل شرس)\n(تخال في كفه مثقفة ... تلمع فيها كشعلة القبس)\n(بكف حران ثائر بدم ... طلاب وتر في الموت منغمس)\n(إما تقارن بك الرماح فلا ... أبكيك إلا للدلو والمرس)\n(حمدت أمري ولمت أمرك إذ ... أمسك جلز السنان بالنفس)\n(وقد تصليت حر نارهم ... كما تصلى المقرور من قرس)\n(تذب عنه كف بها رمق ... طيرا عكوفا كزور العرس)\n(عما قليل علون جثته ... فهن من والغ ومنتهس)\nلما فرغ أبو زبيد من قصيدته بعثت إليه بنو تغلب بدية غلامه وما ذهب من إبله فقال في ذلك\n(ألا أبلغ بني عمرو رسولا ... فإني في مودتكم نفيس)\nهكذا ذكر ابن سلام في خبره والقصيدة لا تدل على أنها قيلت فيمن أحسن إليه وودى غلامه ورد عليه ماله وفي رواية ابن حبيب\n(ألا أبلغ بني نصر بن عمرو ... )\nقوله أيضا فيها\n(فما أنا بالضعيف فتظلموني ... ولا جافي اللقاء ولا خسيس)\n(أفي حق مواساتي أخاكم ... بمالي ثم يظلمني السريس)\nلسريس الضعيف الذي لا ولد له وهذا ليس من ذلك الجنس ولعل ابن سلام وهم وأبو زبيد أحد المعمرين ذكر ابن الكلبي أنه عمر مائة وخمسين سنة أخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي عن أبيه قال كان طول أبي زبيد ثلاثة عشر شبرا أخبرني أحمد بن عبد العزيز وأحمد بن عبيد الله بن عمار قالا حدثنا محمد بن عبد الله العبدي أبو بكرة قال حدثني أبو مسعر الجشمي عن ابن الكلبي قال كان أبو زبيد الطائي ممن إذا دخل مكة دخلها متنكرا لجماله وأخبرني إبراهيم بن محمد بن أيوب قال حدثنا محمد بن عبد الله بن مسلم قال لما صار الوليد بن عقبة إلى الرقة واعتزل عليا عليه السلام ومعاوية صار أبو زبيد إليه فكان ينادمه وكان يحمل في كل أحد إلى البيعة مع النصارى فبينا هو يوم أحد يشرب والنصارى حوله رفع بصره إلى السماء فنظر ثم رمى بالكأس من يده وقال\n(إذا جعل المرء الذي كان حازما ... يحل به حل الحوار ويحمل)\n(فليس له في العيش خير يريده ... وتكفينه ميتا أعف وأجمل)","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":3,"spl":"ما قاله في كلبه — دفن مع الوليد بن عقبة بوصية منه","loc":2197,"partial":1},
{"id":"b134-5","bab":"الجزء 12","sec":"دفن مع الوليد بن عقبة بوصية منه","page":"ج12 ص162","text":"ومات فدفن هناك على البليخ فلما حضرت الوليد بن عقبة الوفاة أوصى أن يدفن إلى جنب أبي زبيد وقد قيل إن ابا زبيد مات بعد الوليد فأوصى أن يدفن إلى جنب الوليد قال ابن الكلبي في خبره الذي ذكره إسحاق عنه هرب أبو زبيد من الإسلام فجاور بهراء فاستأجر منهم أجيرا لإبله فكان يقبله حلب الجمان والقيس وهما ناقتان كانتا له فلما كان يوم حابس وهو اليوم الذي التقت فيه بهراء وتغلب خرج أجير أبي زبيد مع بهراء فقتل وانهزمت بهراء فمر أبو زبيد به وهو يجود بنفسه فقال فيه هذه القصيدة أخبرني محمد بن يحيى ويحيى بن علي الأبوابي المدائني قالا حدثنا عقبة المطرفي قال كنا في الحمام ومعي ابن السعدي وأنا أقرأ القرآن فدخل سعد الرواسي فغنى\n(قد كنت في منظر ومستمع ... عن نصر بهراء غير ذي فرس)\nقال ابن السعدي اسكت اسكت فقد جاء حديث يأكل الأحاديث أخبرني عمي والحسن بن علي قالا حدثني العمري قال حدثني أحمد ابن حاتم قال حدثني محمد بن عمرو الجماز قال حدثني أبو عبيدة عن يونس\nوأبي الخطاب النحوي أن الوليد بن عقبة بن أبي معيط أوصى لما احتضر لأبي زبيد بما يصلحه في فصحه وأعياده من الخمر ولحوم الخنازير وما أشبه ذلك فقال أهله وبنوه لأبي زبيد قد علمت أنه لا يحل لنا هذا في ديننا وإنما فعله إكراما لك وتعظيما لحقك فقدره لنفسك ما شئت أن تعيش وقوم ما أوصى به لك حتى نعطيك قيمته ولا تفضحنا وتفضح آباءنا بهذا واحفظه واحفظنا فيه ففعل أبو زبيد ذلك وقبله منهم\n(هل تعرف الدار من عامين أو عام ... دار لهند بجزع الحرج فالدام)\n(تحنو لأطلائها عين ملمعة ... سفع الخدود بعيدات من الرامي)\nلحرج والدام موضعان ويروى مذ عامين وهذا الأجود وكلاهما روي وعين بقر وأطلاؤها أولادها واحدها طلا ويروى بعيدات من الذام هو الذي يذم","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":3,"spl":"ما قاله في كلبه — دفن مع الوليد بن عقبة بوصية منه","song":1,"loc":2198},
{"id":"b134-6","bab":"الجزء 12","sec":"الحطيئة يمدح أبا موسى الأشعري","page":"ج12 ص163","text":"الشعر للحطيئة يمدح به أبا موسى الأشعري لما ولاه عمر بن الخطاب\nرضي الله عنه العراق والغناء لمالك خفيف رمل مطلق في مجرى الوسطى عن إسحاق وذكر أن فيه لابن جامع أيضا صنعة قال محمد بن حبيب أتى الحطيئة أبا موسى يسأله أن يكتبه معه فأخبره أن العدة قد تمت فمدحه الحطيئة بهذه القصيدة التي ذكرتها وأولها\n(هل تعرف الدار من عامين أو عام ... دار لهند بجزع الحرج فالدام)\nفيها يقول\n(وجحفل كسواد الليل منتجع ... أرض العدو ببوس بعد إنعام)\n(جمعت من عامر فيه ومن أسد ... ومن تميم ومن حاء ومن حام)\nاء من مذحج وحام من خثعم\n(وما رضيت لهم حتى رفدتهم ... من وائل رهط بسطام بأصرام)\n(فيه الرماح وفيه كل سابغة ... جدلاء محكمة من نسج سلام)\nعني سليمان النبي\n(وكل أجرد كالسرحان أضمره ... مسح الأكف وسقي بعد إطعام)\n(مستحقبات رواياها جحافلها ... يسمو بها أشعري طرفه سام)\nلروايا الإبل التي تحمل أثقالهم وأزوادهم وتجنب الخيل إليها فتضع جحافلها على أعجاز الإبل\n(لا يزجر الطير إن مرت به سنحا ... ولا يفيض على قدح بأزلام)\nقال المدائني لما مدح الحطيئة أبا موسى رضي الله عنه بهذه القصيدة وصله أبو موسى وقد كان كتب من أراد وكملت العدة فبلغ ذلك عمر بن الخطاب رضي الله عنه فكتب يلومه فكتب إليه إني اشتريت منه عرضي فكتب إليه أحسنت قال وزاد فيه حماد الراوية أنه يعني نفسه أنشدها بلال بن أبي بردة ولم يكن عرفها فوصله أخبرني القاضي أبو خليفة إجازة قال حدثنا محمد بن سلام قال أخبرني أبو عبيدة عن يونس قال قدم حماد الراوية البصرة على بلال بن أبي بردة وهو عليها فقال له ما أطرفتني شيئا يا حماد فعاد إليه فأنشده قول الحطيئة في أبي موسى فقال له ويحك يمدح الحطيئة أبا موسى وأنا أروي شعره كله ولا أعلم بهذه أذعها تذهب في الناس وكانت ولاية أبي موسى الكوفة بعد أن أخرج أهلها سعيد بن العاص\nعنها وتحالفوا ألا يولوا عليها إلا من يريدون أخبرني بالسبب في ذلك أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة قال حدثنا المدائني عن أبي مخنف عن عبد الملك بن نوفل بن مساحق قال كان قوم من وجوه أهل الكوفة من القراء يختلفون إلى سعيد بن العاص ويسألونه فتذاكروا يوما السهل والجبل فقال حسان بن محدوج سهلنا خير من جبلنا أكثر برا فيه أنهار مطردة ونخل باسقات وقلت فاكهة ينبتها الجبل إلا والسهل ينبت مثلها فقال له عبد الرحمن بن حبيش صدقتم وددت أنه للأمير وأن لكم أفضل منه فقال الأشتر تمن للأمير أفضل ولا تتقرب إليه بأموالنا فقال ما ضرك ذلك والله لو يشاء أن يكون له لكان قال كذبت والله لو أراد ذلك ما قدر عليه فقال سعيد والله ما السواد إلا بستان لقريش ما شئنا أخذنا منه وما شئنا تركنا فقال له الأشتر أنت تقول هذا أصلحك الله وهذا من مركز رماحنا وفيئنا ثم ضربوا عبد الرحمن ابن حبيش حتى سقط قال المدائني فحدثني علي بن مجاهد عن محمد بن إسحاق عن الشعبي","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":4,"spl":"الحطيئة يمدح أبا موسى الأشعري","loc":2199},
{"id":"b134-7","bab":"الجزء 12","sec":"الحطيئة يمدح أبا موسى الأشعري","page":"ج12 ص163","text":"ومجالد بن حمزة بن بيض عن الشعبي قال بينا القراء عند سعيد بن العاص وهم يأكلون تمرا وزبدا إذ قال سعيد السواد بستان قريش فما شئنا أخذنا منه وما شئنا تركنا فقال له عبد الرحمن بن حبيش وكان على شرطة سعيد صدق الأمير فوثب عليه القراء فضربوه وقالوا له يا عدو الله يقول الباطل وتصدقه اخرجوا من داري فخرجوا فلما أصبحوا أتوا المسجد فداروا على الحلق فقالوا إن أميركم زعم أن السواد بستان له ولقومه وهو فيئنا ومركز رماحنا فوالله ما على هذا بايعنا ولا عليه أسلمنا فكتب سعيد إلى عثمان رضي الله عنه إن قبلي قوما يدعون القراء وهم السفهاء وثبوا على صاحب شرطتي فضربوه واستخفوا بي منهم عمرو بن زرارة وكميل بن زياد والأشتر وحرقوص بن هبيرة وشريح بن أوفى ويزيد بن المكفف وزيد وصعصعة ابنا صوحان وجندب بن عبد الله فكتب إليهم عثمان رضي الله عنه يأمرهم أن يخرجوا إلى الشام ويغزوا مغازيهم وكتب إلىسعيد قد كفيتك الذي أردت فأقرئهم كتابي فإني أراهم لا يخالفون إن شاء الله واتق الله جل وعز وأحسن السيرة فأقرأهم الكتاب فخرجوا إلى دمشق فأكرمهم معاوية وقال إنكم قدمتم بلدا لا يعرف أهله إلا الطاعة فلا تجادلوهم فتدخلوا الشك قلوبهم فقال له الأشتر إن الله جل وعز قد أخذ على العلماء في علمهم ميثاقا أن يبينوه للناس ولا يكتموه فإن سألنا سائل عن شيء نعلمه لم نكتمه فقال قد خفت أن تكونوا مرصدين للفتنة فاتقوا الله ( ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينات\nفقال عمرو بن زرارة نحن الذين هدى الله فأمر معاوية بحبسهم فقال له زيد بن صوحان إن الذين أشخصونا إليك لم يعجزوا عن حبسنا أو أرادوا فأحسنوا جوارنا وإن كنا ظالمين فنستغفر الله وإن كنا مظلومين فنسأل الله العافية فقال له معاوية إني لا أرى حبسك أمرا صالحا فإن أحببت أن آذن لك فترجع إلى مصرك\nوأكتب إلى أمير المؤمنين بإذنك فعلت قال حسبي أن تأذن لي وتكتب إلى سعيد فكتب إليه فأذن له فلما أراد زيد الشخوص كلمه في الأشتر وعمرو بن زرارة فأخرجهما وأقام القوم بدمشق لا يرون أمرا يكرهونه ثم أشخصهم معاوية إلى حمص فكانوا بها حتى أجمع أهل الكوفة على إخراج سعيد فكتبوا إليهم فقدموا قال أبو زيد قال المدائني حدثني الوقاصي عن الزهري إن أهل الكوفة لما قدموا على عثمان يشكون سعيدا قال لهم أكتب إليه فأجمع بينكم وبينه ففعل فلم يحققوا عليه شيئا إلا قوله السواد بستان قريش وأثنى الآخرون عليه فقال عثمان أرى أصحابكم يسألون إقراره ولم يثبتوا عليه إلا كلمة واحدة لم ينتهك بها لأحد حرمة ولا أرى عزله إلا أن تثبتوا عليه ما لا يحل لأحد تركه معه فانصرفوا إلى مصركم فرجع سعيد والفريقان معه وتقدمهم علي بن الهيثم السدوسي حتى دخل رحبة المسجد فقال يا أهل الكوفة إنا أتينا خليفتنا فشكونا إليه عاملنا ونحن نرى أنه سيصرفه عنا فرده إلينا وهو يزعم أن السواد بستان له وأنا امرؤ منكم أرضى إذا رضيتم فقالوا لا نرضى","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":5,"spl":"الحطيئة يمدح أبا موسى الأشعري","loc":2200},
{"id":"b134-8","bab":"الجزء 12","sec":"الأشتر يخطب محرضا على عثمان","page":"ج12 ص168","text":"وجاء الأشتر فصعد المنبر فخطب خطبة ذكر فيها النبي وأبا بكر وعمر رضي الله عنهما وذكر عثمان رضي الله عنه فحرض عليه ثم قال من كان يرى أن لله جل وعز حقا فليصبح بالجرعة ثم قال لكميل بن زياد انطلق\nفأخرج ثابت بن قيس بن الخطيم فأخرجه واستعمل أهل الكوفة أبا موسى الأشعري أخبرني أحمد قال حدثنا عمر قال حدثنا عفان قال حدثنا أبو محصن قال حدثنا حصين بن عبد الرحمن قال حدثني جهيم قال أنا شاهد للأمر قالوا لعثمان إنك استعملت أقاربك قال فليقم أهل كل مصر فليسلموا صاحبهم فقام أهل الكوفة فقالوا اعزل عنا سعيدا واستعمل علينا أبا موسى الأشعري ففعل قال أبو زيد وكان سعيد قد ابغضه أهل الكوفة لأمور منها أن عطاء النساء بالكوفة كان مائتين مائتين فحطه سعيد إلى مائة مائة فقالت امرأة من أهل الكوفة تذم سعيدا وتثني على سعد بن أبي وقاص\n(فليت أبا إسحاق كان أميرنا ... وليت سعيدا كان أول هالك)\n(يحطط أشراف النساء ويتقي ... بأبنائهن مرهفات النيازك)\nدثني العباس بن علي بن العباس ومحمد بن جرير الطبري قالا حدثنا يحيى بن معين قال حدثنا أبو داود وأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة قال حدثنا أبو داود قال حدثنا شعبة بن عمرو بن مرة قال سمعت أبا وائل يحدث عن الحارث بن حبيش قال بعثني سعيد بن العاص بهدايا إلى المدينة وبعثني إلى علي عليه السلام وكتب إليه إني لم أبعث إلى أحد\nبأكثر مما بعثت به إليك إلا شيئا في خزائن أمير المؤمنين قال فأتيت عليا فأخبرته فقال لشد ما تحظر بنو أمية تراث محمد أما والله لئن وليتها لأنفضنها نفض القصاب لتراب الوذمة قال أبو جعفر هذا غلط إنما هو لوذام التربة قال أبو زيد وحدثني عبد الله بن محمد بن حكيم الطائي عن السعدي عن أبيه قال بعث سعيد بن العاص مع ابن أبي عائشة مولاه بصلة إلى علي بن أبي طالب عليه السلام فقال والله لا يزال غلام من غلمان بني أمية يبعث إلينا مما أفاء الله على رسوله بمثل قوت الأرملة والله لئن بقيت لأنفضنها نفض القصاب لوذام التربة هكذا في هذه الرواية\n(رب وعد منك لا أنساه لي ... أوجب الشكر وإن لم تفعلي)\n(أقطع الدهر بظن حسن ... وأجلي غمرة ما تنجلي)\n(كلما أملت يوما صالحا ... عرض المكروه لي في أملي)\n(وأرى الأيام لا تدني الذي ... أرتجي منك وتدني أجلي)\nروضه من الرمل الشعر لمحمد بن أمية والغناء لأبي حشيشة رمل طنبوري وفيه لحن لحسين بن محرز ثاني ثقيل بالوسطى عن أبي عبد الله الهشامي","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":6,"spl":"الأشتر يخطب محرضا على عثمان","song":1,"loc":2201}]);
window.__BOOK__['p06'].push([{"id":"b134-9","bab":"الجزء 12","sec":"أخبار محمد بن أمية وأخبار أخيه علي بن أمية وما يغنى فيه من شعرهما","page":"ج12 ص171","text":"سألت أحمد بن جعفر جحظة عن نسبه قلت له إن الناس يقولون ابن أمية وابن أبي أمية فقال هو محمد بن أمية بن أبي أمية قال وكان محمد كاتبا شاعرا ظريفا وكان ينادم إبراهيم بن المهدي وربما عاشر علي بن هشام إلا أن انقطاعه كان إلى إبراهيم وربما كتب بين يديه وكان حسن الخط والبيان وكان أمية بن أبي أمية يكتب للمهدي على بيت المال وكان إليه ختم الكتب بحضرته وكان يأنس به لأدبه وفضله ومكانه من ولائه فزامله أربع دفعات حجها في ابتدائه ورجوعه قال جحظة وحدثني بذلك أبو حشيشة وحدثني جحظة أيضا قال حدثني أبو حشيشة عن محمد بن علي بن أمية قال حدثني عمي محمد بن أمية قال كنت جالسا بين يدي إبراهيم بن المهدي فدخل إليه أبو العتاهية و قد تنسك ولبس الصوف وترك قول الشعر إلا في الزهد فرفعه إبراهيم وسر به\nوأقبل عليه بوجهه وحديثه فقال له أبو العتاهية أيها الأمير بلغني خبر فتى في ناحيتك ومن مواليك يعرف بابن أمية يقول الشعر وأنشدت له شعرا أعجبني فما فعل قال فضحك إبراهيم ثم قال لعله أقرب الحاضرين مجلسا منك فالتفت إلي فقال لي أنت هو فديتك فتشورت وخجلت وقلت له أنا محمد بن أمية جعلت فداءك وأما الشعر فإنما أنا شاب أعبث بالبيت والبيتين والثلاثة كما يعبث الشاب فقال لي فديتك ذلك والله زمان الشعر وإبانه وما قيل فيه فهو غرره وعيونه وما قصر من الشعر وقيل في المعنى الذي تومىء إليه أبلغ وأملح وما زال ينشطني ويؤنسني حتى رأى أني قد أنست به ثم قال لإبراهيم بن المهدي إن رأى الأمير أكرمه الله أن يأمره بإنشادي ما حضر من الشعر فقال لي إبراهيم بحياتي يا محمد أنشده فأنشدته\n(رب وعد منك لا أنساه لي ... أوجب الشكر وإن لم تفعلي)\nذكر الأبيات الأربعة قال فبكى أبو العتاهية حتى جرت دموعه على لحيته وجعل يردد البيت الأخير منها وينتحب وقام فخرج وهو يردد ويبكى حتى خرج إلى الباب","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":7,"spl":"أخبار محمد بن أمية وأخبار أخيه علي بن أمية وما يغنى فيه من شعرهما — شعره في الجارية خداع","loc":2202},
{"id":"b134-10","bab":"الجزء 12","sec":"شعره في الجارية خداع","page":"ج12 ص172","text":"أخبرني عمي قال حدثني يعقوب بن إسرائيل قرقارة قال حدثني محمد بن علي بن أمية قال كان عمي محمد بن أمية يهوى جارية مغنية يقال لها خداع كانت لبعض جواري خال المعتصم فكان يدعوها ويعاشره إخوانه إذا دعوه بها اتباعا لمسرته وأراد المعتصم الخروج والتأهب للغزو وأمر الناس جميعا بالخروج\nوالتأهب فدعاه بعض إخوانه قبل خروجهم بيوم فلما أضحى النهار جاء من المطر أمر عظيم لم يقدر معه أحد أن يطلع رأسه من داره فكاد محمد أن يموت غما فكتب إلى صديقه الذي دعاه وقد كان ركب إليه ثم رجع لشدة المطر ولم يقدر على لقائه\n(تمادى القطر وانقطع السبيل ... من الإلفين إذ جرت السيول)\n(على أني ركبت إليك شوقا ... ووجه الأرض أودية تجول)\n(وكان الشوق يقدمني دليلا ... وللمشتاق معتزما دليل)\n(فلم أجد السبيل إلىحبيب ... أودعه وقد أقد الرحيل)\n(وأرسلت الرسول فغاب عني ... فيالله ما فعل الرسول)\nقال في ذلك أيضا\n(مجلس يشفى به الوطر ... عاق عنه الغيم والمطر)\n(رب خذ لي منهما فهما ... رحمة عمت ولي ضرر)\n(ما علىمولاي معتبة ... عذره باد ومستتر)\n(شغلت عيني بعبرتها ... واستمالت قلبي الفكر)\nال ثم بيعت خداع هذه فاشتراها بعض ولد المهدي وكان ينزل شارع الميدان فحجبت عنه وانقطع ما بينهما إلا مكاتبة ومراسلة قال محمد بن علي فأنشدني يوما عمي محمد لنفسه فيها\n(خطرات الهوى بذكر خداع ... هجن شوقي لا دراسات الطلول)\n(حجبت أن ترى فلست أراها ... وأرى أهلها بكل سبيل)\n(وإذا جاءها الرسول رآها ... ليت عيني مكان عين الرسول)\n(قد أتاك الرسول ينعت ما بي ... فاسمعي منه ما يقول وقولي)\nقال فيها أيضا\n(بناحية الميدان درب لو أنني ... أسميه لم أرشد وإن كان مفسدي)\n(أخاف على سكانه قول حاسد ... يشير إليهم بالجفون وباليد)\n(وصائف أبكار وعون نواطق ... بألسنة تشفي جوى الهائم الصدي)\n(يقاربن أهل الود بالقول في الهوى ... وما النجم من معروفهن بأبعد)\n(يزدن أخا الدنيا مجونا وفتنة ... ويشغفن قلب الناسك المتعبد)\n(وليلة وافى النوم طيف سرى به ... إلي الهوى منهن بعد تجرد)\n(فقاسمته الأشجان نصفين بيننا ... وأوردته من لوعة الحب موردي)\n(ونلت الذي أملت بعد تمنع ... وعاهدته عهد امرئ متوكد)\n(فلما افترقنا خاس بالعهد بيننا ... وأعرض إعراض العروس من الغد)\n(فواندما ألا أكون ارتهنته ... لأخبره في حفظ عهد وموعد)","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":7,"spl":"أخبار محمد بن أمية وأخبار أخيه علي بن أمية وما يغنى فيه من شعرهما — شعره في الجارية خداع","loc":2203},
{"id":"b134-11","bab":"الجزء 12","sec":"اعجاب أبي العتاهية بشعره","page":"ج12 ص174","text":"أخبرني الحسن بن علي وعمي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثني حذيفة بن محمد قال قال لي محمد بن أبي العتاهية سمع أبي يوما مخارقا يغني\n(أحبك حبا لو يفض يسيره ... على الخلق مات الخلق من شدة الحب)\n(وأعلم أني بعد ذاك مقصر ... لأنك في أعلى المراتب من قلبي)\nطرب ثم قال له من يقول هذا يا أبا المهنأ قال فتى من الكتاب يخدم الأمير إبراهيم بن المهدي فقال تعني محمد بن أمية قال نعم قال أحسن والله وما يزال يأتي بالشيء المليح يبدو له أخبرني عمي قال حدثنا أحمد بن أبي طاهر قال حدثني أحمد بن أمية بن أبي أمية قال لقي أخي محمد بن أمية مسلم بن الوليد وهو يمشي وطويلته مع بعض رواته فسلم عليه ثم قال له قد حضرني شيء فقال هاته فقال على أنه مزاح لا يغضب منه قال هاته ولو أنه شتم فقال\n(من رأى فيما خلا رجلا ... تيهه يربى على جدته)\n(يتباهى راجلا وله ... شاكري في قلنسيته)\nسكت عنه مسلم ولم يجبه وضحك منه محمد وافترقا قال وكان لمحمد بن أمية برذون يركبه فلقيه مسلم وهو راجل فقال ما فعل برذونك قال نفق قال الحمد لله فنجازيك إذا على ما كان منك إلينا ثم قال مسلم\n(قل لابن مي لا تكن جازعا ... لن يرجع البرذون بالليت)\n(طامن أحشاءك فقدانه ... وكنت فيه عالي الصوت)\n(وكنت لا تنزل عن ظهره ... ولو من الحش إلى البيت)\n(ما مات من حتف ولكنه ... مات من الشوق إلى الموت)\nأخبرني أحمد بن عبيد الله بن عمار قال حدثنا يعقوب بن إسرائيل قال حدثني محمد بن علي بن أمية قال حدثني حسين بن الضحاك قال دخلت أنا ومحمد بن أمية منزل نخاس بالرقة أيام الرشيد وعنده جارية تغني فوقعت عينها على محمد ووقعت عينه عليها فقال لها يا جارية أتغنين هذا الصوت\n(خبريني من الرسول إليك ... واجعليه من لا ينم عليك)\n(وأشيري إلي من هو باللحظ ... ليخفى على الذين لديك)\n(وأقلي المزاح في المجلس اليوم ... فإن المزاح بين يديك)\nقالت له ما أعرفه وأشارت إلى خادم كان على رأسها واقفا فمكثا زمانا والخادم الرسول بينهما قال والشعر لمحمد بن أمية حدثني جحظة قال حدثني ميمون بن هارون قال حدثني بعض من كان يختلط بالبرامكة قال كنت عند إبراهيم بن المهدي وقد اصطبحنا وعنده عمرو بن بانة\nوعبيد الله بن أبي غسان ومحمد بن عمرو الرومي وعمرو الغزال ونحن في أطيب ما كنا عليه إذ غنى عمرو الغزال وكان إبراهيم بن المهدي يستثقله إلا أنه كان يتخفف بين يديه ويقصده ويبلغه عنه تقديم له وعصبية فكان يحتمل ذاك منه فاندفع عمرو الغزال فتغنى في شعر محمد بن أمية\n(ما تم لي يوم سرور بمن ... أهواه مذ كنت إلى الليل)\n(أغبط ما كنت بما نلته ... منه أتتني الرسل بالويل)\n(لا والذي يعلم كل الذي ... أقول ذي العزة والطول)\n(ما رمت مذ كنت لكم سخطة ... بالغيب في فعل ولا قول)\nال فتطير إبراهيم ووضع القدح من يده وقال أعوذ بالله من شر ما قلت فوالله ما سكت وأخذنا نتلافى إبراهيم إذ أتى حاجبه يعدو فقال ما لك فقال خرج الساعة مسرور من دار أمير المؤمنين حتى دخل إلى جعفر بن يحيى فلم يلبث أن خرج ورأسه بين يديه وقبض على أبيه وإخوته فقال إبراهيم ( إنا لله وإنا إليه راجعون\nارفع يا غلام ارفع فرفع ما كان بين أيدينا وتفرقنا فما رأيت عمرا بعدها في داره","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":8,"spl":"اعجاب أبي العتاهية بشعره","loc":2204},
{"id":"b134-12","bab":"الجزء 12","sec":"كان يستطيب الشراب عند هبوب الجنوب","page":"ج12 ص177","text":"أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن يحيى الكاتب قال حدثني محمد بن يحيى بن بسخنر قال كنت عند إبراهيم بن المهدي بالرقة وقد عزمنا على الشراب ومعنا محمد بن أمية في يوم من حزيران فلما هممنا بذلك هبت الجنوب وتلطخت السماء بغيم وتكدر ذلك اليوم فترك إبراهيم بن المهدي الشرب ولحقه صداع وكان يناله ذلك مع هبوب الجنوب فافترقنا فقال لي محمد بن أمية ما أحب إلي ما كرهتموه من الجنوب فإن أنشدتك بيتين مليحين في\nمعناهما تساعدني على الشرب اليوم قلت نعم فأنشدني\n(إن الجنوب إذا هبت وجدت لها ... طيبا يذكرني الفردوس إن نفحا)\n(لما أتت بنسيم منك أعرفه ... شوقا تنفست واستقبلتها فرحا)\nانصرفت معه إلى منزله وغنيت في هذين البيتين وشربنا عليهما بقية يومنا وجدت في بعض الكتب بغير إسناد أهدت جارية يقال لها خداع إلى محمد بن أمية وكان يهواها تفاحة مفلجة منقوشة مطيبة حسنة فكتب إليها محمد\n(خداع أهديت لنا خدعة ... تفاحة طيبة النشر)\n(ما زلت أرجوك وأخشى الهوى ... معتصما بالله والصبر)\n(حتى أتتني منك في ساعة ... زحزحت الأحزان عن صدري)\n(حشوتها مسكا ونقشتها ... ونقش كفيك من النحر)\n(سقيا لها تفاحة أهديت ... لو لم تكن من خدع الدهر)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني عبد الله بن جعفر اليقطيني قال حدثني أبي جعفر بن علي بن يقطين قال كنت أسير أنا ومحمد بن أمية في شارع الميدان فاستقبلتنا جارية كان محمد يهواها ثم بيعت وهي راكبة فكلمها فأجابته بجواب أخفته فلم يفهمه فأقبل علي وقد تغير لونه فقال\n(يا جعفر بن علي وابن يقطين ... أليس دون الذي لاقيت يكفيني)\n(هذا الذي لم تزل نفسي تخوفني ... منها فأين الذي كانت تمنيني)\n(خاطرت إذ أقبلت نحوي وقلت لها ... تفديك نفسي فداء غير ممنون)\n(فخاطبتني بما أخفته فانصرفت ... نفسي بظنين مخشي ومأمون)\nدثني محمد بن يحيى الصولي قال حدثني أحمد بن يزيد المهلبي قال حدثني أبي قال كنت بين يدي المنتصر جالسا فجاءته رقعة لا أعلم ممن هي فقرأها وتبسم ثم إنه اقبل علي وأنشد\n(لطافة كاتب وخشوع صب ... وفطنة شاعر عند الجواب)\nم أقبل علي فقال من يقول هذا يا يزيد فقلت محمد بن أمية يا أمير المؤمنين فضحك وقال كأنه والله يصف ما في هذه الرقعة أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني حذيفة بن محمد قال كنت أنا وابن قنبر عند محمد بن أمية بعقب بيع جارية كان يحبها وقد لحقه عليها وله كالجنون فجعل ابن قنبر وأخوه علي بن أمية يعاتبانه على ما يظهر منه فأقبل بوجهه عليهما ثم قال\n(لو كنت جربت الهوى يابن قنبر ... كوصفك إياه لألهاك عن عذلي)\n(أنا وأخي الأدنى وأنت لها الفدا ... وإن لم تكونا في مودتها مثلي)\n(أأن حجبت عني أجود لغيرها ... بودي وهل يغري المحب سوى البخل)\n(أسر بأن قالوا تضن بودها ... عليك ومن ذا سر بالبخل من قبلي)\nقال فضحك ابن قنبر وقال إذا كان الأمر هكذا فكن أنت الفداء\nلها وإن ساعدك أخوك فاتفقا على ذلك وأما أنا فلست أنشط لأن أساعدك على هذا وافترقنا أخبرني علي بن سليمان الأخفش قال أنشدني محمد بن الحسن بن الحزور لمحمد بن أمية في جارية كان يهواها وقطع الصوم بينهما فقال يخاطب محمد بن عثمان بن خريم المري\n(قفا فابكيا إن كنتما تجدان ... كوجدي وإن لم تبكيا فدعاني)\n(ففي الدمع مما تضمر النفس راحة ... إذا لم أطق إظهاره بلساني)\n(أغض بأسراري إذا ما لقيتها ... فأبهت مشدوها أعض بناني)\n(فيا بن خريم يا أخي دون إخوتي ... ومن هو لي مثلي بكل مكان)\n(تأمل أحظي من خداع وحبها ... سوى خدع تذكي الهوى وأماني)\n(وأصبح شهر الصوم قد حال بيننا ... فيا ليت شوالا أتى بزمان)\nنشدني جعفر بن قدامة قال أنشدني عبد الله بن المعتز قال أنشدني أبو عبد الله الهشامي لمحمد بن أمية وفيه غناء لمتيم قال واستحسنه عبد الله\n(عجبا عجبت لمذنب متغضب ... لولا قبيح فعاله لم أعجب)\n(أخداع طال على الفراش تقلبي ... وإليك طول تشوقي وتطربي)\n(لهفي عليك وما يرد تلهفي ... قصرت يداي وعز وجه المطلب)\nلغناء لمتيم فيه لحنان رمل عن ابن المعتز وخفيف رمل عن الهشامي وهذا من شعر محمد فيها بعد أن بيعت قال وغنتنا هزار هذا الصوت يومئذ","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":9,"spl":"كان يستطيب الشراب عند هبوب الجنوب","song":1,"loc":2205},
{"id":"b134-13","bab":"الجزء 12","sec":"كان يستطيب الشراب عند هبوب الجنوب","page":"ج12 ص177","text":"حدثني عمي قال حدثنا أحمد بن محمد الفيرزان قال حدثني شيبة بن هشام قال دعانا محمد بن أمية يوما ووجه إلىجارية كان يحبها فدعاها وبعث إلى مولاها يحدرها مع رسوله فأبطأ الرسول حتى انتصف النهار ثم عاد وليست معه وقال أخذوا مني الدراهم ثم ردوها علي ورأيتهم مختلطين ولهم قصة لم يعرفونيها وقالوا ليست ها هنا فإن عادت بعثنا بها إليكم فتنغص عليه يومه وتغير وجهه وتجمل لنا ثم بكرنا من غد بأجمعنا إلى منزل مولاها فإذا هي قد بيعت فوجم طويلا وسار حتى إذا خلا لنا الطريق اندفع باكيا فما أنسى حرقة بكائه وهو ينشدني\n(تخطى إلي الدهر من بين من أرى ... وسوء مقادير لهن شؤون)\n(فشتت شملي دون كل أخي هوى ... وأقصدني بل كلهم سيبين)\n(ومهما تكن من ضحكة بعد فقدها ... فإني وإن أظهرتها لحزين)\n(سلام على أيامنا قبل هذه ... إذ الدار دار والسرور فنون)\nال ومضت على ذلك مدة ثم أخبرني أنه اجتاز بها وهي تنظر من وراء شباك فسلم عليها فأومأت بالسلام إليه ودخلت فقال\n(تطالعني على وجل خداع ... من الشبك التي عملت حديدا)\n(مطالعتي قفي بالله حتى ... أزود مقلتي نظرا جديدا)\n(فقالت إن سها الواشون عنا ... رجونا أن تعود وأن نعودا)\nأنشدني أيضا في ذلك\n\n(يا صاحب الشبك الذي استخفى ... مكانك غير خاف)\n(أفما رأيت تلددي ... بفناء قصرك واختلافي)\n(أو ما رحمت تخشعي ... وتلفتي بعد انصرافي)\nوت\n(إن الرجال لهم إليك وسيلة ... إن يأخذوك تكحلي وتخضبي)\n(وأنا امرؤ إن يأخذوني عنوة ... أقرن إلى سير الركاب وأجنب)\n(ويكون مركبك القعود وحدجه ... وابن النعامة يوم ذلك مركبي)\nروضه من الكامل قال ابن الأعرابي في تفسير قوله\n(وابن النعامة يوم ذلك مركبي ... )\nبن النعامة ظل الإنسان أو الفرس أو غيره قال جرير\n(إذ ظل يحسب كل شيء فارسا ... ويرى نعامة ظله فيحول)\nعني بنعامة ظله جسده وقال أبو عمرو الشيباني النعامة ما يلي الأصابع في مقدم الرجل يقول مركبي يومئذ رجلي وقال الجاحظ ذكر علماؤنا البصريون أن النعامة اسم فرسه يقول إني أشد على ركابي السرج فإذا صار للفرس وهو الذي يسمى النعامة ظل وأنا مقرون إليه صار ظله تحتي فكنت راكبا له وجعل ظلها هاهنا ابنها الشعر للحارث بن لوذان بن عوف بن الحارث بن سدوس بن شيبان بن\nذهل بن ثعلبة وقال ابن سلام لخزز بن لوذان ومن الناس من ينسب هذا الشعر إلى عنترة وذلك خطأ وأحد من نسبه إليه إسحاق الموصلي والغناء لعزة الميلاء وأول لحنها\n(لمن الديار عرفتها بالشربب ... ذهب الذين بها ولما تذهب)\nبعده إن الرجال وطريقته من خفيف الثقيل الأول بالبنصر من روايتي حماد وابن المكي وفيه للهذيل خفيف ثقيل بالوسطى عن الهشامي وفيه لعريب خفيف رمل وفيه لعزة المرزوقية لحن وقال هارون بن محمد بن عبد الملك الزيات هذا اللحن لريق سلخت لحن ومخنث شهد الزفاف وقبله فجعلته لهذا وهو لحن محرك يشبه صنعة ابن سريج وصنعة حكم في محركاتهما فمن هنا يغلط فيه ويظن أنه قديم الصنعة","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":10,"spl":"كان يستطيب الشراب عند هبوب الجنوب","song":1,"loc":2206,"partial":1},
{"id":"b134-14","bab":"الجزء 12","sec":"ابن أبي عتيق يعجب بغناء عزة الميلاء","page":"ج12 ص183","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال حدثت عن صالح بن حسان قال كان ابن أبي عتيق معجبا بغناء عزة الميلاء كثير الزيارة لها وكان يختار عليها قوله\n(لمن الديار عرفتها بالشربب ... )\nسألها يوما زيارته فأجابته إلى ذلك ومضت نحوه فقال لها بعد أن استقر بها المجلس يا عزة أحب أن تغنيني صوتي الذي أنا له عاشق فغنته هذا الصوت فطرب كل الطرب وسر غاية السرور وكانت له جارية وكان فتى من أهل المدينة كثيرا ما يعبث بها فأعلمت ابن أبي عتيق بذلك فقال لها قولي له وأنا أحبك فإذا قال لك وكيف لي بك فقولي له مولاي يخرج غدا إلى مال له فإذا خرج أدخلتك المنزل وجمع ابن أبي عتيق ناسا من أصحابه فأجلسهم في بيته ومعهم عزة الميلاء وأدخلت الجارية الرجل وقال لعزة غني فأعادت الصوت وخرجت الجارية فمكثت ساعة ثم دخلت البيت كأنها تطلب حاجة فقال لها تعالي فقالت الآن آتيك ثم عادت فدعاها فاعتلت فوثب فأخذها فضرب بها الحجلة فوثب ابن أبي عتيق عليه هو وأصحابه فقال لهم وهو غير مكترث يا فساق ما يجلسكم هاهنا مع هذه المغنية فضحك ابن أبي عتيق من قوله وقال له استر علينا ستر الله تعالى عليك فقالت له عزة يا بن الصديق ما أظرف هذا لولا فسقه فاستحيا الرجل فخرج وبلغه أن ابن عتيق قد آلى إن هو وقع في يده أن يصير به إلى السلطان فأقبل يعبث بها كلما خرجت فشكت ذلك إلى مولاها فقال لها أو لم يرتدع من العبث بك قالت لا قال فهيئي الرحى وهيئي من الطعام طحين ليلة إلى\nالغداة فقالت أفعل يا مولاي فهيأت ذلك على ما أمرها به ثم قال لها عديه الليلة فإذا جاء فقولي له إن وظيفتي الليلة طحن هذا البر كله ثم اخرجي من البيت واتركيه ففعلت فلما دخل طحنت الجارية قليلا ثم قالت له إن كفت الرحى فإن مولاي جاء إلي أو بعض من وكله بي فاطحن حتى نأمن أن يجيئنا أحد ثم اصير إلى قضاء حاجتك ففعل الفتى ومضت الجارية إلى مولاها وتركته وقد أمر ابن أبي عتيق عدة من مولياته أن يتراوحن على سهر ليلتهن ويتفقدن أمر الطحين ويحثثن الفتى عليه كلما أمسك ففعلن وجعلن ينادينه كلما كف يا فلانة إن مولاك مستيقظ والساعة يعلم أنك كففت عن الطحن فيقوم إليك بالعصا كعادته مع من كانت نوبتها قبلك إذا هي نامت وكفت عن الطحن فلم يزل الفتى كلما سمع ذلك الكلام يجتهد في العمل والجارية تتعهد وتقول قد استيقظ مولاي والساعة ينام فأصير إلى ما تحب فلم يزل الرجل يطحن حتى أصبح وفرغ من جميع القمح فلما فرغ وعلمت الجارية أتته فقالت قد أصبحت فانج بنفسك فقال أوقد فعلتها يا عدوة الله فخرج تعبا نصبا فأعقبه ذلك مرضا شديدا أشرف منه على الموت وعاهد الله تعالى ألا يعود إلى كلامها فلم تر منه بعد ذلك شيئا ينكر\n(أجد اليوم جيرتك احتمالا ... وحث حداتهم بهم عجالا)\n(وفي الأظعان آنسة لعوب ... ترى قتلي بغير دم حلالا)\nروضه من الوافر الشعر للمتوكل الليثي والغناء لابن محرز ثاني ثقيل\nبالسبابة في مجرى الوسطى عن إسحاق وفيه لابن مسجح ثاني ثقيل آخر بالخنصر في مجرى البنصر عنه وذكر حبش أن هذا اللحن لابن سريج وفيه لإسحاق هزج","topic":"أخبار أبي زبيد ونسبه","topicNo":134,"sp":11,"spl":"ابن أبي عتيق يعجب بغناء عزة الميلاء","song":1,"loc":2207,"partialRef":{"sid":"b134-13","gi":6,"vi":0,"side":0},"partial":1},
{"id":"b135-1","bab":"الجزء 12","sec":"نسب المتوكل الليثي وأخباره","page":"ج12 ص187","text":"هو المتوكل بن عبد الله بن نهشل بن مسافع بن وهب بن عمرو بن لقيط ابن يعمر بن عوف بن عامر بن ليث بن بكر بن عبد مناة بن كنانة بن خزيمة بن مدركة بن إلياس بن مضر بن نزار من شعراء الإسلام وهو من أهل الكوفة كان في عصر معاوية وابنه يزيد ومدحهما ويكنى أبا جهمة وقد اجتمع مع الأخطل وناشده عند قبيصة بن والق ويقال عند عكرمة بن ربعي الذي يقال له الفياض فقدمه الأخطل وهذه القصيدة التي أولها الغناء قصيدة هجا بها عكرمة بن ربعي وخبره معه يذكر بعد أخبرني بذلك الحسن بن علي عن أحمد بن سعيد الدمشقي عن الزبير بن بكار عن عمه وأخبرني الحسن بن علي عن أحمد بن سعيد الدمشقي قال حدثني هارون بن محمد بن عبد الملك قال أخبرني هارون بن مسلم قال حدثني حفص بن عمر العمري عن لقيط بن بكير المحاربي قال قدم الأخطل الكوفة فنزل على قبيصة بن والق فقال المتوكل بن عبد الله الليثي لرجل من قومه انطلق بنا إلى الأخطل نستنشده ونسمع من شعره فأتياه فقالا أنشدنا يا أبا مالك فقال إني لخاثر يومي هذا فقال له المتوكل\nأنشدنا أيها الرجل فوالله لا تنشدني قصيدة إلا أنشدتك مثلها أو أشعر منها من شعري قال ومن أنت قال أنا المتوكل قال أنشدني ويحك من شعرك فأنشده\n(للغانيات بذي المجاز رسوم ... فببطن مكة عهدهن قديم)\n(فبمنحر البدن المقلد من منى ... حلل تلوح كأنهن نجوم)\n(لا تنه عن خلق وتأتي مثله ... عار عليك إذا فعلت عظيم)\n(والهم إن لم تمضه لسبيله ... داء تضمنه الضلوع مقيم)\nنى في هذه الأبيات سائب خاثر من رواية حماد عن أبيه ولم يجنسه قال وأنشده أيضا\n(الشعر لب المرء يعرضه ... والقول مثل مواقع النبل)\n(منها المقصر عن رميته ... ونوافذ يذهبن بالخصل)\nقال وأنشده أيضا\n(إننا معشر خلقنا صدورا ... من يسوي الصدور بالأذناب)\nقال له الأخطل ويحك يا متوكل لو نبحت الخمر في جوفك كنت أشعر الناس","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":0,"spl":"نسب المتوكل الليثي وأخباره — ما قاله في زوجه رهيمة","loc":2208},
{"id":"b135-2","bab":"الجزء 12","sec":"ما قاله في زوجه رهيمة","page":"ج12 ص189","text":"قال الطوسي قال الأصمعي كانت للمتوكل بن عبد الله الكناني امرأة يقال لها رهيمة ويقال أميمة وتكنى أم بكر فأقعدت فسألته الطلاق فقال ليس هذا حين طلاق فأبت عليه فطلقها ثم إنها برئت بعد الطلاق فقال في ذلك\n(طربت وشاقني يا أم بكر ... دعاء حمامة تدعو حماما)\n(فبت وبات همي لي نجيا ... أعزي عنك قلبا مستهاما)\n(إذا ذكرت لقلبك أم بكر ... يبيت كأنما اغتبق المداما)\n(خدلجة ترف غروب فيها ... وتكسو المتن ذا خصل سخاما)\n(أبى قلبي فما يهوى سواها ... وإن كانت مودتها غراما)\n(ينام الليل كل خلي هم ... وتأبى العين مني أن تناما)\n(أراعي التاليات من الثريا ... ودمع العين منحدر سجاما)\n(على حين ارعويت وكان رأسي ... كأن على مفارقه ثغاما)\n(سعى الواشون حتى أزعجوها ... ورث الحبل فانجذم انجذاما)\n(فلست بزائل ما دمت حيا ... مسرا من تذكرها هياما)\n(ترجيها وقد شحطت نواها ... ومنتك المنى عاما فعاما)\n(خدلجة لها كفل وثير ... ينوء بها إذا قامت قياما)\n(مخصرة ترى في الكشح منها ... على تثقيل أسفلها انهضاما)\n(إذا ابتسمت تلألأ ضوء برق ... تهلل في الدجنة ثم داما)\n(وإن قامت تأمل رائياها ... غمامة صيف ولجت غماما)\n(إذا تمشى تقول دبيب أيم ... تعرج ساعة ثم استقاما)\n(وإن جلست فدمية بيت عيد ... تصان ولا ترى إلا لماما)\n(فلو أشكو الذي أشكو إليها ... إلى حجر لراجعني الكلاما)\n(أحب دنوها وتحب نأيي ... وتعتام التنائي لي اعتياما)\n(كأني من تذكر أم بكر ... جريح أسنة يشكو كلاما)\n(تساقط أنفسا نفسي عليها ... إذا شحطت وتغتم اغتماما)\n(غشيت لها منازل مقفرات ... عفت إلا الأياصر والثماما)\n(ونؤيا قد تهدم جانباه ... ومبناها بذي سلم خياما)\n(صليني واعلمي أني كريم ... وأن حلاوتي خلطت عراما)\n(وأني ذو مجامحة صليب ... خلقت لمن يماكسني لجاما)\n(فلا وأبيك لا أنساك حتى ... تجاوب هامتي في القبر هاما)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":0,"spl":"نسب المتوكل الليثي وأخباره — ما قاله في زوجه رهيمة","loc":2209},
{"id":"b135-3","bab":"الجزء 12","sec":"مدحه حوشبا الشيباني","page":"ج12 ص191","text":"والقصيدة التي فيها الغناء المذكور في أول خبر المتوكل يقولها أيضا في امرأته هذه ويمدح فيها حوشبا الشيباني ويقول فيها\n(إذا وعدتك معروفا لوته ... وعجلت التجرم والمطالا)\n(لها بشر نقي اللون صاف ... ومتن حط فاعتدل اعتدالا)\n(إذا تمشي تأود جانباها ... وكاد الخصر ينخزل انخزالا)\n(تنوء بها روادفها إذا ما ... وشاحاها على المتنين جالا)\n(فإن تصبح أميمة قد تولت ... وعاد الوصل صرما واعتلالا)\n(فقد تدنو النوى بعد اغتراب ... بها وتفرق الحي الحلالا)\n(تعبس لي أميمة بعد أنس ... فما أدري أسخطا أم دلالا)\n(أبيني لي فرب أخ مصاف ... رزئت وما أحب به بدالا)\n(أصرم منك هذا أم دلال ... فقد عني الدلال إذا وطالا)\n(أم استبدلت بي ومللت وصلي ... فبوحي لي به ودعي المحالا)\n(فلا وأبيك ما أهوى خليلا ... أقاتله على وصلي قتالا)\n(وكم من كاشح يا أم بكر ... من البغضاء يأتكل ائتكالا)\n(لبست على قناع من أذاه ... ولولا الله كنت له نكالا)\nمما يغني به من هذه القصيدة قوله\n(أنا الصقر الذي حدثت عنه ... عتاق الطير تندخل اندخالا)\n(رأيت الغانيات صدفن لما ... رأين الشيب قد شمل القذالا)\n(فلم يلووا إذا رحلوا ولكن ... تولت عيرهم بهم عجالا)\nغنى فيه عمر الوادي خفيف رمل عن الهشامي وذكر حبش أن فيه لابن محرز ثاني ثقيل بالوسطى وأحسبه مضافا إلى لحنه الذي في أول القصيدة\nوقال الطوسي قال أبو عمرو الشيباني","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":1,"spl":"مدحه حوشبا الشيباني","song":1,"loc":2210},
{"id":"b135-4","bab":"الجزء 12","sec":"هجاؤه معن بن حمل","page":"ج12 ص193","text":"هجا معن بن حمل بن جعونة بن وهب أحد بني لقيط بن يعمر المتوكل ابن عبد الله الليثي وبلغ ذلك المتوكل فترفع عن أن يجيبه ومكث معن سنين يهجوه والمتوكل معرض عنه ثم هجاه بعد ذلك وهجا قومه من بني الديل هجاء قذعا استحيا منه وندم ثم قال المتوكل لقومه يعتذر ويمدح يزيد بن معاوية\n(خليلي عوجا اليوم وانتظراني ... فإن الهوى والهم أم أبان)\n(هي الشمس يدنو قريبا بعيدها ... أرى الشمس ما أسطيعها وتراني)\n(نأت بعد قرب دارها وتبدلت ... بنا بدلا والدهر ذو حدثان)\n(فهاج الهوى والشوق لي ذكر حرة ... من المرجحنات الثقال حصان)\nنى في هذه الأبيات ابن محرز من كتاب يونس ولم يجنسه\n(سيعلم قومي أنني كنت سورة ... من المجد إن داعي المنون دعاني)\n(ألا رب مسرور بموتي لو أتى ... وآخر لو أنعى له لبكاني)\n(خليلي ما لام امرأ مثل نفسه ... إذا هي لامت فاربعا ودعاني)\n(ندمت على شتمي العشيرة بعدما ... تغنى بها غوري وحن يماني)\n(قلبت لهم ظهر المجن وليتني ... رجعت بفضل من يدي ولساني)\n(على أنني لم أرم في الشعر مسلما ... ولم أهج إلا من روى وهجاني)\n(هم بطروا الحلم الذي من سجيتي ... فبدلت قومي شدة بليان)\n(ولو شئتم أولاد وهب نزعتم ... ونحن جميع شملنا أخوان)\n(نهيتم أخاكم عن هجائي وقد مضى ... له بعد حول كامل سنتان)\n(فلج ومناه رجال رأيتهم ... إذا قارنوني يكرهون قراني)\n(وكنت امرأ يأبى لي الضيم أنني ... صروم إذا الأمر المهم عناني)\n(وصول صروم لا أقول لمدبر ... هلم إذا ما اغتشني وعصاني)\n(خليلي لو كنت امرأ بي سقطة ... تضعضعت أو زلت بي القدمان)\n(أعيش على بغي العداة ورغمهم ... وآتي الذي أهوى على الشنآن)\n(ولكنني ثبت المريرة حازم ... إذا صاح طلابي ملأت عناني)\n(خليلي كم من كاشح قد رميته ... بقافية مشهورة ورماني)\n(فكان كذات الحيض لم تبق ماءها ... ولم تنق عنها غسلها لأوان)\nم إنه يقول فيها ليزيد بن معاوية\n(أبا خالد حنت إليك مطيتي ... على بعد منتاب وهول جنان)\n(أبا خالد في الأرض نأي ومفسح ... لذي مرة يرمى به الرجوان)\n(فكيف ينام الليل حر عطاؤه ... ثلاث لرأس الحول أو مائتان)\n(تناهت قلوصي بعد إسآدي السرى ... إلى ملك جزل العطاء هجان)\n(ترى الناس أفواجا ينوبون بابه ... لبكر من الحاجات أو لعوان)\nأجابه معن بن حمل فقال\n(ندمت كذاك العبد يندم بعد ما ... غلبت وسار الشعر كل مكان)\n(ولاقيت قرما في أرومة ماجد ... كريما عزيزا دائم الخطران)\n(أنا الشاعر المعروف وجهي ونسبتي ... أعف وتحميني يدي ولساني)\n(وأغلب من هاجيت عفوا وأنتمي ... إلى معشر بيض الوجوه حسان)\n(فهات إذا يابن الأتان كصاحب الملوك أبي أسيد كمهان ... )\n(فهات كزيد أو كسيحان لا تجد ... لهم كفوا أو يبعث الثقلان)\nخبرني محمد بن الحسن بن دريد قال حدثنا العتيبي عن العباس بن هشام عن أبيه عن عوانة قال أتى المتوكل الليثي عكرمة بن ربعي الذي يقال له الفياض فامتدحه فحرمه فقيل له جاءك شاعر العرب فحرمته فقال ما عرفته فأرسل إليه بأربعة آلاف درهم فأبى أن يقبلها وقال حرمني على رؤوس الناس ويبعث إلي سرا فبينا المتوكل بالحيرة وقد رمد رمدا شديد فمر به قس منهم فقال مالك قال رمدت قال أنا أعالجك قال فافعل فذره فبينا القس عنده وهو مذرور العين مستلق على ظهره يفكر في هجاء عكرمة وذلك غير مطرد له ولا القول في معناه إذ أتاه غلام له فقال بالباب امرأة تدعوك فمسح عينيه وخرج إليها فسفرت عن وجهها فإذا الشمس طالعة حسنا فقال لها ما اسمك قالت أمية قال فممن أنت فلم تخبره قال فما حاجتك قالت بلغني أنك شاعر فأحببت أن تنسب بي في شعرك فقال أسفري ففعلت فكر طرفه في وجهها مصعدا ومصوبا ثم تلثمت وولت عنه\nفاطرد له القول الذي كان استصعب عليه في هجاء عكرمة وافتتحه بالنسيب فقال\n(أجد اليوم جيرتك احتمالا ... وحث حداتهم بهم الجمالا)\n(وفي الأظعان آنسة لعوب ... ترى قتلي بغير دم حلالا)\n(أمية يوم دير القس ضنت ... علينا أن تنولنا نوالا)\n(أبيني لي فرب أخ مصاف ... رزئت وما أحب به بدالا)\nقال فيها يهجو عكرمة\n(أقلني يابن ربعي ثنائي ... وهبها مدحة ذهبت ضلالا)\n(وهبها مدحة لم تغن شيئا ... وقولا عاد أكثره وبالا)\n(وجدنا العز من أولاد بكر ... إلى الذهلين يرجع والفعالا)\n(أعكرم كنت كالمبتاع دارا ... رأى بيع الندامة فاستقالا)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":2,"spl":"هجاؤه معن بن حمل","loc":2211,"partial":1},
{"id":"b135-5","bab":"الجزء 12","sec":"هجاؤه معن بن حمل","page":"ج12 ص193","text":"(بنو شيبان أكرم آل بكر ... وأمتنهم إذا عقدوا حبالا)\n(رجال أعطيت أحلام عاد ... إذا نطقوا وأيديها الطوالا)\n(وتيم الله حي حي صدق ... ولكن الرحى تعلو الثفالا)\n\n(سقى دمنتين لم نجد لهما أهلا ... بحقل لكم يا عز قد رابني حقلا)\n(فيا عز إن واش وشى بي عندكم ... فلا تكرميه أن تقولي له مهلا)\n(كما نحن لو واش وشى بك عندنا ... لقلنا تزحزح لا قريبا ولا سهلا)\n(ألم يأن لي يا قلب أن أترك الجهلا ... وأن يحدث الشيب الملم لي العقلا)\n(على حين صار الرأس مني كأنما ... علت فوقه ندافة العطب الغزلا)\nعروضه من الطويل الدمن آثار الديار واحدتها دمنة والحقل الأرض التي يزرع فيها والعطب هو القطن الشعر لكثير كله إلا البيت الأول فإنه انتحله وهو للأفوه الأودي والغناء لابن سريج ثاني ثقيل بالوسطى عن الهشامي في الثلاثة الأبيات الأول متوالية وذكر حبش أنه لمعبد وفي الرابع والخامس والثاني والثالث لحنين ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه ثقيل أول بالبنصر وذكر ابن المكي أنه لمعبد وذكر الهشامي أنه من منحول يحيى المكي","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":3,"spl":"هجاؤه معن بن حمل","song":1,"loc":2212},
{"id":"b135-6","bab":"الجزء 12","sec":"نسب الأفوه الأودي وشيء من أخباره","page":"ج12 ص198","text":"الأفوه لقب واسمه صلاءة بن عمرو بن مالك بن عوف بن الحارث بن عوف بن منبه بن أود بن الصعب بن سعد العشيرة وكان يقال لأبيه عمرو بن مالك فارس الشوهاء وفي ذلك يقول الأفوه\n(أبي فارس الشوهاء عمرو بن مالك ... غداة الوغى إذ مال بالجد عاثر)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا ابن أبي سعد عن علي بن الصباح عن هشام بن محمد الكلبي عن أبيه قال كان الأفوه من كبار الشعراء القدماء في الجاهلية وكان سيد قومه وقائدهم في حروبهم وكانوا يصدرون عن رأيه والعرب تعده من حكمائها وتعد داليته\n(معاشر ما بنوا مجدا لقومهم ... وإن بنى غيرهم ما أفسدوا عادوا)\nمن حكمة العرب وآدابها فأما البيت الذي اخذه كثير من شعر الأفوه وأضافه إلى أبياته التي ذكرناها وفيها الغناء آنفا فإنه من قصيدة يقول فيها\n(نقاتل أقواما فنسبي نساءهم ... ولم ير ذو عز لنسوتنا حجلا)\n(نقود ونأبى أن نقاد ولا نرى ... لقوم علينا في مكارمة فضلا)\n(وإنا بطاء المشي عند نسائنا ... كما قيدت بالصيف نجدية بزلا)\n(نظل غيارى عند كل ستيرة ... نقلب جيدا واضحا وشوى عبلا)\n(وإنا لنعطي المال دون دمائنا ... ونأبى فما نستام دون دم عقلا)\nقال أبو عمرو الشيباني قال الأفوه الأودي هذه الأبيات يفخر بها على قوم من بني عامر كانت بينه وبينهم دماء فأدرك بثأره وزاد وأعطاهم ديات من قتل فضلا على قتلي قومه فقبلوه وصالحوه وقال أبو عمرو أغارت بنو أود وقد جمعها الأفوه على بني عامر فمرض الأفوه مرضا شديدا فخرج بدله زيد بن الحارث الأودي وأقام الأفوه حتى أفاق من وجعه ومضى زيد بن الحارث حتى لقي بني عامر بتضارع وعليهم عوف بن الأحوص بن جعفر بن كلاب فلما التقوا عرف بعضهم بعضا فقال لهم بنو عامر ساندونا فما أصبنا كان بيننا وبينكم فقالت بنو أود وقد أصابوا منهم رجلين لا والله حتى نأخذ بطائلتنا فقام أخو المقتول وهو رجل من بني كعب بن أود فقال يا بني أود والله لتأخذن\nبطائلتي أو لأنتحين على سيفي فاقتتلت أود وبنو عامر فظفرت أود وأصابت مغنما كثيرا فقال الأفوه في ذلك\n(ألا يا لهف لو شهدت قناتي ... قبائل عامر يوم الصبيب)\n(غداة تجمعت كعب إلينا ... حلائب بين أفناء الحروب)\n(فلما أن رأونا في وغاها ... كآساد الغريفة والحجيب)\n(تداعوا ثم مالوا عن ذراها ... كفعل الخامعات من الوجيب)\n(وطاروا كالنعام ببطن قو ... مواءلة على حذر الرقيب)\nوت\n(كأن لم تري قبلي أسيرا مكبلا ... ولا رجلا يرمى به الرجوان)\n(كأني جواد ضمه القيد بعدما ... جرى سابقا في حلبة ورهان)\nالشعر لرجل من لصوص بني تميم يعرف بأبي النشناش والغناء لابن جامع ثاني ثقيل بالبنصر من روايتي علي بن يحيى والهشامي أخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري عن محمد ابن حبيب قال كان أبو النشناش من ملاص بني تميم وكان يعترض القوافل في شذاذ من العرب بين طريق الحجاز والشام فيجتاحها فظفر به بعض عمال مروان فحبسه وقيده مدة ثم أمكنه الهرب في وقت غرة فهرب فمر بغراب على بانة ينتف ريشه وينعب فجزع من ذلك ثم مر بحي من لهب فقال لهم رجل كان في بلاء وشر وحبس وضيق فنجا من ذلك ثم نظر عن يمينه فلم ير شيئا ونظر عن يساره فرأى غرابا على شجرة بان ينتف ريشه وينعب فقال له اللهبي إن صدقت الطير يعاد إلى حبسه وقيده ويطول ذلك به ويقتل ويصلب فقال له بفيك الحجر قال لا بل بفيك وأنشأ يقول\n(وسائلة أين ارتحالي وسائل ... ومن يسأل الصعلوك أين مذاهبه)\n(مذاهبه أن الفجاج عريضة ... إذا ضن عنه بالنوال أقاربه)\n(إذا المرء لم يسرح سواما ولم يرح ... سواما ولم يبسط له الوجه صاحبه)\n(فللموت خير للفتى من قعوده ... عديما ومن مولى تعاف مشاربه)\n(ودوية قفر يحاربها القطا ... سرت بأبي النشناش فيها ركائبه)\n(ليدرك ثأرا أو ليكسب مغنما ... ألا إن هذا الدهر تترى عجائبه)\n(فلم أر مثل الفقر ضاجعه الفتى ... ولا كسواد الليل أخفق طالبه)\n(فعش معذرا أو مت كريما فإنني ... أرى الموت لا يبقى على من يطالبه)\n\n(أصادرة حجاج كعب ومالك ... على كل فتلاء الذراعين محنق)\n(أقام قناة الود بيني وبينه ... وفارقني عن شيمة لم ترنق)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":4,"spl":"نسب الأفوه الأودي وشيء من أخباره","song":2,"loc":2213},
{"id":"b135-7","bab":"الجزء 12","sec":"نسب الأفوه الأودي وشيء من أخباره","page":"ج12 ص198","text":"روضه من الطويل الصادر المنصرف وهو ضد الوارد وأصله من ورود الماء والصدر عنه ثم يقال لكل مقبل إلى موضع ومنصرف عنه وكعب من خزاعة ومالك يعني مالك بن النضر بن كنانة وكان كثير ينتمي وينمي خزاعة إليهم ومحنق ضامرة والشيمة الخلق والطبيعة وترنق تكدر والرنق الكدر الشعر لكثير عزة يرثي خندقا الأسدي والغناء للهذلي ثاني ثقيل بالخنصر في مجرى البنصر من رواية إسحاق وفي الثاني من البيتين ثم الأول\nلسياط رمل بالبنصر عنه وعن الهشامي وعمرو وفيهما لمعبد لحن ذكره يونس ولم يجنسه وفي رواية حماد عن أبيه أن لحن الهذلي من الثقيل الأول فإن كان ذلك كذلك فالثقيل الثاني لمعبد وذكر أحمد بن عبيد أن الذي صح فيه ثقيل أول أو ثاني ثقيل","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":5,"spl":"نسب الأفوه الأودي وشيء من أخباره","loc":2214},
{"id":"b135-8","bab":"الجزء 12","sec":"خبر كثير وخندق الأسدي الذي من أجله قال هذا الشعر","page":"ج12 ص204","text":"حدثني محمد بن العباس اليزيدي قال حدثني محمد بن حبيب وأخبرني وكيع قال حدثنا علي بن محمد النوفلي عن أبيه وأخبرنا أحمد بن عبد العزيز قال حدثنا عمر بن شبة عن ابن داحة قالوا كان خندق بن مرة الأسدي هكذا قال النوفلي وغيره يقول خندق بن بدر صديقا لكثير وكانا يقولان بالرجعة فاجتمعا بالموسم فتذاكرا التشيع فقال خندق لو وجدت من يضمن لي عيالي بعدي لوقفت بالموسم فذكرت فضل آل محمد وظلم الناس لهم وغصبهم إياهم على حقهم ودعوت إليهم وتبرأت من أبي بكر وعمر فضمن كثير عياله فقام ففعل ذلك وسب أبا بكر وعمر رضوان الله عليهما وتبرأ منهما قال عمر بن شبة في خبره فقال أيها الناس إنكم على غير حق قد تركتم أهل بيت نبيكم والحق لهم وهم الأئمة ولم يقل إنه سب أحدا فوثب عليه الناس فضربوه ورموه حتى قتلوه ودفن خندق بقنونى فقال إذ ذاك كثير يرثيه\n(أصادرة حجاج كعب ومالك ... على كل عجلى ضامر البطن محنق)\n(بمرثية فيها ثناء محبر ... لأزهر من أولاد مرة معرق)\n(كأن أخاه في النوائب ملجأ ... إلى علم من ركن قدس المنطق)\n(ينال رجالا نفعه وهو منهم ... بعيد كعيوق الثريا المعلق)\n(تقول ابنة الضمري مالك شاحبا ... ولونك مصفر وإن لم تخلق)\n(فقلت لها لا تعجبي من يمت له ... أخ كأبي بدر وجدك يشفق)\n(وأمر يهم الناس غب نتاجه ... كفيت وكرب بالدواهي مطرق)\n(كشفت أبا بدر إذا القوم أحجموا ... وعضت ملاقي أمرهم بالمخنق)\n(وخصم أبا بدر ألد أبته ... على مثل طعم الحنظل المتفلق)\n(جزى الله خيرا خندقا من مكافيء ... وصاحب صدق ذي حفاظ ومصدق)\n(أقام قناة الود بيني وبينه ... وفارقني عن شيمة لم ترنق)\n(حلفت على أن قد أجنتك حفرة ... ببطن قنونى لو نعيش فنلتقي)\n(لألفيتني بالود بعدك دائما ... على عهدنا إذ نحن لم نتفرق)\n(إذا ما غدا يهتز للمجد والندى ... أشم كغصن البانة المتورق)\n(وإني لجاز بالذي كان بيننا ... بني أسد رهط ابن مرة خندق)\nأخبرني أحمد بن عبد العزيز قال حدثنا عمر بن شبة إن كثيرا لما انتمى إلى قريش وجرى بينه وبين الحزين الديلي من المواثبة والهجاء ما جرى بلغ ذلك الطفيل بن عامر بن واثلة وهو بالكوفة فأنكر أمر كثير وانتسابه إلى كنانة وتصييره خزاعة منهم وما فعله الحزين فحلف لئن رأى كثيرا ليضربنه بالسيف أو ليطعننه بالرمح فكلمه فيه خندق الأسدي وكان صديقا له ولكثير فوهبه له واجتمعا في مكة فجلسا مع ابن الحنفية فقال طفيل لولا خندق لوفيت لك بيميني فقال يرثيه وعنه كان أخذ مقالته\n(ونال رجالا نفعه وهو منهم ... بعيد كعيوق الثريا المعلق)\nذكر باقي الأبيات\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد ابن إسماعيل قال حدثني حميد بن عبد الرحمن أحد بني عتوارة بن جدي قال كان كثير قد سلطه الله ينسب بعزة بنت عبد الله أحد بني حاجب بن عبد الله بن غفار قال وكان نسوانهم قد لقينها وهي سائرة في نسائهم في الجلاء في عام اصابت أهل تهامة فيه حطمة شديدة وكانت عزة من أجمل النساء وآدبهن وأعقلهن ولا والله ما رأى لها وجها قط إلا أنه استهيم بها قلبه لما ذكر له عنها فلقيه رجال من الحي لما بلغهم ذلك عنه فقالوا له إنك قد شهرت نفسك وشهرتنا وشهرت صاحبتنا فاكفف نفسك قال فإني لا أذكرها بما تكرهون فخرجوا جالين إلى مصر في أعوام الجلاء فتبعهم على راحلته فزجروه فأبى إلا أن يلحقهم بنفسه فجلس له فتية من جدي قال وكان بنو ضمرة كلهم يهون عليهم نسيبه لما يعرفون من براءتها إلا ما كان من بني جدي فإنهم كانوا صمعا غيرا فقعد له عون أحد بني جدي في تسعة نفر على محالج فلما جاز بهم تحت الليل أخذوه ثم عدلوا به عن الطريق إلى جيفة حمار كانوا يعرفونها من النهار فأدخلوه فيها وربطوا يديه ورجليه ثم أوثقوا بطن الحمار فجعل يضطرب فيه ويستغيث ومضوا عنه فاجتاز به خندق الأسدي فسمع استغاثته وهو خندق بن بدر فعدل إلى\nالصوت حين سمعه فوجد في الجيفة إنسانا فسأله من هو وما خبره فأخبره فأطلقه وحمله وألحقه ببلاده فقال كثير في ذلك قال الزبير أنشدنيها عمر بن أبي بكر المؤملي عن عبد الله بن أبي عبيدة معمر بن المثنى\n(أصادرة حجاج كعب ومالك ... على كل فتلاء الذراعين محنق)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":6,"spl":"خبر كثير وخندق الأسدي الذي من أجله قال هذا الشعر","loc":2215},
{"id":"b135-10","bab":"الجزء 12","sec":"خبر كثير وخندق الأسدي الذي من أجله قال هذا الشعر — كثير يرثي خندقا","page":"ج12 ص204 – ج12 ص208","text":"ذكر القصيدة كلها على ما مضت أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثنا عمر بن أبي بكر المؤملي عن أبي عبيدة قال خندق الأسدي هو الذي أدخل كثيرا في مذهب الخشبية\nأخبرني محمد بن العباس اليزيدي قال حدثنا محمد بن حبيب قال لما قتل خندق الأسدي بعرفة رثاه كثير فقال\n(شجا أظعان غاضرة الغوادي ... بغير مشورة عرضا فؤادي)\n(أغاضر لو شهدت غداة بنتم ... حنو العائدات على وسادي)\n(أويت لعاشق لم تشكميه ... نوافذه تلذع بالزناد)\n(ويوم الخيل قد سفرت وكفت ... رداء العصب عن رتل براد)\nالرتل الثغر المستوي النبت\n(وعن نجلاء تدمع في بياض ... إذا دمعت وتنظر في سواد)\n(وعن متكاوس في العقص جثل ... أثيت النبت ذي عذر جعاد)\n(وغاضرة الغداة وإن نأتنا ... وأصبح دونها قطر البلاد)\n(أحب ظعينة وبنات نفسي ... إليها لو بللن بها صوادي)\n(ومن دون الذي أملت ودا ... ولو طالبتها خرط القتاد)\n(وقال الناصحون تحل منها ... ببذل قبل شيمتها الجماد)\nحل أصب يقال ما حليت من فلان بشيء ولا تحليت منه بشيء ومنه حلوان الكاهن والراقي وما أشبه ذلك\n(فقد وعدتك لو أقبلت ودا ... فلج بك التدلل في تعاد)\n(فأسررت الندامة يوم نادى ... برد جمال غاضرة المنادي)\n(تمادى البعد دونهم فأمست ... دموع العين لج بها التمادي)\n(لقد منع الرقاد فبت ليلي ... تجافيني الهموم عن الوساد)\n(عداني أن أزورك غير بغض ... مقامك بين مصفحة شداد)\n(وإني قائل إن لم أزره ... سقت ديم السواري والغوادي)\n(محل أخي بني أسد قنونى ... فما والى إلى برك الغماد)\n(مقيم بالمجازة من قنونى ... وأهلك بالأجيفر والثماد)\n(فلا تبعد فكل فتى سيأتي ... عليه الموت يطرق أو يغادي)\n(وكل ذخيرة لا بد يوما ... ولو بقيت تصير إلى نفاد)\n(يعز علي أن نغدو جميعا ... وتصبح ثاويا رهنا بواد)\n(فلو فوديت من حدث المنايا ... وقيتك بالطريف وبالتلاد)\nي هذه القصيدة عدة أصوات هذه نسبتها قد جمعت\n(أغاضر لو شهدت غداة بنتم ... حنو العائدات على وسادي)\n(رثيت لعاشق لم تشكميه ... نوافذه تلذع بالزناد)\n(عداني أن أزورك غير بغض ... مقامك بين مصفحة شداد)\n(فلا تبعد فكل فتى سيأتي ... عليه الموت يطرق أو يغادي)\nمعبد في البيتين الأولين لحن من خفيف الثقيل الأول بالوسطى عن عمرو وابن المكي والهشامي وفيهما لإبراهيم ثقيل أول بالوسطى عن الهشامي وأحمد بن عبيد وفيهما للغريض ثاني ثقيل عن ابن المكي ومن الناس من ينسب لحن مالك إلى معبد أيضا وفي الثالث والرابع لابن عائشة ثاني ثقيل مطلق في\nمجرى الوسطى عن إسحاق وعمرو وغيرهما ويقال إن لابن سريج وابن محرز وابن جامع فيهما ألحانا غاضرة هذه التي ذكرها كثير مولاة لآل مروان بن الحكم وقد روي في ذكره إياها غير خبر مختلف فأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير قال حدثني عمر بن أبي بكر المؤملي قال حدثني عبد الله بن أبي عبيدة قال","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":7,"spl":"خبر كثير وخندق الأسدي الذي من أجله قال هذا الشعر — كثير يرثي خندقا","song":1,"loc":2216},
{"id":"b135-11","bab":"الجزء 12","sec":"أخبار أم البنين","page":"ج12 ص211","text":"حجت أم البنين بنت عبد العزيز بن مروان فقالت لكثير ووضاح انسبابي فأما وضاح فنسب بها وأما كثير فنسب بجاريتها غاضرة حيث يقول\n(شجا أظعان غاضرة الغوادي ... بغير مشورة عرضا فؤادي)\nال وكانت زوجة الوليد بن عبد الملك فقتل وضاحا ولم يجد على كثير سبيلا أخبرني الحرمي قال حدثنا الزبير قال حدثني إبراهيم بن محمد بن عبد\nالعزيز الزهري عن محرز بن جعفر عن أبيه عن بديح قال قدمت أم البنين بنت عبد العزيز بن مروان وهي عند الوليد بن عبد الملك حاجة والوليد إذ ذاك خليفة فأرسلت إلى كثير ووضاح أن نسبا بي فنسب وضاح بها ونسب كثير بجاريتها غاضرة في شعره الذي يقول فيه\n(شجا أظعان غاضرة الغوادي ... )\nال وكان معها جوار قد فتن الناس بالوضاءة قال بديح فلقيت عبيد الله بن قيس الرقيات فقلت له بمن نسبت من هذا القطين فقال لي\n(ما تصنع بالشر ... إذا لم تك مجنونا)\n(إذا قاسيت ثقل الشر ... حساك الأمرينا)\n(وقد هجت بما قد قلت ... أمرا كان مدفونا)\nال بديح ثم أخذ بيدي فخلا بي وقال لي يا بديح احفظ عني ما أقول لك فإنك موضع أمانة وأنشدني\n(أصحوت عن أم البنين ... وذكرها وعنائها)\n(وهجرتها هجر امرئ ... لم يقل حمل إخائها)\n(من خيفة الأعداء أن ... يوهوا أديم صفائها)\n(قرشية كالشمس أشرق ... نورها ببهائها)\n(زادت على البيض الحسان ... بحسنها ونقائها)\n(لما اسبكرت للشباب ... وقنعت بردائها)\n(لم تلتفت للداتها ... ومضت على غلوائها)\nنى ابن عائشة في الثلاثة الأبيات الأول لحنا من الثقيل الأول عن الهشامي عن يحيى المكي وفي الرابع وما بعده لحنين أحدهما ثاني ثقيل بالبنصر والآخر خفيف ثقيل بالبنصر عن ابنه وغيره وغنى إبراهيم الموصلي في الأربعة الأول لحنا آخر من الثقيل الأول وهو اللحن الذي فيه استهلال وذكر الهشامي أن الثقيل الثاني لابن محرز قال فقتل الوليد وضاحا ولم يجد علىكثير سبيلا قال وحجت بعد ذلك وقد تقدم الوليد إليها وإلى من معها في الحجاب فلقيني ابن قيس حيث خرجت ولم تكلم أحدا ولم يرها فقال لي يا بديح\n(بان الخليط الذي به نثق ... واشتد دون المليحة القلق)\n(من دون صفراء في مفاصلها ... لين وفي بعض بطشها خرق)\n(إن ختمت جاز طين خاتمها ... كما تجوز العبدية العتق)\nنى في هذه الأبيات مالك بن أبي السمح لحنا من الثقيل الأول بالبنصر عن عمرو ويونس وفيها لابن مسجح ويقال لابن محرز وهو مما يشبه غناءهما جميعا وينسب إليهما خفيف ثقيل أول بالبنصر والصحيح أنه\nلابن مسجح وفيها ثاني ثقيل لابن محرز عن ابن المكي وذكر حبش أن لسياط فيها لحنا ماخوريا بالوسطى وفي هذه الأبيات زيادة يغني فيها ولم يذكرها الزبير في خبره وهي\n(إني لأخلي لها الفراش إذا ... قصع في حضن زوجه الحمق)\n(عن غير بغض لها لدي ولكن ... تلك مني سجية خلق)\nال الزبير أراد بقوله في هذه الأبيات\n(إن ختمت جاز طين خاتمها ... )\nنها كانت عند سلطان جائز الأمر والعبدية هي الدنانير نسبها إلى عبد الملك ثم وصل ابن قيس الرقيات هذه الأبيات يعني الهائية بأبيات يمدح بها عبد الملك فقال\n(اسمع أمير المؤمنين ... لمدحتي وثنائها)\n(أنت ابن عائشة التي ... فضلت أروم نسائها)\n(متعطف الأعياص حول ... سريرها وفنائها)\n(ولدت أغر مباركا ... كالبدر وسط سمائها)\nناه ابن عائشة من رواية يونس ولم يجنسه وهذا الشعر يقوله ابن قيس الرقيات في عبد الملك لا الوليد أخبرني الحسين وابن أبي الأزهر عن حماد عن أبيه عن المدائني أن\nعبد الملك لما وهب لابن جعفر جرم عبيد الله بن قيس الرقيات وأمنه ثم تواثب أهل الشام ليقتلوه قال يا أمير المؤمنين أتفعل هذا بي وأنا الذي أقول\n(اسمع أمير المؤمنين ... لمدحتي وثنائها)\n(أنت ابن معتلج البطاح ... كديها وكدائها)\n(ولبطن عائشة التي ... فضلت أروم نسائها)\nلما أنشد هذا البيت قال له عبد الملك قل ولنسل عائشة قال لا بل ولبطن عائشة حتى رد ذلك عليه ثلاث مرات وهو يأبى إلا ولبطن عائشة فقال له عبد الملك اسحنفر الآن قال وعائشة أم عبد الملك بنت معاوية بن المغيرة بن أبي العاص بن أمية بن عبد شمس هذه رواية الزبير بن بكار","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":8,"spl":"أخبار أم البنين","song":2,"loc":2217,"partialRef":{"sid":"b65-4","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b135-12","bab":"الجزء 12","sec":"السائب بن حكيم ومحاورته غاضرة","page":"ج12 ص215","text":"وقد حدثنا به في خبر كثير مع غاضرة هذه بغير هذا محمد بن العباس اليزيدي قال حدثنا محمد بن حبيب عن هشام بن الكلبي وأخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن الكلبي عن أبي عبد الرحمن الأنصاري عن السائب بن حكيم السدوسي راوية كثير قال والله إني لأسير يوما مع كثير حتى إذا كنا ببطن جدار جبل من المدينة\nعلى أميال إذ أنا بأمراة في رحالة متنقبة معها عبيد لها يسعون معها فمرت جنابي فسلمت ثم قالت ممن الرجل قلت من أهل الحجاز قالت فهل تروي لكثير شيئا قلت نعم قالت أما والله ما كان بالمدينة من شيء هو أحب إلي من أن أرى كثيرا وأسمع شعره فهل تروي قصيدته\n(أهاجك برق آخر الليل واصب ... )\nلت نعم فأنشدتها إياها إلى آخرها قالت فهل تروي قوله\n(كأنك لم تسمع ولم تر قبلها ... تفرق ألاف لهن حنين)\nلت نعم وأنشدتها قالت فهل تروي قوله أيضا\n(لعزة من أيام ذي الغصن شاقني ... )\nلت نعم وأنشدتها إلى آخرها قالت فهل تروي قوله أيضا\n(أأطلال سعدى باللوى تتعهد ... )\nلت نعم وأنشدتها حتى أتيت على قوله\n(فلم أر مثل العين ضنت بمائها ... علي ولا مثلي على الدمع يحسد)\nقالت قاتله الله فهل قال مثل قول كثير أحد على الأرض والله لأن أكون رأيت كثيرا أو سمعت منه شعره أحب إلي من مائة ألف درهم قال فقلت هو ذاك الراكب أمامك وأنا السائب راويته قالت حياك الله تعالى ثم ركضت بغلتها حتى أدركته فقالت أنت كثير قال ما لك ويلك فقالت أنت الذي تقول\n(إذا حسرت عنه العمامة راعها ... جميل المحيا أغفلته الدواهن)\nالله ما رأيت عربيا قط أقبح ولا أحقر ولا ألأم منك قال أنت والله أقبح مني وألأم قالت له أو لست القائل\n(تراهن إلا أن يؤدين نظرة ... بمؤخر عين أو يقلبن معصما)\n(كواظم ما ينطقن إلا محورة ... رجيعة قول بعد أن يتفهما)\n(يحاذرن مني غيرة قد عرفنها ... قديما فما يضحكن إلا تبسما)\nعن الله من يفرق منك قال بل لعنك الله قالت أولست الذي تقول\n(إذا ضمرية عطست فنكها ... فإن عطاسها طرف الوداق)\nال من أنت قالت لا يضرك أن لم تعرفني ولا من أنا قال والله إني لأراك لئيمة الأصل والعشيرة قالت حياك الله يا أبا صخر ما كان بالمدينة رجل أحب إلي وجها ولا لقاء منك قال لا حياك الله والله ما كان على الأرض أحد أبغض إلي وجها منك قالت أتعرفني قال أعرف أنك لئيمة من اللئام فتعرفت إليه فإذا هي غاضرة أم ولد لبشر بن مروان قال وسايرها حتى سندنا في الجبل من قبل زرود فقالت له يا أبا صخر\nأضمن لك مائة ألف درهم عند بشر بن مروان إن قدمت عليه قال أفي سبك إياي أو سبي إياك تضمنين لي هذا والله لا أخرج إلى العراق على هذه الحال فلما قامت تودعه سفرت فإذا هي أحسن من رأيت من أهل الدنيا وجها فأمرت له بعشرة آلاف درهم فبعد شد ما قبلها وأمرت لي بخمسة آلاف درهم فلما ولوا قال يا سائب أين نعني أنفسنا إلى عكرمة انطلق بنا نأكل هذه حتى يأتينا الموت قال وذلك قوله لما فارقتنا\n(شجا أظعان غاضرة الغوادي ... بغير مشيئة عرضا فؤادي)\nقد روى الزبير أيضا في خبر هذه المرأة غير هذا وخالف المعاني أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني سليمان بن عياش السعدي قال كان كثير يلقى حاج المدينة من قريش بقديد في كل سنة فغفل عاما من الأعوام عن يومهم الذي نزلوا فيه قديدا حتى ارتفع النهار ثم ركب جملا ثقالا واستقبل الشمس في يوم صائف فجاء قديدا وقد كل وتعب فوجدهم قد راحوا وتخلف فتى من قريش معه راحلته حتى يبرد قال الفتى القرشي فجلس كثير إلى جنبي ولم يسلم علي فجاءت امرأة وسيمة جميلة فجلست إلى خيمة من خيام قديد واستقبلت كثيرا فقالت أأنت كثير قال نعم قالت ابن أبي جمعة قال نعم قالت الذي يقول\n(لعزة أطلال أبت أن تكلما ... )\nقال نعم قالت وأنت الذي تقول فيها\n(وكنت إذا ما جئت أجللن مجلسي ... وأظهرن مني هيبة لا تجهما)\nقال نعم قالت أعلى هذا الوجه هيبة إن كنت كاذبا فعليك لعنة الله والملائكة والناس أجمعين فضجر وقال من أنت فلم تجبه بشيء فسأل الموليات اللواتي في الخباء بقديد عنها فلم يخبرنه شيئا فضجر واختلط فلماسكن من شأوه قالت أأنت الذي تقول\n(متى تحسروا عني العمامة تبصروا ... جميل المحيا أغلفته الدواهن)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":9,"spl":"السائب بن حكيم ومحاورته غاضرة","loc":2218,"partial":1},
{"id":"b135-13","bab":"الجزء 12","sec":"السائب بن حكيم ومحاورته غاضرة","page":"ج12 ص215","text":"هذا الوجه جميل المحيا إن كنت كاذبا فعليك لعنة الله والملائكة والناس أجمعين فاختلط وقال والله ما عرفتك ولو عرفتك لفعلت وفعلت فسكتت فلما سكن من شأوه قالت أأنت الذي تقول\n(يروق العيون الناظرات كأنه ... هرقلي وزن أحمر التبر راجح)\nهذا الوجه يروق العيون الناظرات إن كنت كاذبا فعليك لعنة الله ولعنة اللاعنين والملائكة والناس أجمعين فازداد ضجرا وغيظا واختلاطا وقال لها قد عرفتك والله لأقطعنك وقومك بالهجاء ثم قام فالتفت في أثره ثم رجعت طرفي نحو المرأة فإذا هي قد ذهبت فقلت لمولاة من مولياتها بقديد لك الله علي إن أخبرتني من هذه المرأة لأطوين لك ثوبي هذين إذا قضيت حجي ثم أعطيكهما فقالت والله لو أعطيتني زنتهما ذهبا ما أخبرتك من هي هذا كثير وهو مولاي قد سألني عنها فلم أخبره قال الفتى القرشي فرحت والله وبي أشد مما بكثير\nقال سليمان وكان كثير دميما قليلا أحمر أقيشر عظيم الهامة قبيحا","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":10,"spl":"السائب بن حكيم ومحاورته غاضرة — نسبة ما في هذه الأخبار من الشعر الذي يغنى به","loc":2219},
{"id":"b135-14","bab":"الجزء 12","sec":"نسبة ما في هذه الأخبار من الشعر الذي يغنى به","page":"ج12 ص220","text":"صوت منها\n(أشاقك برق آخر الليل واصب ... تضمنه فرش الجبا فالمسارب)\n(كما أومضت بالعين ثم تبسمت ... خريع بدا منها جبين وحاجب)\n(وهبت لليلى ماءه ونباته ... كما كل ذي ود لمن ود واهب)\nروضه من الطويل الواصب الدائم يقال وصب يصب وصوبا أي دام قال الله سبحانه ( وله الدين واصبا\nأي دائما صوت ومنها\n(لعزة من أيام ذي الغصن شاقني ... بضاحي قرار الروضتين رسوم)\n(هي الدار وحشا غير أن قد يحلها ... ويغنى بها شخص علي كريم)\n(فما برسوم الدار لو كنت عالما ... ولا بالتلاع المقويات أهيم)\n(سألت حكيما أين شطت بها النوى ... فخبرني ما لا أحب حكيم)\n(أجدوا فأما آل عزة غدوة ... فبانوا وأما واسط فمقيم)\n(لعمري لئن كان الفؤاد من الهوى ... بغى سقما إني إذا لسقيم)\nحكيم هذا هو أبو السائب بن حكيم راوية كثير ذكر ذلك لنا اليزيدي عن ابن حبيب في هذه الأبيات لمعبد لحنان أحدهما في الثلاثة الأول خفيف ثقيل بالوسطى عن الهشامي وابن المكي وحبش وفي الثلاثة الأخرى التي أولها\n(سألت حكيما اين شطت بها النوى ... )\nه أيضا ثقيل أول بالبنصر عن يونس وحبش وذكر حبش خاصة أن فيها لكردم خفيف ثقيل آخر وفي الثالث والثاني لابن جامع خفيف رمل عن الهشامي وقال أحمد بن عبيد فيه ثلاثة ألحان ثقيل أول وخفيفه وخفيف رمل أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني المؤملي أن ابن أبي عبيدة كان إذا انشد قصيدة كثير\n(لعزة من أيام ذي الغصن شاقني ... بضاحي قرار الروضتين رسوم)\nيتحازن حتى نقول إنه يبكي أخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني عمي عن الضحاك ابن عثمان قال قال عروة بن أذينة كان الحزين الكناني الشاعر صديقا لأبي وكان عشيرا له على النبيذ فكان كثيرا ما يأتيه وكانت بالمدينة قينة يهواها الحزين ويكثر غشيانها فبيعت وأخرجت عن المدينة فأتى الحزين أبي\nوهو كئيب حزين كاسمه فقال له أبي يا أبا حكيم ما لك قال أنا والله يا أبا عامر كما قال كثير\n(لعمري لئن كان الفؤاد من الهوى ... بغى سقما إني إذا لسقيم)\n(سألت حكيما أين شطت بها النوى ... فخبرني مالا أحب حكيم)\nقال له ابي أنت مجنون إن أقمت على هذا","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":10,"spl":"السائب بن حكيم ومحاورته غاضرة — نسبة ما في هذه الأخبار من الشعر الذي يغنى به","loc":2220,"partial":1},
{"id":"b135-15","bab":"الجزء 12","sec":"ميمية كثير في عزة","page":"ج12 ص222","text":"وهذه القصيدة يقولها كثير في عزة لما أخرجت إلى مصر وذلك قوله فيها\n(ولست براء نحو مصر سحابة ... وإن بعدت إلا قعدت أشيم)\n(فقد يوجد النكس الدني عن الهوى ... عزوفا ويصبو المرء وهو كريم)\n(وقال خليلي ما لها إذ لقيتها ... غداة الشبا فيها عليك وجوم)\n(فقلت له إن المودة بيننا ... على غير فحش والصفاء قديم)\n(وإني وان أعرضت عنها تجلدا ... على العهد فيما بيننا لمقيم)\n(وإن زمانا فرق الدهر بيننا ... وبينكم في صرفه لمشوم)\n(أفي الحق هذا أن قلبك سالم ... صحيح وقلبي في هواك سقيم)\n(وأن بجسمي منك داء مخامرا ... وجسمك موفور عليك سليم)\n(لعمرك ما أنصفتني في مودتي ... ولكنني يا عز عنك حليم)\n(فإما تريني اليوم أبدي جلادة ... فإني لعمري تحت ذاك كليم)\n(ولست ابنة الضمري منك بناقم ... ذنوب العدا إني إذا لظلوم)\n(وإني لذو وجد إذا عاد وصلها ... وإني على ربي إذا لكريم)\nمنها\n(لعزة أطلال أبت أن تكلما ... تهيج مغانيها الفؤاد المتيما)\n(وكنت إذا ما جئت أجللن مجلسي ... وأظهرن مني هيبة لا تجهما)\n(يحاذرن مني غيرة قد عرفنها ... قديما فما يضحكن إلا تبسما)\nروضه من الطويل غنى فيه مالك بن أبي السمح لحنين عن يونس أحدهما ثقيل أؤل بالخنصر في مجرى البنصر عن إسحاق وغيره ينسبه إلى معبد والآخر ثاني ثقيل بالوسطى عن حبش وفيه لابن محرز خفيف ثقيل أول بالبنصر عن عمرو والهشامي وغيره يقول إنه لحن مالك وفيه لابن سريج خفيف رمل بالبنصر عن عمرو والهشامي وعلي بن يحيى وأخبرني أحمد بن جعفر جحظلة قال حدثني ميمون بن هارون قال حدثني من أثق به عن مسرور الخادم أن الرشيد لما أراد قتل جعفر بن يحيى لم يطلع عليه أحدا بتة ودخل عليه جعفر في اليوم الذي قتله في ليلته فقال له اذهب فتشاغل اليوم بمن تأنس\nبه واصطبح فإني مصطبح مع الحرم فمضى جعفر وفعل الرشيد ذلك ولم يزل بر الرشيد وألطافه وتحفه وتحياته تتابع إليه لئلا يستوحش فلما كان في الليل دعاني فقال لي اذهب فجئني الساعة براس جعفر بن يحيى وضم إلي جماعة من الغلمان فمضيت حتى هجمت عليه منزله وإذا أبو زكار الأعمى يغنيه بقوله\n(فلا تبعد فكل فتى سيأتي ... عليه الموت يطرق أو يغادي)\nفقلت له في هذا المعنى ومثله والله جئتك فأجب فوثب وقال ما الخبر يا أبا هاشم جعلني الله فداءك قلت قد أمرت بأخذ رأسك فأكب على رجلي فقبلها وقال الله الله راجع أمير المؤمنين في فقلت ما لي إلى ذلك سبيل قال فأعهد قلت ذاك لك فذهب يدخل إلى النساء فمنعته وقلت أعهد في موضعك فدعا بدواة وكتب أحرفا على دهش ثم قال لي يا أبا هاشم بقيت واحدة قلت هاتها قال خذني معك إلى أمير المؤمنين حتى أخاطبه قلت ما لي إلى ذلك سبيل قال ويحك لا تقتلني بأمره على النبيذ فقلت هيهات ما شرب اليوم شيئا قال فخذني واحبسني عندك في الدار وعاوده في أمري قلت أفعل فأخذته فقال لي أبو زكار الأعمي نشدتك الله إن قتلته إلا ألحقتني به قلت له يا هذا لقد اخترت غير مختار قال وكيف أعيش بعده وحياتي كانت معه وبه وأغناني عمن سواه فما أحب الحياة بعده فمضيت بجعفر وجعلته في بيت وأقفلت عليه ووكلت به ودخلت إلى الرشيد فلما رآني قال أين رأسه ويلك فأخبرته بالخبر فقال يابن الفاعلة والله لئن لم تجئني برأسه الساعة لآخذن رأسك فمضيت إليه فأخذت رأسه ووضعته بين يديه ثم أخبرته خبره\nوذكرت له خبر أبي زكار الأعمى فلما كان بعد مدة أمرني بإحضاره فأحضرته فوصله وبره وأمر بالجراية عليه","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":11,"spl":"ميمية كثير في عزة","song":1,"loc":2221},
{"id":"b135-16","bab":"الجزء 12","sec":"اخبار منظور بن زبان","page":"ج12 ص225","text":"\n(قفا في دار خولة فاسألاها ... تقادم عهدها وهجرتماها)\n(بمحلال يفوح المسك منه ... إذا هبت بأبطحه صباها)\n(أترعى حيث شاءت من حمانا ... وتمنعنا فلا نرعى حماها)\nروضه من الوافر الشعر لرجل من فزارة والغناء ذكر حماد عن أبيه أنه لمعبد وذكر عنه في موضع آخر أنه لأبن مسجح وطريقته من الثقيل الأول مطلق في مجرى الوسطى وهذا الشعر يقوله الفزاري في خولة بنت منظور بن زبان بن سيار بن عمرو ابن جابر بن عقيل بن هلال بن سمي بن مازن بن فزارة بن ذبيان بن بغيض بن ريث بن غطفان وكان منظور بن زبان سيد قومه غير مدافع أمه قهطم بنت هاشم بن حرملة وقد ولدت أيضا زهير بن جذيمة فكان آخذا بأطراف الشرف في قومه وهو أحد من طال حمل أمه به قال الزبير بن بكار فيما أجاز لنا الحرمي بن أبي العلاء والطوسي روايته عنهما مما حدثا به عنه حدثتني مغيرة بنت أبي عدي قال الزبير وقد حدثني هذا الحديث أيضا إبراهيم بن زياد عن محمد بن طلحة وحدثنيه أحمد بن محمد بن سعيد بن عقدة عن يحيى بن الحسن العلوي عن الزبير قالا جميعا حملت قهطم بنت هاشم بمنظور بن زبان أربع سنين فولدته وقد جمع فاه فسماه أبو منظورا لذلك يعني لطول ما انتظره وقال فيه على ما رواه محمد ابن طلحة\n(ما جئت حتى قيل ليس بوارد ... فسميت منظورا وجئت على قدر)\n(وإني لأرجو أن تكون كهاشم ... وإني لأرجو أن تسود بني بدر)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":12,"spl":"اخبار منظور بن زبان","song":1,"loc":2222},
{"id":"b135-17","bab":"الجزء 12","sec":"منظور يتزوج امرأة أبيه","page":"ج12 ص226","text":"ذكر الهيثم بن عدي عن ابن الكلبي وابن عياش وذكر بعضه الزبير بن بكار عن عمه عن مجالد أن منظور بن زبان تزوج امرأة أبيه وهي مليكة بنت سنان بن أبي حارثة المري فولدت له هاشما وعبد الجبار وخولة ولم تزل معه إلىخلافة عمر بن الخطاب رضي الله عنه وكان يشرب الخمر أيضا فرفع أمره إلى عمر فأحضره وسأله عما قيل فاعترف به وقال ما علمت أنها حرام فحبسه إلى وقت صلاة العصر ثم أحلفه أنه لم يعلم أن الله جل وعز حرم ما فعله فحلف فيما ذكر أربعين يمينا فخلى سبيله وفرق بينه وبين امرأة أبيه وقال لولا أنك حلفت لضربت عنقك قال ابن الكلبي في خبره إن عمر قال له أتنكح امرأة أبيك وهي أمك أو ما علمت أن هذا نكاح المقت وفرق بينهما فتزوجها محمد بن طلحة\nقال ابن الكلبي في خبره فلما طلقها أسف عليها وقال فيها\n(ألا لا أبالي اليوم ما صنع الدهر ... إذا منعت مني مليكة والخمر)\n(فإن تك قد أمست بعيدا مزارها ... فحي ابنة المري ما طلع الفجر)\n(لعمري ما كانت مليكة سوءة ... ولا ضم في بيت على مثلها ستر)\nقال أيضا\n(لعمر أبي دين يفرق بيننا ... وبينك قسرا إنه لعظيم)\nقال حجر بن معاوية بن عيينة بن حصن بن حذيفة لمنظور\n(لبئس ما خلف الآباء بعدهم ... في الأمهات عجان الكلب منظور)\n(قد كنت تغمزها والشيخ حاضرها ... فالآن أنت بطول الغمز معذور)\nال أبو الفرج الأصبهاني أخطأ ابن الكلبي في هذا وإنما طلحة بن عبيد الله الذي تزوجها فأما محمد فإنه تزوج خولة بنت منظور فولدت له إبراهيم بن محمد وكان أعرج ثم قتل عنها يوم الجمل فتزوجها الحسن بن\nعلي عليهما السلام فولدت له الحسن بن الحسن عليهما السلام وكان إبراهيم بن محمد بن طلحة نازع بعض ولد الحسين بن علي بعض ما كان بينهم وبين بني الحسن من مال علي عليه السلام فقال الحسيني لأمير المدينة هذا الظالم الضالع الظالع يعني إبراهيم فقال له إبراهيم والله إني لأبغضك فقال له الحسيني صادق والله يحب الصادقين وما يمنعك من ذلك وقد قتل أبي أباك وجدك وناك عمي أمك لا يكني فأمر بهما فأقيما من بين يدي الأمير رجع الخبر إلى رواية ابن الكلبي قال فلما فرق عمر رضي الله عنه بينهما وتزوجت رآها منظور يوما وهي تمشي في الطريق وكانت جميلة رائعة الحسن فقال يا مليكة لعن الله دينا فرق بيني وبينك فلم تكلمه وجازت وجاز بعدها زوجها فقال له منظور كيف رأيت أثر أيري في حر مليكة قال كما رأيت اثر أير أبيك فيه فأفحمه وبلغ عمر رضي الله عنه الخبر فطلبه ليعاقبه فهرب منه وقال الزبير في حديثه فتزوج محمد بن طلحة بن عبيد الله خولة بنت منظور فولدت له إبراهيم وداود وأم القاسم بني محمد بن طلحة ثم قتل عنها يوم الجمل فخلف عليها الحسن بن علي بن أبي طالب عليهما السلام فولدت له الحسن بن الحسن رضي الله عنهما قال الزبير وقال محمد بن الضحاك الحزامي عن أبيه تزوج الحسن عليه السلام خولة بنت منظور زوجه إياها عبد الله بن الزبير وكانت أختها تحته\nوأخبرني أحمد بن محمد بن سعيد قال حدثني يحيى بن الحسن قال حدثني موسى بن عبيد الله بن الحسن قال جعلت خولة أمرها إلى الحسن عليه السلام فتزوجها فبلغ ذلك منظور بن زبان فقال أمثلي يفتات عليه في ابنته فقدم المدينة فركز راية سوداء في مسجد رسول الله فلم يبق قيسي بالمدينة إلا دخل تحتها فقيل لمنظور بن زبان أين يذهب بك تزوجها الحسن بن علي عليه السلام وليس مثله أحد فلم يقبل وبلغ الحسن عليه السلام مافعل فقال له ها شأنك بها فأخذها وخرج بها فلما كان بقباء جعلت خولة تندمه وتقول الحسن بن علي سيد شباب أهل الجنة فقال تلبثي هاهنا فإن كانت للرجل فيك حاجة فسيلحقنا هاهنا قال فلحقه الحسن والحسين عليهما السلام وابن جعفر وابن عباس فتزوجها الحسن ورجع بها قال الزبير ففي ذلك يقول جفير العبسي\n(إن الندى من بني ذبيان قد علموا ... والجود في آل منظور بن سيار)\n(الماطرين بأيديهم ندى ديما ... وكل غيث من الوسمي مدرار)\n(تزور جاراتهم وهنا فواضلهم ... وما فتاهم لها سرا بزوار)\n(ترضى قريش بهم صهرا لأنفسهم ... وهم رضا لبني أخت وأصهار)","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":13,"spl":"منظور يتزوج امرأة أبيه","loc":2223},
{"id":"b135-18","bab":"الجزء 12","sec":"معبد يغني خولة بنت منظور","page":"ج12 ص230","text":"أخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثني ابن أبي أيوب عن ابن عائشة المغني عن معبد أن خولة بنت منظور كانت عند الحسن بن علي عليهما السلام فلما أسنت مات عنها أو طلقها فكشفت قناعها وبرزت للرجال قال معبد فأتيتها ذات يوم أطالبها بحاجة فغنيتها لحني في شعر قاله فيها بعض بني فزارة وكان خطبها فلم ينكحها أبوها\n(قفا في دار خولة فاسألاها ... تقادم عهدها وهجرتماها)\n(بمحلال كأن المسك فيه ... إذا فاحت بأبطحه صباها)\n(كأنك مزنة برقت بليل ... لحران يضيء له سناها)\n(فلم تمطر عليه وجاوزته ... وقد أشفى عليها أو رجاها)\n(وما يملا فؤادي فاعلميه ... سلو النفس عنك ولا غناها)\n(وترعى حيث شاء من حمانا ... وتمنعنا فلا نرعى حماها)\nال فطربت العجوز لذلك وقالت يا عبد بن قطن أنا والله يومئذ أحسن من النار الموقدة في الليلة القرة\n(لله در عصابة صاحبتهم ... يوم الرصافة مثلهم لم يوجد)\n(متقلدين صفائحا هندية ... يتركن من ضربوا كأن لم يولد)\n(وغدا الرجال الثائرون كأنما ... أبصارهم قطع الحديد الموقد)\nعروضه من الكامل الشعر للجحاف السلمي الموقع ببني تغلب في يوم البشر والغناء للأبجر ثقيل أول بالبنصر في مجراها عن إسحاق","topic":"نسب المتوكل الليثي وأخباره","topicNo":135,"sp":14,"spl":"معبد يغني خولة بنت منظور","song":1,"loc":2224},
{"id":"b136-2","bab":"الجزء 12","sec":"خبر الجحاف ونسبه وقصته يوم البشر — قصته يوم البشر","page":"ج12 ص231 – ج12 ص232","text":"هو الجحاف بن حكيم بن عاصم بن قيس بن سباع بن خزاعي بن محاربي بن فالج بن ذكوان بن ثعلبة بن بهثة بن سليم بن منصور\nكان السبب في ذلك فيما أخبرنا به محمد بن العباس اليزيدي وعلي بن سليمان الأخفش قالا حدثنا أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي وأخبرنا إبراهيم بن أيوب عن ابن قتيبة وأخبرنا أحمد بن عبد العزيز الجوهري وحبيب بن نصر المهلبي قالا حدثنا عمر بن شبة وقد جمعت روايتهم وأكثر اللفظ في الخبر لابن حبيب أن عمير بن الحباب لما قتلته بنو تغلب بالحشاك وهو إلى جانب الثرثار وهو قريب من تكريت أتى تميم بن الحباب أخاه زفر بن الحارث\nفأخبره بمقتل عمير وسأله الطلب له بثأره فكره ذلك زفر فسار تميم بن الحباب بمن تبعه من قيس وتابعه على ذلك مسلم بن أبي ربيعة العقيلي فلما توجهوا نحو بني تغلب لقيهم الهذيل في زراعة لهم فقال أين تريدون فأخبروه بما كان من زفر فقال أمهلوني ألق الشيخ فأقاموا ومضى الهذيل فأتى زفر فقال ما صنعت والله لئن ظفر بهذه العصابة إنه لعار عليك ولئن ظفروا إنه لأشد قال زفر فاحبس علي القوم وقام زفر في أصحابه فحرضهم ثم شخص واستخلف عليهم أخاه أوسا وسار حتى انتهى إلى الثرثار فدفنوا أصحابهم ثم وجه زفر بن الحارث يزيد بن حمران في خيل فأساء إلى بني فدوكس من تغلب فقتل رجالهم واستباح أموالهم فلم يبق في ذلك الجو غير امرأة واحدة يقال لها حميدة بنت امرئ القيس عاذت بابن حمران فأعاذها وبعث الهذيل إلى بني كعب بن زهير فقتل فيهم قتلا ذريعا وبعث مسلم بن ربيعة إلى ناحية أخرى فأسرع في القتل وبلغ ذلك بني تغلب واليمن فارتحلوا يريدون عبور دجلة فلحقهم زفر بالكحيل وهو نهر أسفل الموصل مع المغرب فاقتتلوا قتالا شديدا وترجل أصحاب زفر أجمعون وبقي زفر على بغل له فقتلوهم من ليلتهم وبقروا ما وجدوا من النساء وذكر أن من غرق في دجلة أكثر ممن قتل بالسيف وأن الدم كان في دجلة قريبا من رمية سهم فلم يزالوا يقتلون من وجدوا حتى اصبحوا فذكر أن زفر دخل معهم دجلة وكانت فيه بحة فجعل ينادي ولا يسمعه أصحابه ففقدوا\nصوته وحسبوا أن يكون قتل فتذامروا وقالوا لئن قتل شيخنا لما صنعنا شيئا فاتبعوه فإذا هو في دجلة يصيح بالناس وتغلب قد رمت بأنفسها تعبر في الماء فخرج من الماء وأقام في موضعه فهذه الوقعة الحرجية لأنهم أحرجوا فألقوا أنفسهم في الماء ثم وجه يزيد بن حمران وتميم بن الحباب ومسلم بن ربيعة والهذيل بن زفر في أصحابه وأمرهم ألا يلقوا أحدا إلا قتلوه فانصرفوا من ليلتهم وكل قد أصاب حاجته من القتل والمال ثم مضى يستقبل الشمال في جماعة من أصحابه حتى أتى رأس الأثيل ولم يخل بالكحيل أحدا والكحيل على عشرة فراسخ من الموصل فيما بينها وبين الجنوب فصعد قبل راس الأثيل فوجد به عسكرا من اليمن وتغلب فقاتلهم بقية ليلتهم فهربت تغلب وصبرت اليمن وهذه الليلة تسميها تغلب ليلة الهرير ففي ذلك يقول زفر بن الحارث وقد ذكر أنها لغيره\n(ولما أن نعى الناعي عميرا ... حسبت سماءهم دهيت بليل)\nهيت بليل أي أظلمت نهارا كأن ليلا دهاها\n(وكان النجم يطلع في قتام ... وخاف الذل من يمن سهيل)\n(وكنت قبيلها يا أم عمرو ... أرجل لمتي وأجر ذيلي)\n(فلو نبش المقابر عن عمير ... فيخبر من بلاء أبي الهذيل)\n(غداة يقارع الأبطال حتى ... جرى منهم دما مرج الكحيل)\n(قبيل ينهدون إلى قبيل ... تساقى الموت كيلا بعد كيل)\nفي ذلك يقول جرير يعير الأخطل\n(أنسيت يومك بالجزيرة بعدما ... كانت عواقبه عليك وبالا)\n(حملت عليك حماة قيس خيلها ... شعثا عوابس تحمل الأبطالا)\n(ما زلت تحسب كل شيء بعدهم ... خيلا تكر عليكم ورجالا)\n(زفر الرئيس أبو الهذيل أبادكم ... فسبى النساء وأحرز الأموالا)","topic":"خبر الجحاف ونسبه وقصته يوم البشر","topicNo":136,"sp":0,"spl":"خبر الجحاف ونسبه وقصته يوم البشر — قصته يوم البشر","loc":2225},
{"id":"b136-3","bab":"الجزء 12","sec":"اغراه الأخطل بشعره بأخذ الثأر من تغلب","page":"ج12 ص235","text":"فما أن كانت سنة ثلاث وسبعين وقتل عبد الله بن الزبير هدأت الفتنة واجتمع الناس على عبد الملك بن مروان وتكافت قيس وتغلب عن المغازي بالشام والجزيرة وظن كل واحد من الفريقين أن عنده فضلا لصاحبه وتكلم عبد الملك في ذلك ولم يحكم الصلح فيه فبينا هم على تلك الحال إذ أنشد الأخطل عبد الملك بن مروان وعنده وجوه قيس قوله\n(ألا سائل الجحاف هل هو ثائر ... بقتلى أصيبت من سليم وعامر)\n(أجحاف إن نهبط عليك فتلتقي ... عليك بحور طاميات الزواخر)\n(تكن مثل أبداء الحباب الذي جرى ... البحر تزهاه رياح الصراصر)\nوثب الجحاف يجر مطرفه ومايعلم من الغضب فقال عبد الملك\nللأخطل ما أحسبك إلا قد كسبت قومك شرا فافتعل الجحاف عهدا من عبد الملك على صدقات بكر وتغلب وصحبه من قومه نحو من ألف فارس فثار بهم حتى بلغ الرصافة قال وبينها وبين شط الفرات ليلة وهي في قبلة الفرات ثم كشف لهم أمره وأنشدهم شعر الأخطل وقال لهم إنما هي النار أو العار فمن صبر فليقدم ومن كره فليرجع قالوا ما بأنفسنا عن نفسك رغبة فأخبرهم بما يريد فقالوا نحن معك فيما كنت فيه من خير وشر فارتحلوا فطرقوا صهين بعد رؤبة من الليل وهي في قبلة الرصافة وبينهما مي ثم صبحوا عاجنة الرحوب في قبلة صهين والبشر وهو واد لبني تغلب فأغاروا على بني تغلب ليلا فقتلوهم وبقروا من النساء من كانت حاملا ومن كانت غير حامل قتلوها قال عمر بن شبة في خبره سمعت أبي يقول صعد الجحاف الجبل فهو يوم البشر ويقال له أيضا يوم عاجنة الرحوب ويوم مخاشن وهو جبل إلى جنب البشر وهو مرج السلوطح لأنه بالرحوب وقتل في تلك الليلة ابنا للأخطل يقال له أبو غياث ففي ذلك يقول جرير له\n(شربت الخمر بعد أبي غياث ... فلا نعمت لك السوءات بالا)\nال عمر بن شبة في خبره خاصة ووقع الأخطل في أيديهم وعليه عباءة دنسة فسألوه فذكر أنه عبد من عبيدهم فأطلقوه فقال ابن صفار في ذلك\n(لم تنج إلا بالتعبد نفسه ... لما تيقن أنهم قوم عدا)\n(وتشابهت برق العباء عليهم ... فنجا ولو عرفوا عباءته هوى)\nجعل ينادي من كانت حاملا فإلي فصعدن إليه فجعل يبقر بطونهن ثم إن الجحاف هرب بعد فعله وفرق عنه أصحابه ولحق بالروم فلحق الجحاف عبيدة بن همام التغلبي دون الدرب فكر عليه الجحاف فهزمه وهزم أصحابه وقتلهم ومكث زمنا في الروم وقال في ذلك\n(فإن تطردوني تطردوني وقد مضى ... من الورد يوم في دماء الأراقم)\n(لدن ذر قرن الشمس حتى تلبست ... ظلاما بركض المقربات الصلادم)\nتى سكن غضب عبد الملك وكلمته القيسية في أن يؤمنه فلان وتلكأ فقيل له إنا والله لا نأمنه على المسلمين إن طال مقامه بالروم فأمنه فاقبل فلما قدم على عبد الملك لقيه الأخطل فقال له الجحاف\n(أبا مالك هل لمتني إذ حضضتني ... على القتل أم هل لامني لك لائمي)\n(أبا مالك إني أطعتك في التي ... حضضت عليها فعل حران حازم)\n(فإن تدعني أخرى أجبك بمثلها ... وإني لطب بالوغى جد عالم)\nال ابن حبيب فزعموا أن الأخطل قال له أراك والله شيخ سوء وقال فيه جرير\n(فإنك والجحاف يوم تحضه ... أردت بذاك المكث والورد أعجل)\n(بكى دوبل لا يرقئ الله دمعه ... ألا إنما يبكي من الذل دوبل)\n(وما زالت القتلى تمور دماؤهم ... بدجلة حتى ماء دجلة أشكل)\nفقال الأخطل ما لجرير لعنه الله والله ما سمتني أمي دوبلا إلا وأنا صبي صغير ثم ذهب ذلك عني لما كبرت وقال الأخطل\n(لقد أوقع الجحاف بالبشر وقعة ... إلى الله منها المشتكي والمعول)\n(فسائل بني مروان ما بال ذمة ... وحبل ضعيف لا يزال يوصل)\n(فإلا تغيرها قريش بملكها ... يكن عن قريش مستراد ومزحل)\nقال عبد الملك حين أنشده هذا فإلى أين يابن النصرانية قال إلى النار قال أولى لك لو قلت غيرها قال ورأى عبد الملك أنه إن تركهم على حالهم لم يحكم الأمر فأمر الوليد بن عبد الملك فحمل الدماء التي كانت قبل ذلك بين قيس وتغلب وضمن الجحاف قتلى البشر وألزمه إياها عقوبة له فأدى الوليد الحمالات ولم يكن عند الجحاف ما حمل فلحق بالحجاج بالعراق يسأله ما حمل لأنه من هوازن فسأل الإذن على الحجاج فمنعه فلقي أسماء بن خارجة فعصب حاجته به فقال إني لا أقدر لك","topic":"خبر الجحاف ونسبه وقصته يوم البشر","topicNo":136,"sp":1,"spl":"اغراه الأخطل بشعره بأخذ الثأر من تغلب","loc":2226},
{"id":"b136-4","bab":"الجزء 12","sec":"اغراه الأخطل بشعره بأخذ الثأر من تغلب","page":"ج12 ص235","text":"على منفعة قد علم الأمير بمكانك وأبى أن يأذن لك فقال لا والله لا ألزمها غيرك أنجحت أو أكدت فلما بلغ ذلك الحجاج قال ما له عندي شيء فأبلغه ذلك قال وما عليك أن تكون أنت الذي تؤنسه فإنه قد أبى فأذن له فلما رآه قال أعهدتني خائنا لا أبا لك قال أنت سيد هوازن وقد بدأنا بك وأنت أمير العراقين وابن عظيم القريتين وعمالتك في كل سنة خمسمائة ألف درهم وما بك بعدها حاجة إلى خيانة فقال أشهد أن الله تعالى وفقك وأنك نظرت بنور الله فإذا صدقت فلك نصفها العام فأعطاه وادوا البقية قال ثم تأله الجحاف بعد ذلك واستأذن في الحج فأذن له فخرج في المشيخة الذين شهدوا معه قد لبسوا الصوف وأحرموا وأبروا أنوفهم أي خزموها وجعلوا فيها البرى ومشوا إلى مكة فلما قدموا المدينة ومكة جعل الناس يخرجون فينظرون إليهم ويعجبون منهم قال وسمع ابن عمر الجحاف وقد تعلق بأستار الكعبة وهو يقول اللهم اغفر لي وما أراك تفعل فقال له ابن عمر يا هذا لو كنت الجحاف ما زدت على هذا القول قال فأنا الجحاف فسكت وسمعه محمد بن علي بن أبي طالب عليه السلام وهو يقول ذلك فقال يا عبد الله قنوطك من عفو الله أعظم من ذنبك قال عمر بن شبة في خبره كان مولد الجحاف بالبصرة قال عبد الله بن إسحاق النحوي كان الجحاف معي في الكتاب\nقال أبو زيد في خبره أيضا ولما أمنه عبد الملك دخل عليه في جبة صوف فلبث قائما فقال له عبد الملك أنشدني بعض ما قلت في غزوتك هذه وفجرتك فأنشده قوله\n(صبرت سليم للطعان وعامر ... وإذا جزعنا لم نجد من يصبر)\nقال له عبد الملك بن مروان كذبت ما أكثر من يصبر ثم أنشده\n(نحن الذين إذا علوا لم يفخروا ... يوم اللقا وإذا علوا لم يضجروا)\nقال عبدالملك صدقت حدثني أبي عن أبي سفيان بن حرب أنكم كنتم كما وصفت يوم فتح مكة حدثت عن الدمشقي عن الزبير بن بكار وأخبرني وكيع عن عبد الله بن شبيب عن الزبير بن بكار عن عبد الرحمن بن أبي الزناد عن أبيه عن عمر بن عبد العزيز بن مروان أنه حضر الجحاف عند عبد الملك بن مروان يوما والأخطل حاضر في مجلسه ينشد\n(ألا سائل الجحاف هل هو ثائر ... بقتلى أصيبت من سليم وعامر)\nال فتقبض وجهه في وجه الأخطل ثم إن الأخطل لما قال له ذلك قال له\n(نعم سوف نبكيهم بكل مهند ... ونبكي عميرا بالرماح الخواطر)\nم قال ظننت أنك يابن النصرانية لم تكن تجتريء علي ولو رأيتني لك مأسورا وأوعده فما برح الأخطل حتى حم فقال له عبد الملك أنا جارك\nمنه قال هذا أجرتني منه يقظان فمن يجيرني منه نائما قال فجعل عبد الملك يضحك قال فأما قول الأخطل\n(ألا سائل الجحاف هل هو ثائر ... بقتلى أصيبت من سليم وعامر)\nإنه يعني اليوم الذي قتلت فيه بنو تغلب عمير بن الحباب السلمي وكان السبب في ذلك فيما أخبرني به علي بن سليمان الأخفش قال حدثني أبو سعيد السكري عن محمد بن حبيب عن أبي عبيدة عن ابن الأعرابي عن المفضل أن قيسا وتغلب تحاشدوا لما كان بينهم من الوقائع منذ ابتداء الحرب بمرج راهط فكانوا يتغاورون وكانت بنو مالك بن بكر جامعة بالتوباذ وما حوله وجلبت إليها طوائف تغلب وجميع بطونها إلا أن بكر بن جشم لم تجتمع أحلافهم من النمر بن قاسط وحشدت بكر فلم يأت الجمع منهم على قدر عددهم وكانت تغلب بدوا بالجزيرة لا حاضرة لها إلا قليل بالكوفة وكانت حاضرة الجزيرة لقيس وقضاعة وأخلاط مضر ففارقتهم قضاعة قبل حرب تغلب وأرسلت تغلب إلى مهاجريها وهم بأذربيجان فأتاهم شعيب بن مليل في ألفي فارس واستنصر عمير تميما وأسدا فلم يأته منهم أحد فقال\n(أيا أخوينا من تميم هديتما ... ومن أسد هل تسمعان المناديا)\n(ألم تعلما مذ جاء بكر بن وائل ... وتغلب الفافا تهز العواليا)\n(إلى قومكم قد تعلمون مكانهم ... وهم قرب أدنى حاضرين وباديا)\nكان من حضر ذلك من وجوه بكر بن وائل المجشر بن الحارث بن عامر بن مرة بن عبد الله بن أبي ربيعة بن ذهل بن شيبان وكان من سادات شيبان بالجزيرة فأتاهم في جمع كثير من بني أبي ربيعة وفي ذلك يقول تميم ابن الحباب بعد يوم الحشاك\n(فإن تحتجز بالماء بكر بن وائل ... بني عمنا فالدهر ذو متغير)\n(فسوف نخيض الماء أو سوف نلتقي ... فنقتص من أبناء عم المجشر)","topic":"خبر الجحاف ونسبه وقصته يوم البشر","topicNo":136,"sp":2,"spl":"اغراه الأخطل بشعره بأخذ الثأر من تغلب","loc":2227},
{"id":"b136-5","bab":"الجزء 12","sec":"اغراه الأخطل بشعره بأخذ الثأر من تغلب","page":"ج12 ص235","text":"وأتاهم زمام بن مالك بن الحصين من بني عمرو بن هاشم بن مرة في جمع كبير فشهدوا يوم الثرثار فقتل وكان فيمن أتاهم من العراق من بكر بن وائل عبيد الله بن زياد بن ظبيان ورهصة بن النعمان بن سويد بن خالد من بني أسعد بن همام فلذلك تحامل المصعب بن الزبير على أبان بن زياد أخي عبيد الله بن زياد فقتله وفي هذا السبب كانت فرقة عبيد الله لمصعب وجمعت تغلب فأكثرت فلما أتى عميرا كثرة من أتى من بني تغلب وأبطأ عنه أصحابه قال يستبطئهم\n(أناديهم وقد خذلت كلاب ... وحولي من ربيعة كالجبال)\n(أقاتلهم بحي بني سليم ... ويعصر كالمصاعيب النهال)\n(فدى لفوارس الثرثار قومي ... وما جمعت من أهلي ومالي)\n(فإما أمس قد حانت وفاتي ... فقد فارقت أعصر غير قال)\n(أبعد فوارس الثرثار أرجو ... ثراء المال أو عدد الرجال)\nثم زحف العسكران فأتت قيس وتغلب الثرثار بين راس الأثيل والكحيل فشاهدوا القتال يوم الخميس وكان شعيب بن مليل وثعلبة بن نياط التغلبيان قدما في ألفي فارس في الحديد فعبروا على قرية يقال لها لبى على شاطيء دجلة بين تكريت وبين الموصل ثم توجهوا إلى الثرثار فنظر شعيب إلى دواخن قيس فقال لثعلبة بن نياط سر بنا إليهم فقال له الرأي أن نسير إلى جماعة قومنا فيكون مقاتلنا واحدا فقال شعيب والله لا تحدث تغلب أني نظرت إلى دواخنهم ثم انصرفت عنهم فأرسل ناسا من أصحابه قدامة وعمير يقاتل بني تغلب وذلك يوم الخميس وعلى تغلب حنظلة بن هوبر أحد بني كنانة بن تميم فجاء رجل من أصحاب عمير إليه فأخبره أن طلائع شعيب قد أتته وأنه قد عدل إليه فقال عمير لأصحابه اكفوني قتال ابن هوبر ومضى هو في جماعة من أصحابه فأخذ الذين قدمهم شعيب فقتلهم كلهم غير رجل من بني كعب بن زهير يقال له قتب بن عبيد فقال عمير يا قتب أخبرني ما وراءك قال قد أتاك شعيب بن مليل في أصحابه وفارق ثعلبة بن نياط شعيبا فمضى إلى حنظلة بن هوبر فقاتل معه القيسية فقتل فالتقى عمير وشعيب فاقتتلوا قتالا شديدا فما صليت العصر حتى قتل شعيب وأصحابه أجمعون وقطعت رجل شعيب يومئذ فجعل يقاتل القوم وهو يقول\n(قد علمت قيس ونحن نعلم ... أن الفتى يفتك وهو أجذم)\nلما قتل شعيب نزل أصحابه فعقروا دوابهم ثم قاتلوا حتى قتلوا فلما رآه عمير قتيلا قال من سره أن ينظر إلى الأسد عقيرا فها هو ذا وجعلت تغلب يومئذ ترتجز وتقاتل وهي تقول\nحذف\n(انعوا إياسا واندبوا مجاشعا ... كلاهما كان كريما فاجعا)\n(ويه بني تغلب ضربا ناقعا ... )\nوانصرف عمير إلى عسكره وأبلغ بني تغلب مقتل شعيب فحميت على القتال وتذامرت على الصبر فقال محصن بن حصين بن جنجور أحد الأبناء مضيت أنا ومن أفلت من أصحاب شعيب بعد العصر فأتينا راهبا في صومعته فسألنا عن حالنا فأخبرناه فأمر تلميذا له فجاءه بخرق فداوى جراحنا وذلك غداة يوم الجمعة فلما كان آخر ذلك اليوم أتانا خبر مقتل عمير وأصحابه وهرب من أفلت منهم\n(إن جنبي على الفراش لناب ... كتجافي الأسر فوق الظراب)\n(من حديث نمى إلى فما أطعم ... غمضا ولا أسيغ شرابي)\n(لشرحبيل إذ تعاوره الأرماح ... في حال شدة وشباب)\n(فارس يطعن الكماة جريء ... تحته قارح كلون الغراب)\nروضه من الخفيف الأسر البعير الذي يكون به السرر وهي قرحة تخرج في كركرته لا يقدر أن يبرك إلا على موضع مستو من الأرض والظراب النشوز والجبال الصغار واحدها ظرب والشعر لغلفاء وهو معد يكرب بن الحارث بن عمرو بن حجر آكل المرار الكندي يرثي أخاه شرحبيل قتيل يوم الكلاب الأول والغناء للغريض ثقيل أول بالسبابة في مجرى البنصر عن إسحاق ويونس وعمرو","topic":"خبر الجحاف ونسبه وقصته يوم البشر","topicNo":136,"sp":3,"spl":"اغراه الأخطل بشعره بأخذ الثأر من تغلب","song":1,"loc":2228,"partial":1},
{"id":"b136-6","bab":"الجزء 12","sec":"قصة يوم الكلاب الاول","page":"ج12 ص245","text":"وكان السبب في مقتله وقصة يوم الكلاب فيما أخبرنا به محمد بن العباس اليزيدي وعلي بن سليمان الأخفش قالا حدثنا أبو سعيد السكري قال أخبرنا محمد بن حبيب عن أبي عبيدة قال أخبرني إبراهيم بن سعدان عن أبيه عن أبي عبيدة قال أخبرني دماذ عن أبي عبيدة قال كان من حديث الكلاب الأول أن قباذ ملك فارس لما ملك كان ضعيف الملك فوثبت ربيعة على المنذر الأكبر بن ماء السماء وهو ذو القرنين بن النعمان بن الشقيقة فأخرجوه وإنما سمي ذا القرنين لأنه كانت له ذؤابتان فخرج هاربا منهم حتى مات في إياد وترك ابنه المنذر الأصغر فيهم وكان أذكى ولده فانطلقت ربيعة إلى كندة فجاؤوا بالحارث بن عمرو بن حجر آكل المرار فملكوه على بكر بن وائل وحشدوا له فقاتلوا معه فظهر على ما كانت العرب تسكن من أرض العراق وأبى قباذ أن يمد المنذر بجيش فلما رأى ذلك المنذر كتب إلى الحارث بن عمرو إني في غير قومي وأنت أحق من ضمني وأنا متحول إليك فحوله إليه وزوجه ابنته هندا ففرق الحارث بنيه في قبائل العرب فصار شرحبيل بن الحارث في بني بكر بن وائل وحنظلة بن مالك وبني أسيد وطوائف من بني عمرو بن تميم والرباب وصار معد يكرب بن الحارث وهو غلفاء في قيس وصار سلمة بن الحارث في\nبني تغلب والنمر بن قاسط وسعد بن زيد مناة فلما هلك الحارث تشتت أمر بنيه وتفرقت كلمتهم ومشت الرجال بينهم وكانت المغاورة بين الأحياء الذين معهم وتفاقم الأمر حتى جمع كل واحد منهم لصاحبه بين الأحياء الذين معهم وتفاقم الأمر حتى جمع كل واحد منهم لصاحبه الجموع فسار شرحبيل ومن معه من بني تميم والقبائل فنزلوا الكلاب وهو فيما بين الكوفة والبصرة على سبع ليال من اليمامة وأقبل سلمة بن الحارث في تغلب والنمر ومن معه وفي الصنائع وهم الذين يقال لهم بنو رقية وهي أم لهم ينتسبون إليها وكانوا يكونون مع الملوك يريدون الكلاب وكان نصحاء شرحبيل وسلمة قد نهوهما عن الحرب والفساد والتحاسد وحذروهما عثرات الحرب وسوء مغبتها فلم يقبلا ولم يبرحا وأبيا إلا التتايع واللجاجة في أمرهم فقال امرؤ القيس بن حجر في ذلك\n(أنى علي استتب لومكما ... ولم تلوما عمرا ولا عصما)\n(كلا يمين الإله يجمعنا ... شيء وأخوالنا بني جشما)\n(حتى تزور السباع ملحمة ... كأنها من ثمود أو إرما)\nوكان أول من ورد الكلاب من جمع سلمة سفيان بن مجاشع بن دارم وكان نازلا في بني تغلب مع إخوته لأمه فقتلت بكر بن وائل بنين له فيهم مرة بن سفيان قتله سالم بن كعب بن عمرو بن أبي ربيعة بن ذهل بن شيبان فقال سفيان وهو يرتجز\n(الشيخ شيخ ثكلان ... والجوف جوف حران)\n(والورد ورد عجلان ... أنعى مرة بن سفيان)\nوفي ذلك يقول الفرزدق\n(شيوخ منهم عدس بن زيد ... وسفيان الذي ورد الكلابا)\nأول من ورد الماء من بني تغلب رجل من بني عبد جشم يقال له النعمان ابن قريع بن حارثة بن معاوية بن عبد بن جشم وعبد يغوث بن دوس وهو عم الأخطل دوس والفدوكس أخوان على فرس له يقال له الحرون وبه كان يعرف ثم ورد سلمة بين تغلب وسعد وجماعة الناس وعلى بني تغلب يومئذ السفاح واسمه سلمة بن خالد بن كعب بن زهير بن تيم بن أسامة بن مالك بن بكر بن حبيب وهو يقول\n(إن الكلاب ماؤنا فجلوه ... وساجرا والله لن تحلوه)\nفاقتتل القوم قتالا شديدا وثبت بعضهم لبعض حتى إذا كان في آخر النهار من ذلك اليوم خذلت بنو حنظلة وعمرو بن تميم والرباب بكر بن وائل وانصرفت بنو سعد وألفافها عن بني تغلب وصبر ابنا وائل بكر وتغلب ليس معهم غيرهم حتى إذا غشيهم الليل نادى منادي سلمة من أتى برأس شرحبيل فله مائة من الإبل وكان شرحبيل نازلا في بني حنظلة وعمرو بن تميم ففروا عنه وعرف مكانه أبو حنش وهو عصم بن النعمان بن مالك بن غياث بن سعد بن زهير بن جشم بن بكر بن حبيب فصمد نحوه فلما انتهى إليه رآه جالسا وطوائف الناس يقاتلون حوله فطعنه بالرمح ثم نزل إليه فاحتز رأسه وألقاه إليه ويقال إن بني حنظلة وبني عمرو بن تميم والرباب لما انهزموا خرج معهم شرحبيل فلحقه ذو السنينة واسمه حبيب بن عتيبة بن حبيب بن بعج بن عتبة بن سعد بن زهير بن جشم بن بكر وكانت له سن زائدة فالتفت","topic":"خبر الجحاف ونسبه وقصته يوم البشر","topicNo":136,"sp":4,"spl":"قصة يوم الكلاب الاول","loc":2229},
{"id":"b136-7","bab":"الجزء 12","sec":"قصة يوم الكلاب الاول","page":"ج12 ص245","text":"شرحبيل فضرب ذا السنينة على ركبته فأطن رجله وكان ذو السنينة أخا أبي حنش لأمه أمهما سلمى بنت عدي بن ربيعة بنت أخي كليب ومهلهل فقال ذو السنينة قتلني الرجل فقال أبو حنش قتلني الله إن لم أقتله فحمل عليه فلما غشيه قال يا أبا حنش أملكا بسوقة قال إنه قد كان ملكي فطعنه أبو حنش فأصاب رادفة السرج فورعت عنه ثم تناوله فألقاه عن فرسه ونزل إليه فاحتز رأسه فبعث به إلى سلمة مع ابن عم له يقال له أبو أجأ بن كعب بن مالك بن غياث فألقاه بين يديه فقال له سلمة لو كنت ألقيته إلقاء رفيقا فقال ما صنع بي وهو حي أشد من هذا وعرف أبو أجأ الندامة في وجهه والجزع على أخيه فهرب وهرب أبو حنش فتنحى عنه فقال معد يكرب أخو شرحبيل وكان صاحب سلامة معتزلا عن جميع هذه الحروب\n(ألا أبلغ أبا حنش رسولا ... فما لك لا تجيء إلى الثواب)\n(تعلم أن خير الناس طرا ... قتيل بين أحجار الكلاب)\n(تداعت حوله جشم بن بكر ... وأسلمه جعاسيس الرباب)\n(قتيل ما قتيلك يابن سلمى ... تضر به صديقك أو تحابي)\nقال أبو حنش مجيبا له\n(أحاذر أن أجيئكم فتحبو ... حباء أبيك يوم صنيبعات)\n(فكانت غدرة شنعاء تهفو ... تقلدها أبوك إلى الممات)\nويقال إن الشعر الأول لسلمة بن الحارث وقال معد يكرب المعروف بغلفاء يرثي أخاه شرحبيل بن الحارث\n(إن جنبي عن الفراش لنابي ... كتجافي الأسر فوق الظراب)\n(من حديث نمى إلي فلا تر ... فأعيني ولا أسيغ شرابي)\n(مرة كالذعاف أكتمها الناس ... على حر ملة كالشهاب)\n(من شرحبيل إذ تعاوره الأر ... ماح في حال لذة وشباب)\n(يابن أمي ولو شهدتك إذ تدعو ... تميما وأنت غير مجاب)\n(لتركت الحسام تجري ظباه ... من دماء الأعداء يوم الكلاب)\n(ثم طاعنت من ورائك حتى ... تبلغ الرحب أو تبز ثيابي)\n(يوم ثارت بنو تميم وولت ... خيلهم يتقين بالأذناب)\n(ويحكم يا بني أسيد إني ... ويحكم ربكم ورب الرباب)\n(أين معطيكم الجزيل وحابيكم ... على الفقر بالمئين الكباب)\n(فارس يضرب الكتيبة بالسيف ... على نحره كنضح الملاب)\n(فارس يطعن الكماة جريء ... تحته قارح كلون الغراب)\nال ولما قتل شرحبيل قامت بنو سعد بن زيد مناة بن تميم دون عياله فمنعوهم وحالوا بين الناس وبينهم ودفعوا عنهم حتى ألحقوهم بقومهم ومأمنهم ولي ذلك منهم عوف بن شجنة بن الحارث بن عطارد بن عوف بن سعد بن كعب وحشد له فيه رهطه ونهضوا معه فأثنى عليهم في ذلك امرؤ القيس بن حجر ومدحهم به في شعره فقال\n(ألا إن قوما كنتم أمس دونهم ... هم استنقذوا جاراتكم آل غدران)\n(عوير ومن مثل العوير ورهطه ... وأسعد في يوم الهزاهز صفوان)\nهي قصيدة معروفة طويلة\n(وعين الرضا عن كل عيب كليلة ... ولكن عين السخط تبدي المساويا)\n(وأنت أخي مالم تكن لي حاجة ... فإن عرضت أيقنت أن لا أخا ليا)\nلشعر لعبد الله بن معاوية بن عبد الله الجعفري يقوله للحسين بن عبد الله بن عبيد الله بن العباس هكذا ذكر مصعب الزبيري وذكر مؤرج فيما أخبرنا به اليزيدي عن عمه أبي جعفر عن مؤرج وهو الصحيح أن عبد الله بن معاوية قال هذا الشعر في صديق له يقال له قصي بن ذكوان وكان قد عتب عليه وأول الشعر\n(رأيت قصيا كان شيئا ملففا ... فكشفه التمحيص حتى بدا ليا)\n(فلا زاد ما بيني وبينك بعدما ... بلوتك في الحاجات إلا تنائيا)\nالغناء لبنان بن عمرون رمل بالوسطى وفيه الثقيل الأول لعريب من رواية أبي العنبس وغيره","topic":"خبر الجحاف ونسبه وقصته يوم البشر","topicNo":136,"sp":5,"spl":"قصة يوم الكلاب الاول","song":1,"loc":2230},
{"id":"b137-1","bab":"الجزء 12","sec":"خبر عبد الله بن معاوية ونسبه","page":"ج12 ص251","text":"هو عبد الله بن معاوية بن عبد الله بن جعفر بن أبي طالب بن عبد المطلب ابن هاشم بن عبد مناف وأم عبد الله بن جعفر وسائر بني جعفر أسماء بنت عميس بن معد بن تميم بن مالك بن قحافة بن عامر بن معاوية بن زيد بن مالك بن بشر بن وهب الله بن شهران بن عفرس بن أفتل وهوخماعة بن خثعم ابن أنمار وأمها هند بنت عوف امرأة من جرش هذه الجرشية أكرم الناس أحماء أحماؤها رسول الله وعلي وجعفر وحمزة والعباس وأبو بكر رضي الله تعالى عنهم وإنما صار رسول الله من أحمائها أنه كان لها أربع بنات ميمونة زوجة رسول الله وأم الفضل زوجة العباس وأم بنته وسلمى زوجة حمزة بن عبد المطلب بنات الحارث وأسماء بنت عميس أختهن لأمهن كانت عند جعفر بن أبي طالب ثم خلف عليها أبو بكر رضي الله تعالى عنه ثم خلف عليها علي بن أبي طالب عليه السلام وولدت من جميعهم وهن اللواتي قال رسول الله لهن إنهن مؤمنات حدثني بذلك أحمد بن محمد بن سعيد قال حدثني يحيى بن الحسن\nالعلوي قال حدثنا هارون بن محمد بن موسى الفروي قال حدثنا داود بن عبد الله قال حدثني عبد العزيز الدراوردي عن إبراهيم بن عقبة عن كريب عن ابن عباس رضي الله تعالى عنهما قال قال رسول الله الأخوات المؤمنات ميمونة وأم الفضل وسلمى وأسماء بنت عميس أختهن لأمهن حدثني أحمد قال حدثني يحيى قال حدثنا الحسن بن علي قال حدثني عبد الرزاق قال أخبرني يحيى بن العلاء البجلي عن عمه شعيب بن خالد عن حنظلة بن سمرة بن المسيب عن أبيه عن جده عن ابن عباس قال دخل النبي على فاطمة وعلي عليهما السلام ليلة بنى بها فأبصر خيالا من وراء الستر فقال من هذا فقالت أسماء قال بنت عميس قالت نعم أنا التي أحرس بنتك يا رسول الله فإن الفتاة ليلة بنائها لا بد لها من امرأة تكون قريبا منها إن عرضت لها حاجة أفضت بذلك إليها فقال رسول الله فإني أسأل إلهي أن يحرسك من بين يديك ومن خلفك وعن يمينك وعن شمالك من الشيطان","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":0,"spl":"خبر عبد الله بن معاوية ونسبه","loc":2231},
{"id":"b137-2","bab":"الجزء 12","sec":"بعض من أخبار عبد الله بن جعفر","page":"ج12 ص252","text":"وقد أدرك عبد الله بن جعفر رحمه الله رسول الله وروى عنه فمما روى عنه ما حدثنيه حامد بن محمد بن شعيب البلخي وأحمد بن محمد بن الجعد قالا حدثنا محمد بن بكار قال حدثني إبراهيم بن سعد عن أبيه عن عبد الله بن جعفر قال رأيت النبي يأكل البطيخ بالرطب حدثنا أحمد بن محمد بن سعيد قال حدثنا يحيى بن الحسن قال حدثنا\nسلمة بن شبيب قال حدثنا عبد الرزاق قال أخبرني ابن يحيى وعثمان بن أبي سليمان قالا مر النبي بعبد الله بن جعفر وهو يصنع شيئا من طين من لعب الصبيان فقال ما تصنع بهذا قال أبيعه قال ما تصنع بثمنه قال أشتري به رطبا فآكله فقال النبي اللهم بارك له في صفقة يمينه فكان يقال ما اشترى شيئا إلا ربح فيه أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير بن بكار قال حدثني عمي مصعب عن جدي عبد الله بن مصعب أن الحزين قمر في العقيق في غداة باردة ثيابه فمر به عبد الله بن جعفر وعليه مقطعات خز فاستعار الحزين من رجل ثوبا ثم قام إليه فقال\n(أقول له حين واجهته ... عليك السلام أبا جعفر)\nقال وعليك السلام فقال\n(فأنت المهذب من غالب ... وفي البيت منها الذي تذكر)\nفقال كذبت يا عدو الله ذاك رسول الله فقال\n(فهذي ثيابي قد أخلقت ... وقد غضني زمن منكر)\nال هاك ثيابي فأعطاه ثيابه قال الزبير قال عمي أما البيت الثاني فحدثني عمي عن الفضل بن الربيع عن أبي وما بقي فأنا سمعته من أبي حدثنا أحمد بن محمد بن سعيد قال أخبرنا يحيى بن الحسن قال بلغني أن أعرابيا وقف على مروان بن عبد الحكم أيام الموسم بالمدينة فسأله فقال يا أعرابي ما عندنا ما نصلك ولكن عليك بابن جعفر فأتى الأعرابي باب عبد الله بن جعفر فإذا ثقله قد سار نحو مكة وراحلته بالباب عليها متاعها وسيف معلق فخرج عبد الله من داره وأنشأ الأعرابي يقول\n(أبو جعفر من أهل بيت نبوة ... صلاتهم للمسلمين طهور)\n(أبا جعفر إن الحجيج ترحلوا ... وليس لرحلي فاعلمن بعير)\n(أبا جعفر ضن الأمير بماله ... وأنت على ما في يديك أمير)\n(وأنت امرؤ من هاشم في صميمها ... إليك بصير المجد حيث تصير)\nقال يا أعرابي سار الثقل فدونك الراحلة بما عليها وإياك أن تخدع عن السيف فإني أخذته بألف دينار فأنشأ الأعرابي يقول\n(حباني عبد الله نفسي فداؤه ... بأعيس موار سباط مشافره)\n(وأبيض من ماء الحديد كأنه ... شهاب بدا والليل داج عساكره)\n(وكل امرىء يرجو نوال ابن جعفر ... سيجري له باليمن والبشر طائره)\n(فيا خير خلق الله نفسا ووالدا ... وأكرمه للجار حين يجاوره)\n(سأثني بما أوليتني يابن جعفر ... وما شاكر عرفا كمن هو كافره)\nحدثني أحمد بن يحيى عن رجل قال حدثني شيخ من بني تميم بخراسان قال جاء شاعر إلى عبد الله بن جعفر فأنشده\n(رأيت أبا جعفر في المنام ... كساني من الخز دراعه)\n(شكوت إلى صاحبي أمرها ... فقال ستؤتى بها الساعه)\n(سيكسوكها الماجد الجعفري ... ومن كفه الدهر نفاعه)\n(ومن قال للجود لا تعدني ... فقال لك السمع والطاعه)\nقال عبد الله لغلامه ادفع إليه دراعتي الخز ثم قال له كيف لو ترى جبتي المنسوجة بالذهب التي اشتريتها بثلاثمائة دينار فقال له الشاعر بأبي دعني اغفي إغفاءة أخرى فلعلي أرى هذه الجبة في المنام فضحك منه وقال يا غلام ادفع إليه جبتي الوشي حدثني أحمد قال يحيى قال ابن دأب وسمع قول الشماخ بن ضرار الثعلبي في عبد الله بن جعفر بن أبي طالب رحمه الله\n(إنك يابن جعفر نعم الفتى ... ونعم مأوى طارق إذا أتى)\n(وجار ضيف طرق الحي سرى ... صادف زادا وحديثا يشتهى)\n(إن الحديث طرف من القرى ... )\nقال ابن دأب العجب للشماخ يقول مثل هذا القول لابن جعفر ويقول لعرابة\nالأوسي\n(إذا ما راية رفعت لمجد ... تلقاها عرابة باليمين)","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":1,"spl":"بعض من أخبار عبد الله بن جعفر","loc":2232,"partialRef":{"sid":"b93-5","gi":1,"vi":2,"side":0},"partial":1},
{"id":"b137-3","bab":"الجزء 12","sec":"بعض من أخبار عبد الله بن جعفر","page":"ج12 ص252","text":"بد الله بن جعفر كان أحق بهذا من عرابة قال يحيى بن الحسن وكان عبد الله بن الحسن يقول كان أهل المدينة يدانون بعضهم من بعض إلى أن يأتي عطاء عبد الله بن جعفر أخبرني أحمد قال حدثني يحيى قال حدثني أبو عبيد قال حدثني يزيد ابن هارون عن هشام عن ابن سيرين قال جلب رجل إلى المدينة سكرا فكسد عليه فقيل له لو أتيت ابن جعفر قبله منك وأعطاك الثمن فأتى ابن جعفر فأخبره فأمره بإحضاره وبسط له ثم أمر به فنثر فقال للناس انتهبوا فلما رأى الناس ينتهبون قال جعلت فداءك آخذ معهم قال نعم فجعل الرجل يهيل في غرائره ثم قال لعبد الله أعطني الثمن فقال وكم ثمن سكرك قال أربعة آلاف درهم فأمر له بها أخبرنا أحمد قال حدثني يحيى بن علي وحدثني ابن عبد العزيز قال حدثنا أبو محمد الباهلي حسن بن سعيد عن الأصمعي نحوه وزاد فيه قال فقال الرجل مايدري هذا وما يعقل أخذ أم أعطى لأطلبنه بالثمن ثانية فغدا عليه فقال ثمن سكري فأطرق عبد الله مليا ثم قال يا غلام أعطه أربعة آلاف درهم فأعطاه إياها فقال الرجل قد قلت لكم إن هذا\nالرجل لا يعقل أخذ أم أعطى لأطلبنه بالثمن فغدا عليه فقال أصلحك الله ثمن سكري فأطرق عبد الله مليا ثم رفع رأسه إلى رجل فقال ادفع إليه أربعة آلاف درهم فلما ولى ليقبضها قال له ابن جعفر يا أعرابي هذه تمام اثني عشر ألف درهم فانصرف الرجل وهو يعجب من فعله وأخبرني أبو الحسن الأسدي عن دماذ عن أبي عبيدة أن أعرابيا باع راحلة من عبد الله بن جعفر ثم غدا عليه فاقتضى ثمنها فأمر له به ثم عاوده ثلاثا وذكر في الخبر مثل الذي قبله وزاد فيه فقال فيه\n(لا خير في المجتدى في الحين تسأله ... فاستمطروا من قريش خير مختدع)\n(تخال فيه إذا حاروته بلها ... من جوده وهو وافي العقل والورع)\nهذا الشعر يروى لابن قيس الرقيات","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":2,"spl":"بعض من أخبار عبد الله بن جعفر","loc":2233},
{"id":"b137-4","bab":"الجزء 12","sec":"توفي في خلافة عبد الملك بن مروان","page":"ج12 ص257","text":"أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير قال حدثني مصعب بن عثمان قال لما ولي عبد الملك الخلافة جفا عبد الله بن جعفر فراح يوما إلى الجمعة وهو يقول اللهم إنك عودتني عادة جريت عليها فإن كان ذلك قد انقضى فاقبضني إليك فتوفي في الجمعة الأخرى قال يحيى توفي عبد الله وهو ابن سبعين سنة في سنة ثمانين وهو عام الجحاف لسيل كان بمكة جحف الحاج فذهب بالإبل عليها الحمولة وكان الوالي على المدينة يومئذ أبان بن عثمان في خلافة عبد الملك بن مروان وهو الذي صلى عليه\nحدثني أحمد بن محمد قال أخبرنا يحيى قال حدثنا الحسين بن محمد قال أخبرني محمد بن مكرم قال أخبرني أحمد بن إبراهيم بن إسماعيل بن داود قال أخبرني الأصمعي عن الجعفري قال لما مات عبد الله بن جعفر شهده أهل المدينة كلهم وإنما كان عبد الله بن جعفر مأوى المساكين وملجأ الضعفاء فما تنظر إلى ذي حجى إلا رأيته مستعبرا قد أظهر الهلع والجزع فلما فرغوا من دفنه قام عمرو بن عثمان فوقف على شفير القبر فقال رحمك الله يا بن جعفر إن كنت لرحمك لواصلا ولأهل الشر لمبغضا ولأهل الريبة لقاليا ولقد كنت فيما بيني وبينك كما قال الأعشى\n(رعيت الذي كان بيني وبينكم ... من الود حتى غيبتك المقابر)\nرحمك الله يوم ولدت ويوم كنت رجلا ويوم مت ويوم تبعث حيا والله لئن كانت هاشم أصيبت بك لقد عم قريشا كلها هلكك فما أظن أن يرى بعدك مثلك فقام عمرو بن سعيد بن العاص الأشدق فقال لا إله إلا الله الذي يرث الأرض ومن عليها وإليه ترجعون ما كان أحلى العيش بك يابن جعفر وما أسمج ما اصبح بعدك والله لو كانت عيني دامعة على أحد لدمعت عليك كان والله حديثك غير مشوب بكذب وودك غر ممزوج بكدر فوثب ابن للمغيرة بن نوفل ولم يثبث الأصمعي اسمه فقال يا عمرو بمن تعرض بمزج الود وشوب الحديث أفبأبني فاطمة فهما والله خير منك ومنه فقال على رسلك يا لكع أردت أن أدخلك معهم هيهات لست هناك والله لو مت أنت ومات أبوك ما مدحت ولا ذممت فتكلم\nبما شئت فلن تجد لك مجيبا فما هو إلا أن سمعهما الناس يتكلمان حتى حجزوا بينهما وانصرفوا قال يحيى وقال عبد الله بن قيس الرقيات في علة عبد الله بن جعفر التي مات فيها\n(بات قلبي تشفه الأوجاع ... من هموم تجنها الأضلاع)\n(من حديث سمعته منع النوم ... فقلبي مما سمعت يراع)\n(إذ أتانا بما كرهنا أبو اللسلاس ... كانت بنفسه الأوجاع)\n(قال ما قال ثم راح سريعا ... أدركت نفسه المنايا السراع)\n(قال يشكو الصداع وهو ثقيل ... بك لا بالذي عنيت الصداع)\n(ابن أسماء لا أبالك تنعى ... أنه غير هالك نفاع)\n(هاشميا بكفه من سجال المجد ... سجل يهون فيه القباع)\n(نشر الناس كل ذلك منه ... شيمة المجد ليس فيه خداع)\n(لم أجد بعدك الأخلاء إلا ... كثماد به قذى أو نقاع)\n(بيته من بيوت عبد مناف ... مد أطنابه المكان اليفاع)\n(منتهى الحمد والنبوة والمجد ... إذا قصر اللئام الوضاع)\n(فستأتيك مدحة من كريم ... ناله من ندى سجالك باع)\nن هذا الشعر الذي قاله ابن قيس في عبد الله بن جعفر بيتان يغني فيهما وهما\n\n(قد أتانا بما كرهنا أبو اللسلاس ... كانت بنفسه الأوجاع)\n(قال يشكو الصداع وهو ثقيل ... بك لا بالذي ذكرت الصداع)\nناه عمرو بن بانة خفيف ثقيل الأول بالوسطى على مذهب إسحاق ويقال إن عمرو بن بانة صاغ هذا اللحن في هذا الشعر وغنى به الواثق بعقب علة نالته وصداع تشكاه قال فاستحسنه وأمر له بعشرة آلاف درهم وأم معاوية بن عبد الله بن جعفر أم ولد وكان من رجالات قريش ولم يكن في ولد عبد الله مثله حدثنا محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز عن المدائني عن أبي عبد الرحمن القرشي أن معاوية بن عبد الله بن جعفر ولد وأبوه عبد الله عند معاوية فأتاه البشير بذلك وعرف معاوية الخبر فقال سمه معاوية ولك مائة ألف درهم ففعل فأعطاه المال وأعطاه عبد الله للذي بشره به قال المدائني وكان عبد الله بن جعفر لا يؤدب ولده ويقول إن يرد الله جل وعز بهم خيرا يتأدبوا فلم ينجب فيهم غير معاوية","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":3,"spl":"توفي في خلافة عبد الملك بن مروان","song":1,"loc":2234},
{"id":"b137-5","bab":"الجزء 12","sec":"ابن هرمة ومعاوية بن عبد الله بن جعفر","page":"ج12 ص260","text":"أخبرني محمد بن خلف وكيع قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثنا حماد بن إسحاق عن أبيه قال هارون وحدثني محمد بن عبد الله بن موسى بن خالد بن الزبير بن العوام قال حدثني عمرو بن الحكم السعيدي وإبراهيم بن محمد ومحمد بن معن بن عنبسة قالوا\nكان معاوية بن عبد الله بن جعفر قد عود ابن هرمة البر فجاءه يوما وقد ضاقت يده وأخذ خمسين دينارا بدين فرفع إليه مع جاريته رقعة فيها مديح له يسأله فيه أيضا برا فقال للجارية قولي له أيدينا ضيقة وما عندنا شيء إلا شيء أخذناه بكلفة فرجعت جاريته بذلك فأخذ الرقعة فكتب فيها\n(فإني ومدحك غير المصيب ... كالكلب ينبح ضوء القمر)\n(مدحتك أرجو لديك الثواب ... فكنت كعاصر جنب الحجر)\nبعث بالرقعة مع الجارية فدفعتها إلى معاوية فقال لها ويحك قد علم بها أحد قالت لا والله إنما دفعها من يده إلى يدي قال فخذي هذه الدنانير فادفعيها إليه فخرجت بها إليه فقال كلا أليس زعم أنه لا يدفع إلي شيئا أخبرني الحرمي بن أبي العلاء والطوسي قالا حدثنا الزبير قال حدثني عمي مصعب قال سمى عبد الله بن جعفر ابنه معاوية بمعاوية بن أبي سفيان قال وكان معاوية بن عبد الله بن جعفر صديقا ليزيد بن معاوية خاصة فسمى ابنه بيزيد بن معاوية","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":4,"spl":"ابن هرمة ومعاوية بن عبد الله بن جعفر","loc":2235},
{"id":"b137-6","bab":"الجزء 12","sec":"وصية عبد الله بن جعفر","page":"ج12 ص261","text":"قال الزبير وحدثني محمد بن إسحاق بن جعفر عن عمه محمد\nأن عبد الله بن جعفر لما حضرته الوفاة دعا ابنه معاوية فنزع شنفا كان في أذنه وأوصى إليه وفي ولده من هو أسن منه وقال له إني لم أزل أؤملك لها فلما توفي احتال بدين أبيه وخرج فطلب فيه حتى قضاه وقسم أموال أبيه بين ولده ولم يستأثر عليهم بدينار ولا درهم ولا غيرهما وأم عبد الله بن معاوية أم عون بنت عباس بن ربيعة بن الحارث بن عبد المطلب ويقال بنت عياش بن ربيعة وقد روى عباس عن النبي وكان معه يوم حنين وهو أحد من ثبت معه يومئذ وكان عبد الله من فتيان بني هاشم وجودائهم وشعرائهم ولم يكن محمود المذهب في دينه وكان يرمى بالزندقة ويستولي عليه من يعرف ويشهر أمره فيها وكان قد خرج بالكوفة في آخر أيام مروان بن محمد ثم انتقل عنها إلى نواحي الجبل ثم إلى خراسان فأخذه أبو مسلم فقتله هناك ويكنى عبد الله بن جعفر أبا معاوية وله يقول ابن هرمة\n(أحب مدحا أبا معاوية الماجد ... لا تلقه حصورا عييا)\n(بل كريما يرتاح للمجد بساما ... إذا هزه السؤال حييا)\n(إن لي عنده وإن رغم الأعداء حظا من نفسه وقفيا ... )\nفيا أثرة يقول إن لي عنده لأثرة على غيري وقال قوم آخرون القفي الكرامة\n(إن أمت تبق مدحتي وإخائي ... وثنائي من الحياة مليا)\n(يأخذ السبق بالتقدم في الجري ... إذا ما الندى انتحاه عليا)\n(ذو وفاء عند العدات وأوصاه ... أبوه ألا يزال وفيا)\n(فرعى عقدة الوصاة فأكرم ... بهما موصيا وهذا وصيا)\n(يا بن أسماء فاسق دلوي فقد أوردتها ... منهلا يثج رويا)\nيعني أمه أسماء وهي أم عون بنت العباس بن ربيعة بن الحارث بن عبد المطلب وأول هذه القصيدة\n(عاتب النفس والفؤاد الغويا ... في طلاب الصبا فلست صبيا)\nال يحيى بن علي فيما أجازه لنا أخبرني أبو أيوب المديني وأخبرنا وكيع عن هارون بن محمد بن عبد الملك عن حماد بن إسحاق عن أبيه قالا مدح ابن هرمة عبد الله بن جعفر بن أبي طالب فأتاه فوجد الناس بعضهم على بعض على بابه قال ابن هرمة ورآني بعض خدمه فعرفني فسألته عن الذي رأيتهم ببابه فقال عامتهم غرماء له فقلت ذاك شر واستؤذن لي عليه فقلت لم أعلم بهؤلاء الغرماء ببابك قال لا عليك أنشدني قلت أعيذك بالله واستحييت أن أنشد\nفأبى إلا أن أنشده قصيدتي التي أقول فيها\n(حللت محل القلب من آل هاشم ... فعشك مأوى بيضها المتفلق)\n(ولم تك بالمعزى إليها نصابه ... لصاقا ولا ذا المركب المتعلق)\n(فمن مثل عبد الله أو مثل جعفر ... ومثل أبيك الأريحي المرهق)\nفقال من هاهنا من الغرماء فقيل فلان وفلان فدعا باثنين منهم فسارهما وخرجا وقال لي اتبعهما قال فأعطياني مالا كثيرا قال يحيى ومن مختار مدحه فيه منها قوله\n(فإلا توات اليوم سلمى فربما ... شربنا بحوض اللهو غير المرنق)\n(فدعها فقد أعذرت في ذكر وصلها ... وأجريت فيها شأو غرب ومشرق)\n(ولكن لعبد الله فانطق بمدحة ... تجيرك من عسر الزمان المطبق)\n(أخ قلت للاذنين لما مدحته ... هلموا وساري الليل م الآن فاطرق)\n(شديد التأني في الأمور مجرب ... متى يعر أمر القوم يفر ويخلق)\n(ترى الخير يجري في أسرة وجهه ... كما لألأت في السيف جرية رونق)\n(كريم إذا ما شاء عد له أبا ... له نسب فوق السماك المحلق)\n(وأما لها فضل على كل حرة ... متى ما تسابق بابنها القوم تسبق)\nومما يغني فيه من قصيدة ابن هرمة اليائية التي مدح بها ابن معاوية قوله\n\n(عجبت جارتي لشيب علاني ... عمرك الله هل رأيت بديا)\n(إنما يعذر الوليد ولا يعذر ... من عاش في الزمان عتيا)\nنى فيهما فليح رملا بالبنصر من رواية عمرو بن بانة ومن رواية حبش فيهما لابن محرز خفيف ثقيل بالبنصر","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":5,"spl":"وصية عبد الله بن جعفر","song":1,"loc":2236,"partial":1},
{"id":"b137-7","bab":"الجزء 12","sec":"خروج عبد الله بن معاوية على بني أمية","page":"ج12 ص265","text":"حدثنا بالسبب في خروجه أحمد بن عبيد الله بن عمار قال حدثنا علي بن محمد النوفلي عن أبيه وعمه عيسى قال ابن عمار وأخبرنا أيضا ببعض خبره أحمد بن أبي خيثمة عن مصعب الزبيري قال ابن عمار وأخبرني أحمد بن الحارث الخراز عن المدائني عن أبي اليقظان وشهاب بن عبد الله وغيرهما قال ابن عمار وحدثني به سليمان بن أبي شيخ عمن ذكره قال أبو الفرج الأصبهاني ونسخت أنا أيضا بعض خبره من كتاب محمد بن علي بن حمزة عن المدائني وغيره فجمعت معاني ما ذكروه في ذلك كراهة الإطالة أن عبد الله بن معاوية قدم الكوفة زائرا لعبد الله بن عمر بن عبد العزيز ومستميحا له فتزوج بالكوفة بنت الشرقي بن عبد المؤمن بن شبث بن ربعي الرياحي فلما وقعت العصبية أخرجه أهل الكوفة على بني أمية وقالوا له أخرج فأنت أحق بهذا الأمر من غيرك واجتمعت له جماعة فلم يشعر به عبد الله بن عمر إلا وقد خرج عليه قال ابن عمار في خبره إنه إنما خرج في أيام\nيزيد بن الوليد ظهر بالكوفة ودعا إلى الرضا من آل محمد ولبس الصوف وأظهر سيما الخير فاجتمع إليه وبايعه بعض أهل الكوفة ولم يبايعه كلهم وقالوا ما فينا بقية قد قتل جمهورنا مع أهل هذا البيت وأشاروا عليه بقصد فارس وبلاد المشرق فقبل ذلك وجمع جموعا من النواحي وخرج معه عبد الله بن العباس التميمي قال محمد بن علي بن حمزة عن سليمان بن أبي شيخ عن محمدد بن الحكم عن عوانة إن ابن معاوية قبل قصده المشرق ظهر بالكوفة ودعا إلى نفسه وعلى الكوفة يومئذ عامل ليزيد الناقص يقال له عبد الله بن عمر فخرج إلى ظهر الكوفة مما يلي الحرة فقاتل ابن معاوية قتالا شديدا قال محمد بن علي بن حمزة عن المدائني عن عامر بن حفص وأخبرني به ابن عمار عن أحمد بن الحارث عن المدائني أن ابن عمر هذا دس إلى رجل من أصحاب ابن معاوية من وعده عنه مواعيد على أن ينهزم عنه وينهزم الناس بهزيمته فبلغ ذلك ابن معاوية فذكره لأصحابه وقال إذا انهزم ابن حمزة فلا يهولنكم فلما التقوا انهزم ابن حمزة وانهزم الناس معه فلم يبق غير ابن معاوية فجعل يقاتل وحده ويقول\n(تفرقت الظباء على خداش ... فما يدري خداش ما يصيد)\nم ولى وجهه منهزما فنجا وجعل يجمع من الأطراف والنواحي من أجابه حتى\nصار في عدة فغلب على ماه الكوفة وماه البصرة وهمذان وقم والري وقومس وأصبهان وفارس وأقام هو بأصبهان قال وكان الذي أخذ له البيعة بفارس محارب بن موسى مولى بني يشكر فدخل دار الإمارة بنعل ورداء واجتمع الناس إليه فأخذهم بالبيعة فقالوا علام نبايع فقال على ما أحببتم وكرهتم فبايعوا على ذلك وكتب عبد الله بن معاوية فيما ذكر محمد بن علي بن حمزة عن عبد الله بن محمد بن إسماعيل الجعفري عن أبيه عن عبد العزيز بن عمران عن محمد بن جعفر بن الوليد مولى أبي هريرة ومحرز بن جعفر أن عبد الله بن معاوية كتب إلى الأمصار يدعو إلى نفسه لا إلى الرضا من آل محمد قال واستعمل أخاه الحسن على إصطخر وأخاه يزيد على شيراز وأخاه عليا على كرمان وأخاه صالحا على قم ونواحيها وقصدته بنو هاشم جميعا منهم السفاح والمنصور وعيسى بن علي وقال ابن أبي خيثمة عن مصعب وقصده وجوه قريش من بني أمية وغيرهم فممن قصده من بني أمية سليمان بن هشام بن عبد الملك وعمر بن سهيل بن عبد العزيز بن مروان فمن أراد منهم عملا قلده ومن أراد منهم صلة وصله\nفلم يزل مقيما في هذه النواحي التي غلب عليها حتى ولي مروان بن محمد الذي يقال له مروان الحمار فوجه إليه عامر بن ضبارة في عسكر كثيف فسار إليه حتى إذا قرب من أصبهان ندب له ابن معاوية أصحابه وحضهم على الخروج إليه فلم يفعلوا ولا أجابوه فخرج على دهش هو وإخوته قاصدين لخراسان وقد ظهر أبو مسلم بها ونفى عنها نصر بن سيار فلما صار في بعض الطريق نزل على رجل من التناء ذي مروءة ونعمة وجاه فسأله معونته فقال له من أنت من ولد رسول الله أأنت إبراهيم الإمام الذي يدعى له بخراسان قال لا قال فلا حاجة لي في نصرتك فخرج إلى أبي مسلم وطمع في نصرته فأخذه أبو مسلم وحبسه عنده وجعل عليه عينا يرفع إليه أخباره فرفع إليه أنه يقول ليس في الأرض أحمق منكم يا أهل خراسان في طاعتكم هذا الرجل وتسليمكم إليه مقاليد أموركم من غير","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":6,"spl":"خروج عبد الله بن معاوية على بني أمية","loc":2237},
{"id":"b137-8","bab":"الجزء 12","sec":"خروج عبد الله بن معاوية على بني أمية","page":"ج12 ص265","text":"أن تراجعوه في شيء أو تسألوه عنه والله ما رضيت الملائكة الكرام من الله تعالى بهذا حتى راجعته في أمر آدم عليه السلام فقالت ( أتجعل فيها من يفسد فيها ويسفك الدماء\nحتى قال لهم ( إني أعلم ما لا تعلمون","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":7,"spl":"خروج عبد الله بن معاوية على بني أمية — كتابه إلى أبي مسلم وهو في حبسه","loc":2238},
{"id":"b137-9","bab":"الجزء 12","sec":"كتابه إلى أبي مسلم وهو في حبسه","page":"ج12 ص269","text":"ثم كتب إليه عبد الله بن معاوية رسالته المشهورة التي يقول فيها إلى أبي مسلم من الأسير في يديه بلا ذنب إليه ولا خلاف عليه أما بعد فإنك مستودع ودائع ومولي صنائع وإن الودائع مرعية وإن الصنائع عارية فاذكر القصاص واطلب الخلاص ونبه للفكر قلبك واتق الله ربك وآثر ما يلقاك غدا على ما لا يلقاك أبدا فإنك لاق ما أسلفت وغير لاق ما خلفت وفقك الله لما ينجيك وآتاك شكر ما يبليك قال فلما قرأ كتابه رمى به ثم قال قد أفسد علينا أصحابنا وأهل طاعتنا وهو محبوس في أيدينا فلو خرج وملك أمرنا لأهلكنا ثم أمضى تدبيره في قتله وقال آخرون بل دس إليه سما فمات منه ووجه برأسه إلى ابن ضبارة فحمله إلى مروان فأخبرني عمر بن عبد الله العتكي قال حدثنا عن عمر بن شبة قال حدثنا محمد بن يحيى أن عبد العزيز بن عمران حدثه عن عبد الله بن الربيع عن سعيد بن عمرو بن جعدة بن هبيرة أنه حضر مروان يوم الزاب وهو يقاتل عبد الله بن علي فسأل عنه فقيل له هو الشاب المصفر الذي كان يسب عبد الله بن معاوية يوم جيء برأسه إليك فقال والله لقد هممت بقتله مرارا كل ذلك يحال بيني وبينه ( وكان أمر الله قدرا مقدورا","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":7,"spl":"خروج عبد الله بن معاوية على بني أمية — كتابه إلى أبي مسلم وهو في حبسه","loc":2239},
{"id":"b137-10","bab":"الجزء 12","sec":"علاقته بالزنادقة","page":"ج12 ص270","text":"حدثني أحمد بن عبيد الله بن عمار قال حدثني النوفلي عن أبيه عن عمه قال كان عمارة بن حمزة يرمى بالزندقة فاستكتبه ابن معاوية وكان له نديم يعرف بمطيع بن إياس وكان زنديقا مأبونا وكان له نديم آخر يعرف بالبقلي وإنما سمي بذلك لأنه كان يقول الإنسان كالبقلة فإذا مات لم يرجع فقتله المنصور لما أفضت الخلافة إليه فكان هؤلاء الثلاثة خاصته وكان له صاحب شرطة يقال له قيس وكان دهريا لا يؤمن بالله معروفا بذلك فكان يعس بالليل فلا يلقاه أحد إلا قتله فدخل يوما على ابن معاوية فلما رآه قال\n(إن قيسا وإن تقنع شيبا ... لخبيث الهوى على شمطه)\n(ابن تسعين منظرا ومشيبا ... وابن عشر يعد في سقطه)\nوأقبل على مطيع فقال أجز أنت فقال\n(وله شرطة إذا جنه الليل فعوذوا بالله من شرطه ... )\nال ابن عمار أخبرني أحمد بن الحارث الخراز عن المدائني عن أبي اليقظان وشباب بن عبد الله وغيرهما قال ابن عمار وحدثني به سليمان بن أبي شيخ عمن ذكره أن ابن معاوية كان يغضب على الرجل فيأمر بضربه بالسياط وهو يتحدث ويتغافل عنه حتى يموت تحت السياط وأنه فعل ذلك برجل فجعل يستغيث فلا يلتفت إليه فناداه يا زنديق أنت الذي تزعم أنه يوحى إليك فلم يلتفت إليه وضربه حتى مات حدثني أحمد بن عبيد الله بن عمار قال حدثني النوفلي عن أبيه عن عمه عيسى قال كان ابن معاوية أقسى خلق الله قلبا فغضب على غلام له وأنا جالس عنده في غرفة بأصبهان فأمر بأن يرمى به منها إلى أسفل ففعل ذلك به فتعلق بدرابزين كان على الغرفة فأمر بقطع يده التي أمسكه بها فقطعت ومر الغلام يهوي حتى بلغ إلى الأرض فمات وكان مع هذه الأحوال من ظرفاء بني هاشم وشعرائهم وهو الذي يقول\n(ألا تزع القلب عن جهله ... وعما تؤنب من أجله)\n(فأبدل بعد الصبا حلمه ... وأقصر ذو العذل عن عذله)\n(فلا تركبن الصنيع الذي ... تلوم أخاك على مثله)\n(ولا يعجبنك قول امرىء ... يخالف ما قال في فعله)\n(ولا تتبع الطرف ما لا تنال ... ولكن سل الله من فضله)\n(فكم من مقل ينال الغنى ... ويحمد في رزقه كله)\nنشدنا هذا الشعر له ابن عمار عن أحمد بن أبي خيثمة عن يحيى بن معين وذكر محمد بن علي العلوي عن أحمد بن ابي خيثمة أن يحيى بن معين أنشده أيضا لعبد الله بن معاوية\n(إذا افتقرت نفسي قصرت افتقارها ... عليها فلم يظهر لها أبدا فقرى)\n(وإن تلقني في الدهر مندوحة الغنى ... يكن لأخلائي التوسع في اليسر)\n(فلا العسر يزري بي إذا هو نالني ... ولا اليسر يوما إن ظفرت به فخري)\nهذا الشعر الذي غني به أعني قوله\n(وعين الرضا عن كل عيب كليلة ... )\nقوله ابن معاوية للحسين بن عبد الله بن عبيد الله بن العباس بن عبد المطلب وكان الحسين أيضا سيء المذهب مطعونا في دينه أخبرني أحمد بن عبد العزيز الجوهري قال حدثني علي بن محمد بن سليمان النوفلي قال حدثني إبراهيم بن يزيد الخشاب قال كان ابن معاوية صديقا للحسين بن عبد الله بن عبيد الله بن العباس بن عبد المطلب وكان حسين هذا وعبد الله بن معاوية يرميان بالزندقة فقال الناس إنما تصافيا على ذلك ثم دخل بينهما شيء من الأشياء فتهاجرا من أجله فقال عبد الله بن معاوية\n(وإن حسينا كان شيئا ملففا ... فمحصه التكشيف حتى بدا ليا)\n(وعين الرضا عن كل عيب كليلة ... ولكن عين السخط تبدي المساويا)\n(وأنت أخي ما لم تكن لي حاجة ... فإن عرضت أيقنت أن لا أخا ليا)\nله في الحسين أشعار كلها معاتبات فمنها ما أخبرني به أحمد بن محمد بن سعيد بن عقدة قال أنشدني يحيى بن الحسن لعبد الله بن معاوية يقوله في الحسين بن عبد الله بن عبيد الله بن العباس بن عبد المطلب\n(قل لذي الود والصفاء حسين ... اقدر الود بيننا قدره)\n(ليس للدابغ المقرظ بد ... من عتاب الأديم ذي البشره)\nال وقال له أيضا\n(إن ابن عمك وابن أمك ... معلم شاكي السلاح)\n(يقص العدو وليس يرضى ... حين يبطش بالجناح)\n(لا تحسبن أذى ابن عم ... ك شرب ألبان اللقاح)\n(بل كالشجا تحت اللهاة ... إذا يسوغ بالقراح)\n(فانظر لنفسك من يجيبك ... تحت أطراف الرماح)\n(من لا يزال يسوءه ... بالغيب أن يلحاك لاحي)","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":8,"spl":"علاقته بالزنادقة","loc":2240,"partialRef":{"sid":"b136-7","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b137-11","bab":"الجزء 12","sec":"عبد الله بن معاوية وجده عبد الحميد","page":"ج12 ص274","text":"أخبرني الحرمي والطوسي قالا حدثنا يحيى بن الحسن قال حدثنا الزبير وحدثني أحمد بن محمد بن سعيد قال حدثنا الزبير قال حدثني محمد بن يحيى أن عبد الله بن معاوية مر بجده عبد الحميد في مزرعته بصرام وقد عطش فاستسقاه فخاض له سويق لوز فسقاه إياه فقال عبد الله بن معاوية\n(شربت طبرزذا بغريض مزن ... كذوب الثلج خالطه الرضاب)\nال يحيى قال الزبير الرضاب ماء المسك ورضاب كل شيء ماؤه فقال عبد الحميد بن عبيد الله يجيب عبد الله بن معاوية على قوله\n(ما إن ماؤنا بغريض مزن ... ولكن الملاح بكم عذاب)\n(وما إن بالطبرزذ طاب لكن ... بمسك لا به طاب الشراب)\n(وأنت إذا وطئت تراب أرض ... يطيب إذا مشيت بها التراب)\n(لأن نداك يطفي المحل عنها ... وتحييها أياديك الرطاب)\nال هارون بن محمد بن عبد الملك الزيات حدثني حماد بن إسحاق عن أبيه عن جده إبراهيم الموصلي قال بينا نحن عند الرشيد أنا وابن جامع وعمرو الغزال إذ قال صاحب الستارة\nلأبن جامع تغن في شعر عبد الله بن معاوية بن عبد الله بن جعفر قال ولم يكن ابن جامع يغني في شيء منه وفطنت لما أراد من شعره وكنت قد تقدمت فيه فأرتج على ابن جامع فلما رأيت ما حل به اندفعت فغنيت\n(يهيم بجمل وما إن يرى ... له من سبيل إلى جمله)\n(كأن لم يكن عاشق قبله ... وقد عشق الناس من قبله)\n(فمنهم من الحب أودى به ... ومنهم من اشفى على قتله)\nإذا يد قد رفعت الستارة فنظر إلي وقال أحسنت والله أعد فأعدته فقال أحسنت حتى فعل ذلك ثلاث مرات ثم قال لصاحب الستارة كلاما لم أفهمه فدعا صاحب الستارة غلاما فكلمه فمر الغلام يسعى فإذا بدرة دنانير قد جاءت يحملها فراش فوضعت تحت فخذي اليسرى وقيل لي اجعلها تكأتك قال فلما انصرفنا قال لي ابن جامع هل كنت وضعت لهذا الشعر غناء قبل هذا الوقت فقلت ما شعر قيل في الجاهلية ولا الإسلام يدخل فيه الغناء إلا وقد وضعت له لحنا خوفا من أن ينزل بي ما نزل بك فلما كان المجلس الثاني وحضرنا قال صاحب الستارة يابن جامع تغن في شعر عبد الله بن معاوية فوقع في مثل الذي وقع فيه بالأمس قال إبراهيم فلما رأيت ما حل به اندفعت فغنيت\n(يا قوم كيف سواغ عيش ليس تؤمن فاجعاته ... )\n(ليست تزال مطلة ... تغدو عليك منغصاته)\n(الموت هول داخل ... يوما على كره أناته)\n(لا بد للحذر النفور ... من ان تقنصه رماته)\n(قد أمنح الود الخليل ... بغير ما شيء رزاته)\n(وله أقيم قناة ودي ... ما استقامت لي قناته)\nال فأومأ إلي صاحب الستارة أن أمسك ووضع يده على عينه كأنه يوميء إلي أنه يبكي قال فأمسكت ثم انصرفنا فقال لي ابن جامع ما صب أمير المؤمنين على ابن جعفر قلت صبه الله عليه لبدرة الدنانير التي أخذتها قال ثم حضر بعد ذلك فلما اطمأن بنا مجلسنا قال ابن جامع بكلام خفي اللهم أنسه ذكر ابن جعفر قال فقلت اللهم لا تستجب فقال صاحب الستارة يابن جامع تغن في شعر عبد الله بن معاوية قال فقال ابن جامع لو كان عندهم في عبد الله بن معاوية خير لطار مع أبيه ولم يقبل على الشعر قال إبراهيم فسمعنا ضحكة من وراء الستارة قال إبراهيم فاندفعت أغني في شعره\n(سلا ربة الخدر ما شأنها ... ومن أيما شأننا تعجب)\n(فلست بأول من فاته ... على إربه بعض ما يطلب)\n(وكائن تعرض من خاطب ... فزوج غير التي يخطب)\n(وأنكحها بعده غيره ... وكانت له قبله تحجب)\n(وكنا حديثا صفيين لا ... نخاف الوشاة وما سببوا)\n(فإن شطت الدار عنا بها ... فبانت وفي الناس مستعتب)\n(وأصبح صدع الذي بيننا ... كصدع الزجاجة ما يشعب)\n(وكالدر ليست له رجعة ... إلى الضرع من بعدما يحلب)","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":9,"spl":"عبد الله بن معاوية وجده عبد الحميد","song":2,"loc":2241,"partial":1},
{"id":"b137-12","bab":"الجزء 12","sec":"عبد الله بن معاوية وجده عبد الحميد","page":"ج12 ص274","text":"غنى في البيتين الأولين إبراهيم الموصلي خفيف ثقيل الأول بالوسطى من رواية أحمد بن يحيى المكي ووجدتهما في بعض الكتب خفيف رمل غير منسوب قال فقال لي صاحب الستارة أعد فأعدته فأحسب أمير المؤمنين نظر إلى ابن جامع كاسف البال فأمر له بمثل الذي أمر لي بالأمس وجاؤوني ببدرة دنانير فوضعت تحت فخذي اليسرى أيضا وكان ابن جامع فيه حسد ما يستتر منه فلما انصرفنا قال اللهم أرحنا من ابن جعفر هذا فما أشد بغضي له لقد بغض إلى جده فقلت ويحك تدري ما تقول قال فمن يدري ما يقول إذا لوددت أني لم أر إقباله عليك وعلى غنائك في شعر هذا البغيض ابن البغيضة وأني تصدقت بها يعني البدرة وهذا الصوت الأخير يقول شعره عبد الله بن معاوية في زوجته أم زيد بنت زيد بن علي بن الحسين عليهما السلام أخبرني الطوسي والحرمي قالا حدثنا الزبير بن بكار عن عمه قال خطب عبد الله بن معاوية ربيحة بنت محمد بن عبد الله بن علي بن عبد\nالله بن جعفر وخطبها بكار بن عبد الملك بن مروان فتزوجت بكارا فشمتت بعبد الله امرأته أم زيد بنت زيد بن علي بن الحسين فقال في ذلك\n(سلا ربة الخدر ما شأنها ... ومن أيما شأننا تعجب)\nقال ابن أبي خيثمة في خبره عن مصعب قالت له والله ما شمت ولكني نفست عليك فقال لها لا جرم والله لا سؤتك أبدا ما حييت\n(طاف الخيال من ام شيبة فاعترى ... والقوم من سنة نشاوى بالكرى)\n(طافت بخوص كالقسي وفتية ... هجعوا قليلا بعد ما ملوا السرى)\nلشعر لأبي وجزة السعدي والغناء لإسحاق ثقيل أول بالبنصر","topic":"خبر عبد الله بن معاوية ونسبه","topicNo":137,"sp":10,"spl":"عبد الله بن معاوية وجده عبد الحميد","song":1,"loc":2242},
{"id":"b138-1","bab":"الجزء 12","sec":"أخبار أبي وجزة ونسبه","page":"ج12 ص279","text":"اسمه يزيد بن عبيد فيما ذكره أصحاب الحديث وذكر بعض النسابين أن اسمه يزيد بن أبي عبيد وأنه كان له أخ يقال له عبيد وانتسب إلى بني سعد بن بكر بن هوازن لولائه فيهم وأصله من سليم من بني ضبيس بن هلال بن قدم بن ظفر بن الحارث بن بهثة بن سليم ولكنه لحق أباه وهو صبي سباء في الجاهلية فبيع بسوق ذي المجاز فابتاعه رجل من بني سعد واستعبده فلما كبر استعدى عمر رضي الله عنه وأعلمه قصته فقال له إنه لا سباء على عربي وهذا الرجل قد امتن عليك فإن شئت فأقم عنده وإن شئت فالحق بقومك فأقام في بني سعد وانتسب إليهم هو وولده وبنو سعد أظآر رسول الله كان مسترضعا فيهم عند امرأة يقال لها حليمة فلم يزل فيهم عليه السلام حتى يفع ثم أخذه جده عبد المطلب\nمنهم فرده إلى مكة وجاءته حليمة بعد الهجرة فأكرمها وبرها وبسط لها رداءه فجلست عليه وبنو سعد تفتخر بذلك على سائر هوازن وحقيق بكل مكرمة وفخر من اتصل منه رسول الله بأدنى سبب أو وسيلة أخبرني بخبره الذي حكيت جملا منه في نسبه وولائه أبو دلف هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل العتكي قال حدثنا محمد بن سلام الجمحي عن يونس وأخبرني أبو خليفة فيما كتب به إلي عن محمد بن سلام عن يونس وأخبرني به عمي عن الكراني عن الرياشي عن محمد بن سلام عن يونس وأخبرني علي بن سليمان الأخفش عن أبي سعيد السكري عن يعقوب بن السكيت قالوا جميعا سوى يعقوب كان عبيد أبو أبي وجزة السعدي عبد بيع بسوق ذي المجاز في الجاهلية فابتاعه وهيب بن خالد بن عامر بن عمير بن ملان بن ناصرة بن فصية بن نصر بن سعد بن بكر بن هوازن فأقام عنده زمانا يرعى إبله ثم إن عبيدا ضرب ضرع ناقة لمولاه فأدماه فلطم وجهه فخرج عبيد إلى عمر بن الخطاب رضي الله عنه مستعديا فلم قدم عليه قال يا أمير المؤمنين أنا رجل من بني سليم ثم من بني ظفر أصابني سباء في الجاهلية كما يصيب العرب بعضها من بعض وأنا معروف النسب وقد كان رجل من بني سعد ابتاعني فأساء إلي وضرب\nوجهي وقد بلغني أنه لا سباء في الإسلام ولا رق على عربي في الإسلام فما فرغ من كلامه حتى أتى مولاه عمر بن الخطاب رضي الله تعالى عنه على أثره فقال يا أمير المؤمنين هذا غلام ابتعته بذي المجاز وقد كان يقوم في مالي فأساء فضربته ضربة والله ما أعلمني ضربته غيرها قط وإن الرجل ليضرب ابنه أشد منها فكيف بعبده وأنا أشهدك أنه حر لوجه الله تعالى فقال عمر لعبيد قد امتن عليك هذا الرجل وقطع عنك مؤنة البينة فإن أحببت فأقم معه فله عليك منة وإن أحببت فالحق بقومك فأقام مع السعدي وانتسب إلى بني سعد بن بكر بن هوازن وتزوج زينب بنت عرفطة المزنية فولدت له أبا وجزة وأخاه وقال يعقوب وأخاه عبيدا وذكر أن أباهما كان يقال له أبو عبيد ووافق من ذكرت روايته في سائر الخبر فلما بلغ ابناه طلباه بأن يلحق بأصله وينتمي إلى قومه من بني سليم فقال لا أفعل ولا ألحق بهم فيعيروني كل يوم ويدفعوني وأترك قوما يكرموني ويشرفوني فوالله لئن ذهبت إلى بني ظفر لا أرعى طمة ولا أرد جمة إلا قالوا لي يا عبد بني سعد قال وطمة جبل لهم فقال أبو وجزة في ذلك\n(أنمى فأعقل في ضبيس معقلا ... ضخما مناكبه تميم الهادي)\n(والعقد في ملان غير مزلج ... بقوى متينات الحبال شداد)","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":0,"spl":"أخبار أبي وجزة ونسبه","loc":2243},
{"id":"b138-2","bab":"الجزء 12","sec":"كان ابو وجزة من التابعين","page":"ج12 ص281","text":"وكان أبو وجزة من التابعين وقد روى عن جماعة من أصحاب رسول الله ورأى عمر بن الخطاب رضي الله عنه ولم يسند إليه حديثا ولكنه حدث عن ابيه عنه بحديث الاستسقاء ونقل عنه جماعة من الرواة\nأخبرني محمد بن خلف وكيع وعمي قالا حدثنا عبد الله بن شبيب قال حدثني إبراهيم بن حمزة قال حدثني موسى بن شيبة قال سمعت أبا وجزة السعدي يقول قال رسول الله ليس شعر حسان بن ثابت ولا كعب بن مالك ولا عبد الله بن رواحة شعرا ولكنه حكمة فأما خبر الاستسقاء الذي رواه عن أبيه عن عمر فإن الحسن بن علي أخبرنا به قال حدثنا محمد بن القاسم قال حدثني عبد الله بن عمرو عن علي بن الصباح عن هشام بن محمد عن أبيه عن أبي وجزة السعدي عن أبيه قال شهدت عمر بن الخطاب رضي الله تعالى عنه وقد خرج بالناس ليستسقي عام الرمادة فقام وقام الناس خلفه فجعل يستغفر الله رافعا صوته لا يزيد على ذلك فقلت في نفسي ما له لا يأخذ فيما جاء له ولم أعلم أن الاستغفار هو الاستسقاء فما برحنا حتى نشأت سحابة وأظلتنا فسقي\nالناس وقلدتنا السماء قلدا كل خمس عشرة ليلة حتى رأيت الأرينة تأكلها صغار الإبل من وراء حقاق العرفط وأخبرني أبو الحسن الأسدي وهاشم بن محمد الخزاعي جميعا عن الرياشي عن الأصمعي عن عبد الله بن عمر العمري عن أبي وجزة السعدي عن أبيه وذكر الحديث مثله وأخبرني به إبراهيم بن أيوب عن عبد الله بن مسلم بن قتيبة واللفظ متقارب وزاد الرياشي في خبره فقلت لأبي وجزة ما حقاق العرفط قال نبات سنتين وثلاث وزاد ابن قتيبة في خبره عليهم قال ومات أبو وجزة سنة ثلاثين ومائة وهو أحد من شبب بعجوز حيث يقول\n(يأيها الرجل الموكل بالصبا ... فيم ابن سبعين المعمر من دد)\n(حتام أنت موكل بقديمة ... أمست تجدد كاليماني الجيد)\n(زان الجلال كمالها ورسا بها ... عقل وفاضلة وشيمة سيد)\n(ضنت بنائلها عليك وأنتما ... غران في طلب الشباب الأغيد)\n(فالآن ترجو أن تثيبك نائلا ... هيهات نائلها مكان الفرقد)\nأخبرنا الحرمي بن أبي العلاء والطوسي جميعا قالا حدثنا الزبير بن بكار\nقال حدثني محمد بن الحسن المخزومي عن عبد الرحمن بن عبد الله عن أبيه عن أبي وجزة السعدي عن أبيه قال استسقى عمر بن الخطاب رضي الله تعالى عنه فلما وقف على المنبر أخذ في الاستغفار فقلت ما أراه يعمل في حاجته ثم قال في آخر كلامه اللهم إني قد عجزت وما عندك أوسع لهم ثم أخذ بيد العباس رضي الله تعالى عنه ثم قال وهذا عم نبيك ونحن نتوسل إليك به فلما أراد عمر رضي الله تعالى عنه أن ينزل قلب رداءه ثم نزل فتراءى الناس طرة في مغرب الشمس فقالوا ما هذا وما رأينا قبل ذلك قزعة سحاب أربع سنين قال ثم سمعنا الرعد ثم انتشر ثم اضطرب فكان المطر يقلدنا قلدا في كل خمس عشرة ليلة حتى رأيت الأرينة خارجة من حقاق العرفط تأكلها صغار الإبل","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":1,"spl":"كان ابو وجزة من التابعين","loc":2244},
{"id":"b138-3","bab":"الجزء 12","sec":"أبو وجزة يمدح بني الزبير","page":"ج12 ص284","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عمي عن جدي قال خرج أبو وجزة السعدي وأبو زيد الأسلمي يريدان المدينة وقد امتدح أبو وجزة آل الزبير وامتدح أبو زيد إبراهيم بن هشام المخزومي فقال له أبو\nوجزة هل لك في أن أشاركك فيما أصيب من آل الزبير وتشاركني فيما تصيب من إبراهيم فقال كلا والله لرجائي في الأمير أعظم من رجائك في آل الزبير فقدما المدينة فأتى أبو زيد دار إبراهيم فدخلها وأنشد الشعر وصاح وجلب فقال إبراهيم لبعض أصحابه اخرج إلى هذا الأعرابي الجلف فاضربه وأخرجه فأخرج وضرب وأتى أبو وجزة أصحابه فمدحهم وأنشدهم فكتبوا له إلى مال لهم بالفرع أن يعطى منه ستين وسقا من التمر فقال أبو وجزة يمدحهم\n(راحت قلوصي رواحا وهي حامدة ... آل الزبير ولم تعدل بهم أحدا)\n(راحت بستين وسقا في حقيبتها ... ما حملت حملها الأدنى ولا السددا)\n(ذاك القرى لا كأقوام عهدتهم ... يقرون ضيفهم الملوية الجددا)\nعني السياط قال أبو الفرج الأصفهاني قول أبي وجزة\n(راحت بستين وسقا في حقيبتها ... )\nنها حملت ستين وسقا ولا تحمل ناقة ذلك ولا تطيقه ولا نصفه وإنما عنى أنه انصرف عنهم وقد كتبوا له بستين وسقا فركب ناقته والكتاب معه بذلك قد حملته في حقيبتها فكأنها حاملة بالكتاب ستين وسقا لأ أنها أطاقت حمل ذلك وهذا بيت معنى يسأل عنه\nوقال يعقوب بن السكيت فيما حكيناه من روايته التي ذكرها الأخفش لنا عن السكري في شعر ابي وجزة وأخباره كان أبو وجزة قد جاور مزينة وانتجع بلادهم لصهره فيهم فنزل على عمرو بن زياد بن سهيل بن مكدم بن عقيل بن وهب بن عمرو بن مرة بن مازن بن عوف بن ثور بن هذمة بن لاطم بن عثمان فأحسن عمرو جواره وأكرم مثواه فقال أبو وجزة يمدحه\n(لمن دمنة بالنعف عاف صعيدها ... تغير باقيها ومح جديدها)\n(لسعدة من عام الهزيمة إذ بنا ... تصاف وإذ لما يرعنا صدودها)\n(وإذ هي أما نفسها فأريبه ... للهو وأما عن صبا فتذودها)\n(تصيد ألباب الرجال بدلها ... وشميتها وحشية لا نصيدها)\n(كباسقة الوسمي ساعة أسبلت ... تلألأ فيها البرق وابيض جيدها)\nلباسقة التي فضلت غيرها من الغمام وطالت عليه قال الله تبارك وتعالى ( والنخل باسقات كبكر تراني فرقدين بقفرة ... من الرمل أو فيحان لم يعس عودها لعمرو الندى عمرو بن آل مكدم ... كثير عليات الأمور جليدها فتى بين مسروج وآل مكدم ... وعمرو فتى عثمان طرا وسيدها\n(حليم إذا ما الجهل أفرط ذا النهى ... على أمره حامي الحصاة شديدها)\n(وما زال ينحو فعل من كان قبله ... من ابنائه يجني العلا ويفيدها)\n(فكم من خليل قد وصلت وطارق ... وقربت من أدماء وار قصيدها)\n(وذي كربة فرجت كربة همه ... وقد ظل مستدا عليه وصيدها)","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":2,"spl":"أبو وجزة يمدح بني الزبير","loc":2245,"partial":1},
{"id":"b138-4","bab":"الجزء 12","sec":"أبو وجزة يتزوج زينب بنت عرفطة","page":"ج12 ص287","text":"أخبرني عمي قال حدثني العنزي قال حدثنا محمد بن معاوية عن يعقوب بن سلام بن عبد الله بن أبي مسروج قال تزوج أبو وجزة السعدي زينب بنت عرفطة بن سهل بن مكدم المزنية فولدت له عبيدا وكانت قد عنست وكان أبو وجزة يبغضها وإنما أقام عليها لشرفها فقال لها ذات يوم\n(أعطى عبيدا وعبيد مقنع ... من عرمس محزمها جلنفع)\n(ذات عساس ما تكاد تشبع ... تجتلد الصحن وما إن تبضع)\n(تمر في الدار ولا تورع ... كأنها فيهم شجاع أقرع)\nقالت زينب أم وجزة تجيبه\n(أعطى عبيدا من شييخ ذي عجر ... لا حسن الوجه ولا سمح يسر)\n(يشرب عس المذق في اليوم الخصر ... كأنما يقذف في ذات السعر)\n(تقاذف السيل من الشعب المضر ... )\nال وقال أبو وجزة لابنه عبيد\n(يا راكب العنس كمرادة العلم ... أصلحك الله وأدنى ورحم)\n(إن أنت أبلغت وأديت الكلم ... عنى عبيد بن يزيد لو علم)\n(قد علم الأقوام أن سينتقم ... منك ومن أم تلقتك وعم)\n(رب يجازى السيئات من ظلم ... أنذرتك الشدة من ليث أضم)\n(عاد أبي شبلين فرفار لحم ... فارجع إلى أمك تفرشك ونم)\n(إلى عجوز رأسها مثل الإرم ... واطعم فإن الله رزاق الطعم)\nقال عبيد لأبيه\n(دعها أبا وجزة واقعد في الغنم ... فسوف يكفيك غلام كالزلم)\n(مشمر يرقل في نعل خذم ... وفي قفاه لقمة من اللقم)\n(قد ولهت ألافها غير لمم ... حتى تناهت في قفا جعد أحم)\nال يعقوب وقال أبو المزاحم يهجو أبا وجزة ويعيره بنسبه\n(دعتك سليم عبدها فأجبتها ... وسعد وما ندري لأيهما العبد)\nفأجابه أبو وجزة فقال\n(أعيرتموني أن دعتني أخاهم ... سليم وأعطتني بأيمانها سعد)\n(فكنت وسيطا في سليم معاقدا ... لسعد وسعد ما يحل لها عقد)","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":3,"spl":"أبو وجزة يتزوج زينب بنت عرفطة — أبو وجزة يمدح عبد الله بن الحسن وإخوته","loc":2246,"partial":1},
{"id":"b138-5","bab":"الجزء 12","sec":"أبو وجزة يمدح عبد الله بن الحسن وإخوته","page":"ج12 ص289","text":"أخبرني أبو جعفر أحمد بن محمد بن نصر الضبعي إجازة قال حدثنا محمد بن مسعود الزرقي عن مسعود بن المفضل مولى آل حسن بن حسن قال قدم أبو وجزة السعدي على عبد الله بن الحسن وإخوته سويقة وقد\nأصابت قومه سنة مجدبة فأنشده قوله يمدحه\n(أثني على ابني رسول الله أفضل ما ... أثنى به أحد يوما على أحد)\n(السيدين الكريمي كل منصرف ... من والدين ومن صهر ومن ولد)\n(ذرية بعضها من بعضها عمرت ... في اصل مجد رضيع السمك والعمد)\n(ما ذا بنى لهم من صالح حسن ... وحسن وعلي وابتنوا لغد)\n(فكرم الله ذاك البيت تكرمة ... تبقى وتخلد فيه آخر الأبد)\n(هم السدى والندى ما في قناتهم ... إذا تعوجت العيدان من أود)\n(مهذبون هجان أمهاتهم ... إذا نسبن زلال البارق البرد)\n(بين الفواطم ماذا ثم من كرم ... إلى العواتك مجد غير منتقد)\n(ما ينتهي المجد إلا في بني حسن ... وما لهم دونه من دار ملتحد)\nال فأمر له عبد الله بن الحسن وحسن وإبراهيم بمائة وخمسين دينارا وأوقروا له رواحله برا وتمرا وكسوه ثوبين ثوبين\nأخبرني إسماعيل بن يونس الشيعي قال حدثنا عمر بن شبة قال حدثني أبو غسان والمدائني جميعا أن عبد الملك بن يزيد بن محمد بن عطية السعدي كان قد ندب لقتال أبي حمزة الأزدي الشاري لما جاء إلى المدينة فغلب عليها قال وبعث إليه مروان بن محمد بمال ففرقه فيمن خف معه من قومه فكان فيمن فرض له منهم أبو وجزة وابناه فخرج معترضا للعسكر على فرس وهو يرتجز ويقول\n(قل لأبي حمزة هيد هيد ... جئناك بالعادية الصنديد)\n(بالبطل القرم أبي الوليد ... فارس قيس نجدها المعدود)\n(في خيل قيس والكماة الصيد ... كالسيف قد سل من الغمود)\n(محض هجان ماجد الجدود ... في الفرع من قيس وفي العمود)\n(فدى لعبد الملك الحميد ... ما لي من الطارف والتليد)\n(يوم تنادى الخيل بالصعيد ... كأنه في جنن الحديد)\n(سيد مدل عز كل سيد ... )\nال وسار ابن عطية في قومه ولحقت به جيوش أهل الشأم فلقي أبا حمزة في اثني عشرة ألفا فقاتله يوما إلى الليل حتى أصاب صناديد عسكره فنادوه يابن عطية إن الله جل وعز قد جعل الليل سكنا فاسكنوا حتى\nنسكن فأبى وقاتلهم حتى قتلهم جميعا","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":3,"spl":"أبو وجزة يتزوج زينب بنت عرفطة — أبو وجزة يمدح عبد الله بن الحسن وإخوته","loc":2247,"partial":1},
{"id":"b138-6","bab":"الجزء 12","sec":"أبو وجزة مداح ابن عطية","page":"ج12 ص292","text":"قال وكان أبو وجزة منقطعا إلى ابن عطية يقوم بقوت عياله وكسوته ويعطيه ويفضل عليه وكان أبو وجزة مداحا له وفيه يقول\n(حن الفؤاد إلى سعدى ولم تثب ... فيهم الكثير من التحنان والطرب)\n(قالت سعاد أرى من شيبه عجبا ... مهلا سعاد فما في الشيب من عجب)\nنى في هذين البيتين إسحاق خفيف ثقيل أول بالوسطى في مجراها من كتابه\n(إما تريني كساني الدهر شيبته ... فإن ما مر منه عنك لم يغب)\n(سقيا لسعدى على شيب ألم بنا ... وقبل ذلك حين الرأس لم يشب)\n(كأن ريقتها بعد الكرى اغتبقت ... صوب الثريا بماء الكرم من حلب)\nهي قصيدة طويلة يقول فيها\n(أهدي قلاصا عناجيجا أضر بها ... نص الوجيف وتقحيم من العقب)\n(يقصدن سيد قيس وابن سيدها ... والفارس العد منها غير ذي الكذب)\n(محمد وأبوه وابنه صنعوا ... له صنائع من مجد ومن حسب)\n(إني مدحتهم لما رأيت لهم ... فضلا على غيرهم من سائر العرب)\n(إلا تثبني به لا يجزني أحد ... ومن يثيب إذا ما أنت لم تثب)\nالأبيات التي ذكرت فيها الغناء المذكور معه أمر أبي وجزة من قصيدة له مدح بها أيضا عبد الملك بن عطية هذا ومما يختار منها قوله\n(حتى إذا هجدوا ألم خيالها ... سرا ألا بلمامه كان المنى)\n(طرقت بريا روضة من عالج ... وسمية عذبت وبيتها الندى)\n(يا أم شيبة أي ساعة مطرق ... نبهتنا أين المدينة من بدا)\n(إني متى أقض اللبانة أجتهد ... عنق العتاق الناجيات على الوجى)\n(حتى أزورك إن تيسر طائري ... وسلمت من ريب الحوادث والردى)\nفيها يقول\n(فلأ مدحن بني عطية كلهم ... مدحا يوافي في المواسم والقرى)\n(الأكرمين أوائلا وأواخرا ... والأحلمين إذا تخولجت الحبا)\n(والمانعين من الهضيمة جارهم ... والجامعين الراقعين لما وهى)\n(والعاطفين على الضريك بفضلهم ... والسابقين إلى المكارم من سعى)\nهي قصيدة طويلة يمدح فيها بني عطية جميعا ويذكر وقعتهم بأبي حمزة الخارجي ولا معنى للإطالة بذكرها أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي قال كان أبو وجزة السعدي منقطعا إلى آل الزبير وكان عبد الله بن عروة بن الزبير خاصة يفضل عليه ويقوم بأمره فبلغه أن أبا وجزة أتى عبد الله بن الحسن ابن الحسن بن علي بن ابي طالب عليهم السلام فمدحه فوصله فاطرحه ابن عروة وأمسك يده عنه فسأل عن سبب غضبه فأخبره به الأصم بن أرطاة فلم يزل أبو وجزة يمدح آل الزبير ولا يرجع له عبد الله بن عروة إلى ما كان عليه ولا يرضى عنه حتى قال فيه\n(آل الزبير بنو حرة ... مروا بالسيوف صدورا خنافا)\n(سل الجرد عنهم وأيامها ... إذا امتعطوا المرهفات الخفافا)\nمتعطوا سلوا ومنه ذئب أمعط منسل من شعره\n(يموتون والقتل داء لهم ... ويصلون يوم السياف السيافا)\n(إذا فرج القتل عن عيصهم ... أبى ذلك العيص إلا التفافا)\n(مطاعيم تحمد أبياتهم ... إذا قنع الشاهقات الطخافا)\n(وأجبن من صافر كلبهم ... إذا قرعته حصاة أضافا)\nلما أنشد ابن عروة هذه الأبيات رضي عنه وعاد له إلى ما كان عليه","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":4,"spl":"أبو وجزة مداح ابن عطية — من المائة المختارة","song":1,"loc":2248},
{"id":"b138-7","bab":"الجزء 12","sec":"من المائة المختارة","page":"ج12 ص295","text":"(ألا هل أسير المالكية مطلق ... فقد كاد لو لم يعفه الله يغلق)\n(فلا هو مقتول ففي القتل راحة ... ولا منعم يوما عليه فمعتق)\nلشعر لعقيل بن علفة البيت الأول منه والثاني لشبيب بن البرصاء والغناء لأحمد بن المكي خفيف ثقيل بالوسطى من كتابه فيه لدقاق رمل بالوسطى من كتاب عمرو بن بانة وأوله\n(سلا أم عمرو فيم أضحى أسيرها ... يفادى الأسارى حوله وهو موثق)\nبعده البيت الثاني وهو\n(فلا هو مقتول ففي القتل راحة ... ولا منعم يوما عليه فمعتق)\nالبيتان على هذه الرواية لشبيب بن البرصاء","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":4,"spl":"أبو وجزة مداح ابن عطية — من المائة المختارة","loc":2249},
{"id":"b138-8","bab":"الجزء 12","sec":"أخبار عقيل بن علفة","page":"ج12 ص296","text":"عقيل بن علفة بن الحارث بن معاوية بن ضباب بن جابر بن يربوع بن غيظ بن مرة بن سعد بن ذبيان بن بغيض بن الريث بن غطفان بن سعد بن قيس عيلان بن مضر ويكنى أبا العملس وأبا الجرباء وأم عقيل بن علفة العوراء وهي عمرة بنت الحارث بن عوف بن ابي حارثة بن مرة بن نشبة بن غيظ بن مرة وأمها زينب بنت حصن بن حذيفة هذا قول خالد بن كلثوم والمدائني وقال ابن الأعرابي كانت عمرة العوراء أم عقيل ابن علفة والبرصاء أم شبيب بن البرصاء أختين وهما ابنتا الحارث بن عوف واسم البرصاء قرصافة أمها بنت نجبة بن ربيعة بن رياح بن مالك بن شمخ وعقيل شاعر مجيد مقل من شعراء الدولة الأموية وكان أعرج جافيا شديد الهوج والعجرفية والبذخ بنسبه في بني مرة لا يرى أن له كفئا وهو في بيت شرف في قومه من كلا طرفيه وكانت قريش ترغب في مصاهرته\nتزوج إليه خلفاؤها وأشرافها منهم يزيد بن عبد الملك تزوج ابنته الجرباء وكانت قبله عند ابن عم لعقيل يقال له مطيع بن قطعة بن الحارث بن معاوية وولدت ليزيد بنيا درج وتزوج بنته عمرة سلمة بن عبد الله بن المغيرة فولدت له يعقوب بن سلمة وكان من أشراف قريش وجودائها وتزوج أم عمرو بنته ثلاثة نفر من بني الحكم بن أبي العاص يحيى والحارث وخالد أخبرني محمد بن جعفر النحوي قال حدثنا أحمد بن يحيى ثعلب عن ابن الأعرابي عن المفضل قال دخل عقيل بن علفة على عثمان بن حيان وهو يومئذ على المدينة فقال له عثمان زوجني ابنتك فقال أبكرة من إبلي تعني فقال له عثمان ويلك أمجنون أنت قال أي شيء قلت لي قال قلت لك زوجني ابنتك فقال أفعل إن كنت عنيت بكرة من إبلي فأمر به فوجئت عنقه فخرج وهو يقول\n(كنا بني غيظ الرجال فأصبحت ... بنو مالك غيظا وصرنا كمالك)\n(لحى الله دهرا ذعذع المال كله ... وسود أشباه الإماء العوارك)","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":5,"spl":"أخبار عقيل بن علفة","loc":2250},
{"id":"b138-9","bab":"الجزء 12","sec":"عقيل يكتف خاطب ابنته ويلقيه في قرية النمل","page":"ج12 ص298","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال كان لعقيل بن علفة جار من بني سلامان بن سعد فخطب إليه ابنته فغضب عقيل وأخذ السلاماني فكتفه ودهن استه بشحم وألقاه في قرية النمل فأكلن خصييه حتى ورم جسده ثم حله وقال يخطب إلي عبد الملك فأرده وتجترىء أنت علي قال ثم أجدبت مراعي بني مرة فانتجع عقيل أرض جذام وقربهم عذرة قال عقيل فجاءني هني مثل البعرة فخطب إلي ابنتي أم جعفر فخرجت إلى أكمة قريبة من الحي فجعلت أنبح كما ينبح الكلب ثم تحملت وخرجت فاتبعني جمع من حن بطن من عذرة فقالوا اختر إن شئت حبسناك وإن شئت حدرناك وبعيرة من رأس الجبل فإن سبقتها خلينا عنك فأرسلوا بعيرة فسبقتها\nفخلوا سبيلي فقلت لهم ما طمعتم بهذا من أحد قالوا أردنا أن نضع منك حيث رغبت عنا فقلت فيهم\n(لقد هزئت حن بنا وتلاعبت ... وما لعبت حن بذي حسب قبلي)\n(رويدا بني حن تشيحوا وتأمنوا ... وتنتشر الأنعام في بلد سهل)\nالله لأموتن قبل أن أضع كرائمي إلا في الأكفاء أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد بن الضحاك عن أبيه قال وجدت في كتاب بخط الضحاك قال خرج عقيل بن علفة وابناه علفة وجثامة وابنته الجرباء حتى أتوا بنتا له ناكحا في بني مروان بالشام فآمت ثم إنهم قفلوا بها حتى كانوا ببعض الطريق فقال عقيل بن علفة\n(قضت وطرا من دير سعد وطالما ... على عرض ناطحنه بالجماجم)\n(إذا هبطت أرضا يموت غرابها ... بها عطشا أعطينهم بالخزائم)\nم قال أنفذ يا علفة فقال علفة\n(فأصبحن بالموماة يحملن فتية ... نشاوى من الإدلاج ميل العمائم)\n(إذا علم غادرنه بتنوفة ... تذارعن بالأيدي لآخر طاسم)\nثم قال أنفذي يا جرباء فقالت وأنا آمنة قال نعم فقالت\n(كأن الكرى سقاهم صرخدية ... عقارا تمشى في المطا والقوائم)\nقال عقيل شربتها ورب الكعبة لولا الأمان لضربت بالسيف تحت قرطك أما وجدت من الكلام غير هذا فقال جثامة وهل أساءت إنما أجازت وليس غيري وغيرك فرماه عقيل بسهم فأصاب ساقه وأنفذ السهم ساقه والرحل ثم شد على الجرباء فعقر ناقتها ثم حملها على ناقة جثامة وتركه عقيرا مع ناقة الجرباء ثم قال لولا أن تسبني بنو مرة ما ذقت الحياة ثم خرج متوجها إلى أهله وقال لئن أخبرت أهلك بشأن جثامة أو قلت لهم إنه أصابه غير الطاعون لأقتلنك فلما قدموا على أهل أبير وهم بنو القين ندم عقيل على فعله بجثامة فقال لهم هل لكم في جزور انكسرت قالوا نعم قال فالزموا أثر هذه الراحلة حتى تجدوا الجزور فخرج القوم حتى انتهوا إلى جثامة فوجدوه قد أنزفه الدم فاحتملوه وتقسموا الجزور وأنزلوه عليهم وعالجوه حتى برأ وألحقوه بقومه ونسخت هذا الخبر من كتاب أبي عبد الله اليزيدي بخطه ولم أجده ذكر سماعه إياه من أحد قال قرىء على علي بن محمد المدائني عن الطرماح بن خليل بن أبرد فذكر مثل ما ذكره الزبير منه وزاد فيه أن القوم احتملوا جثامة ليلحقوه بقومه حتى إذا كانوا قريبا منهم تغنى جثامة\n(أيعذر لاهينا ويلحين في الصبا ... وما هن والفتيان إلا شقائق)\nفقال له القوم إنما أفلت من الجراحة التي جرحك أبوك آنفا وقد عاودت ما يكرهه فأمسك عن هذا ونحوه إذا لقيته لا يلحقك منه شر وعر فقال إنما هي خطرة خطرت والراكب إذا سار تغنى","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":6,"spl":"عقيل يكتف خاطب ابنته ويلقيه في قرية النمل","loc":2251},
{"id":"b138-10","bab":"الجزء 12","sec":"عقل يصاب بالقولنج","page":"ج12 ص301","text":"أخبرني الحسن بن علي قال حدثني أحمد بن سعيد الدمشقي قال حدثنا الزبير بن بكار قال حدثني عبد الله بن إبراهيم الجمحي قال قدم عقيل بن علفة المدينة فنزل على ابن بنته يعقوب بن سلمة المخزومي فمرض وأصابه القولنج فنعتت له الحقنة فأبى وقدم ابنه عليه فبلغه ذلك فقال\n(لقد سرني والله وقاك شرها ... نجاؤك منها حين جاء يقودها)\n(كفى خزية ألا تزال مجبيا ... على شكوة توكى وفي استك عودها)\nخبرني عبيد الله بن محمد الرازي قال حدثنا أحمد بن الحارث الخراز قال حدثنا علي بن محمد عن زيد بن عياش التغلبي والربيع بن ثميل قالا غدا عقيل بن علفة على أفراس له عند بيوته فأطلقها ثم رجع فإذا بنوه مع بناته وأمهم مجتمعون فشد على عملس فحاد عنه وتغنى علفة فقال\n(قفي يابنة المري أسألك ما الذي ... تريدين فيما كنت منيتنا قبل)\n(نخبرك إن لم تنجزي الوعد أننا ... ذوا خلة لم يبق بينهما وصل)\n(فإن شئت كان الصرم ما هبت الصبا ... وإن شئت لا يفنى التكارم والبذل)\nقال عقيل يابن اللخناء متى منتك نفسك هذا وشد عليه بالسيف وكان عملس أخاه لأمه فحال بينه وبينه فشد على عملس بالسيف وترك علفة لا يلتفت إليه فرماه بسهم فأصاب ركبته فسقط عقيل وجعل يتمعك في دمه ويقول\n(إن بني سربلوني بالدم ... من يلق أبطال الرجال يكلم)\n(ومن يكن ذا أود يقوم ... شنشنة أعرفها من أخزم)\nال المدائني شنشنة أعرفها من أخزم مثل ضربه وأخزم فحل كان لرجل من العرب وكان منجبا فضرب في إبل رجل آخر ولم يعلم صاحبه فرأى بعد ذلك من نسله جملا فقال شنشنة أعرفها من أخزم","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":7,"spl":"عقل يصاب بالقولنج","loc":2252},
{"id":"b138-11","bab":"الجزء 12","sec":"عمر بن عبد العزيز يعاتبه في شأن بناته","page":"ج12 ص302","text":"أخبرني محمد بن خلف وكيع قال حدثني سليمان المدائني قال حدثني\nمصعب بن عبد الله قال قال عمر بن عبد العزيز لعقيل بن علفة إنك تخرج إلى أقاصي البلاد وتدع بناتك في الصحراء لا كاليء لهن والناس ينسبونك إلى الغيرة وتأبى أن تزوجهن إلا الأكفاء قال إني أستعين عليهن بخلتين تكلآنهن وأستغني عن سواهما قال وما هما قال العري والجوع نسخت من كتاب محمد بن العباس اليزيدي قال خالد بن كلثوم لما رمى عملس بن عقيل أباه فأصاب ركبته غضب وأقسم ألا يساكن بنيه فاحتمل وخرج إلى الشام فلما استوى على ناقته المسماة بأطلال بكت ابنته جرباء وحنت ناقته فقال\n(ألم تريا أطلال حنت وشاقها ... تفرقنا يوم الحبيب على ظهر)\n(وأسبل من جرباء دمع كأنه ... جمان أضاع السلك أجرته في سطر)\n(لعمرك إني يوم أغدو عملسا ... لكالمتربي حتفه وهو لا يدري)\n(وإني لأسقيه غبوقي وإنني ... لغرثان منهوك الذراعين والنحر)\nال ومضى علفة أيضا فافترض بالشام وكتب إلى أبيه\n(ألا أبلغا عني عقيلا رسالة ... فإنك من حرب علي كريم)\n(أما تذكر الأيام إذ أنت واحد ... وإذ كل ذي قربى إليك ذميم)\n(وإذ لا يقيك الناس شيئا تخافه ... بأنفسهم إلا الذين تضيم)\n(تناول شأو الأبعدين ولم يقم ... لشأوك بين الأقربين أديم)\n(فأما إذا عضت بك الحرب عضة ... فإنك معطوف عليك رحيم)\n(وأما إذا آنست أمنا ورخوة ... فإنك للقربى ألد ظلوم)\nلما سمع عقيل هذه الأبيات رضي عنه وبعث إليه فقدم عليه أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي عن محمد بن سلام قال حدثني ابن جعدبة قال عاتب عمر بن عبد العزيز رجلا من قريش أمه أخت عقيل بن علفة فقال له قبحك الله أشبهت خالك في الجفاء فبلغت عقيلا فجاء حتى دخل على عمر فقال له ماوجدت لابن عمك شيئا تعيره به إلا خؤولتي فقبح الله شركما خالا فقال له صخير بن أبي الجهم العدوي وأمه قرشية آمين يا أمير المؤمنين فقبح الله شركما خالا وأنا معكما أيضا فقال له عمر إنك لأعرابي جلف جاف أما لو كنت تقدمت إليك لأدبتك والله لا أراك تقرأ من كتاب الله شيئا قال بلى إني لأقرأ قال فاقرأ فقرأ ( إذا زلزلت الأرض زلزالها\nحتى بلغ إلى آخرها فقرأ فمن يعمل مثقال ذرة شرا يره ومن يعمل مثقال ذرة خيرا يره فقال له عمر ألم أقل لك إنك لا تحسن أن تقرأ قال أو لم أقرأ قال لا لأن الله جل وعز قدم الخير وأنك قدمت الشر فقال عقيل\n(خذا بطن هرشى أو قفاها فإنه ... كلا جانبي هرشى لهن طريق)\nجعل القوم يضحكون من عجرفيته وروى هذا الخبر علي بن محمد المدائني فذكر انه كان بين عمر بن\nعبد العزيز وبين يعقوب بن سلمة وأخيه عبد الله كلام فأغلظ يعقوب لعمر في الكلام فقال له عمر اسكت فإنك ابن أعرابية جافية فقال عقيل لعمر لعن الله شر الثلاثة مني ومنك ومنه فغضب عمر فقال له صخير بن ابي الجهم آمين فهو والله أيها الأمير شر الثلاثة فقال عمر والله إني لأراك لو سألته عن آية من كتاب الله ما قرأها فقال بلى والله إني لقاريء لآية وآيات فقال فاقرأ فقرأ إنا بعثنا نوحا إلى قومه فقال له عمر قد أعلمتك أنك لا تحسن ليس هكذا قال الله قال فكيف قال قال ( إنا أرسلنا نوحا\nفقال وما الفرق بين أرسلنا وبعثنا\n(خذ أنف هرشى أو قفاها فإنه ... كلا جانبي هرشى لهن طريق)","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":8,"spl":"عمر بن عبد العزيز يعاتبه في شأن بناته","loc":2253},
{"id":"b138-12","bab":"الجزء 12","sec":"عقيل يضحك الناس في المسجد","page":"ج12 ص305","text":"أخبرني عبيد الله بن أحمد الرازي قال حدثنا أحمد بن الحارث الخراز قال حدثني علي بن محمد المدائني عن عبد الله بن أسلم القرشي قال قدم عقيل بن علفة المدينة فدخل المسجد وعليه خفان غليظان فجعل يضرب برجليه فضحكوا منه فقال ما يضحككم فقال له يحيى بن الحكم وكانت ابنة عقيل تحته يضحكون من خفيك وضربك برجليك وشدة جفائك قال لا ولكن يضحكون من إمارتك فإنها أعجب من خفي فجعل يحيى يضحك أخبرني محمد بن الحسن بن دريد قال حدثنا عبد الرحمن ابن أخي الأصمعي قال حدثني عمي عن عبد الله بن مصعب قاضي المدينة قال دخل عقيل بن علفة على يحيى بن الحكم وهو يومئذ أمير المدينة فقال له يحيى أنكح ابن خالي يعني ابن أوفى فلانة ابنتك فقال إن ابن\nخالك ليرضى مني بدون ذلك قال وما هو قال أن أكف عنه سنن الخيل إذا غشيت سوامه فقال يحيى لحرسيين بين يديه أخرجاه فأخرجاه فلما ولى قال أعيداه إلي فأعاداه فقال عقيل له مالك تكرني إكرار الناضح قال أما والله إني لأكرك أعرج جافيا فقال عقيل كذلك قلت\n(تعجبت إذ رأت رأسي تجلله ... من الروائع شيب ليس من كبر)\n(ومن أديم تولى بعد جدته ... والجفن يخلق فيه الصارم الذكر)\nقال له يحيى أنشدني قصيدتك هذه كلها قال ما انتهيت إلا إلى ما سمعت فقال أما والله إنك لتقول فتقصر فقال إنما يكفي من القلادة ما أحاط بالرقبة قال فأنكحني أنا إحدى بناتك قال أما أنت فنعم قال أما والله لأملأنك مالا وشرفا قال أما الشرف فقد حملت ركائبي منه ما أطاقت وكلفتها تجشم ما لم تطق ولكن عليك بهذا المال فإن فيه صلاح الأيم ورضا الأبي فزوجه ثم خرج فهداها إليه فلما قدمت عليه بعث إليها يحيى مولاة له لتنظر إليها فجاءتها فجعلت تغمز عضدها فرفعت يدها فدقت أنفها فرجعت إلى يحيى وقالت بعثتني إلى أعرابية مجنونة صنعت بي ما ترى فنهض إليها يحيى فقال لها مالك قالت ما أردت أن بعثت إلي أمة تنظر إلي ما أردت بما فعلت إلا أن يكون نظرك إلي قبل كل\nناظر فإن رأيت حسنا كنت قد سبقت إلى بهجته وإن رأيت قبيحا كنت أحق من ستره فسر بقولها وحظيت عنده وذكر المدائني هذا الخبر مثله إلا أنه قال فيه فإن كان ما تراه حسنا كنت أول من رآه وإن كان قبيحا كنت أول من واراه أخبرني ابن دريد قال حدثنا عبد الرحمن عن عمه قال خطب يزيد بن عبد الملك إلى عقيل بن علفة ابنته الجرباء فقال له عقيل قد زوجتكها على أن لا يزفها إليك أعلاجك أكون أنا الذي أجيء بها إليك قال ذلك لك فتزوجها ومكثوا ما شاء الله ثم دخل الحاجب على يزيد فقال له بالباب أعرابي على بعير معه امرأة في هودج قال أراه والله عقيلا قال فجاء بها حتى أناخ بعيرها على بابه ثم أخذ بيدها فأذعنت فدخل بها على الخليفة فقال له إن أنتما ودن بينكما فبارك الله لكما وإن كرهت شيئا فضع يدها في يدي كما وضعت يدها في يدك ثم برئت ذمتك فحملت الجرباء بغلام ففرح به يزيد ونحله وأعطاه ثم مات الصبي فورثت أمه منه الثلث ثم ماتت فورثها زوجها وأبوها فكتب إليه إن ابنك وابنتك هلكا وقد حسبت ميراثك منهما فوجدته عشرة آلاف دينار فهلم فاقبضه فقال إن مصيبتي بابني وابنتي تشغلني عن المال وطلبه فلا حاجة لي في ميراثهما وقد رأيت عندك فرسا سبقت عليه الناس فأعطنيه أجعله فحلا لخيلي وأبى أن يأخذ المال فبعث إليه يزيد بالفرس\nأخبرنا عبيد الله بن محمد قال حدثنا الخراز عن المدائني عن إسحاق بن يحيى قال رأيت رجلا من قريش يقول له عقيل بن علفة بالرفاء والبنين والطائر المحمود فقلت له يابن علفة إنه يكره أن يقال هذا فقال يابن أخي ما تريد إلى ما أحدث إن هذا قول أخوالك في الجاهلية إلى اليوم لا يعرفون غيره قال فحدثت به الزهري فقال إن عقيلا كان من أجهل الناس قال وإنما قال لإسحاق بن يحيى بن طلحة هذا قول أخوالك لأن أم يحيى بن طلحة مرية قال المدائني وحدثني علي بن بشر الجشمي قال قال الرميح خطب إلى عقيل رجل من بني مرة كثير المال يغمز في نسبه فقال\n(لعمري لئن زوجت من أجل ماله ... هجينا لقد حبت إلي الدراهم)\n(أأنكح عبدا بعد يحيى وخالد ... أولئك أكفائي الرجال الأكارم)\n(أبى لي أن أرضى الدنية أنني ... أمد عنانا لم تخنه الشكائم)","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":9,"spl":"عقيل يضحك الناس في المسجد","loc":2254},
{"id":"b138-13","bab":"الجزء 12","sec":"عقيل يضحك الناس في المسجد","page":"ج12 ص305","text":"سخت من كتاب محمد بن العباس اليزيدي بخطه يأثره عن خالد بن كلثوم بغير إسناد متصل بينهما أن رجلا من بني مرة يقال له داود أقبل على ناقة له فخطب إلى عقيل\nابن علفة بعض بناته فنظر إليه عقيل وإن السيف لا يناله فطعن ناقته بالرمح فسقطت وصرعته وشد عليه عقيل فهرب وثار عقيل إلى ناقته فنحرها وأطعمها قومه وقال\n(ألم تقل يا صاحب القلوص ... داود ذا الساج وذا القميص)\n(كانت عليه الأرض حيص بيص ... حتى يلف عيصه بعيصي)\n(وكنت بالشبان ذا تقميص ... )\nقال داود فيه من أبيات\n(أراه فتى جعل الحلال ببيته ... حراما ويقري الضيف عضبا مهندا)\nقال المدائني حدثني جوشن بن يزيد قال لما تزوج عقيل بن علفة زوجته الأنمارية وقد كبر فرت منه فلقيها جحاف وأحد بني قتال بن يربوع فحملها إلى عامل فدك واصبح عقيل معها فقال الأمير لعقيل ما لهذه تستعدي عليك يا أبا الجرباء فقال عقيل كل ذكري وذهب ذفري وتغايب نفري فقال خذ بيدها فأخذها وانصرف فولدت له بعد ذلك علفة الأصغر","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":10,"spl":"عقيل يضحك الناس في المسجد — بنو سلامان يأسرونه ويطلقه بنو القين","loc":2255,"partial":1},
{"id":"b138-14","bab":"الجزء 12","sec":"شعره يحرض بني سهم على بني جوشن","page":"ج12 ص310","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ عن أبي عبيدة قال لما نشبت الحرب بين بني جوشن وبين بني سهم بن مرة رهط عقيل بن علفة المري وهو من بني غيظ بن مرة بن سهم بن مرة إخوتهم فاقتتلوا في أمر يهودي خمار كان جارا لهم فقتلته بنو جوشن من غطفان وكانوا متقاربي المنازل وكان عقيل بن علفة بالشأم غائبا عنهم فكتب إلى بني سهم يحرضهم\n(فإما هلكت ولم آتكم ... فأبلغ أماثل سهم رسولا)\n(بأن التي سامكم قومكم ... لقد جعلوها عليكم عدولا)\n(هوان الحياة وضيم الممات ... وكلا أراه طعاما وبيلا)\n(فإن لم يكن غير إحداهما ... فسيروا إلى الموت سيرا جميلا)\n(ولا تقعدوا وبكم منة ... كفى بالحوادث للمرء غولا)\nال فلما وردت الأبيات عليهم تكفل بالحرب الحصين بن الحمام المري أحد بني سهم وقال إلي كتب وبي نوه خاطب أماثل سهم وأنا من أماثلهم فأبلى في تلك الحروب بلاء شديدا وقال الحصين بن الحمام في ذلك من قصيدة طويلة له\n(يطأن من القتلى ومن قصد القنا ... خبارا فما ينهضن إلا تقحما)\n(عليهن فتيان كساهم محرق ... وكان إذا يكسو أجاد وأكرما)\n(صفائح بصرى أخلصتها قيونها ... ومطردا من نسج داود محكما)\n(تأخرت أستبقي الحياة فلم أجد ... لنفسي حياة مثل أن أتقدما)\nقال المدائني قال جراح بن عصام بن بجير عدت بنو جعفر بن كلاب على جار لعقيل فأطردت إبله وضربوه فغدا عقيل على جار لهم فضربه وأخذ إبله فأطردها فلم يردها حتى ردوا إبل جاره وقال في ذلك\n(إن يشرق الكلبي فيكم بريقه ... بني جعفر يعجل لجاركم القتل)\n(فلا تحسبوا الإسلام غير بعدكم ... رماح مواليكم فذاك بكم جهل)\n(بني جعفر إن ترجعوا الحرب بيننا ... ندنكم كما كنا ندينكم قبل)\n(بدأتم بجاري فانثنيت بجاركم ... وما منهما إلا له عندنا حبل)\nوذكر المدائني أيضا","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":10,"spl":"عقيل يضحك الناس في المسجد — بنو سلامان يأسرونه ويطلقه بنو القين","loc":2256},
{"id":"b138-15","bab":"الجزء 12","sec":"بنو سلامان يأسرونه ويطلقه بنو القين","page":"ج12 ص311","text":"أن عقيلا كان وحده في إبله فمر به ناس من بني سلامان فأسروه ومروا به في طريقه علىناس من بني القين فانتزعوه منهم وخلوا سبيله فقال عقيل في ذلك\n(أسعد هذيم إن سعدا أباكم ... أبي لا يوافي غاية القين من كلب)\n(وجاء هذيم والركاب مناخة ... فقيل تأخر يا هذيم على العجب)\n(فقال هذيم إن في العجب مركبي ... ومركب آبائي وفي عجبها حسبي)\nقال وسعد هذيم هم عذرة وسلامان والحارث وضبة","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":10,"spl":"عقيل يضحك الناس في المسجد — بنو سلامان يأسرونه ويطلقه بنو القين","loc":2257},
{"id":"b138-16","bab":"الجزء 12","sec":"عقيل يرثي ابنه علفة","page":"ج12 ص312","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أبو مسلم عن المدائني عن عبد الحميد بن أيوب بن محمد بن عميلة قال مات علفة بن عقيل الأكبر بالشأم فنعاه مضرس بن سوادة لعقيل بأرض الجناب فلم يصدقه وقال\n(قبح الآله ولا أقبح غيره ... ثفر الحمار مضرس بن سواد)\n(تنعى امرأ لم يعل أمك مثله ... كالسيف بين خضارم أنجاد)\nم تحقق الخبر بعد ذلك فقال يرثيه\n(لعمري لقد جاءت قوافل خبرت ... بأمر من الدنيا علي ثقيل)\n(وقالوا ألا تبكي لمصرع فارس ... نعته جنود الشام غير ضئيل)\n(فأقسمت لا أبكي على هلك هالك ... أصاب سبيل الله خير سبيل)\n(كأن المنايا تبتغي في خيارنا ... لها نسبا أو تهتدي بدليل)\n(تحل المنايا حيث شاءت فإنها ... محللة بعد الفتى ابن عقيل)\n(فتى كان مولاه يحل بربوة ... محل الموالي بعده بمسيل)\nخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة قال كان عقيل بن علفة قد أطرد بنيه فتفرقوا في البلاد وبقي وحده ثم إن رجلا من بني صرمة يقال له بجيل وكان كثير المال والماشية حطم بيوت عقيل بماشيته ولم يكن قبل ذلك أحد يقرب من بيوت عقيل إلا لقي شرا فطردت صافنة أمة له الماشية فضربها بجيل بعصا كانت معه فشجها فخرج إليه عقيل وحده وقد هرم يومئذ وكبرت سنه فزجره فضربه بجيل بعصاه واحتقره فجعل عقيل يصيح يا علفة يا عملس يا فلان يا فلان بأسماء أولاده مستغيثا بهم وهو يحسبهم لهرمه أنهم معه فقال له أرطاة بن سهية\n(أكلت بنيك أكل الضب حتى ... وجدت مرارة الكلأ الوبيل)\n(ولو كان الألى غابوا شهودا ... منعت فناء بيتك من بجيل)\nوبلغ خبر عقيل ابنه العملس وهو بالشام فأقبل إلى أبيه حتى نزل إليه ثم عمد إلى بجيل فضربه ضربا مبرحا وعقر عدة من إبله وأوثقه بجبل وجاء\nبه يقوده حتى ألقاه بين يدي أبيه ثم ركب راحلته وعاد من وقته إلى الشام لم يطعم لأبيه طعاما ولم يشرب شرابا أخبرني عمي قال حدثنا الكراني قال حدثنا ابن عائشة قال نزل أعرابي على المقشعر بن عقيل بن علفة المري فشربا حتى سكرا وناما فانتبه الأعرابي مروعا في الليل وهو يهذي فقال له المقشعر مالك قال هذا ملك الموت يقبض روحي فوثب ابن عقيل فقال لا والله ولا كرامة ولا نعمة عين له أيقبض روحك وأنت ضيفي وجاري فقال بأبي أنتم وأمي طال والله ما منعتم الضيم وتلفف ونام تمت أخبار عقيل ولله الحمد والمنة قد مضت أخبار عقيل فيما تقدم من الكتاب ونذكرها هنا أخبار شبيب ابن البرصاء ونسبه لأن المغنين خلطوا بعض شعره ببعض شعر عقيل في الغناء الماضي ذكره ونعيدها هنا من الغناء ما شعره لشبيب خاصة وهو","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":11,"spl":"عقيل يرثي ابنه علفة — من المائة المختارة","song":1,"loc":2258},
{"id":"b138-17","bab":"الجزء 12","sec":"من المائة المختارة","page":"ج12 ص314","text":"(سلا أم عمرو فيم أضحى أسيرها ... تفادى الأسارى حوله وهو موثق)\n(فلا هو مقتول ففي القتل راحة ... ولا منعم يوما عليه فمطلق)\nيروى\n(ولا هو ممنون عليه فمطلق ... )\nالشعر لشبيب بن البرصاء والغناء لدقاق جارية يحيى بن الربيع رمل بالوسطى عن عمرو وذكر حبش أن فيه رملا آخر لطويس","topic":"أخبار أبي وجزة ونسبه","topicNo":138,"sp":11,"spl":"عقيل يرثي ابنه علفة — من المائة المختارة","loc":2259,"partial":1},
{"id":"b139-1","bab":"الجزء 12","sec":"أخبار شبيب بن البرصاء ونسبه","page":"ج12 ص316","text":"هو شبيب بن يزيد بن جمرة وقيل جبر بن عوف بن أبي حارثة بن مرة بن نشبة بن غيظ بن مرة بن سعد بن ذبيان والبرصاء أمه واسمها قرصافة بنت الحارث بن عوف بن أبي حارثة وهو ابن خالة عقيل بن علفة وأم عقيل عمرة بنت الحارث بن عوف ولقبت قرصافة البرصاء لبياضها لا لأنها كان بها برص وشبيب شاعر فصيح إسلامي من شعراء الدولة الأموية بدوي لم يحضر إلا وافدا أو منتجعا وكان يهاجي عقيل بن علفة ويعاديه لشراسة كانت في عقيل وشر عظيم وكلاهما كان شريفا سيدا في قومه في بيت شرفهم وسؤددهم وكان شبيب أعور أصاب عينة رجل من طيء في حرب كانت بينهم أخبرنا محمد بن الحسن بن دريد قال حدثنا أبو حاتم السجستاني عن أبي عبيدة قال\nدخل أرطاة بن سهية على عبد الملك بن مروان وكان قد هاجى شبيب بن البرصاء فأنشده قوله فيه\n(أبي كان خيرا من أبيك ولم يزل ... جنيبا لآبائي وأنت جنيب)\nقال له عبد الملك كذبت ثم أنشده البيت الآخر فقال\n(وما زلت خيرا منك مذ عض كارها ... برأسك عادي النجاد ركوب)\nقال له عبد الملك صدقت وكان أرطاة أفضل من شبيب نفسا وكان شبيب أفضل من أرطاة بيتا","topic":"أخبار شبيب بن البرصاء ونسبه","topicNo":139,"sp":0,"spl":"أخبار شبيب بن البرصاء ونسبه — شبيب يهجو عقيل بن علفة","loc":2260},
{"id":"b139-2","bab":"الجزء 12","sec":"شبيب يهجو عقيل بن علفة","page":"ج12 ص317","text":"أخبرني محمد بن يحيى الصولي قال حدثنا الحزنبل عن عمرو بن أبي عمرو عن أبيه قال فاخر عقيل بن علفة شبيب بن البرصاء فقال شبيب يهجوه ويعيره برجل من طيء كان يأتي أمه عمرة بنت الحارث يقال له حيان ويهجو غيظ بن مرة\n(ألسنا بفرع قد علمتم دعامة ... ورابية تنشق عنها سيولها)\n(وقد علمت سعد بن ذبيان أننا ... رحاها الذي تأوى إليها وجولها)\n(إذا لم نسسكم في الأمور ولم نكن ... لحرب عوان لاقح من يؤولها)\n(فلستم بأهدى في البلاد من التي ... تردد حيرى حين غاب دليلها)\n(دعت جل يربوع عقيلا لحادث ... من الأمر فاستخفى وأعيا عقيلها)\n(فقلت له هلا أجبت عشيرة ... لطارق ليل حين جاء رسولها)\n(وكائن لنا من ربوة لا تنالها ... مراقيك أو جرثومة لا تطولها)\n(فخرت بأيام لغيرك فخرها ... وغرتها معروفة وحجولها)\n(إذا الناس هابوا سوءة عمدت لها ... بنو جابر شبانها وكهولها)\n(فهلا بني سعد صبحت بغارة ... مسومة قد طار عنها نسيلها)\n(فتدرك وترا عند ألأم واتر ... وتدرك قتلى لم تتمم عقولها)\nقال أبو عمرو اجتمع عقيل بن علفة وشبيب بن البرصاء عند يحيى بن الحكم فتكلما في بعض الأمر فاستطال عقيل على شبيب بالصهر الذي بينه وبين بني مروان وكان زوج ثلاثا من بناته فيهم فقال شبيب يهجوه\n(ألا أبلغ أبا الحرباء عني ... بآيات التباغض والتقالي)\n(فلا تذكر أباك العبد وافخر ... بأم لست مكرمها وخال)\n(وهبها مهرة لقحت ببغل ... فكان جنينها شر البغال)\n(إذا طارت نفوسهم شعاعا ... حمين المحصنات لدى الحجال)\n(بطعن تعثر الأبطال منه ... وضرب حيث تقتنص العوالي)\n(أبى لي أن آبائي كرام ... بنوا لي فوق أشراف طوال)\n(بيوت المجد ثم نموت منها ... إلى علياء مشرفة القذال)\n(تزل حجارة الرامين عنها ... وتقصر دونها نبل النضال)\n(أبالحفاث شر الناس حيا ... وأعناق الأيور بني قتال)\n(رفعت مساميا لتنال مجدا ... فقد أصبحت منهم في سفال)\nال أبو عمرو بنو قتال إخوة بني يربوع رهط عقيل بن علفة وهم قوم فيهم جفاء قال أبو عمرو مات رجل منهم فلفه أخوه في عباءة له وقال أحدهما للآخر كيف تمله قال كما تحمله القربة فعمد إلى حبل فشد طرفه في عنقه وطرفه في ركبتيه وحمله على ظهره كما تحمل القربة فلما صار به إلى الموضع الذي يريد دفنه فيه حفر له حفيرة وألقاه فيها وهال عليه التراب حتى واراه فلما انصرفا قال له يا هناه أنسيت الحبل في عنق\nأخي ورجليه وسيبقى مكتوفا إلى يوم القيامة قال دعه يا هناه فإن يرد الله به خيرا يحلله","topic":"أخبار شبيب بن البرصاء ونسبه","topicNo":139,"sp":0,"spl":"أخبار شبيب بن البرصاء ونسبه — شبيب يهجو عقيل بن علفة","loc":2261},
{"id":"b139-3","bab":"الجزء 12","sec":"خطب بنت يزيد بن هاشم فرده ثم قبله فأبى","page":"ج12 ص320","text":"وقال أبو عمرو خطب شبيب بن البرصاء إلى يزيد بن هاشم بن حرملة المري ثم الصرمي ابنته فقال هي صغيرة فقال شبيب لا ولكنك تبغي أن تردني فقال له يزيد ما أردت ذاك ولكن أنظرني هذا العام فإذا انصرم فعلي أن أزوجك فرحل شبيب من عنده مغضبا فلما مضى قال ليزيد بعض أهله والله ما أفلحت خطب إليك شبيب سيد قومك فرددته قال هي صغيرة قال إن كانت صغيرة فستكبر عنده فبعث إليه يزيد ارجع فقد زوجتك فإني أكره أن ترجع إلى أهلك وقد رددتك فأبى شبيب أن يرجع وقال\n(لعمري لقد أشرفت يوم عنيزة ... على رغبة لو شد نفسي مريرها)\n(ولكن ضعف الأمر ألا تمره ... ولا خير في ذي مرة لا يغيرها)\n(تبين أدبار الأمور إذا مضت ... وتقبل أشباها عليك صدورها)\n(ترجي النفوس الشيء لا تستطيعه ... وتخشى من الأشياء ما لا يضيرها)\n(ألا إنما يكفي النفوس إذا اتقت ... تقى الله مما حاذرت فيجيرها)\n(ولا خير في العيدان إلا صلابها ... ولا ناهضات الطير إلا صقورها)\n(ومستنبح يدعو وقد حال دونه ... من الليل سجفا ظلمة وستورها)\n(رفعت له ناري فلما اهتدى لها ... زجرت كلابي أن يهر عقورها)\n(فبات وقد أسرى من الليل عقبة ... بليلة صدق غاب عنها شرورها)\n(وقد علم الأضياف أن قراهم ... شواء المتالي عندنا وقديرها)\n(إذا افتخرت سعد بن ذبيان لم يجد ... سوى ما بنينا ما يعد فخورها)\n(وإني لتراك الضغينة قد بدا ... ثراها من المولى فلا أستثيرها)\n(مخافة أن تجني علي وإنما ... يهيج كبيرات الأمور صغيرها)\n(إذا قيلت العوراء وليت سمعها ... سواي ولم أسمع بها ما دبيرها)\n(وحاجة نفس قد بلغت وحاجة ... تركت إذا ما النفس شح ضميرها)\n(حياء وصبرا في المواطن إنني ... حيي لدى أمثال تلك ستيرها)\n(وأحبس في الحق الكريمة إنما ... يقوم بحق النائبات صبورها)\n(أحابي بها الحي الذي لا تهمه ... وأحساب أموات تعد قبورها)\n(ألم تر أنا نور قوم وإنما ... يبين في الظلماء للناس نورها)\nخبرني محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني محمد بن عبد الله بن آدم بن جشم العبدي قال كانت بين بني كلب وقوم من قيس ديات فمشى القوم إلى أبناء أخواتهم\nمن بني أمية يستعينون بهم في الحمالة فحملها محمد بن مروان كلها عن الفريقين ثم تمثل بقول شبيب بن البرصاء\n(ولقد وقفت النفس عن حاجاتها ... والنفس حاضرة الشعاع تطلع)\n(وغرمت في الحسب الرفيع غرامة ... يعيا بها الحصر الشحيح ويظلع)\n(إني فتى حر لقدري عارف ... أعطي به وعليه مما أمنع)\nخبرني محمد بن خلف وكيع قال حدثنا إسحاق بن محمد النخعي قال حدثني الحرمازي قال نزل شبيب بن البرصاء وأرطاة بن زفر وعويف القوافي برجل من أشجع كثير المال يسمى علقمة فأتاهم بشربة لبن ممذوقة ولم يذبح لهم فلما رأوا ذلك منه قاموا إلى رواحلهم فركبوها ثم قالوا تعالوا حتى نهجو هذا الكلب فقال شبيب\n(أفي حدثان الدهر أم في قديمه ... تعلمت ألا تقري الضيف علقما)\nقال أرطاة\n(لبثنا طويلا ثم جاء بمذقة ... كماء السلا في جانب القعب أثلما)\nقال عويف\n(فلما رأينا أنه شر منزل ... رمينا بهن الليل حتى تخرما)\nخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل عن القحذمي قال غاب شبيب بن البرصاء عن أهله غيبة ثم عاد بعد مدة وقد مات جماعة من بني عمه فقال شبيب يرثيهم\n(تخرم الدهر إخواني وغادرني ... كما يغادر ثور الطارد الفئد)\n(إني لباق قليلا ثم تابعهم ... ووارد منهل القوم الذي وردوا)\nال أبو عمرو هاجى شبيب بن البرصاء رجلا من غني أو قال من باهلة فأعانه أرطاة بن سهية على شبيب فقال شبيب\n(لعمري لئن كانت سهية أوضعت ... بأرطاة في ركب الخيانة والغدر)\n(فما كان بالطرف العتيق فيشترى ... لفحلته ولا الجواد إذا يجري)\n(أتنصر مني معشرا لست منهم ... وغيرك أولى بالحياطة والنصر)\nيروى وقد كنت أولى بالحياطة وهو أجود\nوقال أبو عمرو استعدى رهط أرطأة بن سهية على شبيب بن البرصاء إلى عثمان بن حيان المري وقالوا له يعمنا بالهجاء ويشتم أعراضنا فأمر بإشخاصه إليه فأشخص ودخل إلى عثمان وقد أتي بثلاثة نفر لصوص قد أفسدوا في الأرض يقال لهم بهدل ومثغور وهيصم فقتل بهدلا وصلبه وقطع مثغورا والهيصم ثم أقبل على شبيب فقال كم تسب أعراض قومك وتستطيل عليهم أقسم قسما حقا لئن عاودت هجاءهم لأقطعن لسانك فقال شبيب","topic":"أخبار شبيب بن البرصاء ونسبه","topicNo":139,"sp":1,"spl":"خطب بنت يزيد بن هاشم فرده ثم قبله فأبى","loc":2262},
{"id":"b139-4","bab":"الجزء 12","sec":"خطب بنت يزيد بن هاشم فرده ثم قبله فأبى","page":"ج12 ص320","text":"(سجنت لساني يابن حيان بعدما ... تولى شبابي إن عقدك محكم)\n(وعيدك أبقى من لساني قذاذة ... هيوبا وصمتا بعد لا يتكلم)\n(رأيتك تحلولي إذا شئت لامرىء ... ومرا مرارا فيه صاب وعلقم)\n(وكل طريد هالك متحير ... كما هلك الحيران والليل مظلم)\n(أصبت رجالا بالذنوب فأصبحوا ... كما كان مثغور عليك وهيصم)\n(خطاطيفك اللاتي تخطفن بهدلا ... فأوفى به الأشراف جذع مقوم)\n(يداك يدا خير وشر فمنهما ... تضر وللأخرى نوال وأنعم)","topic":"أخبار شبيب بن البرصاء ونسبه","topicNo":139,"sp":2,"spl":"خطب بنت يزيد بن هاشم فرده ثم قبله فأبى — دعيج بن سيف يرميه فيصيب عينه","loc":2263},
{"id":"b139-5","bab":"الجزء 12","sec":"دعيج بن سيف يرميه فيصيب عينه","page":"ج12 ص324","text":"وقال أبو عمرو استاق دعيج بن سيف بن جذيمة بن وهب الطائي ثم الجرمي إبل شبيب بن البرصاء فذهب بها وخرج بنو البرصاء في الطلب فلما واجهوا بني جرم قال شبيب اغتنموا بني جرم فقال أصحابه لسنا طالبين إلا أهل القرحة فمضوا حتى أتوا دعيجا وهو برأس الجبل فناداه\nشبيب يا دعيج إن كانت الطراف حية فلك سائر الإبل فقال يا شبيب تبصر رأسها من بين الإبل فنظر فأبصرها فقال شبيب شدوا عليه واصعدوا وراءه فأبوا عليه فحمل شبيب عليه وحده ورماه دعيج فأصاب عينه فذهب بها وكان شبيب أعور ثم عمي بعد ما أسن فانصرف وانصرف معه بنو عمه وفاز دعيج بالإبل فقال شبيب\n(أمرت بني البرصاء يوم حزابة ... بأمر جميع لم تشتت مصادره)\n(بشول ابن معروف وحسان بعدما ... جرى لي يمن قد بدا لي طائره)\n(أيرجع حر دون جرم ولم يكن ... طعان ولا ضرب يذعذع عاسره)\n(فأذهب عيني يوم سفح سفيرة ... دعيج بن سيف أعوزته معاذره)\n(ولما رأيت الشول قد حال دونها ... من الهضب مغبر عنيف عمائره)\n(وأعرض ركن من سفيرة يتقى ... بشم الذرا لا يعبد الله عامره)\n(أخذت بني سيف ومالك موقع ... بما جر مولاهم وجرت جرائره)\n(ولو أن رجلي يوم فر ابن جوشن ... علقن ابن ظبي أعوزته مغاوره)\nأخبرني عمي قال حدثني الكراني قال حدثنا العمري عن عاصم بن الحدثان قال هجا أرطاة بن سهية شبيب بن البرصاء ونفاه عن بني عوف فقال\n(فلو كنت عوفيا عميت وأسهلت ... كداك ولكن المريب مريب)\nال فعمي شبيب بن البرصاء بعد موت أرطاة بن سهية فكان يقول ليت ابن سهية حيا حتى يعلم أني عوفي قال والعمى شائع في بني عوف إذا أسن الرجل منهم عمي وقل من يفلت من ذلك منهم وحدثني عمي قال حدثني عبد الله بن أبي سعد قال حدثني علي بن الصباح عن ابن الكلبي قال أنشد الأخطل عبد الملك بن مروان قوله\n(بكر العواذل يبتدرن ملامتي ... والعاذلون فكلهم يلحاني)\n(في أن سبقت بشربة مقدية ... صرف مشعشعة بماء شنان)\nفقال له عبد الملك شبيب بن البرصاء أكرم منك وصفا لنفسه حيث يقول\n(وإني لسهل الوجه يعرف مجلسي ... إذا أحزن القاذورة المتعبس)\n(يضيء سنا جودي لمن يبتغي القرى ... وليل بخيل القوم ظلماء حندس)\n(ألين لذي القربى مرارا وتلتوي ... بأعناق أعدائي حبال تمرس)\nقال وكان عبد الملك يتمثل بقول شبيب في بذل النفس عند اللقاء ويعجب به\n(دعاني حصن للفرار فساءني ... مواطن أن يثنى علي فأشتما)\n(فقلت لحصن نح نفسك إنما ... يذود الفتى عن حوضه أن يهدما)\n(تأخرت أستبقي الحياة فلم أجد ... لنفسي حياة مثل أن أتقدما)\n(سيكفيك أطراف الأسنة فارس ... إذا ريع نادى بالجواد وبالحمى)\n(إذا المرء لم يغش المكاره أوشكت ... حبال الهوينى بالفتى أن تجذما)\nسخت من كتاب أبي عبد الله اليزيدي ولم أقرأه عليه قال خالد بن كلثوم كان الذي هاج الهجاء بين شبيب بن البرصاء وعقيل بن علفة أنه كان لبنى نشبة جار من بني سلامان بن سعد فبلغ عقيلا عنه أنه يطوف في بني مرة يتحدث إلى النساء فامتلأ عليه غيظا فبينا هو يوما جالس وعنده غلمان له وهو يجز إبلا له على الماء ويسمها إذ طلع عليه السلاماني على راحلته فوثب عليه هو وغلمانه فضربوه ضربا مبرحا وعقر راحلته وانصرف من عنده بشر فلم يعد إلى ذلك الموضع ولج الهجاء بينهما وكان عقيل شرسا سيء الخلق غيورا","topic":"أخبار شبيب بن البرصاء ونسبه","topicNo":139,"sp":2,"spl":"خطب بنت يزيد بن هاشم فرده ثم قبله فأبى — دعيج بن سيف يرميه فيصيب عينه","loc":2264},
{"id":"b139-6","bab":"الجزء 12","sec":"أخبار دقاق","page":"ج12 ص328","text":"كانت دقاق مغنية محسنة جميلة الوجه قد أخذت عن أكابر مغني الدولة العباسية وكانت ليحيى بن الربيع فولدت له أحمد ابنه وعمر عمرا طويلا وحدثنا عنه جحظة ونظراؤه من أصحابنا وكان عالما بأمر الغناء والمغنين وكان يغني غناء ليس بمستطاب ولكنه صحيح ومات يحيى بن الربيع فتزوجت بعده من القواد والكتاب بعده فماتوا وورثتهم فحدثني عمي قال حدثني أحمد بن الطيب السرخسي قال كانت دقاق أم ولد يحيى بن الربيع أحمد المعروف بابن دقاق مغنية محسنة متقنة الأداء والصنعة وكانت قد انقطعت إلى حمدونة بنت الرشيد ثم إلى غضيض وكانت مشهورة بالظرف والمجون والفتوة قال أحمد بن الطيب وعتقت دقاق فتزوجها بعد مولاها ثلاثة من القواد من وجوههم فماتوا جميعا فقال عيسى بن زينب يهجوها\n(قلت لما رأيت دار دقاق ... حسنها قد أضر بالعشاق)\n(حذروا الرابع الشقي دقاقا ... لا يكونن نجمه في محاق)\n(أله عن بضعها فإن دقاقا ... شؤم حرها قد سار في الآفاق)\n(لم تضاجع بعلا فهب سليما ... بل جريحا وجرحه غير راقي)\nخبرني الحسين بن القاسم الكوكبي قال حدثني الهدادي الشاعر قال حدثني أبو عبد الله بن حمدون وأخبرني جحظة عن ابن حمدون ورواية الكوكبي أتم قال كتبت دقاق إلى أبي تصف هنها صفة أعجزه الجواب عنها فقال له صديق له ابعث إلى بعض المخنثين حتى يصف متاعك فيكون جوابها فأحضر بعضهم وأخبره الخبر اكتب إليها عندي القوق البوق الأصلع المزبوق الأقرع المفروق المنتفخ العروق يسد البثوق ويفتق الفتوق ويرم الخروق ويقضي الحقوق أسد بين جملين بغل بين حملين منارة بين صخرتين رأسه رأس كلب واصله مترس درب إذا دخل حفر وإذا خرج قشر لو نطح الفيل كوره ولو دخل البحر كدره إذا رق الكلام وتقاربت الأجسام والتفت الساق بالساق ولطخ باطنها بالبصاق وقرع البيض بالذكور وجعلت الرماح تمور بطعن الفقاح\nوشق الأحراح صبرنا فلم نجزع وسلمنا طائعين فلم نخدع قال فقطعها حدثني عمي قال حدثني أحمد بن الطيب قال حدثني أحمد بن علي بن جعفر قال حضرت مرة مجلسا وفيه ابن دقاق وفيه النصراني المعروف بأبي الجاموس اليعقوبي البزاز قرابة بلال قال فعبث ابن دقاق بأبي الجاموس فلما أكثر عليه قال اسمعوا مني ثم حلف بالحنيفية أنه لا يكذب وحدثنا قال مضيت وأنا غلام مع أستاذي إلى باب حمدونة بنت الرشيد ومعنا بز نعرضه للبيع فخرجت إلينا دقاق أم هذا تقاولنا في ثمن المتاع وفي يدها مروحة على أحد وجهيها منقوش الحر إلى أيرين أحوج من الأير إلى حرين وعلى الوجه الآخر كما أن الرحا إلى بغلين أحوج من البغل إلى رحوين قال فأسكته والله سكوتا علمنا معه أنه لو خرس لكان الخرس أصون لعرضه مما جرى قال أحمد وفي دقاق يقول عيسى بن زينب وكان لها غلامان خلاسيان يروحانها في الخيش فتحدث الناس أنها قالت لواحد منهما أن\nينيكها فعجز فقالت له نكني وأنت حر فقال لها نيكيني أنت وبيعيني في الأعراب فقال فيها عيسى بن زينب\n(أحسن من غنى لنا أو شدا ... دقاق في خفض من العيش)\n(لها غلامان ينيكانها ... بعلة الترويح في الخيش)\nدثني جحظة قال حدثني هبة الله بن إبراهيم بن المهدي قال كانت دقاق جارية يحيى بن الربيع تواصل جماعة كانوا يميلون إليها وتري كل واحد منهم أنها تهواه وكانت أحسن أهل عصرها وجها وأشأمهم على من رابطها وتزوجها فقال فيها أبو إسحاق يعني أباه\n(عدمتك يا صديقة كل خلق ... أكل الناس ويحك تعشقينا)\n(فكيف إذا خلطت الغث منهم ... بلحم سمينهم لا تبشمينا)\nيه خفيف رمل ينسب إلى إبراهيم بن المهدي وإلى ريق وإلى شارية\nأخبرني عمي قال حدثني أحمد بن أبي طاهر قال حدثنا أبو هفان قال خرج يحيى بن الربيع مولى دقاق وكانت قد ولدت منه ابنه أحمد بن يحيى إلى بعض النواحي وترك جاريته دقاق في داره فعملت بعده الأوابد وكانت من أحسن الناس وجها وغناء وأشأمه على أزواجها ومواليها وربطائها فقال أبو موسى الأعمى فيه\n(قل ليحيى نعم صبرت على الموت ... ولم تخش سهم ريب المنون)\n(كيف قل لي أطقت ويحك يا يحيى ... على الضعف منك حمل القرون)\n(ويح يحيى ما مر باست دقاق ... بعد ما غاب من سياط البطون)","topic":"أخبار شبيب بن البرصاء ونسبه","topicNo":139,"sp":3,"spl":"أخبار دقاق","song":1,"loc":2265},
{"id":"b140-1","bab":"الجزء 12","sec":"صوت من المائة المختارة","page":"ج12 ص332","text":"(تكاشرني كرها كأنك ناصح ... وعينك تبدي أن صدرك لي دوي)\n(لسانك لي حلو وعينك علقم ... وشرك مبسوط وخيرك ملتوي)\nلشعر ليزيد بن الحكم الثقفي والغناء لابراهيم ثقيل أول مطلق في مجرى البنصر عن إسحاق وفيه لجهم العطار خفيف ثقيل عن الهشامي","topic":"نسب يزيد بن الحكم وأخباره","topicNo":140,"sp":0,"spl":"صوت من المائة المختارة — نسب يزيد بن الحكم وأخباره","loc":2266},
{"id":"b140-2","bab":"الجزء 12","sec":"نسب يزيد بن الحكم وأخباره","page":"ج12 ص333","text":"هو يزيد بن الحكم بن عثمان بن أبي العاص صاحب رسول الله كذلك وجدت نسبه في نسخة ابن الأعرابي وذكر غيره أنه يزيد بن الحكم بن أبي العاص وأن عثمان عمه وهذا هو القول الصحيح وأبو العاص بن بشر بن عبد دهمان بن عبد الله بن همام بن أبان بن يسار بن مالك بن حطيط بن جشم بن قسي وهو ثقيف وعثمان جده أو عم أبيه أحد من أسلم من ثقيف يوم فتح الطائف هو وأبو بكرة وشط عثمان بالبصرة منسوب إليه كانت له هناك أرض أقطعها وابتاعها وقد روى عن رسول الله الحديث وروى عنه الحسن بن أبي الحسن ومطرف بن عبد الله بن الشخير وغيرهما من التابعين أخبرني الحسن بن علي قال حدثنا بشر بن موسى قال حدثنا الحميدي قال حدثنا سفيان سمعه من محمد بن اسحاق وسمعه محمد من سعيد بن أبي هند وسمعه سعيد بن أبي هند من مطرف بن عبد الله بن الشخير قال سمعت عثمان بن أبي العاص الثقفي يقول قال لي رسول الله\nأم قومك واقدرهم بأضعفهم فإن منهم الضعيف والكبير وذا الحاجة قال الحميدي وحدثنا الفضيل بن عياض عن أشعب عن الحسن عن عثمان بن أبي العاص قال قال رسول الله اتخذوا مؤذنا ولا يأخذ على أذانه أجرا أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثنا العلاء بن الفضل قال حدثني أبي قال مر الفرزدق بيزيد بن الحكم بن أبي العاص الثقفي وهو ينشد في المجلس شعرا فقال من هذا الذي ينشد شعرا كأنه من أشعارنا فقالوا يزيد بن الحكم فقال نعم أشهد بالله أن عمتي ولدته وأم يزيد بكرة بنت الزبرقان بن بدر وأمها هنيدة بنت صعصعة بن ناجية وكانت بكرة أول عربية ركبت البحر فأخرج بها إلى الحكم وهو بتوج وكان الزبرقان يكنى أبا العباس وكان له بنون منهم العباس وعياش","topic":"نسب يزيد بن الحكم وأخباره","topicNo":140,"sp":0,"spl":"صوت من المائة المختارة — نسب يزيد بن الحكم وأخباره","loc":2267},
{"id":"b140-3","bab":"الجزء 12","sec":"أخباره مع الحجاج","page":"ج12 ص334","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن شبيب قال حدثنا الحزامي قال\nدعا الحجاج بن يوسف بيزيد بن الحكم الثقفي فولاه كورة فارس ودفع إليه عهده بها فلما دخل عليه ليودعه قال له الحجاج أنشدني بعض شعرك وإنما أراد أن ينشده مديحا له فأنشده قصيدة يفخر فيها ويقول\n(وأبي الذي سلب ابن كسرى راية ... بيضاء تخفق كالعقاب الطائر)\nفلما سمع الحجاج فخره نهض مغضبا فخرج يزيد من غير أن يودعه فقال الحجاج لحاجبه ارتجع منه العهد فإذا رده فقل له أيهما خير لك ما ورثك أبوك أم هذا فرد على الحاجب العهد وقال قل له\n(ورثت جدي مجده وفعاله ... وورثت جدك أعنزا بالطائف)\nخرج عنه مغضبا فلحق بسليمان بن عبد الملك ومدحه بقصيدته التي أولها\n(أمسى بأسماء هذا القلب معمودا ... إذا أقول صحا يعتاده عيدا)\nقول فيها\n(سميت باسم امريء أشبهت شيمته ... عدلا وفضلا سليمان بن داودا)\n(أحمد به في الورى الماضين من ملك ... وأنت أصبحت في الباقين محمودا)\n(لا يبرأ الناس من أن يحمدوا ملكا ... أولاهم في الأمور الحلم والجودا)\nقال له سليمان وكم كان أجرى لك لعمالة فارس قال عشرين\nألفا قال فهي لك علي ما دمت حيا وفي أول هذه القصيدة غناء نسبته\n(أمسى بأسماء هذا القلب معمودا ... إذا أقول صحا يعتاده عيدا)\n(كأن أحور من غزلان ذي بقر ... أهدى لها شبه العينين والجيدا)\n(أجري على موعد منها فتخلفني ... فلا أمل ولا توفي المواعيدا)\n(كأنني يوم أمسي لا تكلمني ... ذو بغية يبتغي ما ليس موجودا)\nومن الناس من ينسب هذه الأبيات إلى عمر بن أبي ربيعة وذلك خطأ - عروضه من البسيط - والغناء للغريض ثقيل أول بالبنصر في مجراها عن إسحاق وذكر عمرو بن بانة أنه لمعبد ثقيل أول بالوسطى أخبرنا محمد بن العباس اليزيدي قال حدثنا الخليل بن أسد قال حدثني العمري عن الهيثم بن عدي قال أخبرنا ابن عياش عن أبيه قال سمعت الحجاج واستوى جالسا ثم قال صدق والله زهير بن أبي سلمى حيث يقول\n(وما العفو إلا لامرىء ذي حفيظة ... متى يعف عن ذنب امرىء السوء يلجج)\nقال له يزيد بن الحكم أصلح الله الأمير إني قد رثيت ابني عنبسا ببيت إنه لشبيه بهذا قال وما هو قال قلت\n(ويأمن ذو حلم العشيرة جهله ... عليه ويخشى جهله جهلاؤها)\nقال فما منعك أن تقول مثل هذا لمحمد ابني ترثيه به فقال إن ابني والله كان أحب إلي من ابنك وهذه الأبيات من قصيدة أخبرني بها عمي عن الكراني عن الهيثم بن عدي قال كان ليزيد بن الحكم ابن يقال له عنبس فمات فجزع عليه جزعا شديدا وقال يرثيه\n(جزى الله عني عنبسا كل صالح ... إذا كانت الأولاد سيئا جزاؤها)\n(هو ابني وأمسى أجره لي وعزني ... على نفسه رب إليه ولاؤها)\n(جهول إذا جهل العشيرة يبتغى ... حليم ويرضى حلمه حلماؤها)\nبعد هذا البيت المذكور في الخبر الأول","topic":"نسب يزيد بن الحكم وأخباره","topicNo":140,"sp":1,"spl":"أخباره مع الحجاج","song":1,"loc":2268},
{"id":"b140-4","bab":"الجزء 12","sec":"عبد الملك يفضله على شاعر ثقيف","page":"ج12 ص337","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط قال قال عبد الملك بن مروان كان شاعر ثقيف في الجاهلية خيرا من شاعرهم في الإسلام فقيل له من يعني أمير المؤمنين فقال لهم أما شاعرهم في الإسلام فيزيد بن الحكم حيث يقول\n(فما منك الشباب ولست منه ... إذا سألتك لحيتك الخضابا)\n(عقائل من عقائل أهل نجد ... ومكة لم يعقلن الركابا)\n(ولم يطردن أبقع يوم ظعن ... ولا كلبا طردن ولا غرابا)\nقال شاعرهم في الجاهلية\n(والشيب إن يظهر فإن وراءه ... عمرا يكون خلاله متنفس)\n(لم ينتقص مني المشيب قلامة ... ولما بقي مني ألب وأكيس)\nخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن لقيط قال قال يزيد بن الحكم الثقفي ليزيد بن المهلب حين خلع يزيد بن عبد الملك\n(أبا خالد قد هجت حربا مريرة ... وقد شمرت حرب عوان فشمر)\nفقال يزيد بن المهلب بالله أستعين ثم أنشده فلما بلغ قوله\n(فإن بني مروان قد زال ملكهم ... فإن كنت لم تشعر بذلك فاشعر)\nقال يزيد بن المهلب ما شعرت بذلك ثم أنشده فلما بلغ قوله\n(فمت ماجدا أو عش كريما فإن تمت ... وسيفك مشهور بكفك تعذر)\nقال هذا ما لا بد منه قال العمري وحدثني الهيثم بن عدي عن ابن عياش أن يزيد بن المهلب إنما كتب إليه يزيد بن الحكم بهذه الأبيات فوقع إليه تحت البيت الأول أستعين بالله وتحت البيت الثاني ما شعرت وتحت الثالث أما هذه فنعم أخبرني محمد بن خلف وكيع قال حدثني الغلابي قال حدثني ابن عائشة قال دخل يزيد بن الحكم على يزيد بن المهلب في سجن الحجاج وهو\nيعذب وقد حل عليه نجم كان قد نجم عليه وكانت نجومه في كل أسبوع ستة عشر ألف درهم فقال له\n(أصبح في قيدك السماحة والجود ... وفضل الصلاح والحسب)\n(لا بطر إن تتابعت نعم ... وصابر في البلاء محتسب)\n(بززت سبق الجياد في مهل ... وقصرت دون سعيك العرب)\nال فالتفت يزيد بن المهلب إلى مولى له وقال أعطه نجم هذا الأسبوع ونصبر على العذاب إلى السبت الآخر وقد رويت هذه الأبيات والقصة لحمزة بن بيض مع يزيد أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني هارون بن مسلم قال حدثني عثمان بن حفص قال حدثني عبد الواحد عريف ثقيف بالبصرة أن العباس بن يزيد بن الحكم الثقفي هرب من يوسف بن عمر إلى اليمامة قال فجلست في مسجدها وغشيني قوم من أهلها قال فوالله إني لكذلك إذا أنا بشيخ قد دخل يترجح في مشيته فلما رآني أقبل إلي فقال\nالقوم هذا جرير فأتاني حتى جلس إلى جنبي ثم قال لي السلام عليك ممن أنت قلت رجل من ثقيف قال أعرضت الأديم ثم ممن قلت رجل من بني مالك فقال لا إله إلا الله أمثلك يعرف بأهل بيته فقلت أنا رجل من ولد أبي العاص قال ابن بشر قلت نعم قال أيهم أبوك قلت يزيد بن الحكم قال فمن الذي يقول\n(فني الشباب وكل شيء فان ... وعلا لداتي شيبهم وعلاني)\nلت أبي قال فمن الذي يقول\n(ألا لا مرحبا بفراق ليلى ... ولا بالشيب إذ طرد الشبابا)\n(شباب بان محمودا وشيب ... ذميم لم نجد لهما اصطحابا)\n(فما منك الشباب ولست منه ... إذا سألتك لحيتك الخضابا)\nلت أبي قال فمن الذي يقول\n(تعالوا فعدوا يعلم الناس أينا ... لصاحبه في أول الدهر تابع)\n(تزيد يربوع بكم في عدادها ... كما زيد في عرض الأديم الأكارع)\nال قلت غفر الله لك كان أبي أصون لنفسه وعرضه من أن يدخل بينك وبين ابن عمك فقال رحم الله أباك فقد مضى لسبيله ثم انصرف فنزلني بكبشين فقال لي أهل اليمامة ما نزل أحدا قبلك قط أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن إبراهيم الموصلي عن يزيد حوراء المغني قال","topic":"نسب يزيد بن الحكم وأخباره","topicNo":140,"sp":2,"spl":"عبد الملك يفضله على شاعر ثقيف","loc":2269},
{"id":"b140-5","bab":"الجزء 12","sec":"شعره في جارية غير مطاوعة له","page":"ج12 ص341","text":"كان يزيد بن الحكم الثقفي يهوى جارية مغنية وكانت غير مطاوعة له فكان يهيم بها ثم قدم رجل من أهل الكوفة فاشتراها فمرت بيزيد بن الحكم مع غلمة لمولاها وهي راحلة فلما علم بذلك رفع صوته فقال\n(يا أيها النازح الشسوع ... ودائع القلب لا تضيع)\n(أستودع الله من إليه ... قلبي على نأيه نزوع)\n(إذا تذكرته استهلت ... شوقا إلى وجهه الدموع)\nمضت الجارية وغاب عنه خبرها مدة فبينا هو جالس ذات يوم إذ وقف عليه كهل فقال له أأنت يزيد بن الحكم قال نعم فدفع إليه كتابا مختوما ففضه فإذا كتابها إليه وفيه\n(لئن كوى قلبك الشسوع ... فالقلب مني به صدوع)\n(وبي ورب السماء فاعلم ... إليك يا سيدي نزوع)\n(أعزز علينا بما تلاقي ... فينا وإن شفنا الولوع)\n(فالنفس حرى عليك ولهى ... والعين عبرى لها دموع)\n(فموتنا في يد التنائي ... وعيشنا القرب والرجوع)\n(وحيثما كنت يا منايا ... فالقلب مني به خشوع)\n(ثم عليك السلام مني ... ما كان شمسها طلوع)\nقال فبكى والله حتى رحمه من حضر وقال لنا الكهل ما قصته فأخبرناه بما بينهما فجعل يستغفر الله من حمله الكتاب إليه وأحسب أن هذا الخبر مصنوع ولكن هكذا أخبرنا به ابن أبي الأزهر","topic":"نسب يزيد بن الحكم وأخباره","topicNo":140,"sp":3,"spl":"شعره في جارية غير مطاوعة له — شعر نسب إليه وإلى طرفة بن العبد","loc":2270},
{"id":"b140-6","bab":"الجزء 12","sec":"شعر نسب إليه وإلى طرفة بن العبد","page":"ج12 ص342","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال أنشدني أبو الزعراء رجل من بني قيس بن ثعلبة لطرفة بن العبد\n(تكاشرني كرها كأنك ناصح ... وعينك تبدي أن صدرك لي جوي)\nال فعجبت من ذلك وأنشدته أبا عمرو بن العلاء وقلت له إني كنت أرويه ليزيد بن الحكم الثقفي فأنشدنيه أبو الزعراء لطرفة بن العبد فقال لي أبو عمرو إن أبا الزعراء في سن يزيد بن الحكم ويزيد مولد يجيد الشعر وقد يجوز أن يكون أبو الزعراء صادقا قال مؤلف هذا الكتاب ما أظن أبا الزعراء صدق فيما حكاه لأن العلماء من رواة الشعر رووها ليزيد بن الحكم وهذا أعرابي لا يحصل ما يقوله ولو كان هذا الشعر مشكوكا فيه أنه ليزيد بن الحكم وليس كذلك لكان معلوما أنه ليس لطرفة ولا موجودا في شعره على سائر الروايات ولا هو أيضا مشبها لمذهب طرفة ونمطه وهو بيزيد أشبه وله في معناه عدة قصائد يعاتب فيها أخاه عبد ربه بن الحكم وابن عمه عبد الرحمن بن عثمان بن أبي العاص ومن قال إنه ليزيد بن الحكم بن عثمان قال إن عمه عبد الرحمن هو\nالذي عاتبه وفيه يقول\n(ومولى كذئب السوء لو يستطيعني ... أصاب دمي يوما بغير قتيل)\n(وأعرض عما ساءه وكأنما ... يقاد إلى ما ساءني بدليل)\n(مجاملة مني وإكرام غيره ... بلا حسن منه ولا بجميل)\n(ولو شئت لولا الحلم جدعت أنفه ... بإيعاب جدع بادىء وعليل)\n(حفاظا على أحلام قوم رزئتهم ... رزان يزينون الندي كهول)\nوقال في أخيه عبد ربه\n(أخي يسر لي الشحناء يضمرها ... حتى ورى جوفه من غمره الداء)\n(حران ذو غصة جرعت غصته ... وقد تعرض دون الغصة الماء)\n(حتى إذا ما أساغ الريق أنزلني ... منه كما ينزل الأعداء أعداء)\n(أسعى فيكفر سعيي ما سعيت له ... إني كذاك من الإخوان لقاء)\n(وكم يد ويد لي عنده ويد ... يعدهن ترات وهي آلاء)\nأما تمام القصيدة التي نسبت إلى طرفة فأنا أذكر منها مختارها ليعلم أن مرذول كلام طرفة فوقه\n(تصافح من لاقيت لي ذا عداوة ... صفاحا وعني بين عينيك منزوي)\n(اراك إذا لم أهو أمرا هويته ... ولست لما أهوى من الأمر بالهوي)\n(أراك اجتويت الخير مني وأجتوي ... أذاك فكل يجتوي قرب مجتوي)\n(فليت كفافا كان خيرك كله ... وشرك عني ما ارتوى الماء مرتوي)\n(عدوك يخشى صولتي إن لقيته ... وأنت عدوي ليس ذاك بمستوي)\n(وكم موطن لولاي طحت كما هوى ... بأجرامه من قلة النيق منهوي)\n(إذا ما ابتنى المجد ابن عمك لم تعن ... وقلت ألا يا ليت بنيانه خوي)\n(كأنك إن نال ابن عمك مغنما ... شج أو عميد أو أخو غلة لوي)\n(وما برحت نفس حسود حشيتها ... تذيبك حتى قيل هل أنت مكتوي)\n(جمعت وفحشا غيبة ونميمة ... ثلاث خصال لست عنهن نرعوي)\n(ويدحو بك الداحي إلى كل سوءة ... فيا شر من يدحو إلى شر مدحوي)\n(بدا منك غش طالما قد كتمته ... كما كتمت داء ابنها أم مدوي)\nهذا شعر إذا تأمله من له في العلم أدنى سهم عرف أنه لا يدخل في\nمذهب طرفة ولا يقاربه","topic":"نسب يزيد بن الحكم وأخباره","topicNo":140,"sp":3,"spl":"شعره في جارية غير مطاوعة له — شعر نسب إليه وإلى طرفة بن العبد","loc":2271},
{"id":"b141-1","bab":"الجزء 12","sec":"صوت من المائة المختارة","page":"ج12 ص345","text":"(أبى القلب إلا أم عوف وحبها ... عجوزا ومن يعشق عجوزا يفند)\n(كثوب يمان قد تقادم عهده ... ورقعته ما شئت في العين واليد)\nلشعر لأبي الأسود الدؤلي والغناء لعلويه ثقيل أول بالبنصر عن عمرو بن بانة","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":0,"spl":"صوت من المائة المختارة — كان أول من نقط المصاحف","loc":2272},
{"id":"b141-2","bab":"الجزء 12","sec":"أخبار أبي الأسود الدؤلي ونسبه","page":"ج12 ص345","text":"اسمه ظالم بن عمرو بن سفيان بن جندل بن يعمر بن حلس بن نفاثة بن عدي بن الدئل بن بكر بن عبد مناة بن كنانة بن خزيمة بن مدركة بن إلياس بن مضر بن نزار وهم إخوة قريش لأن قريشا مختلف في الموضع الذي افترقت فيه مع أبيها فخصت بهذا الاسم دونهم وأبعد من قال في ذلك مدى من زعم أن النضر بن كنانة منتهى نسب قريش فأما النسابون منهم فيقولون إن من لم يلده فهر بن مالك بن النضر فليس قرشيا وكان أبو الأسود الدؤلي من وجوه التابعين وفقهائهم ومحدثيهم وقد روى عن عمر بن الخطاب وعلي بن أبي طالب رضي الله عنهما فأكثر وروى عن ابن عباس وغيره واستعمله عمر بن الخطاب وعثمان بن عفان وعلي بن أبي طالب رضي الله عنهم وكان من وجوه شيعة علي وذكر أبو عبيدة أنه أدرك أول الإسلام وشهد بدرا مع المسلمين وما سمعت بذلك عن غيره وأخبرني عمي عن ابن أبي سعد عن محمد بن عبد الرحمن بن عبد الصمد السلمي عن أبي عبيدة مثله","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":0,"spl":"صوت من المائة المختارة — كان أول من نقط المصاحف","loc":2273},
{"id":"b141-3","bab":"الجزء 12","sec":"أبو الأسود واضع بناء النحو واصوله","page":"ج12 ص346","text":"واستعمله علي رضي الله عنه على البصرة بعد ابن عباس وهو كان الأصل في بناء النحو وعقد أصوله\nأخبرنا أبو جعفر بن رستم الطبري النحوي بذلك عن أبي عثمان المازني عن أبي عمر الجرمي عن أبي الحسن الأخفش عن سيبويه عن الخليل بن أحمد عن عيسى بن عمر عن عبد الله بن أبي إسحاق الحضرمي عن عنبسة الفيل وميمون الأقرن عن يحيى بن يعمر الليثي أن أبا الأسود الدؤلي دخل إلى ابنته بالبصرة فقالت له يا أبت ما أشد الحر رفعت أشد فظنها تسأله وتستفهم منه أي زمان الحر أشد فقال لها شهر ناجر يريد شهر صفر الجاهلية كانت تسمي شهور السنة بهذه الأسماء فقالت يا أبت إنما أخبرتك ولم أسألك فأتى أمير المؤمنين علي بن أبي طالب عليه السلام فقال يا أمير المؤمنين ذهبت لغة العرب لما خالطت العجم وأوشك إن تطاول عليها زمان أن تضمحل فقال له وما ذلك فأخبره خبر ابنته فأمره فاشترى صحفا بدرهم وأمل عليه الكلام كله لا يخرج عن اسم وفعل وحرف جاء لمعنى وهذا القول أول كتاب سيبويه ثم رسم أصول النحو كلها فنقلها النحويون وفرعوها قال أبو الفرج الأصبهاني هذا حفظته عن أبي جعفر وأنا حديث السن فكتبته من حفظي واللفظ يزيد وينقص وهذا معناه","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":0,"spl":"صوت من المائة المختارة — كان أول من نقط المصاحف","loc":2274},
{"id":"b141-4","bab":"الجزء 12","sec":"كان أول من نقط المصاحف","page":"ج12 ص347","text":"أخبرني عيسى بن الحسين قال حدثنا حماد بن إسحاق عن أبيه عن المدائني قال أمر زياد أبا الأسود الدؤلي أن ينقط المصاحف فنقطها ورسم من النحو\nرسوما ثم جاء بعده ميمون الأقرن فزاد عليه في حدود العربية ثم زاد فيها بعده عنبسة بن معدان المهري ثم جاء عبد الله بن أبي إسحاق الحضرمي وأبو عمرو بن العلاء فزادا فيه ثم جاء الخليل بن أحمد الأزدي وكان صليبة فلحب الطريق ونجم على ابن حمزة الكسائي مولى بني كاهل من أسد فرسم للكوفيين رسوما هم الآن يعملون عليها أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد النحوي قال حدثنا التوزي والمهري قالا حدثنا كيسان بن المعرف الهجيمي أبو سليمان عن أبي سفيان بن العلاء عن جعفر بن أبي حرب بن أبي الأسود الدؤلي عن أبيه قال قيل لأبي الاسود من أين لك هذا العلم يعنون به النحو فقال أخذت حدوده عن علي بن أبي طالب عليه السلام","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":0,"spl":"صوت من المائة المختارة — كان أول من نقط المصاحف","loc":2275},
{"id":"b141-5","bab":"الجزء 12","sec":"خبره مع زياد في سبب وضع النحو","page":"ج12 ص348","text":"أخبرني أحمد بن العباس العسكري قال حدثني عبيد الله بن محمد عن عبد الله بن شاكر العنبري عن يحيى بن آدم عن أبي بكر عياش عن عاصم بن أبي النجود قال أول من وضع العربية أبو الأسود الدؤلي جاء إلى زياد بالبصرة فقال له أصلح الله الأمير إني أرى العرب قد خالطت هذه الأعاجم وتغيرت ألسنتهم أفتأذن لي أن أضع لهم علما يقيمون به كلامهم قال لا قال ثم جاء زيادا رجل فقال مات أبانا وخلف بنون فقال زياد مات أبانا وخلف بنون ردوا إلي أبا الأسود الدؤلي فرد إليه فقال ضع للناس ما نهيتك\nعنه فوضع لهم النحو وقد روى هذا الحديث عن أبي بكر بن عياش يزيد بن مهران فذكر أن هذه القصة كانت بين أبي الأسود وبين عبيد الله بن زياد أخبرني أحمد بن العباس قال حدثنا العنزي عن أبي عثمان المازني عن الأخفش عن الخليل بن أحمد عن عيسى بن عمر عن عبد الله بن أبي إسحاق عن أبي حرب بن الأسود قال أول باب وضعه أبي من النحو باب التعجب وقال الجاحظ أبو الأسود الدؤلي معدود في طبقات من الناس وهو في كلها مقدم مأثور عنه الفضل في جميعها كان معدودا في التابعين والفقهاء والشعراء والمحدثين والأشراف والفرسان والأمراء والدهاة والنحويين والحاضري الجواب والشيعة والبخلاء والصلع الأشراف والبخر الأشراف","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":1,"spl":"خبره مع زياد في سبب وضع النحو — حديثه عن عمر بن الخطاب وعلي","loc":2276},
{"id":"b141-6","bab":"الجزء 12","sec":"حديثه عن عمر بن الخطاب وعلي","page":"ج12 ص349","text":"فما رواه من الحديث عن عمر مسندا عن النبي حدثنا حامد بن محمد بن شعيب البلخي قال حدثنا أبو خيثمة زهير بن حرب قال حدثنا يونس بن محمد قال حدثنا داود بن أبي الفرات عن عبد الله بن ابي بريدة عن أبي الأسود الدؤلي قال أتيت المدينة فوافقتها وقد وقع فيها مرض فهم يموتون موتا ذريعا فجلست إلى عمر بن الخطاب رضي الله تعالى عنه فمرت به جنازة فأثني على صاحبها خير فقال عمر رضي الله عنه وجبت ثم مر بأخرى فأثني على صاحبها بشر فقال عمر رضي الله عنه وجبت فقال أبو الأسود ما وجبت يا أمير المؤمنين فقال قلت كما قال رسول الله أيما مسلم شهد له أربعة بخير أدخله الله الجنة فقلنا وثلاثة قال وثلاثة فقلنا واثنان قال واثنان ثم لم نسأله عن الواحد\nحدثني حماد بن سعيد قال حدثنا أبو خيثمة قال حدثنا معاذ بن هشام قال حدثني أبي عن قتادة عن أبي الأسود الدؤلي قال خطب عمر بن الخطاب رضي الله تعالى عنه الناس يوم الجمعة فقال إن نبي الله قال لا تزال طائفة من أمتي على الحق منصورة حتى يأتي أمر الله جل وعز ومما رواه عن علي بن أبي طالب عليه السلام أخبرنا محمد بن عبد الله بن سليمان الحضرمي قال حدثنا هناد بن السري قال حدثنا عبدة بن سليمان عن سعيد بن أبي عروبة عن قتادة عن أبي حرب بن أبي الأسود الدؤلي عن ابيه أبي الأسود الدؤلي عن علي كرم الله وجهه أنه قال في بول الجارية يغسل وفي بول الغلام ينضح ما لم يأكلا الطعام أخبرني محمد بن العباس اليزيدي قال حدثنا البغوي قال حدثنا علي بن الجعد قال حدثنا معلى بن هلال عن الشعبي وأخبرني أحمد بن عبيد الله بن عمر قال حدثنا عرم بن شبة قال حدثنا المدائني جميعا قالوا لما خرج ابن عباس رضي الله عنهما إلى المدينة من البصرة تبعه أبو الأسود في قومه ليرده فاعتصم عبد الله بأخواله من بني هلال فمنعوه وكادت تكون بينهم حرب فقال لهم بنو هلال ننشدكم الله ألا تسفكوا بيننا دماء تبقى معها العداوة إلى آخر الأبد وأمير المؤمنين أولى بابن عمه فلا تدخلوا أنفسكم بينهما فرجعت كنانة عنه وكتب أبو الأسود إلى علي عليه السلام فأخبره بما جرى فولاه البصرة","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":1,"spl":"خبره مع زياد في سبب وضع النحو — حديثه عن عمر بن الخطاب وعلي","loc":2277},
{"id":"b141-7","bab":"الجزء 12","sec":"كان كاتبا لابن عباس على البصرة","page":"ج12 ص350","text":"أخبرني حبيب بن نصر المهلبي ووكيع وعمي قالوا جميعا حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عمران الضبي قال حدثني خالد بن\nعبد الله قال حدثني أبو عبيدة معمر بن المثنى قال كان أبو الأسود الدؤلي كاتبا لابن عباس على البصرة وهو الذي يقول\n(وإذا طلبت من الحوائج حاجة ... فادع الإله وأحسن الأعمالا)\n(فليعطينك ما أراد بقدرة ... فهو اللطيف لما أراد فعالا)\n(إن العباد وشأنهم وأمورهم ... بيد الإله يقلب الأحوالا)\n(فدع العباد ولا تكن بطلابهم ... لهجا تضعضع للعباد سؤالا)\nخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي عن محمد بن سلام قال كان أبو الأسود الدؤلي قد أسن وكبر وكان مع ذلك يركب إلى المسجد والسوق ويزور اصدقاءه فقال له رجل يا أبا الأسود أراك تكثر الركوب وقد ضعفت عن الحركة وكبرت ولو لزمت منزلك كان أودع لك فقال له أبو الأسود صدقت ولكن الركوب يشد أعضائي وأسمع من أخبار الناس ما لا أسمعه في بيتي واستنشي الريح وألقى إخواني ولو جلست في بيتي لاغتم بي أهلي وأنس بي الصبي واجترأ علي الخادم وكلمني من أهلي من يهاب كلامي لإلفهم إياي وجلوسهم عندي حتى لعل العنز أن تبول علي فلا يقول لها أحد هس\nأخبرني محمد بن القاسم الأنباري قال حدثني أبي قال حدثنا أبو عكرمة قال كان بين بني الديل وبين بني ليث منازعة فقتلت بنو الديل منهم رجلا ثم اصطلحوا بعد ذلك على أن يؤدوا ديته فاجتمعوا إلى أبي الأسود يسألونه المعاونة على أدائها وألح عليه غلام منهم ذو بيان وعارضة فقال له يا أبا الأسود أنت شيخ العشيرة وسيدهم وما يمنعك من معاونتهم قلة ذات يد ولا سؤدد ولا جود فلما أكثر أقبل عليه أبو الأسود ثم قال له قد أكثرت يابن أخي فاسمع مني إن الرجل والله ما يعطي ماله إلا لإحدى خلال إما رجل أعطى ماله رجاء مكافأة ممن يعطيه أو رجل خاف على نفسه فوقاها بماله أو رجل أراد وجه الله وما عنده في الدار الآخرة أو رجل أحمق خدع عن ماله ووالله ما أنتم إحدى هذه الطبقات ولا جئتم في شيء من هذا ولا عمك الرجل العاجز فينخدع لهؤلاء ولما أفدتك إياه في عقلك خير لك من مال أبي الأسود لو وصل إلى بني الديل قوموا إذا شئتم فقاموا يبادرون الباب أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة قال كان طريق أبي الأسود الدؤلي إلى المسجد والسوق في بني تميم الله بن ثعلبة وكان فيهم رجل متفحش يكثر الأستهزاء بمن يمر به فمر به أبو الأسود الدؤلي يوما فقال لقومه كأن وجهه أبي الأسود وجه عجوز راحت إلى أهلها بطلاق فضحك القوم وأعرض عنهم أبو الأسود ثم مر به مرة أخرى فقال لهم كأن غضون قفا أبي الأسود غضون الفقاح فأقبل عليه أبو الأسود فقال له هل تعرف فقحة أمك فيهن فأفحمه وضحك القوم منه وقاموا\nإلى أبي الأسود فاعتذروا إليه مما كان ولم يعاوده الرجل بعد ذلك وقال فيه أبو الأسود بعد ذلك حين رجع إلى أهله\n(وأهوج ملجاج تصاممت قبله ... أن اسمعه وما بسمعي من باس)\n(ولو شئت قد أعرضت حتى أصيبه ... على أنفه حدباء تعضل بالأسي)\n(فإن لساني ليس أهون وقعة ... وأصغر آثارا من النحت بالفاس)\n(وذي إحنة لم يبدها غير أنه ... كذي الخبل تأبى نفسه غير وسواس)\n(صفحت له صفحا جميلا كصفحه ... وعيني وما يدري عليه وأحراسي)\n(وعندي له إن فار فوار صدره ... فحا جبلي لا يعاوده الحاسي)\n(وخب لحوم الناس أكثر زاده ... كثير الخنا صعب المحالة هماس)\n(تركت له لحمي وأبقيت لحمه ... لمن نابه من حاضر الجن والناس)\n(فكر قليلا ثم صد كأنما ... يعض بصم من صفا جبل راسي)\nخبرنا محمد بن العباس اليزيدي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني قال خرج أبو الأسود الدؤلي ومعه جماعة أصحاب له إلى الصيد فجاءه أعرابي فقال له السلام عليك فقال له أبو الأسود كلمة مقولة قال أدخل قال وراؤك أوسع لك قال إن الرمضاء قد أحرقت رجلي قال بل عليها أو ائت الجبل يفيء عليك قال هل عندك شيء تطعمنيه قال\nنأكل ونطعم العيال فإن فضل شيء فأنت أحق به من الكلب فقال الأعرابي ما رأيت قط ألأم منك قال أبو الأسود بلى قد رأيت ولكنك قد أنسيت","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":2,"spl":"كان كاتبا لابن عباس على البصرة","loc":2278},
{"id":"b141-8","bab":"الجزء 12","sec":"أبو الأسود وابن أبي الحمامة","page":"ج12 ص354","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عيسى بن إسماعيل عن المدائني بهذا الخبر فقال فيه كان أبو الأسود جالسا في دهليزه وبين يديه رطب فجاز به رجل من الأعراب يقال له ابن أبي الحمامة فسلم ثم ذكر باقي الخبر مثل الذي تقدمه وزاد عليه فقال أنا ابن أبي الحمامة قال كن ابن أبي طاوسة وانصرف قال أسألك بالله إلا أطعمتني مما تأكل قال فألقى إليه أبو الأسود ثلاث رطبات فوقعت إحداهن في التراب فأخذها يمسحها بثوبه فقال له أبو الأسود دعها فإن الذي تمسحها منه أنظف من الذي تمسحها به فقال إنما كرهت أن أدعها للشيطان فقال له لا والله ولا لجبريل وميكائيل تدعها أخبرني محمد بن عمران الضبي الصيرفي قال حدثنا الحسن بن عليل قال حدثنا محمد بن معاوية الأسدي قال ذكر الهيثم بن عدي عن ابن عياش قال خطب أبو الأسود الدؤلي امرأة من عبد القيس يقال لها أسماء بنت زياد ابن غنيم فأسر أمرها إلى صديق له من الأزد يقال له الهيثم بن زياد فحدث به ابن عم لها كان يخطبها وكان لها مال عند أهلها فمشى ابن عمها الخاطب لها إلى أهلها الذين مالها عندهم فأخبرهم خبر أبي الأسود وسألهم أن\nيمنعوها من نكاحه ومن مالها الذي في أيديهم ففعلوا ذلك وضاروها حتى تزوجت بابن عمها فقال أبو الأسود الدؤلي في ذلك\n(لعمري لقد أفشيت يوما فخانني ... إلى بعض من لم أخش سرا ممنعا)\n(فمزقه مزق العمي وهو غافل ... ونادى بما أخفيت منه فأسمعا)\n(فقلت ولم أفحش لعالك عاثرا ... وقد يعثر الساعي إذا كان مسرعا)\n(ولست بجازيك الملامة إنني ... أرى العفو أدنى للرشاد وأوسعا)\n(ولكن تعلم أنه عهد بيننا ... فبن غير مذموم ولكن مودعا)\n(حديثا أضعناه كلانا فلا أرى ... وأنت نجيا آخر الدهر أجمعا)\n(وكنت إذا ضيعت سرك لم تجد ... سواك له إلا أشت وأضعيا)\nال وقال فيه\n(أمنت أمرأ في السر لم يك حازما ... ولكنه في النصح غير مريب)\n(أذاع به في الناس حتى كأنه ... بعلياء نار أوقدت بثقوب)\n(وكنت متى لم ترع سرك تلتبس ... قوارعه من مخطيء ومصيب)\n(فما كل ذي نصح بمؤتيك نصحه ... وما كل مؤت نصحه بلبيب)\n(ولكن إذا ما استجمعا عند واحد ... فحق له من طاعة بنصيب)\nاخبرني عمي قال حدثني الكراني قال حدثنا العمري عن الهيثم بن عدي عن ابن عياش قال\nاشترى أبو الأسود جارية فأعجبته وكانت حولاء فعابها أهله عنده بالحول فقال في ذلك\n(يعيبونها عندي ولا عيب عندها ... سوى أن في العينين بعض التأخر)\n(فإن يك في العينين سوء فإنها ... مهفهفة الأعلى رداح المؤخر)\nخبرني محمد بن الحسن بن دريد الأزدي قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه قال كان لأبي الأسود الدؤلي صديق من بني تميم ثم من بني سعد يقال له مالك بن أصرم وكانت بينه وبين ابن عم له خصومة في دار له وأنهما اجتمعا عند أبي الأسود فحكماه بينهما فقال له خصم صديقه إني بالذي بينك وبينه عارف فلا يحملنك ها ذاك على أن تحيف علي في الحكم وكان صديق أبي الأسود ظالما فقضى أبو الأسود على صديقه لخصمه بالحق فقال له صديقه والله ما بارك الله لي في صداقتك ولا نفعني بعلمك وفقهك ولقد قضيت علي بغير الحق فقال أبو الأسود\n(إذا كنت مظلوما فلا تلف راضيا ... عن القوم حتى تأخذ النصف واغضب)\n(وإن كنت أنت الظالم القوم فأطرح ... مقالتهم واشغب بهم كل مشغب)\n(وقارب بذي جهل وباعد بعالم ... جلوب عليك الحق من كل مجلب)\n(فإن حدبوا فاقعس وإن هم تقاعسوا ... ليستمكنوا مما وراءك فاحدب)\n(ولا تدعني للجور واصبر على التي ... بها كنت أقضي للبعيد على أبي)\n(فإني امرؤ أخشى إلهي وأتقي ... معادى وقد جربت ما لم تجرب)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":3,"spl":"أبو الأسود وابن أبي الحمامة","loc":2279},
{"id":"b141-9","bab":"الجزء 12","sec":"ابو الأسود يكتب مستجديا","page":"ج12 ص357","text":"كتب إلي أبو خليفة يذكر أن محمد بن سلام حدثه وأخبرني محمد بن يحيى الصولي عن أبي ذكوان عن محمد بن سلام قال وجه أبو الأسود الدؤلي إلى الحصين بن أبي الحر العنبري جد عبيد الله بن الحسن القاضي وهو يلي بعض أعمال الخراج لزياد وإلى نعيم بن مسعود النهشلي وكان يلي مثلي ذلك برسول وكتب معه إليهما وأراد أن يبراه ففعل ذلك نعيم بن مسعود ورمى الحصين بن أبي الحر بكتاب أبي الأسود وراء ظهره فعاد الرجل فأخبره فقال أبو الأسود للحصين\n(حسبت كتابي إذ أتاك تعرضا ... لسيبك لم يذهب رجائي هنالكا)\n(وخبرني من كنت أرسلت أنما ... أخذت كتابي معرضا بشمالكا)\n(نظرت إلى عنوانه فنبذته ... كنبذك نعلا أخلقت من نعالكا)\n(نعيم بن مسعود أحق بما أتى ... وأنت بما تأتي حقيق بذلكا)\n(يصيب وما يدري ويخطي وما درى ... وكيف يكون النوك إلا كذلكا)\nال محمد بن سلام فتقدم رجل إلى عبيد الله بن الحسن بن\nالحصين بن أبي الحر وهو قاضي البصرة مع خصم له فخلط في قوله فتمثل عبيد الله بقول أبي الأسود\n(يصيب وما يدري ويخطي وما درى ... وكيف يكون النوك إلا كذلكا)\nقال الرجل إن رأى القاضي أن يدنيني منه لأقول شيئا فعل فقال له ادن فقال له إن أحق الناس بستر هذا الشعر أنت وقد علمت فيمن قيل فتبسم عبيد الله وقال له إني أرى فيك مصطنعا فقم إلى منزلك وقال لخصمه رح إلي فعزم له ما كان يطالب به أخبرني عمي قال حدثنا الكراني عن ابن عائشة قال أراد أبو الأسود الدؤلي الخروج إلى فارس فقالت له ابنته يا أبت إنك قد كبرت وهذا صميم الشتاء فانتظر حتى ينصرم وتسلك الطريق آمنا فإني أخشى عليك فقال أبو الأسود\n(إذا كنت معنيا بأمر تريده ... فما للمضاء والتوكل من مثل)\n(توكل وحمل أمرك الله إن ما ... تراد به آتيك فاقنع بذي الفضل)\n(ولا تحسبن السير أقرب للردى ... من الخفض في دار المقامة والثمل)\n(ولا تحسبيني يا بنتي عز مذهبي ... بظنك إن الظن يكذب ذا العقل)\n(وإني ملاق ما قضى الله فاصبري ... ولا تجعلي العلم المحقق كالجهل)\n(وإنك لا تدرين هل ما أخافه ... أبعدي يأتي في رحيلي أو قبلي)\n(وكم قد رأيت حاذرا متحفظا ... أصيب وألفته المنية في الأهل)\nأخبرني هاشم بن محمد قال حدثنا عيسى بن إبراهيم العتكي قال حدثنا ابن عائشة عن أبيه قال كان لأبي الأسود صديق من بني سليم يقال له نسيب بن حميد وكان يغشاه في منزله ويتحدث إليه في المسجد وكان كثيرا ما يحلف له أنه ليس بالبصرة أحد من قومه ولا من غيرهم آثر عنده منه فرأى أبو الأسود يوما معه مستقة مخملة أصبهانية من صوف فقال له أبو الأسود ما تصنع بهذه المستقة فقال أريد بيعها فقال له أبو الأسود انظر ما تبلغ فعرفنيه حتى أبعث به إليك فإنها من حاجتي قال لا بل أكسوكها فأبى أبو الأسود أن يقبلها إلا بثمنها فبعث بها إلى السوق فقومت بمائتي درهم فبعث إليه أبو الأسود بالدراهم فردها وقال لست أبيعها إلا بمائتين وخمسين درهما فقال أبو الأسود\n(بعني نسيب ولا تثبني إنني ... لا أستثيب ولا أثيب الواهبا)\n(إن العطية خير ما وجهتها ... وحسبتها حمدا وأجرا واجبا)\n(ومن العطية ما يعود غرامة ... وملامة تبقى ومنا كاذبا)\n(وبلوت أخبار الرجال وفعلهم ... فملئت علما منهم وتجاربا)\nأخذت منهم ما رضيت بأخذه ... وتركت عمدا ما هنالك جانبا فإذا وعدت الوعد كنت كغارم ... دينا أقر به وأحضر كاتبا حتى أنفذه على ما قلته ... وكفى علي به لنفسي طالبا وإذا فعلت غير محاسب ... وكفى بربك جازيا ومحاسبا\n(وإذا منعت منعت منعا بينا ... وأرحت من طول العناء الراغبا)\n(لا اشتري الحمد القليل بقاؤه ... يوما بذم الدهر أجمع واصبا)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":4,"spl":"ابو الأسود يكتب مستجديا","loc":2280},
{"id":"b141-10","bab":"الجزء 12","sec":"ابو الأسود يكتب مستجديا","page":"ج12 ص357","text":"خبرني أحمد بن عبيد الله بن محمد الرازي ومحمد بن العباس اليزيدي وعمي قالوا حدثنا أحمد بن الحارث الخراز عن المدائني قال زعم أبو بكر الهذلي أن أبا الأسود الدؤلي كان يحدث معاوية يوما فتحرك فضرط فقال لمعاوية استرها علي فقال نعم فلما خرج حدث بها معاوية عمرو بن العاص ومروان بن الحكم فلما غدا عليه أبو الأسود قال عمرو ما فعلت ضرطتك يا أبا الأسود بالأمس قال ذهبت كما تذهب الريح مقبلة ومدبرة من شيخ ألان الدهر أعصابه ولحمه عن إمساكها وكل أجوف ضروط ثم أقبل على معاوية فقال إن امرأ ضعفت أمانته ومروءته عن كتمان ضرطة لحقيق بألا يؤمن على أمور المسلمين أخبرني عيسى بن الحسين الوراق قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم عن عوانة قال كان أبو الأسود يجلس إلى فناء امرأة بالبصرة فيتحدث إليها وكانت برزة جميلة فقالت له يا أبا الأسود هل لك في أن أتزوجك فإني صناع الكف حسنة التدبير قانعة بالميسور قال نعم فجمعت أهلها فتزوجته فوجد عندها خلاف ما قدره وأسرعت في ماله ومدت يدها إلى خيانته وأفشت سره فغدا على من كان حضر تزويجه إياها فسألهم أن يجتمعوا عنده ففعلوا فقال لهم\n(أريت أمرا كنت لم أبله ... أتاني فقال اتخذني خليلا)\n(فخاللته ثم أكرمته ... فلم أستفد من لدنه فتيلا)\n(وألفيته حين جربته ... كذوب الحديث سروقا بخيلا)\n(فذكرته ثم عاتبته ... عتابا رفيقا وقولا جميلا)\n(فألفيته غير مستعتب ... ولا ذاكر الله إلا قليلا)\n(ألست حقيقا بتوديعه ... وإتباع ذلك صرما طويلا)\nقالوا بلى والله يا أبا الأسود قال تلك صاحبتكم وقد طلقتها لكم وأنا أحب أن أستر ما أنكرته من أمرها فانصرفت معهم حدثنا اليزيدي قال حدثنا البغوي قال حدثنا العمري قال كان أبو الأسود أبخر فسار معاوية يوما بشيء فأصغى إليه ممسكا بكمه على أنفه فنحى أبو الأسود يده عن أنفه وقال لا والله لا تسود حتى تصبر على سرار المشايخ البخر أخبرني عبد الله بن محمد الرازي قال حدثنا محمد بن الحارث الخراز قال حدثنا المدائني عن أبي بكر الهذلي قال كان علي بن أبي طالب عليه السلام استعمل أبا الأسود على البصرة واستكتب زياد بن أبيه على الديوان والخراج فجعل زياد يسبع أبا الأسود عند علي ويقع فيه ويبغى عليه فلما بلغ ذلك أبا الأسود عنه قال فيه\n(رأيت زيادا ينتحيني بشره ... وأعرض عنه وهو باد مقاتله)\n(وكل امريء والله بالناس عالم ... له عادة قامت عليها شمائله)\n(تعودها فيما مضى من شبابه ... كذلك يدعو كل أمر أوائله)\n(ويعجبه صفحي له وتجملي ... وذو الجهل يحذو الجهل من لا يعاجله)\n(فقلت له دعني وشأني إننا ... كلانا عليه معمل هو عامله)\n(فلولا الذي قد يرتجى من رجائه ... لجربت مني بعض ما أنت جاهله)\n(لجربت أني أمنح الغي من غوى ... علي وأجزي ما جزى وأطاوله)\nقال لزياد أيضا في ذلك\n(نبئت أن زيادا ظل يشتمني ... والقول يكتب عند الله والعمل)\n(وقد لقيت زيادا ثم قلت له ... وقبل ذلك ما خبت به الرسل)\n(حتام تسرقني في كل مجمعه ... عرضي وأنت إذا ما شئت منتفل)\n(كل امريء صائر يوما لشيمته ... في كل منزلة يبلى بها الرجل)\nال فلما ادعى معاوية زيادا وولاه العراق كان أبو الأسود يأتيه فيسأله حوائجه فربما قضاها وربما منعها لما يعلمه من رأيه وهواه في علي بن أبي طالب عليه السلام وما كان بينهما في تلك الأيام وهما عاملان فكان أبو الأسود يترضاه ويداريه ما استطاع ويقول في ذلك\n(رأيت زيادا صدعني وجهه ... ولم يك مردودا عن الخير سائله)\n(ينفذ حاجات الرجال وحاجتي ... كداء الجوى في جوفه لا يزايله)\n(فلا أنا ناس ما نسيت فآيس ... ولا أنا راء ما رأيت ففاعله)\n(وفي اليأس حزم للبيب وراحة ... من الأمر لا ينسى ولا المرء نائله)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":5,"spl":"ابو الأسود يكتب مستجديا","loc":2281},
{"id":"b141-11","bab":"الجزء 12","sec":"مدحه عبد الرحمن بن أبي بكرة","page":"ج12 ص363","text":"وقال المدائني نظر عبد الرحمن بن أبي بكرة إلى أبي الأسود في حال رثه فبعث إليه بدنانير وثياب وسأله أن ينبسط إليه في حوائجه ويستمنحه إذا أضاق فقال أبو الأسود يمدحه\n(أبو بجر أمن الناس طرا ... علينا بعد حي أبي المغيره)\n(لقد ابقى لنا الحدثان منه ... أخا ثقة منافعه كثيره)\n(قريب الخير سهلا غير وعر ... وبعض الخير تمنعه الوعوره)\n(بصرت بأننا أصحاب حق ... ندل به وإخوان وجيره)\n(وأهل مضيعة فوجدت خيرا ... من الخلان فينا والعشيره)\n(وإنك قد علمت وكل نفس ... ترى صفحاتها ولها سريره)\n(لذو قلب بذي القربى رحيم ... وذو عين بما بلغت بصيره)\n(لعمرك ما حباك الله نفسا ... بها جشع ولا نفسا شريره)\n(ولكن أنت لا شرس غليظ ... ولا هشم تنازعه خئوره)\n(كأنا إذا أتيناه نزلنا ... بجانب روضة ريا مطيره)\nقال المدائني وكان أبو الأسود يدخل على عبيد الله بن زياد فيشكو إليه أن عليه دينا لا يجد إلى قضائه سبيلا فيقول له إذا كان غد فارفع إلي حاجتك فإني أحب قضاءها فيدخل إليه من غد فيذكر له أمره ووعده فيتغافل عنه ثم يعاوده فلا يصنع في أمره شيئا فقال فيه أبو الأسود\n(دعاني أميري كي أفوه بحاجتي ... فقلت فما رد الجواب ولا استمع)\n(فقمت ولم أحسس بشيء ولم أصن ... كلامي وخير القول ما صين أو نفع)\n(وأجمعت يأسا لا لبانة بعده ... ولليأس أدنى للعفاف من الطمع)\nخبرنا محمد بن العباس اليزيدي قال حدثنا عيسى بن إسماعيل تينة قال حدثني ابن عائشة قال سأل رجل أبا الأسود شيئا فمنعه فقال له يا أبا الأسود ما أصبحت حاتميا قال بلى قد أصبحت حاتميا من حيث لا تدري أليس حاتم الذي يقول\n(أماوي إما مانع فمبين ... وإما عطاء لا ينهنهه الزجر)\nخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا ابن عائشة قال كان لأبي الأسود جار يحسده وتبلغه عنه قوارص فلما باع أبو الأسود داره في بني الديل وانتقل إلى هذيل قال جار أبي الأسود لبعض جيرانه من هذيل هل يسقيكم أبو الأسود من ألبان لقاحه وكانت لا تزال عنده لقحة\nأو لقحتان وكان جاره هذا يصيب من الشراب فبلغ أبا الأسود قوله فقال فيه\n(إن امرأ نبئته من صديقنا ... يسائل هل أسقي من اللبن الجارا)\n(وإني لأسقي الجار في قعر بيته ... واشرب ما لا إثم فيه ولا عارا)\n(شرابا حلالا يترك المرء صاحيا ... ولا يتولى يقلس الإثم والعارا)\nخبرني عبيد الله بن محمد الرازي قال حدثنا أحمد بن الحارث الخراز قال حدثنا المدائني قال كان لأبي الأسود صديق من بني قيس بن ثعلبة يقال له حوثرة بن سليم فاستعمله عبيد الله بن زياد على جي وأصبهان وكان أبو الأسود بفارس فلما بلغه خبره أتاه فلم يجد عنده ما يقدره وجفاه حوثرة فقال فيه أبو الأسود وفارقه\n(تروحت من رستاق جي عشية ... وخلفت في رستاق أخا لكا)\n(أخا لك إن طال التنائي وجدته ... نسيا وإن طال التعاشر ملكا)\n(ولو كنت سيفا يعجب الناس حده ... وكنت له يوما من الدهر فلكا)\n(ولو كنت أهدى الناس ثم صحبته ... وطاوعته ضل الهوى وأضلكا)\n(إذا جئته تبغي الهدى خالف الهدى ... وإن جرت عن باب الغواية دلكا)\nال المدائني وكان لأبي الأسود جار يقال له وثاق من خزاعة وكان\nيحب اتخاذ اللقاح ويغالي بها ويصفها فأتى أبا الأسود وعنده لقحة غزيرة يقال لها الصفوف فقال له يا أبا الأسود ما بلقحتك بأس لولا عيب كذا وكذا فهل لك في بيعها فقال أبو الأسود على ما تذكر فيها من العيب فقال إني أغتفر ذلك لها لما أرجوه من غزارتها فقال له أبو الأسود بئست الخلتان فيك الحرص والخداع أنا لعيب مالي أشد اغتفارا وقال أبو الأسود فيه\n(يريد وثاق ناقتي ويعيبها ... يخادعني عنها وثاق بن جابر)\n(فقلت تعلم يا وثاق بأنها ... عليك حمى أخرى الليالي الغوابر)\n(بصرت بها كوماء حوساء جلدة ... من الموليات الهام حد الظواهر)\n(فحاولت خدعي والظنون كواذب ... وكم طامع في خدعتي غير ظافر)\nال وكانت له لقحة أخرى يقال لها الطيفاء وكان يقول ماملكت مالا قط أحب إلي منها فأتاه فيها رجل من بني سدوس يقال له أوس بن عامر فجعل يماكر أبا الأسود ويعيبها فألفاه بها بصيرا وفيها منافسا فبذل له فيها ثمنا وافيا فأبى أن يبيعه وقال فيه\n(أتاني في الطيفاء أوس بن عامر ... ليخدعني عنها بجن ضراسها)\n(فسام قليلا ناسئا غير ناجز ... وأحصر نفسا وانتهى بمكاسها)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":6,"spl":"مدحه عبد الرحمن بن أبي بكرة","loc":2282},
{"id":"b141-12","bab":"الجزء 12","sec":"مدحه عبد الرحمن بن أبي بكرة","page":"ج12 ص363","text":"(فأقسم لو أعطيت ما سمت مثله ... وضعفا له لما غدوت براسها)\n(أغرك منها أن نحرت حوارها ... لجيران أم السكن يوم نفاسها)\n(فولى ولم يطمع وفي النفس حاجة ... يرددها مردودة بإياسها)\nأخبرنا اليزيدي قال حدثنا عيسى عن ابن عائشة والأصمعي أن رجلا سأل أبا الأسود الدؤلي فرده فألح عليه فقال له أبو الأسود ليس للسائل الملحف مثل الرد الجامس قال يعني بالجامس الجامد وقال المدائني خطب أبو الأسود امرأة من بني حنيفة وكان قد رآها فأعجبته فأجابته إلى ذلك وأذنت له في الدخول إليها فدخل دارها فخاطبها بما أراد فلماخرج لقيه ابن عم لها قد كان خطبها على أخيه فقال له ما تصنع هاهنا فأخبره بخطبته المرأة فنهاه عن التعرض لها ووضع عليها أرصادا فكان أبو الأسود ربما مر بهم وإجتاز بقبيلتهم فدسوا إليه رجلا يوبخه في كل محفل يراه فيه ففعل وأتاه وهو في نادي قومه فقال له يا أبا الأسود أنت رجل شريف ولك سن وخطر وعرض وما أرضى لك أن تلم بفلانة وليست لك بزوجة ولا قرابة فإن أهلها قد أنكروا ذلك وتشكوه فإما أن تتزوجها أو تضرب عنها فقال له أبو الأسود\n(لقد جد في سلمى الشكاة وللذي ... يقولون لو يبدو لك الرشد أرشد)\n(يقولون لا تمذل بعرضك واصطنع ... معادك إن اليوم يتبعه غد)\n(وإياك والقوم الغضاب فإنهم ... بكل طريق حولهم تترصد)\n(تلام وتلحى كل يوم ولا ترى ... على اللوم وإلا حولها تتردد)\n(أفادتكها العين الطموح وقد ترى ... لك العين ما لا تستطيع لك اليد)\nوقال أبو الأسود\n(دعوا آل سلمى ظنتي وتعنتي ... وما زل مني إن ما فات فائت)\n(ولا تهلكوني بالملامة إنما ... نطقت قليلا ثم إني لساكت)\n(سأسكت حتى تحسبوني أنني ... من الجهد في مرضاتكم متماوت)\n(ألم يكفكم أن قد منعتم بيوتكم ... كما منع الغيل الأسود النواهت)\n(تصيبون عرضي كل يوم كما علا ... نشيط بفأس معدن البرم ناحت)\nخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال ذكر الهيثم بن عدي عن مجالد بن سعيد عن عبد الملك بن عمير قال كان ابن عباس يكرم أبا الأسود الدؤلي لما كان عاملا لعلي بن أبي طالب عليه السلام على البصرة ويقضي حوائجه فلما ولى ابن عامر جفاه وابعده ومنعه حوائجه لما كان يعلمه من هواه في علي بن أبي طالب عليه السلام فقال فيه أبو الأسود\n(ذكرت ابن عباس بباب ابن عامر ... وما مر من عيشي ذكرت وما فضل)\n(اميرين كانا صاحبي كلاهما ... فكل جزاه الله عني بما فعل)\n(فإن كان شرا كان شرا جزاؤه ... وإن كان خيرا كان خيرا إذا عدل)\nخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن شبيب قال حدثنا إبراهيم بن المنذر الخزامي قال حدثنا محمد بن فليح بن سليمان عن موسى بن عقبة قال قال أبو الأسود الدؤلي لابنه أبي حرب وكان له صديق من باهلة يكثر زيارته فكان أبو الأسود يكرهه ويستريب منه\n(أحبب إذا أحببت حبا مقاربا ... فإنك لا تدري متى أنت نازع)\n(وأبغض إذا أبغضت بغضا مقاربا ... فإنك لا تدري متى أنت راجع)\n(وكن معدنا للحلم واصفح عن الخنا ... فإنك راء ما عملت وسامع)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":7,"spl":"مدحه عبد الرحمن بن أبي بكرة","loc":2283},
{"id":"b141-13","bab":"الجزء 12","sec":"ابو الأسود يشكو جيرانه","page":"ج12 ص369","text":"وقال المدائني حدثني أبو بكر الهذلي قال كان لأبي الأسود جار من بني حليس بن يعمر بن نفاثة بن عدي بن الديل من رهطة دنية ومنزل أبي الأسود يومئذ في بني الديل فأولع جاره برميه بالحجارة كلما أمسى فيؤذيه فشكا أبو الأسود ذلك إلى قومه وغيرهم فكلموه ولاموه فكان ما اعتذر به إليهم أن قال لست أرميه وإنما يرميه الله لقطعه للرحم وسرعته إلى الظلم في بخله بماله فقال أبو الأسود والله ما أجاور رجلا يقطع رحمي ويكذب على ربي فباع داره واشترى دارا في هذيل فقيل له يا أبا الأسود أبعث دارك قال لم أبع داري ولكن بعت جاري فأرسلها مثلا وقال في ذلك\n(رماني جاري ظالما برميه ... فقلت له مهلا فأنكر ما أتى)\n(وقال الذي يرميك ربك جازيا ... بذنبك والحوبات تعقب ما ترى)\n(فقلت له لو أن ربي برمية ... رماني لما اخطا إلهي ما رمى)\n(جزى الله شرا كل من نال سوءة ... وينحل فيها ربه الشر والأذى)\nقال فيه أيضا\n(لحى الله مولى السوء لا أنت راغب ... إليه ولا رام به من تحاربه)\n(وما قرب مولى السوء إلا كبعده ... بل البعد خير من عدو تصاقبه)\nقال فيه أيضا\n(وإني لتثنيني عن الشتم والخنا ... وعن سب ذي القربى خلائق أربع)\n(حياء وإسلام ولطف وأنني ... كريم ومثلي قد يضر وينفع)\n(فإن أعف يوما عن ذنوب أتيتها ... فإن العصا كانت لمثلي تقرع)\n(وشتان ما بيني وبينك إنني ... على كل حال أستقيم وتظلع)\nخبرني عمي قال حدثنا الكراني قال حدثنا الرياشي عن العتبي قال كان لأبي الأسود جار في ظهر داره له باب إلى قبيلة أخرى وكان بين دار أبي الأسود وبين داره باب مفتوح يخرج منه كل واحد منهما إلى قبيلة صاحبه إذا أرادها وكان الرجل ابن عم أبي الأسود دنية وكان شرسا سيء الخلق فأراد سد ذلك الباب فقال له قومه لا تفعل فتضر بأبي الأسود وهو شيخ وليس عليك في هذا الباب ضرر ولا مؤنة فأبى إلا سده ثم ندم على ذلك لأنه اضر به فكان إذا أراد سلوك الطريق التي كان يسلكها منه بعد عليه فعزم على فتحه وبلغ ذلك أبا الأسود فمنعه منه وقال فيه\n(بليت بصاحب إن أذن شبرا ... يزدني في مباعدة ذراعا)\n(وإن أمدد له في الوصل ذرعي ... يزدني فوق قيس الذرع باعا)\n(أبت نفسي له إلا اتباعا ... وتأبى نفسه إلا امتناعا)\n(كلانا جاهد أدنو وينأى ... فذلك ما استطعت وما استطاعا)\nلغناء في هذه الأبيات لأبراهيم ثقيل أول بالبنصر وفيه لعريب خفيف رمل ولعلويه لحن غير منسوب قال وقال أبو الأسود أيضا في ذلك\n(لنا جيرة سدوا المجازة بيننا ... فإن أذكروك السد فالسد أكيس)\n(ومن خير ما ألصقت بالجار حائط ... تزل به سفع الخطا طيف أملس)\nوقال أيضا في ذلك\n(أخطأت حين صرمتني ... والمرء يعجز لا محاله)\n(والعبد يقرع بالعصا ... والحر تكفيه المقالة)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني إسحاق بن محمد النخعي عن ابن عائشة عن أبيه وأخبرني به محمد بن جعفر النحوي قال حدثنا أحمد بن القاسم البزي قال حدثني إسحاق بن محمد النخعي عن ابن عائشة ولم يقبل عن أبيه قال كان أبو الأسود الدؤلي نازلا في بني قشير وكانت بنو قشير عثمانية وكانت امرأته أم عوف منهم فكانوا يؤذونه ويسبونه وينالون من علي عليه السلام بحضرته ليغيظوه به ويرمونه بالليل فإذا أصبح قال لهم يا بني\nقشير أي جوار هذا فيقولون له لم نرمك إنما رماك الله لسوء مذهبك وقبح دينك فقال في ذلك\n(يقول الأرذلون بنو قشير ... طوال الدهر لا تنسى عليا)\n(فقلت لهم وكيف يكون تركي ... من الأعمال مفروضا عليا)\n(أحب محمدا حبا شديدا ... وعباسا وحمزة والوصيا)\n(بني عم النبي وأقربيه ... أحب الناس كلهم إليا)\n(فإن يك حبهم رشدا أصبه ... ولست بمخطيء إن كان غيا)\n(هم أهل النصيحة غير شك ... وأهل مودتي مادمت حيا)\n(هوى أعطيته لما استدارت ... رحى الإسلام لم يعدل سويا)\n(أحبهم لحب الله حتى ... أجئ إذا بعثت على هويا)\n(رأيت الله خالق كل شيء ... هداهم واجتبى منهم نبيا)\n(ولم يخصص بها أحدا سواهم ... هنيئا ما اصطفاه لهم مريا)\nال فقالت له بنو قشير شككت يا أبا الأسود في صاحبك حيث تقول\n(فإن يك حبهم رشدا أصبه ... )\nقال أما سمعتم قول الله عز و جل ( وإنا أو إياكم لعلى هدى أو في ضلال مبين\nأفترى الله جل وعز شك في نبيه وقد روي أن معاوية قال هذه المقالة فأجابه بهذا الجواب","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":8,"spl":"ابو الأسود يشكو جيرانه","song":1,"loc":2284,"partial":1},
{"id":"b141-14","bab":"الجزء 12","sec":"ابو الأسود يشكو جيرانه","page":"ج12 ص369","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو عثمان الأشنانداني عن الأخفش عن ابي عمر الجرمي قال دخل أبو الأسود الدؤلي على معاوية فقال له لقد أصبحت جميلا يا أبا الأسود فلو علقت تميمة تنفي عنك العين فقال أبو الأسود\n(أفنى الشباب الذي فارقت جدته ... كر الجديدين من آت ومنطلق)\n(لم يتركا لي في طول اختلافهما ... شيئا تخاف عليه لذعة الحدق)\nخبرني الحسن بن علي قال حدثني الحارث بن محمد قال قال حدثنا المدائني عن علي بن سليمان قال كان ابو الأسود له على باب داره دكان يجلس عليه مرتفع عن الأرض إلى قدر صدر الرجل فكان يوضع بين يديه خوان على قدر الدكان فإذا مر به مار فدعاه إلى الأكل لم يجد موضعا يجلس فيه فمر به ذات يوم فتى فدعاه إلى الغداء فأقبل فتناول الخوان فوضعه أسفل ثم قال له يا أبا الأسود إن عزمت على الغداء فانزل وجعل يأكل وأبو الأسود ينظر إليه مغتاظا حتى أتى على الطعام فقال له أبو الأسود ما اسمك يا فتى قال لقمان الحكيم قال لقد أصاب أهلك حقيقة اسمك قال المدائني وبلغني رجلا دعاه أبو الأسود إلى طعامه وهو على هذا الدكان فمد يده ليأكل فشب به فرسه فسقط عنه فوقص أخبرني هاشم بن محمد قال حدثنا دماذ عن أبي عبيدة قال كان أبو الجارود سالم بن سلمة بن نوفل الهذلي صديقا لأبي الأسود\nيهاديه الشعر ويجيب كل واحد منهما صاحبه ويتعاشران ويتزاوران فولي أبو الجارود ولاية فجفا أبا الأسود وقطعه ولم يبدأه بالمكاتبة ولا أجابه عنها فقال فيه أبو الأسود\n(أبلغ أبا الجارود عني رسالة ... يروح بها الغادي لربعك أو يغدو)\n(فيخبرنا ما بال صرمك بعد ما ... رضيت وما غيرت من خلق بعد)\n(أأن نلت خيرا سرني أن تناله ... تنكرت حتى قلت ذو لبدة ورد)\n(فعيناك عيناه وصوتك صوته ... تمثله لي غير أنك لا تعدو)\n(لئن كنت قد أزمعت بالصرم بيننا ... لقد جعلت أشراط أوله تبدو)\n(فإني إذا ما صاحب رث وصله ... وأعرض عني قل مني له الوجد)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":9,"spl":"ابو الأسود يشكو جيرانه — أبو الأسود والحارث بن خليد","loc":2285},
{"id":"b141-15","bab":"الجزء 12","sec":"أبو الأسود والحارث بن خليد","page":"ج12 ص374","text":"قال المدائني كان لأبي الأسود صديق يقال له الحارث بن خليد وكان في شرف من العطاء فقال لأبي الأسود ما يمنعك من طلب الديوان فإن فيه غنى وخيرا فقال له أبو الأسود قد أغناني الله عنه بالقناعة والتجمل فقال كلا ولكنك تتركه إقامة على محبة ابن أبي طالب وبغض هؤلاء القوم وزاد الكلام بينهما حتى أغلظ له الحارث بن خليد فهجره أبو الأسود وندم الحارث على ما فرط منه فسأل عشيرته أن تصلح بينهما فأتوا أبا الأسود في ذلك وقالوا له قد اعتذر إليك الحارث مما فرط منه وهو رجل حديد فقال أبو الأسود في ذلك\n(لنا صاحب لا كليل اللسان ... فيصمت عنا ولا صارم)\n(وشر الرجال على أهله ... وأصحابه الحمق العارم)\nقال فيه\n(إذا كان شيء بيننا قيل إنه ... حديد فخالف جهله وترفق)\n(شنئت من الأصحاب من لست بارحا ... وأدامله دمل السقاء المخرق)\nقال المدائني ولى عبيد الله بن زياد الحصين بن أبي الحر العنبري ميسان فدامت ولايته إياها خمس سنين فكتب إليه أبو الأسود كتابا يتصدى فيه لرفده فتهاون به ولم ينظر فيه فرجع إليه رسوله فأخبره بفعله فقال فيه\n(ألا أبلغا عني حصينا رسالة ... فإنك قد قطعت أخرى خلالكا)\n(فلو كنت إذا أصبحت للخرج عاملا ... بميسان تعطى الناس من غير مالكا)\n(سألتك أو عرضت بالود بيننا ... لقد كان حقا واجبا بعض ذلكا)\n(وخبرني من كنت أرسلت أنما ... أخذت كتابي معرضا بشمالكا)\n(نظرت إلى عنوانه ونبذته ... كنبذك نعلا أخلقت من نعالكا)\n(حسبت كتابي إذ أتاك تعرضا ... لسيبك لم يذهب رجائي هنالكا)\n(يصيب وما يدري ويخطي وما درى ... وكيف يكون النوك إلا كذلك)\nبلغت أبيات أبي الأسود حصينا فغضب وقال ما ظننت منزلة أبي الأسود بلغت ما يتعاطاه من مساءتنا وتوعدنا وتوبيخنا فبلغ ذلك أبا الأسود فقال فيه\n(أبلغ حصينا إذا جئته ... نصيحة ذي الرأى للمجتنيها)\n(فلا تك مثل التي استخرجت ... بأظلافها مدية أو بفيها)\n(فقام إليها بها ذابح ... ومن تدع يوما شعوب يجيها)\n(فظلت بأوصالها قدرها ... تحش الوليدة أو تشتويها)\n(وإن تأب نصحي ولا تنتهي ... ولم تر قولي بنصح شبيها)\n(أجرعك صابا وكان المرار ... والصاب قدما شرابا كريها)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":9,"spl":"ابو الأسود يشكو جيرانه — أبو الأسود والحارث بن خليد","loc":2286},
{"id":"b141-16","bab":"الجزء 12","sec":"أبو الأسود ومعاوية بن صعصعة","page":"ج12 ص376","text":"وقال خالد بن كلثوم كان معاوية بن صعصعة يلقى أبا الأسود كثيرا فيحادثه ويظهر له المودة\nوكانت تبلغه عنه قوارص فيذكرها له فيجحدها أو يحلف أنه لم يفعل ثم يعاود ذلك فقال فيه أبو الأسود\n(ولي صاحب قد رابني أو ظلمته ... كذلك ما الخصمان بر وفاجر)\n(وإني امرؤ عندي وعمدا أقوله ... لآتي ما يأتي امرؤ وهو خابر)\n(لسانان معسول عليه حلاوة ... وآخر مسموم عليه الشراشر)\n(فقلت ولم أبخل عليه نصيحتي ... وللمرء ناه لا يلام وزاجر)\n(إذا أنت حاولت البراءة فاجتنب ... عواقب قول تعتريه المعاذر)\n(فكم شاعر أرداه أن قال قائل ... له في اعتراض القول إنك شاعر)\n(عطفت عليه عطفة فتركته ... لما كان يرضى قبلها وهو حاقر)\n(بقافية حداء سهل رويها ... وللقول أبواب ترى ومحاضر)\n(تعزى بها من نومه وهو ناعس ... إذا انتصف الليل المكل المسافر)\n(إذا ما قضاها عاد فيها كأنه ... للذته سكران أو متساكر)\nخبرني عمي قال حدثنا الكراني قال حدثني العمري عن العتبي قال كان عبد الله بن عامر مكرما لأبي الأسود ثم جفاه لما كان عليه من التشيع فقال فيه أبو الأسود\n(ألم تر ما بيني وبين ابن عامر ... من الود قد بالت عليه الثعالب)\n(وأصبح باقي الود بيني وبينه ... كأن لم يكن والدهر فيه عجائب)\n(إذا المرء لم يحببك إلا تكرها ... بدا لك من أخلاقه ما يغالب)\n(فللنأي خير من مقام على أذى ... ولا خير فيما يستقل المعاتب)\nأخبرني محمد بن خلف بن المرزبان قال حدثنا عبيدالله بن محمد قال حدثنا ابن النطاح قال ذكر الحرمازي عن رجل من بني الديل قال كانت لأبي الأسود الدؤلي امرأة من بني قشير وامرأة من عبد القيس فأسن وضعف عما يطيقه الشباب من أمر النساء فأما القشيرية فكانت أقدمهما عنده وأسنهما فكانت موافقة له صابرة عليه وهي أم عوف القشيرية التي يقول فيها\n(أبى القلب إلا أم عوف وحبها ... عجوزا ومن يحبب عجوزا يفند)\n(كسحق يمان قد تقادم عهده ... ورقعته ما شئت في العين واليد)\nأما الأخرى التي من عبد القيس فهي فاطمة بنت دعمي وكانت أشبهما وأجملهما فالتوت عليه لما أسن وتكرت له وساءت عشرتها فقال فيها أبو الأسود\n(تعاتبني عرسي على أن أطيعها ... لقد كذبتها نفسها ما تمنت)\n(وظنت بأني كل ما رضيت به ... رضيت به يا جهلها كيف ظنت)\n(وصاحبتها ما لو صحبت بمثله ... على ذعرها أروية لأطمأنت)\n(وقد غرها مني على الشيب والبلى ... جنوني بها جنت حيالي وحنت)\nقال جن وحن وهو من الأتباع كما يقال حسن بسن\n(ولا ذنب لي قد قلت في بدء أمرنا ... ولو علمت ما علمت ما تعنت)\n(تشكى إلى جاراتها وبناتها ... إذا لم تجد ذنبا علينا تجنت)\n(ألم تعلمي أني إذا خفت جفوة ... بمنزلة أبعدت منها مطيتي)\n(وأني إذا شقت علي حليلتي ... ذهلت ولم أحنن إذا هي حنت)\nفيها يقول\n(أفاطم مهلا بعض هذا التعبس ... وإن كان منك الجد فالصرم مؤنسي)\n(تشتم لي لما رأتني أحبها ... كذي نعمة لم يبدها غير أبؤس)\n(فإن تنقضي العهد الذي كان بيننا ... وتلوي به في ودك المتحلس)\n(فإني فلا يغررك مني تجملي ... لأسلي البعاد بالبعاد المكنس)\n(وأعلم أن الأرض فيها منادح ... لمن كان لم تسدد عليه بمجبس)\n(وكنت أمرأ لاصحبه السوء أرتجي ... ولا أنا نوام بغير معرس)\nقال المدائني كان لأبي الأسود الدؤلي مولى يقال له نافع ويكنى أبا الصباح فذكرت لأبي الأسود جارية تباع فركب فنظر إليها فأعجبته فأرسل نافعا يشتريها له اشتراها لنفسه وغدر بأبي الأسود فقال في ذلك\n(إذا كنت تبغى للأمانة حاملا ... فدع نافعا وانظر لها من يطيقها)\n(فإن الفتى خب كذوب وإنه ... له نفس سوء يجتويها صديقها)\n(متى يخل يوما وحده بأمانة ... تغل جميعا أو يغل فريقها)\n(على أنه أبقى الرجال سمانة ... كما كل مسمان الكلاب سروقها)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":10,"spl":"أبو الأسود ومعاوية بن صعصعة","loc":2287},
{"id":"b141-17","bab":"الجزء 12","sec":"خطبته في موت علي بن أبي طالب","page":"ج12 ص380","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثنا علي بن محمد المدائني عن أبي بكر الهذلي قال أتى أبا الأسود الدؤلي نعي أمير المؤمنين علي بن أبي طالب عليه السلام وبيعه الحسن عليه السلام فقام على المنبر فخطب الناس ونعى لهم عليا عليه السلام فقال في خطبته وإن رجلا من أعداء الله المارقة عن دينه اغتال أمير المؤمنين عليا كرم الله وجهه ومثواه في مسجده وهو خارج لتهجده في ليلة يرجى فيها مصادفة ليلة القدر فقتله فيا لله هو من قتيل وأكرم به وبمقتله وروحه من روح عرجت إلى الله تعالى بالبر والتقى والإيمان والإحسان لقد أطفأ منه نور الله في أرضه لا يبين بعده أبدا وهدم ركنا من أركان الله تعالى لا يشاد مثله فإنا لله وإن إليه راجعون وعند الله نحتسب مصيبتنا بأمير المؤمنين وعليه السلام ورحمة الله يوم ولد ويوم قتل ويوم يبعث حيا ثم بكى حتى اختلفت أضلاعه ثم قال وقد أوصى بالإمامة بعده إلى ابن رسول الله وابنه وسليله وشبيهه في خلقه وهديه وإني لأرجو أن يجبر الله عز و جل به ما وهى ويسد به ما انثلم\nويجمع به الشمل ويطفيء به نيران الفتنة فبايعوه ترشدوا فبايعت الشيعة كلها وتوقف ناس ممن كان يرى رأي العثمانية ولم يظهروا أنفسهم بذلك وهربوا إلى معاوية فكتب إليه معاوية ودس إليه رسولا يعلمه أن الحسن عليه السلام قد راسله في الصلح ويدعوه إلى أخذ البيعة له بالبصرة ويعده ويمنيه فقال أبو الأسود\n(ألا أبلغ معاوية بن حرب ... فلا قرت عيون الشامتينا)\n(أمي شهر الصيام فجعتمونا ... بخير الناس طرا أجمعينا)\n(قتلتم خير من ركب المطايا ... وخيسها ومن ركب السفينا)\n(ومن لبس النعال ومن حذاها ... ومن قرأ المثاني والمئينا)\n(إذا استقبلت وجه أبي حسين ... رأيت الدر راق الناظرينا)\n(لقد علمت قريش حيث حلت ... بأنك خيرها حسبا ودينا)\nخبرني أبو الحسن الأسدي قال حدثنا الرياشي عن الهيثم بن عدي عن أبي عبيدة قال كان أبو حرب بن أبي الأسود قد لزم منزل أبيه بالبصرة لا ينتجع أرضا ولا يطلب الرزق في تجارة ولا غيرها فعاتبه على ذلك فقال أبو حرب إن كان لي رزق فسيأتيني فقال له\n(وما طلب المعيشة بالتمني ... ولكن ألق دلوك في الدلاء)\n(تجئك بملئها يوما ويوما ... وتجئك بحمأة وقليل ماء)\nوقال المدائني كانت لأبي الأسود مولاة يقال لها لطيفة وكان لها عبد تاجر يقال له ملم فابتاعت له أمة وأنكحته إياها فجاءت بغلام فسمته زيدا فكانت تؤثره على كل أحد وتجد به وجد الأم بولدها وجعلته على ضيعتها فقال فيه أبو الأسود وقد مرضت لطيفة\n(وزيد هالك هلك الحبارى ... إذا هلكت لطيفة أو ملم)\n(تبنته فقال وأنت أمي ... فأنى بعدها لك زيد أم)\n(ترم متاعه وتزيد فيه ... وصاحبها لما يحوى مضم)\n(ستلقى بعدها شرا وضرا ... وتقصى إن قربت فلا تضم)\n(وتلقاك الملامة كل وجه ... سلكت وينتحي حاليك ذم)\nال فماتت لطيفة من علتها تلك وورثها أبو الأسود فطرد زيدا عما كان يتولاه من ضيعتها وطالبه بما خانه من مالها فارتجعه فكان بعد ذلك ضائعا مهانا بالبصرة كما قال فيه وتوعده وقال المدائني أيضا أشترى أبو الأسود أمة للخدمة فجعلت تتعرض منه للنكاح وتتطيب وتشتمل بثوبها فدعاها أبو الأسود فقال لها اشتريتك للعمل والخدمة ولم اشترك للنكاح فأقبلي على خدمتك وقال فيها\n(أصلاح إني لا أريدك للصبا ... فدعى التشمل حولنا وتبذلي)\n(إني أريدك للعجين وللرحا ... ولحمل قربتنا وغلي المرجل)\n(وإذا تروح ضيف أهلك أوغدا ... فخذي لآخر أهبة المستقبل)\nخبرنا الحسن بن الطيب الشجاعي قال حدثنا ابو عشانة عن ابن عباس قال كان المنذر بن الجارود العبدي صديقا لأبي الأسود الدؤلي تعجبه مجالسته وحديثه وكان كل واحد منهما يغشى صاحبه وكانت لأبي الأسود مقطعة من برود بكثر لبسها فقال له المنذر لقد أدمنت لبس هذه المقطعة فقال له أبو الأسود رب مملول لا يستطاع فراقه فعلم المنذر أنه قد احتاج إلى كسوة فأهدى له ثياب فقال أبو الأسود يمدحه\n(كساك ولم تستكسه فحمدته ... أخ لك يعطيك الجزيل وناصر)\n(وإن أحق الناس إن كنت حامدا ... بحمدك من أعطاك والعرض وافر)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":11,"spl":"خطبته في موت علي بن أبي طالب","loc":2288},
{"id":"b141-18","bab":"الجزء 12","sec":"وصيته لابنه","page":"ج12 ص383","text":"أنشدني محمد بن العباس اليزيدي عن عمه عبيد الله عن ابن حبيب لأبي الأسود يوصي ابنه وفي هذه الأبيات غناء\n(لا ترسلن رسالة مشهورة ... لا تستطيع إذا مضت إدراكها)\n(أكرم صديق أبيك حيث لقيته ... واحب الكرامة من بدا فحباكها)\n(لاتبدين نميمة حدثتها ... وتحفظن من الذي أنباكها)\nأخبرني محمد بن خلف بن مرزبان قال حدثنا أبو محمد المروزي عن القحذمي عن بعض الرواة أن أبا الأسود الدؤلي اعتذر إلى زياد في شيء جرى بينهما فكأنه لم يقبل عذره فأنشأ يقول\n(إنني مجرم وأنت أحق الناس ... أن تقبل الغداة اعتذاري)\n(فاعف عني فقد سفهت وأنت المرء ... تعفو عن الهنات الكبار)\nتبسم زياد وقال أما إذا كان هذا قولك فقد قبلت عذرك وعفوت عن ذنبك أخبرني هاشم بن محمد قال حدثني عبد الرحمن ابن أخي الأصمعي عن عمه عن عيسى بن عمر قال سئل أبو الأسود عن رجل واستشير في أن يولى ولاية فقال أبو الأسود هو ما علمته أهيس أليس ألد ملحس أن اعطى انتهر وإن سئل أزر قال الأصمعي الأهيس الحاد ويقال في المثل\n(إحدى لياليك فهيسى هيسي ... )\nال ويقال ناقة ليساء إذا كانت لا تبرح من المبرك قال وهو مما يوصف به الشجاع وأنشد في صفة ثور\n(أليس عن حوبائه سخي ... )\nخبرني أحمد بن محمد بن عمران الصيرفي قال حدثنا الحسن بن عليل العنزي قال حدثني أحمد بن الأسود بن الهيثم الحنفي قال حدثنا أبو محلم عن مؤرج السدوسي عن عبد الحميد بن عبد الله بن مسلم بن يسار قال وكان من أفصح أهل زمانه قال أوصى أبو الأسود الدؤلي كاتبا لعبد الله بن عامر بحاجة له فضمن له قضاءها ثم لم يصنع فيها شيئا فقال أبو الأسود\n(لعمري لقد أوصيت أمس بحاجتي ... فتى غير قصد علي ولا رؤف)\n(ولا عارف ما كان بيني وبينه ... ومن خير ما أدلى به المرء ما عرف)\n(وما كان ما أملت منه ففاتني ... بأول خير من أخي ثقة صرف)\nأخبرني هاشم بن محمد الخزاعي قال حدثني محمد بن القاسم مولى بني\nهشام قال حدثني أبو زيد الأنصاري سعيد بن أوس قال حدثني بكر بن حبيب السهمي عن أبيه وكان من جلساء أبي الأسود الدؤلي قال كان أبو الجارود سالم بن سلمة بن نوفل الهذلي شاعرا وكان صديقا لأبي الأسود الدؤلي فكان يهاديه الشعر ثم تغير ما بينهما فقال فيه أبو الأسود\n(أبلغ أبا الجارود عني رسالة ... يروح بها الماشي ليلقاك أو يغدو)\n(فيخبرنا ما بال صرمك بعد ما ... رضيت وما غيرت من خلق بعد)\n(أأن نلت خيرا سرني حين نلته ... تنكرت حتى قلت ذو لبدة ورد)\n(فعيناك عيناه وصوتك صوته ... تمثله لي غير أنك لا تعدو)\n(فإن كنت قد أزمعت بالصرم بيننا ... وقد جعلت أسباب أوله تبدو)\n(فإني إذا ما صاحب رث وصله ... وأعرض عني قلت بالأبعد الفقد)","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":12,"spl":"وصيته لابنه — وفاة ابي الأسود","song":1,"loc":2289,"partial":1},
{"id":"b141-19","bab":"الجزء 12","sec":"وفاة ابي الأسود","page":"ج12 ص386","text":"وكانت وفاة أبي الأسود فيما ذكره المدائني في الطاعون الجارف سنة تسع وستين وله خمس وثمانون سنة قال المدائني وقد قيل إنه مات قبل ذلك وهو أشبه القولين بالصواب لأنا لم نسمع له في فتنة مسعود وأمر المختار بذكر وذكر مثل هذا القول بعينه والشك فيه هل أدرك الطاعون الجارف أولا عن يحيى بن معين أخبرني به الحسن بن علي عن أحمد بن زهير عن المدائني ويحيى بن معين\n\n(لعمرك أيها الرجل ... لأي الشكل تنتقل)\n(أتهجر آل زينب أم ... تزورهم فتعتدل)\n(هم ركب لقوا ركبا ... كما قد تجمع السبل)\n(فذلك وأبنا وبذاك ... تجرى بيننا الرسل)\nلشعر لأبي نفيس بن يعلى بن منية والغناء لمعبد خفيف ثقيل أول بالسبابة في مجرى الوسطى وفيه لابن سريج رمل بالوسطى ولجميلة خفيف رمل بالبنصر","topic":"أخبار أبي الأسود الدؤلي ونسبه","topicNo":141,"sp":12,"spl":"وصيته لابنه — وفاة ابي الأسود","song":1,"loc":2290},
{"id":"b142-1","bab":"الجزء 12","sec":"أخبار أبي نفيس ونسبه","page":"ج12 ص387","text":"اسمه حيي بن يحيى بن يعلى بن منية وقيل بل اسم أبي نفيس يحيى بن ثعلبة بن منية ومنية أمه ذكر ذلك الزبير بن بكار عن عمرو بن يحيى بن عبد الحميد قال الزبير وكان عمي يقول اسمه ميمون بن يعلى وأمه منية بنت غزوان أخت عتبة بن غزوان وأبوه أمية بن عبدة بن همام بن جشم بن بكر بن زيد بن مالك بن حنظلة بن مالك بن زيد مناة بن تميم وجدت ذلك بخط أبي محلم النسابة قال ويقال لبنى زيد بن مالك بنو العدوية وهي فكيهة بنت تميم بن الدئل بن حسل بن عدي بن عبد مناة بن تميم ولدت لمالك بن حنظلة زيدا وصديا ويربوعا فهم يدعون بني العدوية","topic":"أخبار أبي نفيس ونسبه","topicNo":142,"sp":0,"spl":"أخبار أبي نفيس ونسبه","loc":2291},
{"id":"b142-2","bab":"الجزء 12","sec":"بعض أخبار جده يعلى بن منية","page":"ج12 ص388","text":"وكان يعلى بن منية حليفا لبني أمية وعديدا لهم وبينه وبينهم صهر ومناسبة وقد أدرك النبي وسمع منه حديثا كثيرا وروى عنه حديثا كثيرا\nوعمر بعده وكان مع عائشة يوم الجمل على أمير المؤمنين علي بن أبي طالب عليه السلام أخبرني عمي ال حدثنا أحمد بن الحارث قال حدثنا المدائني عن ابي مخنف عن عبد الرحمن بن عبيد عن أبي الكنود قال قال علي بن أبي طالب رضي الله عنه منيت أو بليت بأطوع الناس في الناس عائشة وبأدهى الناس طلحة وبأشجع الناس الزبير وبأكثر الناس مالا يعلى بن منية وبأجود قريش عبد الله بن عامر فقام إليه رجل من الأنصار فقال والله يا أمير المؤمنين لأنت أشجع من الزبير وأدهى من طلحة وأطوع فينا من عائشة وأجود من ابن عامر ولمال الله أكثر من مال يعلى بن منية وليكونن كما قال الله جل وعز ( فسينفقونها ثم تكون عليهم حسرة ثم يغلبون\nفسر علي بن أبي طالب رضي الله عنه بقوله ثم قام إليه رجل آخر منهم فقال\n(أما الزبير فأكفيكه ... وطلحة يكفيكه وحوحه)\n(ويعلى بن منية عند القتال ... شديد التثاؤب والنحنحه)\n(وعايش يكفيكها واعظ ... وعائش في الناس مستنصحه)\n(فلا تجزعن فإن الأمور ... إذا ما أتيناك مستنجحه)\n(وما يصلح الأمر إلا بنا ... كما يصلح الجبن بالإنفحه)\nال فسر علي عليه السلام بقوله ودعا له وقال بارك الله فيك قال فأما الزبير فناشده علي عليه السلام فرجع فقتله بنو تميم وأما طلحة فناشده وحوحة وكان صديقه وكان من القراء فذهب لينصرف فرماه رجل من\nعسكرهم فقتله فأم ما رواه عن النبي فكثير ولكني أذكر منه طرفا كما ذكرت لغيره أخبرني أحمد بن الجعد قال حدثني محمد بن عباد المكي قال حدثنا سفيان بن عيينة عن عمرو بن دينار عن عطاء بن أبي رباح عن صفوان بن يعلى ابن منية عن أبيه أنه سمع النبي يقرأ على المنبر ( ونادوا يا مالك ليقض علينا ربك\nوقد روى يعلى عنه حديثا كثيرا اقتصرت منه على هذا لتعرف روايته عنه أخبرني أحمد بن عبيد الله بن عمار قال حدثنا سليمان بن أبي شيخ قال حدثنا محمد بن الحكم عن أبي مخنف قال أقرض يعلى بن منية الزبير بن العوام حين خرج إلى البصرة في وقعة الجمل أربعين ألف دينار فقضاها ابن الزبير بعد ذلك لأن أباه قتل يومئذ ولم يقضه إياها قال ولما صاروا إلى البصرة تنازع طلحة والزبير في الصلاة فاتفقا على أن يصلي ابن هذا يوما وابن هذا يوما وقال شاعرهم في ذلك\n(تبارى الغلامان إذ صليا ... وشح على الملك شيخاهما)\n(وما لي وطلحة وابن الزبير ... وهذا بذي الجزع مولاهما)\n(فأمهما اليوم غرتهما ... ويعلى بن منية دلاهما)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني محمد بن يحيى عن جده عبد الحميد قال\nكان يعلى بن منية ويكنى أبا نفيس وسمعت غير جدي يقول اسمه يحيى وهو من بني العدوية من بني تميم من بني حنظلة تزوج امرأة من بني مالك بن كنانة يقال لها زينب ولهم حلف في بني غفار وهي من بنات طارق اللاتي يقلن\n(نحن بنات طارق ... نمشي على النمارق)\nتوفيت بتهامة فقال يرثيها\n(يا رب رب الناس لما نحبوا ... وحين أفضلوا من منى وحصبوا)\n(لا يسقين ملح وعليب ... والمستراد لا سقاه الكوكب)\n(من أجل حماهن ماتت زينب ... )\nال الزبير وأنشدنيها عمي مصعب لأبي نفيس بن يعلى بن منية قال واسمه ميمون وكان عمي يقول اسم أبي نفيس ميمون بن يعلى وقال في الأبيات\n(لا يسقين عنبب وعليب ... )\nأخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن يحيى عن جده غسان بن عبد الحميد قال رأت عائشة زوج النبي بنات طارق اللواتي يقلن\n(نحن بنات طارق ... نمشي على النمارق)\nفقالت أخطأ من يقول الخيل أحسن من النساء قال وقالت هند بنت عتبة لمشركي قريش يوم أحد\n(نحن بنات طارق ... نمشي على النمارق)\n(الدر في المخانق ... والمسك في المفارق)\n(إن تقبلوا نعانق ... أو تدبروا نفارق)\n(فراق غير وامق ... )\nخبرني الحرمي قال حدثنا الزبير قال حدثني محمد بن يحيى بن عبد الملك الهديري قال\nجلست ليلة وراء الضحاك بن عثمان الحزامي في مسجد رسول الله وأنا متقنع فذكر الضحاك وأصحابه قول هند يوم أحد\n(نحن بنات طارق ... )\nقال وما طارق فقلت النجم فالتفت الضحاك فقال أبا زكريا وكيف بذاك فقلت قال الله عز و جل ( والسماء والطارق وما أدراك ما الطارق النجم الثاقب","topic":"أخبار أبي نفيس ونسبه","topicNo":142,"sp":1,"spl":"بعض أخبار جده يعلى بن منية","loc":2292,"partial":1},
{"id":"b142-3","bab":"الجزء 12","sec":"بعض أخبار جده يعلى بن منية","page":"ج12 ص388","text":"فقالت إنما نحن بنات النجم فقال أحسنت\n(خليلي قوما في عطالة فانظرا ... أنارا أرى من نحو يبرين أم برقا)\n(فإن يك برقا فهو في مشمخرة ... تغادر ماء لا قليلا ولا طرقا)\n(وإن تك نارا فهي نار بملتقى ... من الريح تسفيها وتصفقها صفقا)\nيروى تزهاها وتعفقها عفقا\n(لأم علي أوقدتها طماعة ... لأوبة سفر أن تكون لهم وفقا)\nلشعر لسويد بن كراع والغناء لابن محرز خفيف ثقيل أول بالوسطى عن يحيى المكي وذكره غيره أنه لابن مسحج","topic":"أخبار أبي نفيس ونسبه","topicNo":142,"sp":2,"spl":"بعض أخبار جده يعلى بن منية","song":1,"loc":2293},
{"id":"b143-1","bab":"الجزء 12","sec":"أخبار سويد بن كراع ونسبه","page":"ج12 ص395","text":"سويد بن كراع العكلي أحد بني الحارث بن عوف بن وائل بن قيس بن عكل شاعر فارس مقدم من شعراء الدولة الأموية وكان في آخر أيام جرير والفرزدق وذكر محمد بن سلام في كتاب الطبقات فيما أخبرنا عنه أبو خليفة قال كان سويد بن كراع شاعرا محكما وكان رجل بني عكل وذا الرأي والتقدم فيهم وعكل وضبة وعدي وتيم هم الرباب قال وكان بعض بني عدي ضرب رجلا من بني ضبة ثم من بني السيد وهم قوم نكد شرس وهم أخوال الفرزدق فاجتمعوا حتى ألم أن يكون بينهم شر فجاء رجل من بني عدي فأعطى يده رهينة لينظروا ما يصنع المضروب فقال خالد بن علقمة ابن الطيفان حليف بني عبد الله بن دارم\n(أسالم إني لا إخالك سالما ... أتيت بني السيد الغواة الأشائما)\n(أسالم إن أفلت من شر هذه ... فوائل فرارا إنما كنت حالما)\n(أسالم ما أعطى ابن مامة مثلها ... ولا حاتم فيما بلا الناس حاتما)\nقال سويد بن كراع يجيبه عن ذلك\n(أشاعر عبد الله إن كنت لائما ... فإني لما تأتي من الأمر لائم)\n(تحضض أفناء الرباب سفاهة ... وعرضك موفور وليلك نائم)\n(وهل عجب أن تدرك السيد وترها ... وتصبر للحق السراة الأكارم)\n(رأيتك لم تمنع طهية حكمها ... وأعطيت يربوعا وأنفك راغم)\n(وأنت امرؤ لا تقبل النصح طائعا ... ولكن متى تقهر فإنك رائم)\nوجدت هذا الخبر في رواية أبي عمرو الشيباني أتم منه هاهنا وأوضح فذكرته قال كان بين بني السيد بني مالك من ضبة وبين عدي بن عبد مناة ترام على خبراء بالصمان يقال لها ذات الزجاج فرمي عمرو بن حشفة أخو بني شبيم فمات ورمت بنو السيد رجلا منهم يقال له مدلج بن صخر العدوي فمكث أياما لم يمت فمر رجل من بني عدي يقال له معلل\nعلى بني السيد وهو لا يعلم الخبر فأخذوه فشدوه وثاقا فأفلت منهم ومشى بينهم عصمة بن أبير التيمي سفيرا فقال لسالم بن فلان العدوي لو رهنتهم نفسك فإن مات مدلج كان رجل برجل وإن لم يمت حملت دية صاحبهم ففعل ذلك سالم على أن يكون عند أخثم بن حميري أخي بني شبيم من بني السيد فكان عنده ثم إن بني السيد لما أبطأ عليهم موت مدلج أتوا أخثم لينتزعوا منه سالما ويقتلوه فقوض عليه أخثم بيته ثم قال يا آل أمي وكانت أمه من بني عبد مناة بن بكر فمنعه عبد مناة ثم إن بني السيد قالوا لأخثم إلى كم تمنع هذا الرجل أما الدية فوالله لا نقبلها أبدا فجعل لهم أجلا إن لم يمت مدلج فيه دفع إليهم سالما فقتلوه به فلما كان قبل ذلك الأجل بيوم مات مدلج فقتلوا سالما فقال في ذلك خالد بن علقمة أخو بني عبد الله بن دارم وهو ابن الطيفان\n(أسالم ما منتك نفسك بعدما ... أتيت بني السيد الغواة الأشائما)\n(أسالم قد منتك نفسك أنما ... تكون ديات ثم ترجع سالما)\n(كذبت ولكن ثائر متبسل ... يلقيك مصقول الحديدة صارما)\n(أسالم ما أعطى ابن مامة مثلها ... ولا حاتم فيما بلا الناس حاتما)\n(أسالم إن أفلت من شر هذه ... فوائل فرارا إنما كنت حالما)\n(وقد أسلمت تيم عديا فأربعت ... ودلت لأسباب المنية سالما)\nأجابه سويد بن كراع بالأبيات التي ذكرها ابن سلام وزاد فيها أبو عمرو\n(دعوتم إلى أمر النواكة دارما ... فقد تركتم والنواكة دارم)\n(وكنت كذات البو شرمت استها ... فطابقت لما خرمتك الغمائم)\n(فلو كنت مولى سلت ما تجللت ... به ضبع في ملتقى القوم واحم)\n(ولم يدرك المقتول إلا مجره ... وما أسأرت منه النسور القشاعم)\n(عليك ابن عوف لا تدعه فإنما ... كفاك موالينا الذي جر سالم)\n(أتذكر أقواما كفوك شئونهم ... وشأنك إلا تركه متفاقم)\nال وقال سويد بن كراع في ذلك\n(أرى آل يربوع وأفناء مالك ... أعضوك في الحرب الحديد المنقبا)\n(هم رفعوا فأس اللجام فأدركت ... لهاتك حتى لم تدع لك مشربا)\n(فإن عدت عادوا بالتي ليس فوقها ... من الشر إلا أن تبيت محجبا)\n(وتصبح تدرى الكعكبية قاعدا ... وينتف من ليتيك ما كان أزغبا)\nدري تمشط بالمدرى كما يفعل بالنساء والكعكبية مشطة معروفة\n(فهل سألوا فينا سواء الذي لهم ... وهل نحن أعطينا سواه فتعجبا)\nويروى\n(فهل سألونا خصلة غير حقهم ... )\nهو أجود قال فاستعدت بنو عبد الله سعيد بن عثمان بن عفان على سويد بن كراع في هجائه إياهم فطلبه ليضربه ويحبسه فهرب منه ولم يزل متواريا حتى كلم فيه فأمنه على ألا يعاود فقال سويد بن كراع\n(تقول ابنة العوفي ليلى ألا ترى ... إلى ابن كراع لا يزال مفزعا)","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":0,"spl":"أخبار سويد بن كراع ونسبه","loc":2294,"partial":1},
{"id":"b143-2","bab":"الجزء 12","sec":"أخبار سويد بن كراع ونسبه","page":"ج12 ص395","text":"(مخافة هذين الأميرين سهدت ... رقادي وغشتني بياضا تفرعا)\n(على غير جرم غير أن جار ظالم ... علي فجهزت القصيد المفرعا)\n(وقد هابني الأقوام لما رميتهم ... بفاقرة إن هم أن يتشجعا)\n(أبيت بأبواب القوافي كأنما ... أصادي بها سربا من الوحش نزعا)\n(أكالئها حتى أعرس بعدما ... يكون سحير أو بعيد فأهجعا)\n(فجشمني خوف ابن عثمان ردها ... ورعيتها صيفا جديدا ومربعا)\n(نهاني ابن عثمان الإمام وقد مضت ... نوافذ لو تردي الصفا لتصدعا)\n(عوارق ما يتركن لحما بعظمه ... ولا عظم لحم دون أن يتمزعا)\n(أحقا هداك الله أن جار ظالم ... فأنكر مظلوم بأن يؤخذا معا)\n(وأنت ابن حكام أقاموا وقوموا ... قرونا وأعطوا نائلا غير أقطعا)","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":1,"spl":"أخبار سويد بن كراع ونسبه — تم الجزء الثاني عشر ويليه الجزء الثالث عشر","loc":2295},
{"id":"b143-3","bab":"الجزء 12","sec":"ينتجع بقومه أرض بني تميم","page":"ج12 ص400","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي عن حماد الراوية قال انتجع سويد بن كراع بقومه أرض بني تميم فجاور بني قريع بن عوف بن كعب بن سعد بن زيد مناة بن تميم فأنزله بغيض بن عامر بن شماس بن لأي بن أنف الناقة بن قريع وأرعاه ووصله وكساه فلم يزل مقيما فيهم حتى أحيا ثم ودعهم وأتى بغيضا وهو في نادي قومه وقد مدحه فأنشده قوله قال حماد ومن لا يعلم يروي هذه القصيدة للحطيئة لكثرة مدحه بغيضا وهي لسويد بن كراع\n(ارتعت للزور إذ حيا وأرقني ... ولم يكن دانيا منا ولا صددا)\n(ودونه سبسب تنضى المطى به ... حتى ترى العنس تلقى رحلها الأجدا)\n(إذا ذكرتك فاضت عبرتي دررا ... وكاد متكوم قلبي يصدع الكبدا)\n(وذاك مني هوى قد كان أضمره ... قلبي فما ازداد من نقص ولا نفذا)\n(وقد أرانا وحال الناس صالحة ... نحتل مربوعة أدمان أو بردى)\n(ليت الشباب وذاك العصر راجعنا ... فلم نزل كالذي كنا به أبدا)\n(أيام أعلم كم أعملت نحوكم ... من عرمس عاقد لم ترأم الولدا)\n(تصيخ عند السرى في البيد سامية ... سطعاء تنهض في ميتائها صعدا)\n(كأن رحلي على حمش قوائمه ... برمل عرنان أمسى طاويا وحدا)\n(هاجت عليه من الجوزاء سارية ... وطفاء تحمل جونا مردفا نضدا)\n(فألجأته إلى أرطاة عانكة ... فيحاء ينهال منها ترب ما التبدا)\n(تخال عطفيه من جول الرذاذ به ... منظما بيدي دارية فردا)\n(حتى إذا ما انجلت عنه دجنته ... وكشف الصبح عنه الليل فاطردا)\n(غدا كذي التاج حلته أساورة ... كأنما اجتاب في حر الضحى سندا)\nوهي طويلة اختصرتها يقول فيها\n(لا يبعد الله إذ ودعت أرضهم ... أخي بغيضا ولكن غيره بعدا)\n(لا يبعد الله من يعطي الجزيل ومن ... يحبو الخليل وما أكدى وما صلدا)\n(ومن تلاقيه بالمعروف معترفا ... إذا أجرهد صفا المذموم أو صلدا)\n(لاقيته مفضلا تندى أنامله ... إن يعطك اليوم لا يمنعك ذاك غدا)\n(تجيء عفوا إذا جاءت عطيته ... ولا تخالط ترنيقا ولا زهدا)\n(أولاه بالمفخر الأعلى وأعظمه ... خلقا وأوسعه خيرا ومنتفدا)\n(إذا تكلف أقوام صنائعه ... لاقوا ولم يظلموا من دونها صعدا)\n(بحر إذا نكس الأقوام أو ضجروا ... لاقيت خير يديه دائما رغدا)\n(لا يحسب المدح خدعا حين تمدحه ... ولا يرى البخل منهاه له أبدا)\n(إني لرافده ودي ومنصرتي ... وحافظ غيبه إن غاب أو شهدا)\n\n(حنتني حانيات الدهر حتى ... كأني خاتل يدنوا لصيد)\n(قريب الخطو يحسب من رآني ... ولست مقيدا أني بقيد)\nعروضه من الوافر الخاتل الذي يتقتر للصيد وينحني حتى لا يرى ويقال لكل من أراد خداع صيد أو إنسان ختله ورى أمره فلم يظهره ومن رواه كأني حابل فإنه يعني الذي ينصب حبالة للصيد الشعر لأبي الطمحان القيني والغناء لإبراهيم ماخوري وهو خفيف الثقيل الثاني بالوسطى وذكر ابن حبيب أن هذا الشعر للمسجاح بن سباع الضبي فإن كن ذلك على ما قال فلأبي الطمحان ما يغني فيه من شعره ولا يشك فيه أنه له قوله\n(أضاءت لهم أحسابهم ووجوههم ... دجى الليل حتى نظم الجزع ثاقبه)\nلغناء لعريب ثاني ثقيل وخفيف رمل وذكر ابن المعتز أن خفيف الرمل لها وأن الثقيل الثاني لغيرها","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":1,"spl":"أخبار سويد بن كراع ونسبه — تم الجزء الثاني عشر ويليه الجزء الثالث عشر","song":2,"loc":2296},
{"id":"b143-4","bab":"الجزء 12","sec":"تم الجزء الثاني عشر ويليه الجزء الثالث عشر","page":"ج12 ص403","text":"وأوله أخبار أبي الطمحان القيني\nبسم الله الرحمن الرحيم","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":1,"spl":"أخبار سويد بن كراع ونسبه — تم الجزء الثاني عشر ويليه الجزء الثالث عشر","loc":2297},
{"id":"b143-5","bab":"الجزء 12","sec":"أخبار أبي الطمحان القيني","page":"ج12 ص403","text":"أبو الطمحان اسمه حنظلة بن الشرقي أحد بني القين بن جسر بن شيع الله من قضاعة وقد تقدم هذا النسب في عدة مواضع من الكتاب في أنساب شعرائهم وكان أبو الطمحان شاعرا فارسا خاربا صعلوكا وهو من المخضرمين أدرك الجاهلية والإسلام فكان خبيث الدين فيهما كما يذكر وكان تربا للزبير بن عبد المطلب في الجاهلية ونديما له أخبرنا بذلك أبو الحسن الأسدي عن الرياشي عن أبي عبيدة","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":2,"spl":"أخبار أبي الطمحان القيني","loc":2298},
{"id":"b143-6","bab":"الجزء 13","sec":"قيسبة السكوني يقع في أسر بني عقيل","page":"ج13 ص5","text":"ومما يدل على أنه قد أدرك الجاهلية ما ذكره ابن الكلبي عن أبيه قال خرج قيسبة بن كلثوم السكوني وكان ملكا يريد الحج وكانت العرب تحج في الجاهلية فلا يعرض بعضها لبعض فمر ببني عامر بن عقيل فوثبوا\nعليه فأسروه وأخذوا ماله وما كان معه وألقوه في القد فمكث فيه ثلاث سنين وشاع باليمن أن الجن استطارته فبينا هو في يوم شديد البرد في بيت عجوز منهم إذ قال لها أتأذنين لي أن آتي الأكمة فأتشرق عليها فقد أضر بي القر فقالت له نعم وكانت عليه جبة من حبرة لم يترك عليه غيرها فتمشى في أغلاله وقيوده حتى صعد الأكمة ثم أقبل يضرب ببصره نحو اليمن وتغشاه عبرة فبكى ثم رفع طرفه إلى السماء وقال اللهم ساكن السماء فرج لي مما أصبحت فيه فبينا هو كذلك إذ عرض له راكب يسير فأشار إليه أن أقبل فأقبل الراكب فلما وقف عليه قال له ما حاجتك يا هذا قال أين تريد قال أريد اليمن قال ومن أنت قال أنا أبو الطمحان القيني فاستعبر باكيا فقال له أبو الطمحان من أنت فإني أرى عليك سيما الخير ولباس الملوك وأنت بدار ليس فيها ملك قال أنا قيسبة بن كلثوم السكوني خرجت عام كذا وكذا أريد الحج فوثب علي هذا الحي فصنعوا بي ما ترى وكشف عن أغلاله وقيوده فاستعبر أبو الطمحان فقال له قيسبة\nهل لك في مائة ناقة حمراء قال ما أحوجني إلى ذلك قال فأنخ فأناخ ثم قال له أمعك سكين قال نعم قال ارفع لي عن رحلك فرفع له عن رحله حتى بدت خشبة مؤخره فكتب عليها قيسبة بالمسند وليس يكتب به غير أهل اليمن - خفيف -\n(بلغا كندة الملوك جميعا ... حيث سارت بالأكرمين الجمال)\n(أن ردوا العين بالخميس عجالا ... واصدروا عنه والروايا ثقال)\n(هزئت جارتي وقالت عجيبا ... إذ رأتني في جيدي الأغلال)\n(إن تريني عاري العظام أسيرا ... قد براني تضعضع واختلال)\n(فلقد أقدم الكتيبة بالسيف ... علي السلاح والسربال)\n- خفيف - وكتب تحت الشعر إلى أخيه أن يدفع إلى أبي الطمحان مائة ناقة ثم قال له أقرئ هذا قومي فإنهم سيعطونك مائة ناقة حمراء فخرج تسير به\nناقته حتى أتى حضرموت فتشاغل بما ورد له ونسي أمر قيسبة حتى فرغ من حوائجه ثم سمع نسوة من عجائز اليمن يتذاكرن قيسبة ويبكين فذكر أمره فأتى أخاه الجون بن كلثوم وهو أخوه لأبيه وأمه فقال له يا هذا إني أدلك على قيسبة وقد جعل لي مائة من الإبل قال له فهي لك فكشف عن الرحل فلما قرأه الجون أمر له بمائة ناقة ثم أتى قيس بن معد يكرب الكندي أبا الأشعث بن قيس فقال له يا هذا إن أخي في بني عقيل أسير فسر معي بقومك فقال له أتسير تحت لوائي حتى أطلب ثأرك وأنجدك وإلا فامض راشدا فقال له الجون مس السماء أيسر من ذلك وأهون علي مما خيرته وضجت السكون ثم فاءوا ورجعوا وقالوا له وما عليك من هذا هو ابن عمك ويطلب لك بثأرك فأنعم له بذلك وسار قيس وسار الجون معه تحت لوائه وكندة والسكون معه فهو أول يوم اجتمعت فيه السكون وكندة لقيس وبه أدرك الشرف فسار حتى أوقع بعامر بن عقيل فقتل منهم مقتلة عظيمة واستنقذ قيسبة وقال في ذلك سلامة بن صبيح الكندي - السريع -\n(لا تشتمونا إذا جلبنا لكم ... ألفي كميت كلها سلهبه)\n(نحن أبلنا الخيل في أرضكم ... حتى ثأرنا منكم قيسبة)\n(واعترضت من دونهم مذحج ... فصادفوا من خيلنا مشغبه)\n- السريع - حدثنا إبراهيم بن محمد بن أيوب قال حدثنا عبد الله بن مسلم قال بلغني أن أبا الطمحان القيني قيل له وكان فاسقا خاربا ما أدنى ذنوبك قال ليلة الدير قيل له وما ليلة الدير قال نزلت بديرانية فأكلت عندها طفيشلا بلحم خنزير وشربت من خمرها وزنيت بها وسرقت كساءها ثم انصرفت عنها أخبرني عمي قال حدثني محمد بن عبد الله الحزنبل عن عمرو بن أبي عمرو الشيباني عن أبيه قال جنى أبو الطمحان القيني جناية وطلبه السلطان فهرب من بلاده ولجأ إلى بني فزارة فنزل على رجل منهم يقال له مالك بن سعد أحد بني شمخ فآواه وأجاره وضرب عليه بيتا وخلطه بنفسه فأقام مدة ثم تشوق يوما إلى أهله وقد شرب شرابا ثمل منه فقال لمالك لولا أن يدي تقصر عن دية جنايتي لعدت إلى أهلي فقال له هذه إبلي فخذ\nمنها دية جنايتك واردد ما شئت فلما أصبح ندم على ما قاله وكره مفارقة موضعه ولم يأمن على نفسه فأتى مالكا فأنشده - وافر -\n(سأمدح مالكا في كل ركب ... لقيتهم وأترك كل رذل)\n(فما أنا والبكارة أو مخاض ... عظام جلة سدس وبزل)","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":3,"spl":"قيسبة السكوني يقع في أسر بني عقيل","loc":2299},
{"id":"b143-7","bab":"الجزء 13","sec":"قيسبة السكوني يقع في أسر بني عقيل","page":"ج13 ص5","text":"(وقد عرفت كلابكم ثيابي ... كأني منكم ونسيت أهلي)\n(نمت بك من بني شمخ زناد ... لها ما شئت من فرع وأصل)\n- وافر - قال فقال مالك مرحبا فإنك حبيب ازداد حبا إنما اشتقت إلى أهلك وذكرت أنه يحبسك عنهم ما تطالب به من عقل أو دية فبذلت لك ما بذلت وهو لك على كل حال فأقم في الرحب والسعة فلم يزل مقيما عندهم حتى هلك في دارهم","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":4,"spl":"قيسبة السكوني يقع في أسر بني عقيل — أسر أبي الطمحان في الحرب بين جديلة والغوث","loc":2300},
{"id":"b143-8","bab":"الجزء 13","sec":"اعتذاره لامرأته من ركوبه الأهوال","page":"ج13 ص10","text":"قال أبو عمرو في هذه الرواية وأخبرني أيضا بمثله محمد بن جعفر النحوي صهر المبرد قال حدثنا ثعلب عن ابن الأعرابي قال عاتبت\nأبا الطمحان القيني امرأته في غاراته ومخاطرته بنفسه وكان لصا خاربا خبيثا وأكثرت لومه على ركوب الأهوال ومخاطرته بنفسه في مذاهبه فقال لها - طويل -\n(لو كنت في ريمان تحرس بابه ... أراجيل أحبوش وأغضف آلف)\n(إذا لأتتني حيث كنت منيتي ... يخب بها هاد بأمري قائف)\n(فمن رهبة آتي المتالف سادرا ... وأية أرض ليس فيها متالف)\nأما البيت الذي ذكرت من شعره أن فيه لعريب صنعة وهو - طويل -\n(أضاءت لهم أحسابهم ووجوههم ... )\n- طويل - فإنه من قصيدة له مدح بها بجير بن أوس بن حارثة بن لأم الطائي وكان أسيرا في يده فلما مدحه بهذه القصيدة أطلقه وجز ناصيته فمدحه بعد هذا بعدة قصائد وأول هذه الأبيات - طويل -\n(إذا قيل أي الناس خير قبيلة ... وأصبر يوما لا توارى كواكبه)\n(فإن بني لأم بن عمرو أرومة ... علت فوق صعب لا تنال مراقبه)\n(أضاءت لهم أحسابهم ووجوههم ... دجى الليل حتى نظم الجزع ثاقبه)\n(لهم مجلس لا يحصرون عن الندى ... إذا مطلب المعروف أجدب راكبه)\n- طويل -","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":4,"spl":"قيسبة السكوني يقع في أسر بني عقيل — أسر أبي الطمحان في الحرب بين جديلة والغوث","loc":2301,"partialRef":{"sid":"b143-3","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b143-9","bab":"الجزء 13","sec":"أسر أبي الطمحان في الحرب بين جديلة والغوث","page":"ج13 ص12","text":"وأما خبر أسره والواقعة التي أسر فيها فإن علي بن سليمان الأخفش أخبرني بها عن أحمد بن يحيى ثعلب عن ابن الأعرابي قال كان أبو الطمحان القيني مجاورا في جديلة من طيء وكانت قد اقتتلت بينها وتحاربت الحرب التي يقال لها حرب الفساد وتحزبت حزبين حزب\nجديلة وحزب الغوث وكانت هذه الحرب بينهم أربعة أيام ثلاثة منها للغوث ويوم لجديلة فأما اليوم الذي كان لجديلة فهو يوم ناصفة وأما الثلاثة الأيام التي كانت للغوث فإنها يوم قارات حوق ويوم البيضة ويوم عرنان وهو آخرها وأشدها وكان للغوث فانهزمت جديلة هزيمة قبيحة وهربت فلحقت بكلب وحالفتهم وأقامت فيهم عشرين سنة وأسر أبو الطمحان في هذه الحرب أسره رجلان من طيء واشتركا فيه فاشتراه منهما بجير بن أوس بن حارثة لما بلغه قوله - طويل -\n(أرقت وآبتني الهموم الطوارق ... ولم يلق ما لاقيت قبلي عاشق)\n(إليكم بني لأم تخب هجانها ... بكل طريق صادفته شبارق)\n(لكم نائل غمر وأحلام سادة ... وألسنة يوم الخطاب مسالق)\n(ولم يدع داع مثلكم لعظيمة ... إذا وزمت بالساعدين السوارق)\n- طويل - السوارق الجوامع واحدتها سارقة\nقال فابتاعه بجير من الطائيين بحكمهما فجز ناصيته وأعتقه أخبرني الحسن بن علي قال حدثنا أبو أيوب المديني قال حدثني مصعب بن عبد الله الزبيري قال كان أبو الطمحان القيني مجاورا لبطن من طيئ يقال لهم بنو جديلة فنطح تيس له غلاما منهم فقتله فتعلقوا أبا الطمحان وأسروه حتى يؤدي ديته مائة من الإبل وجاءهم نزيله وكان يدعى هشاما ليدفع عنه فلم يقبلوا قوله فقال أبو الطمحان - طويل -\n(أتاني هشام يدفع الضيم جاهدا ... يقول ألا ماذا ترى وتقول)\n(فقلت له قم يا لك الخير أدها ... مذللة إن العزيز ذليل)\n(فإن يك دون القين أغبر شامخ ... فليس إلى القين الغداة سبيل)\n- طويل - أخبرني عمي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك عن إسحاق قال دخلت يوما على المأمون فوجدته حائرا متفكرا غير نشيط فأخذت أحدثه بملح الأحاديث وطرفها أستميله لأن يضحك أو ينشط فلم يفعل وخطر ببالي بيتان فأنشدته إياهما وهما - طويل -\n(ألا عللاني قبل نوح النوائح ... وقبل نشوز النفس بين الجوانح)\n(وقبل غد يا لهف نفسي على غد ... إذ راح أصحابي ولست برائح)\n- طويل - فتنبه كالمتفزع ثم قال من يقول هذا ويحك قلت أبو الطمحان القيني يا أمير المؤمنين قال صدق والله أعدهما علي فأعدتهما عليه حتى حفظهما ثم دعا بالطعام فأكل ودعا بالشراب فشرب وأمر لي بعشرين ألف درهم","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":4,"spl":"قيسبة السكوني يقع في أسر بني عقيل — أسر أبي الطمحان في الحرب بين جديلة والغوث","loc":2302},
{"id":"b143-10","bab":"الجزء 13","sec":"اعتذار الحسن لعبد الملك","page":"ج13 ص15","text":"أخبرني حبيب بن نصر المهلبي قال حدثني أحمد بن الحارث الخراز قال حدثني المدائني قال عاتب عبد الملك بن مروان الحسن بن الحسن عليهما السلام على شيء بلغه عنه من دعاء أهل العراق إياه إلى الخروج معهم على عبد الملك فجعل يعتذر إليه ويحلف له فقال له خالد بن يزيد بن معاوية يا أمير المؤمنين ألا تقبل عذر ابن عمك وتزيل عن قلبك ما قد أشربته إياه أما سمعت قول أبي الطمحان القيني - طويل -\n(إذا كان في صدر ابن عمك إحنة ... فلا تستثرها سوف يبدو دفينها)\n(وإن حمأة المعروف أعطاك صفوها ... فخذ عفوه لا يلتبس بك طينها)\n- طويل - قال المدائني ونزل أبو الطمحان على الزبير بن عبد المطلب بن هاشم وكانت العرب تنزل عليه فطال مقامه لديه واستأذنه في الرجوع إلى أهله وشكا إليه شوقا إليهم فلم يأذن له وسأله المقام فأقام عنده مدة ثم أتاه فقال له\n(ألا حنت المرقال وائتب ربها ... تذكر أوطانا وأذكر معشري)\n(ولو عرفت صرف البيوع لسرها ... بمكة أن تبتاع حمضا بإذخر)\n(أسرك لو أنا بجنبي عنيزة ... وحمض وضمران الجناب وصعتر)\n(إذا شاء راعيها استقى من وقيعة ... كعين الغراب صفوها لم يكدر)\n- طويل - فلما أنشده إياها أذن له فانصرف وكان نديما له\n(لا يعتري شربنا اللحاء وقد ... توهب فينا القيان والحلل)\n(وفتية كالسيوف نادمتهم ... لاحصر فيهم ولا بخل)\n- منسرح - الشعر للأسود بن يعفر والغناء لسليم خفيف ثقيل أول بالبنصر","topic":"أخبار سويد بن كراع ونسبه","topicNo":143,"sp":5,"spl":"اعتذار الحسن لعبد الملك","song":1,"loc":2303}]);